import type { BankQuestion } from "@/lib/bank";

/** Pedagogy of Maths, EVS and Languages (Child Development & Pedagogy): 2000 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cdp-pedagogy-subjects-1", "question": "In the Van Hiele model of geometric thinking, the basic level at which a child recognises shapes by their overall appearance (\"it looks like a door, so it is a rectangle\") is called:", "options": ["Visualisation", "Informal deduction", "Analysis", "Rigour"], "answer": 0, "explanation": "Level 0 (visualisation, or recognition) is based on the look of the whole shape. Analysis (Level 1) is the next level, where children describe a shape by its properties.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-2","question":"According to the NCF 2005 position on mathematics, the main goal of school mathematics is to develop the child's:","options":["speed and accuracy in mechanical calculation","memory for formulae and standard procedures","ability to score well in board and competitive examinations","ability to think mathematically (mathematisation of thought)"],"answer":3,"explanation":"NCF 2005 names the 'mathematisation' of the child's thinking as the main goal, ahead of narrow goals such as computation speed or rote formulae.","difficulty":"easy","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-3","question":"As recommended by NCF 2005, Environmental Studies (EVS) for Classes III to V is an integrated subject that draws on:","options":["language and art education, taught through stories and drawing","history, geography and civics, as in the middle-school syllabus","physics, chemistry and biology, simplified for young children","science, social science and environmental education"],"answer":3,"explanation":"Primary EVS weaves together concerns of science, social science and environmental education instead of teaching them as separate disciplines.","difficulty":"easy","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-4", "question": "The four basic language skills, in the order in which a child naturally acquires them, are:", "options": ["Listening, Speaking, Reading, Writing", "Reading, Writing, Listening, Speaking", "Listening, Reading, Speaking, Writing", "Speaking, Listening, Reading, Writing"], "answer": 0, "explanation": "Children listen before they speak, and learn to read before they write: the LSRW sequence. Receptive skills come before productive ones in each pair.", "difficulty": "easy", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-5","question":"A Class II child writes 25 + 17 = 312. The error most likely shows that the child:","options":["does not yet know the number names and numerals beyond 50","cannot reliably add single-digit numbers such as 5 and 7","adds the digits correctly but does not regroup (carry) the ten","has a reading disability that makes the digits appear reversed to him"],"answer":2,"explanation":"5 + 7 = 12 is written in full and 2 + 1 = 3 is written beside it, giving 312. The child adds digits correctly but has not grasped place value and carrying.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-6","question":"Which is the most appropriate way to introduce fractions to Class III children?","options":["Writing 1/2 and 1/4 on the board and reading them aloud","Giving worksheets on adding unlike fractions to build speed","Defining the numerator and denominator before any examples","Sharing a roti or a sheet of paper equally among children"],"answer":3,"explanation":"Fractions grow out of the everyday experience of equal sharing. Concrete sharing should come before symbols and definitions.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-7","question":"The NCERT EVS textbooks for Classes III to V, prepared after NCF 2005, are organised around themes such as:","options":["Family and Friends, Food, Shelter, Water, Travel, Things We Make and Do","Grammar, Composition, Comprehension, Poetry, Prose and Letter Writing","Physics, Chemistry, Biology, Geography and Civics as separate units","Ancient, Medieval and Modern History, with maps and civic institutions"],"answer":0,"explanation":"The primary EVS syllabus uses six child-centred themes: Family and Friends (relationships, work and play, animals, plants), Food, Shelter, Water, Travel, and Things We Make and Do. It avoids subject divisions.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-8", "question": "A teacher asks children to run their eyes quickly over a passage only to find the year in which a dam was built. The reading strategy being practised is:", "options": ["scanning", "intensive reading", "extensive reading", "skimming"], "answer": 0, "explanation": "Scanning means searching a text quickly for one specific piece of information, such as a date or name. Skimming means reading quickly to get the general idea.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-9","question":"Which classroom practice best reflects the multilingual approach recommended by NCF 2005?","options":["Teaching only in English from Class I so that children pick it up faster","Translating every textbook sentence word for word into the home language","Letting children use their home language as a bridge to the school language","Fining children who speak their mother tongue so that they practise English"],"answer":2,"explanation":"NCF 2005 treats multilingualism as a resource. The child's home language is a bridge to the school language, not something to suppress.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-10","question":"Using mathematical puzzles and games in a primary class mainly helps to:","options":["build logical reasoning and reduce fear of mathematics","replace the textbook entirely with play-based activities","test how well children have memorised tables and formulae","keep children busy and quiet when the teacher is absent"],"answer":0,"explanation":"Puzzles and games make children reason, try strategies and enjoy mathematics, which counters maths anxiety. They add to the textbook; they do not replace it.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-11", "question": "Which approach to teaching reading begins with whole, meaningful texts such as stories and rhymes and treats reading as making meaning, not decoding isolated letters?", "options": ["Phonics approach", "Alphabetic method", "Whole language approach", "Grammar-translation method"], "answer": 2, "explanation": "The whole language approach starts from meaningful text and the child's experience. Phonics and the alphabetic method build up from sounds or letters.", "difficulty": "moderate", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-12","question":"A Class IV teacher takes children to a nearby pond as part of an EVS lesson. The main value of this field visit is that it:","options":["gives children a relaxing break from textbook-based studies","replaces the need for any further assessment of the chapter","helps the teacher finish the syllabus faster by covering it outdoors","lets children observe first-hand and link learning to their surroundings"],"answer":3,"explanation":"EVS aims to link classroom knowledge with the child's environment. First-hand observation and exploration on a field visit serve exactly that.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-13", "question": "According to the Van Hiele model, a child who explains that 'a square is also a rectangle, because it has four right angles and its opposite sides are equal' is at the level of:", "options": ["Visualisation", "Formal deduction", "Informal deduction", "Analysis"], "answer": 2, "explanation": "Seeing class inclusion (every square is a rectangle) by relating properties is Level 2, informal deduction (also called abstraction or ordering). At the analysis level, children list properties but treat squares and rectangles as separate.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-14","question":"Many Class V children say that 0.25 is greater than 0.5 'because 25 is more than 5'. The most effective teaching response is to:","options":["ask them to memorise the rule 'compare digit by digit' and apply it","show tenths and hundredths on place-value charts or 10 × 10 grids","give them more practice on the same kind of sums until errors stop","tell them they are being careless and ask them to check their work"],"answer":1,"explanation":"The error comes from treating decimals as whole numbers, which is a misconception, not carelessness. Visual models of tenths and hundredths rebuild the concept. Drill or rules alone leave the misconception in place.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-15","question":"According to NCF 2005, the concerns of EVS in Classes I and II should be:","options":["taught as formal science, with simple experiments and definitions","integrated with language and mathematics, not a separate subject","left out entirely, since young children are not ready for it","taught as a separate subject with its own EVS textbook and tests"],"answer":1,"explanation":"NCF 2005 says that in Classes I and II the EVS themes should be integrated with language and mathematics. EVS becomes a separate subject from Class III.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-16","question":"A Class III child insists that 'the sun moves around the earth, because I can see it moving across the sky'. In a constructivist EVS classroom, the teacher should treat this as:","options":["evidence of a learning disability needing referral to a specialist","a sign of low intelligence that calls for extra drill on facts","a wrong answer to be crossed out at once and replaced with the correct fact","an alternative conception from experience, to build on through exploration"],"answer":3,"explanation":"Children build ideas from experience. Constructivist teaching draws out such alternative conceptions and uses activities and discussion to rebuild them, instead of dismissing them.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-17","question":"Stephen Krashen's input hypothesis states that a second language is acquired when the learner:","options":["gets comprehensible input just beyond the current level (i + 1)","is corrected on every error at once so that mistakes do not fossilise","is taught explicit grammar rules first and then applies them in speech","repeats pattern drills until correct responses become automatic habits"],"answer":0,"explanation":"Krashen argued that acquisition happens through understanding messages slightly beyond one's level (i + 1). Drills and constant correction belong to behaviourist methods.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-18","question":"A four-year-old says, 'I goed to the market and buyed two mangoes.' From the viewpoint of language development, this shows that the child:","options":["has a speech disorder that needs early referral for therapy","should be corrected sharply so that the error does not become fixed","is overgeneralising the past-tense rule, a normal sign of learning","is copying the incorrect speech of adults around the child"],"answer":2,"explanation":"Overgeneralisation shows the child has worked out the past-tense rule and is applying it to irregular verbs too. Children never hear adults say 'goed', so it is not imitation. It is a normal stage.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-19","question":"Which assessment task is most suitable for assessing the speaking skill of Class IV children?","options":["An oral narration or role-play assessed with a simple rubric","A multiple-choice test on grammar and correct sentence forms","A dictation exercise read out slowly by the teacher","A fill-in-the-blanks worksheet on useful spoken phrases"],"answer":0,"explanation":"Speaking is a productive oral skill, so it is assessed through actual speaking tasks. The other options assess grammar knowledge, listening-and-writing or reading-and-writing.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-20", "question": "George Pólya's four steps of problem solving, in order, are:", "options": ["Devise a plan, understand the problem, look back, carry out the plan", "Guess, check, revise, conclude", "Understand the problem, devise a plan, carry out the plan, look back", "Read, memorise, calculate, check"], "answer": 2, "explanation": "Pólya's How to Solve It gives understand, plan, carry out and look back (review). The 'look back' step is often skipped in classrooms.", "difficulty": "hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-21","question":"To teach place value, a teacher first lets children bundle sticks into tens, then shows pictures of the bundles, and finally writes numerals such as 34. This sequence follows:","options":["the Van Hiele levels of geometric thought, from visual to formal","Vygotsky's zone of proximal development and scaffolding","Bruner's enactive, iconic and symbolic modes of representation","Piaget's idea of conservation of number and quantity"],"answer":2,"explanation":"Handling sticks is enactive, pictures are iconic and numerals are symbolic. This concrete–pictorial–abstract progression comes from Jerome Bruner.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-22","question":"The idea of 'language across the curriculum' means that:","options":["every subject lesson also builds the language and vocabulary of that subject","children should study as many languages as possible in school","English should be the medium of instruction for all subjects","language should be taught only in the language period, by language teachers"],"answer":0,"explanation":"Language and learning are inseparable. In a science or mathematics lesson, children also learn to describe, explain and argue in the language of that subject.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-23","question":"In mathematics pedagogy, 'mathematical communication' refers to children's ability to:","options":["talk freely with friends during the mathematics period","recite multiplication tables and formulae aloud fluently in chorus","write answers neatly, in the prescribed steps, in the notebook","explain and justify mathematical ideas using precise terms and symbols"],"answer":3,"explanation":"Mathematical communication means explaining one's reasoning, using correct terms and symbols, and justifying solutions to others. It is not just talking or neat writing.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-24","question":"NEP 2020 recommends that, wherever possible, the medium of instruction until at least Grade 5, and preferably till Grade 8 and beyond, should be:","options":["Hindi, as the most widely spoken language across the country","Sanskrit, as the classical root of most Indian languages","the home language, mother tongue or local/regional language","English, so that children are ready for higher education"],"answer":2,"explanation":"NEP 2020 (para 4.11) recommends the home language, mother tongue or local/regional language as the medium of instruction at least till Grade 5, preferably till Grade 8 and beyond.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-25", "question": "How many of the following match the NCF 2005 position on school mathematics? I. The focus should shift from procedures to problem solving and mathematisation. II. Children should see mathematics as something to talk about, communicate and discuss. III. Mathematics should be taught only to children who show an aptitude for it. IV. Algorithms should be taught before children understand the concepts behind them.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "I and II reflect NCF 2005, which wants children to enjoy, discuss and reason about mathematics. III goes against its 'mathematics for all' view, and IV goes against its focus on understanding. So only two match.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-26", "question": "How many of the following statements about the National Curriculum Framework for School Education (NCF-SE) 2023 are correct? I. The Foundational Stage covers ages 3 to 8 (three years of pre-school plus Grades 1 and 2). II. Board examinations are to be offered at least twice a year. III. In Grades 9 and 10 students study three languages, at least two of which are native to India. IV. In Grades 11 and 12 students must study three languages.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: in Grades 11 and 12, NCF-SE 2023 requires two languages, at least one of them native to India. So only three are correct.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-27", "question": "Match the teaching aid with its main use in mathematics: 1. Napier's bones 2. Geoboard 3. Dienes (base-ten) blocks 4. Tangram; a. Place value b. Multiplication c. Making figures from seven geometric pieces d. Area and perimeter using pegs and rubber bands", "options": ["1-a, 2-d, 3-b, 4-c", "1-d, 2-b, 3-c, 4-a", "1-b, 2-c, 3-a, 4-d", "1-b, 2-d, 3-a, 4-c"], "answer": 3, "explanation": "Napier's bones are rods for multiplication. A geoboard uses pegs and rubber bands to explore area and perimeter. Dienes blocks (units, longs, flats) model place value. A tangram has seven pieces for composing figures.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-28", "question": "Assertion (A): Teachers should encourage children to estimate an answer before working it out. Reason (R): Estimation helps children judge whether an answer is reasonable and builds number sense.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true, and R explains A: estimating first gives a benchmark for spotting unreasonable answers and strengthens number sense, which is why it is encouraged.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-29", "question": "Assertion (A): Correcting every error a child makes while speaking a new language is the best way to ensure accuracy. Reason (R): Errors are a natural part of language learning and reveal the child's developing ideas about how the language works.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is true: errors are windows into the learner's developing grammar. A is false, because constant correction discourages children from speaking and harms fluency. Errors call for selective, sensitive feedback.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-30", "question": "How many of the following statements about EVS at the primary level, as envisaged in NCF 2005, are correct? I. EVS is taught as a separate subject with its own textbook from Class I onwards. II. It aims to connect children's learning in school with their life outside school. III. It is to be assessed mainly through written tests of definitions. IV. Its themes are presented from the child's point of view rather than through subject divisions.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II and IV are correct. I is wrong, because EVS is a separate subject only from Class III (it is integrated with language and maths in Classes I–II). III is wrong, because NCF 2005 wants continuous assessment through observation, activities and projects, not tests of definitions. So only two.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-31","question":"Which of the following is NOT a feature of the communicative approach to language teaching?","options":["A focus on meaning and fluency over perfect accuracy","Mechanical grammar drills for accuracy before any real use","Using real-life tasks such as asking for directions","Plenty of pair and group work for genuine interaction among learners"],"answer":1,"explanation":"The communicative approach puts meaningful use first, through real tasks, interaction and fluency. Mechanical drilling for accuracy before use belongs to the structural or audio-lingual methods.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-32","question":"While counting six marbles, a child says 'one, two, three, four, five, six, seven' in the correct order but touches one marble twice. Which counting principle has the child not yet mastered?","options":["One-to-one correspondence","Cardinality principle","Stable-order principle","Order-irrelevance principle"],"answer":0,"explanation":"Each object must get exactly one number word (one-to-one correspondence), and touching a marble twice breaks this. The number words came in the right order, so the stable-order principle is intact.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-33", "question": "After correctly counting seven pencils, a child is asked 'So how many pencils are there?' and starts counting all over again instead of answering 'seven'. The child has not yet grasped the principle of:", "options": ["cardinality", "abstraction", "one-to-one correspondence", "stable order"], "answer": 0, "explanation": "Cardinality means the last number word said gives the size of the whole set. A child who recounts has not linked 'seven' to the total, even though the counting itself was correct.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-34","question":"Phonemic awareness is best shown when a child can:","options":["copy words neatly and correctly from the board","say that 'cat' without its first sound /k/ becomes 'at'","name the letter C when it is shown on a card","read a short printed sentence aloud fluently and clearly"],"answer":1,"explanation":"Phonemic awareness is the ability to hear and handle individual sounds in spoken words, e.g. taking away the first sound. Naming letters is letter knowledge, and fluent reading is a later skill.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-35","question":"Which question best assesses a Class V child's conceptual understanding of fractions rather than procedural skill?","options":["Without calculating, explain why 3/4 is greater than 3/5","Convert 3/4 into a decimal and then into a percentage","Add 3/4 and 3/5 and write the answer in lowest terms","Find the LCM of 4 and 5 and use it to compare 3/4 and 3/5"],"answer":0,"explanation":"Explaining that the same number of larger parts (quarters are bigger than fifths) makes a larger fraction needs understanding. The other tasks can be done by following a learned procedure.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-36","question":"An EVS chapter for Class IV asks children: 'Who cooks food in your family? Who fetches water? Why?' The main purpose of such questions is to:","options":["test children's memory of the names and ages of family members","teach children recipes and household skills such as cooking","help children reflect on gender roles and division of work at home","collect data on household chores for the school's records"],"answer":2,"explanation":"Primary EVS uses open questions from the child's own life to raise social issues such as gender, work and equity, so children think critically about everyday roles.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-37", "question": "How many of the following statements about NEP 2020 are correct? I. It gives the highest priority to achieving universal foundational literacy and numeracy in primary school by 2025. II. The NIPUN Bharat mission was launched to work towards foundational literacy and numeracy goals. III. It keeps the three-language formula but adds flexibility, saying no language will be imposed on any state. IV. It makes English the compulsory medium of instruction from Grade 1.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (NIPUN Bharat was launched in 2021 to pursue FLN). IV is wrong, because NEP 2020 prefers the mother tongue or regional language as the medium of instruction in the early grades. So only three.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-38", "question": "How many of the following statements about teaching reading and writing in the primary grades are correct? I. The aim of reading instruction is reading with comprehension, not just decoding. II. Using children's literature in class supports language development. III. A print-rich classroom environment supports emergent literacy. IV. A child's home language is a resource for learning the school language.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four reflect current language pedagogy (NCF 2005, NCF-FS 2022 and NEP 2020). Reading is meaning-making, children's literature and print-rich classrooms support literacy, and the home language is a bridge, not a barrier.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-39","question":"Which sequence is most appropriate for teaching the measurement of length in the primary classes?","options":["The need for a standard unit, then using a ruler, then direct comparison, then non-standard units","Non-standard units, then using a ruler, then direct comparison, then the need for a standard unit","Direct comparison, then non-standard units, then the need for a standard unit, then using a ruler","Using a ruler, then non-standard units, then direct comparison, then the need for a standard unit"],"answer":2,"explanation":"Children first compare lengths directly (longer or shorter), then measure with body or object units. They see that different hand spans give different answers, which creates the need for a standard unit, and only then use the ruler.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-40", "question": "Which of the following is NOT one of the five guiding principles of NCF 2005?", "options": ["Making board examinations compulsory at the end of Class VIII", "Making examinations more flexible and integrated with classroom life", "Moving learning away from rote methods", "Connecting knowledge to life outside the school"], "answer": 0, "explanation": "The five guiding principles are: connecting knowledge to life outside school, moving away from rote learning, enriching the curriculum beyond textbooks, making examinations flexible and integrated with classroom life, and nurturing an overriding identity informed by caring concerns within the democratic polity. A Class VIII board exam is not one of them.", "difficulty": "very-hard", "source": "CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id": "cdp-pedagogy-subjects-41", "question": "The NCERT textbooks for Environmental Studies (Classes III to V) are titled:", "options": ["Looking Around", "Rimjhim", "Math-Magic", "Marigold"], "answer": 0, "explanation": "“Looking Around” is the NCERT EVS series. Rimjhim is the Hindi reader, Math-Magic the mathematics series and Marigold the English reader for the primary classes.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-42", "question": "A specific learning disability that mainly affects understanding numbers and doing calculations is called:", "options": ["Dyslexia", "Dysgraphia", "Dyscalculia", "Dyspraxia"], "answer": 2, "explanation": "Dyscalculia affects number sense and calculation. Dyslexia affects reading, dysgraphia writing, and dyspraxia motor coordination.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-43","question":"Which is the most suitable way to begin addition with Class I children?","options":["Memorising addition tables up to 10 by recitation","Writing long columns of sums on the board to copy","Practising abstract symbols such as 3 + 2 = 5","Joining and counting real objects such as pebbles"],"answer":3,"explanation":"Young children are at a concrete stage; joining real collections and counting gives meaning to “adding” before symbols are introduced.","difficulty":"easy","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-44","question":"A Class III child writes 52 − 27 = 35. What is the most likely reason for this error?","options":["Carelessness while copying the numbers from the board into the notebook","Subtracting the smaller digit from the larger in each column","Not yet knowing the basic subtraction facts up to 10","Adding the two numbers instead of subtracting them"],"answer":1,"explanation":"In the ones place the child did 7 − 2 = 5 instead of regrouping, then 5 − 2 = 3. This systematic “smaller-from-larger” error shows a gap in understanding place value and borrowing.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-45", "question": "A teacher shows children many triangles, has them measure the angles, and helps them conclude that the angles of a triangle add up to 180°. This is the:", "options": ["Deductive method", "Lecture method", "Inductive method", "Analytic method"], "answer": 2, "explanation": "The inductive method moves from specific examples to a general rule, which suits young learners. The deductive method starts with the rule and then applies it.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-46", "question": "Which of these is NOT one of the six themes around which the NCERT EVS books for Classes III–V are organised?", "options": ["Water", "Travel", "Things We Make and Do", "Our Solar System"], "answer": 3, "explanation": "The six themes are Family and Friends, Food, Shelter, Water, Travel, and Things We Make and Do. The books deliberately avoid organising content by disciplines such as astronomy.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-47", "question": "In the 5E model of inquiry-based teaching used in science and EVS, the phases occur in which order?", "options": ["Engage, Explore, Explain, Elaborate, Evaluate", "Explain, Engage, Explore, Evaluate, Elaborate", "Explore, Engage, Explain, Evaluate, Elaborate", "Engage, Explain, Explore, Elaborate, Evaluate"], "answer": 0, "explanation": "Children are first engaged by a question, then explore, then explain what they found, elaborate by applying it, and finally evaluate their understanding.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-48", "question": "The project method of teaching, built on Dewey's ideas of learning by doing, was developed by:", "options": ["Maria Montessori", "W. H. Kilpatrick", "H. E. Armstrong", "Friedrich Froebel"], "answer": 1, "explanation": "William Heard Kilpatrick proposed the project method (1918). Armstrong is linked with the heuristic method and Froebel with the kindergarten.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-49", "question": "Richard Skemp distinguished “relational understanding” from “instrumental understanding”. Relational understanding means:", "options": ["Knowing a rule and how to apply it quickly", "Knowing both what to do and why it works", "Memorising formulae through repeated practice", "Relating mathematics only to daily life examples"], "answer": 1, "explanation": "Instrumental understanding is “rules without reasons”; relational understanding connects procedures to the underlying concepts, so it transfers better to new problems.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-50","question":"To study the theme “Water” in Class IV, which activity best fits the approach of NCF 2005?","options":["Copying the definition of the water cycle five times for practice","Reading the chapter aloud and answering the textbook questions","Surveying local water sources and discussing who fetches water","Memorising the names of major rivers of India and the world"],"answer":2,"explanation":"A local survey links the theme to children's own lives, involves observation and recording, and raises issues of access and equity, as NCF 2005 recommends.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-51","question":"Zoltan Dienes's “perceptual variability” (multiple embodiment) principle means that a mathematical concept should be:","options":["Taught through one well-chosen model so children are not confused","Presented through several different materials and situations","Introduced first as a formal definition, then illustrated","Practised with one material until answers become automatic"],"answer":1,"explanation":"Meeting the same idea, such as place value, in sticks, beads and blocks helps children abstract what is common and not tie the concept to one material.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-52","question":"Many children think that multiplying always gives a bigger number, so they are puzzled that 1/2 × 1/4 = 1/8. The best teaching response is to:","options":["Tell them the rule and ask them to memorise it for the test","Use area models to show that a part of a part is smaller","Avoid fraction multiplication until they reach Class VIII","Give a large number of similar sums for drill and practice"],"answer":1,"explanation":"The belief comes from experience with whole numbers. An area or paper-folding model shows that “half of a quarter” is smaller than both, correcting the misconception through meaning.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-53", "question": "A child correctly lists the properties of a square (four equal sides, four right angles) but insists that a square is not a rectangle. According to Van Hiele, the child is at the level of:", "options": ["Visualisation", "Analysis", "Informal deduction", "Rigour"], "answer": 1, "explanation": "At the analysis level children describe shapes by their properties but do not yet see relationships between classes of shapes, which comes at informal deduction.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-54", "question": "The heuristic method, in which the learner is put in the position of a discoverer, was advocated by:", "options": ["H. E. Armstrong", "W. H. Kilpatrick", "J. S. Bruner", "B. F. Skinner"], "answer": 0, "explanation": "Henry Edward Armstrong promoted the heuristic method in science teaching. Bruner is linked with discovery learning more generally and Skinner with programmed instruction.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-55", "question": "Concept maps, used in EVS and science to show how ideas are linked, were developed by:", "options": ["Jean Piaget", "Joseph Novak", "Howard Gardner", "Benjamin Bloom"], "answer": 1, "explanation": "Joseph Novak developed concept mapping in the 1970s, building on Ausubel's idea that meaningful learning links new ideas to existing knowledge.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-56","question":"Which of these is an open-ended task in mathematics?","options":["What is 12 + 8? Show your working in the notebook.","Find as many number pairs as you can that add up to 20.","Write the multiplication table of 4 up to 4 × 10.","Copy the numbers from 1 to 50 neatly into your notebook."],"answer":1,"explanation":"An open-ended task has many correct answers and lets children use different strategies and reasoning. The other tasks have a single fixed answer.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-57","question":"NCERT's indicators for assessing learning in EVS include all of the following EXCEPT:","options":["Observation, recording and discussion","Questioning, analysis and experimentation","Concern for justice and equality","Reproducing definitions word for word"],"answer":3,"explanation":"The EVS indicators include observation and recording, discussion, expression, explanation, classification, questioning, analysis, experimentation, concern for justice and equality, and cooperation. Rote reproduction is not an indicator.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-58", "question": "In a geometry proof, working backwards from what is to be proved towards what is already known is called the:", "options": ["Synthetic method", "Inductive method", "Analytic method", "Laboratory method"], "answer": 2, "explanation": "The analytic method goes from the unknown to the known and helps children discover the proof. The synthetic method presents the proof from known facts to the conclusion.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-59","question":"Which is a major limitation of using the deductive method alone with young children in mathematics?","options":["It takes far too long to complete the prescribed syllabus in the year","Children may use formulae without knowing where they come from","It needs costly laboratory equipment in every classroom","It cannot be used for teaching geometry or measurement"],"answer":1,"explanation":"Starting with a ready-made rule is quick, but children may apply it mechanically. Combining it with the inductive method builds understanding first.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-60","question":"Activities in which children extend number and shape patterns (2, 4, 6, 8, …) mainly help them to develop:","options":["Speed and accuracy in written computation","Generalisation and early algebraic thinking","Neat and correctly formed handwriting of numerals","Memory of multiplication tables and number facts"],"answer":1,"explanation":"Recognising and describing a rule behind a pattern is the root of algebraic thinking; NCF 2005 gives patterns a place from the early grades.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-61", "question": "Assertion (A): EVS in the primary classes should begin from the child's immediate surroundings. Reason (R): Children construct new knowledge by linking new experiences to what they already know.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Starting from home, family and neighbourhood gives children a base of experience to build on, in line with constructivism.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-62", "question": "Consider the following statements about the NCERT EVS books for Classes III–V: 1. They follow a thematic organisation rather than separate science and social science chapters. 2. Their exercises are designed mainly for rote recall of definitions. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. The exercises ask children to observe, discuss, find out from elders and express their views, not to reproduce definitions.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-63", "question": "Arrange these Van Hiele levels in the order in which they develop: 1. Deduction 2. Analysis 3. Rigour 4. Informal deduction", "options": ["2, 4, 1, 3", "2, 1, 4, 3", "4, 2, 1, 3", "2, 4, 3, 1"], "answer": 0, "explanation": "After visualisation come analysis, informal deduction (abstraction), formal deduction and finally rigour.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-64", "question": "How many of these statements about the NIPUN Bharat Mission are correct? I. It was launched in 2021. II. It aims for every child to achieve foundational literacy and numeracy by the end of Grade 3. III. Its target year is 2026–27. IV. It covers children in the age group of 3 to 9 years.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. NIPUN Bharat implements the NEP 2020 priority on foundational literacy and numeracy.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-65", "question": "Consider the following statements: 1. Vidya Pravesh is a three-month, play-based school preparation module for children entering Grade 1. 2. It was launched as part of implementing NEP 2020. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Vidya Pravesh eases the move to school through play, stories and activities before formal instruction.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-66", "question": "Assertion (A): Children should be allowed to use their own informal strategies for addition before the standard algorithm is taught. Reason (R): Standard algorithms are always inefficient and should be avoided.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: invented strategies build number sense and make the algorithm meaningful later. R is false: standard algorithms are efficient tools once understood.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-67","question":"A Class V child writes 1/2 + 1/3 = 2/5. Which response best addresses the misconception?","options":["Make the child repeat the rule for finding the LCM","Use fraction strips to show why equal-sized parts are needed","Mark the answer wrong and move on to the next topic","Give twenty similar sums for homework to build speed and accuracy"],"answer":1,"explanation":"The child is treating numerators and denominators as separate whole numbers. Models show why common-sized parts (sixths) are needed, giving meaning to the procedure.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-68","question":"Which question in an EVS lesson on houses most encourages higher-order thinking?","options":["Name two types of houses you saw in the chapter.","What is a house made of mud called in the textbook?","Why do many houses in Rajasthan have thick walls and small windows?","Which material is used for the roofs of the houses in your textbook picture?"],"answer":2,"explanation":"Asking “why” makes children link climate and building design, which calls for reasoning and inference rather than recall.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-69", "question": "Consider the following statements: 1. Formative assessment in mathematics can include observing the strategies children use during group work. 2. Summative assessment results should be used to label children as slow learners. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. Assessment is meant to improve teaching and learning; labelling children harms their confidence and is discouraged by NCF 2005.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-70","question":"In the grammar-translation method of teaching a language:","options":["Only the target language is used in class, and translation is banned","Learning happens through pattern drills and habit formation","Children learn mainly through real-life communicative tasks","Explicit grammar rules and translation using the mother tongue"],"answer":3,"explanation":"Grammar-translation relies on rules, vocabulary lists and translation, with little speaking practice. The direct method bans translation; audio-lingual uses drills.","difficulty":"easy","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-71", "question": "A child who has persistent difficulty in forming letters, spacing words and writing legibly may have:", "options": ["Dysgraphia", "Dyscalculia", "Aphasia", "Dyslexia"], "answer": 0, "explanation": "Dysgraphia is a learning disability affecting handwriting and written expression. Dyslexia affects reading; aphasia is loss of language ability, usually after brain injury.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-72", "question": "A teacher asks children to read a passage quickly to get its general idea before reading it closely. This reading strategy is called:", "options": ["Scanning", "Intensive reading", "Loud reading", "Skimming"], "answer": 3, "explanation": "Skimming is quick reading for the gist; scanning is searching for a specific detail such as a name or date.", "difficulty": "easy", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-73", "question": "Noam Chomsky held that children learn language easily because they are born with:", "options": ["A blank slate shaped wholly by reinforcement", "A Language Acquisition Device", "A fixed vocabulary of a few hundred words", "An ability that appears only after schooling"], "answer": 1, "explanation": "Chomsky argued for an innate Language Acquisition Device and a universal grammar, against Skinner's view that language is learnt only through imitation and reinforcement.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-74", "question": "According to B. F. Skinner, children acquire language mainly through:", "options": ["An innate universal grammar", "Social interaction within the zone of proximal development", "Imitation and reinforcement", "Biological maturation alone"], "answer": 2, "explanation": "Skinner's behaviourist view (Verbal Behavior, 1957) explains language as habits shaped by reinforcement. Chomsky criticised it for not explaining children's novel sentences.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-75", "question": "A test in which children fill in words deleted at regular intervals from a passage is called a:", "options": ["Dictation test", "Cloze test", "True–false test", "Matching test"], "answer": 1, "explanation": "A cloze test checks comprehension and language knowledge, since filling the gaps needs understanding of the context and grammar.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-76", "question": "In the process approach to writing, which sequence is correct?", "options": ["Editing, drafting, brainstorming, revising", "Drafting, brainstorming, editing, revising", "Brainstorming, editing, drafting, revising", "Brainstorming, drafting, revising, editing"], "answer": 3, "explanation": "Writers first generate ideas, then write a draft, revise its content and organisation, and finally edit for language and mechanics before publishing.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-77","question":"The phonics approach to teaching reading focuses on:","options":["Guessing unknown words from pictures and context only","Memorising whole texts and reciting them from memory","Teaching how letters relate to the sounds they stand for","Reading silently from the start to build comprehension"],"answer":2,"explanation":"Phonics teaches sound–symbol correspondence so that children can decode new words. It works best alongside meaningful reading, not in isolation.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-78","question":"Which is the most effective way to build the vocabulary of young learners?","options":["Meeting new words again and again in stories, songs and talk","Giving lists of words with meanings to memorise each week","Testing the spellings of new words every single day","Asking them to copy dictionary entries into a notebook"],"answer":0,"explanation":"Words are learnt best in meaningful context with repeated exposure; isolated lists are quickly forgotten.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-79", "question": "Who held that thought and language develop from separate roots and come together at about the age of two, when thought becomes verbal and speech becomes rational?", "options": ["Jean Piaget", "Noam Chomsky", "B. F. Skinner", "Lev Vygotsky"], "answer": 3, "explanation": "Vygotsky (Thought and Language) described this meeting of thought and speech. Piaget saw language as reflecting thought, and Chomsky stressed innate grammar.", "difficulty": "moderate", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-80","question":"According to Krashen's affective filter hypothesis, a learner's acquisition of a second language is blocked mainly by:","options":["Too much comprehensible input given at one time","Anxiety, low motivation and low self-confidence","Learning grammar rules before learning vocabulary","Using the mother tongue at home with family"],"answer":1,"explanation":"A high affective filter keeps input from being acquired. A relaxed classroom where mistakes are accepted lowers the filter.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-81", "question": "Consider the following statements based on Krashen's theory: 1. Acquisition is a subconscious process similar to how children pick up their first language. 2. Learning refers to conscious knowledge of the rules of a language. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Krashen argued that fluency comes mainly from acquisition, while consciously learnt rules mostly serve as a monitor.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-82","question":"After a story, which question checks inferential comprehension?","options":["What was the name of the old man in the story?","Where did the old man live with his family?","How many goats did the old man have at the start?","Why do you think the old man smiled at the end?"],"answer":3,"explanation":"Inferential questions need children to read between the lines. The others are literal questions whose answers are stated in the text.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-83", "question": "The three-language formula was recommended by the Kothari Commission and adopted in the:", "options": ["National Policy on Education, 1968", "National Policy on Education, 1986", "Right to Education Act, 2009", "National Curriculum Framework, 2005"], "answer": 0, "explanation": "The Education Commission (1964–66) recommended it and the 1968 policy adopted it. NCF 2005 and NEP 2020 reaffirmed it with flexibility.", "difficulty": "hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-84","question":"Which Article of the Constitution asks every State to provide facilities for instruction in the mother tongue at the primary stage to children of linguistic minority groups?","options":["Article 350B","Article 29","Article 21A","Article 350A"],"answer":3,"explanation":"Article 350A, added in 1956, deals with mother-tongue instruction at the primary stage. Article 350B provides a Special Officer for linguistic minorities, Article 29 protects culture and language, and Article 21A is the right to education.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-85","question":"A Class I teacher labels objects in the room, displays children's names, charts and posters at their eye level. The main purpose is to:","options":["Decorate the classroom so it looks attractive for inspections","Create a print-rich setting that supports early literacy","Make children copy the labels as handwriting practice","Test children's spelling of common classroom objects"],"answer":1,"explanation":"Seeing meaningful print around them helps children notice that print carries meaning and supports early reading and writing.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-86","question":"“Big Books” in early-grade classrooms are mainly used for:","options":["Silent individual reading by each child at the desk","Shared reading, with the whole class able to see the text","Testing spellings of new words shown in large print","Copying large-print text into notebooks from a distance"],"answer":1,"explanation":"Big Books let the teacher model reading, point to words and invite predictions, so children join in reading together.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-87","question":"A child often reverses letters such as b and d. Which remedial approach is most suitable?","options":["Making the child write each letter a hundred times","Scolding the child for carelessness so that the habit finally stops","Tracing letters in sand or air while saying their sounds","Moving the child to a lower class to repeat basics"],"answer":2,"explanation":"Multisensory methods link sight, sound, movement and touch, which helps children with reversal difficulties; punishment and drills do not.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-88","question":"Which task is most suitable for assessing the listening skill of Class III children?","options":["Copying a paragraph from the board into the notebook","Writing a short essay on “My School” in the notebook","Reading a passage aloud to the class with expression","Answering questions on a short announcement heard aloud"],"answer":3,"explanation":"A listening task needs a spoken input and a response that shows understanding. The other tasks assess writing or reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-89","question":"While reading a story aloud, a teacher stops and asks, “What do you think will happen next?” This mainly develops children's:","options":["Handwriting, by noting key words from the story","Prediction and active engagement with the text","Memory for the spellings of new words in the story","Speed of silent reading and word recognition"],"answer":1,"explanation":"Predicting makes children use clues from the text and their own experience, which builds active comprehension.","difficulty":"hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-90", "question": "Consider the following statements based on Krashen's theory: 1. The monitor hypothesis says consciously learnt rules act as an editor on what the learner produces. 2. The natural order hypothesis says grammatical structures are acquired in a broadly predictable order. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Together with the input, acquisition–learning and affective filter hypotheses, these make up Krashen's five hypotheses.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-91", "question": "Match the language teaching method with its feature: A. Grammar-translation B. Direct method C. Audio-lingual method D. Communicative approach — 1. Drills and habit formation 2. Meaningful interaction through real-life tasks 3. Translation and explicit rules 4. Target language only, no translation", "options": ["A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-1, C-4, D-2", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Grammar-translation uses translation and rules, the direct method avoids the mother tongue, the audio-lingual method uses behaviourist drills, and the communicative approach stresses meaningful use.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-92", "question": "How many of these statements about language policy in education are correct? I. The Kothari Commission recommended the three-language formula. II. Article 350A concerns mother-tongue instruction at the primary stage. III. Article 351 directs the Union to promote the spread of Hindi. IV. NEP 2020 makes it compulsory for every State to teach a particular language.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. NEP 2020 states that no language will be imposed on any State; the choice of languages rests with States and students.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-93", "question": "Arrange these levels of reading comprehension in increasing order of cognitive demand: 1. Evaluative (critical) 2. Literal 3. Inferential", "options": ["2, 3, 1", "3, 2, 1", "2, 1, 3", "1, 3, 2"], "answer": 0, "explanation": "Literal comprehension recalls what is stated, inferential reads between the lines, and evaluative comprehension judges the text against one's own values and knowledge.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-94", "question": "Consider the following statements: 1. Dictation can assess listening and writing together. 2. A cloze test assesses only spelling. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 0, "explanation": "Only 1 is correct. A cloze test checks comprehension, vocabulary and grammar, since the missing words must fit the meaning of the passage.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-95", "question": "Assertion (A): Children should learn the whole alphabet in order before they are exposed to any meaningful text. Reason (R): Reading is mainly the decoding of letters and has little to do with meaning.", "options": ["Both A and R are true and R explains A", "Both A and R are true but R does not explain A", "A is true but R is false", "Both A and R are false"], "answer": 3, "explanation": "Both are false. Reading is making meaning from text; children benefit from stories and print from the start, with decoding skills taught alongside, not before.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-96","question":"A Class II child reads a story aloud fluently but cannot answer simple questions about it. What should the teacher focus on?","options":["More practice in loud, fast reading to build speed and fluency","Comprehension, through talk and links to the child's life","Spelling tests on the difficult words from the story","Copying the story into the notebook for handwriting"],"answer":1,"explanation":"The child can decode but is not making meaning. Talking about the story, predicting and connecting it to life build comprehension.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-97","question":"Which classroom arrangement best supports a child with a hearing impairment in a language class?","options":["Seating the child at the back to avoid distraction","Speaking faster so that the whole lesson gets covered","Turning to the board while speaking, to model the writing clearly","Seating the child to see the teacher's face, with visual aids"],"answer":3,"explanation":"Seeing the speaker's face helps lip-reading, and visual support makes content accessible, in line with inclusive education under the RPwD Act, 2016.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-98", "question": "How many of these statements about the process approach to writing are correct? I. It focuses on the stages through which a piece of writing is composed. II. Feedback from peers is valued. III. Only the final product is assessed. IV. Drafts are revised before the final version.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The process approach also values and assesses drafts and revisions, not just the finished product.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id": "cdp-pedagogy-subjects-99", "question": "Consider the following statements: 1. Phonemic awareness is an oral skill and can be developed without print, for example through rhymes and sound games. 2. Phonics connects sounds with written letters. Which of the above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": 2, "explanation": "Both are correct. Phonemic awareness (hearing and playing with sounds) usually comes first and supports later phonics instruction.", "difficulty": "very-hard", "source": "CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-100","question":"A teacher lets children answer in their home language during an English lesson and then helps them express the same idea in English. This practice is best described as:","options":["Using the mother tongue as a resource for learning English","Lowering the standard of English teaching in the class","The grammar-translation method of language teaching","Avoiding the target language to keep children comfortable"],"answer":0,"explanation":"NCF 2005 treats multilingualism as a resource; building on the home language lets children participate and gradually move to English.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-101","question":"A Class 6 child writes 0.3 × 0.2 = 0.6. Which teaching response best addresses the misconception behind this answer?","options":["Tell the child to count the total decimal places and practise twenty such sums","Use a 10 × 10 grid to show that 3 tenths of 2 tenths is 6 hundredths","Explain that the decimal point in a product stays where it is in the numbers","Convert both numbers to whole numbers, multiply, and ignore the decimal point"],"answer":1,"explanation":"The child is treating decimal multiplication like addition of tenths. An area model shows the answer is 6 hundredths (0.06) and builds the reasoning that taking part of a part gives something smaller; a rule alone leaves the misconception intact.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-102","question":"Asked to fill the box in 5 + ☐ = 12, several Class 2 children write 17. The most likely reason, and the best response, is that the children:","options":["Cannot yet add within 20, so they need more daily addition drill","Did not read the question, so they need to be told to be careful next time","Read ‘=’ as ‘write the answer’; use a balance to show it means ‘the same as’","Are confused by the box, so it should be replaced by a blank line or a letter"],"answer":2,"explanation":"Children often hold an operational view of the equals sign (‘do the sum’). Activities with balances and varied forms of equations develop the relational meaning needed for later algebra.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-103","question":"A Class 4 child insists that 1/8 is bigger than 1/6 ‘because 8 is bigger than 6’. Which activity is most likely to change this idea?","options":["Sharing equal rotis among 6 and among 8 friends and comparing the shares","Making the child write ‘1/6 > 1/8’ ten times in the notebook","Teaching the rule ‘bigger denominator, smaller fraction’ to be memorised","Converting both fractions to decimals with a calculator and comparing"],"answer":0,"explanation":"The child is applying whole-number ordering to fractions. Fair-sharing experience shows that more sharers make smaller pieces, giving meaning to the rule instead of a memorised statement.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-104","question":"Many Class 5 children believe that two rectangles with the same perimeter must have the same area. Which activity best challenges this belief?","options":["Giving the formulas for perimeter and area to memorise and apply","Asking them to find the area and perimeter of a single 6 cm × 6 cm square","Telling them clearly that area and perimeter are different ideas","Making different rectangles from a 24 cm string loop and comparing areas"],"answer":3,"explanation":"With a perimeter of 24 cm they can make 1 × 11 (area 11), 2 × 10 (area 20) or 6 × 6 (area 36): same perimeter, very different areas. Discovering this first-hand changes the belief.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-105","question":"A child measures a pencil by placing its end at the ‘1’ mark of a ruler and reads ‘8 cm’ at the other end; the pencil is actually 7 cm long. The child most likely:","options":["Has poor eyesight and needs a ruler with larger numbers","Reads the number at the end instead of counting the unit spaces","Does not know the numbers up to 10 in the right order","Has been taught the wrong length of a centimetre in an earlier class"],"answer":1,"explanation":"Measuring means counting units (spaces) from a zero point; children who see the ruler as a list of numbers make this error. Measuring with unit strips or ‘broken rulers’ builds the idea.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-106","question":"A teacher first lets children measure the length of the classroom with their own footsteps and hand spans, and only later introduces the metre. The main purpose is to:","options":["Make children see the need for a standard unit when results differ","Avoid teaching standard units altogether in primary classes","Save the cost of buying metre scales for every child","Show that body measures are more accurate than rulers for length"],"answer":0,"explanation":"When different children get different numbers of hand spans for the same length, they see why a common, standard unit is needed; this gives meaning to the metre.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-107","question":"Which response by a Class 4 child shows the best number sense?","options":["Writing 99 + 47 in columns and carrying the ones carefully","Counting on from 99 one by one up to 146","Saying ‘99 + 47 is the same as 100 + 46, so it’s 146’","Using a calculator to work out and check 99 + 47"],"answer":2,"explanation":"Number sense is flexible understanding of numbers and their relationships; seeing 99 as 1 less than 100 and adjusting shows it. The column method is correct but procedural.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-108","question":"A child works out 298 + 165 by thinking ‘300 + 165 = 465, and I added 2 too many, so 463.’ This mental strategy is called:","options":["Partitioning by place value","Counting on in ones","Using the standard algorithm","Compensation"],"answer":3,"explanation":"Compensation rounds one number to a friendly value and then adjusts for the change. It reflects a sound understanding of how numbers can be rearranged.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-109","question":"Squares are made in a row with matchsticks: 1 square needs 4 sticks, 2 squares need 7, 3 squares need 10. A child says 10 squares need 40 sticks. The child’s error and the correct number are:","options":["Counted each square separately, ignoring shared sides; 31 sticks","Added 3 sticks for every square including the first; 30 sticks","Multiplied correctly by 4 sticks per square; 40 sticks is right","Forgot to add the first starting stick of the row; 41 sticks"],"answer":0,"explanation":"After the first square each new square needs only 3 sticks, so n squares need 3n + 1 = 31. Asking children to explain the rule from the figure moves them from counting to algebraic generalisation.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-110","question":"In a pictograph where one 🙂 stands for 5 children, a Class 3 child reads 4 symbols as ‘4 children like mangoes’. The child has difficulty with:","options":["Counting the symbols correctly up to 5","Collecting the data through tally marks first","Interpreting the key (scale) of the pictograph","Drawing the symbols neatly and of equal size"],"answer":2,"explanation":"The child reads each symbol as one item. Building pictographs themselves with a one-to-many key helps children understand scale (4 symbols × 5 = 20 children).","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-111","question":"Shown a triangle standing on one of its corners, several Class 2 children say, ‘That is not a triangle, it is upside down.’ The best teaching response is to:","options":["Tell them that it is a triangle and move on to the next shape","Avoid showing shapes in unusual positions until children reach higher classes","Teach the formal definition of a triangle for them to memorise","Let them make triangles in varied positions and discuss what they share"],"answer":3,"explanation":"Children’s idea of a shape is often tied to a prototype seen in books. Varied examples and attention to defining properties (three straight sides, closed) broaden the concept.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-112","question":"Shown two angles of the same size, one drawn with long arms and one with short arms, a child says the one with longer arms is bigger. Which activity best addresses this?","options":["Making the child memorise that an angle is measured in degrees","Show with hinged strips that angle is the turn, not the arm length","Asking the child to draw the arms more carefully and evenly","Telling the child to always use a protractor, without any discussion"],"answer":1,"explanation":"The misconception confuses angle with arm length. Seeing an angle as an amount of turn, with arms that can be extended without changing it, builds the correct concept.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-113","question":"Asked to write ‘four hundred and five’ in numerals, a Class 3 child writes 4005. The error most clearly shows that the child:","options":["Writes the number as it sounds, without grasping place value","Cannot yet write the digit 5 in the correct form","Does not know the number name ‘four hundred’ at all","Is careless and needs to be told to check the answer again"],"answer":0,"explanation":"Children who write ‘400’ and ‘5’ side by side are transcribing the spoken form. Place value mats and expanded forms (400 + 0 + 5) build the idea that zero holds the tens place.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-114","question":"A child works out 23 × 14 as 23 × 4 = 92 and 23 × 1 = 23, then adds to get 115. The real source of the error is that the child:","options":["Cannot multiply a two-digit number by 4 correctly","Does not know the multiplication table of 23 by heart, so guesses","Treats the 1 in 14 as one, not one ten, so never forms 23 × 10","Adds 23 and 14 at some step instead of multiplying"],"answer":2,"explanation":"The correct product is 92 + 230 = 322. The ‘shift’ in the algorithm stands for multiplying by ten; an area or grid method (20 × 10, 3 × 10, 20 × 4, 3 × 4) makes this visible.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-115","question":"A Class 4 child divides 728 by 7 and writes the quotient as 14. The most likely misconception and the correct quotient are:","options":["The child cannot do 7 ÷ 7 correctly; the answer is 140","The child divided by 2 instead of 7; the answer is 104","The child made an error in the table of 7 while dividing; the answer is 114","Skips the 0 in the tens place when 2 tens cannot be divided by 7; 104"],"answer":3,"explanation":"7 hundreds ÷ 7 = 1 hundred, 2 tens ÷ 7 = 0 tens (carry 20), 28 ones ÷ 7 = 4, so 104. Estimating first (700 ÷ 7 = 100) would show that 14 is far too small.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-116","question":"A teacher asks Class 4 children to make up their own word problems for 24 ÷ 4 and share them. The main pedagogical value of this task is that it:","options":["Reduces the teacher’s work in preparing practice questions","Shows whether children know what division means in real life","Is mainly a test of children’s handwriting and spelling","Helps children memorise the division table of 4 faster"],"answer":1,"explanation":"Problem posing reveals whether children can connect the symbol to meaning; it often exposes children who can calculate but cannot tell when division applies.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-117","question":"Which problem models division as grouping (measurement or quotitive division) rather than as equal sharing?","options":["12 sweets are shared equally among 3 children. How many does each child get?","A ribbon of 12 m is cut into 3 equal pieces. How long is each piece?","There are 12 sweets and each child gets 3. How many children get sweets?","12 apples are put equally into 3 baskets. How many are in each basket?"],"answer":2,"explanation":"In grouping, the size of each group is known and the number of groups is asked; in sharing, the number of groups is known and the size of each is asked. Children need experience of both.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-118","question":"Which assessment item would give a teacher the MOST diagnostic information about children’s understanding of subtraction?","options":["Ten sums like 64 − 28, each marked simply as right or wrong","A timed test of fifty basic subtraction facts up to 20","A multiple-choice question on the rule for borrowing","Solving 64 − 28 and explaining the method in words or drawings"],"answer":3,"explanation":"An explanation shows the strategy and reasoning behind the answer, revealing specific misconceptions; right/wrong marks show only whether the result was correct.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-119","question":"The NCF 2005 position paper on mathematics distinguishes a ‘narrow aim’ and a ‘higher aim’ of school mathematics. The higher aim is to:","options":["Develop mathematical thinking: reasoning, logic and handling abstraction","Teach useful numeracy for daily life, such as calculation and measurement","Prepare every child for competitive and entrance examinations later","Complete the syllabus on time with plenty of drill and practice"],"answer":0,"explanation":"The narrow aim is useful numeracy; the higher aim is to develop mathematical thinking itself, which NCF 2005 calls the main goal (mathematisation).","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-120","question":"Children can correctly show 42 − 17 with base-ten blocks by exchanging a ten for ten ones, but they still make errors in the written column method. The teacher’s best next step is to:","options":["Stop using blocks because they are confusing the children","Have children record each step on paper as they do it with the blocks","Teach the written method separately as a fixed set of rules to follow","Give them more practice with the blocks alone, without writing"],"answer":1,"explanation":"Concrete materials help only when connected to the symbols; recording alongside the action builds the bridge from the enactive to the symbolic form.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-121","question":"Exploring a calendar, children find that in several 3 × 3 blocks the sum of the nine dates equals 9 times the middle date. One child says, ‘If the middle is n, the dates are n − 8, n − 7, n − 6, n − 1, n, n + 1, n + 6, n + 7, n + 8, and they add up to 9n.’ This child has moved from:","options":["Rote recall of calendar facts to quick and accurate mental calculation","Measurement of time to rough estimation of the totals","Checking examples to a general argument for why it always holds","Algebraic reasoning back to plain arithmetic on dates"],"answer":2,"explanation":"Testing cases is inductive; using a variable to show the pattern holds for every block is generalisation and justification, a key step towards algebraic reasoning.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-122","question":"A Class 3 child shades one part of a circle divided into four unequal parts and calls it ‘one-fourth’. The child has not yet understood that:","options":["Fractions can only be shown using circles, not other shapes","The parts must be equal for each to be a fourth of the whole","A fraction must always have 1 as its numerator, as in 1/4","Shading must always start from the top part of the circle"],"answer":1,"explanation":"A fraction names one of several equal parts. Folding paper strips into equal and unequal parts and comparing helps children see this.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-123","question":"When the clock shows 3:45, a child reads it as ‘4:45’ because the hour hand is almost at 4. What does the child not yet understand?","options":["How to count minutes in fives around the clock face","That the minute hand is the longer one and shows the minutes passed","How many minutes make one complete hour on a clock","That the hour hand moves slowly between numbers during the hour"],"answer":3,"explanation":"Reading time needs coordinating both hands; using a geared clock to watch the hour hand travel between numbers as the minute hand goes round builds this understanding.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-124","question":"‘Ram has 5 more marbles than Shyam. Ram has 12 marbles. How many does Shyam have?’ Many children answer 17, explaining ‘more means add’. The best teaching response is to:","options":["Ask children to model the situation with bars, not rely on key words","Give a list of key words for each operation to memorise","Tell children to always subtract in word problems that have two numbers","Avoid such problems because they are confusing for children"],"answer":0,"explanation":"The key-word strategy fails whenever the language is ‘inconsistent’ with the operation. Representing the relationship (Shyam = 12 − 5 = 7) builds real problem comprehension.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-125","question":"In mathematics education, a task is a genuine ‘problem’ for a learner (rather than an exercise) when:","options":["It contains large numbers or many steps of calculation","It is taken from the end-of-chapter section of the textbook","The learner does not already know a method and must work one out","It has first been solved by the teacher on the board as a model"],"answer":2,"explanation":"A problem requires the learner to devise an approach; an exercise practises a method already known. The same task can be a problem for one child and an exercise for another.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-126","question":"A Class 6 student checks that 3 + 5, 7 + 9, 11 + 13, 1 + 1 and 15 + 21 are all even, and says she has ‘proved’ that the sum of two odd numbers is always even. The best teacher response is to:","options":["Accept it as a proof, since five varied examples are enough","Tell her the statement is false, as some odd sums are odd","Ask her to test fifty more examples so that the proof becomes complete","Show that examples cannot cover every case and build a general argument"],"answer":3,"explanation":"Examples support a conjecture but cannot cover every case. A general argument (for example 2m + 1 + 2n + 1 = 2(m + n + 1)) shows why it must always hold, introducing children to mathematical proof.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-127","question":"A Class 5 student who is blind is learning about shapes and number operations in an inclusive class. Which resources are most suitable?","options":["Coloured charts and printed worksheets in a large font","Tactile shapes, geoboards and an abacus, with written work read aloud","Asking a classmate to do all the written work on her behalf","Exempting her from geometry, since the topic is mainly visual in nature"],"answer":1,"explanation":"Tactile materials and an abacus give access to geometry and calculation; exemption or having others do the work denies her the learning the RPwD Act aims to secure.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-128","question":"Which practice is most likely to REDUCE mathematics anxiety among children?","options":["Daily timed tests with the results read out in class","Insisting on one ‘correct’ method so children are not confused","Valuing varied methods and treating errors as part of learning","Making slow children stand until they answer correctly"],"answer":2,"explanation":"Fear of public failure and speed pressure feed maths anxiety; an environment that values reasoning over speed and accepts multiple methods reduces it, as NCF 2005 urges.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-129","question":"Asked, ‘What is the difference between 15 and 9?’, a child says, ‘15 has a 1 and 5, and 9 has only one digit.’ The teacher should recognise that:","options":["The child lacks number knowledge and must go back to counting","The child is being deliberately cheeky to the teacher","The question is too difficult for children at the primary level","The child is using the everyday meaning of the word ‘difference’"],"answer":3,"explanation":"Words such as difference, product, table and volume have different everyday meanings. Making the mathematical meaning explicit is part of developing the language of mathematics.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-130","question":"During an EVS lesson on families, a Class 3 child says, ‘I live only with my mother and grandmother.’ Some classmates laugh. The most appropriate response of the teacher is to:","options":["Tell the class that a ‘proper’ family has a father, mother and children","Ignore the remark and continue with the textbook picture of a family","Ask the child to sit quietly so that she is not embarrassed further","Discuss how families differ, inviting children to share without judgement"],"answer":3,"explanation":"EVS aims to help children appreciate diversity in families and lifestyles; building on the child’s experience respectfully counters stereotypes and teasing.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-131","question":"Many questions in the NCERT EVS books (‘Have you ever seen…?’, ‘What do people in your family do when…?’) have no answer printed in the chapter. The main reason is that:","options":["The answers were left out to keep the books short and light","They draw on children’s own experiences, so many answers can be right","Children are expected to find the single correct answer from a guidebook","Teachers are expected to dictate model answers for children to memorise"],"answer":1,"explanation":"The books treat children as sources of knowledge; open questions link EVS to the child’s life and require teachers to accept varied responses rather than one ‘right’ answer.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-132","question":"In an EVS activity, children collect leaves and group them by shape, edge and texture, explaining their groups. Which NCERT indicator of EVS learning is mainly being assessed?","options":["Classification","Concern for justice and equality","Experimentation","Cooperation"],"answer":0,"explanation":"Grouping objects by observed features and explaining the basis of grouping is the indicator ‘classification’; it also draws on observation.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-133","question":"Match the EVS classroom behaviour with the NCERT learning indicator it best shows: 1. A child asks, ‘Why do some birds have long, thin beaks?’ 2. A child objects that a chapter’s story treats a girl unfairly. 3. A child tries soaking seeds in different amounts of water to see what happens. 4. A child explains in her own words why clothes dry faster on a windy day; a. Explanation b. Experimentation c. Concern for justice and equality d. Questioning","options":["1-d, 2-c, 3-b, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-d, 2-c, 3-a, 4-b"],"answer":0,"explanation":"Asking ‘why’ is questioning, objecting to unfair treatment shows concern for justice and equality, trying out conditions is experimentation, and accounting for a phenomenon in one’s words is explanation.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-134","question":"A teacher holds up a cricket ball and a tennis ball and asks, ‘If I drop them together from this height, which will land first? Write down your guess and why.’ She then drops them, and the class discusses why the result differed from many predictions. This strategy is called:","options":["Concept mapping exercise","Brainstorming session","Predict–Observe–Explain","Programmed instruction"],"answer":2,"explanation":"POE makes children commit to a prediction, which brings out their ideas (heavier falls faster), then uses observation and discussion to challenge and reconstruct them.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-135","question":"A Class 7 student explains that it is winter in December ‘because the earth is then farthest from the sun’. Which piece of evidence would best challenge this idea?","options":["The earth moves in an orbit around the sun, taking one year","When India has winter, Australia has summer","The sun appears smaller and paler in the sky during winter","Days are shorter and nights are longer in India during winter"],"answer":1,"explanation":"If distance caused seasons, both hemispheres would have the same season at once. Opposite seasons in the two hemispheres point to the tilt of the earth’s axis as the cause.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-136","question":"A Class 4 child says, ‘A bus is living because it moves, but a tree is not living because it does not move.’ Which teaching approach best addresses this idea?","options":["Make the child memorise the definition of a living thing","Tell the child that only animals and humans are living things","Show a video of a moving bus and a still tree for comparison","Apply several life features, like growth, to the tree and the bus"],"answer":3,"explanation":"The child is using one feature (movement) as the test of life. Considering several characteristics together lets children see why a tree is living and a bus is not.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-137","question":"To find out whether seeds need water to sprout, a child puts seeds on wet cotton in one bowl and on dry sand in another. The main flaw in this test is that:","options":["Water and the material were both changed, so water alone is not tested","Seeds should be planted in a pot of soil, not in a bowl","Only one bowl should have been used, with more seeds placed in it together","The child should have used a microscope to watch the seeds"],"answer":0,"explanation":"A fair test changes only the factor under study and keeps everything else the same; here cotton should be used in both bowls, one wet and one dry.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-138","question":"Class 8 students decide on their own question (‘Does the colour of a cloth affect how fast it dries?’), plan their own method, collect data and present conclusions, with the teacher only facilitating. This is best described as:","options":["Confirmation inquiry","Structured inquiry","Open inquiry","Teacher demonstration"],"answer":2,"explanation":"In open inquiry students frame the question and design the investigation themselves. In structured inquiry the teacher gives the question and procedure, and in confirmation inquiry students verify a known result.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-139","question":"The NCF 2005 position paper on science lists criteria a good science curriculum must meet. Including the story of how scientific ideas changed over time, such as the shift from an earth-centred to a sun-centred view, mainly serves:","options":["Cognitive validity","Ethical validity","Environmental validity","Historical validity"],"answer":3,"explanation":"Historical validity means the curriculum shows how science developed and changed, showing it as a social enterprise. The other criteria are cognitive, content, process, environmental and ethical validity.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-140","question":"Under the NCF 2005 science criteria, a curriculum has ‘process validity’ when it:","options":["Is suited to the age and cognitive level of the learners","Engages learners in the methods by which science builds knowledge","Presents scientifically correct and significant content","Promotes values of honesty, objectivity and a concern for all forms of life"],"answer":1,"explanation":"Process validity concerns learning how scientific knowledge is generated, through observation, experiment and reasoning. The other options describe cognitive, content and ethical validity.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-141","question":"Class 5 children interview their grandparents about where the family got drinking water fifty years ago and compare it with today. The main learning purpose of this activity in EVS is to help children:","options":["Understand change over time and link it with people’s lives","Improve their handwriting through careful note-taking","Memorise the names of different old and new water sources","Learn that old practices were always better than new ones"],"answer":0,"explanation":"Oral history surveys link the present to the past and show how environment and society shape each other, an integrated EVS aim; they also develop questioning and recording skills.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-142","question":"Children draw a map of their route from home to school, marking landmarks such as a temple, a shop and a pond. This activity mainly helps them to:","options":["Learn the scale and projection used in standard printed maps","Memorise the names of shops and buildings on the way","Develop a sense of space and direction, the basis of map reading","Improve their drawing and colouring as an art activity"],"answer":2,"explanation":"Drawing familiar routes builds spatial understanding, perspective and the use of symbols, the foundation of mapping skills developed later in EVS.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-143","question":"A teacher fills her science periods with activities: children float objects, mix colours and grow seeds, but she moves straight on to the next activity without any discussion. What is most clearly missing?","options":["More activities, so that children are kept busy and interested","A written test after every activity to check the facts","Strict silence during the activities so children concentrate","Discussion that helps children make sense of what they observed"],"answer":3,"explanation":"Activities lead to learning only when children are helped to think about what happened, explain it and connect it to concepts; activity alone does not build understanding.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-144","question":"In a school without a science laboratory, a teacher uses plastic bottles, straws, balloons and old cells to teach ideas about air pressure and electricity. This practice is best described as:","options":["Poor teaching, because real laboratory apparatus is always needed","Improvisation with low-cost local materials, as NCF 2005 urges","A waste of class time that should go to the textbook","Suitable only for children who cannot afford books"],"answer":1,"explanation":"Low-cost, improvised materials make hands-on science possible everywhere and help children see science in everyday objects.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-145","question":"To explain an electric circuit, a teacher compares electric current to water flowing in pipes. Which follow-up best uses this analogy responsibly?","options":["Discussing where the analogy works and where it breaks down","Avoiding analogies altogether, since they always cause misconceptions","Telling children that electricity is a kind of water","Using the analogy only in tests and not in teaching"],"answer":0,"explanation":"Analogies help children grasp abstract ideas, but learners can transfer irrelevant features; making the limits explicit prevents new misconceptions.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-146","question":"A teacher shows a cartoon in which three children give different views about why a snowman wrapped in a coat will melt faster, slower or at the same rate, and asks the class whom they agree with and why. The main purpose of such a concept cartoon is to:","options":["Entertain children before the real lesson begins","Test whether children can read and understand speech bubbles","Draw out children’s ideas and get them to argue and test them","Give the correct answer in an attractive, memorable form"],"answer":2,"explanation":"Concept cartoons present competing ideas, including common misconceptions, to provoke discussion and investigation (here, a coat insulates and slows melting).","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-147","question":"An EVS discussion asks who in the neighbourhood cleans drains and collects garbage, how they are treated, and how the children would feel doing that work. The main aim of such a discussion is to:","options":["Teach children the correct steps of cleaning a drain safely","Discourage children from keeping their surroundings clean","Show that such work belongs to particular communities by tradition","Sensitise children to the dignity of labour and inequities in work"],"answer":3,"explanation":"EVS includes the social environment; examining who does what work and how they are treated promotes empathy, equality and respect for labour.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-148","question":"A Class 3 child who cannot yet write well draws a detailed picture of how her family stores water at home and explains it orally. As an EVS assessment, the teacher should:","options":["Give no marks, because nothing has been written down","Accept the drawing and explanation as valid evidence of learning","Ask her to copy a written answer from the board instead","Mark her down for not using the textbook answer and its exact words"],"answer":1,"explanation":"Assessment in EVS should allow varied forms of expression; drawing and speaking are valid ways to show observation and understanding, especially in early grades.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-149","question":"Class 6 students can recite that ‘photosynthesis is the process by which green plants make food using sunlight’, but cannot explain why a plant kept in a dark cupboard for a week has become pale and weak. This shows that their learning is mainly:","options":["Rote, without understanding that applies to new situations","Conceptual, because they can state the definition accurately","Experiential, since they have seen plants growing at home","Complete, as the definition they recite is correct"],"answer":0,"explanation":"Applying an idea to explain a new situation is a test of understanding; reproducing a definition shows only memorisation.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-150","question":"Which behaviour of a student best shows a scientific attitude?","options":["Changing her readings so that they match the textbook value","Accepting a claim because it was made by an elder or a book","Recording a surprising result honestly and repeating the test","Refusing to consider a classmate’s explanation that differs from hers"],"answer":2,"explanation":"Honesty in recording data, scepticism and willingness to check results are the core of scientific attitude; fudging data or accepting authority uncritically are not.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-151","question":"Asked to group pictures of 12 animals, one group sorts by ‘lives on land / in water’, another by ‘has legs / no legs’ and a third by ‘eats plants / eats animals’. The teacher should:","options":["Accept only the textbook grouping and mark the others wrong","Choose the ‘best’ grouping and ask the other groups to copy it","Tell children that classification can only be done properly by scientists","Accept every grouping based on a clear, consistently applied criterion"],"answer":3,"explanation":"Classification depends on the criterion chosen; what matters is that it is clearly stated and applied consistently. Discussing different schemes deepens understanding.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-152","question":"In an EVS lesson on food, a teacher encourages children to use the local names of grains, vegetables and dishes eaten at home. The main reason is that this:","options":["Connects classroom learning with children’s home knowledge","Avoids the need for any standard names in later classes","Saves the time needed to teach the standard names of foods","Shows the teacher which children come from rural families"],"answer":0,"explanation":"Using children’s own words and experiences validates home knowledge and helps them link new learning to what they already know.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-153","question":"Many Class 7 students believe that electric current ‘gets used up’ in a bulb, so less current returns to the cell. Which activity best challenges this idea?","options":["Telling them that energy is always conserved in a circuit","Measuring the current with an ammeter on both sides of the bulb","Making them memorise the definition of current and its unit","Showing that a bulb gets hot, so something is used up"],"answer":1,"explanation":"In a series circuit the current is the same everywhere; equal ammeter readings on both sides of the bulb directly contradict the ‘used up’ model. Energy, not charge, is transferred in the bulb.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-154","question":"A teacher holds an open-book test in EVS. Which kind of question suits it best?","options":["‘List the six themes of EVS given in the textbook.’","‘Write the definition of a food chain as given in the book.’","‘Name three sources of water mentioned in the book.’","‘Give two reasons why the school pond may have dried up.’"],"answer":3,"explanation":"Open-book tests are meant to assess application, analysis and reasoning; recall questions would only reward copying from the book.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-155","question":"A teacher wants to show a reaction that involves heating a strong acid. The most suitable method is:","options":["A teacher demonstration with safety measures, then discussion","Letting each child do it alone to build their confidence","Skipping the topic altogether because it is unsafe","Only reading about it in the textbook, with no demonstration"],"answer":0,"explanation":"Demonstration is appropriate when materials are dangerous, expensive or scarce; children can still predict, observe and explain, keeping it inquiry-oriented.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-156","question":"Which question in an EVS lesson on water best promotes critical thinking about the social environment?","options":["‘What colour is water, and what does it taste like?’","‘Name two rivers of India and the states they flow through.’","‘In your area, who walks farthest to fetch water, and why?’","‘How many glasses of water do you drink a day?’"],"answer":2,"explanation":"This question asks children to notice and reason about unequal access to resources (by gender, place or class), linking science and social issues as EVS intends.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-157","question":"How many of the following are consistent with the NCF 2005 view of science teaching at the upper primary stage? I. Learning science through familiar experiences and simple experiments. II. Treating science as a fixed set of facts to be memorised. III. Encouraging children to ask questions and test their own ideas. IV. Linking science with environmental and health concerns.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV match NCF 2005, which sees science as a process of inquiry. Viewing it as a fixed body of facts for memorisation is what it argues against.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-158","question":"Which of the following is the most suitable way to begin a Class 4 EVS lesson on ‘Our Food’?","options":["Dictating notes on carbohydrates, proteins and fats","Asking children what they ate yesterday and how it was cooked","Giving a short written test on food nutrients and vitamins","Writing the chapter summary on the board for children to copy"],"answer":1,"explanation":"Starting from children’s own experience (their meals) makes the topic meaningful and lets the teacher build on prior knowledge, as EVS pedagogy recommends.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-159","question":"After reading a story, a teacher writes five sentences from it on the board (‘The fox jumped…’, ‘The crow dropped…’) and asks children what they notice about the action words and when the events happened. The children work out how the past tense is formed. This way of teaching grammar is:","options":["Deductive, because the rule comes first","Inductive, in context, because learners discover the rule from examples","Grammar-translation, because sentences are compared with the mother tongue","Audio-lingual, because it relies on pattern drills"],"answer":1,"explanation":"In the inductive approach, learners observe examples in meaningful context and infer the rule, which leads to better understanding than memorising a rule first.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-160","question":"A learner of English regularly writes ‘He go to school daily’, but once, while hurrying, wrote ‘They was late’ although she normally writes ‘They were’. In S. P. Corder’s terms:","options":["Both are mistakes, since she generally knows English well","Both are errors, since both forms are grammatically incorrect","The first is a mistake (a slip) and the second an error (systematic)","The first is an error (systematic) and the second a mistake (a slip)"],"answer":3,"explanation":"Corder distinguished systematic errors, which reveal the learner’s current rule system, from occasional mistakes, which she can self-correct. Errors are useful evidence of what to teach next.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-161","question":"A Class 6 learner of English consistently says ‘He no like mango’ and ‘She no coming today’. Language teachers would describe this as:","options":["Interlanguage: the learner’s own rule-governed, developing system","Proof that the learner cannot learn English properly at this late age","Deliberate carelessness that should be firmly punished","A speech disorder needing therapy from a specialist"],"answer":0,"explanation":"Selinker’s interlanguage is the learner’s own evolving grammar; using ‘no’ before the verb for all negatives is a normal stage that changes with rich input and feedback.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-162","question":"A child whose home language does not allow words to begin with ‘sk’ says ‘iskool’ for ‘school’. The best teacher response is to:","options":["Correct the child sharply in front of the class every time","Model the word naturally, treating it as normal first-language influence","Ask the child to stop speaking English until the pronunciation is perfect","Ignore spoken English and focus only on written English instead"],"answer":1,"explanation":"Transfer of first-language sound patterns is natural; plenty of input, modelling and low-anxiety practice help, while public correction raises the affective filter.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-163","question":"A four-year-old turns the pages of a picture book and ‘reads’ the story aloud from the pictures, though she cannot yet decode the words. This behaviour should be seen as:","options":["Cheating, because she is not actually reading the printed words","A sign of a reading disability that needs early testing","Emergent literacy, to be encouraged as real progress towards reading","Proof that she has memorised the book and so needs no further help now"],"answer":2,"explanation":"Pretend reading shows growing concepts about print, story structure and book handling; the emergent literacy view treats such behaviour as real progress towards reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-164","question":"A Class 1 child writes, ‘I wnt to skool on my sikl.’ From the perspective of early writing development, the teacher should recognise that:","options":["The child must be stopped from writing until spelling is correct","The child is careless and needs to copy each word correctly five times","The spellings show that the child has not learnt the alphabet properly","Invented spelling from sound–letter knowledge, a normal stage to value"],"answer":3,"explanation":"Invented spellings like ‘skool’ and ‘sikl’ show the child hearing sounds and mapping them to letters. Encouraging writing for meaning, with gentle modelling, builds both fluency and accuracy.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-165","question":"Before reading a chapter on bees, students fill in what they already know and what they want to know, and after reading they note what they have learnt. This reading strategy is:","options":["SQ3R","The KWL chart","The cloze procedure","Skimming"],"answer":1,"explanation":"KWL (Know, Want to know, Learnt) activates prior knowledge, sets a purpose for reading and supports reflection on learning.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-166","question":"In a weekly library period, children choose storybooks they like and read many of them for pleasure, without answering questions afterwards. This is an example of:","options":["Extensive reading","Intensive reading","Scanning","Choral reading"],"answer":0,"explanation":"Extensive reading means reading a lot of self-chosen material for enjoyment and general understanding; it builds fluency, vocabulary and the reading habit. Intensive reading studies a short text closely.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-167","question":"Which is the most suitable way to teach a poem to Class 5 children?","options":["Explaining the meaning line by line for children to memorise","Asking children to write meanings of hard words before hearing it","Testing them on the poet’s life and other famous works","Reading it aloud with expression and inviting children’s responses"],"answer":3,"explanation":"Poetry is first to be enjoyed and responded to; line-by-line paraphrase and memorised meanings kill the pleasure and personal response that literature aims to develop.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-168","question":"A teacher gives each essay a single overall grade based on her general impression of its quality, rather than separate marks for content, organisation, vocabulary and grammar. Which statement is correct?","options":["Analytic scoring, which gives detailed diagnostic feedback on each part","Holistic scoring: quick, but less diagnostic than analytic scoring","Checklist scoring, ticking features present or absent","Norm-referenced scoring, ranking essays against each other"],"answer":1,"explanation":"Holistic scoring rates the whole piece at once; analytic scoring rates separate components and so shows learners exactly where to improve.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-169","question":"Students work in pairs: one has a picture of a room and the other a slightly different picture. Without showing their pictures, they talk to find the differences. This kind of task is called:","options":["A substitution drill in pairs","Choral repetition","An information-gap activity","Picture dictation"],"answer":2,"explanation":"In an information-gap activity each learner has information the other needs, so they must communicate for a real purpose, a core technique of the communicative approach.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-170","question":"A teacher of young learners says, ‘Stand up! Touch your nose! Hop three times! Sit down!’ and children respond with actions, without being required to speak yet. This method is:","options":["The grammar-translation method","The silent way","The direct method using reading aloud","Total Physical Response (TPR)"],"answer":3,"explanation":"Asher’s TPR links language with physical action, lets learners first show understanding through movement, and keeps anxiety low before speaking is expected.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-171","question":"A Class 3 child reads very slowly, word by word with a finger under each word, though he decodes accurately. Which strategy is most likely to improve his reading fluency?","options":["Repeated reading of familiar texts, with paired reading","More phonics worksheets on letter sounds and blends","Asking him to read only silently, so no one hears him","Giving him longer and harder texts so that he is challenged"],"answer":0,"explanation":"He already decodes; what he lacks is automaticity. Re-reading familiar texts and hearing fluent models build speed, phrasing and expression.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-172","question":"While reading, a child meets the word ‘parched’ in ‘After weeks without rain, the parched fields cracked open.’ Which strategy should the teacher encourage first?","options":["Stop reading and look up the word in the dictionary at once","Skip the word, since one word does not affect the meaning","Guess from clues like ‘weeks without rain’, then check","Ask the teacher at once for the meaning of every new word"],"answer":2,"explanation":"Guessing meaning from context keeps reading fluent and builds independent word learning; the dictionary can confirm the guess later.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-173","question":"A three-year-old points at a new object and keeps asking, ‘What’s that? Why?’ In Michael Halliday’s account of children’s language functions, this use of language is:","options":["Instrumental","Regulatory","Imaginative","Heuristic"],"answer":3,"explanation":"Halliday’s heuristic function is using language to explore and learn about the world. Instrumental is getting things (‘I want…’), regulatory is controlling others, and imaginative is creating pretend worlds.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-174","question":"A Class 8 student writes a leave application to the principal beginning, ‘Hey Sir! Can’t come tomorrow, got stuff to do.’ The student mainly needs help with:","options":["Spelling of everyday words used in letters","Register: language suited to purpose and audience","Handwriting and neat layout of the letter page","Grammar of the past and future tenses in letters"],"answer":1,"explanation":"The sentence is grammatical but too informal for a formal letter. Comparing texts for different audiences builds awareness of register.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-175","question":"A Class 5 teacher has children write their own stories, revise them with peer feedback and publish them in a class magazine read by other classes and parents. The main pedagogical value of publishing is that it:","options":["Gives children a real audience and purpose for careful writing","Saves the teacher from correcting all the stories herself","Helps children memorise their own and others’ stories","Allows the teacher to rank children by their writing ability"],"answer":0,"explanation":"Writing for real readers gives purpose, raises motivation and makes revision meaningful, a key idea of the process and whole-language approaches.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-176","question":"Which item from a Class 4 language test best assesses creative and divergent thinking?","options":["‘Who was the king in the story, and where did he live?’","‘Write the meaning of the word “brave” as used in the story.’","‘Rewrite the ending so the king learns his lesson in a new way.’","‘Fill in the blank with the correct form of the verb.’"],"answer":2,"explanation":"Rewriting the ending is open-ended, allows many acceptable answers and requires imagination; the others check recall or a single correct form.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-177","question":"Which task integrates listening, speaking, reading and writing most fully?","options":["Copying a paragraph from the board into the notebook","Hearing a weather report, discussing it, then reading and writing forecasts","Reading a lesson silently and answering questions in one word","Reciting a learnt poem from memory, with actions, in front of the whole class"],"answer":1,"explanation":"Language skills develop best together through meaningful tasks; this sequence uses all four in a connected way, unlike tasks that isolate one skill.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-178","question":"Assertion (A): Grammar should be taught through rules and exercises in isolation before children start using the language for communication. Reason (R): Knowing grammar rules is the main way children acquire the ability to speak a language.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Children acquire language mainly through meaningful use and rich input; grammar is better learnt in context alongside use, not as a precondition for it.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-179","question":"A Class 2 child reads the sentence ‘The boy ran to his house’ aloud as ‘The boy ran to his home’. In miscue analysis this miscue suggests that the child:","options":["Cannot read and needs to start again with the alphabet","Is careless and should be stopped and corrected at once, each and every time","Is reading for meaning, though attention to the print can be sharpened","Has a visual problem and needs an eye test before reading"],"answer":2,"explanation":"Goodman’s miscue analysis treats reading errors as windows into the strategies a reader uses. A substitution that keeps the meaning shows the child is reading for sense.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-180","question":"Which classroom plan best reflects a balanced approach to early literacy?","options":["Phonics drills only, with no stories until the child can decode","Stories only, with no direct attention to letters and sounds","Read-alouds and shared reading plus systematic phonics and daily writing","Copying letters and words from the board for most of every language period"],"answer":2,"explanation":"Balanced literacy combines meaning-centred reading and writing with explicit teaching of the sound–letter system, rather than either alone.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-181","question":"For a student with a visual impairment in a language class, the most suitable support is:","options":["Exempting her from reading and writing tasks altogether","Audio books, Braille or large print, and reading the board aloud","Asking a friend to do her reading and written homework","Seating her at the back of the class to avoid disturbing other children"],"answer":1,"explanation":"Accessible formats and oral support let her take full part in reading and writing; exemption or dependence on others denies her learning.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-182","question":"Regular storytelling in the early grades mainly helps children to:","options":["Prepare for written examinations through model answers","Learn grammar rules explicitly through the teacher’s explanation","Improve their handwriting by writing the stories down","Develop listening, vocabulary, imagination and a sense of story"],"answer":3,"explanation":"Stories expose children to rich language in meaningful context and build listening comprehension, vocabulary, prediction and narrative sense, the base for reading.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-183","question":"A teacher keeps a folder for each child with dated samples of writing from the year, a reading log, an audio recording of the child reading, and the child’s comments on her own progress. This tool is a:","options":["Portfolio","Cumulative record","Rating scale","Question bank"],"answer":0,"explanation":"A language portfolio is a purposeful collection showing growth over time with the learner’s reflection; it supports continuous, comprehensive assessment.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-184","question":"Which question about a story checks evaluative (critical) comprehension?","options":["‘Where did the farmer go in the morning?’","‘Why do you think the farmer did not tell anyone about the treasure?’","‘How many sons did the farmer have?’","‘Do you think the farmer was fair to his sons? Give reasons.’"],"answer":3,"explanation":"Evaluative questions ask readers to judge ideas or actions using their own values and reasoning. ‘Why do you think…’ asks for an inference, and the others check literal recall.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-185","question":"According to NCF 2005, the main aim of teaching a second language such as English in the early years is that children should:","options":["Communicate naturally in it, using the home language as a resource","Learn grammar rules thoroughly before using the language at all","Read only the prescribed textbooks with full accuracy","Translate texts word by word into the mother tongue to check meaning"],"answer":0,"explanation":"NCF 2005 stresses acquiring the second language through rich, comprehensible input and meaningful use, with multilingualism as a resource, rather than through grammar and translation.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-186","question":"A Class 7 teacher asks students to record a conversation in the market, transcribe it, and compare it with a dialogue in their textbook. The main learning outcome is awareness of:","options":["How spoken language differs from written language","The spelling of difficult words used in markets","The history and economics of the local market","Handwriting speed when transcribing quickly"],"answer":0,"explanation":"Analysing real speech helps learners notice how spoken language differs from written dialogue, building language awareness and sensitivity to how language is used.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-187","question":"Which practice in a language class is LEAST consistent with treating errors as part of learning?","options":["Noting common errors and addressing them later through practice","Recasting a child’s incorrect sentence correctly in the reply","Interrupting a child mid-story to correct every error","Encouraging peers to give each other feedback on drafts"],"answer":2,"explanation":"Constant interruption focuses on form over meaning, raises anxiety and discourages speaking; the other practices give feedback without blocking communication.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-188","question":"A Class 7 student simplifies 2a + 3b as 5ab. Which teacher response is most likely to help her see the error for herself?","options":["Tell her unlike terms can never be added and ask her to memorise it","Give her ten more sums of the same kind for practice","Ask her to put a = 2, b = 3 into both expressions and compare","Explain that ‘ab’ means a times b, not a plus b"],"answer":2,"explanation":"Substituting numbers shows that the two expressions are not equal, which creates cognitive conflict and builds the idea that letters stand for numbers; a rule alone does not.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-189","question":"Asked to write an expression for ‘the cost of 3 pens and 2 books’, a student writes ‘3p + 2b’ and explains, ‘p means pens and b means books.’ The teacher’s main concern should be that the student:","options":["Has written a wrong expression for the total cost","Sees letters as labels for objects, not as numbers (prices)","Does not know how multiplication is shown in algebra","Should have used x and y, the standard letters for unknowns"],"answer":1,"explanation":"The expression is right, but the ‘letter as object’ (fruit-salad) view causes later errors, such as reading 3p as ‘3 pens’. The teacher should stress that p stands for the price of one pen.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-190","question":"A Class 6 student says −5 is greater than −2 ‘because 5 is greater than 2’. Which context best helps correct this idea?","options":["A thermometer: −5 °C is colder, so lower, than −2 °C","Telling the student that the rule for negatives is the opposite","Counting objects in groups of 5 and 2 and comparing the groups","Adding −5 and −2 on paper and comparing with 5 + 2"],"answer":0,"explanation":"A vertical number line such as a thermometer shows that numbers further below zero are smaller, giving meaning to the order of negative integers.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-191","question":"Most students in a class claim that if a price is increased by 20% and then decreased by 20%, it returns to the original price. The best teaching move is to:","options":["Tell them they are wrong and give the formula to apply","Skip the problem as too advanced for this class level","Ask them to memorise that successive changes are not additive","Ask them to try it with ₹100 (→ ₹120 → ₹96) and explain why"],"answer":3,"explanation":"Working with a concrete value reveals the result and shows why: the 20% decrease is taken on ₹120, not ₹100. Students then construct the idea of a changing base themselves.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-192","question":"A recipe for 4 people needs 6 cups of rice. Asked how much is needed for 6 people, a child says 8 cups ‘because 2 more people means 2 more cups’. The correct amount and the child’s difficulty are:","options":["9 cups; the child is adding instead of reasoning proportionally","8 cups; the child is right, since 2 more people need 2 more cups","10 cups; the child has made a counting error of two cups","12 cups; the child should double the amount for more people"],"answer":0,"explanation":"Each person needs 6 ÷ 4 = 1.5 cups, so 6 people need 9 cups. Adding a fixed difference instead of keeping the ratio is the most common error in proportional reasoning.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-193","question":"To help Class 4 children understand symmetry, the most suitable activity is:","options":["Writing the definition of a line of symmetry five times","Folding cut-outs and ink-blot patterns to see if the halves match","Reading the chapter on symmetry silently and underlining terms","Measuring the angles of a square and a rectangle with a protractor"],"answer":1,"explanation":"Folding and matching halves gives a direct, hands-on experience of reflection symmetry that children can then look for in letters, leaves and rangoli.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-194","question":"A child finds the area of a 4 cm by 3 cm rectangle and writes ‘12 cm’. The teacher’s best response is to:","options":["Deduct a mark for the wrong unit and move on to the next sum","Explain again that the formula for area is length × breadth","Let her tile it with 1 cm squares and count, to see units of area","Ask her to measure the sides again more carefully with a ruler"],"answer":2,"explanation":"The number is right but the unit shows she does not yet see area as the number of unit squares covering a surface; tiling builds this meaning of cm².","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-195","question":"A teacher studies symmetry and patterns through the rangoli, kolam and weaving designs that children’s families make at home. This approach is best described as:","options":["Rote learning of geometric terms through a few cultural examples","Recreational mathematics with no link to the syllabus","Avoiding formal geometry in favour of craft activities","Ethnomathematics, linking school maths with cultural practices"],"answer":3,"explanation":"Ethnomathematics recognises mathematical ideas in everyday cultural practices; using them links school maths to children’s lives, as NCF 2005 recommends.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-196","question":"A shop offers ‘Buy 2, get 1 free’ while another offers ‘30% off’ on the same item. Which question built on this situation best assesses application and reasoning in Class 7?","options":["‘Which offer is better on 3 items? Show your reasoning.’","‘Define percentage and give one example of it.’","‘Write 30% as a fraction in its lowest terms.’","‘What is 30% of ₹100? Write the answer in rupees and paise.’"],"answer":0,"explanation":"Comparing offers needs students to see that ‘buy 2, get 1 free’ is a 1/3 (about 33.3%) discount on 3 items, better than 30%; the other items test recall or routine calculation.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-197","question":"At the end of a maths lesson, each child writes on a slip one thing she learnt and one question she still has, and hands it to the teacher on the way out. The teacher uses the slips to plan the next lesson. This practice is:","options":["A summative assessment at the end of the unit","A norm-referenced test comparing children","An exit slip used for formative assessment","A diagnostic test of general intelligence"],"answer":2,"explanation":"Exit slips give quick evidence of what children understood and where they are stuck, which the teacher uses to adjust teaching, the defining use of formative assessment.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-198","question":"In a Class 5 class of mixed abilities, which task is best suited to engage all learners in mathematics?","options":["A worksheet of 30 identical sums for everyone to finish","A low-floor, high-ceiling task, such as making rectangles from 24 tiles","Separate worksheets for ‘weak’ and ‘bright’ students with no shared work","A speed test of multiplication tables for the whole class"],"answer":1,"explanation":"Low-floor, high-ceiling tasks let every child start easily and allow able learners to go much deeper (all factor pairs, patterns in perimeter), supporting inclusion without labelling.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-199","question":"Many Class 7 students believe that ‘plants breathe in carbon dioxide in the day and respire only at night’. Which statement should the teacher help them reach?","options":["Plants photosynthesise only at night, when it is cool","Plants do not respire at all, they only photosynthesise","The students are right: plants respire only after dark","Plants respire day and night; in light, photosynthesis is faster"],"answer":3,"explanation":"Respiration goes on continuously in all living cells; in daylight it is masked by faster photosynthesis. The misconception confuses net gas exchange with the processes themselves.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-200","question":"A Class 6 student explains that we see a book because ‘light goes out from our eyes to the book’. Which activity best challenges this idea?","options":["Reading and copying the definition of reflection of light","Telling the student that the idea is ancient and wrong","Looking at objects in a totally dark room with eyes open","Drawing the eye and labelling its parts correctly"],"answer":2,"explanation":"If eyes sent out light, we could see in total darkness. The experience leads to the idea that light from a source is reflected by objects into our eyes.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-201","question":"Which school practice best develops children’s concern for the environment, as intended in EVS?","options":["A school garden, waste segregation and tracking water use","Children copy a list of ‘do’s and don’ts’ for the environment","Children write an essay on pollution from a guidebook","Children memorise the names of environmental laws"],"answer":0,"explanation":"Attitudes develop through participation and reflection on real action; copying rules or memorising information rarely changes behaviour.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-202","question":"Class 5 children prepare a puppet show to explain the water cycle, writing the dialogue and making the puppets themselves. Under NEP 2020, this is an example of:","options":["Rote learning through repeated rehearsal of lines","Art-integrated learning, using an art form to learn a concept","Co-scholastic activity that is unrelated to the EVS concept itself","Summative assessment of the water cycle unit"],"answer":1,"explanation":"NEP 2020 recommends art-integrated education, using the arts as a medium for learning concepts across subjects, which also builds creativity and communication.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-203","question":"Which practice best reflects the play-based and toy-based pedagogy that NEP 2020 recommends for the foundational stage?","options":["Daily worksheets of letter and number writing for regular practice","Long lectures followed by question-answer sessions","Learning counting and sorting with local toys, games and puzzles","Homework with copying of textbook pages each evening"],"answer":2,"explanation":"For ages 3–8 NEP 2020 favours flexible, play-, toy- and activity-based learning in which concepts grow through hands-on exploration and talk.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-204","question":"Why does NCF 2005 stress oral language development in the early grades before and alongside reading and writing?","options":["Because reading and writing should not be taught before Class 3","Because oral work keeps children busy and the class orderly","Because oral language is easier to assess than written work","Because spoken vocabulary and listening are the base for literacy"],"answer":3,"explanation":"Children understand in print what they already understand in speech; talk, stories and discussion build the vocabulary and comprehension that literacy depends on.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-205","question":"A Class 7 teacher regularly reads aloud chapters from a novel that is somewhat above her students’ independent reading level. The main purpose of this practice is to:","options":["Model rich language and fluent reading, and motivate reading","Test their spelling of the new words in the novel","Replace the need for students to read independently","Fill time at the end of the day when the regular lessons are over"],"answer":0,"explanation":"Read-alouds model fluency and expression and give access to vocabulary and ideas beyond what children can yet read alone, building interest in reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-206","question":"A Class 3 child asks, ‘Why does the moon change its shape?’ The teacher is not sure of the answer. The most appropriate response is:","options":["‘That is not in our syllabus, so focus on the lesson.’","‘You will learn it in higher classes, when you are a little older.’","‘It is God’s wish, and we should not question it.’","‘I am not sure. Let us watch the moon each night and find out.’"],"answer":3,"explanation":"Valuing questions, admitting uncertainty and investigating together models a scientific attitude and encourages children’s curiosity.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-207","question":"Class 4 children count and record the kinds of trees around the school in a table and then make a simple bar graph. Which statement best describes the pedagogy?","options":["It is purely an EVS activity unrelated to mathematics","It integrates EVS and mathematics through real data handling","It is mainly a handwriting and table-drawing exercise","It should be done only after children learn graphs formally"],"answer":1,"explanation":"Collecting real data about their environment and representing it links EVS content with data handling, giving meaning to both.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-208","question":"During a Class 8 practical on preparing a slide of onion peel, which tool would best assess students’ practical skills?","options":["A multiple-choice test on the parts of a plant cell","An essay on the history and parts of the microscope","An observation checklist used while students do the practical","Asking students to copy the onion-peel diagram from the book"],"answer":2,"explanation":"Practical skills are best judged as they are performed; a checklist of key steps makes such observation systematic. Written tests check knowledge about the practical, not the skill.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-209","question":"When asked to draw a scientist, most children in a class draw an old man in a white coat. The teacher’s most suitable follow-up is to:","options":["Accept it, since most scientists are men anyway","Ignore the drawings, as they are not part of the prescribed syllabus","Ask only the girls to draw a woman scientist instead","Share stories of diverse scientists and discuss who can be one"],"answer":3,"explanation":"‘Draw-a-scientist’ reveals stereotypes; showing diverse role models helps all children, especially girls, see science as something they can do.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-210","question":"Class 5 students who read stories easily struggle with an EVS text explaining how the monsoon causes floods. The most useful support is to:","options":["Teach cause–effect text structure using a graphic organiser","Tell them to read the text three more times until it is clear","Replace the text with a story on the same topic","Ask them to memorise the paragraph for the test"],"answer":0,"explanation":"Expository texts are organised differently from stories; explicitly teaching text structures with graphic organisers improves comprehension of informational writing.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-211","question":"A Class 2 teacher shows ‘5 − 3’ with five beads, removing three, and later a child is puzzled by ‘Raju has 5 marbles and Sita has 3. How many more does Raju have?’ The teacher should realise that:","options":["The child cannot subtract and needs more drill","Subtraction also means comparing, not only taking away","The comparison problem is too hard for Class 2 and should be removed","Beads should never be used for teaching subtraction"],"answer":1,"explanation":"Take-away, comparison (difference) and missing-addend situations all use subtraction; children who meet only take-away often cannot recognise the others.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-212","question":"Which of these is the strongest reason for using a number line when teaching addition of fractions such as 1/4 + 1/2?","options":["It avoids the need for a common denominator when adding","It is easier and quicker to draw than circles or rectangular strips","It shows fractions as numbers with size, so sums can be judged","It is what the textbook uses, so it must be followed"],"answer":2,"explanation":"Area models present fractions as parts of shapes; the number line shows them as numbers on a continuum, supporting estimation and reasoning about the size of sums.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-213","question":"How many of the following match the NCF 2005 recommendations for assessment in mathematics? I. Assess the processes children use, not only the final answer. II. Use mainly speed tests of procedures. III. Include tasks that ask children to explain and justify. IV. Use assessment to understand children’s thinking and plan teaching.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, III and IV are recommended. NCF 2005 criticises assessment that rewards only speed and memorised procedures.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-214","question":"Assertion (A): In the primary classes, children should be allowed to solve word problems using drawings and their own methods before formal symbols are required. Reason (R): Representing a situation in their own way helps children understand the problem and connect it later to standard notation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Children’s own representations (drawings, objects, informal notation) build understanding of the structure of a problem, which then gives meaning to formal symbols.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-215","question":"A Class 8 science teacher wants students to understand how a hypothesis differs from a guess. Which task serves this best?","options":["Writing and learning the definition of a hypothesis","Reading about famous inventions and their inventors","Framing a testable ‘if…then’ statement and designing a fair test","Memorising the steps of the scientific method in the correct order"],"answer":2,"explanation":"A hypothesis is a testable, reasoned prediction about a relationship between variables; framing one and planning how to test it shows the difference from a mere guess.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-216","question":"Which of the following is the best example of a ‘higher-order’ EVS question for Class 5 on the topic of animals?","options":["‘Name three animals that live in water, like the fish and the crab.’","‘Which animal is known as the ship of the desert?’","‘How many legs does an insect such as an ant have?’","‘If a pond’s frogs vanished, what might happen to its insects?’"],"answer":3,"explanation":"Predicting the effect of a change on a food web requires analysis and reasoning about relationships, unlike recall questions.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-217","question":"A teacher asks Class 6 students to estimate the number of beans in a jar before counting them, and then discuss how close each estimate was and how they made it. The main value of this activity is that it:","options":["Builds estimation strategies and number sense, like sampling","Teaches exact and careful counting of large sets","Is a time-filler with no real mathematical value","Helps the teacher find the fastest and most accurate counter"],"answer":0,"explanation":"Estimating and comparing strategies (counting a layer and multiplying, for example) builds number sense and reasoning about quantity that exact calculation alone does not.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-218","question":"How many of these statements about the Van Hiele model are correct? I. The levels are sequential, so a learner cannot reach a level without passing through the earlier ones. II. Progress from one level to the next depends more on instruction and experience than on age. III. If a teacher teaches at a level above the learners’, they may only memorise without understanding. IV. All children reach the deduction level automatically by the age of 12.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III reflect the Van Hieles’ view. Advancement is not automatic with age, so IV is false; many adults never reach formal deduction.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-219","question":"Assertion (A): Children who are taught the long-division algorithm as a set of steps, without understanding, often make errors such as leaving out zeros in the quotient. Reason (R): Standard algorithms are efficient methods for calculation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are true, but efficiency does not explain the errors; they arise because the steps are followed without understanding of place value and of what each step means.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-220","question":"A Class 3 child writes 7 × 0 = 7. Which approach best helps the child understand the correct answer?","options":["Telling the child the rule ‘anything times zero is zero’ to remember","Asking the child to write the zero table ten times over","Asking the child to check the answer on a calculator","Using a story: ‘7 plates with no laddoos on each; how many in all?’"],"answer":3,"explanation":"Seeing 7 × 0 as 7 groups of nothing (0 + 0 + … + 0) shows why the product is 0; the error often comes from treating ×0 like +0.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-221","question":"A Class 5 child writes 0.5 + 0.25 = 0.30. What has the child most likely done?","options":["Added 5 + 25 as whole numbers, ignoring place value; correct sum 0.75","Added correctly but forgot to carry; the correct sum is 0.80","Subtracted instead of adding the two decimals; the correct sum is 0.25","Misread 0.25 as 0.025 while adding; the correct sum is 0.525"],"answer":0,"explanation":"0.5 is 5 tenths, which is 50 hundredths; 50 + 25 = 75 hundredths = 0.75. Money (₹0.50 + ₹0.25) or a hundred-square makes the place values visible.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-222","question":"A Class 2 child insists that a large balloon must be heavier than a small stone. The best way to address this is to:","options":["Tell the child that size and weight are not the same thing","Let her compare them on a simple balance and discuss it","Ask the child to draw both objects and label them","Explain the scientific meaning of mass and weight"],"answer":1,"explanation":"Young children often judge weight by size; direct comparison on a balance gives evidence that challenges the idea and builds the concept of weight.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-223","question":"A Class 6 student says that any arrangement of six joined squares can be folded into a cube. The best teaching response is to:","options":["Tell the student that only some arrangements work and give the list","Show a finished cube and move on to its properties","Let students predict which six-square nets fold into a cube, then test","Ask students to memorise the faces, edges and vertices of a cube"],"answer":2,"explanation":"Predicting and testing nets develops spatial visualisation and reasoning; students discover that only some arrangements (11 in all) fold into a cube and can explain why others overlap.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-224","question":"A child says, ‘Maths makes sense to me. If I keep trying, I can work out problems.’ Among the strands of mathematical proficiency (conceptual understanding, procedural fluency, strategic competence, adaptive reasoning and productive disposition), this mainly reflects:","options":["Procedural fluency","Strategic competence","Adaptive reasoning","Productive disposition"],"answer":3,"explanation":"Productive disposition is seeing mathematics as sensible and worthwhile and believing in one’s own effort; it supports and is supported by the other strands.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-225","question":"A teacher takes a common wrong solution from the class test, removes the name, puts it on the board and asks students to find and explain the mistake. The main value of this practice is that it:","options":["Uses a common error as a resource for analysing reasoning","Embarrasses students who make mistakes so they are careful","Saves the teacher from correcting every student’s copy","Shows students which answers will lose marks in the exam"],"answer":0,"explanation":"NCF 2005 urges teachers to treat errors as windows into thinking; analysing an anonymous error is safe and makes the misconception explicit for everyone.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-226","question":"A Class 4 teacher plans a ‘water’ theme in which children sing songs about rain in language class, measure rainfall in mathematics, and study water sources in EVS. This approach is called:","options":["The subject-centred approach","The thematic (integrated) approach","The lecture method","The project method in its original form"],"answer":1,"explanation":"A thematic approach organises learning across subjects around one theme, helping children see knowledge as connected rather than in separate compartments.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-227","question":"NCERT’s Learning Outcomes for the elementary stage (2017) for EVS are best described as:","options":["A list of chapters and topics to be completed in each class","A set of questions to be asked in the final examination","Process-based statements of what children should be able to do","Guidelines on school infrastructure and teacher numbers"],"answer":2,"explanation":"Learning outcomes describe what children should be able to do (e.g. ‘identifies simple features of animals’, ‘records observations’), guiding teaching and assessment rather than listing content.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-228","question":"A Class 3 child says a seed is ‘non-living, because it does not move or eat’. Which activity best challenges this idea?","options":["Telling the child firmly that seeds are living things","Showing a picture of a big tree grown from a seed","Asking the child to memorise the seven features of living things","Soaking some seeds, keeping others dry, and watching for a week"],"answer":3,"explanation":"Watching soaked seeds swell and germinate shows that a seed holds a living embryo that grows under suitable conditions, giving evidence instead of a statement.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-229","question":"A Class 6 student predicts that a magnet will attract ‘all metals’. The best activity to test this is to let students:","options":["Test a steel spoon, aluminium foil, copper wire and brass key","Read the textbook definition of magnetic materials aloud in class","Watch the teacher pick up iron nails with a magnet","Memorise a list of magnetic materials from the book"],"answer":0,"explanation":"Testing several metals shows that only some (iron, steel, nickel, cobalt) are attracted, while aluminium, copper and brass are not, so students revise the overgeneralisation from evidence.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-230","question":"In an EVS lesson on local self-government, Class 5 children role-play a gram sabha meeting where villagers discuss a broken hand pump. The main learning purpose is to help children:","options":["Memorise the names and duties of panchayat officials","See how people take part in decisions about common resources","Practise acting for the school’s annual day function","Learn that only elected members are allowed to speak in a meeting"],"answer":1,"explanation":"Role-play makes democratic processes concrete and lets children experience participation, negotiation and civic responsibility.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-231","question":"Assertion (A): NCF 2005 treats the multilingual nature of Indian classrooms as a resource for learning. Reason (R): Research links bilingual proficiency with cognitive flexibility, greater awareness of language, and good academic achievement.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCF 2005 cites research associating bilingualism with cognitive growth and scholastic achievement, which is why it urges teachers to use children’s languages as a resource.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-232","question":"Before reading a story titled ‘The Lost Kite’, a teacher shows the cover picture and asks, ‘What do you think will happen in this story?’ This is an example of a:","options":["While-reading comprehension check on the plot","Post-reading evaluation activity on the story","Pre-reading activity to activate prior knowledge","Grammar exercise based on the title"],"answer":2,"explanation":"Predicting from the title and pictures before reading arouses interest, activates what children know and gives them a purpose for reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-233","question":"Match each writing activity with the stage of the process approach it belongs to: 1. Drawing a mind-map of ideas 2. Writing a first version quickly without worrying about errors 3. Changing the order of ideas after peer feedback 4. Correcting spelling and punctuation before display; a. Revising b. Editing c. Pre-writing d. Drafting","options":["1-c, 2-a, 3-d, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a","1-c, 2-d, 3-a, 4-b"],"answer":3,"explanation":"Planning ideas is pre-writing, the first version is drafting, changing content and organisation is revising, and correcting surface errors is editing.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-234","question":"Which approach to spelling is most effective for Class 3 children?","options":["Learning a list of 20 unrelated words by heart every week for a test","Writing each misspelt word 50 times as a correction","Exploring word families (cat, hat, mat) and children’s own writing","Avoiding any attention to spelling until Class 5 or later"],"answer":2,"explanation":"Spelling develops through noticing patterns and meaningful use; rote lists and punitive repetition rarely transfer to children’s actual writing.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-235","question":"To assess the listening comprehension of Class 1 children, a teacher reads a short story aloud and asks them to put four picture cards from the story in order. Why is this a suitable task?","options":["It tests handwriting and drawing along with listening","It is quicker and easier to mark than an oral test","It shows which children can read the words on the cards","It tests what was heard without needing reading or writing"],"answer":3,"explanation":"A valid listening test should not be contaminated by other skills; sequencing pictures lets young children show comprehension directly.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-236","question":"Regular use of short dramas and dialogues in a Class 4 English class mainly helps children to:","options":["Memorise grammar rules through repeated lines","Use language in meaningful situations, building spoken fluency","Improve their handwriting by copying the scripts","Prepare mainly for written examinations and class tests in English"],"answer":1,"explanation":"Drama provides context, purpose and emotion for language use, lowering anxiety and developing spoken fluency.","difficulty":"moderate","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-237","question":"A child who speaks a regional dialect at home is laughed at by classmates for ‘speaking wrongly’. The most appropriate response of a language teacher is to:","options":["Explain that all dialects are rule-governed and value the child’s speech","Tell the child firmly to stop using the dialect anywhere in school from now on","Correct the child’s speech in front of the class each time","Ignore the incident, as children will settle it themselves"],"answer":0,"explanation":"Linguistically, dialects are systematic, not ‘wrong’; respecting them protects children’s identity and confidence, while the standard form can be added for formal use.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-238","question":"A teacher writes ‘happy, unhappy, happiness, happily’ on the board and asks children to find other words that change in the same way. This activity mainly develops:","options":["Phonemic awareness of sounds in spoken words","Handwriting and copying of new words from the board","Morphological awareness of how word parts build words","Listening skill through attention to the teacher"],"answer":2,"explanation":"Knowing how word parts combine helps children work out the meanings of many new words, a strong support for vocabulary and reading.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-239","question":"Kenneth Goodman described reading as a ‘psycholinguistic guessing game’. This view implies that skilled readers:","options":["Read every letter of every word in strict order, left to right","Predict meaning and sample only as much print as they need","Read mainly by memorising whole texts and pages","Depend only on phonics rules to decode each word"],"answer":1,"explanation":"Goodman’s top-down view sees reading as an active process of predicting, sampling and confirming meaning, in contrast to a purely letter-by-letter (bottom-up) process.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-240","question":"Which question asked by a teacher in an English class is a ‘referential’ question rather than a ‘display’ question?","options":["‘What is the past tense of “go” in this sentence?’","‘Who wrote this story that we just read in class?’","‘How many characters are there in the story that we just read?’","‘What would you have done if you were in the boy’s place?’"],"answer":3,"explanation":"Display questions ask for answers the teacher already knows, to check knowledge; referential questions seek genuine information or opinion and lead to more authentic communication.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-241","question":"Which practice is most in line with NEP 2020’s guidance on languages in the classroom?","options":["Punishing children for speaking their home language in school","Using only English textbooks from the foundational stage onwards","Using bilingual materials where the home language differs from the medium","Teaching the home language only as an optional subject after Class 8 or later"],"answer":2,"explanation":"NEP 2020 encourages teachers to use a bilingual approach, including bilingual materials, for students whose home language differs from the medium of instruction.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-242","question":"Class 6 students measure the distance around and across several round objects (bangles, plates, lids) and find that the ratio is close to 3.1 every time. The main value of this activity is that it:","options":["Proves the exact value of π to two decimal places","Shows that measurement of round objects is always inaccurate","Replaces the need to learn the circumference formula","Lets students discover π as a constant ratio before the formula"],"answer":3,"explanation":"Measuring many circles shows a constant ratio, making π a discovered relationship rather than a memorised number; measurement cannot prove its exact value.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-243","question":"A Class 6 student says 6 ÷ 1/2 = 3. Which question best helps the student make sense of the correct answer?","options":["‘How many half-rotis can you make from 6 rotis?’","‘What is half of 6?’","‘What is the rule for dividing a number by a fraction?’","‘What is 6 × 2?’"],"answer":0,"explanation":"The student has found half of 6. Interpreting division as ‘how many halves fit into 6’ shows that the answer is 12 and gives meaning to the invert-and-multiply rule.","difficulty":"hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-244","question":"A shopkeeper gives change for a ₹100 note on a ₹63 purchase by saying ‘63… 64, 65, 70, 100’ while handing over ₹1, ₹1, ₹5 and ₹30. Using this method in class mainly helps children to understand:","options":["Multiplication of money in rupees and paise","Subtraction by counting up from 63 to 100","Division of the money into equal shares","Rounding amounts to the nearest ten rupees"],"answer":1,"explanation":"Counting up from the smaller number to the larger is a powerful informal strategy for subtraction (100 − 63 = 37) that connects school maths to everyday practice.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-245","question":"A Class 5 child says that when a wet cloth dries, ‘the water just goes into the cloth and disappears’. Which activity best helps the child build the idea of evaporation?","options":["Telling the child that water becomes vapour in the sun","Showing and explaining a diagram of the water cycle","Comparing a covered and an open plate of water left in the sun","Asking the child to memorise the definition of evaporation"],"answer":2,"explanation":"The open plate loses water while the covered one does not, showing that the water goes into the air rather than vanishing. A follow-up with droplets forming on a cold glass shows the vapour is still there. Evidence builds the idea that water changes state.","difficulty":"very-hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-246","question":"A teacher uses phonics drills to build word recognition and also asks children to predict words from the story context and pictures. Which statement best describes this?","options":["It is purely a bottom-up approach to reading, from letters up","It is purely a top-down approach to reading, from meaning down","It mixes up two incompatible methods and will confuse children","An interactive model, combining decoding with use of context"],"answer":3,"explanation":"Interactive models hold that readers use letter–sound information and contextual knowledge together; good teaching develops both.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-247","question":"A Class 8 student writes (a + b)² = a² + b². Which activity best helps the student see why this is wrong?","options":["Drawing a square of side (a + b) split into a², b² and two ab parts","Making the student memorise the identity by writing it out many times","Telling the student that brackets cannot be removed","Giving ten more expansions to practise the same way"],"answer":0,"explanation":"The area model shows the two missing ab rectangles, and the numerical check (5² = 25, but 9 + 4 = 13) confirms it, building understanding instead of rote recall.","difficulty":"very-hard","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-248","question":"In an EVS lesson on houses, a child from a migrant family says her family has lived in a tent, a hut and now a room in the city. The teacher should:","options":["Move on quickly to avoid embarrassing the child","Invite her to share it as an example of how shelters change","Tell the class that tents are not real or proper houses for families","Ask her to describe the house in the textbook instead"],"answer":1,"explanation":"Children’s varied lives are rich resources for EVS; valuing them builds inclusion and helps all children understand the links between shelter, livelihood and migration.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-249","question":"Class 4 children find it hard to read maps. The teacher asks them to draw how a pencil box, a bottle and a book on the desk look from directly above. The main purpose of this activity is to develop:","options":["Drawing and shading skills for the weekly art period in school","Knowledge of standard map symbols and colours","The idea of a top (bird’s-eye) view, the basis of maps","Measurement of length of objects on the desk"],"answer":2,"explanation":"Maps show places as seen from above; drawing top views of familiar objects helps children make the shift from side views to the plan view that maps use.","difficulty":"hard","source":"CTET · State TETs"},
  {"id":"cdp-pedagogy-subjects-250","question":"A Class 7 student with a locomotor disability uses a wheelchair. Which arrangement best supports her in science practicals?","options":["Letting her only watch while others perform the experiments","An accessible table, apparatus within reach and a hands-on role","Asking her to write the record while others do the practical","Exempting her from practical work and its assessment"],"answer":1,"explanation":"Reasonable accommodation, such as accessible furniture and placement of apparatus, lets her take part fully; being only an observer or recorder denies her the practical learning.","difficulty":"moderate","source":"CTET Paper II · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-251","question":"A Class 3 teacher in a village in western Rajasthan opens the EVS theme ‘Water’ by asking: ‘Where does the water in your home come from? Who brings it? How far do they walk?’ The strongest pedagogical justification for this opening is that it:","options":["quickly checks prior knowledge so that children can be ranked by ability before the unit begins","shows that the textbook can be set aside, since it is not written for rural children","starts from children’s lived experience and links the natural and social sides of water","fills the first period with talk until children are ready for the textbook definitions"],"answer":2,"explanation":"NCF 2005 asks EVS to begin from the child’s own context; the questions tie a natural resource to who labours for it and how access differs. Ranking, replacing the textbook or delaying ‘definitions’ all misread the intent.","difficulty":"moderate","source":"CTET Paper 1 · REET Level 1"},
  {"id":"cdp-pedagogy-subjects-252","question":"Consider these statements about EVS in Classes I and II as envisaged in NCF 2005: I. A separate EVS textbook is prescribed from Class I. II. Environmental concerns are woven into language and mathematics. III. Children engage with their surroundings mainly through activities, talk and stories. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III all"],"answer":1,"explanation":"In Classes I–II there is no separate EVS book; its concerns are integrated with language and mathematics and approached through activities and conversation. Statement I is the trap.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-253","question":"Assertion (A): The NCERT EVS syllabus for Classes III–V is organised around themes rather than around chapters of science and social science. Reason (R): Young children perceive their surroundings as a whole and do not divide experience into disciplinary compartments. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The thematic organisation (Family and Friends, Food, Shelter, Water, Travel, Things We Make and Do) exists precisely because children experience the world holistically, so R explains A.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-254","question":"Which of the following is NOT an objective of primary EVS as laid down in the NCERT syllabus that followed NCF 2005?","options":["To help children relate the natural, social and cultural environment to one another","To develop awareness of environmental issues through the child’s own context","To build skills such as observing, classifying and inferring through hands-on exploration","To give children an early, formal introduction to physics, chemistry and biology"],"answer":3,"explanation":"Primary EVS deliberately avoids splitting knowledge into formal disciplines; the other three are stated objectives. Early disciplinary teaching is the very approach NCF 2005 moved away from.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-255","question":"A senior teacher tells a trainee, ‘EVS in Class 4 is just science with a bit of geography added.’ Which response best corrects this view?","options":["EVS is really a social studies subject, since most of its chapters are about families, people and the work they do","The view is right, because the EVS books contain far more science content than history, and geography fills the rest","EVS integrates science, social science and environmental education, and aims at sensitivity and values in the child’s context","EVS is mainly about pollution and its control, so it sits closer to environmental science than to either science or geography"],"answer":2,"explanation":"EVS is not a sum of two subjects; it weaves several areas into themes and aims at awareness, concern and skills. Each distractor reduces it to a single discipline or a single issue.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-256","question":"In the NCERT EVS framework, ‘Animals’ and ‘Plants’ appear as sub-themes under ‘Family and Friends’. The best explanation for this placement is that it:","options":["follows the legal status of pets as members of a household, so animals are taught as relatives of the family","shows plants and animals as part of the child’s web of relationships, building sensitivity, not mere classification","signals that biology is not really part of EVS, so plants and animals are treated only as social topics","keeps difficult biological content such as classification and life processes out of Classes III–V altogether, by design"],"answer":1,"explanation":"Placing plants and animals beside relationships and work and play signals that children should relate to them with care and curiosity. Biology is present, but approached through relationship, not taxonomy.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-257","question":"A Class 4 teacher in a hill district of Uttarakhand is starting the theme ‘Travel’. Which opening is most appropriate?","options":["Showing a video of metro and bullet trains first, so that children see the most modern transport of the country","Listing land, water and air transport from the textbook for children to copy and memorise before any discussion","Defining transport and asking children to sort pictures of vehicles into land, water and air groups","Asking children how their families reach the market, hospital and school, and what difficulties they face"],"answer":3,"explanation":"Starting from local journeys and their difficulties connects travel to geography, access and livelihood in the child’s own world. Videos of distant transport, memorised lists and definitions begin far from experience.","difficulty":"moderate","source":"CTET Paper 1 · UKTET"},
  {"id":"cdp-pedagogy-subjects-258","question":"Which of the following practices goes AGAINST the thematic approach in EVS?","options":["Teaching ‘Water’ in one science period on its states and a separate, unconnected period on scarcity","Exploring how water is used at home, in the fields and during festivals in the children’s own village","Tracing how water reaches the village, who carries it and who decides who gets how much of it","Drawing how the family’s water use changes between the dry summer months and the monsoon season"],"answer":0,"explanation":"A theme loses its point if it is split back into disconnected disciplinary periods. The other three keep the natural and social aspects of water together.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-259","question":"‘Water’ appears in the NCERT EVS books of Classes III, IV and V, moving from water in daily life to its sources, and then to access, scarcity and conservation. This organisation best reflects:","options":["drill through repetition of the same content in the same way each year","sequencing from abstract ideas in Class III to concrete examples in Class V","a spiral curriculum in which a theme is revisited at greater depth","a strictly subject-centred, linear sequence that never returns to a topic"],"answer":2,"explanation":"Revisiting the same theme with increasing complexity is Bruner’s spiral idea. It is not mere repetition, and it moves from concrete to abstract, not the reverse.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-260","question":"A Class 5 teacher in a coastal village of Kerala begins a lesson on deserts by asking children to compare their own houses, seasons and water with photographs of a family in Jaisalmer. Which principle is she mainly using?","options":["From abstract to concrete, by starting with an unseen place","From the known to the unknown, by contrast with the familiar","From the whole to its parts, by treating India as one region","From rote recall to understanding, by testing desert facts first"],"answer":1,"explanation":"The familiar coastal life is the anchor against which the unfamiliar desert is understood. ‘Abstract to concrete’ reverses the accepted maxim.","difficulty":"moderate","source":"CTET Paper 1 · Kerala TET"},
  {"id":"cdp-pedagogy-subjects-261","question":"Which question by a teacher during the theme ‘Food’ is most in the spirit of the NCERT EVS books?","options":["Define a balanced diet and list all the nutrients it must contain in the right amounts.","Name five foods that give us protein and five that give us carbohydrates.","Write the full form of ORS and the steps for preparing it as given in the chapter.","In your family, who decides what is cooked? Has it always been the same person? Why?"],"answer":3,"explanation":"The question draws on the child’s home, has no single textbook answer and opens up issues of roles and gender. The others call for recall of definitions or lists.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-262","question":"Match each NCERT EVS theme with the classroom example that best belongs to it: 1. Shelter 2. Things We Make and Do 3. Travel 4. Water. a. Why houses in parts of Assam stand on bamboo stilts. b. How a potter shapes clay on a wheel. c. A family’s train journey from Kolkata to Chennai. d. Who built the old village stepwell and who was allowed to use it.","options":["1-a, 2-c, 3-b, 4-d","1-d, 2-b, 3-c, 4-a","1-a, 2-b, 3-c, 4-d","1-b, 2-a, 3-c, 4-d"],"answer":2,"explanation":"Stilt houses answer to climate (Shelter), pottery is a craft (Things We Make and Do), the journey is Travel and the stepwell raises questions of water and access (Water).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-263","question":"Assertion (A): EVS is not taught as a separate subject with its own textbook in Classes I and II. Reason (R): Children of this age cannot learn anything meaningful about their environment. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true, but the reason is that young children learn about their surroundings best through language, mathematics and activity, not that they cannot learn about it. R is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-264","question":"Which statement about the EVS textbook is consistent with NCF 2005?","options":["The textbook is one resource among many; children’s experience, the local environment and the community are others","The textbook is the final authority and must be completed page by page, since examinations are set from it","Teachers should not bring in local examples that are not printed in the textbook, as they may confuse children","Every question in the textbook should have a single correct answer printed in the chapter, so that marking stays fair"],"answer":0,"explanation":"NCF 2005 asks teachers to move beyond the textbook and treat it as one resource among many. The other options describe the textbook-centred culture it criticised.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-265","question":"A Class 3 teacher asks, ‘Which animals live around your village? Which have you seen up close? Which ones do people fear?’ She writes every answer on a chart, including local names, without correcting them. The main purpose of this is to:","options":["delay scientific names until Class 6, because using them early confuses young learners","value children’s knowledge and local vocabulary as a base for further exploration","identify which children come from farming families so that they can be grouped together","replace the need for first-hand observation, since children have already seen the animals"],"answer":1,"explanation":"Recording local names and experiences without judgement legitimises children’s knowledge and gives the teacher a starting point. It neither forbids scientific names nor replaces observation.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-266","question":"Which of the following fall within the scope of primary EVS as envisaged by NCF 2005? I. Caste-based discrimination in access to a village well. II. Simple estimation and measurement. III. Memorising chemical formulae of common substances. IV. Local crafts and occupations.","options":["I and II only","II and IV only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"EVS includes social issues of equity, process skills like estimating and measuring, and local work and crafts. Chemical formulae are outside the primary stage and against the spirit of EVS.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-267","question":"During a Class 4 discussion on festival food, a child says, ‘People who eat meat are dirty.’ The most appropriate response of the teacher is to:","options":["ignore the remark so that the discussion does not turn controversial and hurt the feelings of the other children present","ask the child to apologise to the class at once and then move on quickly to the next topic in the chapter","open a discussion on how food habits depend on region, culture and availability, and why no habit makes anyone dirty","agree in part, saying vegetarian food is healthier, so the child’s remark contains some truth worth keeping"],"answer":2,"explanation":"EVS aims at respect for diversity, so the prejudice must be examined, not silenced or endorsed. A forced apology closes thinking without changing the belief.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-268","question":"Many chapters of the NCERT EVS books are written as stories, letters, diary entries and interviews rather than as descriptive information. The main reason is to:","options":["connect with children’s experience, carry the social context and invite them to think, not to supply facts to memorise","improve reading speed and fluency so that children score better in their language tests and reading assessments","follow an RTE rule that bans purely informational text in primary classes and requires stories in every single subject","reduce the number of pages in each book, since stories pack more information into less space than descriptions"],"answer":0,"explanation":"Narratives place ideas within people’s lives and prompt children to relate, question and express. There is no RTE ban on informational text; reading speed and page count are not the aim.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-269","question":"A teacher in a tribal area of Jharkhand finds that the EVS chapter on farming describes crops that are not grown locally. The best course of action is to:","options":["teach the chapter exactly as it is written, since the examinations are based only on the textbook content","skip the chapter entirely because its crops do not suit the children and will not interest them","ask children to memorise the textbook crops first and then the local crops as additional work","adapt the lesson to local crops, farming practices and children’s knowledge, comparing with the textbook"],"answer":3,"explanation":"Contextualising meets the same learning goals through what children know and adds a comparison. Skipping loses the goals; teaching unchanged or doubling the memory load misses the point of EVS.","difficulty":"hard","source":"CTET Paper 1 · JTET"},
  {"id":"cdp-pedagogy-subjects-270","question":"Which of the following is the best example of meaningful integration of EVS with mathematics in Class 4?","options":["Children solve textbook sums in which the names of animals and plants replace the usual numbers","Children measure a stick’s shadow at different times of day, record the lengths and compare them","Children count the pictures of animals printed in the EVS textbook and write the totals in a table","Children copy multiplication tables onto a large chart decorated with drawings of trees and birds"],"answer":1,"explanation":"Measuring and recording a real phenomenon uses mathematics to make sense of the environment. The others are cosmetic: EVS words or pictures are pasted onto routine maths.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-271","question":"Consider these statements about the NCERT EVS syllabus for Classes III–V: 1. Each sub-theme is opened up through ‘key questions’ rather than a list of content to be covered. 2. Definitions and technical terms are discouraged at this stage. 3. The experiences of children and their communities are treated as valid knowledge. Which are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 only"],"answer":2,"explanation":"The syllabus is laid out as key questions, key concepts, resources and activities; it avoids definitions and treats lived experience as knowledge. All three statements hold.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-272","question":"Which is the WEAKEST justification for teaching EVS through activities?","options":["Activities keep children busy, so the class stays quiet and disciplined","Activities let children build ideas through their own direct experience","Activities let children with different abilities take part in learning together","Activities develop process skills such as observing and predicting"],"answer":0,"explanation":"Activities are meant to drive thinking, not to manage behaviour; ‘busy work’ with no learning aim is a known misuse. The other three are genuine pedagogical reasons.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-273","question":"Assertion (A): EVS uses the child’s local environment as a major learning resource. Reason (R): The NCERT EVS books contain a large number of pictures. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both are true, but the use of the local environment rests on constructivism and contextual learning, not on the books having pictures.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-274","question":"Class 5 children of a fishing village in Odisha are studying ‘Travel’. The teacher invites fishermen parents to explain how they find their way at sea using wind, stars and birds. This mainly shows:","options":["the community being used as a learning resource and local knowledge being valued","a way to reduce the teacher’s workload by letting parents take the lesson","traditional belief being taught in place of scientific knowledge of navigation","early vocational training so that the children can later join the family trade in fishing"],"answer":0,"explanation":"Navigation by wind and stars is real, tested local knowledge, and bringing parents in links school with community. It is not a replacement for science, nor vocational training.","difficulty":"hard","source":"CTET Paper 1 · OTET"},
  {"id":"cdp-pedagogy-subjects-275","question":"A head teacher lists claims to show that her school follows an ‘integrated approach’ to EVS. Which claim actually reflects integration?","options":["EVS, Hindi and Mathematics are all taught by the same class teacher, so she can link them whenever she likes","The EVS period is combined with the art period to save time, and children draw whatever the chapter shows","Science and social science chapters are printed together in one EVS book, although each of them is still taught separately","A theme such as ‘Shelter’ is explored through materials, climate, the people who build houses and those with no home"],"answer":3,"explanation":"Integration is about ideas: one theme viewed through natural, social and ethical lenses. One teacher, merged periods or a combined binding do not integrate knowledge.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-276","question":"A Class VII social science teacher in Jaipur tells her students, 'This subject is only facts and dates, so learn the question bank by heart before the test.' Which position of NCF 2005 does her remark most directly contradict?","options":["Social science should build conceptual understanding and the ability to question social reality, not the memorising of facts","Social science should be merged into science in the upper primary classes so that it becomes more useful for careers","Social science should be taught only from the prescribed board textbook so that all schools stay uniform in content","Social science should mainly train students to obey rules and be loyal to the state, as good and dutiful citizens are expected to"],"answer":0,"explanation":"NCF 2005 wants social science to move from loading information to building concepts and a critical, questioning outlook. Obedience-centred 'civics' and textbook-only teaching are the very things the framework criticises.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-277","question":"Assertion (A): NCF 2005 recommends using the term 'political science' in place of 'civics' for the upper primary and secondary stages.\nReason (R): 'Civics' carried a colonial association with training loyal, obedient subjects, whereas the aim now is to prepare thinking citizens of a democracy.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The position paper argues that civics grew in the colonial period to stress obedience and loyalty; political science is meant to build an understanding of democratic institutions and the ability to question them. R gives the actual reason for A.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-278","question":"Which of the following statements reflect the NCF 2005 view of social science?\n1. Social science lays the foundation for an analytical and creative mindset.\n2. Because social science is non-utilitarian, it deserves less curriculum time than science.\n3. A gender perspective should run through the content of social science rather than sit in one chapter.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"NCF 2005 rejects the common belief that social science is 'non-utilitarian' and less important; it argues the subject builds analytical, creative thinking. It also asks for gender to be integrated across themes, so 1 and 3 are correct.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-279","question":"Before introducing the term 'market', a Class VII teacher in a Bihar town asks pupils to find out where a vegetable seller at the weekly haat buys her stock, how much she pays and what she earns in a day. This choice best reflects which approach recommended for economics?","options":["Replacing economic concepts with stories so that no formal economic theory is taught at this stage","Postponing all economic ideas to Class XI, when students are mature enough to handle abstract theory","Studying economic life from the point of view of ordinary people and their everyday experience","Training pupils to recite definitions of demand and supply accurately before they observe any market"],"answer":2,"explanation":"NCF 2005 asks that economics be approached from the perspective of people, such as the vendor, the farmer and the consumer, so that concepts grow out of lived experience. The concept is still taught; it simply begins from what children can observe.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-280","question":"For a Class VIII lesson on the Revolt of 1857, a teacher gives groups a British official's report, a petition written by a sepoy, and a song remembered in a village of the region. What is the main learning she intends?","options":["Students should conclude that since the accounts disagree, none of them can be trusted as evidence","Students should rely on the teacher to tell them which of the three accounts is the correct, official one","Students should cover more of the syllabus in less time by dividing the sources among the groups","Students should see that the past is reconstructed from varied sources reflecting different viewpoints"],"answer":3,"explanation":"Using several sources teaches that history is an interpretation built from evidence and that each source carries its author's position. The trap is relativism: disagreement among sources calls for weighing them, not rejecting all of them.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-281","question":"A Class VI history unit on the Mauryas in a Kendriya Vidyalaya covers only Ashoka's conquests, edicts and administration. A reviewer asks the teacher to add how farmers, crafts-people and traders lived and paid taxes. The reviewer's suggestion best addresses which concern of NCF 2005?","options":["History should be reduced to fewer chapters so that the syllabus becomes lighter","History must include the lives of ordinary people and not only rulers and wars","History should avoid ancient periods because the available sources are limited","History should be taught through dates arranged in a clear chronological chart"],"answer":1,"explanation":"NCF 2005 criticises history taught as a chronicle of kings and battles and asks that the everyday lives of common people, including peasants, artisans and women, be part of the story.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-282","question":"A teacher plans a four-week theme 'Water' for Class VIII: rainfall patterns (geography), stepwells of Gujarat (history), who decides on water supply in the city (political science) and the cost of buying water (economics). Which evaluation of this plan is the most accurate?","options":["It goes against NCF 2005, which wants every social science discipline taught in strict isolation from Class VI","It suits only primary EVS and is unsuitable once separate textbooks begin","It turns social science into science and should be shifted to the science period","It lets students see one issue through several disciplines, an interdisciplinary approach NCF 2005 supports"],"answer":3,"explanation":"NCF 2005 favours examining important issues such as water across disciplines while still keeping disciplinary perspectives. The plan does exactly this; nothing in the framework forbids themes after the primary stage.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-283","question":"While teaching secularism in Class VIII, Mr. Rawat notices some students voicing strong opinions about other communities. Which response is most in line with the normative role of social science described in NCF 2005?","options":["Tell students his own religious views clearly so that they know what the correct opinion is","Skip the chapter, because religion is too sensitive a subject to discuss in a classroom of mixed communities","Use real cases to help students reflect on equality, dignity and the constitutional idea of secularism","Ask students to memorise the textbook definition of secularism and reproduce it in the test"],"answer":2,"explanation":"Social science has a normative responsibility to help students engage with constitutional values, but through reflection and evidence, not preaching. Avoiding the topic or reducing it to a definition loses the very learning the chapter is meant for.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-284","question":"At a parent-teacher meeting in a Pune school, parents ask the Class IX teacher to cut social science homework because 'it will not help in any career'. Which reply is best grounded in NCF 2005?","options":["Social science builds the inquiry, analysis and judgement that every citizen and profession needs in a democracy","They are right, and the school will reduce social science periods to give more time to science and mathematics","Social science matters only because its marks count in the board examination total and affect the percentage","Social science is useful only for students who will later sit the civil services or other competitive examinations"],"answer":0,"explanation":"NCF 2005 names the belief that social science is non-utilitarian as a problem and argues that the subject builds critical, analytical capacities needed by all. Answers based only on marks or one career accept the narrow view instead of correcting it.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-285","question":"Assertion (A): Beginning a Class VI lesson on diversity by asking children to list the languages, foods and festivals of their own lane makes the idea more meaningful.\nReason (R): Children construct new understanding by linking it with what they already know and have experienced.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Starting from children's own surroundings makes an abstract idea concrete, and it works precisely because learners build knowledge on their prior experience, as constructivism holds. R therefore explains A.","difficulty":"moderate","source":"CTET Paper 2 · NVS · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-286","question":"Which of the following statements about NCF 2005 and social science are correct?\n1. Textbooks should give one authoritative interpretation so that children are not confused.\n2. Teachers should be free to bring in local examples and resources beyond the textbook.\n3. Children's experiences are a starting point but must be linked to wider concepts.\n4. Content should be cut down to essential facts that can be memorised easily.","options":["1, 2 and 3 only","2, 3 and 4 only","2 and 3 only","1 and 4 only"],"answer":2,"explanation":"NCF 2005 values multiple perspectives and local resources and wants experience linked to concepts. Statement 1 opposes its call for plural views, and statement 4 confuses 'reducing load' with reducing learning to memorised facts.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-287","question":"In a discussion on poverty, a Class IX student says, 'People are poor because they do not work hard.' What should the teacher do to best serve the aims of social science?","options":["Tell the student that the remark is rude and offensive, and move on quickly to the next topic","Accept it without discussion, since every opinion in social science is equally valid","Give a lecture on the official definition of the poverty line and how the government calculates it","Ask the class to examine data and case studies on wages, land, health and schooling to test it"],"answer":3,"explanation":"Social science aims to replace prejudice with reasoning based on evidence. Testing the claim against data about structural causes builds critical thinking; silencing or merely accepting the view does not change the misconception.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-288","question":"While teaching colonial forest laws in Class VIII, a teacher in Jharkhand includes oral accounts of how Adivasi families lost the right to collect forest produce. What is the main purpose of adding these voices?","options":["To show that one policy affected groups very differently and that history includes the experience of the marginalised","To prove that colonial rule brought no real change at all to the life of people living in forest areas","To replace the textbook chapter with local folklore, which children usually find more interesting than written history","To make the chapter shorter and easier for slower learners by telling it through simple family stories"],"answer":0,"explanation":"NCF 2005 asks that the perspectives of marginalised groups such as Adivasis, Dalits and women be part of social science. Their accounts show who gained and who lost from a policy, something an account from the rulers' side alone would hide.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-289","question":"Assertion (A): Two historians working with the same set of sources may reach different conclusions about an event.\nReason (R): Historical facts do not exist; history is only a matter of personal opinion.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Historians select and interpret evidence, so conclusions can differ. But interpretation is bound by evidence; it is not mere opinion, and facts such as dates and documents do exist. So A is true and R is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-290","question":"A Class VI geography teacher spends most periods on quizzes about state capitals and the longest rivers. Which change would best bring her teaching in line with the aims of geography in NCF 2005?","options":["Add more quizzes on state capitals and rivers so that students can remember even more names and facts","Have students study how people of a region adapt their houses, crops and work to its climate and land","Drop maps entirely, since map work mostly encourages rote learning of places and boundaries","Replace geography periods with general knowledge periods that cover a wider range of facts"],"answer":1,"explanation":"Geography in NCF 2005 is about the relation between people and their environment, studied from local to global. A list of names is information, not geographical understanding, while maps remain a central tool rather than something to drop.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-291","question":"An NCERT Social and Political Life chapter explains equality through the story of a man who is refused entry to a place because of his caste. Why do such textbooks use narratives of individual lives?","options":["Stories are easier to memorise than definitions, so students can reproduce them and improve board results","Narratives avoid the need to discuss constitutional provisions, which are too difficult for Class VII students","Narratives replace concepts, so students need not learn a formal meaning of equality at this stage at all","A real-life situation makes an abstract idea like equality concrete and lets children feel its human meaning"],"answer":3,"explanation":"Case studies and narratives anchor abstract political ideas in situations children can relate to, after which the concept and the relevant constitutional value are discussed. The story leads to the concept; it does not replace it.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-292","question":"Which of these questions best reflects the NCF 2005 idea of connecting social science with children's lives in a Class VI lesson on local government?","options":["List five functions of the gram panchayat given in the chapter, with an example of each","Define 'local self-government' in your own words and give its meaning in one line","Find out one problem your gram panchayat or ward office handled recently, and how","Write the year in which panchayats received constitutional status and the amendment number"],"answer":2,"explanation":"The investigative task links the concept to the child's own locality and requires inquiry. The other options test recall of textbook information or dates, even when phrased as 'in your own words'.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-293","question":"Two Class VIII teachers plan a lesson on citizenship. Teacher P stresses that good citizens pay taxes, obey laws and respect the flag. Teacher Q asks students why some colonies in their city get water daily while others get it twice a week, and what citizens could do about it. Which judgement fits NCF 2005 best?","options":["Teacher P, because obedience to laws and authority is the core aim of political science at this stage","Teacher Q, because it builds the ability to question social reality and to take part in democracy","Both are equally aligned, since NCF 2005 gives no preference between the two kinds of lesson","Neither, because social science should not take up problems from the students' own city or colony"],"answer":1,"explanation":"NCF 2005 wants learners who can critically examine social reality and participate in democracy, not merely obey. Teacher P's content is not wrong, but limiting citizenship to obedience is the old 'civics' view the framework moves away from.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-294","question":"Assertion (A): Social science uses systematic methods of inquiry such as gathering evidence, comparing cases and examining sources.\nReason (R): Social phenomena can always be tested through controlled laboratory experiments, just as in physics.","options":["Both A and R are true and R is the correct explanation of A","A is false but R is true","Both A and R are true but R is not the correct explanation of A","A is true but R is false"],"answer":3,"explanation":"Social sciences are rigorous in their own way through evidence, comparison and interpretation, but most social phenomena cannot be put through controlled experiments. So A is true and R is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-295","question":"Which of the following is NOT an aim of teaching social science according to the spirit of NCF 2005?","options":["Developing a critical understanding of society","Nurturing constitutional values such as justice, liberty and equality","Building the ability to question and investigate","Getting all students to hold the same opinion on political issues"],"answer":3,"explanation":"The framework values independent thinking and respect for multiple perspectives. Producing uniform opinions is indoctrination, which is the opposite of the critical, democratic aims it sets out.","difficulty":"moderate","source":"CTET Paper 2 · NVS · KVS"},
  {"id":"cdp-pedagogy-subjects-296","question":"In a Class VI lesson on 'family', the textbook shows a father, mother and two children. Sonu, whose family migrates every season to work at brick kilns, says, 'My family is not like this.' What should the teacher do?","options":["Use Sonu's experience to discuss the many forms families take and why some families move for work","Tell Sonu kindly that the textbook shows the correct and normal family that most children have","Ask Sonu to speak to the teacher after class so that the lesson for the others is not disturbed","Explain that migrant families are a topic for higher classes and will be taught in a later chapter"],"answer":0,"explanation":"NCF 2005 wants children's lives, especially those of marginalised children, to be treated as valid sources of knowledge. Sonu's experience widens the class's understanding and shows that a textbook image is one example, not a norm.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-297","question":"A Class X student asks, 'Why did the Non-Cooperation Movement mean different things to different groups?' The teacher replies by dictating four points to memorise. Which criticism of this response is the most accurate?","options":["It is correct, since dictated notes ensure that all students write the same answer in the board examination","It shuts down inquiry; groups could compare accounts of peasants, tribal people and urban traders to build the answer","It is wrong only because the dictated points may not match the exact wording given in the textbook chapter","It is wrong because Class X students should not be raising questions that go beyond what the prescribed chapter actually covers"],"answer":1,"explanation":"The student's question is an opening for inquiry into multiple perspectives. Comparing how different social groups understood the movement builds historical reasoning, whereas dictation turns an inquiry question into recall.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-298","question":"A teacher of Class VII in Kerala introduces climate by first asking how the monsoon affects paddy sowing and fishing in pupils' own village, and only then moves to world climate regions. Which maxim of teaching is she mainly following?","options":["From abstract to concrete and from the theory to the example","From the whole to its parts and the world to the village","From the known to the unknown and the local to the global","From analysis to synthesis and from rules to examples"],"answer":2,"explanation":"She starts from what children know in their own surroundings and moves outward to the wider world, the 'known to unknown' and 'local to global' progression NCF 2005 recommends for geography.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-299","question":"A school adds a separate chapter titled 'Women in Indian History' to its Class VIII syllabus and leaves every other chapter unchanged. Which critique is most in line with NCF 2005?","options":["The change is enough, since one dedicated chapter fully covers the gender requirement of the curriculum","Gender belongs in home science and should be removed from social science, where it only distracts from the main political story","Gender should be a lens across all themes, asking how women experienced work, law and change, not a one-chapter add-on","The topic should be avoided altogether because it may cause controversy among parents and the local community"],"answer":2,"explanation":"NCF 2005 asks for a gender perspective integrated across social science, not a single 'women' chapter beside an otherwise male-centred narrative. An add-on chapter keeps women at the margins of the main story.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-300","question":"Which of the following statements about the nature of social science are correct?\n1. It deals with human beings in society, so values and perspectives enter into it.\n2. Its concepts, such as democracy or market, are best learnt as fixed definitions.\n3. It helps students understand how society came to be what it is and how it can change.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Social science studies people in society, involves values and perspectives, and explains how society is shaped and can change. Treating its concepts as fixed definitions to memorise is the rote approach NCF 2005 criticises.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-301","question":"Consider the following statements about reading aloud to young children: 1. Choosing books with repetitive, predictable patterns helps children join in and anticipate words. 2. Showing the pictures and inviting children's talk interrupts the story and should be avoided. 3. Re-reading a favourite book several times can deepen understanding and vocabulary. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Predictable texts and repeated reading both support early readers. Talk about pictures is a core part of interactive read-aloud, so statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-302","question":"To make a Class 7 chapter 'easier', a textbook writer replaces 'Green plants make their food from carbon dioxide and water in the presence of sunlight' with 'Plants eat sunlight'. Judged against the NCF 2005 criteria for a science curriculum, this change most directly violates:","options":["Cognitive validity, because the new sentence is pitched below the learner's level","Content validity, because the simplification has made the science wrong","Process validity, because no experiment accompanies the statement","Environmental validity, because the plant is not shown in its local setting"],"answer":1,"explanation":"Content validity requires that simplification for the learner's level must not make the information incorrect; 'plants eat sunlight' is simply wrong. The writer's motive (cognitive reach) does not rescue a factually false statement.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PRT/TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-303","question":"Match the NCF 2005 validity criterion with the curriculum feature that best illustrates it. P. Cognitive validity  Q. Process validity  R. Historical validity  S. Ethical validity. 1. Students plan their own test of whether sugar dissolves faster in warm water  2. Students discuss why Mendel's findings were ignored for decades  3. Students record data honestly even when it contradicts the textbook value  4. The idea of the atom's inner structure is kept for a later stage when learners can handle abstraction","options":["P-1, Q-4, R-2, S-3","P-4, Q-3, R-2, S-1","P-4, Q-1, R-2, S-3","P-2, Q-1, R-4, S-3"],"answer":2,"explanation":"Age-appropriate sequencing is cognitive validity (P-4); designing a test is learning the methods of science, process validity (Q-1); how an idea was received over time is historical validity (R-2); honesty in data is ethical validity (S-3).","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · KVS"},
  {"id":"cdp-pedagogy-subjects-304","question":"Assertion (A): Introducing the quantum-mechanical model of the atom in Class 6 would weaken the science curriculum even though the model is scientifically correct. Reason (R): NCF 2005 requires that the content, process, language and pedagogy of science be within the cognitive reach of the learner.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Correct content alone is not enough; cognitive validity demands that it suit the learner's age and level of abstraction, which is exactly why the model would weaken a Class 6 curriculum.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-305","question":"While teaching malaria in Class 8, a teacher narrates how the disease was once blamed on 'bad air' and how Ronald Ross, working in India, showed that mosquitoes carry the malaria parasite. Which NCF 2005 criterion does this narrative serve most directly?","options":["Environmental validity, because malaria is a local health problem in many parts of India","Historical validity, because it shows how a scientific idea changed over time","Ethical validity, because the story promotes concern for human life and public health","Content validity, because the present cause of malaria is stated correctly at the end"],"answer":1,"explanation":"Telling how an earlier explanation was replaced by a better-evidenced one shows the learner how scientific concepts evolve, which is historical validity. The health link alone would not need the story of the change.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-306","question":"In a germination experiment, Ravi's seeds fail to sprout, and he is tempted to copy his friend's 'all seeds sprouted' result. The teacher holds a discussion on why an honestly reported failure is valuable in science. Which NCF 2005 criterion is the teacher mainly addressing?","options":["Process validity, since the episode arose during an experiment","Cognitive validity, since Ravi must understand germination at his level","Ethical validity, since it promotes honesty and objectivity","Content validity, since the correct germination result must be known"],"answer":2,"explanation":"Ethical validity asks the curriculum to promote values such as honesty, objectivity and freedom from fear and prejudice. The episode happened during an experiment, but the lesson drawn is about integrity, not method.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-307","question":"Consider these statements about the nature of science. 1. Scientific knowledge is tentative and may change in the light of new evidence. 2. A well-tested theory eventually gets promoted to a law. 3. What a scientist observes is partly shaped by what she already knows and expects. 4. All scientists follow one fixed, step-by-step 'scientific method'. Which are correct?","options":["1, 2 and 3 only","1 and 4 only","2, 3 and 4 only","1 and 3 only"],"answer":3,"explanation":"Science is tentative and observation is theory-laden. Theories and laws are different kinds of knowledge (a theory explains, a law describes a pattern), so one does not grow into the other, and there is no single universal method.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-308","question":"After a lesson on the solar system, a Class 6 student says, 'Pluto used to be a planet and now it is not, so science keeps getting things wrong and cannot be trusted.' The response that best builds an understanding of the nature of science is:","options":["Explaining that new discoveries and an agreed definition led to the change, and that such self-correction is a strength of science","Telling the student that earlier scientists were careless and that today's scientists are correct for ever, so the new list is final","Saying that scientific facts never change once they are proved, and that Pluto was just a rare exception to this rule","Asking the student to note the new list of planets and move on, since only the current list is in the syllabus"],"answer":0,"explanation":"Science revises its claims when new evidence appears; the Pluto reclassification shows this self-correcting character. Calling earlier work careless or science unchanging both distort its nature.","difficulty":"hard","source":"CTET Paper 2 · NVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-309","question":"Rina observes a lit candle placed under an inverted glass tumbler and writes four statements. Which one is an inference rather than an observation?","options":["The flame went out about twenty seconds after the glass was placed over it.","Tiny water droplets appeared on the inside of the glass near the top.","The flame went out because the air needed for burning ran short inside.","The candle had become slightly shorter by the end than it was at the start."],"answer":2,"explanation":"An inference is an explanation drawn from observations; the 'because' statement interprets why the flame died. The others report what was directly seen or measured.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-310","question":"Class 7 students want to test whether the amount of water given daily affects the growth of moong seedlings. Which plan controls the variables correctly?","options":["Three pots get 20, 40 and 60 mL daily; the 60 mL pot is kept in the sunniest corner since it needs the most energy","Three pots with the same soil, the same number of seeds and the same sunlight get 20, 40 and 60 mL of water daily","Three pots get different amounts of water, and each pot has a different kind of seed to make the test more interesting","One pot gets 20 mL daily and the other two get no water at all, so the difference is clearest"],"answer":1,"explanation":"A fair test changes only the independent variable (amount of water) and keeps soil, seeds and light the same. Changing sunlight or seed type with water confounds the result.","difficulty":"moderate","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-311","question":"Which classroom task demands an integrated science process skill rather than only a basic one?","options":["Sorting fallen leaves of the school garden into groups by the shape of their margins","Measuring the length of a bean shoot every morning with a ruler and recording it","Describing the colour change when turmeric paper touches soap solution in a dish","Proposing that warmer soil makes seeds sprout sooner and planning how to check it"],"answer":3,"explanation":"Formulating a hypothesis and designing a test are integrated process skills that combine several basic ones. Classifying, measuring and observing are basic process skills.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-312","question":"Before a plant-growth project, a Class 8 group agrees: 'A plant will count as healthier if, after two weeks, it is taller in cm and has more leaves.' Which process skill have they used?","options":["Predicting the outcome","Defining operationally","Inferring from data","Communicating results"],"answer":1,"explanation":"An operational definition states how a vague idea ('healthier') will be measured in the investigation. It is not a prediction about what will happen.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-313","question":"In a 5E lesson on air pressure, students have played with syringes and suction cups and recorded what they noticed. The teacher has then introduced the term 'atmospheric pressure' and helped them explain their observations. What should the next phase involve?","options":["A surprising demonstration, such as a crushed can, to raise fresh curiosity about air","A unit test on atmospheric pressure, since the concept has now been explained","More free play with syringes and suction cups so that every child gets a turn","Applying the idea to new situations, such as how a drinking straw or dropper works"],"answer":3,"explanation":"After Engage, Explore and Explain comes Elaborate, where learners extend the concept to new contexts. Evaluation follows, and a demonstration to raise curiosity belongs to the Engage phase.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-314","question":"A teacher begins the chapter on acids and bases by writing the definitions of acid, base and indicator on the board, and then gives students turmeric and litmus to test household substances. A teacher using the 5E model would most likely suggest:","options":["Letting students test substances first and introducing the terms after they try to explain their results","Dropping the activity altogether, because the definitions already cover what students need to know","Giving the definitions twice, once before and once after the activity, so that they are firmly fixed in memory","Replacing the testing with a teacher demonstration so that no class time is lost to student handling"],"answer":0,"explanation":"In the 5E sequence, formal terms come in the Explain phase, after learners have explored; definitions first turn the activity into mere confirmation.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-315","question":"A teacher gives Class 8 the question, 'Does the colour of a cloth affect how fast it dries in the sun?' The students themselves decide the materials, the method and how to record results. This is best described as:","options":["Confirmation inquiry","Structured inquiry","Guided inquiry","Open inquiry"],"answer":2,"explanation":"In guided inquiry the teacher supplies the question and students design the procedure. In structured inquiry the teacher also gives the procedure, and in open inquiry students frame the question too.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-316","question":"Arjun says a cup of boiling water has 'more heat' than a full bucket of lukewarm water because it is hotter. Which statement should the teacher help him reach?","options":["The cup has the higher temperature, but the bucket holds more thermal energy and could melt more ice","The cup has both the higher temperature and more heat, since heat and temperature are the same thing","The bucket has the higher temperature because it contains more water","Both contain the same heat, because heat depends only on the kind of substance"],"answer":0,"explanation":"Temperature is a measure of hotness; the total thermal energy also depends on the amount of matter. A large mass of lukewarm water can hold far more energy than a small cup of boiling water.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-317","question":"Most of a Class 7 class believes that a woollen sweater keeps us warm because it 'produces heat'. Which strategy is most likely to change this idea?","options":["Writing the correct reason on the board and asking students to learn it by heart for the next unit test","Letting the idea pass, since the belief does no harm in daily life and will surely correct itself in the later classes","Having students predict, then check with a thermometer inside a folded sweater for an hour, and explain the result","Listing more examples of warm clothes such as shawls, blankets and jackets so that the idea becomes clearer"],"answer":2,"explanation":"Predict-Observe-Explain creates a conflict between expectation and evidence: the thermometer reading does not rise, so wool must be insulating rather than producing heat. Telling or ignoring leaves the misconception intact.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-318","question":"Meena insists that while a ball thrown straight up is rising, an upward force from the throw is still acting on it. Which teacher question best creates productive cognitive conflict?","options":["'Can you write out the textbook definition of force and give one example of it?'","'If an upward force were acting, why does the ball keep slowing down until it stops?'","'Will you throw the ball up a few more times, watching closely until you see the force?'","'Can you solve v = u - gt for this ball and find the height it reaches?'"],"answer":1,"explanation":"Meena holds the common 'motion needs a force in its direction' (impetus) idea. Asking her to reconcile it with the steady slowing makes the idea fail on its own terms; definitions and formulae can be repeated without changing the belief.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-319","question":"Most students in a Class 7 class say that plants take their food from the soil. Which historical investigation, retold and discussed, would most directly challenge this idea?","options":["Pasteur's swan-neck flask experiment, which showed that broth spoils only from outside","Mendel's crosses of pea plants, which showed how traits pass from parent to offspring","Van Helmont's willow, which gained much mass while its soil lost very little","Jenner's work on cowpox and smallpox, which led to the first vaccine against disease"],"answer":2,"explanation":"Van Helmont found that a willow grew heavier by many kilograms over five years while its soil lost only about 60 grams, so the plant's mass could not have come from the soil. The other experiments address different questions.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS"},
  {"id":"cdp-pedagogy-subjects-320","question":"Students believe that a bulb 'uses up' current, so less current returns to the cell than leaves it. Which activity gives the most direct evidence against this belief?","options":["Adding a second cell so that the bulb glows more brightly","Explaining that energy, not current, is used in the bulb, and asking them to copy it","Showing a video of lightning to show how strong current can be","Placing identical ammeters on both sides of the bulb and comparing the readings"],"answer":3,"explanation":"Equal readings before and after the bulb show that current is the same all round a series circuit; what the bulb converts is energy. Telling the correct idea without evidence rarely shifts a misconception.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-321","question":"Assertion (A): A science teacher should present the structure of the atom as a series of models that were revised over time. Reason (R): Once scientific knowledge is accepted by the scientific community, it is absolute and final.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Showing successive atomic models conveys the tentative, evolving nature of science, so A is sound. R is false: accepted knowledge is still open to revision when new evidence arrives.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-322","question":"A Class 8 class studies a proposed dam in their district: students collect data on irrigation and power benefits, forest loss and displacement, and role-play farmers, engineers and displaced families. The main learning outcome intended is the ability to:","options":["Memorise the types of dams and their parts so that they can label diagrams accurately","Take informed, reasoned positions on issues where science, technology and society meet","Conclude that all development projects harm the environment and so should be stopped","Accept that such decisions are purely technical and are best left to trained engineers"],"answer":1,"explanation":"A socio-scientific issue taught this way builds evidence-based decision-making that weighs scientific, social and ethical aspects. Treating such issues as purely technical, or opposing all development, are both one-sided views.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-323","question":"A solar eclipse is due during school hours, and several families have told their children not to eat or step out during it. The most appropriate step for the science teacher is to:","options":["Ridicule the families' beliefs in class so that students give them up quickly and accept the scientific view instead","Avoid the topic altogether, since discussing it could upset families and create conflict with the school","Allow students to view the eclipse through dark sunglasses so that they can see the event for themselves","Arrange safe pinhole viewing, explain the event and invite students to weigh evidence against beliefs respectfully"],"answer":3,"explanation":"Safe observation plus explanation builds a scientific temper without humiliating families. Sunglasses do not protect the eyes from the sun, and avoiding or mocking the topic both fail as teaching.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-324","question":"A teacher introduces the Mitticool clay refrigerator, a grassroots innovation that keeps vegetables cool without electricity. Which follow-up task best develops students' own capacity to innovate?","options":["Designing a better cooler from local materials and measuring how far it lowers the temperature","Writing an essay on the life of the inventor and the many hardships he faced while building it","Memorising that the cooler works on the principle of evaporation, for use in the test","Drawing and labelling a neat diagram of the cooler, showing each of its parts clearly"],"answer":0,"explanation":"Innovation is developed by designing, testing and improving a product, which uses the evaporative-cooling idea in a new way. Biographies, memorising and diagrams leave students as passive receivers.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-325","question":"A teacher's test item asks students to pick the correct answer and then, in a second part, to choose the reason for their answer from four given reasons. The chief advantage of this two-tier format is that it:","options":["Reduces the time needed to mark the test, since both tiers can be checked by machine","Allows the teacher to award more marks to every student, since there are two parts","Reveals students who give the right answer for a wrong reason, exposing hidden misconceptions","Replaces the need for any practical assessment, because reasoning is already being tested on paper"],"answer":2,"explanation":"Two-tier items are diagnostic: the reason tier separates true understanding from guessing or a correct answer held for a faulty reason, which a single-tier MCQ cannot show.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-326","question":"A Class 6 chapter on fibres takes students to a local handloom weavers' cluster, where they observe the process and ask how power looms have affected the weavers' livelihoods. Which NCF 2005 criterion does this most directly reflect?","options":["Historical validity","Cognitive validity","Content validity","Environmental validity"],"answer":3,"explanation":"Environmental validity places science in the learner's wider environment, local and global, including issues of technology, society and the world of work. The visit is about present livelihoods, not the history of an idea.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-327","question":"A Class I teacher in Bhopal first asks children to clap once for every beat in their names (Ra-hul: two claps, Ka-ma-la: three claps). A month later she asks, 'What is left if we take the /m/ sound away from mat?' Which statement best describes what she is doing?","options":["Both tasks build phonological awareness, first at the syllable level and then at the harder, later-developing phoneme level","Both tasks are phonics, because the children are linking spoken sounds with the letters that stand for them on paper","The first task builds print awareness and the second builds phonological awareness, so they target different skills","The second task is easier than the first, because a single sound is shorter and much simpler to pick out than a whole syllable"],"answer":0,"explanation":"Both tasks are purely oral, so they are phonological awareness, not phonics (which needs letters). Syllable awareness develops before phoneme manipulation, so moving from clapping beats to deleting /m/ follows the normal developmental order.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-328","question":"Consider the following statements about how children learn to read and write: 1. In the emergent literacy view, literacy begins long before formal schooling, through scribbling, pretend reading and talk about books. 2. In the emergent literacy view, a child's 'pretend reading' of a memorised picture book is mere imitation that the teacher should correct. 3. The older reading readiness view held that reading instruction should wait until the child has acquired certain prerequisite skills. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Emergent literacy treats pretend reading as a genuine early literacy behaviour to be encouraged, so statement 2 is false. Statements 1 and 3 correctly contrast the emergent literacy view with the older readiness view.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-329","question":"Seven-year-old Meenu in a Class II classroom in Lucknow writes in her journal: 'I wnt to skul with my frnd.' What is the most appropriate response from the teacher?","options":["Circle each wrong word in red and ask Meenu to write the correct spelling five times so that the errors do not stick in her mind","Respond to the message first, note that Meenu writes the main sounds she hears, and model standard spellings in a reply","Stop journal writing for Meenu until she has learnt the spellings of common words from the textbook","Ignore spelling completely in every class up to Class V, since correct spelling always develops on its own over time"],"answer":1,"explanation":"Invented spelling shows the child's growing sound-letter knowledge; responding to meaning while modelling conventional forms supports progress without killing the urge to write. Endless drill or banning writing harms motivation, while 'never attend to spelling' ignores the need for gradual guidance.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-330","question":"A Class I teacher proudly shows a visitor her 'print-rich' classroom: the walls are covered with glossy commercially printed English alphabet and fruit charts, fixed high above the blackboard, and she rarely refers to them. Which evaluation is most accurate?","options":["The room is print-rich, because constant exposure to printed charts is by itself enough for young children to learn to read and write on their own","The charts should be removed altogether, because print on the walls distracts young children from the teacher and the lesson","The room would be better if the fruit charts were replaced with more alphabet charts, since letters must come before words","It is not print-rich in the real sense: print should be at eye level, include children's writing and home languages, and be used daily"],"answer":3,"explanation":"A print-rich environment is about meaningful, accessible print that children interact with (labels, names, their own charts, local languages), not decoration. Passive exposure alone does not teach reading, and more alphabet charts only repeat the same mistake.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-331","question":"While reading aloud a picture storybook to Class II in a Pune school, which teacher practice is most likely to develop children's comprehension?","options":["Reading the whole story without any pause so that fluency is not broken, then asking factual questions from the text","Asking each child to read one line aloud in turn so that everybody in the class gets an equal chance to read","Pausing at key points so children predict what happens, connect events to their lives and talk about the pictures","Translating each sentence word by word into the children's home language right after reading it aloud"],"answer":2,"explanation":"Interactive read-aloud (predicting, connecting, discussing) makes children active meaning-makers. Round-robin reading is a performance exercise, word-by-word translation fragments meaning, and only factual recall questions miss higher-level comprehension.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-332","question":"Assertion (A): Round-robin reading, in which each child reads one sentence aloud in turn, is not recommended as the main reading practice in the early grades. Reason (R): It gives each child very little actual reading time, focuses attention on oral performance rather than meaning, and can embarrass struggling readers.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Round-robin reading keeps most children idle while one reads, turns reading into a test of pronunciation, and creates anxiety; these are exactly why it is discouraged, so R explains A.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-333","question":"Five-year-old Arjun tells the whole story of a picture book fluently while turning its pages, but he holds the book upside down and starts from the last page. His teacher concludes, 'He cannot read at all.' What is the most appropriate interpretation?","options":["Arjun lacks phonemic awareness and needs daily drills on letter sounds before he is allowed to handle books again","Arjun has good oral narrative skill but not yet concepts about print, such as orientation and direction, which shared reading can model","Arjun may have a visual-perceptual disorder, so he should be referred to a specialist before any further reading instruction in class can begin","Arjun has only memorised the story, so his narration has no real value for his literacy development and can be ignored"],"answer":1,"explanation":"Narrating from pictures is a real emergent literacy strength; what is missing is concepts about print (which way up, front to back, left to right), best taught by modelling with big books. Referral or dismissing his narration misreads normal development.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-334","question":"During shared reading with a big book, a Class I teacher slides her finger under each word as she reads. The main purpose of this action is to:","options":["make children memorise the text faster so that they can recite the whole book from memory by the end of the week","check whether children are pronouncing every word correctly as they read along with her","keep children's eyes fixed on the book so that attention and discipline are maintained","show the one-to-one match between spoken and written words and the direction in which print runs"],"answer":3,"explanation":"Finger tracking demonstrates concepts about print: each spoken word matches a written word, with spaces between words, read left to right and top to bottom. It is a teaching move, not a memory or discipline device.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-335","question":"In a Class I classroom in Bastar, almost all children speak Gondi at home, while the school textbook and the teacher use Hindi. In line with NEP 2020 and multilingual education, what should the teacher do?","options":["Ban Gondi in the classroom so that children get the maximum possible exposure to Hindi, the language of the textbook","Postpone all reading and writing until the children have become fluent speakers of Hindi, the medium of instruction","Begin with Gondi for talk, concepts and early literacy, and gradually bridge to Hindi by building on what children know","Teach Gondi and Hindi as two separate subjects in separate periods, with no link at all being made between the two languages"],"answer":2,"explanation":"Children learn concepts and literacy best in a language they understand; a planned bridge then transfers these skills to the school language. Banning the home language (submersion) causes failure and alienation, and postponing literacy wastes the foundational years.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-336","question":"In a well-planned mother-tongue-based multilingual education (MTB-MLE) programme, which sequence of the bridge to the school language is most appropriate?","options":["Oral home language and home-language literacy first, then oral school language, then school-language literacy built on the first","Reading and writing in the school language first, then oral home language, and only then the oral school language","Oral school language first, then reading and writing in the school language, with the home language used only to explain the textbook","Literacy in the home language and the school language both started together on the first day, with oral work added later on"],"answer":0,"explanation":"MTB-MLE moves from the known to the unknown: oral home language, home-language literacy, oral second language, then second-language literacy that transfers already-learnt skills. Starting with literacy in an unfamiliar language reverses this logic.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-337","question":"Assertion (A): Children who first learn to read well in their mother tongue usually find it easier to learn to read in a second language. Reason (R): Literacy skills and conceptual knowledge, once acquired in one language, can largely transfer to another language.","options":["Both A and R are true, but R is not the correct explanation of A","Both A and R are true, and R is the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Cummins' idea of a common underlying proficiency holds that reading strategies and concepts learnt in one language are available in another; this transfer is exactly why strong mother-tongue literacy helps second-language reading.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-338","question":"A Class I teacher has planned four oral activities: P. splitting sun into its three separate sounds; Q. counting the words in a spoken sentence; R. noticing that cat and hat end with the same chunk -at; S. clapping the syllables in banana. In which order should they ideally be introduced, from easiest to hardest?","options":["S, Q, R, P","Q, S, P, R","R, Q, S, P","Q, S, R, P"],"answer":3,"explanation":"Phonological awareness usually develops from larger to smaller units: words in a sentence, syllables, onset and rime (rhyme families), and finally individual phonemes. So Q, S, R, P.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-339","question":"Consider the following statements: 1. A teacher asking 'What is the first sound in pen?' with children's eyes closed is developing phonemic awareness. 2. Phonics instruction teaches the relationship between sounds and the letters or akshar that represent them. 3. Phonemic awareness cannot be developed until children know the letters of the alphabet. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Phonemic awareness is an oral skill and can be built without any print, so statement 3 is false. Phonics adds the link to written symbols, as statement 2 says.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-340","question":"After a visit to a mango orchard, a Class II teacher in Ratnagiri writes on chart paper the sentences children dictate about the trip, reads them back with the class, and uses the chart for reading practice over the next week. Why is this approach particularly effective for beginning readers?","options":["The text is in the children's own words about their own trip, so its meaning is predictable and they see speech become print","It guarantees that children will learn the correct spelling of every word on the chart, since they copy and read it every day of the week","It removes the need for any explicit teaching of letters and sounds, because children learn them from the chart","It makes sure all children learn exactly the same vocabulary as the textbook, so the syllabus is covered faster"],"answer":0,"explanation":"The language experience approach turns the child's own talk into reading material, so familiar meaning supports decoding and links oral and written language. It complements, not replaces, sound-letter teaching.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-341","question":"Reading the sentence 'I live in a big house', a Class II child says 'I live in a big home' and carries on. What should the teacher conclude and do?","options":["The child has a visual processing problem and should be referred for a detailed assessment before reading further","The child uses meaning and first letters but not the whole word; prompt cross-checking: 'It makes sense, but does it look right?'","The child is guessing randomly, so the teacher should stop the story at once and drill the isolated letter sounds until they are secure","The child is reading word by word without understanding, so comprehension questions should be dropped for now"],"answer":1,"explanation":"A miscue that keeps the meaning shows the child is reading for sense; the gap is in attending to the whole printed word. Prompting the child to check meaning against print strengthens both cue systems without treating the miscue as a random error.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-342","question":"Which sequence correctly shows how young children's writing usually develops?","options":["Random letter strings, scribbling, letter-like shapes, invented spelling, conventional spelling","Scribbling, invented spelling, letter-like shapes, random letter strings, conventional spelling","Letter-like shapes, scribbling, invented spelling, random letter strings, conventional spelling","Scribbling, letter-like shapes, random letter strings, invented spelling, conventional spelling"],"answer":3,"explanation":"Children move from scribbles to mock letters, then to strings of real letters without sound links, then to spelling by sound, and finally to conventional spelling. Seeing these stages helps teachers value early writing.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-343","question":"Assertion (A): A teacher should continue reading aloud to children in Classes IV and V, even after they can read independently. Reason (R): Read-alouds let children enjoy and understand texts that are richer in vocabulary and structure than what they can yet read on their own.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Listening comprehension runs ahead of reading level for years, so read-alouds expose children to harder language and model fluent, expressive reading. This is precisely why they remain useful in upper primary.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-344","question":"A district resource group is designing early-grade reading lessons under NIPUN Bharat. Which plan best reflects a balanced approach to early literacy?","options":["Only phonics drills until decoding is perfect, after which stories and books are gradually introduced for enjoyment","Only exposure to stories and books, with no explicit teaching of letters and sounds, since children pick up decoding naturally by themselves","Daily read-alouds, talk and children's books combined with explicit, systematic sound-symbol work and plenty of meaningful writing","Rote recitation of the full varnamala in its fixed order before any words, stories or books are introduced to children"],"answer":2,"explanation":"A balanced approach combines meaning-making (oral language, read-aloud, books) with explicit decoding instruction and writing. The two extremes (only drills or only exposure) and rote alphabet recitation each leave out a vital strand.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-345","question":"A Class I Hindi teacher teaches one letter of the varnamala each week, strictly in alphabetical order, through chanting and copying, and introduces words only after all letters are covered. Which criticism is most valid?","options":["The pace is too fast; two weeks per letter would give children enough time to master each letter fully before moving on to the next one","Letters are taught in isolation and too slowly; children should meet common letters in meaningful words and read simple words early","Matras should be taught first, before any consonants, since they occur in almost every word children will read","Chanting is good, but the teacher should first insist on neat handwriting of every letter before any reading is attempted"],"answer":1,"explanation":"Decontextualised, letter-a-week teaching delays reading for months and gives no meaning; starting with high-utility letters and blending them into words quickly lets children read early. Slowing down or adding handwriting prerequisites makes the problem worse.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-346","question":"While reading a Hindi passage aloud, a Class III child in a Bihar village pronounces several words the way they are spoken in Bhojpuri, but answers every comprehension question correctly. What is the most appropriate teacher response?","options":["Stop the child at every such word and insist on the standard pronunciation before letting her move on in the passage","Record each dialect pronunciation as a reading error in the child's assessment so that progress can be tracked","Refer the child to a speech therapist, since the repeated mispronunciations suggest an articulation problem","Accept the dialect pronunciations as part of the child's language, since she is decoding and understanding the text"],"answer":3,"explanation":"Dialect features are not reading errors; the child is decoding and comprehending. Constant correction marks the home language as inferior and discourages reading, while referral confuses dialect with a disorder.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-347","question":"A Class IV teacher wants her library period to build a lasting reading habit. Which practice is most suitable?","options":["Children choose their own books, including books in home languages, and read for pleasure with no test afterwards","All children read the same book and write a summary that is marked for grammar, so that reading is checked","Only textbook chapters are read in the library period so that the syllabus is completed well before the annual exams","Children are allowed into the library only after finishing their classwork, so that reading becomes a reward"],"answer":0,"explanation":"Free voluntary reading with choice and no testing builds motivation and volume of reading, which drive fluency and vocabulary. Turning reading into a test or a reward makes it an assignment rather than a habit.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-348","question":"Match each Class I activity with the early literacy skill it mainly targets. Activities: P. Picking the odd one out by first sound (bat, ball, cup); Q. Showing where to start reading on a page; R. Re-reading a familiar poem with expression until it flows; S. Retelling a story in one's own words. Skills: 1. Fluency; 2. Phonological awareness; 3. Comprehension; 4. Concepts about print.","options":["P-2, Q-1, R-4, S-3","P-4, Q-2, R-1, S-3","P-2, Q-4, R-1, S-3","P-2, Q-4, R-3, S-1"],"answer":2,"explanation":"Odd-one-out by sound is phonological awareness; knowing where to start is a concept about print; repeated expressive reading builds fluency; retelling shows comprehension.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-349","question":"A teacher wants to check the phonological awareness of a Class I child who cannot yet read. Which task is the valid one for this purpose?","options":["Dictating five simple words for the child to write","Asking the child to say kamal without the ka sound","Showing letter cards and asking the child to name each letter","Asking the child to copy a sentence from the blackboard"],"answer":1,"explanation":"Phonological awareness is oral, so it must be assessed without print; sound deletion does this. The other tasks test letter knowledge, spelling or copying, which a non-reader would fail for different reasons.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-350","question":"Parents of four-year-olds in an Anganwadi-cum-preschool want daily worksheets for tracing and writing the alphabet. Following NCF for the Foundational Stage 2022, what should the teacher explain and do?","options":["Agree, and start daily cursive writing practice at once, since early neat handwriting is widely said to predict later success at school","Refuse to show children any print at all until they turn six, because early print exposure causes stress and confusion","Agree to daily alphabet tracing so that the parents are satisfied, while continuing play-based activities separately","Explain that at this age the focus is talk, stories, songs, drawing, emergent writing and fine-motor play, not formal writing drills"],"answer":3,"explanation":"NCF-FS 2022 stresses oral language, storytelling, print exposure and emergent writing through play for ages 3-6, not formal writing drills. Hiding all print is the opposite extreme and wrong too.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-351","question":"A Class 3 child works out 503 − 178 and gets 335. Her working shows: ones, 13 − 8 = 5; the 0 in the tens place crossed out and written as 10, then 10 − 7 = 3; hundreds, 4 − 1 = 3. What is the precise misconception?","options":["She subtracts the smaller digit from the larger digit in each column, whatever its position","She does not yet know the subtraction facts 13 − 8 and 10 − 7, so each column result is a guess","She turns the 0 tens into 10 tens, forgetting that one ten went to the ones, so it should be 9","She borrows from the hundreds twice, once for the ones and again for the tens, losing one hundred"],"answer":2,"explanation":"503 regroups as 4 hundreds, 9 tens and 13 ones, giving 325. Writing the tens as 10 instead of 9 counts one ten twice, so the answer is exactly 10 too big; the facts themselves are correct.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-352","question":"A Class 5 child multiplies 23 × 14 in columns and writes: 23 × 4 = 92, then 23 × 1 = 23, then 92 + 23 = 115. Which diagnosis is accurate?","options":["She treats the 1 in 14 as one, not one ten, so the second partial product should be 230, not 23","She does not know the fact 3 × 4 and has carried wrongly into the tens of the first partial product","She has added the tens digits where she should have multiplied them, which shrinks the final answer","She multiplied the digits in the wrong order, which changes the product in column multiplication"],"answer":0,"explanation":"The partial product for the tens digit is 23 × 10 = 230, and 92 + 230 = 322. Her facts are correct (23 × 4 = 92); the error is about the place value of the multiplier's digit, which an area or grid model makes visible.","difficulty":"hard","source":"CTET Paper 1 · state TETs · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-353","question":"A Class 4 child divides 624 by 6 using long division and writes the quotient as 14. Which explanation and follow-up are most appropriate?","options":["She does not know that 6 goes into 24 four times, so she should practise the 6 times table every day this week","She divided from right to left; insist that long division must always start from the leftmost digit","She subtracted at each step instead of dividing, so the meaning of division needs to be revised first","She skipped the 0 when 6 would not go into 2 tens; estimating 600 ÷ 6 = 100 shows 14 is far too small"],"answer":3,"explanation":"624 ÷ 6 = 104. Skipping the 0 for the tens collapses the place value of the 1. Asking for an estimate first is the strongest check, since 14 × 6 is only 84.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-354","question":"Asked ‘How many tens are there in 352?’, a Class 4 child answers ‘5’. Which interpretation and next step are most appropriate?","options":["The child is right; the tens digit is the only correct answer to this question, so no follow-up is needed at all","She reads only the tens digit; 352 has 35 tens in all, so let her unbundle 3 hundreds into 30 tens and count","The child confuses tens with hundreds, so she should be drilled on naming the places from right to left","The child cannot count beyond 100 and should go back to counting objects one by one before place value"],"answer":1,"explanation":"‘How many tens in 352’ asks for the total number of tens, which is 35 (with 2 ones left). Seeing that 1 hundred = 10 tens by regrouping bundles builds the flexible place value that later supports division.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-355","question":"A Class 1 child correctly says ‘sixteen’ when shown 16 counters but writes the number as 61. The most likely reason is that:","options":["the child has a visual-perception disorder that reverses digits and should be referred for assessment","the child has not yet memorised the written numerals beyond 10, so she writes any two digits she knows","in ‘sixteen’ the ones word comes first, so she writes the digits in the order she hears them","the child is used to writing from right to left, as in the Urdu script she sees at home"],"answer":2,"explanation":"Teen number names are irregular: ‘six-teen’ says the ones before the ten. Children who write what they hear produce 61; bundling one ten and six loose sticks shows that the ten is written first.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-356","question":"To find 3 + 8, a Class 1 child counts out three fingers, then eight fingers, and counts all of them from one. Which step by the teacher is most likely to move her to a more efficient strategy?","options":["Hide eight counters under a cloth, say ‘there are eight here’, and ask her to count on using the three she can see","Give her flash cards so that she memorises all the addition facts up to 20 and no longer needs to count at all","Tell her that counting on fingers is babyish and must stop, so that she is pushed to use mental methods instead","Give her the same kind of sum with much larger numbers, so that counting all becomes too slow and she gives it up herself"],"answer":0,"explanation":"Hiding the larger set pushes the child to start from 8 and count on (‘nine, ten, eleven’), the natural next stage after counting all. Banning fingers or drilling facts skips the understanding that makes counting on possible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-357","question":"A teacher flashes a card with five dots for two seconds. A child says, ‘Five, because I saw three on top and two below.’ This shows:","options":["perceptual subitising, recognising a small set at a glance without any parts","rote counting, saying number names in order","one-to-one correspondence between dots and number names","conceptual subitising, seeing small parts at once and combining them"],"answer":3,"explanation":"The child saw 3 and 2 instantly and put them together: conceptual subitising. Perceptual subitising is seeing the whole small set at once; there was no time to count one by one.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-358","question":"Two rows of seven bottle caps are laid out one-to-one. When the teacher spreads one row out, a five-year-old says that row now has more. What is the most appropriate conclusion?","options":["The child cannot yet count to seven correctly and needs daily counting drills before any number work","She judges quantity by length and has not yet conserved number; let her re-match and re-count after each change","The child shows early signs of dyscalculia and should be referred to a specialist for a full assessment","The child should be told the rule ‘spreading never changes the number’ and repeat it aloud until she can remember it"],"answer":1,"explanation":"Judging number by the space a row takes up is typical before conservation (Piaget). Re-matching and re-counting the same caps lets her build the idea that number stays the same; telling her a rule does not.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-359","question":"For 8 + 4 = ☐ + 5, most children in a Class 2 class write 12 in the box and a few write 17. What does this most likely show, and what helps?","options":["They cannot add 8 and 4 reliably, so they should be given more practice with single-digit addition facts","They did not read the whole number sentence, so they should be asked to read every question slowly and carefully at least twice","They read ‘=’ as ‘the answer comes next’, not ‘has the same value as’; use a pan balance and true/false sentences","They have not yet learnt subtraction, so they cannot work out a missing addend on the right-hand side"],"answer":2,"explanation":"Both 12 and 17 come from an operational view of ‘=’ (calculate and write the result). Balancing both sides on a pan balance and judging sentences like 7 + 2 = 6 + 3 builds the relational meaning needed for algebra.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-360","question":"A teacher wants true/false number sentences that best test whether children understand ‘=’ as a relation. Which set should she choose?","options":["5 + 3 = 8; 9 + 1 = 10; 6 + 2 = 8; 4 + 4 = 8; 7 + 1 = 9","8 + 0 = 8; 0 + 8 = 8; 8 − 0 = 8; 8 + 1 = 9; 9 − 1 = 7","12 − 4 = 8; 15 − 7 = 8; 10 − 2 = 8; 11 − 3 = 8; 9 − 2 = 6","7 + 2 = 9; 9 = 7 + 2; 7 + 2 = 6 + 3; 7 + 2 = 9 + 4"],"answer":3,"explanation":"Only the last set breaks the ‘sum on the left, answer on the right’ pattern: 9 = 7 + 2 and 7 + 2 = 6 + 3 are true, and 7 + 2 = 9 + 4 is false. Children who see ‘=’ as ‘write the answer’ wrongly judge these.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-361","question":"On a number line a child does 3 + 4 by putting her finger on 3, saying ‘one’, then ‘two, three, four’ on 4, 5 and 6, and answers 6. What is she missing?","options":["That we count the jumps (spaces) from the starting point, not the marks","The basic fact 3 + 4 = 7, which she should already have memorised by now","That addition on a number line always means moving to the left","That the number line must start at 1, not 0, for counting to work"],"answer":0,"explanation":"She counted the starting point as a step, so she made only three jumps. A number line models numbers as distances from zero, so 3 + 4 means four jumps starting from 3, landing on 7.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-362","question":"A Class 5 child writes 49 × 21 = 1229. Which response by the teacher best builds number sense?","options":["Mark it wrong and ask her to redo it carefully with the standard column method in her notebook","Ask her to estimate 50 × 20, judge if 1229 is reasonable, then find where the extra came from","Give her a calculator so that she can check every answer herself before handing in her work","Tell her the correct answer is 1029 and move on quickly to the next sum in the exercise"],"answer":1,"explanation":"49 × 21 = 1029, close to the estimate 50 × 20 = 1000. Asking the child to compare her result with an estimate teaches her to check reasonableness herself, which redoing or being told the answer does not.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-363","question":"A Class 4 child who helps at her family's vegetable stall works out the cost of 3 kg at ₹35 a kg in her head (‘35, 70, 105’) but gets 35 × 3 wrong in her notebook. What should the teacher conclude?","options":["The written algorithm does not suit her, so she should be excused from it and allowed to use mental methods only","She has a memory problem that shows only in school, where she cannot recall the steps of the method","Her informal, context-based strategy is real mathematics, and the written method should be linked to it","Market mathematics is unreliable and informal, and should be discouraged in class in favour of the textbook"],"answer":2,"explanation":"Studies of street mathematics (Nunes and Carraher) show children reason well in real contexts. The teacher should build on this repeated-addition reasoning to give meaning to the written method, not dismiss either.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-364","question":"Which of these statements about teaching place value are correct? I. Bundles of sticks help because each bundle keeps ten visible as one unit. II. A bead on the tens rod of an abacus looks like a bead on the ones rod, so the abacus is a more abstract model than bundles. III. Zero is best taught as ‘nothing’, so children can ignore it when reading numbers. IV. Writing numbers in expanded form (300 + 50 + 2) helps children see the value of each digit.","options":["I and III only","II and IV only","I, III and IV","I, II and IV"],"answer":3,"explanation":"Bundles are proportional models (a ten is ten times as big); an abacus is non-proportional, so it should come later. Zero is a place holder that changes value (405 vs 45), so III is wrong.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-365","question":"Which of these is a non-proportional model of place value, best used only after children are confident with proportional ones?","options":["₹10 notes and ₹1 coins","A bundle of ten sticks tied with a rubber band","A base-ten rod made of ten unit cubes joined together","A string of ten beads with each bead visible"],"answer":0,"explanation":"A ₹10 note is not ten times the size of a ₹1 coin; its value is given by agreement, just like a digit's place. Bundles, rods and bead strings physically contain ten ones, so they are proportional.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-366","question":"A Class 3 child works out 63 − 28 like this: ‘60 − 20 = 40. 3 − 8 is five less. 40 − 5 = 35.’ The teacher should:","options":["mark it wrong, because 3 − 8 cannot be done in Class 3 and negative ideas only confuse children","accept it as a valid partitioning strategy and ask her to explain to the class why ‘five less’ works","insist that she use borrowing instead, since it is the standard method expected in the final examination","tell her it gave the right answer only by luck for these numbers and will fail with other numbers"],"answer":1,"explanation":"Splitting both numbers into tens and ones is valid for any numbers: 63 − 28 = (60 − 20) + (3 − 8) = 40 − 5 = 35. Inviting her to explain respects her reasoning and helps classmates think flexibly.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-367","question":"Which situation best models 4 × 6 so that children can also see why 4 × 6 = 6 × 4?","options":["Four children each get six sweets, making twenty-four sweets in all","A ribbon 6 m long is cut into 4 equal pieces of the same length","Chairs set in 4 rows of 6, which can also be seen as 6 columns of 4","The price of a pen rises from ₹6 to ₹24 after a few years"],"answer":2,"explanation":"An array can be read by rows or by columns, so the same 24 chairs show both 4 × 6 and 6 × 4. Equal groups (four children with six sweets) do not show commutativity at a glance.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-368","question":"A Class 5 child says 5 ÷ 0 = 0 ‘because anything with zero is zero’. Which response best helps her make sense of it?","options":["Ask her to learn the rule ‘division by zero is not defined’ and repeat it until it finally sticks","Point out that 5 × 0 = 0, so her answer 5 ÷ 0 = 0 fits the related multiplication fact","Tell her the answer is 5, because dividing by nothing means nothing is taken away from 5","Ask: ‘What number times 0 gives 5?’ and ‘How many groups of 0 can you make from 5 sweets?’"],"answer":3,"explanation":"Linking division to multiplication shows no number works, since any number × 0 is 0, not 5; so 5 ÷ 0 has no answer. Option B uses the same faulty link, and option C confuses division with subtraction.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-369","question":"‘A school bus holds 40 children. 130 children are going on a trip. How many buses are needed?’ A child writes ‘130 ÷ 40 = 3 remainder 10, so 3 buses.’ What is the correct diagnosis?","options":["The division is right, but she did not interpret the remainder in context; 4 buses are needed","She made an error in the division itself, since 130 ÷ 40 does not really leave a remainder of 10","She should have multiplied 130 by 40 instead of dividing, since buses carry many children","The question is ambiguous, so 3 buses is also acceptable if the extra children squeeze in"],"answer":0,"explanation":"130 ÷ 40 = 3 remainder 10, and the 10 children left over still need a bus. Children need practice deciding whether a remainder is dropped, rounded up or written as a fraction, depending on the context.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-370","question":"A Class 3 child says 0 is neither even nor odd ‘because it is nothing’. What is the best response?","options":["Tell her firmly that 0 is even, because the textbook and the teacher's guide both say so, and that settles it","Ask whether 0 fits the even–odd pattern on the number line and whether 0 sweets can be shared equally by two","Accept her answer, since 0 is a special number that does not behave like the other whole numbers in any way","Agree that even and odd apply only to counting numbers, so 0 is neither, and move on to the next topic"],"answer":1,"explanation":"0 sits between the odd numbers −1 and 1 in the alternating pattern and can be split into two equal groups of 0, so it is even. Letting her test the definition builds reasoning instead of relying on authority.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-371","question":"A teacher uses a 100-bead string (ganit mala) whose colour changes after every ten beads. What is its main advantage?","options":["It makes rote counting from 1 to 100 faster, since children can slide the beads quickly","It removes the need for written numerals, since children can show every number with beads","It lets children see and move in tens and ones, e.g. 38 + 10 by jumping one colour block","It helps children learn multiplication tables by heart by counting the beads in each block"],"answer":2,"explanation":"Colour blocks of ten make the structure of numbers visible, so children can count on in tens and link counting with place value and mental addition.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-372","question":"In a ‘number talk’ the teacher writes 25 × 4. Children share 25 + 25 + 25 + 25, ‘four quarters make 100’, and 20 × 4 + 5 × 4. What is the teacher's main role?","options":["Pick the quickest strategy and ask everyone to use it from now on, for the sake of efficiency","Correct wrong answers at once and move on, so that no child is left holding on to a wrong method","Write only the correct answers on the board, so that wrong strategies do not confuse others","Record each strategy, ask children to explain a classmate's method, and compare the strategies"],"answer":3,"explanation":"Number talks build flexible mental strategies through discussion. The teacher records ideas, including wrong ones to be examined, and gets children to explain and compare, rather than imposing one method.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-373","question":"Assertion (A): A teacher should ask ‘How did you get it?’ after both right and wrong answers in mathematics. Reason (R): A right answer can come from a faulty method, and a wrong answer can hide mostly correct reasoning.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because answers alone hide the thinking behind them, asking children to explain their method is how a teacher diagnoses understanding; R is exactly why A is good practice.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-374","question":"Assertion (A): Children should be taught the standard written algorithms before they are allowed to try their own methods. Reason (R): Children's own methods often reveal how well they understand place value.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Invented strategies are valuable both as learning and as a window into the child's place-value understanding, so they should come before, not after, the standard algorithm. A is false; R is true.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-375","question":"To assess Class 4 children's understanding of multiplication rather than recall, which task is best?","options":["Write out the tables of 6 to 9 correctly within five minutes","Solve twenty sums of the type 2-digit × 1-digit without any errors","Write a story for 6 × 4, draw it, and explain why 6 × 4 = 4 × 6","Match multiplication facts with their answers in a timed quiz"],"answer":2,"explanation":"Making a story and a picture shows whether the child knows what multiplication means, and explaining commutativity shows reasoning. The other tasks test speed and memory.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-376","question":"Riya, a Class 9 student in Patna, can state the rule for the present perfect continuous, yet in class discussion she says ‘I am waiting here since morning’. In a written grammar test with plenty of time she correctly writes ‘I have been waiting here since morning’. Which of Krashen’s hypotheses best explains this gap?","options":["Natural order hypothesis: the present perfect continuous is always acquired before the simple present continuous","Monitor hypothesis: learnt rules can edit output only when there is time, a focus on form and knowledge of the rule","Input hypothesis: she has received input at exactly the i+1 level for this structure, but only ever in its written form","Affective filter hypothesis: written tests raise her anxiety and so block the use of her acquired knowledge"],"answer":1,"explanation":"Fast speech leaves no time to consult learnt rules, so her acquired system (which still says ‘am waiting since’) shows; with time in a written test the monitor edits the sentence. Option D reverses what actually happens.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-377","question":"Which of the following statements would Stephen Krashen NOT accept?","options":["Acquisition is a subconscious process that gives the learner a ‘feel’ for what is correct","Learning produces conscious knowledge about the rules of a language, useful mainly for editing","Rules that are consciously learnt and practised enough eventually turn into acquired competence","Adults as well as children keep the ability to acquire a second language through comprehensible input"],"answer":2,"explanation":"Krashen held a ‘non-interface’ position: learnt knowledge does not convert into acquired knowledge. He also insisted adults keep the capacity to acquire, so the other three fit his model.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-378","question":"A Class 3 teacher taught the third-person ‘-s’ (‘She plays’) in July and the ‘-ing’ form (‘She is playing’) in October. By December most children use ‘-ing’ correctly but still say ‘She play’. Which conclusion is most consistent with Krashen’s natural order hypothesis?","options":["The ‘-s’ lesson was badly taught and should simply be repeated with many more substitution and pattern drills","The pattern reflects only interference from the mother tongue and says nothing about any general order","The ‘-ing’ form should never have been taught until the third-person ‘-s’ was fully mastered by every child in the class","Some structures are acquired before others whatever the teaching order, so instant mastery should not be expected"],"answer":3,"explanation":"Morpheme-order studies found ‘-ing’ is acquired early and third-person ‘-s’ late, whatever the order of teaching. Krashen argued this is why rich input matters more than grammatical sequencing.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-379","question":"A teacher is choosing stories for Class 5 learners in a Hindi-medium school in Jaipur. According to Krashen’s input hypothesis, the best choice is texts that are:","options":["Entirely at the learners’ present level, so that no word or structure in them is at all unfamiliar","A little beyond the learners’ present level but made understandable through pictures and context","Preceded by a full grammar explanation of every new structure that appears in them","Advanced authentic texts such as newspaper editorials, so that learners are fully stretched"],"answer":1,"explanation":"Acquisition happens through input at ‘i+1’ that is still comprehensible. Input at ‘i’ adds nothing new, input far beyond the learner is noise, and grammar explanation is learning, not acquisition.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-380","question":"A shy Class 7 girl from a tribal community in Jharkhand follows English instructions well but freezes whenever she is asked to read aloud, and some classmates giggle. In the light of Krashen’s theory, the best teacher action is to:","options":["Ask her to read aloud before the class every day so that she slowly gets used to the attention","Give her extra grammar worksheets so that knowing the rules well builds up her confidence to speak","Stop the ridicule, begin with pair or choral reading and accept early answers in her home language","Excuse her from English lessons for some months until she becomes more confident on her own"],"answer":2,"explanation":"A high affective filter (anxiety, low self-confidence) blocks input from being acquired. Forcing public performance raises the filter, and excusing her cuts off input altogether.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-381","question":"A Class 1 child in a Bengaluru school, whose home language is Tamil, has not spoken a word of English in two months, but he follows every classroom instruction correctly. The most appropriate teacher response is to:","options":["Treat it as a normal silent period, keep giving comprehensible input and accept non-verbal responses","Refer the child to a speech therapist, since two months of silence signals a language delay","Insist that he answer every question in a complete English sentence so that he is pushed to start speaking","Shift him to a lower class where the English used is simpler and the pressure is less"],"answer":0,"explanation":"Many second-language learners go through a silent period in which they build competence through listening; his correct responses to instructions show comprehension. Forcing speech raises the affective filter.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-382","question":"Assertion (A): Krashen held that formal grammar teaching contributes little to a learner’s fluency in speaking. Reason (R): According to the monitor hypothesis, fluent utterances are initiated by the acquired system, and learnt rules can only edit them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In Krashen’s model acquired competence initiates speech and learnt knowledge only monitors it, which is exactly why he saw grammar teaching as having limited value for fluency.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-383","question":"Arjun speaks English very haltingly, pausing to check each sentence against a grammar rule before he says it. Farhan chats fluently, makes many errors and never thinks about rules. In Krashen’s terms:","options":["Arjun is a monitor under-user and Farhan is a monitor over-user","Both are optimal monitor users who apply rules when appropriate","Arjun is a monitor over-user and Farhan is a monitor under-user","Arjun has simply received more comprehensible input than Farhan"],"answer":2,"explanation":"Over-users rely so heavily on learnt rules that their speech becomes hesitant; under-users rely only on acquired competence. The optimal user applies the monitor when it does not hinder communication, for example while editing writing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-384","question":"In which situation is a learner most likely to use Krashen’s ‘monitor’ effectively?","options":["Answering rapid-fire questions in the buzzer round of an inter-school quiz","Revising a formal letter at leisure, checking a rule she already knows","Chatting with friends in the canteen about yesterday’s cricket match","Listening carefully to a news bulletin on All India Radio"],"answer":1,"explanation":"The monitor needs three conditions together: enough time, a focus on form, and knowledge of the rule. Only careful editing of writing meets all three; listening is comprehension, not monitoring of output.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-385","question":"Students in an English-immersion school in Kochi understand spoken and written English very well, yet their own speech and writing remain inaccurate after years. Their teacher therefore designs tasks that push them to speak and write, notice gaps in what they produce, and reformulate. Which idea most directly supports her plan?","options":["Krashen’s input hypothesis","Skinner’s theory of reinforcement","Chomsky’s language acquisition device","Swain’s output hypothesis"],"answer":3,"explanation":"Merrill Swain, studying Canadian immersion learners, argued that comprehension alone is not enough; ‘pushed output’ makes learners notice gaps and test hypotheses. The input hypothesis alone would not predict this gap.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-386","question":"During pair work, Meena says, ‘Then the man cut the kite.’ Her partner asks, ‘Cut? You mean with scissors, or the thread broke?’ Meena replies, ‘No, in the kite fight, he cut the thread of my kite.’ This exchange best illustrates:","options":["Negotiation of meaning, which Long’s interaction hypothesis links to acquisition","Pattern practice of the kind used in the audio-lingual method of teaching","Use of the monitor to edit a grammatical form carefully before speaking aloud","Fossilisation of an incorrect structure that is reinforced through peer interaction"],"answer":0,"explanation":"Clarification requests and reformulation during interaction adjust the input until it is understood; Long argued this negotiation is a key route to acquisition.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-387","question":"A shopkeeper in Agra has used English with tourists for twenty years. He communicates well but still says ‘He don’t know’ and ‘You are coming tomorrow, no?’, and these forms have not changed despite constant exposure. This phenomenon is called:","options":["The silent period","Overgeneralisation","Code-mixing","Fossilisation"],"answer":3,"explanation":"Fossilisation (Selinker) is the stabilisation of interlanguage features that persist despite continued input. Overgeneralisation is a temporary developmental stage, not a permanent plateau.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-388","question":"Sunita, a Class 5 child who migrated from Odisha to a Delhi English-medium school, chats easily in English with friends within a year but struggles with her science textbook. Using Jim Cummins’ ideas, the teacher should conclude that:","options":["Her fluent chatting shows she has full proficiency, so the difficulty must be lack of effort","Her pattern points to a specific reading disability that needs early referral","She has conversational fluency (BICS), but academic language (CALP) takes years to develop","She should be moved back to a school that teaches in her home language"],"answer":2,"explanation":"Cummins found that playground fluency develops in about two years but context-reduced academic language takes five to seven. Mistaking BICS for full proficiency leads to wrong labels such as ‘lazy’ or ‘learning disabled’.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-389","question":"A Class 4 child reads and writes fluently in Marathi and is now learning English. According to Cummins’ ‘common underlying proficiency’ (iceberg) model, which implication is correct?","options":["Literacy skills built in Marathi transfer to English, so strengthening Marathi also supports English","Marathi and English are stored separately, so time spent on Marathi takes away from English","She should stop using Marathi at school so that her English can develop faster and cleaner","Only knowledge of letters transfers between the two languages; reading strategies must be learnt anew"],"answer":0,"explanation":"Cummins showed that the two languages share an underlying proficiency; skills such as predicting, inferring and knowing how texts work transfer. Option B is the discredited ‘separate underlying proficiency’ view.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-390","question":"Consider these statements: I. Chomsky’s language acquisition device helps explain why children everywhere pass through similar stages of language development. II. Skinner explained language development through imitation, reinforcement and habit formation. III. Vygotsky saw language as a social tool that later turns into inner speech and guides thought. IV. Krashen’s ‘acquisition’ is essentially the same as Skinner’s conditioning. Which are correct?","options":["I and III only","I, II and III only","II and IV only","All four: I, II, III and IV"],"answer":1,"explanation":"I, II and III describe the nativist, behaviourist and socio-cultural views correctly. Krashen’s acquisition is a subconscious, input-driven process in the nativist tradition, not habit formation, so IV is false.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-391","question":"Which classroom practice is most consistent with Krashen’s view of errors in a beginner English class?","options":["Correcting every spoken error at once so that the wrong forms are never acquired by the class","Keeping the focus on meaningful communication and leaving error work mainly for edited writing","Teaching the rule for each structure before students are allowed to use it in their own speech","Having students memorise model dialogues until they can say them without any errors"],"answer":1,"explanation":"For Krashen, acquisition comes from understood input in a low-anxiety setting; constant correction raises the filter and only feeds the monitor. Rule-first teaching and dialogue memorisation reflect learning or habit formation.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-392","question":"In the Natural Approach of Krashen and Terrell, a Class 2 learner who answers questions with single words or short phrases such as ‘Yes’, ‘Red one’ and ‘Two mango’ is at the stage of:","options":["Early production","Speech emergence","Intermediate fluency","Pre-production"],"answer":0,"explanation":"Pre-production is the silent comprehension stage; early production has one- or two-word answers and yes/no responses; speech emergence brings longer phrases and simple sentences.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-393","question":"Which of these activities is most likely to promote acquisition rather than learning, in Krashen’s sense?","options":["Underlining all the verbs in a passage and labelling each one’s tense","Converting ten sentences from the active into the passive voice","Memorising the rules for changing direct into indirect speech","Listening to a funny picture story and talking about what happens"],"answer":3,"explanation":"Acquisition happens when attention is on understanding a meaningful message; the other three focus attention on form and rules, which builds conscious learning.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-394","question":"A school in Lucknow introduces a daily 20-minute period in which every child reads a book of her own choice, with no questions, marks or reports afterwards. Krashen would justify this practice mainly because it:","options":["Teaches grammar rules more efficiently than the prescribed textbook and its exercises can","Lets the teacher quietly check each child’s reading level and progress every day","Gives plenty of comprehensible input in a relaxed setting, from which language is acquired","Trains children to apply the monitor carefully to every sentence they read, checking each rule"],"answer":2,"explanation":"Krashen saw free voluntary reading as one of the most powerful sources of comprehensible input, building vocabulary, grammar and spelling. Its value comes precisely from the absence of testing and rule focus.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-395","question":"Which of the following is a well-known criticism of Krashen’s theory of second language acquisition?","options":["Its key constructs, such as acquisition versus learning and ‘i+1’, are hard to test","It gives too much importance to grammar drills and to pattern practice in the classroom","It largely ignores the role that input and exposure play in a learner's language development","It is built on the behaviourist idea that language is a set of habits"],"answer":0,"explanation":"Critics such as McLaughlin argued that ‘acquisition’, ‘learning’ and ‘i+1’ cannot be measured, so the hypotheses are hard to falsify. The other options describe the opposite of Krashen’s position.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-396","question":"A Class 4 child can write a sentence about her family only with help. Her teacher pairs her with a more capable classmate and gives her sentence starters (‘My mother likes…’) that are withdrawn over the next weeks as she gains control. This practice is best described as:","options":["Providing input at i+1, as Krashen suggested","Shaping through reinforcement, as Skinner suggested","Scaffolding within the zone of proximal development","Activating the monitor to edit written output"],"answer":2,"explanation":"Temporary, gradually withdrawn support from a more knowledgeable other, within what the child can do with help, is Vygotskian scaffolding. Krashen’s i+1 concerns input, not assisted performance.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-397","question":"A Class 3 child writes ‘childs’, ‘mouses’ and ‘sheeps’ in a story. Such errors are best classified as:","options":["Interlingual errors caused by transfer from the mother tongue","Intralingual errors caused by overgeneralising an English rule","Performance slips that the child would notice and correct on her own","Spelling errors that point to a problem with hearing"],"answer":1,"explanation":"The child applies the regular ‘-s’ plural rule to irregular nouns, a developmental error within English itself. It shows rule learning in progress, not mother-tongue interference.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-398","question":"Consider these statements about Krashen’s affective filter: I. A high filter can stop comprehensible input from being used for acquisition. II. Motivation, self-confidence and low anxiety help to lower the filter. III. According to Krashen, the filter is generally stronger in young children than in adolescents. Which are correct?","options":["I only","I, II and III","II and III only","I and II only"],"answer":3,"explanation":"Krashen suggested the filter grows stronger around puberty, which helps explain why adolescents are often more self-conscious learners. So III is reversed, while I and II are correct.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-399","question":"Match each of Krashen’s hypotheses with the classroom implication it most directly supports: 1. Input hypothesis 2. Affective filter hypothesis 3. Natural order hypothesis 4. Monitor hypothesis; a. Do not expect a structure to be mastered just because it has been taught b. Keep the classroom relaxed and non-threatening c. Provide plenty of understandable reading and listening d. Give learners time to edit their written work","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d"],"answer":3,"explanation":"Input calls for plenty of comprehensible input, the filter for low anxiety, natural order for not equating teaching with acquisition, and the monitor for using learnt rules while editing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-400","question":"To teach ‘The farmer is ploughing the field’ to Class 3 children in a village in Assam, a teacher shows a picture, mimes the action and quickly gives the Assamese word for ‘plough’. Which evaluation of her practice is most appropriate?","options":["Using Assamese is a mistake, since English must be taught only through English","It makes the input comprehensible and uses the home language as a resource","Miming distracts the children from the language and should be avoided","It is the grammar-translation method, because a translation was given"],"answer":1,"explanation":"Pictures, gestures and a brief home-language gloss make input understandable, and NCF 2005 treats children’s languages as a resource. One gloss does not make a lesson grammar-translation, which centres on rules and written translation.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-401","question":"A Class 4 teacher plans a visit to the local post office. Which sequence will make the visit most useful for learning?","options":["Visit the post office → children write a long essay on it at home → a written test on the essay the next day","Read the textbook chapter → visit the post office → children copy a note dictated by the teacher into their books","Visit without any preparation so that children are surprised by everything they see → a surprise class test on what they remember","Children frame what they want to find out → observe and interview during the visit → share, record and reflect afterwards"],"answer":3,"explanation":"A field visit works when it has a pre-visit stage (purpose and questions), an active visit stage and a post-visit stage of sharing and reflection. The other sequences reduce it to a trip followed by recall.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-402","question":"Class 5 children enjoyed a trip to a dairy farm, but the next week few of them could explain anything they had seen. The most likely reason is that:","options":["the visit had no pre-visit discussion of purpose and no follow-up discussion afterwards","children of this age are still too young to learn much from field visits outside school","a dairy farm is not related to any EVS theme, so children had nothing to connect it to","the visit was too short for the children to see the cows and the milking properly"],"answer":0,"explanation":"Without a purpose before and reflection after, a visit stays an outing. Dairy links to the ‘Food’ theme, and Class 5 children learn well from visits that are properly planned.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-403","question":"Class 5 children survey 30 households in their basti to find which fuel each family uses for cooking: LPG, firewood or cow-dung cakes. Which follow-up question best moves the survey from collecting data to analysing it?","options":["How many families in the basti use LPG, and how many use each of the other two fuels?","Why do some families still use firewood though they know the smoke harms them?","Name the three fuels found in the survey and write one use of each fuel.","Draw an LPG cylinder and a chulha in your notebook and label their parts."],"answer":1,"explanation":"Asking ‘why’ about a pattern in the data calls for reasoning about cost, access and choice: analysis. Counting is recording, naming is recall and drawing is expression.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-404","question":"Before Class 4 children test which substances dissolve in water, the teacher hands out a worksheet with the ‘result’ column already filled in. The main problem with this is that it:","options":["wastes paper that could be used for other activities, since children could simply write in their notebooks","makes the activity too difficult for slower learners, who cannot read the filled-in column","turns the experiment into a confirmation exercise, discouraging real prediction and observation","is against the rule that worksheets must not be used in EVS classes at the primary stage"],"answer":2,"explanation":"If the answers are given, children copy rather than observe, and any surprising observation is treated as an error. Worksheets themselves are fine; it is the pre-filled results that defeat inquiry.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-405","question":"Before soaking moong seeds, a teacher asks Class 3 children to predict what will happen to soaked and dry seeds over three days and to write their guesses. Asking for predictions first mainly helps to:","options":["find out who guesses correctly so that marks can be given for all the right predictions made","make children’s existing ideas explicit so that they can test them against what they see","save time, because children who have predicted need not observe the seeds closely","make the lesson enjoyable and lively, which is the only real purpose of predicting"],"answer":1,"explanation":"A prediction surfaces the child’s current idea and creates a reason to observe; comparing prediction and result is where learning happens. It is not for grading guesses.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-406","question":"To find out whether plants need sunlight, Class 5 children keep one potted plant in sunlight and water it daily, and another in a dark cupboard and water it once a week. After ten days the cupboard plant is wilted. The most serious flaw in this investigation is that:","options":["the plants should have been of different kinds to make the comparison more interesting","the teacher should have done it as a demonstration instead, to save time and avoid mess","the children should have read the answer in the textbook first, so they knew what to expect","more than one condition was changed, so the wilting cannot be put down to darkness alone"],"answer":3,"explanation":"Light and water were both varied, so it is not a fair test. Using different kinds of plants would add yet another variable, which is the opposite of what is needed.","difficulty":"very-hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-407","question":"Class 5 children spend four weeks on ‘Trees of our school’: they choose questions, measure trunk girths, note birds and insects on each tree, interview the gardener and present a booklet. What mainly makes this a project rather than a one-period activity?","options":["It is a long investigation of a real question, planned and done mainly by the children, ending in a shared product","It takes place outside the classroom, in the school grounds, so that learning moves well beyond the four walls of the class","It uses tools such as measuring tapes, notebooks and interviews that ordinary lessons do not use","It is assessed with marks at the end, on the basis of the booklet that each group presents to the class"],"answer":0,"explanation":"Kilpatrick’s project method stresses purposeful, child-directed work on a real problem over time. Going outdoors, using tools or marking can happen in ordinary activities too.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-408","question":"Consider these statements about classroom discussion in EVS: I. It helps children put their ideas into words and revise them. II. The teacher should give the correct answer at the start so that the discussion stays on track. III. Disagreements among children can be used as a resource for learning. Which are correct?","options":["I only","I and II only","I and III only","I, II and III all"],"answer":2,"explanation":"Giving the ‘right answer’ first closes the discussion; differing views are what drive reasoning. Statements I and III describe the role of discussion in EVS.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-409","question":"Class 3 children cut pictures of animals from old magazines and paste them in a scrapbook. The teacher then collects the scrapbooks and gives stars for neatness. The best evaluation of this activity is that it is:","options":["an ideal EVS activity, because children were busy with their hands and clearly enjoyed the work","inappropriate, because cutting and pasting is an art activity and has no place in EVS","complete as it is, since neatness is the main learning indicator for EVS at this stage","hands-on but not minds-on; it needs sorting, questioning or explaining to become learning"],"answer":3,"explanation":"Cutting and pasting can be a good start, but without children grouping animals, asking questions or giving reasons, there is little thinking. Neatness is not an EVS indicator.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-410","question":"Class 4 children role-play a family whose village will be submerged by a new dam. The main learning aim of this role play is to help children:","options":["develop their acting and public speaking skills so that the role play can be staged at the school annual day","understand how displaced people feel and see that development affects different people differently","memorise the names and locations of India's major dams and the rivers on which they are built","conclude that all dams are harmful to people and should therefore be opposed by everyone"],"answer":1,"explanation":"Role play builds empathy and shows several perspectives. Pushing a single conclusion (‘all dams are bad’) would be indoctrination, not EVS.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-411","question":"Class 5 children draw the shape of the moon every night for a month. Later, using their drawings, they say what the moon will look like a week from today. In NCERT’s list of EVS learning indicators, this final step mainly shows:","options":["Observation and recording, through drawing nightly","Classification, through sorting the moon's shapes","Analysis, through predicting from a pattern","Expression, through drawing and describing the moon"],"answer":2,"explanation":"Drawing the moon nightly is observation and recording, but using the records to predict is analysis (predicting, inferring, hypothesising). That is the trap.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-412","question":"Assertion (A): In an EVS experiment, a result that does not match the children’s expectation can be a valuable learning moment. Reason (R): Understanding grows when learners examine why what they observe differs from what they expected. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Mismatch between expectation and observation creates cognitive conflict, which is what pushes children to revise their ideas. R directly explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-413","question":"A government school has only one magnifying glass, and the Class 4 teacher wants all children to observe the parts of a flower. The best approach is to:","options":["show the flower under the glass herself and describe each part clearly and slowly to the whole class","drop the activity, since there are not enough magnifying glasses for every child to use","let small groups take turns, each with a specific thing to look for, and pool their findings","show textbook pictures instead, which are clearer and more detailed than real flowers"],"answer":2,"explanation":"Rotating groups with focused tasks lets every child observe and turns scarcity into collaboration. Demonstration or pictures replace the child’s own observation.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-414","question":"A Class 5 teacher is planning a visit to a temple on a hillside. One child in the class uses crutches. The most appropriate step is to:","options":["leave the child in school with a worksheet on the same topic, so that he does not miss out","choose an accessible site or plan the route and roles so that the child takes part fully","ask the parents to decide whether the child should come, since they know his needs best","cancel the visit altogether so that no child in the class feels left out or different"],"answer":1,"explanation":"Inclusion means planning so that every child participates, not excluding one child or depriving everyone. Leaving the decision to parents avoids the teacher’s responsibility to adapt.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-415","question":"Class 4 children will interview a local mason about how houses are built. Which preparation is most important?","options":["The teacher writes all the questions in advance so that nothing goes wrong on the day","Children memorise the answers the mason is likely to give, so the interview runs smoothly","Children read the textbook chapter thoroughly so that they need not ask much","Children discuss in groups what they want to find out and frame their own questions"],"answer":3,"explanation":"Children’s own questions give the interview purpose and build questioning skill. If the teacher writes the questions or children ‘pre-learn’ answers, the inquiry is lost.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-416","question":"Class 5 children survey their own classmates about their favourite food and conclude, ‘Children of India like noodles best.’ The teacher’s most useful response is to:","options":["discuss whether a conclusion about 40 classmates can be stretched to all children in India","accept the conclusion, since the data were collected honestly and counted correctly","say that noodles are junk food, so the survey result must be wrong and should be changed","ask them to repeat the same survey in the same class to make sure that the result is really reliable"],"answer":0,"explanation":"The flaw is over-generalising from a small, particular group. Repeating it in the same class keeps the same bias, and judging the food misses the reasoning issue.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-417","question":"Which sequence best reflects experiential learning in a Class 4 EVS lesson on houses?","options":["The teacher lists the properties of mud, brick and cement, and children copy them neatly into their notebooks","Children build a mud house model, test it under sprinkled ‘rain’, think about why it fell and redesign it","Children watch a video on different kinds of houses and then answer ten objective questions","Children learn a poem about houses by heart and recite it together at the morning assembly"],"answer":1,"explanation":"Doing, observing, reflecting and trying again is the experiential cycle (Dewey, Kolb). The others are transmission or recall.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-418","question":"A Class 4 teacher invites a local basket weaver, who shows how baskets are made, and then children try weaving with paper strips. From an EVS point of view, the most important outcome is:","options":["early vocational training so that the children can earn a living from this craft later on in life","producing baskets of good quality that can be sold at the school fair to raise funds","a grade in art education for the neatness and design of the woven paper strips","respect for the skill and work of artisans, and an understanding of the materials they use"],"answer":3,"explanation":"‘Things We Make and Do’ aims at valuing work and workers and understanding materials and processes. It is not vocational training or a sales activity.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-419","question":"Class 3 children predict that a large log will sink and a small iron nail will float, because ‘heavy things sink and light things float’. Testing shows the opposite. The teacher’s best next step is to:","options":["write the definition of density on the board for children to copy and learn by heart","tell them their prediction was wrong and give them the correct scientific answer straight away","ask why their prediction failed, and let them test big and small pieces of one material","move on, since floating and sinking is too difficult a topic for Class 3 children"],"answer":2,"explanation":"Testing big and small pieces of the same material challenges the ‘heavy sinks’ idea with fresh evidence; asking ‘why’ invites revision. A copied definition does not change the underlying idea.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-420","question":"Which of the following is NOT a strength of using surveys in primary EVS?","options":["Children learn to collect and record information from people around them","Surveys give exact conclusions that are true for society everywhere","Children learn to organise data in tables and simple graphs","Surveys connect classroom learning with the community"],"answer":1,"explanation":"A small class survey describes only the group surveyed; claiming universal truth is a misuse. The other three are real benefits.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-421","question":"A teacher says, ‘Since EVS is activity-based, I will not intervene at all. Children must discover everything on their own.’ The best critique of this view is that:","options":["unguided discovery can leave misconceptions in place; the teacher should guide with questions and scaffolding","the teacher should instead explain everything first and only then give activities to confirm it","activities are useful only for children who are already good at EVS and can work on their own","the statement is correct, because constructivism forbids any form of teacher intervention in children's learning"],"answer":0,"explanation":"Constructivism does not mean leaving children alone; Vygotskian scaffolding and guided questioning help children reach ideas they would not reach unaided. Telling everything first is the opposite error.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-422","question":"During EVS group work on measuring rainfall, a teacher notices that one confident child does all the work while others watch. The most effective strategy is to:","options":["make the confident child work alone from now on so that the others in the group finally get a fair chance to do the work","let the groups continue as they are, since the task is getting done and the results are correct","replace group work with individual worksheets so that every child has to do the measuring","give each member a role such as measurer, recorder or reporter, rotate the roles, and check individual contributions"],"answer":3,"explanation":"Defined, rotating roles and individual accountability are the standard ways to make cooperative learning work. Removing group work loses the benefits of cooperation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-423","question":"Two plates with equal water are kept, one in the sun and one in shade. The plate in the sun dries first, and a child concludes, ‘The sun destroys the water.’ The teacher’s best next step is to:","options":["tell the child the word ‘evaporation’ and ask her to learn its textbook definition by heart for the next test","ask where the water could have gone, and let children hold a cold lid over warm water to see drops form","praise the conclusion, since the water did disappear and the child observed it correctly","tell the child that the conclusion is wrong and move on to the next topic in the chapter"],"answer":1,"explanation":"The child holds the idea that water vanishes. An experience in which the ‘lost’ water reappears as droplets challenges it directly, which a new word alone cannot do.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-424","question":"Match each EVS method with its main purpose: 1. Survey 2. Field visit 3. Experiment 4. Role play. a. Testing a prediction under controlled conditions. b. Collecting information from many people. c. Understanding the feelings and viewpoints of others. d. Observing directly in a real setting.","options":["1-d, 2-b, 3-a, 4-c","1-b, 2-a, 3-d, 4-c","1-b, 2-d, 3-a, 4-c","1-c, 2-d, 3-a, 4-b"],"answer":2,"explanation":"Surveys gather information from many people, field visits allow direct observation, experiments test predictions, and role play builds empathy.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-425","question":"Class 5 children grow a kitchen garden over two months as an EVS project. Which evidence best shows what they have learnt?","options":["Their dated observations, the questions they raised and their explanations of changes in a project file","The final height and yield of the plants, which show how well the garden was looked after","How neat, complete and colourful the project file is when it is handed in at the end","Praise from the parents who visited the garden and saw the healthy, well-watered and flowering plants for themselves"],"answer":0,"explanation":"Learning shows in the process: records, questions and reasoning over time. Plant height depends on soil and weather; neatness and praise say little about understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-426","question":"A Class VII teacher in Hyderabad takes her section to Golconda Fort. Last year's trip to the same fort became a picnic and students learnt little. What single change would most turn the visit into a learning experience?","options":["Take a larger group this time so that more students benefit from seeing the fort in person","Give students guiding questions and observation tasks before the visit and hold a follow-up discussion","Hire a trained guide so that students hear the full history of the fort in one long and detailed lecture","Allow students to photograph whatever they like during the visit and submit the photos later"],"answer":1,"explanation":"A field trip teaches when it is planned around questions before, focused observation during, and analysis after the visit. A guide's lecture or a free photo collection keeps students passive or aimless.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-427","question":"After a visit to the vegetable mandi, Class VII students compare the wholesale price of tomatoes they recorded with prices at a shop near the school and discuss why the two differ. This post-visit task mainly develops the ability to:","options":["recall the names of all the vegetables sold in the mandi on that day","draw an accurate, labelled sketch of the layout of the mandi","analyse observations and link them to the concept of a chain of markets","memorise the definition of a wholesale trader for the next class test on markets"],"answer":2,"explanation":"Comparing data from two points in the chain and explaining the gap turns raw observation into conceptual understanding of how goods pass through traders. The other options stay at recall or description.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-428","question":"Which of the following statements about project work in social science are correct?\n1. A good project arises from a question that is real and meaningful to the students.\n2. The teacher should complete the difficult parts so that the final product is of good quality.\n3. Assessment should consider planning, data collection and teamwork, not only the final chart or report.","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"Projects work when students own a meaningful question and when the process is assessed alongside the product. A teacher doing the hard parts takes away the very learning the project was meant to create.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-429","question":"Class VII students in Nagpur talk with their teacher and decide that they want to find out where the water in their homes comes from and why some lanes get less. In Kilpatrick's project method, this stage is called:","options":["Planning","Purposing","Executing","Judging"],"answer":1,"explanation":"Kilpatrick's stages are purposing, planning, executing and judging. Choosing what to find out and why it matters is purposing; deciding how to collect information comes next, under planning.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-430","question":"During a Class IX discussion on 'Should a factory be set up near our village?', four confident students do all the talking while most others stay silent. What is the best step for the teacher?","options":["End the discussion and give a lecture listing the pros and cons of the factory for the village","Let the four students continue, since they clearly know the topic and keep the whole discussion moving along","Give marks only to students who speak, so that the silent ones are pushed into talking","Set ground rules, move into small groups with assigned roles, and bring each group's view to the class"],"answer":3,"explanation":"Structured small groups with roles such as recorder and reporter widen participation, and ground rules make it safe to speak. Marking speech pressures anxious students without helping them, and a lecture abandons discussion altogether.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-431","question":"Assertion (A): At the end of a class discussion on whether mobile towers should be allowed on school roofs, the teacher should summarise the different viewpoints rather than declare one side the winner.\nReason (R): The purpose of a classroom discussion is to deepen understanding of an issue, not to defeat opponents.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Discussion, unlike a competitive debate, aims at shared understanding of the reasons behind different positions. That purpose is precisely why the teacher closes by drawing views together rather than announcing a winner.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-432","question":"Class VIII students role-play a court hearing in which a construction worker claims unpaid wages. Which step after the performance matters most for learning?","options":["Debriefing: discussing what happened, how each character felt and how it links to courts and the right to justice","Giving marks for acting and dialogue delivery so that students take all future role plays in class much more seriously","Repeating the performance at the annual function so that parents can also see what was learnt","Moving on to the next chapter, since the role play has already covered the topic of courts fully"],"answer":0,"explanation":"Role play generates experience; the debrief turns that experience into understanding by linking it to concepts. Without it the activity remains a performance, however lively.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-433","question":"A Kendriya Vidyalaya organises a youth parliament in which Class IX students introduce a bill, debate it and vote. What does this simulation mainly help students learn?","options":["The names and portfolios of current Union ministers and their many departments","How laws are made, and the democratic skills of debate, listening and voting","How to win elections by making persuasive promises to voters in a campaign","The exact text of the rules of procedure followed in the Lok Sabha"],"answer":1,"explanation":"A simulation gives first-hand experience of a process, here law-making, along with democratic habits such as argument and respect for the majority decision. Names of office-holders or verbatim rules are recall, not what the simulation is for.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-434","question":"A teacher in a Rajasthan village school plans a role play on untouchability for Class VIII. Several children in the class belong to Dalit families. Which precaution is most important?","options":["Assign roles strictly by lottery so that no one can complain of any bias or favouritism shown by the class teacher","Ask the Dalit children to play the victims, since they can act the part most realistically and with feeling","Avoid casting any child in a role that mirrors or mocks their own identity, and debrief on dignity and rights","Cancel the role play altogether and only read the chapter aloud to avoid any risk of hurt"],"answer":2,"explanation":"Role play on discrimination can hurt children whose own lives it touches. Thoughtful casting and a debrief centred on dignity keep the activity safe; a lottery could still put a child in a painful role, and cancelling loses a powerful method.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-435","question":"A teacher asks, 'What is fair?' A student answers. The teacher then asks, 'Would it be fair if everyone got the same tiffin, even the child who had no breakfast?' and keeps probing until students refine their idea of fairness. Which method is she using?","options":["Inductive method of teaching","Lecture method","Drill method","Socratic questioning"],"answer":3,"explanation":"Socratic questioning uses a chain of probing questions that exposes gaps in an answer and leads learners to sharper ideas. The inductive method moves from examples to a rule, which is not what is happening here.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-436","question":"Which evaluation of the lecture method in social science is the most balanced?","options":["It should never be used in social science, because it is always teacher-centred and one-way","It is the best method for social science, because it covers the long syllabus fastest of all","It is useful for setting context or narrating, but used alone leaves learners passive, so it needs active methods too","It is suitable only for the primary classes, where children cannot yet read and understand the textbook by themselves"],"answer":2,"explanation":"A short lecture can set context, tell a story or clarify a difficult idea. The problem lies in relying on it alone, which makes students passive listeners. Rejecting it outright is as one-sided as praising it for speed.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-437","question":"A Class VI teacher narrates the life of a Gupta ruler as a vivid story, adding imagined conversations in the court. What should she do to keep it a sound history lesson?","options":["Point out which parts rest on evidence such as inscriptions and coins and which are her own reconstruction","Avoid stories altogether, since imagined details have no place at all in a history lesson","Tell students that every detail is true, so that they take the story and the ruler seriously","Ask students to memorise the court dialogues, since they will surely be asked about them in the coming test"],"answer":0,"explanation":"Storytelling engages young learners, but history depends on evidence. Marking the line between what the sources tell us and what is imagined builds early historical thinking, and banning stories gives up a strong tool.","difficulty":"very-hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-438","question":"Class VII students survey 30 households in their basti about the fuel used for cooking, put the results in a table and write what they notice. Which skill does this activity develop most?","options":["Reading maps using scale and direction","Collecting, organising and interpreting data","Arranging historical events in chronological order","Judging the reliability of an ancient inscription"],"answer":1,"explanation":"A survey trains students to gather data, tabulate it and draw inferences, which are core social science skills. The other options are real skills too, but they belong to geography mapping or history, not to this task.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-439","question":"Assertion (A): Accounts collected from elderly people in the locality are valuable sources for writing local history.\nReason (R): Oral accounts are always more accurate than written records, because they come from people who were present.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":3,"explanation":"Oral history captures voices that written records often leave out, which makes it valuable. But memory can be selective or altered over time, so oral accounts must be checked against other sources; R is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-440","question":"A Class IX teacher divides 'Forest Society and Colonialism' into four parts. Each student in a group of four studies one part with members of other groups who have the same part, then returns and teaches it to the home group. This strategy is:","options":["Think-pair-share","Brainstorming","Jigsaw","Fishbowl"],"answer":2,"explanation":"In jigsaw, each member becomes an 'expert' on one piece by meeting the other experts, then teaches the home group, so every member depends on every other. Think-pair-share and fishbowl do not divide content this way.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-441","question":"A Class VI teacher opens with, 'Why were so many early cities built beside rivers?' Students then examine maps, pictures of archaeological sites and short readings to build and test their explanations. This lesson follows which approach?","options":["Inquiry-based learning","Expository teaching","Programmed instruction","Rote learning through repetition"],"answer":0,"explanation":"The lesson starts with a genuine question, and students gather and weigh evidence to construct an answer, which is the core of inquiry-based learning. In expository teaching the teacher gives the explanation directly.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-442","question":"To teach credit, a Class X teacher uses the detailed account of a small farmer in Andhra Pradesh who borrows from a moneylender, the terms of the loan and what happens after a crop failure. What is the main strength of this case study method?","options":["It covers a large number of facts about credit in a short time, so that the long syllabus moves faster","It removes the need to discuss general concepts of credit, since the story says everything","It ensures that every student reaches the same conclusion about moneylenders and banks","It gives a concrete, in-depth situation from which students draw general ideas about credit and debt"],"answer":3,"explanation":"A case study gives a real context in depth, letting students examine causes and consequences and then generalise to concepts such as collateral and terms of credit. The concepts still have to be drawn out; the case does not replace them.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-443","question":"Which of the following statements about organising a field trip are correct?\n1. The teacher should visit the site beforehand where possible.\n2. Students should go with specific tasks to observe and record.\n3. A field trip is complete once students return safely to school.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"A preliminary visit and clear observation tasks make the trip purposeful. Statement 3 is wrong because the follow-up, where observations are discussed and connected to concepts, is an essential part of the trip.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-444","question":"A Class VIII teacher shows two newspaper reports of the same farmers' protest. One headline reads 'Farmers block highway, commuters suffer'; the other reads 'Farmers demand fair price for crops'. What is the main learning objective?","options":["To teach students that newspapers are biased and should never be used as sources in class","To help students find out which of the two newspapers is the more popular and widely read","To make students see that word choice and focus reflect a perspective, and to read news critically","To prove that one of the two newspapers is printing false news about the protest and should be avoided"],"answer":2,"explanation":"Both headlines may be factually accurate yet frame the event differently. Comparing them builds media literacy and an awareness of perspective, a key critical-thinking aim of social science, without reducing the lesson to 'true versus false'.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-445","question":"In a Class IX project on 'Changes in our town's livelihoods', one student did all the work while three group members signed the report. Which redesign would best prevent this next time?","options":["Ban group projects and give only individual written tests, since only they show each student's own work clearly","Give each member a defined role, ask for a process diary, and add peer assessment and a short viva","Give the whole group the same marks so that the members learn to share responsibility fairly","Ask parents to sign a form certifying that their child contributed equally to the project"],"answer":1,"explanation":"Clear roles, a record of the process and individual accountability through peer review and a viva make each student's contribution visible. Identical group marks reward free-riding, and banning projects throws away their value.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-446","question":"Class VIII students investigating 'Why is the lake in our town shrinking?' list possible reasons: less rainfall, construction on its banks, and too many borewells nearby. In the problem-solving method, this step is:","options":["Identifying the problem","Collecting data","Drawing conclusions","Forming hypotheses"],"answer":3,"explanation":"Possible explanations proposed before evidence is gathered are hypotheses. The problem was already identified, and data collection will now test which of these reasons holds.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-447","question":"A Class VI teacher spends three periods having students colour the states of India on outline maps with crayons. Which critique of this activity is the most accurate?","options":["It is ideal as it is, since any activity that keeps children's hands busy makes learning child-centred and enjoyable for them","It lacks a thinking purpose; it would gain value if students, say, located states and asked why some are larger or have more rivers","Colouring maps is harmful because it wastes time, and it should be banned from social science altogether","Maps should be introduced only in Class IX, when students are old enough to understand scale, direction and map projection properly on their own"],"answer":1,"explanation":"Activity-based learning needs a cognitive purpose; hands busy is not the same as minds active. Tying the map work to questions turns colouring into geographical thinking, without throwing away a useful tool.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-448","question":"Which of the following pairs of a teaching method and its main use in social science are correctly matched?\n1. Role play – experiencing a situation from another person's viewpoint\n2. Field trip – first-hand observation of places, people and processes\n3. Brainstorming – testing a hypothesis against collected evidence\n4. Debate – examining opposing arguments on an issue","options":["1, 2 and 4 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Brainstorming generates many ideas quickly without judging them; testing hypotheses against evidence belongs to the problem-solving or inquiry method. The other three pairs are correctly matched.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-449","question":"A Class VII teacher in Assam asks students to interview a local weaver about how she buys yarn, how long a mekhela chador takes and who buys it, then to compare her earnings with the final selling price. Which aim of economics teaching does this best serve?","options":["Memorising the definition of the putting-out system accurately so that it can be written word for word in the examination","Understanding production and markets through a real producer's experience, and asking who gains at each stage","Learning to weave from her so that students gain a vocational skill they can later use to earn a living","Finding out which state of India produces the most silk and where it is exported"],"answer":1,"explanation":"Interviewing a producer and comparing her earnings with the selling price connects economic ideas to lived experience and raises questions of fairness in the chain. Learning the craft or memorising terms misses that purpose.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-450","question":"A teacher drops a cricket ball and a much lighter rubber ball of the same size together from the first-floor balcony; they land together. Pooja still says, 'The cricket ball fell faster, it was just too quick to see.' Her reaction best illustrates that:","options":["Prior ideas are robust, and learners may reinterpret evidence to fit what they believe","The demonstration was faulty, since heavier objects really do fall faster when dropped together","Pooja lacks the intelligence needed for physics at this stage and should not be pressed further","Demonstrations confuse children and should be avoided in science in favour of textbook reading"],"answer":0,"explanation":"Misconceptions resist change; a single demonstration may not create real dissatisfaction, so the teacher needs repetition with careful observation, discussion and a plausible alternative idea. Air resistance is negligible here, so the balls do land together.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-451","question":"According to the conceptual change model, which conditions are needed for a student to give up 'the bulb uses up current' in favour of 'current is the same all round the circuit'? 1. She is dissatisfied with her existing idea. 2. The new idea is intelligible to her. 3. The new idea appears plausible. 4. The new idea is fruitful in explaining new situations. 5. The teacher declares the old idea wrong.","options":["1, 2 and 5 only","2, 3 and 4 only","All five: 1, 2, 3, 4 and 5","1, 2, 3 and 4 only"],"answer":3,"explanation":"Posner and colleagues named dissatisfaction, intelligibility, plausibility and fruitfulness as the conditions for conceptual change. An authority simply declaring the old idea wrong does not by itself change it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-452","question":"On a winter morning, Class 7 students say the school's iron gate is 'colder' than the wooden door beside it. Which statement should the teacher help them arrive at, after measuring with a thermometer?","options":["The iron gate is at a lower temperature, because metals always stay colder than wood in winter","Both are at about the same temperature; iron feels colder as it conducts heat from the hand faster","Iron attracts cold from the surrounding air at night, while the wood keeps the cold out of its fibres","The wood produces a little heat of its own, so it is always warmer than the iron gate"],"answer":1,"explanation":"Objects left in the same surroundings reach the same temperature. Metal feels colder because it is a better conductor and draws heat from the skin faster; 'cold flowing in' is a common misconception.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-453","question":"A student explains that it is summer in India in May because the earth is then closest to the sun. Which fact, brought into discussion, would create the strongest conflict with her idea?","options":["The sun rises in the east and sets in the west in every season","The moon also goes round the earth once in about a month","When it is summer in India, it is winter in Australia","The earth takes about 365 days to go round the sun"],"answer":2,"explanation":"If distance from the sun caused summer, both hemispheres would have summer together. Opposite seasons in the two hemispheres point to the tilt of the earth's axis instead.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-454","question":"After stirring sugar into water, many Class 6 students say the sugar has 'disappeared', so the solution must weigh less than the water and sugar did before. Which activity directly tests their claim?","options":["Tasting the solution to show that the sugar is still present in the water","Weighing the water and the sugar separately, mixing them, and weighing the solution","Heating the solution until the water evaporates to show that sugar can be recovered","Telling them that matter can neither be created nor destroyed in any change"],"answer":1,"explanation":"Their claim is about mass, so weighing before and after gives direct evidence that the mass is unchanged. Tasting shows the sugar is present but does not address the claim about weight.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-455","question":"A student writes, 'Sugar melts in hot tea.' What is the most appropriate teacher response?","options":["Accept it, because the exact word does not matter as long as the student's underlying idea about sugar is right","Mark it wrong and ask the student to write the word 'dissolves' ten times in the notebook so that the correct term sticks","Explain that sugar melts only in hot tea and not in cold water, so the sentence is correct","Contrast it with heating sugar alone in a pan, where it does melt, so the student sees that dissolving is different"],"answer":3,"explanation":"Everyday language hides a real conceptual confusion between melting (a change of state on heating) and dissolving (mixing into a solvent). Experiencing both makes the difference meaningful; drill or ignoring it does not.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-456","question":"Students believe that the water droplets outside a glass of iced water have seeped through the glass. Which change to the activity would best test this idea?","options":["Colouring the water inside with ink and checking whether the outside droplets are coloured","Using a bigger glass with more ice so that more droplets form and are much easier for all to see","Wiping the glass dry and asking students to watch the outside more carefully this time","Repeating the activity on a hotter day, when the droplets form more quickly"],"answer":0,"explanation":"If water were seeping through, the droplets would carry the ink's colour; clear droplets show they came from water vapour in the air. The other changes do not distinguish between the two explanations.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-457","question":"Assertion (A): Plants respire both during the day and at night. Reason (R): In bright daylight, the gas exchange of photosynthesis is much larger than that of respiration and masks it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Plants respire all the time because every living cell needs energy; that is why A is true. R is also true, but it explains why respiration seems to stop in daytime (the common misconception), not why plants respire.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-458","question":"Children in a Class 6 class say that 'heavy things sink and light things float'. Which pair of objects, tried in a tub of water, would best challenge this idea?","options":["A plastic button and a large smooth pebble","A light feather and a heavy steel coin","A big wooden log and a small iron nail","A dry leaf and a heavy glass marble"],"answer":2,"explanation":"The heavy log floats and the light nail sinks, which contradicts 'heavy sinks'. The other pairs fit the children's rule and would only confirm the misconception.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-459","question":"A student believes that we see objects because something goes out of our eyes to the objects. Which experience would most directly challenge this idea?","options":["Looking at a small object closely through a magnifying glass in good light","Comparing how far away different students can read the small letters on an eye chart","Drawing and labelling a neat diagram of the human eye and all its parts","Sitting in a completely dark room with eyes wide open, trying to see objects"],"answer":3,"explanation":"If seeing depended only on something leaving the eye, open eyes would see in the dark. Failing to see shows that light must come from the object (or a source) into the eye.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-460","question":"Several students explain the phases of the moon as 'the earth's shadow falling on the moon'. Which teaching approach would best address this?","options":["Telling them that the shadow explanation is correct but applies only to some of the phases","Using a lamp, a ball on a stick and each student's head as the earth to model the moon's positions","Showing photographs of the full moon and the new moon and asking them to note the difference between the two","Asking students to memorise the names of the eight phases in their correct order"],"answer":1,"explanation":"Moving the ball round one's own head in lamplight shows the lit part seen from the earth changing with position, without the earth's shadow being involved. The shadow idea actually explains a lunar eclipse.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-461","question":"Many students in a class call a spider an insect and a whale a fish. The best strategy to address both errors is to:","options":["Have students list the defining features of each group (body parts, legs, breathing, feeding young) and test the animals","Give students a long list of correct examples of insects, spiders, fish and mammals to learn by heart","Tell students that spiders and whales are simply exceptions to the usual rules of classification and need not be explained","Show pictures of spiders and whales and simply tell students which group each belongs to"],"answer":0,"explanation":"Both errors come from judging by surface features (small and crawling, lives in water). Classifying by defining characteristics builds the right criteria, which then transfer to new animals.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-462","question":"A teacher has to give a demonstration to a class of 48 students. Which plan reflects good demonstration practice?","options":["Performing it quickly at the teacher's table while students copy the notes written on the board to save time","Performing it while students watch silently and carefully, and then explaining the result afterwards","Placing it where all can see, asking for predictions, letting some students handle it, and discussing the result","Showing it only to the front rows, since the students at the back can read about it in the textbook at home later"],"answer":2,"explanation":"A good demonstration is visible to all, engages thinking through prediction and student participation, and ends with discussion. A silent show with explanation afterwards turns students into passive spectators.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-463","question":"For a Class 8 class, which of the following is better done as a teacher demonstration than as individual student lab work?","options":["Testing household substances with turmeric paper","Testing whether materials conduct electricity with a cell and bulb tester","Germinating seeds on moist cotton","Showing the reaction of a small piece of sodium with water"],"answer":3,"explanation":"Sodium reacts violently with water, so safety demands that only the teacher handle it in a controlled way. The other activities are safe and are best done by students themselves.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-464","question":"While preparing safety rules for the Class 8 laboratory, a teacher drafts four instructions. Which one is unsafe and must be removed?","options":["Smell a substance by gently wafting its vapour towards the nose","Always add water slowly to concentrated acid while diluting it","Never taste any chemical in the laboratory","Point the mouth of a test tube being heated away from yourself and others"],"answer":1,"explanation":"To dilute an acid, the acid is added slowly to water with stirring; adding water to concentrated acid can make it boil and splash. The other three are standard safe practices.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-465","question":"A teacher's lab worksheet lists every step and also states the result students are 'supposed to get'. Which single change would best turn it into an inquiry activity?","options":["Adding more detailed steps so that students make fewer mistakes and reliably get the right result","Asking students to copy the expected result into their notebooks before they start","Removing the expected result, posing a question, and asking students to predict and then explain","Doing the activity as a teacher demonstration so that the result is certain and quick"],"answer":2,"explanation":"Stating the answer in advance turns practical work into confirmation. Posing a question and asking for prediction and explanation makes students reason from evidence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-466","question":"To assess students' practical skills, such as handling apparatus and taking readings, the most valid method is:","options":["Marking only the neatness and completeness of each student's written practical record","A written test asking students to list the steps of each experiment in order","An oral quiz on the names and uses of the laboratory apparatus","Observing students while they perform the task, using a checklist or rating scale"],"answer":3,"explanation":"Skills are shown in performance, so they are validly judged by observing the performance against clear criteria. Written records and quizzes measure recall, not skill.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-467","question":"A Class 7 class decides to set up a vermicompost pit in the school garden and plans the materials, roles and timeline. Following the project method, what should come next?","options":["Executing the plan, and then judging the work and the result","Judging the plan, and then purposing a new project","Purposing again to make sure all students agree","A written test on vermicompost, followed by executing the plan"],"answer":0,"explanation":"The project method runs through purposing, planning, executing and judging (evaluating). Having purposed and planned, the class must carry out the plan and then review it.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-468","question":"A teacher lets students test an iron nail, a copper wire and aluminium foil (all conduct) and a plastic scale and a wooden stick (neither conducts). Students conclude that metals conduct electricity, and then predict whether a steel spoon will conduct. The lesson moved:","options":["From deductive to inductive reasoning","From inductive to deductive reasoning","Only by deductive reasoning throughout","Only by rote learning of the rule"],"answer":1,"explanation":"Generalising from particular cases to a rule is induction; applying the rule to a new case (the steel spoon) is deduction. Good science lessons often use both in this order.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-469","question":"A teacher uses a bell jar model, with balloons for lungs and a rubber sheet for the diaphragm, to teach breathing. Which follow-up best prevents the model from creating new misconceptions?","options":["Telling students that the model works exactly as the body does, so that they can trust every part of it fully","Not showing the model again, as models only confuse learners once the idea is explained","Letting students play freely with the model without any discussion, so they discover it alone","Asking which parts correspond to the body and where the model differs, e.g. the rigid jar unlike the rib cage"],"answer":3,"explanation":"Models help visualise, but learners may take every feature literally. Mapping the parts and discussing the model's limits keeps the useful idea and prevents new errors.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-470","question":"A teacher plans a field visit to a village pond with Class 7. Which plan is most likely to lead to learning?","options":["A visit with no preparation at all, so that students are not biased by what they expect to see there","A visit where the teacher explains everything about the pond while the students listen quietly and walk around it with her","Preparing questions and recording sheets beforehand, collecting data at the pond, and discussing findings in class","A visit followed by an essay on 'My trip to the pond', marked for language and neatness"],"answer":2,"explanation":"A field trip teaches well when it has a purpose (pre-visit), active observation and recording (visit) and sense-making afterwards (post-visit). Unprepared outings or lecture-walks make it a picnic.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-471","question":"A diagnostic test shows that many Class 8 students confuse mass and weight. The most appropriate remedial step is to:","options":["Repeat the same lecture more slowly and loudly, so that every student can follow each definition this time around","Give extra homework with the definitions of mass and weight to copy out several times","Use a new approach, such as comparing spring balance readings with the object's mass and discussing what changes on the moon","Move on to the next chapter for now and revisit the topic just before the final examination as part of the general revision plan"],"answer":2,"explanation":"Remedial teaching targets the specific difficulty found in diagnosis and uses a new, more concrete approach. Repeating the same explanation that failed rarely helps.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-472","question":"Which question best assesses the application of knowledge rather than recall, after a Class 7 lesson on thermometers?","options":["What is the range of a clinical thermometer, in degrees Celsius?","Name the liquid used in most clinical and laboratory thermometers.","What is the normal temperature of the human body, in degrees Celsius and Fahrenheit?","Why does a clinical thermometer have a kink, while a laboratory one does not?"],"answer":3,"explanation":"Explaining why the kink suits clinical use (it stops the mercury falling back before the reading is taken) requires relating structure to function. The other questions can be answered from memory.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-473","question":"When students in a Class 6 class are asked why things fall, many write 'because of air pressure pushing them down'. The teacher's first step should be to:","options":["Find out what experiences and reasoning lie behind this idea before planning activities","Mark the answer wrong and give the correct textbook answer for students to learn","Ignore the answer, since gravitation is taught properly only in the higher classes","Tell students firmly that air has nothing at all to do with motion or with falling objects"],"answer":0,"explanation":"Constructivist teaching begins by probing the reasoning behind a misconception so that the teacher can design experiences that challenge it. Simply marking it wrong leaves the reasoning untouched.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-474","question":"In which situation is a teacher using the heuristic approach, in the spirit of its original proposal?","options":["Explaining the working of an electric bell step by step with the help of a labelled wall chart","Giving students a dry cell, wire and nail to find out how to make the nail attract pins, with hints only when stuck","Showing a video on electromagnets, followed by a question-answer session on what was seen","Asking students to read the textbook section on electromagnets carefully and then summarise it in their own words"],"answer":1,"explanation":"In the heuristic approach the learner is put in the position of a discoverer and finds things out by her own effort, with the teacher giving minimal guidance. The others transmit ready-made knowledge.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-475","question":"In a Class V EVS lesson in Guwahati, Pranjal explains why the pond dried up partly in Assamese, mixing in a few English words from the textbook. What is the most appropriate response from the teacher?","options":["Tell Pranjal to repeat his answer only in English, since both the textbook and the final exam are in English","Value his reasoning, accept the mixed answer, then help the class say the key idea in English too","Accept the answer but give him lower marks for not using English, so he tries harder next time","Ignore the content of his answer and focus on correcting his English pronunciation and grammar"],"answer":1,"explanation":"Using all of a child's languages (translanguaging) lets him show real understanding; the teacher then builds the school-language version from it. Rejecting or penalising the home language suppresses thinking and participation.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-476","question":"Consider the following statements about language in education under NEP 2020: 1. Wherever possible, the medium of instruction until at least Grade 5, and preferably till Grade 8 and beyond, should be the home language, mother tongue, local language or regional language. 2. NEP 2020 bans the teaching of English as a subject in all schools until Grade 8. 3. Under the three-language formula, no language will be imposed on any State. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"NEP 2020 recommends the home or local language as medium and keeps the three-language formula flexible with no imposition. It does not ban English as a subject, so statement 2 is false.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-477","question":"A Class III teacher in a Delhi resettlement colony has children whose home languages are Bhojpuri, Bengali, Punjabi and Haryanvi. Which strategy best treats this diversity as a resource?","options":["Use only the language spoken by the majority of children, so that the largest group learns the most","Use only English in the classroom, so that no child's home language gets an unfair advantage over another","Invite children to share words, songs and stories in their languages, compare how each says the same idea, and build a word wall","Seat children in fixed language groups for the whole year so that each group can work comfortably together in its own home language"],"answer":2,"explanation":"Comparing languages builds metalinguistic awareness and makes every child's language visible and valued. Picking one language, imposing English, or segregating children by language each excludes or isolates some learners.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-478","question":"Assertion (A): Forbidding children to speak their home language from the first day of school is the quickest way to make them proficient in the school language. Reason (R): A new language is acquired mainly through understandable input in meaningful contexts.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Input in a language children do not yet understand is not comprehensible, so a home-language ban slows rather than speeds learning, and harms confidence. R states the accepted principle, which actually argues against A.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-479","question":"Fatima joined an English-medium Class I in Bengaluru from a Dakhini-speaking home. For six weeks she has spoken almost no English, though she follows instructions, points and joins in actions. What is the most appropriate step for the teacher?","options":["Treat it as a normal silent period, keep up rich input with gestures and pictures, and accept gestures and home-language replies","Make Fatima answer one question in English aloud every day in front of the class so that she is forced to break her silence soon","Note in her record that she may have a learning disability and refer her for a formal assessment","Seat her with the slowest group until she starts speaking English, so that she is not under pressure"],"answer":0,"explanation":"Many second-language learners go through a silent period in which they are absorbing the language; following instructions shows comprehension is growing. Forcing speech or labelling her raises anxiety and is a misdiagnosis.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-480","question":"Children of a Class II class in Koraput make a picture dictionary in which each page shows a drawing with the word in Desia (their home language), Odia and English. What is the main pedagogical value of this activity?","options":["It replaces the need to teach Odia and English separately, since all three appear on one page","It mainly improves children's drawing and colouring skills, which matter most in Class II","It helps the teacher finish the textbook vocabulary list faster by covering all three languages together on each page","It bridges from the known home language to the school languages, using children's own knowledge and experience"],"answer":3,"explanation":"Linking the same concept across languages lets children map new words onto meanings they already have, which is the essence of bridging in multilingual education. It supports, not replaces, systematic language teaching.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-481","question":"In the Anganwadi's play corner set up as a vegetable market, the teacher joins in as a customer and asks, 'I need two tomatoes and three onions. How many vegetables is that?' This is best described as:","options":["guided play, where the teacher enters the play to extend thinking without taking over","free play, because the children chose the market theme themselves and the teacher only joined in as a customer","a formal mathematics lesson disguised as play, which spoils the play and should be avoided","teacher-directed instruction, which is not appropriate in the foundational stage at all"],"answer":0,"explanation":"Guided play keeps the child's agency and the play context while the adult scaffolds learning goals (here, combining quantities). It is neither unstructured free play nor direct instruction.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-482","question":"Consider the following statements about play-based learning in the foundational stage: 1. Play supports physical, cognitive, language, social and emotional development together. 2. Play-based learning means children play all day without any planning by the teacher. 3. Both free play and teacher-planned, structured play have a place in the curriculum. Which of these are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Play-based pedagogy is deliberately planned: the teacher designs materials, spaces and guided activities alongside free play. So statement 2 misreads the idea; 1 and 3 are correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-483","question":"A father complains to a pre-primary teacher in Jaipur: 'My child just plays all day here. When will real learning start?' What is the most professional response?","options":["Promise to replace play time with daily writing worksheets so that the father is satisfied with the school","Explain that play is only for fun at this age and that real learning will begin once the child reaches Class I next year","Share observation notes, photographs and work samples showing what the child has learnt through play, linked to goals","Reduce play to the recess period and start rote learning of tables and rhymes to show visible progress"],"answer":2,"explanation":"Documented evidence (anecdotal records, portfolios) shows parents how play builds language, number sense and social skills. Abandoning play misreads early learning, and calling it 'only fun' undermines the teacher's own practice.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-484","question":"In pretend play, four-year-old Kavya uses a stick as a thermometer, plays the 'doctor' role and insists that the 'patient' must lie still until she has finished. From a Vygotskian view, what does this play most strongly show?","options":["Only gross motor development, since she is moving around and using her body in the game","Mere imitation of the adults around her, which does not by itself contribute anything to her learning","A lack of imagination, because she is only copying a real-life situation she has seen at the local clinic with her mother","Growing symbolic thought and self-regulation, as she lets one object stand for another and keeps to role rules"],"answer":3,"explanation":"Vygotsky saw make-believe play as a leading activity: using objects as symbols separates meaning from things, and keeping to role rules builds self-control. In play the child acts 'beyond her average age'.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-485","question":"In the blocks corner, five-year-old Rohan always grabs most of the blocks and pushes others out. Which teacher action best fits a play-based, inclusive classroom?","options":["Ban Rohan from the blocks corner for a week, so that he learns that grabbing has consequences","Do nothing, since free play must never be interrupted by adults, and children will sort it out among themselves","Remove the blocks from the classroom altogether, since they keep causing quarrels among children","Join the play, introduce simple turn-taking and sharing routines, and coach Rohan to build jointly with others"],"answer":3,"explanation":"Play is a key setting for learning social skills, and the adult's role includes coaching them in context. Exclusion, total non-intervention, or removing materials all miss the learning opportunity.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-486","question":"Assertion (A): Observing children closely during play can give a teacher valid information for assessing their development in the foundational stage. Reason (R): During play, children show their language, problem-solving and social skills naturally, without the stress of a test.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"NCF-FS 2022 favours observation and documentation over tests for young children because play shows authentic competence; R gives exactly this reason.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-487","question":"A teacher in a pre-primary class keeps the sand and water trays covered because they are 'messy and teach nothing'. Which statement best counters her view?","options":["Pouring, filling and moulding build sensory experience, early ideas of volume and cause-effect, and descriptive language","Sand and water play is useful only as a short break to calm restless children between lessons","Sand and water play should be allowed only after children finish their writing work, as a reward","Sand and water play builds only fine-motor control in the hands and fingers, and has no real cognitive or language value of its own"],"answer":0,"explanation":"Exploratory play with sand and water lays foundations for measurement concepts and scientific thinking, and prompts rich talk. Treating it as a break or a reward misses its learning value.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-488","question":"A Class IV teacher in Wardha helps children make paper pinwheels and asks them to find out when the pinwheel spins faster, then try changes to the blades. What makes this a genuine example of toy-based pedagogy rather than a craft activity?","options":["The pinwheels are made from low-cost paper, so every child in the class can afford to make one","Children use the toy to ask questions, predict, test and explain how moving air spins it, linking play to concepts","Children can take the pinwheels home as a reward for good behaviour and finishing their work","The activity keeps children busy and quiet while the teacher completes the attendance registers and other paperwork"],"answer":1,"explanation":"Toy-based pedagogy uses toys as tools for inquiry and conceptual understanding, not as rewards or time-fillers. Low cost is helpful but is not what makes it pedagogy.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-489","question":"Class VI children make rubber-band-powered cotton-reel toys; several toys fail to move. Which next step adds the most learning?","options":["The teacher fixes the toys herself so that every child has a working toy to take home and show parents","The teacher gives marks only to the children whose toys worked properly the very first time","Children discuss why some toys failed, change one thing at a time, test again and record changes","The activity is closed at this point, since the concept is already explained in the textbook"],"answer":2,"explanation":"The design-make-test-improve cycle, with analysis of failure and changing one variable at a time, builds scientific and engineering thinking. Fixing toys for children or rewarding only first-time success removes this learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-490","question":"In a Class VII social science lesson, a teacher shows Channapatna wooden toys from Karnataka and Kondapalli toys from Andhra Pradesh and asks children where the materials come from, who makes them and how they reach markets. What is the strongest pedagogic justification for this?","options":["The toys make the class colourful and attractive so that children do not get bored or restless during the long lesson","It covers part of the art syllabus as well, so that a separate art period is no longer needed","It helps the teacher finish the long geography chapter quickly by using objects instead of text","Local toys link crafts, culture, resources and livelihoods across subjects, rooted in children's own context"],"answer":3,"explanation":"Indigenous toys connect to geography (resources), economics (livelihoods, markets), history and culture, which is the cross-curricular, context-based learning NEP 2020 encourages. Colour alone or saving time is not a pedagogic reason.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-491","question":"Assertion (A): Giving a toy car as a prize to the child who scores highest in a test is an example of toy-based pedagogy. Reason (R): Toys can raise children's interest and motivation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false, but R is true","A is true, but R is false"],"answer":2,"explanation":"Toy-based pedagogy uses toys as learning tools for all children; a toy as a prize is an extrinsic reward, not pedagogy. R is true in general but does not make A true.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-492","question":"In a Class I classroom in Indore, the teacher notices that boys always take the toy cars and building sets while girls take the dolls and kitchen sets. What is the most appropriate action?","options":["Leave it as it is, since children naturally prefer the toys that are suited to their own gender","Rotate every child through all toy areas and use stories and talk to question 'boys' toys' and 'girls' toys'","Remove the dolls and kitchen sets from the class so that the girls also start using building sets","Buy separate sets of toys for the boys' and girls' sections of the class so that nobody has to share or quarrel"],"answer":1,"explanation":"Toy preferences are shaped by social messages, and an inclusive teacher widens every child's experiences. Removing toys or separating children reinforces rather than challenges stereotypes.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-493","question":"Shy Class II child Sunaina never speaks in class, but when the teacher hands her a sock puppet she talks to the puppet's 'friend' at length. What best explains this?","options":["The puppet acts as a safe mask, lowering her anxiety so she can use language without feeling exposed","Sunaina is only pretending, so what she says through the puppet has no value for assessing her language","Puppets work only for children with speech disorders","Sunaina speaks only because the puppet is a new object, and the effect will disappear within a day or two"],"answer":0,"explanation":"Puppets let children speak through a character, which reduces the fear of being judged; this is why they are widely used for oral language in early grades. What she says is real evidence of her language ability.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-494","question":"Consider the following statements about Jadui Pitara, introduced by the Ministry of Education in 2023: 1. It is a play-based learning-teaching kit for children of the foundational stage (ages 3 to 8). 2. It includes items such as toys, puzzles, puppets, storybooks and activity books. 3. It is meant to replace teacher-child interaction with self-learning material. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Jadui Pitara supports NCF-FS 2022 with play materials for ages 3-8 that teachers and parents use with children. It is a resource for interaction and play, not a replacement for it, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-495","question":"A teacher of Class III has a child with low vision. She is planning a toy-based activity on shapes. Which choice best ensures the child takes part fully?","options":["Let the child watch from the side while the others handle the toys, so that she is not hurt or left feeling embarrassed","Give the child a separate worksheet with large print instead of the toys, to work on alone","Excuse the child from the activity, since it depends entirely on being able to see the shapes","Use toys and shape blocks with clear textures and edges to explore by touch, and describe actions aloud for all"],"answer":3,"explanation":"Inclusive design (tactile materials, verbal description) lets the child learn alongside peers through the same activity. Watching from the side, separate work or exclusion denies equal participation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-496","question":"A Class II teacher in Hubli uses traditional games such as hopscotch (kunte bille) and a pebble game for counting and grouping. Which statement best evaluates this choice?","options":["Traditional games are useful only for physical education and cannot be used to teach any concepts at all","Familiar games link learning to children's culture and give natural contexts for counting, grouping, turn-taking and rules","Traditional games should be avoided in class because children already play them at home and in the street with their friends","Using games for maths makes children dependent on play and unable to do written sums in their notebooks later"],"answer":1,"explanation":"Culturally familiar games give meaningful, low-cost contexts for number work and social skills, building a bridge from home to school. They complement written work rather than preventing it.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-497","question":"A Class V teacher says, 'I use toys in class: on Fridays children may play with them if they have finished all their work.' A teacher educator says this is not toy-based pedagogy. Which reason best supports the teacher educator?","options":["Toys should never be used beyond the pre-primary stage, so a Class V teacher should not be using them in class at all","Toy-based pedagogy requires costly factory-made educational toys rather than ordinary toys","In toy-based pedagogy, toys are tools for exploring concepts within learning objectives, not a leisure reward","Letting children play with toys on Fridays goes against the RTE Act and the school's timetable rules"],"answer":2,"explanation":"The key feature of toy-based pedagogy is that toys serve the learning goal, often made by children from local materials; using them only as a reward separates play from learning. Cost and grade level are not the issue.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-498","question":"Consider the following about a teacher's role during children's free play in a pre-primary class: 1. Observing and recording what children do is part of the teacher's role. 2. The teacher should frequently stop play to ask questions so that learning is not wasted. 3. The teacher arranges materials and space so that play invites exploration. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"During free play the teacher prepares the environment and observes, intervening sensitively; constantly stopping play turns it into a lesson and kills its value, so statement 2 is wrong.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-499","question":"A Class VIII teacher in Kerala wants to use a spinning top (pambaram) to start a lesson. Which use is the most pedagogically sound?","options":["Show the top spinning and then dictate the definition of rotation for the children to copy down neatly into their own notebooks","Let groups spin tops on different surfaces, observe how long they spin, ask questions and link it to friction and motion","Spin the top once to get the children's attention and then proceed with the textbook reading","Hold a spinning competition among the children and give a prize to the one whose top keeps spinning the longest"],"answer":1,"explanation":"Children's own observations and questions about the toy lead to concepts such as friction, which is the core of toy-based and experiential learning. An attention-grabber or competition alone does not lead to concepts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-500","question":"A Class 5 child says 3/4 and 4/5 are equal ‘because each is just one piece short of a whole’. Which teaching move best addresses this?","options":["Agree, since both fractions are exactly one piece less than one whole, so they must be equal","Lay strips of fourths and fifths under a whole strip so she sees that the missing quarter is bigger than the missing fifth","Teach her to cross-multiply and compare 15 and 16, which gives the correct answer quickly and reliably every single time it is used","Tell her to compare the denominators, since the bigger denominator always gives the bigger fraction"],"answer":1,"explanation":"This is ‘gap thinking’: she compares the number of missing pieces, not their size. Strips show 1/4 > 1/5, so 3/4 leaves a bigger gap and is smaller. Cross-multiplying gives the answer without fixing the idea; D is a new misconception.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-501","question":"Asked to shade 1/3 of a row of 12 stars, a Class 4 child shades 3 stars. What has she most likely done?","options":["Read the denominator as the number of stars to shade, instead of making 3 equal groups","Miscounted while shading, though she meant to shade one-third of the twelve stars","Shaded 1/4 on purpose, believing a quarter and a third of 12 are the same","Understood one-third correctly but took a different set of stars as the whole"],"answer":0,"explanation":"1/3 of 12 means split 12 into 3 equal groups of 4 and take one group, so 4 stars. Reading the ‘3’ as ‘shade three’ shows she has not yet linked fractions of a set to equal grouping.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-502","question":"A Class 5 child writes 2/5 + 1/5 = 3/10. Which response is most likely to change her thinking?","options":["Remind her of the rule ‘add the numerators only’ and set ten more practice sums","Tell her to find the LCM of the denominators first, then add the converted numerators","Shade 2/5 and then 1/5 on one fifths strip and ask what part of the strip is now shaded","Explain that 3/10 cannot be right because 10 is not a factor of 5, so it is not allowed"],"answer":2,"explanation":"She is treating numerators and denominators as separate whole numbers. Shading on one strip shows the pieces are still fifths, so 3 fifths are shaded; the rule alone does not repair the meaning, and LCM is not the issue with like denominators.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-503","question":"A Class 6 child says 2/3 = 4/5 ‘because I added 2 to the top and 2 to the bottom’. What is the underlying misconception?","options":["She does not yet know how to simplify fractions to lowest terms before comparing them","She has confused the numerator with the denominator while writing the new fraction","She thinks adding the same number to top and bottom always makes a fraction bigger","She uses additive thinking where equivalence needs multiplication, as in 2/3 = 4/6"],"answer":3,"explanation":"Equivalent fractions come from multiplying (or dividing) both parts by the same number, which keeps the ratio. Adding changes the ratio: 2/3 ≈ 0.67 but 4/5 = 0.8.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-504","question":"Match each situation with the meaning of 3/4 it uses. 1. Three rotis shared equally among four children 2. Marking 3/4 on a number line 3. Finding 3/4 of ₹200 4. Three boys for every four girls in a class; a. ratio b. operator c. measure d. quotient","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-b, 2-c, 3-d, 4-a"],"answer":0,"explanation":"Sharing 3 among 4 gives 3/4 each (quotient); a point on the line is a measure from 0; ‘3/4 of’ acts on a quantity (operator); 3 boys to 4 girls compares two quantities (ratio).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-505","question":"Why do many maths educators recommend equal-sharing problems (‘share 4 rotis equally among 3 children’) as an early entry into fractions?","options":["They let children learn the written symbols for fractions first, before the ideas behind them","They draw on children's sense of fairness and naturally produce amounts such as 1 1/3 to name","They avoid the need for drawings or objects, so children can work with numbers alone","They are the only correct way to introduce unit fractions such as 1/2 and 1/3 in school"],"answer":1,"explanation":"Children already care about fair shares, so they partition and name the pieces themselves; the problem also gives fractions greater than one and the quotient meaning (4 ÷ 3), not only part-whole.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-506","question":"Riya says she got half of a big roti and Aman got half of a small roti, so they ‘got the same, because half is half’. The idea the teacher most needs to bring out is that:","options":["half of anything is always the same amount, so both children really did get equal shares","fractions can be compared only when the shapes being divided are of the same kind","a fraction is relative to its own whole, so halves of different wholes can differ","Aman's share is not really a half, because a small roti cannot be divided equally"],"answer":2,"explanation":"The fraction is always relative to a whole. Both shares are halves, but of different wholes, so the amounts differ. Comparing fractions as amounts needs the same whole.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-507","question":"A number line is drawn from 0 to 2 with only 0, 1 and 2 labelled. Asked to mark 2/3, a Class 5 child divides the whole line from 0 to 2 into three equal parts and marks the second division. What does this show?","options":["She knows that 2/3 lies between 1 and 2, so she marks a point inside that interval","She has confused the numerator and denominator, so she has really marked 3/2","She marks the correct point, since any line can be divided into three equal thirds","She takes the whole line, not the length from 0 to 1, as the unit, so she marks 4/3"],"answer":3,"explanation":"On a number line the unit is the length from 0 to 1. Dividing 0–2 into thirds makes each part 2/3, so the second mark is at 4/3. Children used to ‘the whole shape’ in area models often make this error.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-508","question":"A Class 5 child writes 3.7 + 2 = 3.9. Which explanation and response are most appropriate?","options":["She aligns last digits as in whole numbers; writing 2 as 2.0 shows the 2 is ones, giving 5.7","She does not know the basic fact 7 + 2, so she needs more drill on addition facts","She has added the digits correctly but placed the decimal point in the wrong position","She should be taught to ignore the decimal point while adding and insert it at the end"],"answer":0,"explanation":"Right-aligning digits works for whole numbers but not decimals. Putting the 2 in the ones column (2.0) shows ones must be added to ones: 3.7 + 2.0 = 5.7.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-509","question":"A Class 6 child says 0.36 is less than 0.3 ‘because hundredths are smaller than tenths’. Which statement best describes her thinking?","options":["She uses the ‘longer is larger’ rule carried over from comparing whole numbers","She uses ‘shorter is larger’: hundredths are smaller parts, so she ignores how many","She compares only the digits after the point and decides that 36 is greater than 3","She has made a careless slip, since she clearly knows that 36 is more than 30"],"answer":1,"explanation":"0.36 = 36 hundredths and 0.3 = 30 hundredths, so 0.36 is bigger. Thinking that more decimal places means smaller pieces, and so a smaller number, is the ‘shorter is larger’ misconception, the opposite of ‘longer is larger’.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-510","question":"A Class 6 child writes 2.5 × 10 = 2.50, explaining ‘to multiply by 10 you put a zero at the end’. What is the best response?","options":["Tell her the ‘add a zero’ rule works only for whole numbers, and move on to the next sum","Ask her to work out 25 × 10 instead and then put the decimal point back at the end","Use a place-value chart to show each digit moving one place left, so 2.5 becomes 25","Ask her to memorise the new rule ‘move the decimal point one place to the right’"],"answer":2,"explanation":"‘Add a zero’ is a whole-number shortcut that fails for decimals (2.50 = 2.5). Seeing digits shift one place left in a chart explains why the value becomes ten times larger; a new rule to memorise does not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-511","question":"A child converts 2 m 5 cm into metres and writes 2.5 m. What does the error reveal?","options":["She does not know that 1 m = 100 cm, so she cannot convert between the two units","She has confused metres with kilometres and divided by 1000 instead of by 100","She has made a slip in copying, though she knows the answer should be 2.05 m","She puts the centimetres straight after the point, not seeing 5 cm is 0.05 m"],"answer":3,"explanation":"5 cm = 5/100 m = 0.05 m, so 2 m 5 cm = 2.05 m. Writing 2.5 m (= 2 m 50 cm) shows a weak link between decimal places and measurement units.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-512","question":"A shopkeeper raises a ₹100 price by 20% and later reduces the new price by 20%. A Class 8 student says the price is back to ₹100. Which response best uncovers the misconception?","options":["Ask her to work out each step in rupees and note what each 20% is taken of","Tell her that percentages can never be added to or subtracted from each other","Ask her to use the formula for successive change without explaining it","Agree with her, since a 20% rise and a 20% fall of the same price cancel out"],"answer":0,"explanation":"The rise is 20% of ₹100 (₹20, giving ₹120), but the fall is 20% of ₹120 (₹24), leaving ₹96. Working it out shows that a percentage depends on its base, which is exactly what she missed.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-513","question":"A recipe uses 2 cups of rice with 3 cups of water. For 6 cups of rice a child says 7 cups of water ‘because water is always 1 more than rice’. The child's reasoning is:","options":["correct, since the difference between rice and water stays the same at every scale","additive where it should be multiplicative: rice is tripled, so water must be 9 cups","correct for small amounts of rice, but it would not work for much larger amounts","wrong only because she did not use the unitary method to find water for one cup"],"answer":1,"explanation":"Proportional situations keep the ratio, not the difference: 6 is 3 × 2, so water is 3 × 3 = 9 cups. Using a constant difference is the classic additive error in ratio problems.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-514","question":"A Class 7 student says there is no fraction between 2/5 and 3/5 ‘because they come one after the other’. Which question helps her most?","options":["‘What is the next whole number after 2, and the one after 3?’","‘Can you list all the fractions between 0 and 1 for me?’","‘Can you write 2/5 and 3/5 with denominator 10 and look again?’","‘Is 3/5 bigger than 2/5, and how do you know that it is?’"],"answer":2,"explanation":"Renaming as 4/10 and 6/10 reveals 5/10 between them, and again with 20ths, and so on. She is carrying over the whole-number idea of a ‘next’ number; fractions are dense.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-515","question":"After learning that 3x means 3 × x, a Class 7 student reads the mixed number 2 1/3 as 2 × 1/3 = 2/3. Which response best addresses this?","options":["Tell her that mixed numbers are no longer used once algebra begins in Class 7","Ask her to always convert mixed numbers into decimals so the confusion goes away","Mark it wrong and ask her to learn the rule for converting mixed numbers by heart","Explain that 2 1/3 means 2 + 1/3, unlike the algebra convention, and check with drawings"],"answer":3,"explanation":"Here she is wrongly transferring the algebra convention (side by side means multiply). 2 1/3 means 2 + 1/3 = 7/3. Naming the clash between the two conventions and checking with a picture fixes it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-516","question":"Which representation best helps Class 6 children see why 2/3 × 3/4 = 6/12?","options":["Fold a strip into fourths, shade 3/4, then fold into thirds the other way and shade 2/3 of it","Draw 2/3 and 3/4 on two separate number lines and then add the two lengths together","Write the rule ‘multiply tops, multiply bottoms’ on the board and practise it with sums","Cut one roti into 3 parts and another into 4 parts and compare the sizes of the pieces"],"answer":0,"explanation":"Folding both ways gives 12 equal parts, of which 6 are double-shaded: 2/3 of 3/4 is 6/12. The area model shows both the meaning of ‘of’ and why the denominators multiply.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-517","question":"Which story fits the calculation 1 1/2 ÷ 1/4?","options":["What is 1/4 of a ribbon 1 1/2 m long?","How many pieces of 1/4 m can be cut from a ribbon 1 1/2 m long?","A ribbon 1 1/2 m long is shared equally among 4 children. How long is each piece?","A ribbon is 1 1/2 m long and another is 1/4 m. What is their total length?"],"answer":1,"explanation":"‘How many quarters fit into one and a half?’ is the measurement meaning of division, giving 6 pieces. Option A is multiplication by 1/4, and option C is division by 4; both are common mix-ups.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-518","question":"A teacher used money to introduce decimals. Later a child reads ₹2.5 as ‘two rupees and five paise’. What does this most clearly show?","options":["She has not yet learnt that 100 paise make a rupee, so she cannot convert between them","She is careless with the decimal point and needs reminders to read numbers slowly","The money model tied decimals to two places, so she reads the 5 as paise, not as 5 tenths","She has confused rupees with paise and so reads the whole amount in the wrong unit"],"answer":2,"explanation":"Money always shows two decimal places, so children may read digits after the point as a whole-number count of paise. A place-value chart showing 2.5 = 2.50 corrects this limitation of the model.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-519","question":"Asked to find 35% of 240, four Class 7 students explain their thinking. Whose explanation shows the strongest understanding of percent?","options":["‘35 by 100 into 240 is 84, because that is the percentage formula.’","‘35% means 35 out of 240, so the answer is simply 35.’","‘Multiply 35 by 240 and divide by 10 to get the answer.’","‘10% is 24, so 30% is 72; 5% is half of 24, which is 12. So 84.’"],"answer":3,"explanation":"Building 35% from 10% and 5% shows that percent means ‘per hundred of this quantity’ and uses relationships flexibly. The formula answer is right but unexplained; B and C show misconceptions.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-520","question":"Which of these statements about teaching fractions are correct? I. Fractions can be introduced through equal sharing of real things such as rotis. II. Children should learn that the fraction with the bigger denominator is always the smaller one. III. Placing fractions on a number line helps children see them as numbers. IV. Showing shapes cut into unequal parts, and asking why they are not quarters, deepens understanding.","options":["I, III and IV","I, II and III","II and IV only","I and III only"],"answer":0,"explanation":"Statement II is true only when the numerators are equal (3/4 > 2/3 although 4 > 3), so teaching it as a rule creates a new misconception. Non-examples, as in IV, sharpen the idea of equal parts.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-521","question":"Assertion (A): Children who know only that ‘a fraction is a part of a whole’ often struggle with fractions such as 5/4. Reason (R): With only the part-whole view, they ask how 5 parts can be taken from a whole that has 4.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Improper fractions make sense as measures (5 quarter-lengths) or quotients (5 ÷ 4), not within a single whole. R explains why a narrow part-whole view causes the difficulty in A.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-522","question":"A Class 6 child writes 0.6 ÷ 3 = 2. What is the best first question for the teacher to ask?","options":["‘Did you remember to put the decimal point in your answer?’","‘What is 6 ÷ 3, and where should the point go now?’","‘If 0.6 kg of sugar is shared by 3 people, can each get 2 kg?’","‘Can you show 3 × 2 on a number line and check your answer?’"],"answer":2,"explanation":"A sense-making context shows at once that each share must be less than 0.6 kg; in fact it is 0.2 kg. The child has ignored the point and divided 6 by 3. Checking reasonableness is better than a reminder about the point.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-523","question":"Which task best checks whether a Class 5 child sees a fraction as a number with a size, not just as shaded pieces?","options":["Shade 3/8 of a rectangle divided into eight equal parts","Write the fraction for the shaded part of a circle drawn on the board","Name the numerator and denominator of 7/8 and say what each means","Is 7/8 closer to 0, to 1/2 or to 1? Explain how you know"],"answer":3,"explanation":"Judging closeness to benchmarks (7/8 is only 1/8 short of 1) needs a sense of the fraction's size. Shading and naming test part-whole pictures and vocabulary only.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-524","question":"A Class 5 child writes 1/4 = 0.4 and 1/5 = 0.5. What is she doing?","options":["Dividing the denominator by the numerator and writing the result as a decimal","Writing the denominator after the point, not seeing 1/4 as 25 hundredths","Rounding each fraction to one decimal place, as she was taught for measurement","Confusing fractions with percentages, so she reads 1/4 as 4 per cent of a whole"],"answer":1,"explanation":"1/4 = 0.25 and 1/5 = 0.2. Copying the visible digit after the point shows she has not linked decimals to tenths and hundredths; a 10 × 10 grid shading 1/4 helps.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-525","question":"A Class 8 English teacher in a Gorakhpur school reads each sentence of the lesson aloud, gives its Hindi meaning, makes students copy word lists with Hindi equivalents and sets passages for translation. Her students score well in written tests but cannot hold a simple conversation. Which method is she using, and what is its main weakness here?","options":["Bilingual method; it allows the mother tongue only at sentence level and so slows comprehension","Grammar-translation method; it neglects listening and speaking and treats language as knowledge","Direct method; using the target language only makes the lessons too difficult for these learners","Audio-lingual method; its heavy oral drilling leaves students little time to read or write anything"],"answer":1,"explanation":"Sentence-by-sentence translation, bilingual word lists and written translation are the hallmarks of grammar-translation, which develops reading and accuracy but not spoken communication.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-526","question":"A teacher using the direct method never uses the mother tongue, teaches ‘window’ by pointing, and lets children work out grammar from oral examples. Which criticism of this method is most valid in a typical Indian government school?","options":["It neglects oral skills because it gives most class time to reading and to written grammar exercises","Abstract words are hard to convey without the mother tongue, and it needs very fluent teachers","It teaches grammar deductively, with rules first, which young learners find hard to follow","It depends on translation, so learners never start thinking directly in the target language"],"answer":1,"explanation":"Mime and realia work for ‘window’ but not for ‘honesty’ or ‘although’, and the method assumes teachers with native-like fluency. Options A to C describe grammar-translation, not the direct method.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-527","question":"A Pune teacher says, ‘I go to school. He…’ and students respond, ‘He goes to school.’ She then says ‘They…’, and so on. Students also memorise dialogues, and she corrects errors at once and praises correct responses. The theoretical basis of this method is:","options":["Cognitive psychology and the idea that learners test hypotheses about rules","Vygotsky’s socio-cultural theory and learning through social interaction with peers","Chomsky’s nativism and the language acquisition device","Behaviourist psychology and structural linguistics, treating language as habit"],"answer":3,"explanation":"Drills, dialogue memorisation, immediate correction and reinforcement mark the audio-lingual method, built on Skinnerian habit formation and structural descriptions of language.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-528","question":"To help learners say a long sentence, a teacher has them repeat ‘…to the market’, then ‘…going to the market’, then ‘…am going to the market’ and finally ‘I am going to the market.’ This audio-lingual technique is called:","options":["Backward build-up drill","Sentence transformation drill","Substitution drill","Chain drill"],"answer":0,"explanation":"In backward build-up the sentence is built from the end so that learners always finish on the familiar, correctly stressed part. A substitution drill swaps one word; a transformation drill changes the structure; a chain drill passes a question from learner to learner.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-529","question":"Class 7 students plan a class trip to Jaipur. In groups they compare train timings, work out a budget and write an email to the principal asking for permission; the teacher looks mainly at whether each plan is clear and complete, and takes up useful language afterwards. This lesson is best described as:","options":["Situational language teaching, since a new structure is presented through a real situation","Audio-lingual teaching, since the groups repeat useful phrases until they become habits","Task-based language teaching, organised around a meaningful task with a real outcome","Grammar-translation, since the email is written and checked for correctness at the end"],"answer":2,"explanation":"The lesson centres on a task with a non-linguistic outcome (a workable plan), meaning comes first, and attention to form follows the task, as in TBLT.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-530","question":"In Jane Willis’s task-based framework, after groups have presented their survey results to the class, the teacher draws attention to phrases they used or needed (‘Most of us…’, ‘Only a few…’) and gives brief practice. This stage is called:","options":["The pre-task (introduction to the topic and task)","The planning stage of the task cycle","The language focus (analysis and practice)","The report stage of the task cycle"],"answer":2,"explanation":"Willis’s framework runs pre-task, task cycle (task, planning, report) and then language focus, where learners analyse and practise forms that arose during the task.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-531","question":"Assertion (A): In task-based language teaching, explicit work on grammar usually comes after the task rather than before it. Reason (R): Learners notice the forms they need more readily after trying to communicate a message with their own resources.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Unlike present-practise-produce, TBLT puts form-focus after the task because the attempt to communicate makes learners aware of gaps, so the language focus meets a felt need.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-532","question":"Consider these statements about Total Physical Response: I. It links language with physical movement, which helps memory. II. It lets beginners show understanding before they are expected to speak. III. It is best suited to teaching abstract vocabulary and complex grammar to advanced learners. Which are correct?","options":["I, II and III","I and II only","II and III only","I only"],"answer":1,"explanation":"Asher’s TPR builds comprehension through commands and actions and allows a silent period. It is hard to use for abstract ideas and advanced structures, so III is false.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-533","question":"Which practice is LEAST consistent with the whole language approach in a Class 1 classroom?","options":["Shared reading of a big book, pointing to words while reading the story together","Linking reading and writing to the theme children are exploring in EVS","Children writing greeting cards and notes for real readers at home and school","Daily worksheets of isolated letter sounds before children see any real story"],"answer":3,"explanation":"Whole language moves from whole, meaningful texts to parts, so isolating sounds before any real reading contradicts it. The other practices use authentic texts and purposes.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-534","question":"A teacher draws a table on the board with columns ‘This / That’, ‘is’, ‘a / an’ and ‘pen / umbrella / bag’, and children make as many correct sentences as they can. This practice belongs to:","options":["The structural approach, which drills graded sentence patterns through substitution","Communicative language teaching, which builds fluency through information-gap activities","Task-based teaching, which organises learning around tasks with real outcomes","The whole language approach, which teaches language through authentic texts"],"answer":0,"explanation":"Substitution tables are a typical tool of the structural approach, widely used in Indian schools, which grades and drills sentence patterns one at a time, largely orally.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-535","question":"A teacher reads an English sentence aloud, gives its Telugu equivalent once to make the meaning clear, and then has learners practise only the English sentence orally in many variations. Learners themselves never translate. This is closest to:","options":["C. J. Dodson’s bilingual method","The direct method","The audio-lingual (oral drill) method","The grammar-translation method"],"answer":0,"explanation":"In Dodson’s bilingual method only the teacher uses the mother tongue, at sentence level, to convey meaning; practice is in English. Grammar-translation makes learners translate texts, and the direct method bans the mother tongue.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-536","question":"Match each method with its typical feature: 1. Silent Way 2. Suggestopedia 3. Community Language Learning 4. Total Physical Response; a. The teacher acts as a counsellor and helps translate what learners want to say b. A relaxed setting with music and comfortable seating removes mental barriers c. The teacher speaks very little and uses coloured rods and charts d. Learners respond to commands with actions","options":["1-a, 2-b, 3-c, 4-d","1-c, 2-a, 3-b, 4-d","1-c, 2-b, 3-a, 4-d","1-c, 2-b, 3-d, 4-a"],"answer":2,"explanation":"Gattegno’s Silent Way uses rods and teacher silence; Lozanov’s Suggestopedia uses music and relaxation; Curran’s CLL casts the teacher as counsellor; Asher’s TPR pairs commands with actions.","difficulty":"very-hard","source":"DSSSB · KVS TGT · CTET Paper II"},
  {"id":"cdp-pedagogy-subjects-537","question":"Which feature is shared by the direct method and the audio-lingual method?","options":["Both teach grammar deductively by stating the rule before examples","Both are based on the cognitive view that learners form and test hypotheses","Both rely on translation to check that learners have understood","Both give priority to speech and keep the mother tongue out of class"],"answer":3,"explanation":"Both put spoken language first and avoid the mother tongue; both also treat grammar inductively. Translation belongs to grammar-translation, and the audio-lingual method is behaviourist, not cognitive.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-538","question":"A Class 10 student writes a flawless application but begins it ‘Hi Principal buddy’. In Canale and Swain’s model of communicative competence, the component he most needs to develop is:","options":["Grammatical competence","Discourse competence","Sociolinguistic competence","Strategic competence"],"answer":2,"explanation":"Sociolinguistic competence is using language appropriately for the setting, relationship and purpose. His grammar is fine; the problem is appropriacy.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-539","question":"A Class 6 learner who does not know the word ‘ladle’ tells her partner, ‘You know, the big spoon with a long handle for serving dal.’ This shows her:","options":["Grammatical competence","Strategic competence","Discourse competence","Sociolinguistic competence"],"answer":1,"explanation":"Strategic competence covers the strategies, such as paraphrase and circumlocution, that learners use to keep communication going when their language falls short.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-540","question":"A Class 9 student’s essay has correct sentences, yet the ideas do not connect: there are no linking words, ‘it’ and ‘they’ refer to unclear things, and paragraphs jump between points. In communicative-competence terms the student mainly needs to develop:","options":["Strategic competence: ways to repair breakdowns in talk","Grammatical competence: accuracy in forming sentences","Discourse competence: cohesion and coherence across sentences","Sociolinguistic competence: matching style and register to the reader"],"answer":2,"explanation":"Discourse competence is the ability to combine sentences into a unified, connected text through cohesive devices and logical organisation. Each of his sentences is already accurate.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-541","question":"During a group discussion meant to build fluency, a teacher hears many grammatical errors. In communicative language teaching, her best course of action is to:","options":["Stop each group whenever an error occurs and have the speaker repeat it correctly","Note the common errors quietly and deal with them after the activity is over","Allow students to continue only if they can speak in complete, correct sentences","Award marks for grammar during the discussion so that students take more care"],"answer":1,"explanation":"Fluency activities aim at keeping communication going; interrupting shifts attention to form and raises anxiety. Delayed feedback on recurring errors keeps both fluency and accuracy in view.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-542","question":"A Class 4 teacher uses TPR for classroom commands, a short pattern drill to practise ‘Can you…?’, and role plays at a vegetable stall, choosing each according to the aim of the lesson. The best description of her practice is:","options":["Principled eclecticism: choosing techniques from several methods to suit learners and aims","A confused mixture of methods that will leave children unsure of what is expected of them","Essentially the audio-lingual method, since a pattern drill for ‘Can you…?’ appears in the lesson","Essentially grammar-translation, since a particular structure is being practised"],"answer":0,"explanation":"Eclecticism is principled when techniques are selected because they serve specific learning aims and learners. One drill does not turn a lesson into the audio-lingual method.","difficulty":"moderate","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-543","question":"A teacher in a rural Chhattisgarh school with 60 children and few resources finds that no textbook method fits her class. She studies her learners, tries strategies, reflects on what works, and builds her own approach guided by aims such as maximising learning opportunities and promoting learner autonomy. Her stance is closest to:","options":["The audio-lingual method, which offers one fixed set of procedures that works for any class","The natural approach, which prescribes a silent period followed by early production in speech","Grammar-translation, which suits large classes because it needs little oral interaction","Kumaravadivelu’s post-method pedagogy, based on particularity, practicality and possibility"],"answer":3,"explanation":"Post-method pedagogy rejects the search for one best method and asks teachers to theorise from practice, using macro-strategies sensitive to their particular context.","difficulty":"very-hard","source":"KVS TGT · DSSSB · CTET Paper II"},
  {"id":"cdp-pedagogy-subjects-544","question":"A teacher stops her class in the middle of a drill to correct each error at once and insists on perfect repetition, saying, ‘If a wrong form is repeated, it becomes a habit.’ Her view of errors reflects:","options":["Communicative language teaching","The audio-lingual method","The natural approach","The whole language approach"],"answer":1,"explanation":"In the behaviourist audio-lingual method, errors are bad habits to be prevented and corrected immediately. The other approaches see errors as a natural, informative part of development.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-545","question":"Assertion (A): In the whole language approach, children must master all the letter–sound correspondences before they are given real books. Reason (R): The whole language approach moves from the parts of language to the whole.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Whole language moves from whole to part: children meet real, meaningful texts from the start, and sound–letter work is embedded in them. Both statements describe a bottom-up view, not whole language.","difficulty":"very-hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-546","question":"After a class visit to a dairy, Class 2 children tell the teacher what they saw, she writes their own sentences on chart paper, and the chart becomes their reading text for the week. This is the:","options":["Language experience approach, using the children’s own words as text","Look-and-say method, since words on the chart are learnt as wholes","Grammar-translation method, since speech is converted into writing","Phonics approach, since the chart is mainly used to practise letter sounds"],"answer":0,"explanation":"The language experience approach turns children’s shared experiences and their own language into reading material, so texts are meaningful and predictable for them.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-547","question":"A Class 1 teacher teaches reading only through flash cards of whole words with pictures (‘bus’, ‘cow’, ‘tree’), which children learn to recognise by shape. If this is the only method used, the main problem is likely to be that children:","options":["Cannot learn any sight words at all through flash cards","Will learn too many letter sounds too early to manage","Will be unable to work out unfamiliar words on their own","Will lose interest, since pictures make reading too easy"],"answer":2,"explanation":"The look-and-say method builds a sight vocabulary quickly, but without sound–letter knowledge children have no strategy for new words, which is why it is combined with phonics.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-548","question":"Which of the following is a ‘task’ in the sense used in task-based language teaching?","options":["Pairs read a passage on railways and translate it, line by line, into their home language","Pairs fill in the blanks in ten sentences about the station with the correct prepositions of place","Pairs repeat the sentence ‘The station is near the school’ until they can say it fluently","Pairs use a town map to agree on the shortest route from school to the station and present it"],"answer":3,"explanation":"A task has a primary focus on meaning, a gap to close, learners using their own resources, and a clear non-linguistic outcome. The others are form-focused exercises.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-549","question":"A Kolkata teacher brings a real railway timetable, a restaurant menu and a newspaper weather report to her Class 7 English class. Which reason best justifies the use of such materials?","options":["They are strictly graded by grammar, so each one teaches one structure","They show language as it is actually used for real purposes in daily life","They should replace the textbook altogether, since textbooks are never authentic","They are easier for learners than the textbook, so they reduce effort"],"answer":1,"explanation":"Authentic materials expose learners to real language for real purposes, increase motivation and help transfer to life outside school. They are not graded by structure and supplement, rather than replace, the textbook.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-550","question":"A Class VII teacher asks students to sort these materials for studying the Delhi Sultanate:\n1. Ibn Battuta's account of his travels in 14th-century India\n2. A book on the Sultanate written by a historian in the 1990s\n3. Silver coins issued by Alauddin Khalji\n4. A documentary on the Sultanate made in 2010\nWhich of them are primary sources?","options":["1 and 2 only","3 and 4 only","1 and 3 only","1, 3 and 4 only"],"answer":2,"explanation":"Primary sources come from the period being studied: a contemporary traveller's account and the coins of the time. A modern historian's book and a recent documentary interpret the past from a later vantage point, so they are secondary.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-551","question":"A Class VII student says, 'The Akbarnama was written by Akbar's own courtier, so it must be a perfect and unbiased account of his reign.' What is the best response?","options":["Agree, because a primary source written by an eyewitness at court is always objective and complete in detail","Disagree, and tell the class that court chronicles are propaganda and should not be used at all","Note that it is valuable, but was written to praise the emperor, so its claims must be cross-checked","Tell the student to rely only on the textbook, since it has already removed all bias from sources"],"answer":2,"explanation":"Being close to events makes a source valuable, not neutral. Court chronicles reflect the patron's view, so historians ask who wrote them, why and for whom, and they cross-check. Rejecting such sources is as mistaken as trusting them blindly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-552","question":"Students reading an extract from an indigo cultivator's petition are asked: 'Who wrote this? When? To whom? What did the writer want?' These questions mainly build the skill of:","options":["memorising key dates and events of the colonial period","summarising a text in fewer words","translating old documents into modern everyday language","evaluating a source's origin, purpose and reliability"],"answer":3,"explanation":"Questions about author, date, audience and intention are the core of source criticism, sometimes called 'sourcing'. They help students judge what a document can and cannot tell us.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-553","question":"Assertion (A): A newspaper printed in August 1947 is a primary source for studying Partition.\nReason (R): Primary sources are materials produced at or near the time of the events, by people who took part in or observed them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A newspaper of that month was produced while the events were unfolding, which is exactly what makes it primary under R's definition. R therefore explains A.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-554","question":"An NCERT history textbook printed in 1975 is a secondary source for the Mughal period. A researcher, however, uses it as a primary source. Which research question would justify this?","options":["How was the Mughal revenue system organised under Akbar's rule?","How was Indian history presented to school students in the 1970s?","What did foreign travellers write about Mughal cities and markets?","Which coins did Shah Jahan issue, and in what metals?"],"answer":1,"explanation":"Whether a source is primary or secondary depends on the question being asked. For the Mughals the 1975 book is a later interpretation, but for the history of school education in the 1970s it is itself evidence from that time.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-555","question":"Which sequence is the most suitable for developing map skills from Class III to Class VI?","options":["World map → map of India → map of the state → sketch of the classroom","Globe → physical map of the world → atlas reading → map of the village","Route from home to school → school plan → village map → maps of state and country","Political map of India → physical map of India → thematic maps → sketch of the neighbourhood"],"answer":2,"explanation":"Map skills grow from children's own space, from a sketch of a known route to a plan drawn to scale and then to maps of larger and more distant areas. Starting with the world map reverses the 'known to unknown' order.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-556","question":"A Class VI student measures her classroom and draws its layout using 1 cm on paper for 1 m on the floor, marking the desks and the door. What has she drawn?","options":["A sketch, because it is drawn freehand by the student","A map, because it shows the positions of objects","A globe projection, because it is drawn to a scale","A plan, because it shows a small area drawn to scale"],"answer":3,"explanation":"A plan is a drawing of a small area to scale. A sketch is not drawn to scale, even if neat, and a map normally covers a larger area. Being hand-drawn does not decide the category; using a scale does.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-557","question":"A teacher wants Class VI students in a Himachal village to locate their houses, the village well and the temple on a map. Which kind of map should she use?","options":["A large-scale map, which shows a small area in great detail","A small-scale map, which shows a small area in great detail","A small-scale map, because larger areas give more detail","A physical map of India, because it shows relief"],"answer":0,"explanation":"Large-scale maps (for example 1:5,000) show small areas with much detail; small-scale maps show large areas with little detail. The common trap is to think 'large scale' means 'large area'.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-558","question":"Many Class VI students in a Lucknow school believe that 'north' means 'the top of the wall' or 'up the stairs'. Which activity best corrects this misconception?","options":["Ask them to memorise the rule that north is always at the top of every map they will ever use","Take them outdoors with a compass, find north, and turn the map to match the real directions","Show them the north arrow on a wall map and ask them to copy it into their notebooks","Tell them that directions do not really matter for reading a map correctly"],"answer":1,"explanation":"Directions are real orientations on the ground, not positions on a page. Finding north outdoors and orienting a map to it builds the concept, whereas 'north is at the top' merely restates the misconception in map form.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-559","question":"Looking at a wall map of the world, a Class VII student asks why Greenland looks almost as big as Africa. What is the most appropriate response?","options":["Explain that Greenland really is about the size of Africa, so the map shows it correctly","Explain that the map printer made a mistake and that the map should be replaced","Tell the student that the size of countries is not an important matter in geography lessons","Compare them on a globe: flat maps distort size, especially far from the equator"],"answer":3,"explanation":"Every flat map distorts something. Projections such as Mercator's enlarge areas far from the equator, which makes Greenland look huge though it is much smaller than Africa. The globe shows true relative size.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-560","question":"A Class VI student insists that 500 BCE came after 200 BCE 'because 500 is a bigger number'. Which is the most effective remedy?","options":["Ask the student to memorise a list of important BCE dates in their correct order","Explain that BCE dates are not very important for understanding history at school level","Tell the student to avoid BCE dates altogether, since they confuse most learners","Use a timeline that counts down to the Common Era and then up, and place both dates"],"answer":3,"explanation":"The error comes from applying ordinary counting to years that run backwards before the Common Era. A visible timeline shows that 500 BCE lies further back, so it happened earlier.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-561","question":"A Class VIII teacher draws two parallel timelines, one for events in India and one for events in Europe, from 1750 to 1900. What does this mainly help students understand?","options":["That Indian history is less important than European history during this whole period","The exact dates of every battle so that they can be recalled for the test","Simultaneity: what happened in different places at the same time, and how it linked","That timelines should only show political events, such as wars and treaties"],"answer":2,"explanation":"Parallel timelines develop the sense that events in different regions happened together and could influence each other, an important part of chronological thinking beyond sequence alone.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-562","question":"A Class VIII student writes, 'The Revolt of 1857 took place in the 18th century.' What is the most likely source of the error, and how can the teacher address it?","options":["The student has misread the date; the teacher should make her write ‘1857’ correctly ten times","The student reads ‘18’ as the century; a timeline of centuries shows the 1800s are the 19th","The student does not know about 1857; the teacher should retell the full story of the revolt","The student is right, since 1857 begins with 18, so the teacher need only praise the answer"],"answer":1,"explanation":"Children often take '18' in 1857 as the century number. Counting centuries on a timeline from the 1st century onwards shows that the 1800s form the 19th century. The error is about the concept of a century, not about the event.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-563","question":"A Class VII teacher shows a 12th-century Arab geographer's map of the Indian subcontinent in which south appears at the top, beside a modern map. What is the main purpose?","options":["To prove that old maps are useless and too inaccurate to be used for studying the past","To show that maps reflect the knowledge and conventions of their time, which change","To test whether students can spot which of the two maps is drawn wrongly","To show that north was not discovered until modern times by European sailors"],"answer":1,"explanation":"Maps are historical sources shaped by their makers' knowledge and conventions; placing north at the top is itself a convention. Comparing maps from different periods builds an awareness of how representations change.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-564","question":"To teach about early hunter-gatherers, a Class VI teacher shows stone tools and pictures of cave paintings and asks, 'What can these tell us about how these people lived?' This mainly develops the skill of:","options":["making inferences from material evidence where no written records exist","memorising the names and locations of important prehistoric sites in India","drawing and painting in the style of prehistoric cave artists","reading and decoding the scripts used by ancient peoples"],"answer":0,"explanation":"For periods without writing, historians infer ways of life from objects and art. Asking what the evidence reveals builds inference from material remains, the basic method of archaeology.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-565","question":"After reading a prashasti composed by a court poet in praise of a Gupta king, a student concludes that the king never lost a single battle. What should the teacher help the student understand?","options":["That a prashasti is written to praise, so its claims need checking against other evidence","That inscriptions on stone pillars are always accurate, because they are permanent and official","That prashastis are later forgeries and must be ignored when studying the Guptas","That only coins, not inscriptions, are reliable sources for the reigns of ancient kings"],"answer":0,"explanation":"A prashasti is a eulogy whose purpose shapes what it says and leaves out. It is valuable evidence, but its claims must be weighed against other sources. Treating it as fact or as worthless are both errors.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-566","question":"A Class VIII teacher shows a painting by a British artist that presents an Indian village as calm, picturesque and timeless. Which question should she ask students first, to build critical reading of visual sources?","options":["‘How many colours has the artist used, and which is the brightest?’","‘Is the painting beautiful, and would you hang it at home?’","‘Who painted this, for whom, and what might it leave out?’","‘How much would this painting sell for at an auction today?’"],"answer":2,"explanation":"Like written documents, images carry the viewpoint and purpose of their makers. Asking about creator, audience and omissions reveals the colonial gaze that a purely aesthetic question would miss.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-567","question":"Assertion (A): A map drawn to scale shows every feature at its true size.\nReason (R): Scale is the ratio between a distance on the map and the corresponding distance on the ground.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R correctly defines scale. But a scale reduces sizes; it does not show them at true size. Many features, such as roads, are drawn wider than scale or as symbols, so A is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-568","question":"When Class IV children in Bhopal draw their neighbourhood from memory, they draw their own house and the sweet shop very large and the bank very small. How should the teacher use these drawings?","options":["Mark them wrong, since the buildings are not drawn to the correct scale","Ignore them, since children of this age are too young to draw real maps","Use them to see how children perceive space, and build the idea of scale from there","Ask the children to trace a printed map of the neighbourhood instead of drawing from memory"],"answer":2,"explanation":"Mental maps show what matters to the child; they are a starting point, not an error to punish. Comparing them with measured distances leads naturally to the idea of scale.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-569","question":"Why should students of colonial India be taught to treat official British records with caution?","options":["They were all written in English, a language that most Indians of the time could not read","They are forgeries, made later by British historians to justify colonial rule","They were mostly destroyed in 1857, so only unreliable later copies now remain","They reflect officials' concerns and viewpoint, and may not show how others saw events"],"answer":3,"explanation":"Administrative records are rich sources, but they record what the state wanted to know and how officials understood things. The voices of peasants, workers and women often have to be found elsewhere.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-570","question":"Before teaching historical timelines, a Class VI teacher asks each child to make a timeline of their own life: birth, first day at school, a move to a new house, a sibling's birth. What is the main reason?","options":["To introduce sequence and duration through the child's own familiar past","To collect personal information about the families for the school's records","To fill the time before the actual history chapter begins","To test children's handwriting and their neatness in drawing lines"],"answer":0,"explanation":"Personal timelines build ideas of sequence, intervals and change on familiar ground before students apply them to distant periods, following the 'known to unknown' principle.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-571","question":"Class VII students bring old objects from home, such as a hurricane lantern, an inland letter, a brass lota and an old coin, to set up a class museum. Each object gets a label with what it was used for and what replaced it. What is the main learning?","options":["Learning to arrange and label objects neatly and attractively for a school exhibition","Seeing everyday objects as evidence of change and continuity in daily life","Learning the market value of antiques and how to price old objects","Proving that life in the past was always harder than life today"],"answer":1,"explanation":"Material objects are sources; asking how they were used and what replaced them develops ideas of change and continuity in everyday life. 'Life was harder then' is a judgement the evidence alone does not establish.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-572","question":"Which of the following statements about using primary sources with Class VIII students are correct?\n1. Short, carefully chosen extracts with guiding questions work better than long documents.\n2. Students should be encouraged to ask who produced a source and why.\n3. Primary sources should replace the textbook entirely, since textbooks are secondary.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Manageable extracts and questions about authorship make sources accessible and build critical skills. Statement 3 goes too far: sources and textbooks complement each other, and a textbook gives the framework within which sources make sense.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-573","question":"A Class VIII teacher gives students census tables showing the literacy rates of boys and girls in their state over several decades and asks what changed and why. What does this activity mainly develop?","options":["The ability to memorise statistical figures for use in examinations","Map-drawing skills, by plotting the literacy figures on a map","Reading data as evidence of social change, including gender gaps","Knowledge of how the census is conducted and who collects data"],"answer":2,"explanation":"Interpreting data over time shows trends and inequalities, such as the gap between boys' and girls' literacy, and invites students to explain them. Memorising figures or census procedures misses the point.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-574","question":"Assertion (A): Conventional symbols are used on topographical maps.\nReason (R): Agreed symbols let anyone who knows the convention read a map without long written labels.","options":["A is true but R is false","Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":1,"explanation":"Standard symbols are used because they form a shared language that saves space and is understood across maps and readers. R is the reason for A.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-575","question":"A Class 5 child firmly says, ‘Plants eat soil. That is why we put them in pots of soil.’ Which teaching move is most likely to bring about real conceptual change?","options":["Writing ‘Plants make their food in the leaves’ on the board and asking children to learn it","Telling the child the idea is wrong and giving her a lower grade so that she remembers next time","Growing a money plant in a bottle of plain water for weeks and asking where its food comes from","Skipping the topic until Class 7, when photosynthesis is formally taught in the syllabus"],"answer":2,"explanation":"A plant thriving without soil directly contradicts the child’s idea and pushes her to look for another explanation. Restating the textbook line or penalising does not shift a belief rooted in experience.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-576","question":"Consider these statements about children’s alternative conceptions in EVS: I. They are often consistent and make sense to the child. II. They disappear once the teacher states the correct fact clearly. III. Many of them are found among children across different regions and cultures. IV. They are a sign of low intelligence. Which are correct?","options":["I and III only","I, II and III only","II and IV only","I and IV only"],"answer":0,"explanation":"Alternative conceptions are reasoned, widely shared and resistant to mere telling. They come from experience and language, not from low intelligence.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-577","question":"Children believe that ‘heavy things sink’. The teacher shows that a large, heavy wooden log floats while a small iron nail sinks, and the children are puzzled because their rule fails. In the conceptual-change model, this step mainly serves to:","options":["show that the new idea is useful in fresh situations","create dissatisfaction with the children’s existing idea","make the new idea clear and easy to understand","reward the children who gave the correct answer earlier on"],"answer":1,"explanation":"Posner and colleagues held that conceptual change begins when learners become dissatisfied with their current idea; the new one must then be intelligible, plausible and fruitful. This demonstration creates the dissatisfaction.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-578","question":"A Class 3 child says, ‘A car is living because it moves, but a tree is non-living because it does not move.’ The teacher’s best response is to:","options":["tell the child that cars are machines made in factories and therefore can never be living things","ask the child to memorise the textbook list of characteristics of living things","ignore it, since the child will understand the idea properly in a higher class","have children list what living things do (grow, feed, reproduce) and test the car and tree"],"answer":3,"explanation":"The child is using one criterion (movement). Having children examine several features themselves widens the concept through reasoning, which a bare correction or a memorised list does not.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-579","question":"Asked to circle the animals in a picture of a village, most Class 3 children circle the cow, the buffalo and the dog but not the ant, the crow or the boy. This most likely shows that:","options":["the children cannot see small creatures such as ants clearly in a printed picture","the children use a narrow everyday sense of ‘animal’, unlike the scientific one","the picture was badly drawn, so the smaller animals were hard to recognise","the children have not studied insects and birds yet, so the question is unfair"],"answer":1,"explanation":"In everyday use ‘animal’ often means a four-legged mammal, so insects, birds and humans are left out. This is a classic language-based alternative conception.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-580","question":"Several Class 3 children in an industrial town say that clouds are made of smoke from factory chimneys. Which teaching sequence best addresses this idea?","options":["Telling them clouds are made of water and asking them to write the correct answer five times","Showing a labelled diagram of the water cycle and naming each of its stages in order","Letting them see steam from boiling water form drops on a cold plate, then discussing clouds","Agreeing with them, since factories do pollute the air and smoke does rise into the sky"],"answer":2,"explanation":"The child’s idea comes from what she sees. Seeing water vapour condense gives a new, concrete experience from which she can build a better idea, before any diagram or term is used.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-581","question":"A Class 4 child walking home at night says, ‘The moon follows me wherever I go.’ Which activity best helps the child rethink this idea?","options":["Telling the child that the moon is very far away and actually moves around the earth, not her","Asking the child to read the chapter on the moon again and answer its questions","Asking the child to draw the moon in her notebook every night for a month","Having two children walk opposite ways at night and asking if the moon can follow both"],"answer":3,"explanation":"The activity creates a contradiction the child can see for herself and leads her to think about distance. Telling a fact does not engage the reasoning behind the belief.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-582","question":"A Class 5 child believes that ‘a sweater gives out heat and that is why it keeps us warm.’ Which activity most directly challenges this idea?","options":["Wrapping one ice cube in wool, leaving another bare, and comparing which melts first","Asking children to touch a sweater and say whether it feels warm or cold to their hands","Reading a passage on wool production by shepherds in Ladakh and Himachal","Asking children to list the woollen clothes their families wear in winter"],"answer":0,"explanation":"If the sweater gave out heat, the wrapped ice would melt faster; it melts more slowly, because wool slows the movement of heat. The prediction-contradiction is what challenges the idea.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-583","question":"Which demonstration most directly challenges a child’s belief that ‘heavier things always fall faster’?","options":["Dropping a brick and a feather together from the same height on the school playground","Dropping a flat sheet of paper and an identical sheet crumpled into a ball together","Dropping a heavy stone and a light dry leaf together from a rooftop","Dropping a cricket ball and an inflated balloon together from the same height"],"answer":1,"explanation":"The flat and crumpled sheets weigh the same yet fall differently, so weight cannot be the deciding factor. The other pairs seem to confirm the child’s belief.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-584","question":"Before teaching about rain, a Class 3 teacher wants to know what ideas children already hold. The most useful tool is to:","options":["give a ten-question multiple-choice test based on the textbook chapter","ask the textbook question ‘What is rain?’ and check answers against the book","ask children to draw ‘where rain comes from’ and explain their drawings","explain the water cycle first and then ask whether anyone has any doubts"],"answer":2,"explanation":"Open drawings with explanations reveal children’s own ideas, including unexpected ones. Closed tests and textbook questions check recall and hide alternative conceptions.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-585","question":"A teacher shows a picture in which three cartoon children give different reasons why a puddle has dried up, and asks the class whom they agree with and why. The main purpose of such a ‘concept cartoon’ is to:","options":["test how quickly and accurately children can read the speech bubbles","find out which children can draw and colour cartoon characters well","entertain children for a few minutes before the real lesson starts","bring out and discuss children’s ideas without fear of being personally wrong"],"answer":3,"explanation":"Concept cartoons present competing views so that children can argue for one without exposing their ‘own’ wrong answer, which makes it safe to reveal and examine alternative ideas.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-586","question":"Assertion (A): Children’s alternative conceptions are a hindrance and should be wiped out before any teaching begins. Reason (R): Children form ideas about the world through their own interaction with the environment. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Children’s ideas do come from experience (R is true), but they are the starting point for teaching, not something to ‘wipe out’ first; constructivist teaching builds on and reworks them.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-587","question":"A Class 4 child says that the drops on the outside of a glass of iced water have ‘leaked through the glass’. Which test best challenges this?","options":["Explaining to the child that glass has no holes through which water could pass","Adding ink to the water and checking whether the drops outside turn coloured","Wiping the drops away and asking the child to taste the water inside","Using a steel glass instead and simply telling the child the right answer"],"answer":1,"explanation":"If water leaked, the outside drops would carry the ink colour; they stay clear, so they must come from somewhere else (the air). The test lets evidence, not authority, settle the matter.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-588","question":"A teacher sticks a piece of dry paper to the bottom inside of a glass, turns the glass upside down and pushes it straight down into a bucket of water. The paper stays dry. This activity is mainly meant to challenge the idea that:","options":["water is lighter than the air above it","paper does not absorb water at all","an ‘empty’ glass contains nothing","glass is not a living thing"],"answer":2,"explanation":"Air trapped in the glass keeps the water out, showing that the ‘empty’ glass is full of air, which takes up space. Children commonly think empty means nothing is there.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-589","question":"Class 3 children classify a seed as non-living because ‘it does not move or eat’. The best response is to:","options":["sow soaked seeds and keep others dry, then watch over days for signs of life","tell them that seeds are living things and ask them to remember the fact","show them a picture of a big tree and say that it grew from a small seed","accept their answer, since seeds really do not move, eat or breathe"],"answer":0,"explanation":"Seeing seeds germinate under the right conditions, unlike the dry ones, gives evidence that seeds are alive but dormant. Simply stating it does not shift the child’s criterion.","difficulty":"hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-590","question":"Which of the following can be sources of children’s alternative conceptions? I. Everyday language, such as ‘the sun rises’. II. Direct sensory experience. III. Textbook illustrations and over-simplified statements. IV. The teacher’s own explanations.","options":["I and II only","I, II and III only","II and IV only","I, II, III and IV"],"answer":3,"explanation":"Alternative conceptions arise from everyday talk and experience, but also from simplified textbook material and from teachers who hold the same ideas. All four are sources.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-591","question":"To check whether Class 5 children really understand why wet clothes dry, which question is best?","options":["What is evaporation? Write its definition from the textbook.","Name the process by which wet clothes dry, and write its definition in one line.","Will clothes dry faster on a windy day or a still day, if both are sunny? Why?","Do clothes dry in the sun? Write yes or no and name the process."],"answer":2,"explanation":"Applying the idea to a new situation and giving a reason shows understanding; the others can be answered by recalling a word.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-592","question":"After a lesson with several floating and sinking activities, many Class 4 children still say that ‘heavy things sink’. The best interpretation for the teacher is that:","options":["the children were not paying attention during the activities and need to be warned firmly","alternative conceptions resist change and need repeated experiences in varied contexts","the activities were the wrong choice and should be replaced with clear lectures","these children are not yet ready for EVS and need separate remedial classes first"],"answer":1,"explanation":"Research on alternative conceptions shows they persist after a single lesson; children need repeated, varied encounters and discussion. Blaming the children or going back to lectures misreads this.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-593","question":"A Class 1 child says, ‘The sun is sad today, so it has hidden behind the clouds.’ This kind of thinking is best described as:","options":["animism, typical of Piaget’s pre-operational stage","egocentrism, typical of the formal operational stage","conservation, typical of the concrete operational stage","hypothetical reasoning, typical of the formal operational stage"],"answer":0,"explanation":"Giving feelings and intentions to non-living things is animism, characteristic of the pre-operational stage (about 2–7 years). The other options name the wrong process or the wrong stage.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-594","question":"A teacher asks Class 5 children what will happen when the ice in a glass of water filled to the brim melts. Most predict that it will overflow. They watch, see that it does not, and then try to explain why. This strategy is called:","options":["Drill and practice method","Programmed instruction","Predict–Observe–Explain","Advance organiser"],"answer":2,"explanation":"Predict–Observe–Explain brings out children’s ideas (predict), confronts them with evidence (observe) and pushes for reconciliation (explain).","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-595","question":"A Class 4 child draws the sun as a small circle next to a large earth. The teacher’s most appropriate response is to:","options":["mark the drawing wrong and draw the correct sizes beside it","ask the child to explain her drawing and use it to understand how she is thinking","praise the drawing for its colours and move on","tell the class that the sun is much bigger than the earth and ask them to copy the line"],"answer":1,"explanation":"A drawing is a window into the child’s ideas; asking her to explain it reveals the reasoning (the sun looks small) that the teacher must work with. Marking it wrong closes that window.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-596","question":"Class 4 children studying houses in Ladakh say, ‘The roofs are flat because the people there are too poor to make sloping roofs.’ The teacher should:","options":["agree, because Ladakh is a remote area where families have little money","tell them the correct reason about the climate and move on to the next chapter","avoid the topic, since it may hurt the feelings of children from Ladakh","guide them to find out how little rain falls there and how flat roofs are used"],"answer":3,"explanation":"The remark is a social-science alternative conception built on stereotype. Linking house design to climate and use replaces the assumption with reasoning and builds respect for other ways of life.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-597","question":"Which of the following is LEAST useful for finding out the ideas children bring to an EVS topic?","options":["A true/false test whose statements are taken word for word from the textbook","Asking children to draw what they think happens and then explain it to the class","An open discussion in which the teacher asks ‘What do you think, and why?’","A concept cartoon showing different views for children to argue about"],"answer":0,"explanation":"Textbook-based true/false items test recognition of book statements and give no reasons, so they hide the child’s own ideas. The others are open and reveal reasoning.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-598","question":"A Class 3 child says, ‘A hen is not an animal, because animals give birth to babies and hens lay eggs.’ The best response of the teacher is to:","options":["have children list many animals, find how the young of each are born or hatched, and rethink ‘animal’","tell the child that hens are birds, and that birds are not counted as animals","explain the scientific classification of vertebrates into five classes, with examples of each","correct the child and give a lower grade, so that the mistake is not repeated"],"answer":0,"explanation":"Exploring many examples widens the child’s narrow category. Saying ‘birds are not animals’ is itself a misconception, and formal classification is beyond the stage.","difficulty":"very-hard","source":"CTET Paper 1 · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-599","question":"After a lesson on how leaves make food, a Class 5 child writes, ‘Plants take food from the soil and then cook it in the leaves.’ This answer best shows that the child has:","options":["joined the new information to her old idea, so her conception has changed only partly","fully understood how plants make food, and simply expressed it in her own everyday words","not listened in class at all and is repeating what she believed before","copied the answer from another child without understanding it herself"],"answer":0,"explanation":"Such ‘hybrid’ answers are common: new words are attached to an old framework. The teacher should probe further rather than treat it as either complete success or plain failure.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-600","question":"Which of the following does NCF 2005 recommend for the secondary stage rather than for the upper primary stage of science?","options":["Learning the principles of science through familiar experiences and simple experiments","Designing simple technological units and modules with one's own hands","Learning about environment and health through activities and local surveys","Studying science as disciplines, stressing abstraction and quantitative reasoning"],"answer":3,"explanation":"NCF 2005 keeps upper primary science close to familiar experience, hands-on technology, activities and surveys; abstraction, quantitative reasoning and disciplinary treatment begin at the secondary stage.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-601","question":"Assertion (A): At the upper primary stage, scientific concepts should be arrived at mainly through activities and experiments. Reason (R): Children at this stage can learn science only by memorising definitions and laws.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"NCF 2005 wants concepts at this stage to come mainly from activities and experiments, so A is true. R contradicts this view; memorising definitions is what it argues against.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-602","question":"A Class 7 teacher wants students to understand pollination. Going by Edgar Dale's Cone of Experience, which option gives the most concrete experience?","options":["Watching a close-up documentary film on how bees and butterflies pollinate different flowers","Watching bees visit flowers in the school garden and examining the flowers with a hand lens","Studying a large labelled wall chart of the parts of a flower and pollination","Listening to the teacher's detailed explanation of pollination with examples"],"answer":1,"explanation":"Dale's Cone places direct, purposeful experience at the base (most concrete) and verbal symbols at the top (most abstract), with films and charts in between.","difficulty":"moderate","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-603","question":"In which of the following situations is a computer simulation more suitable than a real activity for Class 8 students?","options":["Finding the boiling point of water using a thermometer in the laboratory","Testing which classroom objects a bar magnet attracts","Showing how the positions of the planets change over several years","Observing the germination of gram seeds on wet cotton over a week"],"answer":2,"explanation":"Simulations are best for what cannot be observed directly in class because of scale, time or danger. Boiling, magnetism and germination can and should be experienced first-hand.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-604","question":"After rumours spread in a town that idols were 'drinking' milk, a science teacher shows how a liquid rises up through a thin tube and a lump of sugar, and asks students to explain the rumour. Which constitutional fundamental duty is she most directly promoting?","options":["To develop the scientific temper, humanism and the spirit of inquiry and reform","To protect and improve the natural environment including forests, lakes, rivers and wild life","To safeguard public property and to abjure violence","To value and preserve the rich heritage of our composite culture"],"answer":0,"explanation":"Article 51A(h) asks citizens to develop the scientific temper, humanism and the spirit of inquiry and reform. Explaining a 'miracle' by capillary action does exactly this.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-605","question":"In mixed groups during science practicals, a teacher notices that boys always handle the apparatus while girls only record the readings. The most suitable action is to:","options":["Leave the groups as they are, since students have chosen their own roles freely","Form separate groups for boys and girls so that the girls also get a chance to handle apparatus","Ask the girls to be more confident, without changing anything else in the groups","Assign rotating roles so that every student handles apparatus, records and reports"],"answer":3,"explanation":"Rotating roles ensures equal hands-on experience and challenges gender stereotypes within the group. Leaving it alone or blaming the girls preserves the inequity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-606","question":"In a school in a tribal district, Class 6 students know many local plants by their Gondi names but not by their textbook names. The teacher's best approach is to:","options":["Insist that students use only the textbook names in class, to avoid confusion","Use the local names as a starting point and link them to the textbook names","Avoid discussing local plants, since they are not part of the prescribed syllabus","Teach only the scientific names, since they are the same all over the world"],"answer":1,"explanation":"NCF 2005 treats the learner's language and local knowledge as resources; connecting known names to new terms builds understanding and respect. Excluding them alienates learners.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-607","question":"Which question asked in a Class 7 lesson on food preservation is the most divergent?","options":["At what temperature does a household refrigerator usually keep food fresh?","What is the chemical name of the common salt that is used to preserve fish?","How many ways could a village family without electricity keep milk from spoiling?","Which preservative is commonly used in pickles made at home?"],"answer":2,"explanation":"A divergent question admits many valid answers and invites creative thinking; the others have a single expected answer (convergent).","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-608","question":"A teacher asks, 'Why do we sweat more on a hot day?' and immediately calls on the first student whose hand goes up. Classroom research suggests she would get more thoughtful answers from more students if she:","options":["Asked only the brightest students, who are likely to answer correctly","Repeated the question quickly in different words","Gave the answer herself to save time","Waited a few seconds after asking before calling on anyone"],"answer":3,"explanation":"Increasing wait time to three to five seconds leads to longer, better-reasoned answers and more students taking part. Instant calling rewards only the fastest.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-609","question":"A teacher asks students to draw a concept map linking 'photosynthesis, chlorophyll, sunlight, glucose, respiration, energy'. Compared with an MCQ test on the same topic, the main advantage of the concept map is that it:","options":["Is quicker and easier to mark objectively, using a fixed answer key for all","Reveals how the student links the ideas, including missing or wrong links","Covers more facts in less time than an MCQ test can","Avoids the need for any further assessment of the topic later"],"answer":1,"explanation":"A concept map makes the structure of a learner's understanding visible: which concepts are linked, how, and where the links are faulty. MCQs show only isolated right or wrong answers.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-610","question":"Throughout the year, a Class 8 student keeps her observation records, project reports, drawings and reflections on what she learned in a file, which the teacher reviews periodically. This assessment tool is a:","options":["Portfolio, which shows progress over time","Anecdotal record, which notes significant incidents","Rating scale, which grades a single performance","Achievement test, which measures learning at the end"],"answer":0,"explanation":"A portfolio is a purposeful collection of a learner's work over time, which shows growth and allows reflection. An anecdotal record is the teacher's note of specific incidents.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-611","question":"Before Class 8 students begin a project on water quality in their locality, the teacher shares a rubric listing criteria (data collection, analysis, presentation) and what each level of performance looks like. The main benefit of sharing it in advance is that:","options":["The teacher can then award marks without having to read the reports in detail","Students will all get the same marks if they follow it","Students know what good work looks like and can check their own progress","It removes the need to give any feedback after the project is over"],"answer":2,"explanation":"A rubric shared in advance makes expectations transparent and supports self-assessment, making it a tool for learning and not just grading.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-612","question":"At the end of each science period, a teacher asks students to write one thing they understood and one question they still have on a slip of paper, and uses the slips to plan the next lesson. This practice is best described as:","options":["Assessment of learning, since it comes at the end of the period","Summative assessment, since it covers the whole of the day's lesson","Norm-referenced testing, since slips are compared across students","Assessment for learning, since it guides the next steps of teaching"],"answer":3,"explanation":"Exit slips give ongoing feedback used to adjust teaching, which is formative assessment (assessment for learning). Its timing at the end of the period does not make it summative.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-613","question":"Sana has measured a bean plant every day: it has grown about 1 cm each day and is now 9 cm tall. She says, 'It will be about 15 cm tall six days from now.' Which process skill is she using?","options":["Inferring","Predicting","Classifying","Hypothesising"],"answer":1,"explanation":"Forecasting a future observation from a pattern in data is predicting. She offers no explanation of why the plant grows, so it is not a hypothesis.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-614","question":"After an experiment on the solubility of salt at different temperatures, a group presents its results as a bar graph and explains it to the class. Which process skill is mainly being developed?","options":["Communicating","Controlling variables","Measuring","Observing"],"answer":0,"explanation":"Presenting data through graphs, tables and explanations so that others can understand it is communicating. Measuring and observing came earlier, while collecting the data.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-615","question":"A teacher presents legends about ancient flying machines as established scientific fact, without any evidence. From the point of view of the NCF 2005 science criteria, the main problem is that:","options":["It violates historical validity, because history should not be taught in science","It violates cognitive validity, because the legends are too complex for children","It violates content validity, because unsupported claims are presented as correct science","It violates environmental validity, because the flying machines are not part of the local environment"],"answer":2,"explanation":"Content validity requires that what is taught as science be correct and significant. Historical validity welcomes the real history of science, but presenting unverified claims as fact distorts both history and science.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-616","question":"Which of the following fall under environmental validity as described in the NCF 2005 position paper on science? 1. Placing science in the wider context of the learner's environment, local and global. 2. Helping learners appreciate issues at the interface of science, technology and society. 3. Equipping learners with knowledge and skills to enter the world of work. 4. Promoting honesty and objectivity in the conduct of science.","options":["1 and 2 only","1, 2 and 3 only","1, 2, 3 and 4","2, 3 and 4 only"],"answer":1,"explanation":"Environmental validity covers the learner's environment, science-technology-society issues and preparation for the world of work. Honesty and objectivity come under ethical validity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-617","question":"A Class 6 chapter on food from plants introduces photosynthesis using terms such as 'thylakoid', 'light reactions' and 'Calvin cycle', all stated correctly. Judged by the NCF 2005 criteria, the chapter is weakest in:","options":["Content validity","Historical validity","Ethical validity","Cognitive validity"],"answer":3,"explanation":"The content is correct, so content validity is met, but the terms and abstraction are beyond the reach of eleven-year-olds, which violates cognitive validity.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-618","question":"A science textbook chapter gives correct, well-organised facts about magnets, but contains no activities, no open questions and no tasks in which students observe or test anything themselves. It is weakest in:","options":["Process validity","Content validity","Cognitive validity","Ethical validity"],"answer":0,"explanation":"Process validity requires that learners engage in the methods and processes of science, such as observing, testing and reasoning from evidence. Correct facts alone satisfy content validity only.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-619","question":"In a Class 7 class there is a student with low vision. For a lesson on the structure of a flower, the teacher's most suitable arrangement is:","options":["Excusing her from the lesson and giving her printed notes to read later at home","Providing large real flowers and a tactile model to explore, with clear oral description","Seating her at the back so that she does not disturb others who can see the board","Giving her the same small textbook diagram as everyone else, so that all are treated equally"],"answer":1,"explanation":"Inclusive science uses multi-sensory resources such as real specimens, tactile models and verbal description so that every learner takes part in the same lesson. Excusing or ignoring her denies her the learning.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-620","question":"Consider the following statements about the science textbook in the light of NCF 2005. 1. It is one of several resources and not the only source of knowledge. 2. A teacher should never go beyond the textbook in class. 3. Questions in it should include some that have no single 'right' answer. 4. Its activities should be done, not just read about.","options":["1 and 2 only","2 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"NCF 2005 discourages treating the textbook as the sole authority and encourages open-ended questions and doing the activities. Statement 2 contradicts its call to link learning to life outside school.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-621","question":"A Class 8 teacher finds that her students can recite the definition of friction but cannot say why a matchstick lights only when rubbed on the side of the box. This most clearly shows that:","options":["The students need to memorise the definition more thoroughly before tests","The topic of friction is too difficult for Class 8","The students have not paid attention in class","Learning was rote and had not been connected to everyday experience"],"answer":3,"explanation":"Being able to recite a definition but not apply it to a familiar situation is the mark of rote learning. More memorising will not help; linking concepts to experience will.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-622","question":"In a lesson on magnets, a student asks, 'Why do two north poles push each other away?' The teacher replies, 'That is just how it is; it will come in the exam.' The main weakness of this reply is that it:","options":["Encourages accepting claims on authority and discourages students' curiosity","Gives the student too much information at once, so the main idea is lost","Is too difficult for the student to understand at this stage of learning","Shows that the teacher relied only on the textbook rather than on her own notes"],"answer":0,"explanation":"Science teaching should nurture curiosity and reasoning from evidence. Answering on authority teaches students that questions are unwelcome; the teacher could instead invite them to explore magnets and find patterns.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-623","question":"A teacher in a Class 8 class of 60 students says she cannot do any activities because the class is too big and there is no laboratory. Which response best addresses the problem?","options":["Teaching only through lectures, since activities are impossible in large classes","Doing all activities as teacher demonstrations at the front, with no student involvement","Organising small groups with low-cost materials and clear roles within each group","Asking only a few students to do the activities while others watch"],"answer":2,"explanation":"Group work with low-cost materials and clear roles makes activity-based learning possible even in large classes without a laboratory. Lectures or demonstrations alone leave most students passive.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-624","question":"While teaching nutrition, a teacher asks students to find out what their families eat in a week, compare meals across households of different income, and discuss why some families cannot afford a balanced diet. Which NCF 2005 criteria does this activity serve most clearly?","options":["Cognitive validity and content validity","Historical validity and ethical validity","Process validity and historical validity","Environmental validity and ethical validity"],"answer":3,"explanation":"Relating nutrition to households and income places science in the learner's social environment (environmental validity), and discussing why some cannot afford food builds concern for others (ethical validity).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-625","question":"A Class VI teacher in Palghar wants to use Warli painting in a science unit on the water cycle. Which activity is a true example of art-integrated learning?","options":["Children colour a printed water-cycle diagram and decorate it with Warli-style borders","After the science period, children have a separate art period in which they copy a Warli painting","Children make a Warli-style mural of evaporation, condensation and rain, and explain each stage","The teacher shows a short video on Warli art at the end of the lesson as a reward"],"answer":2,"explanation":"In art-integrated learning the art form is the medium through which children explore and express the concept, and the explanation shows their understanding. Colouring a diagram, a separate art period or a video reward keeps art and concept apart.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-626","question":"Consider the following statements about art-integrated learning (AIL): 1. Visual and performing arts are used as tools to learn concepts of other subjects. 2. It expects every child to produce artwork of professional quality. 3. Local and regional art forms of the children's area can be used. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"AIL values the process of learning through art and draws on local art traditions; it does not demand professional-quality products, so statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-627","question":"Assertion (A): In art-integrated learning, children should be assessed mainly on how beautiful their final artwork looks. Reason (R): Art-integrated learning aims at experiential learning of concepts through art forms.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Since AIL is about learning concepts through art, assessment should look at the process, the child's understanding and expression, not only the beauty of the product. R is true and actually contradicts A.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-628","question":"A Class VIII teacher organises a role play of a Constituent Assembly debate on official language, with groups representing different regions. What is the main learning this role play is designed to produce?","options":["Memorising the dialogues and speeches of famous leaders word for word for the test","Seeing the Constitution as shaped by negotiation, and viewing the issue from others' perspectives","Improving children's acting and speaking skills for the annual day function","Covering the chapter quickly and in an entertaining way, without the need for any discussion afterwards"],"answer":1,"explanation":"Drama in social science builds perspective-taking and shows that decisions came out of debate and compromise. Rote dialogue or performance alone misses this purpose.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-629","question":"A Class II child in Shimla draws the sun purple and the trees blue. Which response from the teacher is most appropriate?","options":["'The sun is yellow and trees are green. Please colour it again correctly.'","'Very nice' without looking closely, and move on to the next child","Display the drawing as an example of what not to do","'Tell me about your picture. Why did you choose purple for the sun?'"],"answer":3,"explanation":"Children's art is self-expression; inviting the child to talk about choices values creativity and builds language. Correcting colours to 'real' ones or empty praise both fail the child.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-630","question":"A Class III teacher in Jorhat plays a Bihu song and asks children to clap its repeating beat, show the beat with shapes, and then invent and clap their own repeating patterns for classmates to continue. What is the most important learning in this activity?","options":["Learning the words of the Bihu song by heart so it can be sung in the assembly","Practising clapping in rhythm together for a cultural programme at the end of the term","Recognising, extending and creating patterns, a key maths idea, through a familiar art","Relaxing and energising children before the real maths lesson begins"],"answer":2,"explanation":"Here music is the medium for pattern recognition and generalisation, which is central to early mathematical thinking. Remembering lyrics or rehearsing for a programme is not the goal.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-631","question":"A Class IV teacher pins only the five 'best' drawings on the display board each week. What is the most valid criticism of this practice?","options":["It signals that most children's work is not valued; every child's work should be displayed","Five drawings are too few; the ten best drawings should be displayed each week instead","Drawings should not be displayed at all, as a busy board distracts children during lessons","The teacher should display her own drawings as a model for children to copy instead"],"answer":0,"explanation":"Displaying everyone's work builds belonging and confidence, which matters especially in art. Expanding the 'best' list keeps the same exclusion, and hiding all work loses the motivation display gives.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-632","question":"A Class VII teacher in Madhubani district wants to integrate the local painting style into a lesson on line symmetry. Which task shows the deepest integration of art and mathematics?","options":["Children colour a photocopied Madhubani painting using the traditional colours","Children read a paragraph on the history of Madhubani painting and answer questions on it","Children design a Madhubani-style border with a set line of symmetry and test it with a mirror","Children copy any Madhubani painting freehand as homework and bring it to class"],"answer":2,"explanation":"Designing to a symmetry condition, testing it and explaining it requires the mathematical idea to shape the artwork. Colouring, copying or reading history do not engage the concept of symmetry.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-633","question":"In a Class I craft period, the teacher shows a finished paper boat and has all children fold identical boats step by step after her. A teacher educator suggests a more open approach. Which suggestion best fits the spirit of art education in NCF?","options":["Give children paper and a few folds, let them invent their own floating objects, then test them","Continue the step-by-step copying, but award marks for the neatness and accuracy of each fold","Let only the children who can already fold neatly take part in the craft activity","Replace craft with drawing, since drawing is easier to teach to young children"],"answer":0,"explanation":"Art education aims at exploration, imagination and self-expression, not identical reproduction of a model. Testing their own designs also adds inquiry. Marking neatness or excluding children moves further away from this aim.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-634","question":"A Class VII class visits a milk cooperative in Anand. Back in school: P. children write what they noticed and discuss what surprised them; Q. the teacher helps them form the general idea of a cooperative and how it differs from a private dairy; R. children plan and run a small class cooperative stall. In Kolb's experiential learning cycle, P, Q and R are respectively:","options":["active experimentation, reflective observation, abstract conceptualisation","reflective observation, active experimentation, abstract conceptualisation","abstract conceptualisation, reflective observation, active experimentation","reflective observation, abstract conceptualisation, active experimentation"],"answer":3,"explanation":"Kolb's cycle runs: concrete experience (the visit), reflective observation (P), abstract conceptualisation (Q, forming the general idea), and active experimentation (R, trying it out).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-635","question":"Assertion (A): Every hands-on activity in a classroom is an example of experiential learning. Reason (R): Experiential learning requires learners to reflect on their experience and draw meaning from it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false, but R is true","A is true, but R is false"],"answer":2,"explanation":"Doing an activity is not enough; without reflection and conceptualisation it remains 'activity for activity's sake'. R is true and shows why A is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-636","question":"Consider the following statements about Edgar Dale's Cone of Experience: 1. Direct, purposeful experiences form its base and verbal symbols are at its top. 2. It provides research-proven percentages showing that learners remember 10% of what they read and 90% of what they do. 3. Dale did not claim that abstract experiences are useless; he saw the cone as moving between concrete and abstract as learners need. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"The retention percentages often printed with the cone were added later by others and are not part of Dale's work or backed by his research, so statement 2 is false. Statements 1 and 3 describe the cone correctly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-637","question":"For a Class V project on 'Water sources in our village' in a Rajasthan school, which design best reflects project-based, experiential learning?","options":["Children copy information about water sources in India from the internet and paste pictures into a neat file","Children survey local wells and tanks, interview elders, record data and present findings to the panchayat","Parents prepare attractive project files at home, which are displayed at the school exhibition","The teacher dictates notes on water sources and children write them neatly in a project file"],"answer":1,"explanation":"A real project involves inquiry into a local, authentic question, first-hand data and a product shared with a real audience. Copying, parental work or dictated notes keep the child passive.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-638","question":"A Class IV teacher is planning a visit to a local post office. Which plan is most likely to turn the visit into real learning?","options":["Children frame questions before, observe and record during, and discuss findings after the visit","The visit itself is enough, since children learn automatically just by seeing new places and people","Children are told to remain silent and only listen to the postmaster to avoid indiscipline","After the visit children write a 200-word essay titled 'A Visit to the Post Office'"],"answer":0,"explanation":"Field trips work when framed by pre-visit questions, focused observation and post-visit reflection. Simply going, listening passively or writing a generic essay misses the inquiry cycle.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-639","question":"A Class VI PE teacher and maths teacher jointly plan a sports-integrated lesson: children run a 50 m race in groups, time it, and then work out averages and compare speeds. According to the idea of sports-integrated learning promoted in NEP 2020, which statement is most accurate?","options":["It is only a PE activity, since the maths is incidental and can be ignored","Sports should be kept separate from academic subjects to avoid wasting class time","Physical activity becomes a real context for learning concepts, while building teamwork and fitness","Only children who are good at sports benefit, so the slow runners should just record the times instead"],"answer":2,"explanation":"NEP 2020 lists sports-integrated learning as a cross-curricular approach: real data from physical activity makes averages and speed meaningful and builds life skills. Excluding slower runners would defeat its inclusive purpose.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-640","question":"A school in Satara has a vegetable garden. Which way of using it is closest to John Dewey's idea of learning by doing?","options":["The school gardener tends the garden while children watch from the classroom window during EVS","Children read the chapter on plants and then visit the garden once to see and name the plants growing there","Children copy notes on gardening and are then tested on the names of the vegetables","Children plan beds, sow and water seeds, measure growth, tackle pests and discuss what they learn"],"answer":3,"explanation":"Dewey saw learning as growing out of purposeful, real activity in which children face genuine problems and reflect on them. Watching or reading about a garden keeps them as spectators.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-641","question":"A Class VII social science teacher holds a mock election in school, with nominations, campaigning, secret ballot and counting. Which follow-up makes the experience most educational?","options":["Announcing the winner in the assembly and moving straight on to the next chapter","A discussion comparing it with real elections: fairness, secret ballot and the Election Commission","Giving a prize to the winning candidate to motivate others to stand next time","Asking children to write the definition of 'election' five times in their notebooks for homework"],"answer":1,"explanation":"Simulation becomes learning when children reflect on it and link it to the real institution. Announcing results or giving prizes leaves the experience unprocessed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-642","question":"While writing on the blackboard, Ms Rao says without turning around, 'Ravi and Imran, please put that away and finish the sum.' The children are surprised that she knew. In Kounin's terms this teacher behaviour is called:","options":["Ripple effect","Withitness","Overlapping","Group alerting"],"answer":1,"explanation":"Withitness is the teacher's awareness of everything happening in the room, communicated to students so they know she 'has eyes at the back of her head'. Overlapping is attending to two things at once; the ripple effect is how correcting one child affects others.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-643","question":"In the first week of a new session, a Class V teacher wants to set classroom rules that children will actually follow. Which approach is best?","options":["Display a long list of 'Do nots' prepared by the teacher and read it aloud to the class every morning","Avoid rules altogether, since children of this age will learn to regulate themselves","Copy the rules from the previous year's class and announce the punishment for each","Discuss why rules are needed, agree on a few positive rules together, and revisit them as needed"],"answer":3,"explanation":"Rules that children help make, that are few, positive and explained, are owned and followed. Imposed lists of prohibitions invite resistance, and having no rules leaves children without structure.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-644","question":"A colleague advises a new teacher: 'Making a child stand outside the class on one leg is fine, because you are not touching the child.' Which statement is correct?","options":["It is allowed, because the law prohibits only physical beating, not other forms of punishment","It is allowed if the parents have given the school their written consent for such punishments","It is not allowed: the RTE Act 2009 bans physical punishment and mental harassment of children","It is allowed for serious misbehaviour, but not for minor mistakes such as forgetting homework"],"answer":2,"explanation":"Section 17 of the RTE Act bans physical punishment and mental harassment; making a child stand outside on one leg is both painful and humiliating. Parental consent or seriousness of misbehaviour does not make it legal.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-645","question":"During a Class III lesson, Sameer keeps tapping his pencil loudly, looking around to see who notices. No one else is disturbed much and no one is at risk. Which teacher response is most appropriate first?","options":["Ignore the tapping on purpose and praise Sameer as soon as he is back on task","Stop the lesson and scold Sameer in front of the class so that others also learn","Send Sameer to the principal's office so that the lesson is not disturbed","Take away his pencil for the rest of the day as a firm consequence"],"answer":0,"explanation":"For low-level attention-seeking behaviour, planned ignoring combined with attention for appropriate behaviour removes the payoff of misbehaving. Public scolding gives exactly the attention sought and disrupts everyone.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-646","question":"In Ms Thomas's Class IV, a lot of time is lost and noise rises every time the class moves from one activity to another. Which strategy is most likely to solve this?","options":["Cut out group activities altogether and keep the children in a single whole-class activity all day","Raise her voice at each transition until the whole class settles down again","Set clear routines and a signal for transitions, keep materials ready, and practise the routine","Give extra homework to the whole class whenever the noise level rises"],"answer":2,"explanation":"Smooth transitions depend on predictable routines, signals and preparation (Kounin's momentum and smoothness). Abandoning active work, shouting or collective punishment treat symptoms and harm learning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-647","question":"Arrange these teacher responses to a minor disturbance by two talkative Class VI students from the least intrusive to the most intrusive: P. a private conversation after class; Q. a meaningful look; R. moving to stand near them while teaching; S. using a student's name naturally in the lesson ('Suppose Neha has 3 apples...').","options":["R, Q, S, P","Q, S, R, P","Q, R, S, P","S, Q, R, P"],"answer":2,"explanation":"Effective managers begin with the least disruptive interventions: non-verbal look, proximity, then drawing the student in by name, and only then a private talk. Each step keeps the lesson flowing as long as possible.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-648","question":"A Class VI teacher loudly and harshly humiliates one child for chewing gum. Afterwards the rest of the class is quiet but anxious, and fewer children volunteer answers. Which conclusion is best supported by research on classroom management?","options":["Harsh public correction is effective, since the whole class became quiet and orderly straight afterwards","Corrections ripple to onlookers: firm, clear ones help, but harsh, humiliating ones breed anxiety","The teacher should have ignored the gum-chewing completely, since it was not disturbing anyone","Quiet classes always show that learning is taking place, so the correction worked as intended"],"answer":1,"explanation":"Kounin found that corrections affect onlookers (the ripple effect); clarity and firmness improve behaviour, but roughness mostly produces fear rather than better conduct. A quiet room is not evidence of learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-649","question":"While working with a small reading group, a Class II teacher notices a child at another table looking lost. Without leaving the group, she signals him to start the next task and keeps the group reading. In Kounin's terms, she is showing:","options":["Overlapping","Withitness only","Satiation","The ripple effect"],"answer":0,"explanation":"Overlapping is the ability to handle two classroom matters at the same time without breaking the flow. Withitness is awareness; she shows it too, but the skill of dealing with both together is overlapping.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-650","question":"When the teacher turns a square cut-out so that it stands on a corner, several Class 3 children say ‘Now it is a diamond, not a square.’ What is the best way to respond?","options":["Tell them that ‘diamond’ is the correct name for a square only when it is tilted on a corner","Ask them to learn the definition of a square by heart and to repeat it whenever they see a tilted one","Show squares in many sizes and positions, and let children check that sides and corners stay the same","Use only upright squares in class from now on, so that the children are not confused again"],"answer":2,"explanation":"At the visual level children judge shapes by overall look and by the usual textbook position. Varied orientations plus checking properties moves them towards analysis; showing only upright squares makes the problem worse.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-651","question":"A Class 6 student says two lines crossing at a right angle are ‘not perpendicular’ because neither of them is standing straight up. What has shaped this idea?","options":["Lines are nearly always drawn one flat and one upright, so she takes position as part of the meaning","Not yet knowing how to place a protractor to measure the angle between two crossing lines","Confusing perpendicular lines with parallel lines, which never meet","A correct understanding, since ‘perpendicular’ simply means vertical, as with a builder's plumb line"],"answer":0,"explanation":"A standard textbook picture (one vertical line on a horizontal one) gets mistaken for the definition. Perpendicular means meeting at 90°, in any position, so tilted examples must be shown.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-652","question":"A Class 8 student explains, ‘A rhombus is a special kite, because a kite needs two pairs of equal sides next to each other, and a rhombus has that.’ In the Van Hiele model this student is reasoning at the level of:","options":["visualisation (recognition)","informal deduction (order)","analysis (description)","formal deduction (proof)"],"answer":1,"explanation":"Using the defining properties to place one class of shapes inside another (class inclusion) is informal deduction. At analysis, students list properties but do not yet relate one class of shapes to another.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-653","question":"Children fold and cut paper kites by following the teacher's step-by-step instructions, and each step leads them to discover that the diagonals cross at a right angle. Which Van Hiele phase of learning is this?","options":["Inquiry (information)","Explicitation","Free orientation (open tasks)","Directed orientation"],"answer":3,"explanation":"In directed orientation, carefully sequenced tasks set by the teacher lead students to the key properties. Free orientation comes later, with open, many-step tasks that students solve their own way.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-654","question":"After exploring kites, children describe in their own words what they noticed, and only then does the teacher give the word ‘diagonal’. In the Van Hiele phases of learning this is:","options":["integration","inquiry (information)","explicitation","free orientation"],"answer":2,"explanation":"Explicitation is when learners put their observations into words and the teacher introduces the technical terms. Integration is the final phase, when students summarise and connect what they have learnt.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-655","question":"A Class 9 teacher writes formal two-column proofs for students who still reason at the analysis level. According to the Van Hiele theory, the most likely result is that:","options":["students memorise the proofs without understanding, as the language is above their level","students quickly move up to the deduction level because they see proofs modelled","students skip the informal deduction level and go straight on to formal proof","students lose the properties they learnt at the analysis level and have to relearn them later"],"answer":0,"explanation":"Van Hiele stressed that each level has its own language; teaching above the learner's level leads to rote learning. Levels are not skipped, and learners do not lose earlier levels.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-656","question":"Which of these statements about the Van Hiele levels are correct? I. Moving up depends more on teaching and experience than on age. II. Each level has its own language and symbols. III. A good student can skip a level if taught well. IV. Two people reasoning at different levels may fail to understand each other.","options":["I and III only","I, II and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"The levels are sequential, so none can be skipped (III is false). Progress depends on instruction, not age, and each level has its own language, which is why teacher and student can talk past each other.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-657","question":"A student agrees that ‘a quadrilateral with four right angles’ is enough to define a rectangle, because equal opposite sides then follow. Which Van Hiele level does this show?","options":["Visualisation (recognition)","Analysis","Informal deduction","Formal deduction"],"answer":2,"explanation":"Seeing that some properties imply others, and so accepting a minimal definition, marks informal deduction. At analysis a student insists on listing every property.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-658","question":"Shown two angles, a Class 5 child says the one with longer arms is bigger, though it is actually smaller. Which activity best addresses this?","options":["Ask her to measure both angles with a protractor and write the two readings neatly side by side","Give her the definition ‘an angle is formed by two rays with a common end-point’","Draw both angles with arms of the same length from now on so that she is not confused","Let her open a pair of hinged strips by different amounts and compare turns, varying the arms"],"answer":3,"explanation":"Seeing an angle as an amount of turn, and noticing that changing arm length does not change the turn, targets the misconception. Making the arms equal removes the very thing she needs to reason about.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-659","question":"A Class 6 student measures an angle that is clearly less than a right angle and writes 130°. What is the most likely cause, and the best habit to build?","options":["She read the wrong scale; she should first estimate whether the angle is acute or obtuse","She does not know what a right angle is, so she cannot tell acute from obtuse","She placed the centre of the protractor away from the vertex, so the whole reading shifted","She has misread 30° as 130°, and simply needs to read the numbers more carefully"],"answer":0,"explanation":"Angles of 50° and 130° sit on the same mark of the two scales. Estimating first (‘less than 90°, so 50°’) catches this error, which is the most common one with protractors.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-660","question":"Children think that rectangles with the same perimeter must have the same area. Which activity best challenges this?","options":["Give them the formulas for area and perimeter to memorise and practise on ten sums","Let them make rectangles from a 12 cm loop of string on squared paper and count the squares","Ask them to find the area of one rectangle in two different ways and compare the two answers","Show them that a square has the largest perimeter for a given area, using examples"],"answer":1,"explanation":"With perimeter 12 cm, a 1 × 5 rectangle encloses 5 squares, 2 × 4 encloses 8 and 3 × 3 encloses 9. Children see the area change while the perimeter stays fixed. Option D is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-661","question":"A child cuts a triangle off one end of a paper rectangle and sticks it on the other end to make a parallelogram, then says the new shape has a bigger area ‘because it is longer and slanting’. What has the child not yet understood?","options":["The formula for finding the area of a parallelogram, which is base times height","How to measure the length of slanting sides with a ruler","That area stays the same when a shape is cut and rearranged without overlap","That a parallelogram is a kind of rectangle with slanting sides"],"answer":2,"explanation":"The pieces are the same, so the area is the same; this is conservation of area. Judging area by length or appearance is the misconception, and it is the idea behind deriving the parallelogram formula.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-662","question":"Measuring a table with her hand span, a child leaves gaps between spans in some places and overlaps them in others. Which measurement principle is she missing?","options":["That the unit must be a standard unit such as a centimetre or a metre","That the measure must start from zero","That longer units give smaller numbers","That equal units must be laid end to end with no gaps or overlaps"],"answer":3,"explanation":"Unit iteration means repeating the same unit without gaps or overlaps; without it the count does not represent length. This is basic to all measurement, whatever unit is used.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-663","question":"Ravi measures a bench as 8 hand spans and Meena measures the same bench as 12 hand spans. Asked whose hand is bigger, a child says ‘Meena's, because she got the bigger number.’ The child has not understood that:","options":["the bigger the unit, the fewer of them are needed for the same length","hand spans are not reliable units, so the comparison is meaningless","both children must have measured carelessly, since the bench is the same","the same bench can have only one correct measurement"],"answer":0,"explanation":"Unit size and the count are inversely related: Ravi needed fewer spans, so his span is longer. This relationship is an important outcome of measuring with non-standard units.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-664","question":"A Class 7 student writes 1 m² = 100 cm². Which response best helps her see why this is wrong?","options":["Tell her the rule ‘multiply by 100 twice when changing square units’ and set some practice sums","Ask her to picture a 1 m square as 100 cm by 100 cm and count how many 1 cm squares fill it","Remind her that 1 m = 100 cm and ask her to write the conversion again carefully","Ask her to convert 1 m³ into cm³ as well, so that she sees the pattern"],"answer":1,"explanation":"A 1 m square is 100 cm on each side, so it holds 100 × 100 = 10,000 squares of 1 cm². She applied the length conversion to area. Picturing the square builds the reason, not just a new rule.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-665","question":"A Class 6 student is shown a drawing of a cuboid made of unit cubes, 2 cubes high, 3 wide and 4 long. She counts the cubes she can see on the three visible faces and says the volume is 18 cubes. What has she missed?","options":["The cubes on the edges, which she has counted twice on two faces","That volume is measured in square units, not by counting cubes","The hidden cubes; counting layer by layer (2 layers of 12) gives 24","That the length should be multiplied by the height only, which gives 8"],"answer":2,"explanation":"Counting visible faces leaves out the 6 hidden cubes (a 1 × 2 × 3 block), so she gets 18 instead of 24. Building the cuboid and counting it in layers gives meaning to length × breadth × height.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-666","question":"A Class 6 child believes any six squares joined edge to edge will fold into a cube. What is the best way to deal with this?","options":["Give her the list of all 11 cube nets to learn by heart and then draw them from memory in her notebook","Tell her that only the cross-shaped net can fold into a cube, and ask her to draw it neatly","Show a video of a cube being unfolded into a net, and then move on","Have her predict which six-square shapes will fold into a cube, then cut and fold them to check"],"answer":3,"explanation":"Predicting and then testing builds spatial visualisation and lets her see that some six-square shapes (such as six in a row) do not close. The cross is only one of 11 nets, so option B is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-667","question":"A Class 5 child marks four lines of symmetry on a rectangle that is not a square: two through the midpoints of the sides and the two diagonals. Which response is best?","options":["Let her fold a paper rectangle along a diagonal and see whether the two halves match","Accept it, since every rectangle has four lines of symmetry, just as a square has","Tell her that only squares have diagonals","Ask her to count the corners, since the number of lines of symmetry equals the number of corners"],"answer":0,"explanation":"Folding along a diagonal shows the halves do not fit on each other, so a non-square rectangle has only two lines of symmetry. Diagonals split it into two congruent triangles, but that is not reflection symmetry.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-668","question":"A child says the letter N ‘has no symmetry at all’ because no fold line works. What is the best response?","options":["Agree, because N has no line of symmetry and so it cannot have any symmetry","Ask her to trace N, turn the tracing half a turn about its centre, and see if it fits","Tell her that every capital letter of the alphabet has at least one line of symmetry somewhere","Ask her to fold N along its slanting stroke and check the two halves again"],"answer":1,"explanation":"N has no line of symmetry, but it fits on itself after a half turn, so it has rotational symmetry of order 2. The child has taken ‘symmetry’ to mean only line symmetry.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-669","question":"To build spatial thinking in Class 5, which activity is most suitable?","options":["Copying the names and pictures of 3-D shapes from the board neatly into their notebooks","Learning the number of faces, edges and corners of each solid by heart for a weekly class quiz","Building block models, drawing their top, front and side views, and having a partner rebuild them","Colouring pictures of cubes, cones and cylinders in the textbook"],"answer":2,"explanation":"Moving between a solid and its views, in both directions, develops spatial visualisation, which NCERT's primary maths books emphasise. Memorising counts of faces does not.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-670","question":"A teacher asks, ‘On this dot grid, make as many different triangles as you can that each have an area of 2 square units.’ What kind of task is this, and what is its main value?","options":["A closed drill that builds speed and accuracy in finding the areas of triangles","A memory task that checks whether children recall the area formula for triangles","A test item meant only for the fastest learners, to keep them busy while the others catch up","An open-ended task with many answers, inviting exploration and reasoning at different levels"],"answer":3,"explanation":"With many correct solutions, every child can enter at her own level, and comparing triangles leads naturally to the idea that the same base and height give the same area.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-671","question":"Children use the seven tangram pieces and find that each large triangle covers exactly a quarter of the full square. Which mathematical process is the activity mainly developing?","options":["Connecting geometry and fractions through visualisation","Memorising the names and shapes of the seven tangram pieces","Practising measurement of the pieces with standard units such as cm","Learning the formula for the area of a triangle and applying it"],"answer":0,"explanation":"Comparing the pieces to the whole links shape with fraction (a quarter) and with area, the kind of connection NCF 2005 lists among the processes of mathematics.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-672","question":"Assertion (A): Children should sort and handle many real objects and shapes before they are given definitions of shapes. Reason (R): At the visual level, children recognise shapes by their appearance and need varied experiences to begin noticing properties.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Van Hiele's model says that properties grow out of varied experience with shapes; definitions given too early are only memorised. R gives the reason for A.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-673","question":"Class 7 students measure the angles of three triangles and get totals of 179°, 181° and 180°. One says, ‘So the angle sum is only about 180°.’ What should the teacher do?","options":["Tell them to measure more carefully, again and again, until they all get exactly 180°","Discuss measurement error, then show the sum is exactly 180° by tearing off the corners and later by proof","Accept ‘about 180°’ as the right answer at this stage, since measurement is never exact","Tell them the angle sum differs slightly for different kinds of triangles, such as obtuse or right ones"],"answer":1,"explanation":"Measurement suggests a result but cannot prove it. Moving from measuring to a general argument, first by arranging the torn corners and then by a proof, shows the difference between checking examples and proving.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-674","question":"A Class 4 child finds the perimeter of a rectangle 8 cm long and 5 cm wide as 8 + 5 = 13 cm. What is the most suitable next step?","options":["Give her the formula 2 × (l + b) to memorise and practise on similar sums","Tell her that she has found the area instead of the perimeter of the rectangle","Ask her to trace the whole edge with a finger or string and say which sides she added","Ask her to measure the rectangle again carefully with a ruler and then add the two numbers once more"],"answer":2,"explanation":"She added only the two labelled sides. Tracing the whole boundary shows that perimeter is the full distance around, 8 + 5 + 8 + 5 = 26 cm, and gives the formula its meaning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-675","question":"A Class 8 student preparing for a debate on banning single-use plastic is handed a six-page magazine feature. Which sequence of reading strategies would be most efficient for her purpose?","options":["Scan each line for the word ‘plastic’ and copy out every sentence in which it appears","Read every page carefully from the beginning so that no point is missed, and then make notes","Skim to find relevant sections, scan them for figures, then read the useful parts closely","Read only the final paragraph, since articles always put their main argument at the end"],"answer":2,"explanation":"Skilled readers match strategy to purpose: skimming locates what is relevant, scanning picks out data, and intensive reading is kept for the parts that matter. Reading everything closely wastes time.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-676","question":"Consider these statements: I. Skimming is used to get the gist, often by reading headings and the first sentences of paragraphs. II. Scanning requires reading every word of the text carefully. III. In both skimming and scanning, the reader deliberately ignores much of the text according to her purpose. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Scanning is a rapid search for a specific item, such as a date or name, so it does not involve reading every word. Both skimming and scanning are selective, purpose-driven reading.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-677","question":"Class 6 children in a coastal Kerala village easily follow an English story about fishing boats in the monsoon, but children in a desert school in Rajasthan, who decode just as well, struggle with the same story. The most likely explanation is:","options":["The Rajasthan children have weaker phonics skills and need more decoding practice","The grammar of the story is beyond the level that the Rajasthan children have reached","The Kerala children are simply more intelligent readers than the others","The two groups differ in the background knowledge (schema) they bring to the text"],"answer":3,"explanation":"Schema theory holds that readers build meaning by linking text to what they already know. Since decoding is equal, the difference lies in prior knowledge, which a teacher can build through pictures, videos and talk before reading.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-678","question":"A Class 3 child reads ‘The horse jumped over the fence’ as ‘The house jumped over the fence’ and carries on without pausing. The most useful teacher prompt is:","options":["‘Sound out every letter of each word again from the start.’","‘Look only at the picture and guess the word from it.’","‘Does that make sense? Read the sentence again and check.’","‘Skip any word you are not sure of and keep reading.’"],"answer":2,"explanation":"The miscue matches the letters but not the meaning, showing reliance on visual cues without monitoring sense. Prompting the child to cross-check with meaning builds self-monitoring, which further sounding out would not.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-679","question":"In groups of four, Class 6 students read a text section by section. One student predicts what comes next, another asks questions, a third clears up confusing words or ideas, and a fourth summarises; the roles rotate and the teacher gradually withdraws her support. This technique is:","options":["SQ3R","Jigsaw reading","Directed Reading-Thinking Activity","Reciprocal teaching"],"answer":3,"explanation":"Palincsar and Brown’s reciprocal teaching trains four strategies, predicting, questioning, clarifying and summarising, through dialogue in which students gradually take over the teacher’s role.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-680","question":"Preparing a history chapter, a Class 9 student first glances over the headings and pictures, turns each heading into a question, reads to answer it, and then closes the book and answers her questions aloud from memory. In SQ3R, this last step is:","options":["Survey","Recite","Review","Question"],"answer":1,"explanation":"SQ3R runs Survey, Question, Read, Recite, Review. Answering the questions from memory after reading a section is Recite; Review is the later revision of the whole chapter.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-681","question":"A teacher reads a story in parts. At each pause she asks, ‘What do you think will happen next, and why?’, students read on to check, and then say which clues in the text confirmed or changed their predictions. This procedure is known as:","options":["Round-robin reading","Language experience approach","Directed Reading-Thinking Activity","Shared reading"],"answer":2,"explanation":"Stauffer’s DRTA cycles through predict, read, and prove with evidence from the text, making reading an active process of hypothesis and confirmation.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-682","question":"Passage: ‘Raju looked at the dark clouds, picked up his umbrella and hurried out.’ Which question is inferential?","options":["‘What did Raju pick up before he left?’","‘Why did Raju take his umbrella with him?’","‘Was Raju right to hurry out in such weather?’","‘What were the clouds like when Raju looked?’"],"answer":1,"explanation":"The text never says it was about to rain; the reader must infer it from the dark clouds. The question about whether he was right asks for a judgement, which makes it evaluative, not inferential.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-683","question":"After reading a newspaper report on a new dam, a Class 8 teacher wants to develop critical literacy. Which question best serves this aim?","options":["‘In which district is the dam being built, and by whom?’","‘How many villages will get water from the new dam each year?’","‘What is the meaning of the word “reservoir” in the report?’","‘Whose views are missing from this report, and why?’"],"answer":3,"explanation":"Critical literacy asks readers to examine whose perspective a text presents or leaves out and why. The other questions check literal information or vocabulary.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-684","question":"For which purpose is intensive reading most appropriate?","options":["Studying the steps of a science experiment to carry it out exactly","Choosing a library novel by flipping quickly through a few of its pages","Reading comics on a holiday afternoon purely for fun","Finding a relative’s number in a telephone directory"],"answer":0,"explanation":"Intensive reading means careful, detailed reading for full understanding, needed when every step matters. The other purposes call for scanning, skimming and extensive reading respectively.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-685","question":"In a Class 6 English class, children take turns reading the lesson aloud one paragraph each while the rest follow along, and this is the main reading activity every day. What is the main problem with this practice?","options":["It is a problem only because silent reading should not start before Class 8","It is the only reliable way for the teacher to check whether children have understood the text","Its only drawback is that the weaker readers take too much of the class’s time","It stresses performance over comprehension, and the listeners often lose the meaning"],"answer":3,"explanation":"Round-robin reading makes children anxious about pronunciation, engages one reader at a time, and does not show comprehension. Silent reading with a purpose is better suited to understanding at this stage.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-686","question":"Which of these tasks demands the most advanced level of phonological awareness in a Class 1 child?","options":["Saying whether ‘cat’ and ‘hat’ rhyme","Clapping the number of syllables in ‘banana’","Saying ‘stop’ without the /s/ sound","Telling the first sound in ‘mango’"],"answer":2,"explanation":"Deleting a phoneme and blending the rest (‘top’) is phoneme manipulation, the most demanding level. Rhyme, syllables and initial sounds are earlier skills.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-687","question":"A Class 1 teacher first teaches the sounds /s/, /a/, /t/, /p/ and then has children blend them to read ‘sat’, ‘pat’ and ‘tap’. This approach is:","options":["Synthetic phonics, which builds words by blending individual sounds","Analytic phonics, which begins with whole words and studies their parts","The look-and-say method, which teaches whole words by their shape","The whole language approach, which teaches sounds only inside stories"],"answer":0,"explanation":"Synthetic phonics teaches letter–sound links first and then blends (synthesises) them into words. Analytic phonics starts from known words and analyses their shared sounds.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-688","question":"High-frequency words such as ‘the’, ‘was’, ‘said’ and ‘one’ are hard for Class 1 children to sound out. They are best taught:","options":["By asking children to sound them out letter by letter like all other words","As sight words, through repeated meeting in texts, games and word walls","By delaying them until children have learnt all the letter sounds","By having children copy each word twenty times in a notebook"],"answer":1,"explanation":"Irregular high-frequency words do not follow simple sound rules, so children learn to recognise them instantly through frequent meaningful exposure; they are too common to postpone.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-689","question":"While teaching a passage on the causes and effects of floods in Assam, a Class 7 teacher asks students to fill in a chart with ‘Cause’ and ‘Effect’ boxes linked by arrows. The main purpose is to help students:","options":["Copy the passage in a shorter and neater form for revision later","See the structure of the text, which aids understanding and recall","Memorise the difficult words that appear in the passage on floods","Practise drawing neat diagrams for their geography examination answers"],"answer":1,"explanation":"Graphic organisers make a text’s organisation (cause–effect, compare–contrast, sequence) visible, so students see how ideas relate and remember them better.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-690","question":"A teacher divides a text about Pongal into four parts. Each group reads a different part, then members regroup so that each new group has one person from every part, and they must put the whole account together by talking. The main benefit of this jigsaw reading is that it:","options":["Creates an information gap, giving speaking and listening a real purpose","Lets the teacher finish the lesson faster by dividing the reading work","Ensures that every child reads the full text closely and on her own","Reduces the need for any whole-class discussion after the reading is over"],"answer":0,"explanation":"Since each learner holds information the others need, the task creates genuine interdependence and purposeful communication, integrating reading with speaking and listening.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-691","question":"Reading a story aloud, a teacher pauses to say, ‘Hmm, I don’t know this word, so I’ll read on to see if the next sentence helps… The author keeps mentioning the cracked wall; I think it’s a clue.’ The main purpose of this think-aloud is to:","options":["Show children that even teachers make mistakes and get stuck while reading","Fill time so that children can rest between parts of the story","Test whether children are listening carefully to the story","Make visible the mental strategies a skilled reader uses to understand"],"answer":3,"explanation":"Think-alouds model metacognitive comprehension strategies, such as reading on, predicting and noticing clues, which are otherwise invisible to learners.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-692","question":"Which behaviour best shows that a pre-school child has developed ‘concepts about print’?","options":["She can sing the whole alphabet song from A to Z without a single mistake","She can copy capital letters neatly from the board into her notebook","She knows English print runs left to right and that spaces separate words","She can name ten colours and match each colour to a picture"],"answer":2,"explanation":"Concepts about print include directionality, the idea that print carries meaning, and what words and letters are. Reciting the alphabet or copying letters can happen without this understanding.","difficulty":"moderate","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-693","question":"All the questions a Class 5 teacher sets on a passage can be answered by copying one sentence from the text. Using the Question–Answer Relationship (QAR) framework, which kind of question should she add to deepen comprehension?","options":["‘Think and search’ and ‘On my own’ questions that link ideas and prior knowledge","More ‘Right there’ questions, but taken from less obvious parts of the text","Only multiple-choice questions, so that the answers are quicker and easier to mark","Questions that ask for the meanings of difficult words listed in the glossary"],"answer":0,"explanation":"Raphael’s QAR separates ‘Right there’ answers from those that require putting ideas together across the text or combining it with the reader’s own knowledge, which build deeper comprehension.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-694","question":"A lesson in a Class 6 reader has 25 new words. Before reading, the teacher writes all 25 on the board with their meanings and has students copy them. A better plan would be to:","options":["Avoid all vocabulary work, since students should never be made to meet any unknown words","Continue with all 25 words, but also give their Hindi meanings for greater clarity","Pre-teach only the few words needed for the gist; let others be worked out from context","Make students learn all 25 meanings by heart and test them before reading begins"],"answer":2,"explanation":"Pre-teaching a long list overloads memory and takes away the chance to infer meaning. Pre-teaching only key words supports the gist and leaves room for building word-learning strategies.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-695","question":"Assertion (A): A reader with rich knowledge of a topic can often understand a text about it even when she does not know some of the words. Reason (R): In top-down processing, readers use prior knowledge and expectations to construct meaning from a text.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Top-down processing lets background knowledge fill gaps and guide interpretation, which is exactly why a well-informed reader can cope with some unknown words.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-696","question":"Match each comprehension question with the reading sub-skill it mainly tests: 1. ‘Choose the most suitable title for the passage.’ 2. ‘Find a word in paragraph 3 that means “tired”.’ 3. ‘What does “it” in line 5 refer to?’ 4. ‘Why does the writer mention her grandmother?’; a. Understanding reference (cohesion) b. Vocabulary in context c. Getting the gist d. Inferring the writer’s purpose","options":["1-c, 2-b, 3-a, 4-d","1-c, 2-a, 3-b, 4-d","1-d, 2-b, 3-a, 4-c","1-b, 2-c, 3-a, 4-d"],"answer":0,"explanation":"A title tests the gist, a synonym hunt tests vocabulary in context, a pronoun’s referent tests cohesion, and ‘why does the writer…’ requires inferring purpose.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-697","question":"For small-group guided reading sessions, in which the teacher supports children as they read, the texts chosen should be at the children’s:","options":["Independent level, which they can read easily with no help at all","Instructional level, challenging but manageable with some support","Frustration level, so that the teacher has plenty to correct","Grade level, whatever their actual reading ability may be"],"answer":1,"explanation":"Guided reading uses instructional-level texts, which stretch readers but remain understandable with teacher support. Independent-level texts suit free reading; frustration-level texts break down comprehension.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-698","question":"A Class 7 teacher asks students to write a single-sentence summary of each paragraph of a long passage. This mainly develops the ability to:","options":["Copy sentences quickly and accurately from a printed text into notes","Learn the spelling of the difficult words that are used in each paragraph","Count how many sentences a well-built paragraph should contain","Separate the main idea of each paragraph from its supporting details"],"answer":3,"explanation":"Summarising forces readers to decide what is central and what is detail, a core comprehension skill that also helps them follow the overall structure of a text.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-699","question":"A Class 4 child often reads by guessing from the pictures and the first letter: for ‘The dog is bad’ she reads ‘The dog is big’, and for ‘pony’ she reads ‘pond’. The most suitable support is to:","options":["Remove all pictures from her books so that she cannot guess any more","Strengthen her letter–sound decoding while keeping attention on meaning","Ask her to read faster, so that guessing gives way naturally to fluent reading","Accept these miscues, since guessing is always a sign of a good reader"],"answer":1,"explanation":"Over-reliance on top-down guessing without full decoding produces meaning-changing errors. Building decoding while asking ‘Does it look right and make sense?’ develops balanced, interactive reading.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-700","question":"A Class X class in Delhi wants to discuss whether reservation in jobs should continue in its present form, and feelings run high. Which approach should the teacher take?","options":["Refuse the discussion, since the topic is political and too divisive for a classroom","State her own view clearly at the start, so that the students learn the one correct position on it","Let students argue freely without any rules or structure, so that no one feels restricted","Hold a structured discussion with ground rules, present positions with evidence, and not impose her view"],"answer":3,"explanation":"Controversial issues are part of social science learning, but they need structure: ground rules, balanced evidence and the constitutional framework. Avoiding the issue, imposing a view or allowing an unruly free-for-all each defeats critical thinking.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-701","question":"During a discussion on caste, a Class IX student uses a slur and says people of a certain caste 'deserve' to do cleaning work. What should the teacher do?","options":["Stay neutral, since every opinion in a class discussion is equally valid and must be respected","Firmly point out that the remark denies equal dignity, then help the class examine its roots","Send the student out of class at once and carry on with the chapter without comment","Ignore the remark, so that the discussion does not become tense or divided"],"answer":1,"explanation":"Openness to different views does not extend to views that deny others' dignity; equality and dignity are constitutional values the classroom must uphold. Examining the prejudice teaches far more than silence or expulsion.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-702","question":"Which of the following statements about handling controversial issues in social science are correct?\n1. Ground rules for respectful talk should be agreed before the discussion.\n2. Students should be helped to separate facts, opinions and values.\n3. The teacher must make sure that every student reaches the same conclusion by the end.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Ground rules make the space safe, and separating facts from opinions and values sharpens reasoning. Forcing a common conclusion turns discussion into indoctrination, which is why statement 3 is wrong.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-703","question":"A Class VII student's essay on the Constitution contains these sentences. Which one is an opinion presented as though it were a fact?","options":["The Constitution of India came into force on 26 January 1950.","The Constitution of India is the best constitution in the world.","The Constitution provides for elections to Parliament.","The Constitution has been amended several times since it came into force."],"answer":1,"explanation":"'Best in the world' is a value judgement that cannot be checked like a date or a provision, even if many people hold it. Telling such claims apart from facts is a basic critical-thinking skill.","difficulty":"moderate","source":"CTET Paper 2 · NVS · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-704","question":"Which question on Panchayati Raj is most likely to develop critical thinking in Class VIII?","options":["How many seats in panchayats are reserved for women under the 73rd Constitutional Amendment Act?","Who heads the gram panchayat, and for how many years is she elected?","Why might a woman sarpanch's husband attend meetings in her place, and what could change this?","Name the three tiers of Panchayati Raj and the body at each level."],"answer":2,"explanation":"The third question asks students to explain a gap between the law and practice and to suggest remedies, which calls for analysis and evaluation. The others ask for facts given in the textbook.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-705","question":"A Class VII teacher asks, 'Should our town allow a shopping mall to replace the weekly market? Give reasons for your answer.' In Bloom's revised taxonomy, this question is mainly at which level?","options":["Remembering","Understanding","Applying","Evaluating"],"answer":3,"explanation":"The question asks students to judge between alternatives and justify their stand, which is evaluation. It cannot be answered by recalling or explaining information alone.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-706","question":"Assertion (A): A social science teacher should not use the classroom to promote any particular political party.\nReason (R): Social science should avoid discussing current political issues altogether.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Partisan teaching violates the student's right to reach independent views, so A is true. But current political issues are legitimate and valuable content when handled fairly, so R is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-707","question":"Assertion (A): Avoiding every controversial issue does not make a social science classroom neutral.\nReason (R): Silence on social issues leaves prejudices unexamined and quietly accepts the way things are.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Choosing not to discuss inequality or conflict is itself a choice with consequences: existing prejudices go unchallenged. That is exactly why avoidance is not neutral, so R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-708","question":"Class XII history students in an Amritsar school are studying Partition. Several students' grandparents lived through it. Which approach is the most appropriate?","options":["Use only official statistics and records, so that emotions do not enter the lesson at all","Present the account of one community, since it is closest to the students' own families","Use personal accounts from different sides, focus on human experience, and avoid blaming communities today","Skip Partition, since it is too painful a topic for students with family connections to it"],"answer":2,"explanation":"Testimonies from several sides build empathy and an understanding of Partition's human cost, while avoiding blame on today's communities prevents old wounds from becoming new prejudice. One-sided accounts or omission both fail the learners.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-709","question":"A Class VIII teacher asks students to write a diary entry as a Bengal indigo cultivator of the 1850s, using details from the sources they have studied. Which aim does this activity serve best?","options":["Historical empathy: understanding past people in their own context, based on evidence","Creative writing practice, without any need for the details to be historically accurate","Judging the cultivators of the 1850s by today's values and standards","Memorising the chronology and main leaders of the Indigo Revolt"],"answer":0,"explanation":"Historical empathy means reconstructing how people saw their world, anchored in sources. It is neither free fiction nor 'presentism', which judges the past only by present standards.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-710","question":"A Class VI student remarks that people in the 16th century 'were foolish because they did not use electricity'. What thinking skill should the teacher help the student develop?","options":["Memorising the date on which electricity was discovered and by whom","Understanding people of the past in their own context, not by present-day knowledge","Accepting that people in the past were less intelligent than people today","Comparing the prices of everyday goods in the past and present to see how life has changed"],"answer":1,"explanation":"The remark judges the past by present standards, an error called presentism. Seeing what people knew and could do in their own time is the basis of historical understanding.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-711","question":"A textbook picture shows an Adivasi man only in traditional dress at a festival dance. A student in a Bhubaneswar school asks, 'Do Adivasis go to college?' What should the teacher do?","options":["Say that Adivasis mostly prefer to stay in forest villages and so do not need to go to college","Move on, since the question is not in the syllabus and may distract the class","Correct the student for asking a rude question about a community in class","Discuss how one image can create a stereotype, and show the varied lives of Adivasis today"],"answer":3,"explanation":"The question reveals a stereotype built from limited images. Showing diverse, contemporary Adivasi lives challenges it, which is part of NCF 2005's concern with representing marginalised groups fairly.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-712","question":"A student brings a viral WhatsApp message making dramatic claims about a historical figure. What is the most suitable classroom response?","options":["Ban mobile phones in school so that such messages never reach the classroom","Accept the claims, since the message has been forwarded by so many people","Have students check its author, sources and dates against reliable accounts","Tell students the message is false and move on to the lesson"],"answer":2,"explanation":"Teaching students to verify claims builds a lasting critical skill. Simply declaring the message false still asks students to rely on authority, and popularity is no evidence of truth.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-713","question":"Which teacher behaviour most fosters critical thinking during a social science discussion?","options":["Giving the correct answer right after asking a question, to save time for covering more content","Pausing after questions and probing with ‘Why do you think so?’ and ‘What is your evidence?’","Praising only the answers that match the textbook, so students learn what is correct","Calling only on students who have raised their hands quickly, to keep up the pace"],"answer":1,"explanation":"Wait time gives students room to think, and probing for reasons and evidence pushes them beyond first answers. Quick answers, textbook-matching praise and favouring fast responders all reward recall over reasoning.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-714","question":"For a Class X lesson on large dams, a teacher gives groups role cards: a family displaced by the reservoir, a farmer in the irrigated area downstream, a city water board official and an environmental scientist. What is the main learning goal?","options":["To decide which group is right, so that the debate can end with a clear winner","To show that development projects such as large dams bring no real benefits to anyone at all","To memorise the heights and locations of India's major dams","To see that a development project affects groups differently and involves trade-offs"],"answer":3,"explanation":"Stakeholder role cards reveal who gains, who loses and what is traded off, which is central to thinking critically about development. The aim is not to declare a winner or to reject development outright.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-715","question":"After a structured discussion on whether exams should be replaced by projects, students ask the Class IX teacher for her own opinion. Which response is most appropriate?","options":["Share her view as one perspective, with reasons, making clear that students may disagree","Refuse ever to share any opinion on any issue, so that she stays neutral","Share her view and tell students to write it in their notebooks as the correct answer for exams","Pretend to agree with whatever the majority of the class thinks, to keep the peace"],"answer":0,"explanation":"After students have reasoned for themselves, a teacher may offer a view if it is clearly one perspective open to challenge. Imposing it, or hiding behind false agreement, undermines honest inquiry.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-716","question":"A teacher drafts ground rules for discussing sensitive topics in Class VIII. Which proposed rule should she NOT adopt?","options":["Criticise ideas, not the people who hold them","Anyone may say 'pass' when asked about a personal experience","Back your claims with reasons or evidence","Every student must state their family's views on each issue"],"answer":3,"explanation":"Forcing students to reveal personal or family positions can expose and hurt them; the right to pass protects them. The other rules keep discussion respectful and reasoned.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-717","question":"After communal violence in their district, Class IX students in a government school start talking about it angrily in class. What is the most appropriate response for the social science teacher?","options":["Gently return to the syllabus and suggest that students talk it over calmly with their families","Acknowledge feelings, keep to verified facts and constitutional values, blame no community","Hold a class debate on which side was more at fault, so that every view gets a hearing","Ask the school counsellor to handle the matter so that the lesson is not disturbed"],"answer":1,"explanation":"A safe, fact-based discussion anchored in constitutional values helps students process real events without deepening divisions. A debate on which side was at fault seems fair but invites blaming communities, while redirecting or handing over to the counsellor leaves rumours unaddressed in the classroom.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-718","question":"A Class VIII teacher, while teaching about caste discrimination, also covers the work of Jotirao Phule, Savitribai Phule and B. R. Ambedkar and the movements against untouchability. Why is this important?","options":["It shows that marginalised groups were not only victims but also resisted and worked for change","It proves that caste discrimination ended completely once these reform movements had finally succeeded","It lets the teacher skip the uncomfortable discussion of discrimination itself","It is required only because these names appear often in examination questions"],"answer":0,"explanation":"Presenting resistance and reform restores agency to marginalised people and shows how social change happens. Claiming that discrimination simply ended would be historically untrue.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-719","question":"A Class IX teacher shows a political cartoon on the Emergency and asks students to identify its symbols, its message and whose viewpoint it represents. Which skill is mainly being developed?","options":["Drawing skills for making cartoons","Memorising the dates and events of the Emergency","Critical reading of a visual text and its perspective","Appreciation of humour and satire purely for its own sake"],"answer":2,"explanation":"Cartoons are compressed arguments. Decoding symbols, message and viewpoint is critical visual reading, a skill that transfers to all media.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-720","question":"In a Class VII discussion on banning plastic bags in the market, one student argues, 'Shopkeepers will lose customers.' The teacher asks, 'What are you assuming about customers?' The teacher is mainly helping students to:","options":["Memorise the arguments for and against the ban","Avoid taking any position on the issue","Identify the hidden assumptions in an argument","Agree with the shopkeepers' point of view"],"answer":2,"explanation":"The argument assumes customers will go elsewhere rather than carry their own bags. Bringing such assumptions to the surface is a key critical-thinking skill.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-721","question":"Which of the following statements describe a critical pedagogy approach in social science?\n1. Students are encouraged to question the textbook as well.\n2. Learning is related to the social context of the children.\n3. The teacher's word is the final authority on every interpretation.","options":["1 and 3 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Critical pedagogy invites questioning of all texts and roots learning in students' social reality. Treating the teacher as the final authority is the 'banking' model it rejects.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-722","question":"Which question would best develop critical thinking in a Class VI lesson on diversity?","options":["Why do people sometimes form wrong ideas about speakers of other languages, and how can these change?","Name the folk dances of any four states of India and the occasions for each.","How many languages are spoken in India, and which are listed in the Constitution?","Which festival is celebrated in Punjab in April, and what crop does it mark?"],"answer":0,"explanation":"Exploring how prejudice forms and changes requires reasoning about causes and solutions. The other questions ask for facts about diversity rather than thinking about it.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-723","question":"A Class X student studying district data notices that districts with more roads have higher average incomes and concludes, 'Building roads makes people richer.' What should the teacher help the student consider?","options":["That the conclusion is fully proven, because the data come from an official government source","That correlation alone does not prove cause; richer districts may build more roads instead","That roads have no connection with incomes at all, so the data must be wrong","That data should never be used in social science, since numbers can mislead"],"answer":1,"explanation":"A relationship in data can run in either direction or come from a third factor, such as industry or nearness to cities. Spotting this is high-level critical thinking. Denying any link is also an overreach.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-724","question":"A teacher wants to help Class VIII students judge competing claims about why a river in their state is polluted. Which activity is most effective?","options":["A field visit to the river to record its colour, smell and visible waste in a diary","A class debate in which each team argues the side assigned to it by the teacher","Testing river water with a simple kit and graphing the pH readings over a week","Groups compare claims and evidence from the factory, farmers, board and residents"],"answer":3,"explanation":"Judging competing claims needs students to set each party's claim against evidence. A debate is tempting but rewards persuading for an assigned side rather than weighing evidence, and the field visit and water test show that the river is polluted, not who is responsible.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-725","question":"At the end of the ‘Water’ unit, a Class 5 teacher gives children the words rain, well, river, drinking, farming and scarcity, and asks each child to arrange them as a concept map with linking words on the lines. The main value of this as an assessment is that it:","options":["checks whether children can spell all the key words of the unit correctly","shows how each child links the ideas, including missing or wrong links","produces a neat and colourful chart for the classroom wall","replaces the need for any other assessment for the rest of the unit"],"answer":1,"explanation":"A concept map makes the learner’s web of relationships visible, so gaps and wrong links show up. Spelling and display are incidental, and no single tool should replace all others.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-726","question":"In a concept map, the basic unit of meaning, such as ‘Plants → give → oxygen’, is formed by:","options":["a single concept written inside a box or circle","a branch drawn from a central word without any label on it","a line that joins two different maps on one page","two concepts joined by a line with a linking word"],"answer":3,"explanation":"Two concepts plus a labelled link make a proposition, which is what distinguishes a concept map from an unlabelled web. A single box carries no relationship.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-727","question":"Consider these statements about concept maps: I. Lines between concepts carry linking words that state the relationship. II. Joseph Novak developed them, drawing on Ausubel’s theory of meaningful learning. III. They should always be drawn by the teacher and only copied by children. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":0,"explanation":"Novak built concept mapping on Ausubel’s idea that new knowledge must be linked to existing knowledge. Children making their own maps is the point, so III is wrong.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-728","question":"In a Class 4 child’s concept map on water, the only source shown is ‘Water → comes from → tap’, with nothing beyond the tap. The teacher should best treat this as a sign that:","options":["the child is careless and should redo the map neatly, adding many more words to it","the child has fully understood the sources of water, since taps supply most homes","the child's idea of water's source stops at the tap, so tracing tap water back is needed","concept maps are unsuitable for Class 4 children and should be dropped"],"answer":2,"explanation":"The map shows where the child’s understanding ends. A follow-up (tracing pipes to a tank, well or river) can extend it; the map has done its diagnostic job.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-729","question":"In a concept map on ‘Food’, a Class 5 child draws a line from ‘Farmer’, under the branch ‘Where food comes from’, to ‘Hunger’, under the branch ‘Who does not get enough food’, labelled ‘sometimes also faces’. Such a cross-link mainly shows:","options":["the ability to connect ideas across branches, a sign of deeper, integrated understanding","confusion, since each branch of a concept map should always stay separate from the others","a drawing mistake that the teacher should erase so the map looks tidy","memorisation of a textbook sentence about farmers and food"],"answer":0,"explanation":"Novak treated meaningful cross-links between branches as evidence of integrative, creative thinking. Here the child sees the irony that food producers may go hungry.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-730","question":"Before beginning the theme ‘Shelter’, a teacher draws a web around the word with branches such as materials, climate, people who build, animal homes and people without homes. The main purpose of this web is to:","options":["give children a ready-made summary of the whole theme to memorise for the test","decide which pages of the textbook can safely be skipped this term","test whether children already know the meanings of these words","plan links and activities across the natural and social sides of the theme"],"answer":3,"explanation":"A thematic web is a planning tool for the teacher to see how a theme branches into science, social and ethical questions and to design activities that link them.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-731","question":"A Class 3 teacher wants children who cannot yet write fluently to make concept maps. The best adaptation is to:","options":["leave concept maps aside until the children can write full sentences fluently on their own","let children arrange picture cards and say the links aloud while the teacher writes them","give them a completed map drawn by the teacher to colour in","let only the good writers make maps while the others watch and learn"],"answer":1,"explanation":"The thinking in a concept map is about relationships, not writing. Pictures and spoken links keep the thinking while removing the writing barrier, and every child takes part.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-732","question":"Which activity best uses the school’s surroundings for learning about plants in Class 3?","options":["Copying the names of ten common trees from the textbook into notebooks","Showing photographs of famous trees from other countries on a screen","Each group ‘adopting’ a tree in the compound and recording its changes through the year","Learning the parts of a plant from a labelled chart and drawing them"],"answer":2,"explanation":"Sustained observation of a real tree across seasons builds observation, recording and questioning, all rooted in the local environment. The others are second-hand.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-733","question":"Class 4 children visit the weekly haat and note where each vegetable comes from and how its price changes from season to season. The main EVS learning here is the link between:","options":["food, farmers, transport and the seasons","shopping and good manners in the market","prices and profit making in a business","vegetables and their scientific names in Latin"],"answer":0,"explanation":"Tracing vegetables from field to haat and across seasons connects the ‘Food’ theme to work, travel and climate. It is not about trade profits or naming.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-734","question":"Class 5 children ask their grandparents how water was collected and stored in the village in the past, such as in johads and kunds. Which of these is NOT a benefit of this activity?","options":["It shows children how life and resources have changed over time","It values the knowledge of elders in the community","It connects traditional practices with present water problems","It makes the EVS textbook unnecessary for the rest of the year"],"answer":3,"explanation":"Elders’ knowledge enriches the textbook but does not replace it. Change over time, respect for community knowledge and links to present issues are real benefits.","difficulty":"hard","source":"CTET Paper 1 · REET Level 1"},
  {"id":"cdp-pedagogy-subjects-735","question":"Assertion (A): Drawing on the local environment in EVS helps children who have little exposure to books take part meaningfully. Reason (R): Children from every background come to school with rich knowledge of their own surroundings. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because every child knows her surroundings, starting from them gives first-generation learners a voice that a book-centred class may deny them. R explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-736","question":"A teacher in a chawl-area school in Mumbai says, ‘There is no environment here to study, only buildings and traffic.’ The best response to this view is that:","options":["she is right, so EVS should be taught mainly through videos of forests, rivers and wildlife","the environment includes built and social surroundings: trains, markets, water supply and work","she should take the children to a national park or a forest every month instead","EVS in cities should be limited to the textbook, since there is no real environment outside to study"],"answer":1,"explanation":"EVS treats the environment as natural, social and cultural. A city neighbourhood is full of material for every theme; ‘environment equals forests’ is a narrow misconception.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-737","question":"A teacher in Tamil Nadu uses Pongal to discuss the harvest, the crops grown locally and the season in which they are reaped. This practice is best described as:","options":["mixing religion into a secular subject, which should be avoided in school","a celebration activity with no real link to EVS learning","linking cultural practice with the natural cycles of crops and seasons","teaching the history of festivals so that it can be tested in examinations"],"answer":2,"explanation":"Harvest festivals mark agricultural and seasonal cycles; using them connects culture with nature in a way children already know. Exploring a festival’s link with farming is not religious instruction.","difficulty":"hard","source":"CTET Paper 1 · TNTET"},
  {"id":"cdp-pedagogy-subjects-738","question":"Class 5 children make a map of their mohalla, marking the hand pumps, wells and taps and noting which families use each one. Besides map skills such as symbols and direction, this activity helps children to:","options":["memorise the official names of all the local streets, lanes and landmarks by heart","become skilled in land surveying, which may help them get a future job","practise neat colouring within the lines of a drawn map","see how access to water is spread across the area and who must walk farther"],"answer":3,"explanation":"A water-source map turns into a tool for social inquiry about distance, access and fairness, linking spatial skills with the social environment.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-739","question":"On a neighbourhood walk, Class 4 children notice that one hand pump is used ‘only by some families’ and that others are not allowed to use it. The teacher should:","options":["move on quickly, since the matter is too sensitive for children","hold a careful discussion on fairness and everyone’s equal right to water","tell the children that this is a local custom that must be respected by all","ask the children to report the families to the police"],"answer":1,"explanation":"EVS aims at concern for justice and equality, and the Constitution forbids denying public water on the basis of caste. A sensitive discussion builds this concern; silence or approval would endorse discrimination.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-740","question":"Class 5 children prepare a large chart showing, month by month, the local crops sown and harvested, festivals, birds seen and weather. This seasonal calendar mainly helps children to:","options":["integrate observations of the natural and social world over time","memorise the names of the Indian months in order","practise writing information in a table format only","compare their own village with the illustrations given in the textbook"],"answer":0,"explanation":"The calendar brings crops, culture, wildlife and weather together across the year, showing how they depend on one another. That is integration, not rote naming.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-741","question":"Consider these statements about using low-cost local materials such as clay, waste cloth and bamboo in EVS: I. They make learning accessible in schools with few resources. II. They connect learning with local crafts and skills. III. They are inferior to commercial kits and should be used only when kits are not available. Which are correct?","options":["I only","III only","I and II only","I, II and III"],"answer":2,"explanation":"Local materials are valued for their own sake, not as a poor substitute: they are accessible, familiar and linked to local work. III expresses a common but wrong assumption.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-742","question":"A Class 4 teacher in a flood-prone district of Assam is teaching ‘Shelter’. Which question best uses the local environment to develop analysis?","options":["What is a stilt house? Write its definition in your notebook.","Name the kinds of houses found in different states of India and the materials used in each.","Draw a picture of your house and colour it neatly.","Why do many houses in our village stand on stilts, and what might happen if they did not?"],"answer":3,"explanation":"The question asks children to reason about cause and consequence from what they see every day. The others call for a definition, a list or a drawing.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-743","question":"On a nature walk, a Class 2 teacher asks children to describe the sounds and colours they notice and then to make up a short song about them. This is in line with NCF 2005 because in Classes I and II:","options":["EVS is a separate subject that must be assessed through songs and rhymes","children are too young for any form of observation, so songs are used to replace it","EVS concerns are taught through language and activity, not a separate textbook","music is the main subject of the curriculum in the early primary classes"],"answer":2,"explanation":"In Classes I–II, EVS concerns are woven into language and activities. Observing and then expressing in song does exactly this.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-744","question":"Class 4 children interview their parents about the work they do. The most suitable follow-up activity is to:","options":["rank the jobs from most to least respectable, so that children understand society","display all kinds of work and discuss how each is needed, building respect for all labour","praise the children whose parents have office jobs, to motivate the others","ask children what job they will do when they grow up, so that they can be grouped by their choice"],"answer":1,"explanation":"EVS aims at dignity of labour and sensitivity to all workers. Ranking jobs or praising some parents reinforces the very hierarchies EVS seeks to question.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-745","question":"During a lesson on plants, a Class 4 child says her grandmother uses neem leaves to keep insects away from stored grain. The teacher should best:","options":["treat it as local knowledge worth recording, and help children think how it could be checked","dismiss it, since only the knowledge given in the textbook counts as proper scientific knowledge","tell the class to use neem leaves for every problem with insects at home","note it but tell the child not to bring practices from home into the school"],"answer":0,"explanation":"Local knowledge is a resource in EVS, and children can learn to test claims too. Dismissing it alienates the child; uncritical promotion is equally poor.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-746","question":"Instead of giving a talk on saving water, a Class 5 teacher has children check every tap in the school for leaks for a week, measure the water lost in buckets and present their suggestions to the head teacher. This mainly shows:","options":["a punishment activity for children who have wasted water","a mathematics lesson on measurement, unrelated to EVS","a survey whose only aim is to produce a neat chart for the classroom display","learning through action on a real local problem, building responsibility"],"answer":3,"explanation":"Children investigate, measure, analyse and act on their own surroundings, which develops concern and responsibility far better than a lecture.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-747","question":"Which plan makes the best use of a village pond as an EVS resource for Class 4?","options":["One visit to draw the pond, followed by a written test on pond life","Reading about ponds in the textbook and listing the animals that are usually found in them","Visiting the pond across seasons to record water and birds, who uses it, and what pollutes it","Telling children to stay away from the pond because it is unsafe for them"],"answer":2,"explanation":"Repeated seasonal visits link change over time, living things, human use and pollution, connecting several themes through one local resource.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-748","question":"Which statement about using the local environment in EVS is NOT correct?","options":["It helps children build new ideas on what they already know from daily life","Since EVS starts from the local, children need not learn about distant people and places","It allows children to observe, question and investigate things around them directly for themselves","It connects school learning with the life and work of the community"],"answer":1,"explanation":"EVS starts from the local but widens to the distant, so that children can appreciate diversity across India and beyond. Staying only local would keep horizons narrow.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-749","question":"On a walk through the village, Class 4 children sort the houses they see into kachcha, pucca and mixed, and say what each type is made of. In NCERT’s list of EVS learning indicators, this mainly shows:","options":["Experimentation","Concern for justice and equality","Classification","Questioning"],"answer":2,"explanation":"Grouping things by shared features and comparing them is classification. Observation precedes it, but the sorting itself is the classification indicator.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-750","question":"Kabir says that no force acts on a book lying on the table, because it is not moving. Which activity makes the 'hidden' upward force most perceptible to him?","options":["Dropping the book from a height and watching it fall, to show that gravity always pulls on it","Placing the book on a thick sponge on his palm and feeling his hand push up as it squashes","Sliding the book across the table to show the force of friction","Weighing the book on a spring balance to find its weight"],"answer":1,"explanation":"Kabir thinks 'at rest' means 'no forces'. Feeling his own hand push up through a squashed sponge makes the supporting force real, so he can see that gravity is balanced, not absent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-751","question":"Students believe a rolling ball stops because 'its force gets used up'. The teacher has them roll the same ball with the same push on a carpet, a cement floor and a polished stone floor, measuring how far it goes each time. Which conclusion should the discussion lead them to extend from this pattern?","options":["On a perfectly frictionless surface the ball would stop sooner","On any surface the ball stops at the same point, since its force is fixed","On a perfectly frictionless surface the ball would keep moving without slowing","On a smoother surface the ball would gradually speed up on its own as it rolls along"],"answer":2,"explanation":"Less friction gives a longer run, so extrapolating to zero friction suggests that the ball would not slow down at all. Slowing is caused by an opposing force, not by force 'running out', which is Galileo's line of reasoning.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-752","question":"To challenge the belief that 'supplying heat always raises the temperature', a teacher heats crushed ice steadily and has students record its temperature every minute. Which observation directly challenges the belief?","options":["The thermometer stays near 0 °C while the ice melts, even though heat is supplied throughout","The temperature rises steadily from the first minute, showing that heat and temperature always go together","Water droplets collect on the outside of the beaker, showing that heat is passing out through the glass","The ice at the bottom melts faster than the ice at the top, since it is closer to the flame"],"answer":0,"explanation":"While ice melts, the heat supplied goes into changing its state, so the temperature does not rise until all the ice has melted. This breaks the link students make between heat and temperature.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-753","question":"While teaching about thermometers, a teacher hears students say that 'the thermometer tells us how much heat there is in the water'. Which statement should she help them reach?","options":["A thermometer measures the total heat in the water, so a bucket of water gives a higher reading than a cup","A thermometer measures heat only in liquids, since the mercury must touch the liquid to take its heat","A thermometer measures how much cold is present, while heat itself can only be felt by touching","A thermometer measures temperature, the degree of hotness, which is not the same as the quantity of heat"],"answer":3,"explanation":"A bucket and a cup of water at the same temperature give the same reading although the bucket holds far more heat, so a thermometer reads temperature, not quantity of heat.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-754","question":"To show that leaves make starch only in light, a teacher keeps a potted plant in a dark cupboard for two to three days before covering part of a leaf with black paper and placing the plant in sunlight. Why is the plant first kept in the dark?","options":["To make the plant hungry, so that it photosynthesises faster and more strongly once it is placed in light","To use up the starch already present, so that any starch found later must have been newly made","To kill germs on the leaves, so that they do not feed on the starch during the experiment","To soften the leaves in the cool dark, so that the iodine solution can enter them more easily"],"answer":1,"explanation":"Destarching removes old starch; otherwise starch found in the covered part could be left over from before, and the result would not show that light is needed. The 'hungry plant' idea is a misconception.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-755","question":"Many Class 6 students say that seeds need sunlight to germinate, because 'plants need sunlight to grow'. The most suitable way for the teacher to respond is to:","options":["Have students test soaked seeds kept in light and in a dark box, and compare what happens","Tell them clearly that seeds do not need light, so that the wrong idea is corrected at once","Accept the idea for now, since it is true for grown plants and the difference is too subtle","Show a picture of a seedling growing in sunlight, so that they see where plants grow best"],"answer":0,"explanation":"Letting students test their own idea with a fair comparison turns the misconception into an investigation; seeds germinate in the dark, though the seedlings later need light to make food.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-756","question":"A teacher gives each group one cell, one bulb and a single piece of wire, and challenges them to light the bulb. Many groups first connect the wire from one terminal of the cell to the bulb and expect it to glow. The main value of this challenge is that it:","options":["Saves the cost of extra wires, so that every group can do the activity with very little material","Shows students that some bulbs are faulty, so they learn to check each part before building a circuit","Exposes the 'one wire is enough' idea and lets students discover that a complete loop is needed","Teaches students the correct symbols for circuit diagrams before they draw their own circuits"],"answer":2,"explanation":"The task brings the students' own model into the open and lets it fail; working out that the bulb lights only when cell and bulb form a complete path builds the concept of a closed circuit.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-757","question":"Arrange the phases of the constructivist teaching sequence proposed by Rosalind Driver and colleagues in the correct order: P. Restructuring of ideas  Q. Elicitation of students' ideas  R. Orientation  S. Application of ideas  T. Review of change in ideas","options":["Q, R, P, S, T","R, Q, S, P, T","R, P, Q, S, T","R, Q, P, S, T"],"answer":3,"explanation":"The sequence begins with orientation (arousing interest), then elicits existing ideas, restructures them through conflict and new ideas, applies them, and finally reviews how the ideas have changed.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-758","question":"A teacher fixes a funnel into the mouth of a bottle and seals the gap with clay. When she pours water into the funnel, the water barely goes in. She asks, 'What is stopping the water?' This discrepant event is best used to:","options":["Arouse curiosity and make students question their ideas about air at the start of the lesson","Test students at the end of the lesson on what they have already learnt about air and air pressure","Entertain the class with a magic trick that has no scientific explanation behind it","Replace discussion about air, since students can see the answer for themselves directly"],"answer":0,"explanation":"A discrepant event produces a surprising outcome that conflicts with expectations, motivating inquiry. Here the trapped air takes up space and stops the water from entering.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-759","question":"In a Predict-Observe-Explain task, the teacher insists that students write the reason for their prediction before the demonstration. Why is this step important?","options":["It helps the teacher award marks fairly to students whose predictions turn out to be correct","It makes students' existing ideas explicit, so any conflict with the observation is noticed and discussed","It saves time later, since students then do not need to explain anything at all after seeing the demonstration","It ensures that all students think carefully enough to predict the correct answer beforehand"],"answer":1,"explanation":"Committing to a reasoned prediction surfaces the learner's prior idea; when the observation contradicts it, the learner can recognise exactly which idea needs to change.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-760","question":"A teacher narrates how Jagadish Chandra Bose designed sensitive instruments such as the crescograph to record tiny responses of plants, and how other scientists examined his claims. Which aspect of the nature of science does this narrative bring out best?","options":["Science is a fixed body of facts that great scientists discover once and for all","Scientific claims are accepted on the reputation of the scientist who makes them","Science needs creativity in designing ways to observe, and claims are tested by the wider community","Science is done mainly in expensive laboratories abroad, using costly equipment that few can access"],"answer":2,"explanation":"Bose's work shows imagination in building new instruments and the role of the scientific community in scrutinising claims, which is science as a human and social enterprise.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-761","question":"Consider these statements about science, technology and society (STS) in the upper primary curriculum. 1. Science is value-neutral, so citizens need not debate how it is used. 2. Technological decisions often involve trade-offs between benefits and risks. 3. Local communities' knowledge and concerns can be relevant to such decisions. 4. Only scientists are competent to judge any issue involving technology. Which are consistent with the NCF 2005 view?","options":["1 and 4 only","2 and 3 only","1, 2 and 3 only","2, 3 and 4 only"],"answer":1,"explanation":"NCF 2005 wants learners to weigh benefits and risks and to see the social side of science. Treating science as value-free or leaving all judgments to experts goes against its aim of informed citizenship.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-762","question":"Students report that their grandparents use neem leaves to protect stored grain from insects. The most scientific response from the teacher is to:","options":["Accept the practice as true, since traditional knowledge has been tested over generations","Dismiss it as superstition, since it is not mentioned anywhere in the science textbook","Tell students that only chemical pesticides can really protect stored grain from insects","Help students design a test comparing grain stored with and without neem leaves"],"answer":3,"explanation":"Traditional practices deserve neither blind acceptance nor rejection; a scientific attitude tests them with evidence. A fair comparison lets students judge the claim for themselves.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-763","question":"A unit test shows that many Class 7 students cannot read a temperature-time graph. The most effective remedial activity is to:","options":["Have students record the temperature of cooling tea every two minutes, plot their own graph and discuss its shape","Give many more graphs from the textbook to copy into notebooks, so that practice builds familiarity","Explain the same graph again on the board, more slowly and in the same way, until students remember it","Drop graph questions from future tests, since graph reading can be taken up again in higher classes"],"answer":0,"explanation":"Remedial teaching works best with a fresh, concrete approach; plotting data they collected themselves connects each point and the curve's shape to a real event.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-764","question":"A teacher wants her MCQ test on light to be diagnostic rather than only a measure of achievement. The distractors she writes should be:","options":["Obviously wrong, so that weaker students are not confused and the test measures only what they know","Taken from the textbook's end-of-chapter answers, so that every option is familiar to the students","Based on common wrong ideas students hold, so that each wrong choice points to a particular misconception","Random words or numbers of similar length, so that no option gives away the answer by its length or appearance"],"answer":2,"explanation":"In a diagnostic test, each distractor matches a known misconception, so a student's choice tells the teacher what she is thinking and what to remediate.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-765","question":"A teacher wants to assess how far students show curiosity, cooperation and open-mindedness during group investigations over a term. The most suitable tool is:","options":["A written test with questions on scientific attitude, given at the end of the term","A single end-of-term practical examination in which each student works alone","An essay on 'The qualities of a scientist', marked for the attitudes it describes","Anecdotal records and an observation checklist maintained during the activities"],"answer":3,"explanation":"Attitudes are shown in behaviour over time, so they are best captured by systematic observation and records of significant incidents. A written test shows what students know about attitudes, not whether they have them.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-766","question":"After an experiment, students in each group assess their own contribution and that of their group mates against criteria the class agreed upon. The main purpose of this practice in science is to:","options":["Reduce the teacher's work of marking, since students check their own work","Help students reflect on their learning and take responsibility for it","Rank students fairly for the final result using many judges","Replace the teacher's assessment completely with the students' judgement"],"answer":1,"explanation":"Self- and peer-assessment against shared criteria build reflection, metacognition and ownership of learning; they support, not replace, the teacher's assessment.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-767","question":"A curriculum committee removes dissection of animals from the upper primary practicals, and replaces it with models and observation of living organisms in their natural surroundings, citing respect for life. This decision most clearly reflects:","options":["Environmental validity, because organisms are observed in their surroundings","Cognitive validity, because dissection is too difficult for children","Ethical validity, because it promotes concern for living beings","Content validity, because models are more accurate than real organisms"],"answer":2,"explanation":"The stated reason is respect for life, which falls under ethical validity. Observing organisms in their surroundings is how the change is carried out, not why it was made.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-768","question":"A Class 7 science book contains correct information, but is written in long passive sentences full of technical words, which most students cannot follow even after reading it twice. By the NCF 2005 criteria, the book most needs improvement in:","options":["Cognitive validity, since language must also suit the learner","Content validity, since the information must be made more accurate","Historical validity, since the book lacks the history of each idea","Process validity, since the book needs more experiments"],"answer":0,"explanation":"Cognitive validity covers content, process, language and pedagogy being within the learner's reach. Here the content is accurate; it is the language that puts it out of reach.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-769","question":"Assertion (A): Hands-on activity by itself does not guarantee conceptual understanding in science. Reason (R): Learners interpret what they observe through the ideas they already hold.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because observations are read through prior ideas, students can do an activity and still hold their misconception; the activity has to be followed by discussion that challenges and reconstructs those ideas.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-770","question":"After a lesson on reflection has stated the rule, students follow a printed procedure with a plane mirror and pins to show that the angle of incidence equals the angle of reflection. This is an example of:","options":["Open inquiry","Guided inquiry","Structured inquiry","Confirmation inquiry"],"answer":3,"explanation":"When the result is known in advance and students follow given steps to verify it, it is confirmation inquiry. In structured inquiry the procedure is given but the result is not known beforehand.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-771","question":"Students are asked to choose a hypothesis for their science fair project that can actually be tested in school. Which one should the teacher accept?","options":["Plants feel happy and grow better when they are watered regularly","Some unknown force that cannot be detected by any instrument makes plants grow","Gram seeds soaked overnight germinate sooner than unsoaked gram seeds","Plants are the most important living things on earth"],"answer":2,"explanation":"A testable hypothesis names variables that can be measured and compared. Feelings of plants, undetectable forces and value judgments cannot be tested by a school investigation.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-772","question":"A Class 8 class of a school with an Atal Tinkering Lab builds a small device to remind elderly people to take their medicines on time. The pedagogic value of such work lies mainly in:","options":["Preparing students for the board examination through extra practice in applied science","Developing creativity, design thinking and the ability to apply science to real problems","Teaching students to follow written instructions exactly, step by step, as given in a manual","Replacing classroom science teaching with hands-on work in the lab"],"answer":1,"explanation":"Tinkering and design tasks develop innovation: students identify a problem, design, build, test and improve a solution, using science purposefully.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-773","question":"In a Class 8 class, a student claims that a heavier stone and a lighter stone dropped together will 'obviously' land at different times. Instead of answering, the teacher asks him to imagine the two stones tied together by a string: would the lighter one slow the heavier one down, or would the pair, being heavier, fall faster? The teacher is using:","options":["A thought experiment that exposes a contradiction in the student's own reasoning","A lecture method in which the correct answer is transmitted to the student directly","Rote memorisation of the law of falling bodies through repeated recall","A demonstration in which the stones are dropped to prove the result by observation"],"answer":0,"explanation":"Galileo's tied-stones argument shows that 'heavier falls faster' leads to two contradictory predictions, so the idea cannot be right. A thought experiment uses reasoning, not apparatus, to create cognitive conflict.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-774","question":"While teaching the water cycle, a teacher has Class 6 students keep a covered dish of water in the sun and observe droplets on the lid, then asks them to relate it to clouds and rain in their village. This sequence moves:","options":["From the abstract idea of evaporation to concrete observation","From the general principle of the water cycle to a particular example","From the known and concrete to the unknown and abstract","From the whole cycle to its separate parts, one at a time"],"answer":2,"explanation":"Beginning with a direct, observable experience and then relating it to large-scale processes follows the maxims 'known to unknown' and 'concrete to abstract'.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-775","question":"After a unit on plants, a Class V teacher in Mysuru lets each child show what they learnt through a labelled poster, an oral explanation recorded on the class phone, or a short written note. Which principle of Universal Design for Learning (UDL) does this mainly apply?","options":["Multiple means of representation of content","Multiple means of engagement","Multiple means of action and expression","Reasonable accommodation for one child"],"answer":2,"explanation":"Offering different ways for learners to show what they know is 'action and expression'. 'Representation' is about presenting content in varied forms, a common confusion; this is a design for all, not an individual accommodation.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-776","question":"In a Class IV maths lesson on division, all children work towards the same goal of sharing equally. Some use bottle caps and plates, some draw pictures, and some work only with numbers. What is the teacher differentiating here?","options":["The content, because each group is learning a different topic suited to its level","The process, because children reach the same goal by different routes suited to their readiness","The product, because each group submits a different kind of final assignment at the end of the lesson","The learning environment, because the furniture and seating have been rearranged for groups"],"answer":1,"explanation":"In Tomlinson's model, differentiating process means varying how learners make sense of the same content. The learning goal (content) is common here, and the outputs are not what is being varied.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-777","question":"Consider the following statements about the Rights of Persons with Disabilities Act, 2016: 1. It recognises 21 types of disabilities. 2. It describes inclusive education as a system in which students with and without disabilities learn together, with teaching and learning suitably adapted. 3. It requires children with disabilities to study only in special schools. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The RPwD Act 2016 lists 21 disabilities and promotes inclusive education in regular schools with adaptations; it does not confine children to special schools, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-778","question":"Asha, who has cerebral palsy and uses a wheelchair, is admitted to Class III of a regular school. She sits at the back because the aisles are narrow, no materials are adapted, and she does not join group work. Which description fits this situation best?","options":["Full inclusion, because Asha is in a regular classroom alongside other children of her own age and locality","Exclusion, because she has not been placed in a special school suited to her disability","Inclusion, because the school has met the RTE Act requirement simply by admitting her","Integration without inclusion, since the classroom and teaching have not been adapted for her to take part"],"answer":3,"explanation":"Inclusion means the school changes its space, materials and teaching so every child participates fully. Merely placing the child in a regular room while expecting her to fit in is integration, not inclusion.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-779","question":"Karan, a Class VI student with partial hearing loss, relies partly on lip-reading. Which set of classroom adjustments is most appropriate?","options":["Seat him at the back so that loud voices do not hurt his ears, and speak much louder than usual whenever addressing him","Seat him near the front with a well-lit view of the teacher's face, and write key words and instructions on the board","Seat him near the window for fresh air and light, and give him extra written homework in place of oral work","Excuse him from all discussions and oral activities so that he is not embarrassed in front of others"],"answer":1,"explanation":"A child who lip-reads needs a clear, well-lit view of the speaker's face and visual support for key information. Shouting distorts lip patterns, and excluding him from oral work denies participation.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-780","question":"Imran in Class IV narrates stories brilliantly and solves oral maths problems, but reads very slowly, confuses b and d, and his written answers are short and full of errors. Which response is most appropriate?","options":["Make him copy two pages from the textbook daily, so that steady practice improves his reading and writing","Treat him as lazy and careless, since a child who speaks so well could clearly write well if he tried","Recommend that he repeat Class IV, so that his reading and writing can catch up with his speaking","Suspect dyslexia; use multisensory methods, allow oral answers and extra time, and seek an assessment"],"answer":3,"explanation":"A gap between strong oral ability and weak reading and writing is typical of dyslexia, which needs multisensory methods and accommodations. Copying, labelling or retention punish the child for a learning difference.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-781","question":"Riya, diagnosed with ADHD, finds it very hard to stay seated through long written tasks in Class III. Which strategy is best?","options":["Give short tasks with checkpoints, build in movement, and seat her near the teacher away from distractions","Seat her near the window so that she can look outside whenever she feels restless and calm herself down quietly","Give her longer tasks every day so that she gradually trains herself to sit still for long periods","Keep her inside during recess to finish incomplete work, so that she learns that tasks must be completed"],"answer":0,"explanation":"Short, structured tasks, purposeful movement and reduced distraction work with how ADHD affects attention. Longer tasks or losing recess increase the very restlessness they target.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-782","question":"A Class VI teacher finds that a group of students has been calling Deepika names because of her dark skin. What is the most appropriate course of action?","options":["Tell Deepika to ignore them, since such teasing is a normal part of growing up and usually stops once it gets no reaction","Make the bullies apologise in the morning assembly in front of the whole school, so that others are warned too","Support Deepika privately, talk firmly with the bullies about the harm caused, and discuss respect and colourism in class","Move Deepika to another section so that she is kept away from the bullies and can study in peace"],"answer":2,"explanation":"Effective anti-bullying work protects the target, holds the bullies accountable in a way that changes behaviour, and addresses the prejudice with the whole class. Ignoring it, moving the victim or public shaming leaves the cause untouched.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-783","question":"During the mid-day meal in a village school, a few children refuse to sit next to classmates from a Scheduled Caste community. What should the teacher do?","options":["Arrange separate rows for the two groups, so that the meal goes on peacefully and no family's beliefs are offended","Seat all children together, firmly stop the discrimination, and take up the prejudice with the class and parents","Ignore it for now, since these are views children bring from home and the school cannot change them","Let the children who object eat in another room, so that the others can have their meal without any trouble"],"answer":1,"explanation":"Untouchability is abolished under Article 17 and any discriminatory practice in school must be stopped; the teacher must also work on the attitudes behind it. Separate seating accepts and reinforces discrimination.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-784","question":"In a Class V classroom, girls are always asked to sweep and decorate the board, while boys move benches and fetch the sports kit. Which change best reflects a gender-sensitive classroom?","options":["Continue as before, since these tasks suit the natural abilities and interests of girls and boys respectively","Ask only for volunteers each day, so that every child freely picks the duties he or she prefers to do","Hire a helper for all such tasks, so that no child has to spend class time on chores at all","Rotate all duties among all children, and discuss why tasks should not be divided by gender"],"answer":3,"explanation":"Assigning tasks by gender teaches stereotypes through the 'hidden curriculum'. Rotating duties for everyone, with discussion, makes equality visible; volunteering alone often reproduces the same pattern.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-785","question":"Assertion (A): Children learn more in a classroom where mistakes are treated as a normal part of learning. Reason (R): When children fear being wrong, they avoid taking risks and hide what they do not understand.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Fear of error leads to silence and hiding confusion, so the teacher never sees what needs fixing. Treating errors as information makes it safe to try, which is why A follows from R.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-786","question":"A Class VII teacher routinely refers to Section C as 'the weak section' in front of the students and gives them easier work and fewer questions. Over the year their results fall further. Which phenomenon best explains this?","options":["The Hawthorne effect, since the students knew they were being watched and labelled by the teacher all year","Self-fulfilling prophecy, where low teacher expectations shape treatment and then students' performance","The halo effect, since one trait of the section shaped the teacher's overall judgement of it","Regression to the mean, since extreme scores tend to move towards the average over a year"],"answer":1,"explanation":"Rosenthal and Jacobson's Pygmalion research showed that teacher expectations affect how students are treated and how they perform. Labelling plus reduced challenge turned the low expectation into reality.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-787","question":"Somu, a first-generation learner from a tribal family in Dantewada, rarely completes homework, and there is no one at home who can read. What is the most appropriate response?","options":["Punish Somu each time he misses homework, so that he builds the habit of completing it regularly","Ask his parents to arrange private tuition, so that someone can help him with homework every evening","Understand his home situation, set homework he can do alone or with peers, and give support time in school","Stop expecting any homework from Somu, since his home cannot support him and he should not be put under stress"],"answer":2,"explanation":"Homework that assumes literate adults at home disadvantages first-generation learners; adjusting tasks and giving school-based support is equitable. Punishing or giving up both fail the child.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-788","question":"Twelve-year-old Lakshmi, the child of seasonal migrant brick-kiln workers, has never attended school. Her parents seek admission in a government school in October. Under the RTE Act 2009, what should the school do?","options":["Admit her to an age-appropriate class (around Class VI) and give special training to help her catch up","Admit her to Class I, since a child who has never been to school must begin from the first class","Refuse admission for now, since the session has already started, and ask the family to come back next April","Ask for her birth certificate and refuse admission until it is produced, as proof of age is required"],"answer":0,"explanation":"Section 4 of the RTE Act requires a child who has not been admitted or has dropped out to be placed in an age-appropriate class with special training. Admission cannot be denied for the time of year or lack of age proof.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-789","question":"A Class IV child quietly tells her teacher that a relative touches her in ways that make her uncomfortable, and begs her not to tell anyone. What is the correct response?","options":["Promise to keep it a secret, so that the child continues to trust her and shares more in the future","Call the relative to school and question him in front of the child, so that the truth comes out at once and he is warned","Ask the child to describe the incidents in detail several times, to check whether her story stays the same","Listen calmly, believe her, tell her it is not her fault, explain that she must be helped, and report it under POCSO"],"answer":3,"explanation":"The POCSO Act 2012 makes reporting of suspected child sexual abuse mandatory; the teacher must not promise secrecy, must avoid repeated questioning that re-traumatises the child, and must not confront the alleged abuser herself.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-790","question":"In a Class V classroom, the teacher always seats the highest scorers in the front rows and the 'slow' children at the back. Which change best supports an inclusive classroom?","options":["Keep the arrangement, since toppers deserve to sit in front and it motivates others to work harder","Move the slow children to the front and the toppers to the back, so that the weak get more attention","Rotate seating and use mixed-ability groups, placing children with specific needs where they are best supported","Let children choose their own seats for the whole year, so that they can sit with their friends and feel comfortable"],"answer":2,"explanation":"Fixed seating by ability signals the teacher's expectations and isolates some children. Rotation and mixed groups widen interaction; individual needs, such as hearing or vision, still guide where a child sits.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-791","question":"Consider the following statements about teaching mathematics to a child who is blind in a Class VI inclusive classroom: 1. A Taylor frame or an abacus can be used for calculation. 2. Tactile diagrams with raised lines can be used for geometry. 3. The child should be excused from geometry, since it depends entirely on vision. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"Tactile and assistive tools let a blind child learn the same concepts, including geometry, through touch. Excusing the child from geometry is exclusion, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-792","question":"Gopal, a Class III child with a mild intellectual disability, cannot follow a multi-step task such as 'measure the table, record it and compare it with your friend's table'. Which teacher action is most appropriate?","options":["Repeat the full instruction more loudly and slowly until he can follow all of it in one go without help","Break the task into small steps with concrete materials and demonstration, giving feedback after each step","Give him a colouring sheet instead while the others measure, so that he does not feel left behind","Ask a classmate to do the task for him, so that the group's table is completed on time"],"answer":1,"explanation":"Task analysis (smaller steps, concrete support, immediate feedback) lets children with intellectual disability learn the same skill. Substituting a different activity or letting peers do it removes the learning opportunity.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-793","question":"Pooja in Class V finishes every maths task in minutes and then disturbs others out of boredom. What is the most appropriate step for the teacher?","options":["Give her more problems of the same type, so that she stays busy and gets extra practice in the meantime","Make her sit quietly until the others finish, as a useful lesson in patience and in respecting her slower classmates","Promote her to Class VI immediately, since the Class V syllabus is clearly too easy for her","Offer enrichment: deeper, open-ended problems on the same concept, and at times let her explain solutions to peers"],"answer":3,"explanation":"Gifted learners need greater depth and complexity, not more of the same, which feels like a penalty. Enrichment keeps her engaged while the class continues; skipping a grade is a much bigger decision than the problem needs.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-794","question":"Arif in Class II stammers. When he answers, some classmates laugh and the teacher often finishes his sentences to save time. What should the teacher do instead?","options":["Let Arif finish, keep natural eye contact, never complete his words, and set a norm that nobody laughs","Stop asking Arif to answer orally, so that he is not embarrassed and his confidence is protected","Ask Arif to speak faster and to take a deep breath before every sentence so that the words come out","Let Arif answer only in writing for the rest of the year, so that his ideas are heard without pressure"],"answer":0,"explanation":"Patience and an accepting climate reduce the pressure that makes stammering worse; finishing sentences or telling him to 'breathe' increases it. Removing oral participation excludes him from talk, which every child needs.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-795","question":"Assertion (A): Providing a scribe in examinations for a Class VIII student with dysgraphia gives him an unfair advantage over other students. Reason (R): Accommodations change the way a student shows learning, not the learning outcome being assessed.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"A scribe removes the barrier of handwriting so the test measures what it is meant to measure; the standard of answers is the same. R is true and it shows why A is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-796","question":"A Class IV teacher in Hyderabad gives all examples in her lessons from one community's festivals, food and names. Children from other backgrounds stay quiet. Which step would best make the classroom more inclusive?","options":["Avoid examples from any community at all, so that no child feels singled out or left out of the lesson","Ask children from other communities to learn about the majority festivals, so that they can fit in better with others","Draw examples from the festivals, food, names and languages of all the children, and invite them to share","Use examples only from the textbook, since these have been chosen to be neutral for every region"],"answer":2,"explanation":"Seeing their own lives in lessons gives children a sense of belonging and makes learning relevant. Removing all culture or expecting assimilation leaves minority children invisible.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-797","question":"A Class VII teacher notices that several girls are absent for a few days every month, and learns it is linked to menstruation and lack of facilities. What is the most appropriate response?","options":["Mark them absent without comment, since menstruation is a private matter the school should not discuss","Press the head and SMC for private toilets and sanitary support, and hold stigma-free talks on menstrual health","Advise the girls to rest and cope at home on those days, and borrow notes from classmates afterwards","Tell only the girls' mothers to send them to school regularly, since attendance is the family's duty"],"answer":1,"explanation":"Absence linked to menstruation is a barrier the school can address through facilities and by breaking stigma; a safe school includes these needs. Treating it as only a private or family issue leaves the barrier in place.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-798","question":"Consider the following statements about inclusive education: 1. Inclusion means changing the school to fit the child rather than expecting the child to fit the school. 2. Inclusion is concerned only with children with disabilities. 3. Inclusive classrooms also benefit children without disabilities. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Inclusion covers all forms of diversity (disability, gender, caste, language, poverty) and benefits all learners through empathy and flexible teaching. Statement 2 wrongly narrows it to disability.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-799","question":"Eight-year-old Nisha, usually cheerful, has become withdrawn and tearful since her parents separated. Which response by the class teacher is best?","options":["Mention her family situation in class so that her classmates understand and are extra kind to her","Ignore it, since family matters are outside a teacher's role and children usually settle down in time on their own","Talk to her privately and warmly, keep a calm routine, involve the counsellor with care, and keep it confidential","Give her extra work to keep her mind busy, so that she has less time to think about the separation"],"answer":2,"explanation":"Emotional safety needs a caring adult, predictability, professional support and confidentiality. Disclosing her situation in class or ignoring her distress would harm her further.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-800","question":"Asked ‘Which is larger, 2n or n + 2?’, a Class 7 student answers at once, ‘2n, because multiplying makes things bigger.’ What should the teacher help her see?","options":["She is right, because doubling a number always gives at least as much as adding 2 to it","She is wrong, because for whole numbers adding 2 always gives more than doubling the number","It depends on n: 2n is larger if n > 2, they are equal at n = 2, and n + 2 is larger if n < 2","The question cannot be answered, because letters stand for objects and so cannot be compared in size"],"answer":2,"explanation":"Trying n = 1, 2 and 5 shows that the answer changes. The student treats n as a fixed number and uses the false idea that multiplying always makes bigger; seeing n as any number is the heart of algebraic thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-801","question":"Asked to ‘add 5 to x’, a Class 6 student says the question is incomplete ‘because x + 5 is not an answer; we must get a number’. This difficulty is known as:","options":["lack of closure, not accepting an expression as a complete answer","letter as object, where the letter x is read as a name for a thing","reversal error, where the order of words is copied into the symbols","over-generalising the distributive law to every kind of bracket"],"answer":0,"explanation":"From arithmetic, children expect every answer to be a single number. Accepting x + 5 as both a process and an answer (an object) is a key step towards algebra.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-802","question":"‘At a school there are 6 times as many students as teachers.’ Using S for students and T for teachers, a Class 8 student writes 6S = T. What is the best way to help her?","options":["Tell her to write the letters in the same order in which the words appear in the sentence","Ask her to test it with numbers: if there are 10 teachers, does 6S = T give 60 students?","Give her the rule ‘the bigger group always gets the number’ so that she can check quickly","Accept it, since it uses both letters correctly and matches the wording of the sentence"],"answer":1,"explanation":"This is the classic reversal error: S and T are read as labels (‘6 students for each teacher’), not as numbers. Testing with T = 10 shows 6S = 10 is absurd; the correct equation is S = 6T.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-803","question":"A Class 7 student solves 3x = 12 and writes x = 9. What has she most likely done?","options":["Divided 12 by 3 and made a slip in the division","Confused 3x with x³","Subtracted 12 from 3 and dropped the sign","Read 3x as 3 + x and subtracted 3 from 12"],"answer":3,"explanation":"Getting 9 from 12 means she ‘undid’ an addition, so she read 3x as 3 + x. Asking ‘what does 3x mean?’ and checking 3 × 9 = 27 ≠ 12 by substitution exposes this.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-804","question":"A Class 8 student writes (a + b)² = a² + b². Which response is most likely to change her understanding?","options":["Draw a square of side a + b, split it into parts and ask her to find each part's area","Ask her to learn the identity (a + b)² = a² + 2ab + b² by heart and recite it daily","Tell her that the power cannot be given to each term separately and must be applied whole","Give her ten more expansions to practise, so that the correct form becomes a habit"],"answer":0,"explanation":"The area model shows a² and b² plus two rectangles of area ab, giving a² + 2ab + b². Checking with a = 2 and b = 3 (25 versus 13) also shows the error. She has over-generalised the distributive law.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-805","question":"Asked to find the value of 2x² when x = 3, a Class 7 student writes 36. What is the error?","options":["She has added instead of multiplying at some step of the work","She has calculated 2 × 3 × 2, doubling the power instead of squaring","She has squared 2x instead of only x; it should be 2 × 9 = 18","She has substituted the wrong value of x into the expression"],"answer":2,"explanation":"In 2x² the power belongs only to x, so 2x² = 2 × 3² = 18. Her answer 36 is (2 × 3)². Writing 2 × x × x helps students see what the power applies to.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-806","question":"For a tile pattern of 5, 8, 11, 14, … tiles, a student finds the 20th figure by adding 3 again and again in a table. Which next step by the teacher best moves her towards algebraic thinking?","options":["Tell her that her method is wrong and that adding again and again is not proper mathematics","Ask her to continue the table carefully up to the 50th figure, so that she becomes fully fluent in the pattern","Give her the formula for the nth term of an arithmetic progression and ask her to apply it","Ask how the number of tiles is linked to the figure number, such as how to find the 100th figure directly"],"answer":3,"explanation":"Adding 3 each time is recursive thinking; linking tiles to the figure number (3n + 2) is functional thinking, which lets her generalise. A large figure number makes the step-by-step table impractical and invites the rule.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-807","question":"For the number of border tiles around an n × n square of tiles, students give 4n + 4, 2n + 2(n + 2), 4(n + 1) and (n + 2)² − n². What should the teacher do?","options":["Accept only 4n + 4, since it is the simplest form and the others are needlessly long","Have each student link their expression to how they saw the figure, then show that all four are equal","Accept only (n + 2)² − n², since it is the only one that uses the area of the squares","Tell the class that more than one formula means some students must have counted the tiles wrongly"],"answer":1,"explanation":"All four expressions simplify to 4n + 4, and each comes from seeing the border differently. Linking every expression to the figure, and then proving them equivalent, gives meaning to algebraic manipulation.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-808","question":"Match each statement with the role the letter plays in it. 1. x + 3 = 8 2. a + b = b + a 3. y = 2x + 1 4. A = l × b; a. a formula linking measures b. a generalised number (true for every value) c. a specific unknown d. a quantity that varies with another","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"In x + 3 = 8 the letter has one value; in a + b = b + a it stands for any numbers; in y = 2x + 1, y changes as x changes; A = l × b links area to length and breadth. Students need to meet all these uses.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-809","question":"Which statement about using a pan balance to teach equations is correct?","options":["It cannot model any equation that has the unknown on both sides, such as 3x + 2 = x + 8","It is meant mainly to teach the rule ‘change the side, change the sign’ in a concrete way","It shows ‘do the same to both sides’ well, but is awkward for subtraction or negatives, as in 2x − 3 = 7","It should replace written symbols completely in Class 7, since the physical model is much easier for children to grasp"],"answer":2,"explanation":"Removing equal weights from both pans models solving well, and it handles unknowns on both sides. But you cannot place negative weights in a pan, so the model has limits; that is why teachers also use other models.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-810","question":"A Class 7 student solves x − 5 = 12 as ‘x = 12 − 5 = 7, because I moved the 5 across’. Which response best helps?","options":["Repeat the rule ‘change side, change sign’ more firmly until she applies it correctly","Give her ten similar equations to practise, so that the correct move becomes automatic","Tell her to always add the numbers that appear on both sides of an equation","Ask her to put x = 7 back into x − 5 = 12, then think of adding 5 to both sides"],"answer":3,"explanation":"Substitution shows 7 − 5 = 2, not 12. Seeing ‘add 5 to both sides’ (x = 17) gives meaning to the move; the rote ‘move across’ rule is exactly what she has misapplied.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-811","question":"Assertion (A): Students should be asked to substitute their solution back into the original equation. Reason (R): Substituting checks whether the value makes the equation true and builds the habit of self-checking.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"A solution is, by definition, a value that makes the equation true, so substitution is a natural check; R explains why the practice in A is valuable.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-812","question":"‘Without adding, is 37 + 48 = 38 + 47 true or false?’ Which student answer shows relational thinking?","options":["‘True, because I worked out both sides and got 85 on each side of the sign.’","‘True, because 38 is one more than 37 and 47 is one less than 48.’","‘False, because the numbers on the two sides are different, so the sums must differ.’","‘True, because both sides have two numbers and the same kind of sum.’"],"answer":1,"explanation":"Relational thinking compares the structure of both sides (one more, one less) without calculating, which is the kind of reasoning algebra needs. Option A is correct but computational.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-813","question":"Asked to show that the sum of any three consecutive numbers is divisible by 3, which student response shows algebraic generalisation?","options":["‘4 + 5 + 6 = 15 and 10 + 11 + 12 = 33, and both of these sums divide exactly by 3.’","‘I tried twenty different sets of three numbers and every single one of them worked.’","‘If the middle number is n, the sum is (n − 1) + n + (n + 1) = 3n, a multiple of 3.’","‘It is true because 3 is an odd number, and three odd steps always give a multiple of 3.’"],"answer":2,"explanation":"Writing the numbers in terms of n covers every case and explains why it works. Any number of examples only supports the claim; it does not prove it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-814","question":"A Class 7 student writes 2(x + 3) = 2x + 3. Which representation best shows her the error?","options":["A balance with 2 on one pan and x + 3 on the other, to show both sides are equal","Expanding brackets with the rule ‘multiply only the first term inside by the number’","A number line from 0 to x + 3, marking x first and then the 3","A rectangle 2 wide and x + 3 long, split into a 2 × x part and a 2 × 3 part"],"answer":3,"explanation":"The area model shows both parts are multiplied by 2: 2x + 6. Testing x = 1 (8 versus 5) also exposes it. Option B states her own wrong rule.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-815","question":"A student writes 3x + 2 = 5x. The teacher wants to show the error by substituting a value for x. Which value would NOT reveal the error?","options":["x = 1","x = 2","x = 0","x = 10"],"answer":0,"explanation":"At x = 1 both sides are 5, so the wrong statement looks true. At x = 2 it gives 8 against 10, at x = 0 gives 2 against 0, and at x = 10 gives 32 against 50. Teachers must choose test values with care.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-816","question":"A Class 7 student writes (−3) − (−5) = −8. Which model best helps her make sense of the correct answer?","options":["The rule ‘two negatives make a positive’, applied to the two minus signs in the question","Counters: start with 3 red (negative), add two zero pairs, take away 5 red, and see what is left","A thermometer that reads −3 degrees and then falls by a further 5 degrees during the night","The rule that subtraction always gives an answer smaller than the starting number"],"answer":1,"explanation":"Adding two zero pairs (a red and a yellow) lets her remove 5 reds, leaving 2 yellows, so the answer is +2. A falling thermometer models subtracting a positive, and ‘two negatives make a positive’ is misapplied everywhere.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-817","question":"Which approach best helps Class 7 students see why (−1) × (−2) = 2?","options":["State the rule that a negative times a negative is positive, and drill it with many examples","Explain that two wrongs make a right, so two negative signs together become a positive one","Extend the pattern 2 × (−2) = −4, 1 × (−2) = −2, 0 × (−2) = 0 and ask what comes next","Tell them it is a convention that cannot be explained at school level and must be accepted"],"answer":2,"explanation":"Each step adds 2, so extending the pattern gives (−1) × (−2) = 2. The pattern keeps the rule consistent with what students already know; ‘two wrongs make a right’ is a misleading slogan.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-818","question":"A Class 6 student writes 2³ = 6. What should the teacher focus on?","options":["Telling her to memorise powers of 2","Explaining that powers are not part of the Class 6 syllabus","Giving her a calculator to check","The meaning of the power: 2³ means 2 × 2 × 2, not 2 × 3"],"answer":3,"explanation":"She has multiplied the base by the exponent. Writing the power as repeated multiplication (2 × 2 × 2 = 8) fixes the meaning, which memorising answers does not.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-819","question":"A Class 8 student writes a³ × a² = a⁶. Which response is most useful?","options":["Ask her to write both powers out in full as a × a × a and a × a and count the factors","Tell her that powers are added, not multiplied, when the bases are the same, and move on","Ask her to practise twenty such questions until the rule for indices becomes automatic","Accept it, since 3 × 2 = 6 and the index rules are only a matter of convention"],"answer":0,"explanation":"Writing out the factors shows five a's in all, so a³ × a² = a⁵. Expanding gives a reason she can use again, rather than a rule she may confuse with (a³)² = a⁶.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-820","question":"A teacher plays ‘think of a number, add 5, double it, subtract 10, halve it, and you get your number back’. What is the main value of then asking the class to explain the trick with a letter?","options":["It gives quick practice in the four operations through a game that students enjoy","It shows that a letter can stand for any number, so it explains why the trick always works","It shows that number tricks are often a quicker route than algebra for such problems","It helps students learn how to guess the numbers other people are thinking of"],"answer":1,"explanation":"With n: ((n + 5) × 2 − 10) ÷ 2 = n. The letter covers every possible number at once, which is exactly why algebra is useful for proving general results.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-821","question":"For a function machine whose input-output table is 1 → 5, 2 → 8, 3 → 11, 4 → 14, a student says the rule is ‘add 3’. Which question best moves her towards a rule linking input and output?","options":["‘Is the output always an odd number, or does it change?’","‘What is the next output after 14, if you add 3 again?’","‘What would the output be if the input were 100?’","‘Can you add up all the outputs and find their total?’"],"answer":2,"explanation":"‘Add 3’ describes how the outputs change, not how each output depends on its input. Asking for input 100 forces a direct rule: output = 3 × input + 2, so 302.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-822","question":"Given a + b = 10, a Class 7 student refuses to accept a = 5, b = 5 ‘because different letters must have different values’. What is the best response?","options":["Agree with her, since different letters in algebra always stand for different numbers","Tell her that a and b must always be equal, since they appear in the same equation","Tell her that letters cannot have fixed values at all, since in algebra they only stand for unknown things","Ask whether 5 + 5 makes it true, and discuss that different letters may, but need not, have the same value"],"answer":3,"explanation":"Different letters can stand for the same number; the only rule is that one letter keeps one value within a problem. Checking 5 + 5 = 10 lets her see this for herself.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-823","question":"Solving x + x = 10, a student offers x = 3 and x = 7 ‘because 3 + 7 is 10’. Which idea does she lack?","options":["That one letter must stand for the same value everywhere in a statement","That x can only be a whole number, so fractions and decimals are not allowed","That two letters can never be added together unless their values are known","That an equation has no solution unless it is first written in the form 2x = 10"],"answer":0,"explanation":"Within one statement, each x stands for the same number, so x + x = 2x = 10 gives x = 5. She is treating each x as a separate unknown.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-824","question":"Which of these statements about preparing children for algebra are correct? I. Pattern work in the primary classes lays a foundation for algebra. II. Children should not meet letters for numbers before Class 8. III. Understanding ‘=’ as ‘has the same value as’ is needed for solving equations. IV. Teaching that ‘a stands for apple’ helps build the idea of a variable.","options":["I, III and IV","I and III only","II and IV only","I, II and III"],"answer":1,"explanation":"Patterns and a relational ‘=’ prepare children for algebra. ‘a for apple’ makes the letter a label for objects, not a number, which causes later errors; and letters appear from Class 6, not Class 8.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-825","question":"Class VII students list the work done by each family member. Several write about their mothers, 'She does nothing; she is a housewife.' What should the teacher help them recognise?","options":["That housewives do no productive work, since they are not employed, so the entries are correct","That only work done outside the home for a salary or wage can properly be counted as work","That cooking, cleaning, fetching water and caring are work, though unpaid and often undervalued","That the activity should be dropped, since it touches on private family matters best left alone"],"answer":2,"explanation":"Household and care work takes long hours and keeps families running, yet because it is unpaid it is often treated as 'nothing'. Making this work visible is a key gender concern of the social science curriculum.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-826","question":"A teacher replaces the phrase 'early man' with 'early people' or 'early humans' throughout her Class VI history notes. What is the best justification?","options":["The new phrase is shorter, simpler and easier for young children to spell correctly","Language shapes how we imagine the past, and 'man' tends to hide women's roles","The textbook does not use the word 'man' anywhere, so notes must match the textbook","Historians have proved that early societies were led by women rather than by men"],"answer":1,"explanation":"Gendered language quietly suggests that the past was made only by men. Inclusive terms let children picture women gathering, making tools and raising families as part of early human life.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-827","question":"In a Class VI lesson on livelihoods, a teacher's examples are a male farmer, a male doctor, a female nurse and a female teacher. Which critique is the most accurate?","options":["The examples are fine, since they match the occupations most commonly seen in society","The examples should avoid all mention of gender, so that children do not notice it at all","The lesson should focus only on men's occupations, since men are usually the main earners for most families","The examples reinforce stereotypes about work; women farmers and men in caring jobs should also appear"],"answer":3,"explanation":"Women do a large share of farm work, and men can be nurses and teachers. Examples that always pair jobs with one gender teach children a narrow, stereotyped picture of who can do what.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-828","question":"In a co-educational Class VIII, boys answer most questions while girls speak only when called upon. Which strategy best ensures equitable participation?","options":["Allow boys to continue answering, since they are more confident and keep the lesson moving","Ask girls to sit in the front rows, so that the teacher can see them and call on them more","Use structured turn-taking, give thinking time, and form mixed groups with rotating roles such as reporter","Hold separate discussions for boys and girls on different days, so that girls feel free to speak"],"answer":2,"explanation":"Wait time, deliberate turn-taking and rotating roles in mixed groups give every learner a fair chance to speak. Separating boys and girls avoids the problem instead of addressing it.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-829","question":"Assertion (A): Women's history in the classroom should not be limited to famous queens and freedom fighters.\nReason (R): The work, lives and struggles of ordinary women are also part of how society changed.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A list of 'great women' adds a few names but leaves the main story unchanged. Including ordinary women's experience, such as in farming, factories or reform movements, is why women's history must go beyond famous figures.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-830","question":"Which of the following statements about gender are correct?\n1. Gender roles are shaped by society and differ across places and periods.\n2. Differences between the roles of boys and girls are entirely biological.\n3. Textbooks and classroom practices can either reinforce or challenge gender stereotypes.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Sex is biological, but gender roles are social constructions that vary across societies and times. Schools, through texts and practice, can strengthen stereotypes or question them; statement 2 confuses gender with sex.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-831","question":"A Class VII chapter compares how boys and girls grew up in a Pacific island society in the 1920s with how they grew up in an Indian town in the 1960s. What is the main purpose of this comparison?","options":["To show that one society treated its children better and more fairly than the other did","To teach students the geography and way of life of the Pacific islands in some detail","To prove that boys and girls are naturally suited to different tasks, whatever the society","To show that what is expected of boys and girls differs with society and time"],"answer":3,"explanation":"Seeing that childhood roles were organised differently elsewhere and at another time shows that gender roles are socially made, which opens them to questioning. The comparison argues against the 'natural' view, not for it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-832","question":"A Class VI student with a visual impairment is in a lesson on reading the physical map of India. What is the best adaptation?","options":["Exempt her from map work, since maps are visual and she can make up the marks elsewhere","Use a raised-relief map, describe features aloud, and let a peer guide her hands across it","Ask her to listen carefully while the others read the map aloud and name its features","Give her a written list of rivers and mountains to memorise in place of the map work"],"answer":1,"explanation":"Inclusive education adapts the material so that the learner meets the same goal. Tactile maps with verbal support let her explore relief and location; exemption or rote lists deny her the learning.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-833","question":"Mamata has recently moved with her family from Odisha to a Gujarati-medium school in Surat. She understands little Gujarati and stays silent in social science. What should the teacher do?","options":["Wait until she learns Gujarati fully before involving her in lessons, so that she is not confused or embarrassed","Seat her at the back for now so that she does not slow the class while she picks up the language","Use visuals and peer support, let her share ideas in her home language, and draw on her knowledge of Odisha","Give her lower-level work permanently, since she cannot follow the language used in the lessons"],"answer":2,"explanation":"Language is a bridge, not a barrier to be cleared first. Visuals, peer help and valuing her own language and experience bring her into learning now and enrich the class.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-834","question":"A Class VI teacher's examples of festivals in a lesson on diversity come only from the majority religion, though the class has Muslim, Sikh and Christian students. What should she change?","options":["Include festivals and practices of different communities, including those of her own students","Remove all festivals from the lesson, so that religion does not enter the classroom at all","Ask minority students to explain their festivals, but only if they volunteer after school hours","Keep the examples as they are, since the textbook already lists them and they are widely known"],"answer":0,"explanation":"A lesson on diversity must reflect the diversity it describes. Showing only one community's practices makes others invisible; dropping the topic loses a meaningful link to children's lives.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-835","question":"Which explanation of why many Adivasi communities in India are considered marginalised best fits the social science approach?","options":["Their cultures are primitive and have not developed in step with the rest of modern, urban Indian society","They prefer to stay away from mainstream society and so choose not to take up its benefits","They are fewer in number, and small groups are always marginalised in a large democracy","They have been pushed out of economic and political power, through loss of land and forest rights"],"answer":3,"explanation":"Marginalisation is a process of exclusion from resources and power, not a feature of a community's culture. Calling a culture 'primitive' is the very prejudice that social science teaching should question.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-836","question":"While teaching the growth of Bombay, a Class VIII teacher spends time on the lives of mill workers, dock labourers and migrants from the Konkan, not only on the merchants and colonial officials. This reflects which approach to history?","options":["Great-man history","History from below","Diplomatic history","Dynastic history"],"answer":1,"explanation":"'History from below' tells the past through the experience of ordinary and working people. The other approaches centre on rulers, elites or relations between states.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-837","question":"A teacher prides herself on 'finishing the textbook line by line' every year and never using anything else. Which statement best evaluates this practice in light of NCF 2005?","options":["It makes the textbook the sole source, whereas NCF 2005 treats it as one resource among many","It is ideal, since the textbook contains everything the examination will ask about","It is acceptable only if she also gives notes from guidebooks to cover extra questions","It is wrong, because textbooks should not be used in social science teaching at all"],"answer":0,"explanation":"NCF 2005 asks teachers to go beyond the textbook and draw on the child's surroundings and other sources. Rejecting textbooks altogether is a different mistake; they remain a useful resource.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-838","question":"A Class VI geography textbook illustrates rivers with examples from the plains. A teacher in Leh uses the streams, glaciers and irrigation channels around the town for the same lesson. What does this show?","options":["She is departing from the prescribed syllabus and should go back to the textbook's own examples of rivers","She is filling a gap a national textbook cannot avoid, with local examples that give the concepts meaning","She is using local examples, which are useful only in primary classes, not in Class VI","She is right only because students in Leh do not need to learn about rivers in the plains"],"answer":1,"explanation":"A national textbook cannot cover every region. Using local geography teaches the same concepts through what the children see, and they can then compare it with other regions.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-839","question":"Assertion (A): NCF 2005 favours a variety of textbooks and learning materials rather than one prescribed book.\nReason (R): A single textbook can make knowledge look fixed and final and may not suit local contexts.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"NCF 2005 encourages multiple materials because one authoritative book presents knowledge as closed and cannot reflect every region's context. R explains A.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-840","question":"A Class VIII teacher asks students to read a textbook paragraph on the building of a railway line and to answer: 'From whose point of view is this written? Whose experience is missing?' What is she mainly teaching?","options":["That the textbook is full of errors and should be set aside in favour of other books","How to summarise a paragraph by picking out the main points of the author","That textbooks too present events from particular perspectives and can be read critically","How railways were built and who planned and paid for the railway lines"],"answer":2,"explanation":"Textbooks are not neutral windows on the past. Asking whose view is present and whose is absent, for example the labourers or the people displaced, builds critical reading without dismissing the text.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-841","question":"A Class VIII textbook's table on literacy uses census figures that are more than a decade old. What should the teacher do?","options":["Teach the figures as current, since the textbook is officially approved and the examination follows it","Skip the table altogether, since outdated data can only confuse students and waste class time","Tell students that data in textbooks are never reliable and should not be studied","Point out the year of the data, compare it with newer official figures, and discuss what has changed"],"answer":3,"explanation":"Data are always tied to a date. Noting the year and comparing with newer figures teaches students to read data critically and shows trends, rather than treating the textbook figure as timeless.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-842","question":"To finish the syllabus on time, a Class VII teacher skips all the in-text boxes and 'Let's discuss' questions in the NCERT social science book and teaches only the main text. What is the main loss?","options":["Students miss prompts that link ideas to their own lives and make them think and discuss","Students lose information that appears often in board examination questions","Students miss pictures and boxes that are mainly decorative and add little","There is no real loss, since the boxes are optional and are not part of the syllabus"],"answer":0,"explanation":"In-text questions and boxes are designed to pause the reading for reflection, discussion and connection with students' experience. Skipping them turns an inquiry-oriented book into a reader of facts.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-843","question":"Class VI students in a tribal-area school in Chhattisgarh find the language of the social science textbook difficult. Which response is most suitable?","options":["Make students copy the chapter twice so that they become familiar with its language","Ask students to memorise the difficult words with their meanings before each chapter","Explain in the children's own language, add local stories and visuals, then return to the text","Skip the difficult chapters, since the children cannot follow them in any case"],"answer":2,"explanation":"Using the home language and local context as a bridge makes concepts accessible, after which the textbook becomes readable. Copying or rote vocabulary lists do not build understanding.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-844","question":"Many Class IX students in a Patna school memorise answers from guidebooks. Which assessment practice would best discourage this and promote thinking?","options":["Asking questions copied directly from the end of the textbook chapter, so that all are prepared","Banning guidebooks in school and checking bags regularly for copies","Giving more marks for longer answers, so that students write in more detail","Asking questions that apply concepts to new situations, local cases or source extracts"],"answer":3,"explanation":"When questions need application to unfamiliar contexts, memorised answers stop working and students must think. Banning guidebooks treats the symptom; textbook-copied questions reward the very habit to be changed.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-845","question":"Which of the following statements about good social science textbooks are correct?\n1. They present information in a way that invites questioning.\n2. They include open-ended activities that can be linked to the local context.\n3. They mark the boundary beyond which the teacher should not go, since examinations are set from them.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"A good textbook invites inquiry and adaptation to local contexts. It is a starting point; treating it as a fence that limits teaching is the textbook-centred culture NCF 2005 criticises.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-846","question":"A teacher says, 'The textbook is the curriculum; what is not in it is not my job.' What is the misconception?","options":["She is right, since the curriculum and the textbook are simply two names for the same thing","The curriculum is a wider plan of aims, content, methods and assessment; the textbook is one tool for it","The syllabus is broader than the curriculum, so she should follow the syllabus document instead of either","The textbook is actually broader than the curriculum, so she should teach even more from it than she does"],"answer":1,"explanation":"Curriculum includes goals, experiences, methods and evaluation; the syllabus lists content; the textbook is a resource that serves both. Equating the textbook with the curriculum narrows teaching to one book.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-847","question":"A Class VII teacher in Madurai finds that the textbook says little about the everyday life of people under the southern kingdoms of the period. What is the most suitable response?","options":["Teach only regional history, and drop the textbook chapters on other regions of the subcontinent","Ignore the gap, since the examination follows the textbook and extra material adds to the load","Add regional sources such as temple inscriptions, and link them to the textbook's larger story","Tell students that the southern kingdoms were less important, which is why they get less space"],"answer":2,"explanation":"Supplementing the textbook with regional material fills its gaps and makes history relevant, while linking back keeps the larger picture. Replacing the textbook with regional history or ignoring the gap are both one-sided responses.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-848","question":"Assertion (A): Including Dalit autobiographies as source extracts enriches the teaching of caste in Class VIII.\nReason (R): First-person accounts let students understand discrimination from the perspective of those who experienced it.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Autobiographies bring the experience of discrimination into the classroom in the voice of those who lived it, which a general description cannot. That is why they enrich the lesson; R explains A.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-849","question":"Which of these exercises best represents the voices of marginalised people in a Class VIII lesson on urban development?","options":["Reading a newspaper editorial that criticises the project on behalf of the city's poor","A role-play in which students imagine how a slum family feels about the project","Studying government data on how many families the project had to resettle","Interviewing a waste-picker or street vendor on how a city project affected work"],"answer":3,"explanation":"Only the interview lets marginalised people speak for themselves. The role-play and the editorial are tempting, but they speak about or for the poor through others' imagination or words, and resettlement data reduces people to numbers.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-850","question":"A Class 8 teacher hands out a model leave letter, has students underline its fixed phrases and sentence patterns, and then asks them to write a similar letter changing only the names, dates and reasons. Marks are given for how closely the letter follows the model without errors. This reflects the:","options":["Process approach, which values drafting, feedback and revision","Product approach, centred on accurately imitating a model text","Genre approach, which explores the social purpose of a text type","Whole language approach, which uses writing for real readers"],"answer":1,"explanation":"Analysing and imitating a model and judging the finished text for accuracy is the product approach. The genre approach also uses models, but focuses on purpose, audience and context and moves through joint construction.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-851","question":"A teacher shows Class 9 students several real complaint letters, discusses who writes them, to whom and why, and how they usually move from background to problem to request. She then writes one together with the class before students write their own. This approach is:","options":["The genre-based approach, linking text structure to social purpose","The product approach, since a model text is used throughout","The audio-lingual approach, since a fixed pattern is practised","The free-writing approach, since students then write their own letters"],"answer":0,"explanation":"The genre approach studies how a text type achieves its social purpose, then moves through modelling, joint construction and independent writing (the teaching–learning cycle).","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-852","question":"Which activity is an example of guided (rather than controlled or free) writing?","options":["Copying a paragraph from the board neatly, without making any change","Filling in blanks in a paragraph with words chosen from a given list","Writing about one’s village from a given outline and word bank","Writing about any topic of the learner’s own choice, with no help"],"answer":2,"explanation":"Guided writing gives support such as an outline, prompts or useful words but leaves learners to compose their own sentences. Copying and gap-filling are controlled; an open topic with no support is free writing.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-853","question":"A Class 5 child’s first draft about the day her goat ran away has an interesting story but many spelling mistakes. In a writing conference, the teacher’s best first response is to:","options":["Circle every spelling mistake in red so that she notices each one of them","Respond to the ideas first, e.g. ‘Tell me more about where you found her’","Give a mark out of ten so that she knows exactly how good the draft is","Ask her to copy the draft out again neatly before discussing anything"],"answer":1,"explanation":"In the process approach, early conferences focus on content and organisation; surface errors are handled later at the editing stage. Starting with red marks tells the child that only correctness matters.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-854","question":"A Class 8 teacher wants peer review of story drafts to be genuinely useful. The most effective step is to:","options":["Ask students to exchange notebooks and give each draft a mark","Let peers correct only spelling, since they know little about content","Give guiding questions and model how to give specific, kind feedback","Avoid peer review, since classmates know less than the teacher"],"answer":2,"explanation":"Without guidance peer feedback tends to be vague or limited to spelling. A short checklist and teacher modelling show students what to look for and how to comment helpfully.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-855","question":"Before writing on ‘The first rain’, Class 7 students write non-stop for five minutes, putting down whatever comes to mind without worrying about spelling or grammar. This technique mainly serves to:","options":["Produce a final draft quickly for display on the class board","Practise handwriting speed for the board examinations","Test how many spelling errors students make under pressure","Generate ideas and overcome the block of a blank page"],"answer":3,"explanation":"Freewriting is a pre-writing technique that releases ideas and builds fluency by suspending judgement; the material is later shaped through drafting and revision.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-856","question":"A teacher reads a short text twice at normal speed. Students jot down key words, then work in groups to rebuild the text so that it is as close as possible in meaning and grammar to the original, and compare versions. This technique is:","options":["Dictogloss","Traditional dictation","The cloze procedure","Précis writing"],"answer":0,"explanation":"In dictogloss learners reconstruct a text from notes through discussion, which integrates listening, speaking and writing and draws attention to grammar in context. Traditional dictation is word-for-word transcription.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-857","question":"Class 8 students are given a bar graph showing monthly rainfall in Cherrapunji and asked to write a paragraph describing what it shows. This activity develops:","options":["Free composition on a topic of the learner's own choice","Précis writing by shortening a long passage of text","Information transfer from non-verbal to verbal form","Paraphrasing a written text in simpler words of one's own"],"answer":2,"explanation":"Information transfer involves converting information between forms, here from a graph to prose, which requires interpreting data and choosing language to compare and describe.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-858","question":"A Class 6 teacher asks students to write about the school sports day three times: as a diary entry, as a notice for the board and as a report for the school magazine. The main learning aim is that students realise:","options":["A good piece of writing can be reused for any reader with no change","Notices and reports are less important than diary entries","Writing the same thing three times improves handwriting","Layout, content and language change with purpose and audience"],"answer":3,"explanation":"Comparing text types on one topic shows how purpose and audience shape format, level of formality and what is included.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-859","question":"Several Class 4 children cannot begin a story on their own. Their teacher gives them a sheet with ‘One day…’, ‘Then…’, ‘After that…’ and ‘In the end…’ as starters. This support is best described as:","options":["A writing frame that scaffolds structure and is withdrawn later","Controlled dictation in which the teacher supplies all the words","Copying practice that develops neat handwriting","A test that checks whether children already know linking words"],"answer":0,"explanation":"Writing frames give a skeleton of connectives and sentence starters, letting learners compose while seeing how a text is organised; the support is reduced as they gain confidence.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-860","question":"A Class 7 student writes in her notebook every week about whatever she likes, and the teacher replies in writing to what she says, without marking errors, though her replies naturally use correct forms. The main value of such a dialogue journal is that it:","options":["Lets the teacher grade each student's written grammar more often and more closely","Gives a real reader and purpose without anxiety, while correct forms are modelled","Replaces the need for any other kind of writing practice in the classroom","Gives the teacher a detailed record of each student’s private life at home"],"answer":1,"explanation":"Dialogue journals turn writing into genuine communication; students write more freely, and the teacher’s replies give implicit models of correct language without discouraging the writer.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-861","question":"A Class 7 paragraph titled ‘Why trees matter’ opens with a long description of a school picnic, and only the last sentence mentions trees. The teacher’s feedback should focus mainly on:","options":["Spelling, since several words in the paragraph are misspelt","Punctuation, since the sentences are long and run together","Unity: a clear topic sentence and relevant supporting sentences","Handwriting, since neat presentation strongly affects the reader"],"answer":2,"explanation":"A paragraph needs a controlling idea, usually in a topic sentence, with every other sentence supporting it. Surface matters can be handled after this larger problem.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-862","question":"Assertion (A): Using linking words such as ‘however’ and ‘therefore’ is enough by itself to make a piece of writing coherent. Reason (R): Coherence depends on the logical organisation and connection of ideas, not only on surface linking words.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Cohesive devices can be scattered through a text whose ideas still do not hang together; coherence comes from logical organisation of meaning, so A is false and R is true.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-863","question":"A Class 3 teacher gives a set of four pictures showing a boy, a kite, a tree and a ladder, and wants children to write a story. The most effective way to begin is to:","options":["Ask children to start writing at once, so that their ideas stay fully original","Talk about the pictures, build useful words on the board, then let them write","Give children a model story to copy beneath the pictures for practice","Teach the past tense rule thoroughly before even showing the pictures"],"answer":1,"explanation":"Oral discussion before writing builds ideas and vocabulary, so children have something to say and words to say it with. Copying a model removes composition altogether.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-864","question":"A Class 8 teacher shares the rubric for a descriptive essay (ideas, organisation, vocabulary, accuracy) with students before they begin writing. The main advantage is that it:","options":["Turns the essay into a test of memory rather than a test of writing","Means the teacher no longer needs to read the essays carefully","Ensures that every student will get the same mark for the essay","Makes criteria clear, so students can plan and check their own work"],"answer":3,"explanation":"Transparent criteria tell learners what quality looks like, guide their planning and revision, and support self- and peer assessment, a core idea of assessment for learning.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-865","question":"Instead of writing corrections, a teacher underlines errors in Class 9 compositions and writes codes such as ‘Sp’ (spelling), ‘T’ (tense) and ‘WO’ (word order) in the margin, and students correct their own work. The main aim is to:","options":["Promote self-correction and make learners notice their errors","Avoid giving any feedback that might upset or discourage students","Show students how many errors they made so they try harder","Reduce the time the teacher spends reading the compositions"],"answer":0,"explanation":"Indirect, coded feedback makes learners think about the rule involved and fix the error themselves, which builds awareness and responsibility more than receiving ready corrections.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-866","question":"For three weeks, a teacher’s written feedback on Class 6 stories focuses only on errors in past-tense verbs, the target of current lessons, and ignores most other errors. Which statement best supports her choice?","options":["Feedback on a few patterns is easier to act on than marking everything","Other errors do not matter, since only verbs really affect the meaning","Children should never be told about any error other than the tense taught","Ignoring errors always produces faster learning than correcting them"],"answer":0,"explanation":"Marking every error overwhelms learners and hides patterns. Selective, focused feedback on a target area helps them notice and fix it, while other areas are taken up in turn.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-867","question":"In a Class 2 classroom, most of the writing period is spent copying sentences from the board into notebooks. The main weakness of this practice is that it:","options":["Develops composition too early, before children can form their letters properly","Makes the children’s handwriting worse, since copying is done in a hurry","Builds handwriting but gives no chance to write down their own ideas","Is too difficult for Class 2 children and should wait until they reach Class 5"],"answer":2,"explanation":"Writing is composing meaning, not only forming letters. Copying has a place for handwriting, but children also need early chances to write their own messages, lists and stories.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-868","question":"Which writing task is the most authentic for Class 5 children?","options":["Writing out the memorised essay ‘My Cow’ from the guidebook for the unit test","Writing to the panchayat about the school's broken handpump, and sending it","Copying a model letter from the textbook neatly into the notebook","Filling in the blanks in an incomplete letter on a printed worksheet"],"answer":1,"explanation":"Authentic writing has a real purpose and a real reader, which gives children a reason to make their writing clear and correct. The other tasks are exercises with no actual audience.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-869","question":"Which statement about the process approach to writing is NOT correct?","options":["Writing is recursive: writers move back and forth between planning, drafting and revising","Feedback is given while the text is still being developed, not only at the end","Learners usually produce more than one draft of the same piece","The main emphasis is on the grammatical correctness of the final product"],"answer":3,"explanation":"The process approach shifts attention from the finished product to how writers generate, draft and revise ideas; correctness matters but is handled at the editing stage.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-870","question":"Four pre-school children are asked to write ‘kite’. P draws wavy lines; Q writes ‘KT’; R writes a random string ‘AOTMB’; S writes ‘kite’. Arrange them from the earliest to the most advanced stage of writing development.","options":["P, Q, R, S","P, R, Q, S","R, P, Q, S","P, R, S, Q"],"answer":1,"explanation":"Children move from scribbles to random strings of letters (no sound link), then to invented spelling that records some sounds (‘KT’), and then to conventional spelling.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-871","question":"In a ‘running dictation’, a short text is pinned on the wall; one partner runs to it, reads and remembers a chunk, returns and dictates it, and the other partner writes it down. Which skills does this activity practise?","options":["Reading, speaking, listening and writing together","Only listening and writing, since one partner dictates","Only reading and writing, since the text is read and copied","Only writing, since the outcome is a written text"],"answer":0,"explanation":"The runner reads and speaks, the writer listens and writes, and partners often switch roles, so all four skills are integrated in one lively activity.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-872","question":"Which prompt is most likely to encourage creative, original writing from Class 6 students?","options":["‘Write ten lines on the school bell, in your best handwriting.’","‘Copy and complete the given paragraph on the school bell.’","‘If the school bell could talk, what would it say about our day?’","‘Describe the school bell in five sentences, using the words given below.’"],"answer":2,"explanation":"An imaginative prompt invites a fresh point of view and divergent ideas, whereas the others lead to predictable, formulaic or controlled writing.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-873","question":"A teacher marks only the final version of each composition with a grade and brief comments. Students look at the grade and put the work away. Which change would make her feedback most useful for learning?","options":["Displaying only the best compositions on the class board as models","Writing much longer, more detailed comments on the final version only","Replacing the comments with a percentage score for each piece","Giving feedback on drafts while students can still use it to revise"],"answer":3,"explanation":"Feedback improves writing when learners can act on it. Comments on drafts during the process are used; comments on a finished, graded piece are mostly ignored.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-874","question":"A Class 4 child in Manipur cannot yet write a story in English but writes vividly in Meitei. Her teacher lets her plan and draft in Meitei and then helps her write the story in English. Which statement best supports this practice?","options":["It is unhelpful, since thinking in Meitei will slow down her progress in English","It should be stopped once she reaches Class 5, whatever progress she has made by then","It is acceptable only for children with a learning disability, not for others","Planning skills transfer across languages, and using Meitei reduces the load"],"answer":3,"explanation":"Composing skills are shared across languages (Cummins’ common underlying proficiency), and planning in the stronger language frees attention for expressing ideas in English, a translanguaging practice.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-875","question":"An older EVS workbook used in a school shows a woman cooking while a man reads the newspaper. The most appropriate way for the Class 3 teacher to use this picture is to:","options":["skip the page, so that children do not notice the stereotype and pick it up","tell children that the picture shows how most families organise their work","ask children who does which work in their homes, and whether it could be different","replace the picture with one showing only men at work, both in the home and outside"],"answer":2,"explanation":"Turning the picture into a discussion makes children notice and question gender roles. Skipping hides the issue, and swapping in another one-sided picture repeats the problem.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-876","question":"The NCERT EVS books deliberately show girls climbing trees, men cooking and women driving vehicles. The main purpose is to:","options":["challenge gender stereotypes and widen what children think anyone can do","make the illustrations look modern and attractive to young readers","show that household work is unimportant compared with outside work","suggest that men should do housework instead of outside work"],"answer":0,"explanation":"Counter-stereotypical images are a conscious choice to question fixed gender roles. They do not devalue household work or reverse roles.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-877","question":"Consider these statements about gender sensitivity in an EVS classroom: I. Always asking girls to sweep and boys to lift benches reinforces stereotypes. II. Gender sensitivity means treating girls as weaker and keeping them away from difficult activities. III. Discussing who does unpaid work at home helps children see the value of that work. Which are correct?","options":["I only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Fixed chores reinforce roles, and discussing unpaid work makes it visible. ‘Protecting’ girls from activities is itself a stereotype, so II is wrong.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-878","question":"After reading an EVS story about a visually challenged child who plays chess, a teacher has children cover their eyes and identify objects by touch and smell, and then discuss the experience. The main aim is to:","options":["test which children have the sharpest sense of touch and smell in the class","show children that people with disabilities need our pity and help in everything they do","practise the names and uses of common objects found in the classroom","build empathy and respect for how people with disabilities use other abilities"],"answer":3,"explanation":"The activity moves children from pity to understanding and respect for different abilities. It is not a test of senses or a vocabulary drill.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-879","question":"During a lesson on water, a Class 4 girl says that on some days she misses school because she has to fetch water. The teacher’s best response is to:","options":["tell her that school must come first, and that she should simply refuse to fetch water on school days","discuss why the task falls on girls and how it affects schooling, and raise it with parents and SMC","say nothing in class, since it is a family matter that the school has no part in","mark her absent and inform the head teacher about her irregular attendance for action"],"answer":1,"explanation":"The girl’s experience reveals a gendered burden; EVS aims to help children understand such realities, and the teacher can also work with the community. Ignoring or blaming her helps no one.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-880","question":"Assertion (A): EVS should take up issues such as child labour and caste discrimination even at the primary level. Reason (R): Many children directly experience these realities, and EVS aims to develop concern for justice and equality. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCF 2005 wants EVS to connect with children’s real lives, including unjust ones, and to build sensitivity and concern. R gives exactly that reason.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-881","question":"Asked to draw ‘a family’, nearly every Class 3 child draws a father, a mother and two children. The teacher’s best next step is to:","options":["praise the drawings, since a father, mother and two children is the ideal family","ask children to add grandparents, so that every drawing shows a proper joint family","share stories and pictures of many kinds of families, such as single-parent ones, and discuss them","tell children their drawings are wrong, because most families in India are bigger than this"],"answer":2,"explanation":"Children draw the image they see everywhere. Exposure to the real variety of families widens the idea and makes children from other families feel included; no form should be called ‘ideal’ or ‘wrong’.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-882","question":"In every EVS activity a teacher says, ‘Boys, bring the soil; girls, decorate the chart.’ This is best described as:","options":["efficient division of labour suited to children’s abilities","a neutral classroom routine with no effect on learning","a reflection of children’s natural interests","the hidden curriculum transmitting gender stereotypes"],"answer":3,"explanation":"Routine messages that are never stated as lessons still teach children ‘what boys and girls do’. Assuming natural interests is the stereotype itself.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-883","question":"During the mid-day meal, some Class 4 children refuse to sit next to a classmate because of her caste. The teacher’s best response is to:","options":["make sure all children eat together, and discuss equality and dignity with them and their parents","seat the classmate separately for now, so that the meal goes on without any conflict","ignore it, since it is a matter of family belief that the school should not interfere in","punish the children who refused, without any discussion, so that it does not happen again"],"answer":0,"explanation":"Untouchability is prohibited by the Constitution, and EVS seeks concern for equality; the teacher must act and also help children and parents rethink. Separate seating endorses the discrimination.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-884","question":"A Class 5 boy notices that the girls’ toilet in the school has no water and raises it in the class meeting, asking that it be fixed. In NCERT’s list of EVS learning indicators, this behaviour mainly shows:","options":["Observation and recording","Cooperation","Concern for justice and equality","Experimentation"],"answer":2,"explanation":"Sensitivity to an unfair situation faced by others, and speaking up about it, is concern for justice and equality. Noticing alone would be observation, but the concern and action go further.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-885","question":"Some Class 4 children call a classmate from Manipur ‘Chinese’. The teacher’s most appropriate response is to:","options":["ignore it, since children say such things casually and do not really mean any harm by them","address it at once, discuss how it hurts and how diverse India is, and learn about Manipur together","move the child from Manipur to another section where she is less likely to be teased","tell the child from Manipur not to mind such jokes, since they will soon stop if she simply ignores them"],"answer":1,"explanation":"Such labels deny a child her identity and belonging. Addressing them immediately and building knowledge about the North-East is what EVS sensitivity requires.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-886","question":"A Class 4 child with low vision is in an EVS class. Which adaptation is LEAST appropriate?","options":["Using real objects and tactile models that she can handle and explore","Giving her large-print material and seating her close to the board","Pairing her with a peer who describes what is seen during observation tasks","Exempting her from all observation activities so that she is not burdened"],"answer":3,"explanation":"Inclusion means adapting the task, not removing the child from it; observation can use touch, sound and smell. Exemption denies her the learning.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-887","question":"While discussing an EVS story about a girl who works at a tea stall, a Class 5 child says, ‘My cousin works at a dhaba because his family needs money.’ The teacher should best:","options":["acknowledge it without shaming anyone, and discuss every child's right to school and the help available","tell the child that his family is breaking the law and must be reported to the authorities","change the topic quickly, since it is a personal matter that may embarrass the child","ask the child to bring his cousin to school the next day to talk to the class about his work"],"answer":0,"explanation":"The aim is understanding and concern, not blame. Talking about rights and support, without shaming a family in hardship, keeps the child safe and the discussion honest.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-888","question":"In a lesson on ‘Work and Play’, which question best helps Class 3 children reflect on gender?","options":["Name five games played in different parts of India, and say where each is played.","Which game do you like best, and what do you enjoy most about playing it?","Which games do boys and girls play in your area? Are some games not allowed for girls? Why?","How many players are there in a kabaddi team, and how is the game scored?"],"answer":2,"explanation":"Only this question asks children to notice and question a gendered pattern in their own lives. The others ask for lists, preferences or facts.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-889","question":"A teacher believes that ‘being sensitive’ means not talking about poverty, caste or gender in EVS, so that no child feels uncomfortable. The best critique of this view is that:","options":["such topics should be left to secondary school social science, when children are older","avoiding them leaves prejudice unchallenged; the aim is to take them up with care so all feel respected","children at this age are not affected by these issues and do not notice them at all","the view is correct, since EVS should deal only with nature, plants, animals and the wider physical environment"],"answer":1,"explanation":"Silence protects existing prejudice; NCF 2005 asks EVS to address social realities sensitively. EVS is not limited to nature.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-890","question":"In a discussion on ‘Shelter’, a Class 4 child mentions that her family sleeps on the footpath near the railway station. The teacher should:","options":["ask her to describe her life in detail to the whole class, as a real-life example","tell the class that people without homes have usually not worked hard enough","quickly change the subject, so that she is spared any embarrassment in front of her classmates","ensure no one mocks her, and discuss why some people lack homes, without singling her out"],"answer":3,"explanation":"Sensitivity means protecting the child’s dignity while helping the class understand homelessness as a social issue. Making her an exhibit or silencing her both harm her.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-891","question":"Assertion (A): An EVS teacher should actively encourage girls to take part in experiments and outdoor fieldwork. Reason (R): Girls are naturally less interested in science than boys. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Encouraging girls counters social barriers, but there is no natural difference in interest; such gaps are produced by stereotypes and opportunity. R is false.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-892","question":"Match each term with its example: 1. Stereotype 2. Prejudice 3. Discrimination 4. Inclusion. a. Refusing a child a seat because of her community. b. Believing that all girls are poor at using tools. c. Disliking a group without knowing any of its members. d. Planning an activity so that every child, including one with a disability, can take part.","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d","1-b, 2-c, 3-a, 4-d"],"answer":3,"explanation":"A stereotype is a fixed generalisation (b), prejudice is a negative attitude (c), discrimination is unfair action (a), and inclusion is planning for everyone’s participation (d).","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-893","question":"While reviewing an old EVS chart, a teacher finds that all the doctors shown are men and all the nurses are women. The best use of the chart is to:","options":["ask whether this is always so, and share examples of women doctors and men nurses","throw it away quietly and never mention it, so that children are not exposed to the bias","use it as it is, since it shows the usual pattern seen in most hospitals","tell children that this shows which jobs suit men and which suit women"],"answer":0,"explanation":"Using biased material critically teaches children to read pictures with a questioning eye and to see counter-examples. Discarding it silently loses that chance.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-894","question":"After reading about how Gandhiji asked everyone to clean toilets in his ashram, a Class 5 teacher plans the school cleaning duties. The practice most in line with the spirit of the lesson is to:","options":["give cleaning duties to children whose families already do such work","ask only the girls to clean, since they are usually neater and more careful","rotate cleaning duties among all children, regardless of caste or gender","leave all cleaning to the school sweeper, so that children can study"],"answer":2,"explanation":"Rotating duties among everyone puts dignity of labour into practice and breaks caste and gender links with cleaning. The other options reinforce those links.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-895","question":"A Class 5 teacher plans a household survey on toilets and sanitation. Some children’s families have no toilet at home. The teacher should:","options":["drop the survey altogether, since the topic may embarrass some of the children","keep individual answers private, and discuss patterns in the community and their reasons","read out each child's answer in class, so that the class gets complete and accurate data","ask only children from families with toilets to take part, so that nobody is embarrassed"],"answer":1,"explanation":"Sensitive surveys protect privacy while still letting children analyse social issues. Public exposure shames children; dropping or restricting the survey loses learning.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-896","question":"A Class 3 teacher plans a chart with two columns: ‘Mother’s work’ and ‘Father’s work’. A more sensitive way to frame the same activity is:","options":["‘Work done by women’ and ‘Work done by men’","‘Easy work’ and ‘Hard work’","‘Indoor work’ and ‘Outdoor work’","‘Who does what work in your family?’"],"answer":3,"explanation":"The open question does not assume that roles are fixed by gender or that every family has a mother and a father. The other frames still sort work in assumed or ranked categories.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-897","question":"Which of the following are in line with NCF 2005’s view of EVS? I. It should reflect diverse lives, including those of marginalised groups. II. It should present the urban middle-class family as the normal family. III. It should allow children to question unfair practices around them.","options":["I and III only","I and II only","II and III only","I, II and III"],"answer":0,"explanation":"NCF 2005 asks for diversity and critical engagement with injustice; treating one kind of family as normal excludes many children, so II is wrong.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-898","question":"Which observation best shows ‘concern for justice and equality’ in a Class 4 child?","options":["She draws a very neat and detailed chart of the animals found near her home, labelling each one","She asks many thoughtful questions about how different birds build their nests and from what","In a game, she makes sure a classmate in a wheelchair gets a role, changing the rules so he can play","She correctly sorts a large collection of leaves into groups by their shapes"],"answer":2,"explanation":"Acting so that a disadvantaged peer is included is the core of this indicator. The others show recording, questioning and classification.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-899","question":"In the ‘Food’ theme, Class 5 children ask why some people do not get enough to eat when farmers grow so much grain. The best way for the teacher to handle this is to:","options":["explain that people who are poor usually do not work hard enough to buy enough food","open an inquiry into causes such as income, storage and distribution, and schemes like ration shops","tell children the question is too complex for their age and will be taken up later","ask children to donate food to the needy and close the discussion on a positive note"],"answer":1,"explanation":"The question invites real analysis of a social issue; exploring causes and public schemes builds understanding without blaming the poor. Brushing it aside or reducing it to charity stops the thinking.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-900","question":"Match each misconception with the activity best suited to challenge it. P. A bulb uses up current  Q. Plants get their food from the soil  R. Heavier objects fall faster  S. A sweater produces heat. 1. Keeping a thermometer inside a folded sweater for an hour  2. Placing identical ammeters on both sides of a bulb  3. Discussing van Helmont's willow tree experiment  4. Dropping two balls of the same size but different mass together","options":["P-2, Q-3, R-4, S-1","P-2, Q-4, R-3, S-1","P-1, Q-3, R-4, S-2","P-3, Q-2, R-4, S-1"],"answer":0,"explanation":"Equal ammeter readings counter 'used-up current'; the willow gaining mass from almost no soil counters 'food from soil'; equal fall times counter 'heavier falls faster'; an unchanged thermometer counters 'sweater produces heat'.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-901","question":"How many of the following are integrated (not basic) science process skills? Controlling variables, interpreting data, classifying, formulating models, measuring.","options":["Two","Four","Three","Five"],"answer":2,"explanation":"Controlling variables, interpreting data and formulating models are integrated process skills. Classifying and measuring are basic process skills.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-902","question":"After an investigation supports her hypothesis, a Class 8 student writes, 'My experiment has proved my hypothesis true for ever.' The teacher should help her understand that:","options":["One supporting experiment is enough to turn a hypothesis into a scientific law","Evidence can support a hypothesis, but further tests could still challenge it","A hypothesis can never be supported by an experiment, so her result means nothing","Her experiment proved nothing because school experiments are not real science"],"answer":1,"explanation":"Scientific claims are tentative: supporting evidence increases confidence, but new evidence may require revision. Calling it proved for ever ignores this, and dismissing school experiments is equally wrong.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-903","question":"Two Class 8 students look at the same onion peel slide under a microscope. One reports 'brick-like cells with a dark dot in each'; the other, who has never seen cells, reports 'some lines and bubbles'. This best illustrates that:","options":["The second student's microscope was not focused or working properly","The first student must have copied the description from the textbook","Observations are shaped by what the observer already knows and looks for","Microscopes give slightly different images to the different people looking through them"],"answer":2,"explanation":"Observation is not purely passive; knowing what cells and nuclei look like guides what one notices and how one describes it. Teachers therefore need to guide observation, not just say 'look'.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-904","question":"A student brings a phone message claiming that 'drinking hot water every hour cures all infections'. The teacher uses it in class. Which line of questioning best develops students' scientific thinking?","options":["'Who sent the message? If it came from someone older and educated, it must be true.'","'How many people have shared it? If so many have shared it, it must surely be true.'","'Does it sound sensible to us? If it does, we can safely accept it as true without checking.'","'What evidence supports it? Was it compared with people who did not drink hot water?'"],"answer":3,"explanation":"Scientific thinking judges claims by evidence and fair comparison, not by authority, popularity or plausibility. This builds the media literacy that science education should give citizens.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-905","question":"Consider these statements about the 5E model. 1. The Engage phase should bring out students' prior ideas and raise curiosity. 2. In the Explore phase, the teacher first gives formal definitions for students to verify. 3. The Explain phase builds on what students experienced during exploration. 4. Assessment can happen throughout, though the Evaluate phase formally checks understanding. Which are correct?","options":["1, 3 and 4 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"In 5E, formal explanations come after exploration, so statement 2 reverses the model. The others correctly describe Engage, Explain and the role of assessment.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-906","question":"Which opening is most suitable for the Engage phase of a Class 8 lesson on rusting?","options":["Writing the chemical equation for rusting on the board for students to copy","Asking why people paint iron gates before the monsoon, and showing a rusted and a new nail","Dictating the definition of rusting and the methods of its prevention","Giving a short test on the previous chapter to check what students remember"],"answer":1,"explanation":"Engage should connect to everyday experience and raise a question worth investigating. An equation or definition at the outset belongs, if at all, to the Explain phase.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-907","question":"In which of the following situations is the lecture-cum-demonstration method more suitable than individual laboratory work? 1. Only one set of costly apparatus is available. 2. The aim is to develop each student's skill in handling apparatus. 3. The experiment involves a hazard. 4. The class is large and time is short.","options":["1 and 2 only","2 and 4 only","1, 2, 3 and 4","1, 3 and 4 only"],"answer":3,"explanation":"Demonstrations suit costly, scarce or hazardous experiments and situations with large classes and little time. Developing each student's manipulative skill requires students to handle the apparatus themselves.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-908","question":"Which objective of science teaching can be achieved only poorly through teacher demonstrations and needs students to do laboratory work themselves?","options":["Developing skill in handling apparatus and taking accurate readings","Arousing interest and curiosity at the start of a new topic","Showing a hazardous reaction safely to the whole class","Saving time and material when apparatus is limited or costly"],"answer":0,"explanation":"Manipulative skills are developed only through one's own practice with apparatus. The other aims are in fact strengths of the demonstration method.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-909","question":"During a class debate on farmers burning crop stubble, students hold sharply different views. The most appropriate role for the science teacher is to:","options":["Tell students the right opinion, so that the debate ends quickly and no one is confused","Avoid the topic altogether, since it is controversial and may upset some families","Ensure evidence from different perspectives is examined and students give reasons for their views","Let students say whatever they like, without asking for evidence, so that all feel heard"],"answer":2,"explanation":"For socio-scientific issues the teacher facilitates evidence-based reasoning across perspectives (farmers' costs, air quality, health), rather than imposing her own view or leaving claims unexamined.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-910","question":"While teaching the rotation of the earth, a teacher tells Class 7 how Aryabhata proposed that the earth spins on its axis, and how this idea was received and debated in later centuries. This element of the lesson mainly serves:","options":["Ethical validity","Environmental validity","Cognitive validity","Historical validity"],"answer":3,"explanation":"Showing how an idea was proposed, debated and accepted over time gives a historical perspective on science, which is historical validity.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-911","question":"Before introducing the word 'force', a Class 6 teacher lets students push and pull objects in games such as tug-of-war and football and describe what happens to them. This choice is based mainly on:","options":["Content validity, since force must first be defined accurately before it is used in games","Cognitive validity, since concepts should grow from experiences children can handle","Ethical validity, since team games teach cooperation and fair play","Historical validity, since such games have been played for centuries"],"answer":1,"explanation":"Starting from concrete experience suited to the learner's level before formal terms is the essence of cognitive validity at the upper primary stage.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-912","question":"Which simplified statement for a Class 6 chapter on magnets still keeps content validity?","options":["Magnets attract all metals, such as iron, copper and aluminium, but not plastic or wood.","Magnets attract some materials, such as iron and nickel, but not others, such as copper.","A magnet's attraction works only on objects that are actually touching it.","Breaking a bar magnet in two gives one piece with a north pole and one with a south pole."],"answer":1,"explanation":"A simplification is valid if it is incomplete but not wrong. 'Attracts all metals', 'only on contact' and separate poles on breaking are all common misconceptions; each broken piece has both poles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-913","question":"A teacher plans remedial classes for all 'slow learners' in science, giving them the same worksheet without first finding out what each of them finds difficult. The main flaw in this plan is that:","options":["Remedial teaching should be given to all students in the class, not only to slow learners","Worksheets should never be used in remedial teaching, only oral explanation","Remedial teaching must rest on diagnosing each learner's specific difficulties","Slow learners should be taught only through lectures, not through worksheets"],"answer":2,"explanation":"Diagnosis precedes remediation: different learners struggle for different reasons, so a single worksheet may miss their actual difficulties.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-914","question":"In a Class 7 class, students who understood the concept of conduction explain it to classmates who are struggling, using their own words and examples. As a remedial strategy this is useful mainly because:","options":["It lets the teacher rest while students take charge of teaching each other","It is the only practical way to deal with very large classes in schools","It removes the need for the teacher to diagnose each struggling learner's difficulties","Peers often explain in words and examples closer to struggling learners' thinking"],"answer":3,"explanation":"Peer tutoring works partly because peers share a similar frame of reference; it also deepens the tutor's own understanding. It complements, not replaces, the teacher's diagnosis.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-915","question":"Assertion (A): A well-designed open-book test in science can assess higher-order thinking. Reason (R): Its questions require students to apply and analyse information rather than simply locate it in the book.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because the information is available, a well-designed open-book test must ask students to use it, which is what lets it assess application and analysis rather than recall.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-916","question":"A teacher asks Class 8 students to design a method of keeping drinking water cool in summer without a refrigerator, using only local materials. In the revised Bloom's taxonomy, this task is mainly at the level of:","options":["Remembering","Applying","Creating","Understanding"],"answer":2,"explanation":"Designing a new product or plan is creating, the highest level of the revised taxonomy. Applying would be using a known procedure in a familiar situation.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-917","question":"A teacher shows a magnet picking up iron nails, pins and a steel spoon, and the class concludes that 'magnets attract all metals'. What should the teacher have done to prevent this over-generalisation?","options":["Used a stronger magnet, so that the attraction was clearer to the whole class","Included non-examples such as a copper coin, aluminium foil and a brass key","Told students the definition of magnetic materials before the demonstration","Shown more iron objects, so that the pattern was clearer and more convincing"],"answer":1,"explanation":"Concepts form from both examples and non-examples. Showing only iron-based objects invites the wrong rule; non-magnetic metals mark the true boundary of the concept.","difficulty":"hard","source":"CTET Paper 2 · DSSSB · state TETs"},
  {"id":"cdp-pedagogy-subjects-918","question":"A Class 6 teacher wants her students to classify materials around them. Which instruction best develops the skill of classification?","options":["Copy the table of materials from the textbook and learn the groups it shows","Group the objects any way you like, name the property used, then regroup by another","Put all the shiny objects in one place and all the dull objects in another","Write the names of ten materials found at home and say what each one of them is used for"],"answer":1,"explanation":"Real classification means choosing a property, grouping consistently by it, and seeing that the same objects can be grouped differently by different properties. Copying or following a single given rule does not develop the skill.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-919","question":"While teaching sources of energy, a teacher asks students to survey which fuels are used in their homes, why, and with what effects on health and money, and then to discuss what alternatives are available locally. This approach is best called:","options":["Lecture-cum-demonstration approach","Rote memorisation approach","Programmed instruction approach","Science-Technology-Society approach"],"answer":3,"explanation":"Starting from a real-life issue in the learners' community and linking scientific ideas to technology and social effects is the STS approach.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-920","question":"A teacher notices that in her classes, the same three students answer every question while the rest stay silent. Which strategy is most likely to involve the whole class in thinking about a science question?","options":["Asking only the three students, since they usually know the answers","Letting students think alone, discuss in pairs, then share with the class","Asking the question and then answering it herself after a short pause","Punishing students who do not answer, so that all of them pay closer attention"],"answer":1,"explanation":"Think-pair-share gives every student time to think and a low-risk chance to voice ideas before speaking to the whole class. Relying on volunteers or punishment shrinks participation.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-921","question":"A student says that a bigger magnet is always stronger than a smaller one. The best way to address this is to:","options":["Agree with the student, since size and strength of magnets generally go together","Tell the student to read the chapter on magnets again more carefully","Have students compare how many pins magnets of different sizes and kinds can lift","Show the student a picture of a large magnet lifting a heavy load"],"answer":2,"explanation":"Testing the claim with evidence, for instance a small strong magnet lifting more pins than a large weak one, lets students discover that strength does not depend on size alone.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-922","question":"Consider these practices of a Class 7 science teacher. 1. She asks students to explain their reasoning even when their answer is correct. 2. She treats wrong answers as clues to students' thinking. 3. She tells students that every question has exactly one right answer given in the textbook. 4. She encourages students to question each other's explanations politely. Which practices support conceptual understanding?","options":["1, 2 and 4 only","1 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Asking for reasoning, using errors diagnostically and encouraging respectful argument all help build understanding. Treating the textbook as the only authority discourages thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-923","question":"A Class 8 teacher finds that students easily state that 'friction opposes motion' but believe that friction is always harmful. Which teaching move best corrects the second idea?","options":["Repeating the definition of friction several times until students know it well","Listing ways to reduce friction in machines, such as oiling and ball bearings","Telling students to memorise a list of the advantages of friction for the coming unit test","Let students walk on a soapy floor and write on glass, and discuss what friction allows"],"answer":3,"explanation":"Experiencing how hard walking and writing become with little friction shows that friction is necessary as well as wasteful. Memorised lists rarely change a belief.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-924","question":"A science teacher wants to judge whether her students can transfer the idea of conduction to new situations. Which question is most suitable?","options":["Define conduction and give one example of it from the textbook.","Name two good conductors and two poor conductors of heat.","Why do cooks hold a hot pan with a folded cloth rather than with bare hands?","Draw a labelled diagram showing conduction of heat in a metal rod."],"answer":2,"explanation":"Explaining an unfamiliar, everyday case requires students to apply the concept (cloth is a poor conductor, so it slows heat flow to the hand). Definitions, lists and textbook diagrams can be recalled.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-925","question":"After studying two water-saving schemes in their village, Class VII students in Sikar are asked: 'Which of the two schemes would you recommend to the gram panchayat, and why?' In Bloom's revised taxonomy, this question is mainly at the level of:","options":["Analyse","Create","Apply","Evaluate"],"answer":3,"explanation":"Judging between options against criteria and justifying a recommendation is Evaluate. Analysing would stop at breaking the schemes into parts and comparing them; nothing new is being designed, so it is not Create.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-926","question":"A Class V teacher asks four questions about a fable: P. 'Write a new ending in which the crow outsmarts the fox.' Q. 'Was it fair of the fox to trick the crow? Give reasons.' R. 'How are the fox's reasons for flattering different from the crow's reasons for singing?' S. 'What was the crow holding in its beak?' Arrange them from the lowest to the highest level of Bloom's revised taxonomy.","options":["S, R, Q, P","S, Q, R, P","S, R, P, Q","R, S, Q, P"],"answer":0,"explanation":"S is Remember, R is Analyse (comparing motives), Q is Evaluate (judging fairness) and P is Create (producing something new). In the revised taxonomy Create sits above Evaluate.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-927","question":"Consider the following statements about the revision of Bloom's taxonomy by Anderson and Krathwohl (2001): 1. The cognitive categories are named with verbs such as remember, understand and apply. 2. Synthesis was renamed Create and placed at the highest level, above Evaluate. 3. A separate knowledge dimension was added with factual, conceptual, procedural and metacognitive knowledge. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":2,"explanation":"All three are features of the revised taxonomy: nouns became verbs, Create replaced Synthesis at the top, and the two-dimensional taxonomy table pairs cognitive processes with four types of knowledge.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-928","question":"While revising for a test, Class VIII student Tanvi realises, 'I always mix up area and perimeter, so I will check the units of every answer before writing it.' In the knowledge dimension of Bloom's revised taxonomy, this is an example of:","options":["Procedural knowledge","Metacognitive knowledge","Conceptual knowledge","Factual knowledge"],"answer":1,"explanation":"Knowing one's own typical errors and choosing a strategy to monitor them is metacognitive knowledge. The checking steps might look procedural, but the source is awareness of her own thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-929","question":"A Class VI task says: 'Use the steps of long division to divide 4,356 by 12.' In the two-dimensional table of Bloom's revised taxonomy, this task fits best at:","options":["Understand x Conceptual knowledge","Remember x Factual knowledge","Analyse x Procedural knowledge","Apply x Procedural knowledge"],"answer":3,"explanation":"Carrying out a known algorithm on a familiar type of problem is Apply (executing), and the knowledge involved is the method itself, which is procedural.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-930","question":"Assertion (A): After asking a thinking question, a teacher should wait at least three seconds before calling on a student. Reason (R): Longer wait time has been found to increase the length and quality of student answers and the number of students who respond.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Mary Budd Rowe's research on wait time found that pausing about three seconds or more produced longer, better-reasoned answers and more participation; that is the reason for A.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-931","question":"After a Class IV child answers, the teacher does not immediately say 'Good' or 'Wrong' but pauses silently for a few seconds. The child then adds an example, and another child builds on it. What is this pause called and what does it achieve?","options":["Wait time after the question; it gives children time to frame an answer before anyone is called","Planned ignoring; it discourages children from giving attention-seeking answers","Wait time after the response (wait time II); it invites elaboration and lets others respond","Redirecting; it shifts the question silently to another student to answer"],"answer":2,"explanation":"Wait time II is the pause after a student's answer; it keeps thinking open so the student elaborates and peers join in. Wait time I is the pause after the teacher's question.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-932","question":"Which of these questions in a Class V EVS lesson is most clearly a divergent question?","options":["Which gas do plants take in from the air during photosynthesis?","What might happen to our town if all the roadside trees were cut down?","How many legs does an insect have, and how many body parts?","Name the river that flows through our city and where it begins."],"answer":1,"explanation":"Divergent questions have many acceptable answers and invite imagination and reasoning about possibilities. The others have one correct answer and are convergent.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-933","question":"Match each teacher move with the questioning technique it shows. P. 'Can you tell me more about why you think so?' Q. 'Neha, do you agree with Ravi's answer?' R. 'Think about what happens to ice when you keep it in the sun...' S. Asking the question to the whole class, pausing, and only then naming a student. Techniques: 1. Prompting; 2. Probing; 3. Redirecting; 4. Pose-pause-pick (keeping the whole group alert).","options":["P-1, Q-3, R-2, S-4","P-2, Q-4, R-1, S-3","P-3, Q-2, R-1, S-4","P-2, Q-3, R-1, S-4"],"answer":3,"explanation":"Probing pushes a student to go deeper, redirecting passes the question to another student, prompting gives a hint to a stuck student, and pose-pause-pick keeps everyone thinking until a name is called.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-934","question":"A Class VI teacher usually says the student's name first and then the question: 'Rahul, what is the capital of Odisha?' Why is this a weaker practice than asking the question first?","options":["Naming a student first tells the rest they are not being asked, so they may stop thinking","It is impolite to use a student's name in class before asking a question","It makes the question too easy for the named student, who gets extra time","It takes longer than asking the question first, which wastes class time"],"answer":0,"explanation":"Posing the question to all, pausing and then naming someone keeps every student mentally engaged. Naming first lets everyone else switch off.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-935","question":"In a Class IV English lesson, which teacher question is a referential question that invites real communication rather than a display question?","options":["'What colour is the bus in the picture?'","'What is the past tense of go?'","'What did you do with your family last Sunday?'","'Who wrote this poem? It is written below the title.'"],"answer":2,"explanation":"A referential question asks for information the teacher does not already know, so the child has something real to say. Display questions only check known answers.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-936","question":"A Class VII teacher writes a test item: 'List three differences between a plant cell and an animal cell.' The three differences were listed in a table in the textbook and copied in notes. At which level of Bloom's revised taxonomy is this item really working?","options":["Analyse, because students must compare two kinds of cells and find differences","Remember, because students only recall a list they have already studied","Evaluate, because students must judge which differences are the most important","Create, because students produce their own list of differences in the answer"],"answer":1,"explanation":"The level of a question depends on what students must actually do; if the comparison was already made and taught, recalling it is Remember. It would be Analyse only if students had to work out the differences themselves.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-937","question":"A Class VIII science teacher gives this task: 'Plan an experiment to find out whether the amount of sunlight affects how fast moong seeds sprout. Say what you will change, what you will keep the same and what you will measure.' At which level of Bloom's revised taxonomy is this task?","options":["Create","Apply","Understand","Remember"],"answer":0,"explanation":"Designing an investigation that did not exist before is planning, which falls under Create. It is not just Apply, because students are not carrying out a given procedure but devising one.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-938","question":"A Class VII student says that heavier objects always fall faster. Instead of correcting him, the teacher asks: 'If you tie a heavy stone and a light stone together, should the pair fall faster or slower than the heavy stone alone? Why?' What is the main purpose of this style of questioning?","options":["To embarrass the student into silence so that the lesson can continue as planned","To check whether the student remembers the textbook definition and the law of gravity","To lead the student to examine his own assumption and find the contradiction in it","To redirect the question to another student who may know the correct answer"],"answer":2,"explanation":"Socratic questioning uses a chain of questions that makes the learner test his belief and notice where it breaks, so understanding is built rather than told. It is not a recall check or a redirection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-939","question":"During a Class III lesson on vegetables, a child asks, 'Why do onions make us cry?' The question is not part of the plan. What is the best response?","options":["Tell the child to ask only questions about the lesson, so that the class stays on track","Ignore the question and continue, so as not to lose time from the planned lesson","Give the full scientific explanation at once, even if the lesson is delayed by half an hour","Welcome the question, note it on the class question wall, and explore it together later"],"answer":3,"explanation":"Children's own questions show curiosity, which NCF wants to nurture; recording and returning to them values the question without derailing the lesson. Dismissing questions teaches children to stop asking.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-940","question":"After explaining fractions, a Class IV teacher asks, 'Did everyone understand?' Most children say 'Yes', yet many fail a later task. What is the most useful change to her questioning?","options":["Ask 'Did everyone understand?' twice, and more firmly, to make sure of the answer","Ask children to show or explain, e.g. 'Fold this paper to show three-quarters and say why'","Ask only the best students to confirm that they understood, as they speak honestly","Give the class a written test every day so that gaps show up in the marks"],"answer":1,"explanation":"Yes/no questions about understanding are unreliable because children say 'yes' to avoid embarrassment. Asking them to show or explain gives real evidence of understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-941","question":"A Class VI teacher asks a challenging question, waits two seconds and, hearing no answer, gives the answer herself. This happens several times each period. What is the most likely long-term effect?","options":["Students learn that the teacher will supply the answer, so they stop thinking","Students' scores improve, because they hear the correct answers more often","Students begin to ask more questions of their own during lessons","Students' answers become longer and more detailed over the year"],"answer":0,"explanation":"Answering one's own questions teaches students to wait rather than think, and lowers participation. Extending wait time and using think-pair-share would encourage thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-942","question":"In a Class V class, the same five children raise their hands and answer every question. Which change best spreads thinking and participation across the whole class?","options":["Continue taking answers only from volunteers, since calling on others creates anxiety and fear in them","Ask questions only to the five confident children, so that the lesson moves faster","Punish children who never raise their hands, so that they learn to take part","Use think-pair-share, then call on students at random (e.g. with name sticks) in a supportive way"],"answer":3,"explanation":"Thinking time with a partner gives every child something to say, and random selection means everyone must prepare; a supportive tone keeps it safe. Relying on volunteers leaves most children passive.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-943","question":"A Class VII EVS teacher wants a question that genuinely requires the Analyse level. Which question should she choose?","options":["'From this table of rainfall and wheat yield in two villages, what pattern do you see, and why?'","'Define rainfall and write two sentences about how the monsoon reaches your state.'","'Which state of India receives the highest rainfall, and in which months does it fall?'","'Draw the symbol used for rainfall on weather maps and label it.'"],"answer":0,"explanation":"Finding patterns and relationships in unfamiliar data and looking for causes is Analyse. The other questions only ask for recall or reproduction of known information.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-944","question":"Consider the following statements about using Bloom's revised taxonomy in teaching: 1. Its categories are treated as a less rigid hierarchy than the original, so they can overlap. 2. Higher-order questions are suitable for primary-school children as well. 3. Questions at the Remember level have no place in good teaching. Which of these are correct?","options":["2 and 3 only","1 and 3 only","1 and 2 only","1, 2 and 3"],"answer":2,"explanation":"The revised taxonomy relaxes the strict cumulative hierarchy, and even young children can analyse and evaluate at their level. Recall still has a role (facts feed higher thinking), so statement 3 is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-945","question":"In a Class VI art-and-science project, students use a rubric to judge a partner's poster on 'clarity of the diagram' and 'accuracy of labels' and give reasons for each score. The task is mainly at which level of Bloom's revised taxonomy?","options":["Create","Analyse","Evaluate","Understand"],"answer":2,"explanation":"Judging work against given criteria and justifying the judgement (checking, critiquing) is Evaluate. Students are not producing something new, so it is not Create.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-946","question":"A teacher believes: 'Weak students cannot handle why and how questions; I ask them only what and who questions until they master the basics.' Which response is best supported by research and NCF?","options":["The teacher is right, because thinking questions only confuse and discourage weak students","All students gain from higher-order questions with support; restricting some to recall lowers expectations","The teacher is right, because a child must fully master recall before any higher-order thinking","Higher-order questions should be asked only in written tests, never in class, where weak students feel exposed"],"answer":1,"explanation":"Limiting low achievers to recall denies them the thinking that builds understanding and signals low expectations. With scaffolds such as examples and think time, they can and should reason too.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-947","question":"A Class VIII student explains to her group: 'Iron nails rust faster in coastal Mumbai than in dry Jaipur because there is more moisture in the air there.' In Bloom's revised taxonomy, this explanation is best placed at:","options":["Remember x Factual knowledge","Understand x Conceptual knowledge","Create x Procedural knowledge","Evaluate x Metacognitive knowledge"],"answer":1,"explanation":"Explaining a cause-and-effect relation in a new example is Understand (explaining), and the knowledge is a principle about rusting, which is conceptual. She is not judging, creating or recalling a stand-alone fact.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-948","question":"Assertion (A): A question that begins with 'Why' is always a higher-order question. Reason (R): The level of a question depends on the thinking students must do to answer it, not only on its opening word.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"'Why did the Mughal empire decline?' is only recall if students learnt a list of reasons by heart. Since level depends on the actual cognitive work, R is true and it shows A is false.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-949","question":"In a Class V maths lesson, the teacher shows that 3/4 and 6/8 are equal and asks: 'Can you find two other fractions equal to 3/4 and explain how you know?' Which feature makes this a good question for learning?","options":["It has only one correct answer, which makes marking quick, simple and fair for every child in class","It is really a yes/no question, which saves time and keeps the lesson moving","It asks children to recall a rule exactly as it is written in the textbook","It allows many correct answers and asks children to justify them, revealing their understanding"],"answer":3,"explanation":"Open questions with several answers and a call for justification show whether children grasp the idea of equivalence, not just a memorised rule. This makes their thinking visible to the teacher.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-950","question":"The NCF 2005 position paper on teaching mathematics names some core problems of school mathematics in India. Which of these is NOT one of them?","options":["A sense of fear and failure about mathematics among a majority of school children","Crude methods of assessment that make mathematics look like mechanical computation","Too much time on concrete materials and activities in the upper primary classes","Inadequate preparation of, and support for, mathematics teachers in schools"],"answer":2,"explanation":"The paper lists fear and failure, a curriculum that disappoints both the talented and the non-participating majority, crude assessment, and inadequate teacher preparation. It argues for more activity, not less.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-951","question":"NCF 2005 recommends shifting the focus from mathematical content to a learning environment where processes come first. Which classroom best fits this?","options":["Students estimate the school's daily water use, choose a method, check their reasoning and present it","The teacher completes the syllabus early so that there is more time for revision and tests","Students copy solved examples from the board and then do similar exercises on their own","Students practise timed speed tests on all the formulae every day to build fluency"],"answer":0,"explanation":"Estimation, representation, reasoning and communication are among the processes NCF 2005 puts ahead of covering content. The other options focus on finishing content or on mechanical practice.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-952","question":"Which of these statements match the NCF 2005 position on mathematics at the primary stage? I. A positive attitude towards, and liking for, mathematics is as important as cognitive skills, if not more. II. Games, puzzles and stories help children develop this attitude. III. The primary stage should concentrate on speed in written algorithms.","options":["I only","I and II only","II and III only","I, II and III"],"answer":1,"explanation":"NCF 2005 says that liking mathematics at the primary stage matters as much as cognitive skills, and that games, puzzles and stories help build it. It does not ask for a focus on speed in algorithms.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-953","question":"Assertion (A): NCF 2005 recommends changing assessment in mathematics so that it tests students' ability to mathematise rather than only procedural knowledge. Reason (R): Crude assessment encourages children and teachers to see mathematics as mechanical computation.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"NCF 2005 names crude assessment as a core problem precisely because it shapes what is taught and learnt as mechanical computation; changing assessment is its remedy. R explains A.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-954","question":"A Class 1 child, after counting 3 mangoes, 3 claps and 3 days of the week, says, ‘They are different things, but it is always three.’ Which feature of mathematics has she begun to grasp?","options":["Precision of language, since she uses the word ‘three’ correctly each time","Deductive proof, since she has proved a rule from her own examples","Measurement, since she has measured three different kinds of things","Abstraction, since number is a property shared by all sets of that size"],"answer":3,"explanation":"Seeing ‘three’ as separate from mangoes, claps or days is abstraction, a basic feature of mathematics that lets one idea apply to countless situations.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-955","question":"A teacher shows several examples, asks Class 7 students to spot the rule that the exterior angle of a triangle equals the sum of the two opposite interior angles, and then proves it for any triangle. This lesson moves from:","options":["the deductive method to the inductive method","the analytic method to the synthetic method","the inductive method to the deductive method","the lecture method to the project method"],"answer":2,"explanation":"Finding a rule from examples is inductive; proving it for every case from known facts is deductive. Moving from the first to the second gives understanding and then certainty.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-956","question":"A child reads a word problem and at once adds all the numbers in it. Which of Pólya's problem-solving stages has she skipped?","options":["Understanding the problem","Devising a plan","Carrying out the plan","Looking back"],"answer":0,"explanation":"Before planning, a solver must know what is given and what is asked. Asking her to retell the problem in her own words or draw it addresses the skipped first stage.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-957","question":"‘Ravi spent half his pocket money on a book and then ₹20 on snacks. He had ₹30 left. How much did he start with?’ Which strategy is the most efficient for this problem?","options":["Guess and check","Work backwards","Make a table","Look for a pattern"],"answer":1,"explanation":"The end amount and the steps are known, so undoing them in reverse order gives the start: (30 + 20) × 2 = ₹100. Guessing works but is slower.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-958","question":"After proving that the angles of a triangle add up to 180°, a teacher asks, ‘What if the shape had four sides? What if the triangle were drawn on a ball?’ This is an example of:","options":["drill and practice, applying a known result to new figures","the lecture method, extending the proof through explanation","problem posing, by asking ‘what if not?’ about a known result","remedial teaching for students who could not follow the proof"],"answer":2,"explanation":"Changing one condition of a known result to create new questions is the ‘what if not?’ strategy of problem posing. It develops curiosity and the habit of asking mathematical questions.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-959","question":"A teacher shows a ration shop's price list and asks Class 4 children to make up their own questions from it. What is the main value of this task?","options":["It saves the teacher's time and effort in setting fresh questions for the class","It replaces the need for textbook exercises, since children make their own","It is mainly a test of how fast children can read the items on a price list","Posing problems deepens grasp of the operations and reveals what children understand"],"answer":3,"explanation":"To pose a sensible problem a child must understand what each operation means. The questions children make, and the mistakes in them, show the teacher their understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-960","question":"‘Some birds were on a tree. 5 flew away and 8 are left. How many were there at first?’ A Class 2 child writes 8 − 5 = 3, saying ‘left means take away’. What is the best response?","options":["Act it out or draw a part-whole picture, showing that birds gone and birds left make up the start","Give the children a list of key words with the operation that goes with each word","Tell the child that the word ‘left’ means add in this problem, and to remember it","Ask the child to read the problem again more slowly and then try the subtraction again"],"answer":0,"explanation":"Acting out or drawing shows the start is 5 + 8 = 13. Key-word lists cause exactly this error, since the same word can signal different operations.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-961","question":"Asked ‘Is 7 an odd number?’, a child says, ‘No, 7 is a normal number. Odd means strange.’ How should the teacher understand and respond?","options":["The child is being cheeky and should be warned not to joke during the lesson","It is a language issue: discuss how everyday and mathematical meanings of ‘odd’ differ","The child has not yet learnt to count up to 7 and needs much more practice in counting","The child should be told to avoid such everyday words when doing mathematics"],"answer":1,"explanation":"Many words (odd, difference, product, volume, table) have different everyday and mathematical meanings. Building the mathematical register through talk is part of teaching mathematics.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-962","question":"A Class 3 child can write 3 × 4 = 12 correctly but cannot draw a picture or make up a story for it. What does this suggest?","options":["Her understanding is already complete, since she writes both the symbols and the answer correctly","She has a language problem that is not related to her understanding of mathematics","Her understanding is limited; she needs tasks linking objects, pictures, words and symbols","She should do more written practice of tables until she is fully fluent with them"],"answer":2,"explanation":"Understanding shows in the ability to translate between representations, such as objects, pictures, spoken language and symbols. Knowing only the symbol form suggests rote learning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-963","question":"A child says, ‘I think you can't take 8 from 3.’ The teacher replies, ‘So you are saying that 3 − 8 has no answer. Who agrees or disagrees, and why?’ This talk move is called:","options":["wait time, giving the child more time to rethink","telling, by giving the class the correct answer","closing the discussion with the right answer","revoicing, then inviting others to respond"],"answer":3,"explanation":"Revoicing restates the child's idea clearly and checks it, and asking others to agree or disagree turns it into a class discussion. It neither tells the answer nor closes the talk.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-964","question":"A teacher asks ‘Why does this method work?’ and calls on the first hand raised within a second. Which change would most improve participation and reasoning?","options":["Wait several seconds, or let pairs discuss first, before taking any answers","Ask easier questions that need no explanation, so more hands go up","Call on the best student first, so that the others hear a model answer","Give the answer herself if no hand goes up at once, to save time"],"answer":0,"explanation":"Longer wait time and pair talk give every child time to think and rehearse an explanation, leading to more and better answers. Calling on the quickest child shuts the others out.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-965","question":"A teacher puts up sentence frames such as ‘I agree with ___ because ___’ and ‘My method is different because ___’ during maths discussions. The main purpose is to:","options":["make children copy the sentences neatly into their notebooks as practice","help all children, including those learning the language, to explain their reasoning","replace the teacher's explanation, since children can now explain everything to each other","keep the class quiet during group work by giving children fixed things to say"],"answer":1,"explanation":"Frames give a structure for mathematical argument, such as agreeing, disagreeing and justifying, so that more children take part in reasoning, especially those less fluent in the language of instruction.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-966","question":"In a Class 1 classroom in a tribal area, children count fluently in their home language but are shy to answer in Hindi. What is the most suitable approach?","options":["Insist on Hindi number words only, so that children learn the school language much faster","Postpone number work until the children have learnt enough Hindi to follow it","Let them count in their home language, then link those words to the school number names","Teach only the written numerals, without using number words in any language"],"answer":2,"explanation":"NCF 2005 and NEP 2020 treat children's home language as a resource. Building on what they know, and bridging to the school language, keeps the focus on mathematical thinking.","difficulty":"hard","source":"CTET Paper 1 · state TETs · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-967","question":"Which statement reflects the NCF 2005 vision of how children should experience mathematics?","options":["Children should see mathematics mainly as a set of procedures to be practised until fluent","Mathematics should be done individually and silently, so that children do not copy","Children should talk about mathematics only after they have written the correct answer","Children should see mathematics as something to talk about, discuss and work on together"],"answer":3,"explanation":"NCF 2005's vision includes children seeing mathematics as something to talk about, communicate through, discuss and work on together, along with enjoying mathematics, posing and solving problems, and seeing structure.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-968","question":"A Class 4 child says, ‘Odd plus odd is always even, because each odd number has one left over after making pairs, and the two left-overs make another pair.’ How should the teacher regard this?","options":["As a general argument that shows why it holds for all odd numbers, a proof in words","As a guess that still needs many more examples before it can be accepted","As wrong, because a real proof needs algebra and cannot be in words","As correct only for the small numbers that she has been able to try"],"answer":0,"explanation":"The child's reasoning covers every odd number, not just the ones she tried, so it is a valid general argument. Young children can reason deductively with pictures and words, which NCF 2005 encourages.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-969","question":"A Class 6 student claims, ‘All prime numbers are odd.’ What is the best response?","options":["Tell her she is right, since nearly all the prime numbers she will meet are odd","Ask her to look for a prime that breaks the rule, since one counterexample disproves a claim","Ask her to list the first ten odd primes, so that she can confirm the claim holds","Tell her to check her claim carefully with all the primes from 3 to 50"],"answer":1,"explanation":"2 is prime and even, so the claim is false. Checking more cases that agree cannot prove a general claim, but a single counterexample disproves it; this is an important idea about the nature of mathematics.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-970","question":"Children agree on the claim, ‘Multiplying a number by itself always gives a bigger number.’ What should the teacher do next?","options":["Agree, and write it on the class chart of rules for future reference","Correct it at once by telling them the right rule for squares","Have them test it with 1, 0 and 1/2, and then refine the claim","Tell them the claim is true for whole numbers only, from Class 6 on"],"answer":2,"explanation":"1 × 1 = 1, 0 × 0 = 0 and 1/2 × 1/2 = 1/4 break the claim. Testing and refining their own conjecture teaches how mathematics works: claims are checked, not accepted on agreement.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-971","question":"Before teaching 2-digit by 2-digit multiplication, a Class 5 teacher gives a short check on place value and multiplication facts. This reflects which feature of mathematics?","options":["Its abstract nature, which makes it difficult for many children","Its use of symbols in place of words, which must be learnt first","Its practical use in daily life, such as in shopping, cooking and measuring","Its sequential structure, in which new concepts build on earlier ones"],"answer":3,"explanation":"Mathematics builds in layers, so gaps in earlier ideas block later learning. A readiness check finds the gaps before the new topic is taught.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-972","question":"Class 5 children use a village map to find the shortest route for a postman to visit four houses and return to the post office. Which mathematical process is mainly being developed?","options":["Optimisation, finding the best of several possible solutions","Memorisation of the symbols and colours used on village maps","Rote computation of distances using a formula","Measurement of distances with standard units only"],"answer":0,"explanation":"Comparing routes to find the shortest one is optimisation, listed in NCF 2005 among the processes of mathematics along with estimation, visualisation and reasoning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-973","question":"Which of these statements about the language of mathematics in school are correct? I. Symbols such as ‘=’ and ‘<’ should come after children have expressed the ideas in their own words. II. Word problems test only computation. III. Children's informal language should be linked to formal terms gradually. IV. Precise language matters in mathematics.","options":["I and II only","I, III and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"Word problems also test reading, comprehension and modelling, so II is false. The rest describe good practice: ideas first in words, then symbols, building towards precise mathematical language.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-974","question":"Match each problem with the most suitable strategy. 1. ‘Half my money went on a book and ₹20 on snacks; ₹30 is left. How much did I start with?’ 2. ‘How many handshakes happen when 20 people each shake hands once?’ 3. ‘Two numbers add up to 20 and multiply to 96. Find them.’ 4. ‘A frog climbs 3 m up a 10 m well each day and slips back 2 m each night. When does it get out?’; a. Draw a diagram b. Guess and check c. Solve simpler cases and look for a pattern d. Work backwards","options":["1-d, 2-b, 3-c, 4-a","1-a, 2-c, 3-b, 4-d","1-d, 2-c, 3-b, 4-a","1-b, 2-c, 3-d, 4-a"],"answer":2,"explanation":"Known end with known steps suggests working backwards; handshakes with 2, 3 and 4 people show a pattern; small number pairs can be checked quickly; and a diagram of the well avoids the trap of answering 10 days (it gets out on day 8).","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-975","question":"Asked why her mother keeps the drinking-water matka covered, a Class 3 child says, ‘So that dust and flies do not fall in, otherwise we will fall ill.’ In NCERT’s list of EVS learning indicators, this answer mainly shows:","options":["Observation and recording","Explanation","Expression","Classification"],"answer":1,"explanation":"The child links a practice to its reason and consequence, which is the indicator ‘Explanation’ (reasoning, making logical connections). Merely noticing the cover would be observation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-976","question":"While making a model of a village in groups, a Class 5 child takes the lead in dividing the work, makes sure everyone gets a turn with the scissors and helps a slower member finish his part. The EVS indicator best shown is:","options":["Concern for justice and equality","Expression","Questioning","Cooperation"],"answer":3,"explanation":"Taking responsibility and initiative, sharing and working together are the sub-indicators of Cooperation. Fair turns can look like ‘justice’, but the behaviour centres on teamwork within the group.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-977","question":"Before an activity, a Class 5 child says, ‘The bread kept in the damp tin will grow fungus sooner than the bread in the dry tin, because fungus likes moisture.’ This statement mainly shows the EVS indicator:","options":["Analysis","Experimentation","Discussion","Observation and recording"],"answer":0,"explanation":"Predicting and hypothesising with a reason fall under Analysis. Experimentation would be setting up and doing the test, which has not happened yet.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-978","question":"Without being asked, a Class 5 child makes a simple filter from a cut plastic bottle, sand and gravel, and pours muddy water through it to see whether it comes out cleaner. This best shows the EVS indicator:","options":["Classification","Expression","Experimentation","Discussion"],"answer":2,"explanation":"Improvising apparatus and testing an idea is Experimentation. Making something by hand might suggest Expression, but the purpose here is to try out and check.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-979","question":"After a visit to the river near her village, a Class 4 child writes a short poem about it and, with friends, makes up a dance about the rain. The EVS indicator mainly shown is:","options":["Analysis","Explanation","Observation and recording","Expression"],"answer":3,"explanation":"Creative writing, drawing, body movement and similar forms belong to Expression. No reasoning or prediction is involved.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-980","question":"A Class 4 child asks, ‘Why does the water from the hand pump feel warm in winter and cool in summer?’ This mainly reflects the EVS indicator:","options":["Questioning","Analysis","Classification","Cooperation"],"answer":0,"explanation":"Expressing curiosity and framing her own question is Questioning. She is not yet predicting or reasoning, so it is not Analysis.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-981","question":"During a talk on how to save water, a Class 5 child listens to a classmate and then says, ‘I do not agree with Ravi. I think we waste more water while washing utensils.’ The EVS indicator best shown is:","options":["Explanation","Concern for justice and equality","Discussion","Expression"],"answer":2,"explanation":"Listening to others, talking, expressing an opinion and finding out from others are the sub-indicators of Discussion.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-982","question":"Which of the following are among the indicators NCERT suggests for assessing learning in EVS? I. Classification II. Memorisation of facts III. Concern for justice and equality IV. Handwriting","options":["I, II and III","II and IV","I and IV","I and III"],"answer":3,"explanation":"NCERT’s indicators include classification and concern for justice and equality; memorisation and handwriting are not EVS indicators.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-983","question":"Match each EVS indicator with its sub-skills: 1. Observation and recording 2. Classification 3. Analysis 4. Cooperation. a. Predicting, hypothesising, inferring. b. Reporting, narrating, drawing, making tables. c. Grouping, comparing and contrasting. d. Sharing, taking initiative, working together.","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-a, 4-d","1-b, 2-a, 3-c, 4-d","1-a, 2-c, 3-b, 4-d"],"answer":1,"explanation":"Reporting and drawing record observations; grouping and comparing classify; predicting and inferring analyse; sharing and initiative show cooperation.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-984","question":"A Class 4 teacher wants to assess the indicator ‘Cooperation’. The most suitable tool is:","options":["observation during group work, recorded as anecdotal notes over weeks","a written test with questions on teamwork and sharing in groups","an oral quiz in which children explain the meaning and value of cooperation","a homework essay on ‘Why we should cooperate’, marked for ideas"],"answer":0,"explanation":"Cooperation is a behaviour, so it must be seen in action and recorded over time. Tests and essays measure what a child can say about it, not what she does.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-985","question":"After noticing that many Class 3 children cannot group animals by where they live, a teacher drops her plan for the next chapter and adds more sorting activities with real examples. This is an example of:","options":["assessment of learning used only for grading","summative assessment carried out at the end of the term","assessment for learning, used to adapt teaching","norm-referenced testing to rank children"],"answer":2,"explanation":"Using information about learning to change teaching is formative assessment, or assessment for learning. No grade or ranking is involved.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-986","question":"Which question is best suited to assessing the EVS indicator ‘Analysis’ in Class 5?","options":["Name three trees found near your school and say which of them is the tallest.","Draw any tree you like and colour its leaves, flowers and fruits.","Which tree gives us mangoes, and in which season does it fruit?","If all the trees around our school were cut down, what changes might we notice? Why?"],"answer":3,"explanation":"Predicting consequences and giving reasons is analysis. The others call for recall or expression.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-987","question":"A Class 2 teacher plans a written test on ‘Our surroundings’. The best advice for her is that:","options":["written tests should be given weekly from Class 1 to prepare children for later exams","at this stage, observing children's talk, drawings and activities tells more than written tests","only oral tests should be given at this stage, with marks awarded for every answer","no assessment of any kind should be done in Classes I and II, since the children are far too young"],"answer":1,"explanation":"In the early classes assessment should be informal and observation-based. That does not mean no assessment at all, and oral tests with marks for every answer are just exams in another form.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-988","question":"Which of these is NOT a feature of a good EVS portfolio?","options":["It holds only the child’s best final products, chosen by the teacher","It contains dated samples of the child's work collected over a period","It includes the child’s own reflections on her work and progress","It contains varied forms of work such as drawings, survey sheets and notes"],"answer":0,"explanation":"A portfolio documents growth over time and the child’s own reflection; a teacher-selected showcase of best products hides the process.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-989","question":"A teacher prepares a rubric for a Class 5 project with criteria such as questions raised, information collected, explanation and presentation, and shares it with children before they begin. The main advantage of sharing it in advance is that children:","options":["can finish the project faster, with less effort and fewer mistakes","can compare their marks with children in other sections","know what good work looks like and can judge their own progress","need no further help or guidance from the teacher"],"answer":2,"explanation":"Transparent criteria let children aim at quality and judge their own work, which is the core of assessment for learning. Speed and comparison are not the point.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-990","question":"Assertion (A): Peer assessment in EVS group projects can help children reflect on their own work. Reason (R): Marks given by peers are always accurate and can replace the teacher’s assessment. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Judging others’ work against criteria sharpens children’s view of their own, but peer marks are not always accurate and complement rather than replace teacher assessment.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-991","question":"Which remark in a Class 4 child’s EVS report is most useful for the child and parents?","options":["Ravi is weak in EVS and must pay more attention in class.","Ravi scored 12 out of 25, which is below the class average.","Ravi should work harder and revise all his EVS lessons regularly at home.","Ravi records observations well but needs help giving reasons for them."],"answer":3,"explanation":"Descriptive feedback names strengths and a specific next step tied to the indicators. Labels, bare marks and general exhortations give no direction.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-992","question":"A Class 5 child’s written EVS answer has several spelling mistakes, but her reasoning about why the pond dries up in summer is correct. When assessing EVS, the teacher should:","options":["deduct marks for each spelling mistake, since accuracy matters in every subject","credit her EVS understanding and note the spelling for language support separately","ask her to rewrite the answer neatly and correctly before it is assessed","give no marks, since an answer with so many errors cannot be accepted"],"answer":1,"explanation":"EVS assessment should judge the EVS learning (here, explanation). Penalising language errors would mix two different things and discourage children who are still learning to write.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-993","question":"During an activity with bottles holding different amounts of water, which observation should the teacher record under the indicator ‘Experimentation’?","options":["Ruchi varied the water level herself to see how the sound changed","Ruchi drew all the bottles neatly in her notebook with labels","Ruchi helped her group clean up carefully after the activity","Ruchi told the class a story about a musician who played on glass bottles"],"answer":0,"explanation":"Changing a condition to see its effect is experimentation. Drawing is recording, helping is cooperation and storytelling is expression.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-994","question":"Which statements about assessment in EVS are correct? I. It should be woven into the teaching–learning process. II. Questions should leave room for many correct answers drawn from children’s experience. III. Values such as concern and cooperation should be assessed through written tests only. IV. Children’s errors give useful information for teaching.","options":["I and II only","I, II and IV only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Continuous, open and diagnostic assessment is the NCERT view. Values are seen in behaviour, so written tests alone cannot assess them; III is wrong.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-995","question":"A teacher shows a picture of a crowded railway platform and asks Class 3 children to tell what they see and what the people might be doing. Under NCERT’s EVS indicators, picture reading is a sub-skill of:","options":["Classification","Analysis","Concern for justice and equality","Observation and recording"],"answer":3,"explanation":"NCERT lists picture reading, along with reporting, narrating and drawing, under Observation and recording.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-996","question":"Which of these EVS questions tests memory rather than understanding?","options":["Name the animal that sleeps for about 17 hours a day.","Why do you think animals in very cold places have thick fur?","How is a camel suited to living in a desert, compared with a fish in a river?","What might happen to a field if there were no earthworms in it?"],"answer":0,"explanation":"The first can only be answered by recalling a fact. The others ask children to reason, compare or predict.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-997","question":"A teacher collects Class 5 project files, keeps them for a month and returns them with only a mark written on the cover. The main weakness of this practice is that:","options":["projects should never be marked, only displayed in the class","a month is too short a time for proper checking of projects","the feedback comes late and gives no guidance on improving","children should mark their own files instead of the teacher"],"answer":2,"explanation":"Feedback helps learning only when it is timely and descriptive. A late bare mark tells the child nothing about what to do next.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-998","question":"Class 4 children make a table comparing a village house and a city flat in terms of materials, space and source of water. In NCERT’s list of EVS indicators, this mainly shows:","options":["Analysis","Classification","Expression","Experimentation"],"answer":1,"explanation":"Comparing and contrasting are sub-skills of Classification. Analysis would involve predicting or inferring from the comparison.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-999","question":"A teacher notes that a Class 5 child ‘measured the shadow of a stick at 9, 12 and 3 o’clock, put the readings in a table, and said the shadow is shortest at noon because the sun is highest in the sky then’. Which two indicators does this record show, in that order?","options":["Observation and recording, then Explanation","Classification, then Expression","Experimentation, then Concern for justice and equality","Questioning, then Discussion"],"answer":0,"explanation":"Measuring and tabulating is observation and recording; linking short shadows to the sun’s height is explanation.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1000","question":"Which of the following is an open-ended question for a Class VIII unit on local government?","options":["How many members are there in your gram panchayat, and who elects them?","At your gram sabha, which village problem would you raise, and why?","Who presides over the gram sabha, and how often must it meet?","In which year was the 73rd Amendment passed, and what did it set up?"],"answer":1,"explanation":"An open-ended question allows many valid answers and asks students to reason and justify. The others have one fixed answer to be recalled.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1001","question":"A Class IX teacher shares a rubric with students before they start their project on local livelihoods, with criteria for use of sources, analysis, presentation and teamwork, each described at four levels. What is the main advantage?","options":["It lets the teacher award every student the same marks, so no one feels judged unfairly","It ensures that all projects reach the same conclusion about local livelihoods","It removes the need for the teacher to read each project in full before marking","It makes expectations clear, marking more consistent and feedback more specific"],"answer":3,"explanation":"A rubric shared in advance tells students what quality looks like, makes grading fairer across students, and gives a language for feedback. It does not standardise conclusions or replace reading the work.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1002","question":"Assertion (A): Open-book examinations in social science can be used to test higher-order thinking.\nReason (R): When the book is open, questions that need only recall of facts become pointless, so questions must demand application and analysis.","options":["Both A and R are true but R is not the correct explanation of A","Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"An open-book test only makes sense when its questions cannot be answered by locating a line in the book. That forces questions of application, analysis and evaluation, which is why such tests can assess higher-order thinking.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1003","question":"At the end of each lesson on the Indian Constitution, a teacher collects slips on which students write one thing they understood and one question they still have. How should these slips be used?","options":["To find gaps and confusions and adjust the next lesson accordingly","To award marks that count towards each student's final term grade","To identify students who should be punished for not paying attention","To send parents a written report on their child's weaknesses each week"],"answer":0,"explanation":"Exit slips are a formative tool: assessment for learning. Their value lies in guiding teaching, not in grading or blaming students.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1004","question":"A Class VIII teacher asks each student to keep a portfolio of maps they drew, a field-trip report, a source analysis and short reflections, collected over the year. What is the main strength of this method?","options":["It shows growth and a range of skills over time, not just one day's performance","It replaces the need for regular feedback, since the work speaks for itself","It is the quickest way to grade a large class, as one mark covers the whole file","It lets students include only their best test papers, which raises their marks"],"answer":0,"explanation":"Portfolios capture development across tasks and time and encourage reflection. A single test shows performance on one occasion and in one format.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1005","question":"Which test item best assesses map skills in Class VII rather than memory?","options":["Mark Delhi, Mumbai, Kolkata and Chennai on the outline map of India and write the state each lies in.","Name the states through which the Tropic of Cancer passes, listing them in order from west to east.","Use the scale on a map of an unfamiliar district to find the distance between two villages and the river's flow direction.","List all the countries that share a land border with India and write the capital city of each one."],"answer":2,"explanation":"Applying scale, direction and symbols to an unfamiliar map tests whether students can actually use a map. Locating well-known cities or listing countries can be done from memory.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1006","question":"A Class X question paper includes an extract from a 1920s pamphlet followed by questions such as 'What does the writer fear?' and 'Why might a peasant reader disagree?'. What do such source-based questions mainly assess?","options":["The ability to reproduce the textbook paragraph on the national movement accurately","The ability to memorise the pamphlet's author, date and place of publication","Reading speed, since students must finish a long extract within the time","The ability to interpret evidence, infer meaning and consider other perspectives"],"answer":3,"explanation":"Source-based questions place students in the historian's role: reading evidence, drawing inferences and comparing viewpoints. Such skills cannot be shown by reproducing textbook text.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1007","question":"A teacher wants to assess whether Class VIII students show respect for differing views during discussions. Which tool is most appropriate?","options":["A written test question asking, 'Why should we respect others' views?'","A multiple-choice quiz on tolerance and respect, given once at the end of the unit","Observing discussions over several weeks, using a checklist and anecdotal notes","A one-time oral question asked by the principal during a class visit"],"answer":2,"explanation":"Attitudes show up in behaviour, so they are assessed by observing it over time. A written question tests whether students know the right answer, not whether they act on it.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1008","question":"After group presentations on 'Our local market', students use the class rubric to assess another group's work and give one suggestion. What is the main benefit of this peer assessment?","options":["It saves the teacher from having to assess any of the presentations herself","It helps students grasp the quality criteria and reflect on their own work","It ensures that every group gets high marks, since friends will mark generously","It replaces the need for a rubric, since students judge by their own standards"],"answer":1,"explanation":"Applying criteria to others' work helps students internalise what good work looks like and improve their own. The teacher still moderates, and the rubric is what makes peer judgements meaningful.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1009","question":"Which question tests understanding rather than recall in a Class VI chapter on early farming?","options":["Name two crops grown by early farmers and the tools they used to harvest them.","Which animal was domesticated first by early humans, and in which region?","Why might people who began farming also have started living in one place?","Where was the site of Mehrgarh located, and in which present-day country is it?"],"answer":2,"explanation":"Explaining the link between farming and settled life requires reasoning about cause and effect. The other questions can be answered by recalling a fact.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1010","question":"A Class VII student's project report on 'Weekly markets' gets back comments. Which comment is the most useful feedback?","options":["'Good work, 7/10. The report is well organised and your title page is neatly and colourfully presented.'","'Your handwriting needs improvement; please rewrite the whole report more neatly by Monday.'","'Very nice, keep it up! You are one of the best students in the class.'","'Your vendor interviews are strong. Next, compare their answers and explain why they differ.'"],"answer":3,"explanation":"Good feedback says what was done well and gives a specific, actionable next step tied to the learning goal. A score or general praise tells the student nothing about how to improve.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1011","question":"A short quiz given before a chapter on Parliament reveals that many Class VIII students think 'Parliament' is the Prime Minister's house. What is the best use of this finding?","options":["Record the scores in the report card so that parents can see the starting level of each child","Plan lessons that directly address this misconception about what Parliament is","Repeat the same quiz every day until all students give the right answer","Ignore it, since the chapter itself will correct the misconception anyway"],"answer":1,"explanation":"A diagnostic assessment is meant to shape teaching. Knowing the misconception lets the teacher target it, rather than hoping it disappears or grading it.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1012","question":"A Class VI geography test includes: 'Describe your last holiday trip to a hill station and the changes in climate you noticed.' What is the main problem with this question?","options":["It is too easy for Class VI, since any child can write about a holiday trip","It asks about climate change, which is not part of the Class VI geography syllabus at all","It tests history rather than geography, because it asks about a past event","It assumes every child has visited a hill station, which disadvantages poorer children"],"answer":3,"explanation":"Questions that assume particular experiences are socio-economically biased: they test access, not learning. A fair question lets every child show the same skill, for example through a given description or picture.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1013","question":"A teacher sets an open-ended question: 'What could your town do to reduce waste?' She then gives full marks only to answers that match her own model answer. What is the main flaw?","options":["Open-ended questions should not be marked at all, only discussed in class","She should give everyone full marks for trying, since there is no right answer","Several answers can be valid; she should judge reasoning and evidence instead","She should have set a multiple-choice question, which is easier to mark fairly"],"answer":2,"explanation":"Marking open-ended work against one answer defeats its purpose and penalises original thinking. Criteria about reasoning and evidence keep the marking fair while allowing varied answers.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1014","question":"Assertion (A): Continuous assessment in social science should include skills such as map reading, data interpretation and participation in discussion, not only written tests.\nReason (R): Paper-and-pencil tests capture every aspect of learning in social science.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Many important outcomes, such as collaboration, inquiry and practical map use, do not show up fully on paper, which is why varied tools are needed. R is false, and it would in fact argue against A.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-1015","question":"A Class VII test gives a table of rainfall and main crops for three districts, then asks which crop a fourth district with similar rainfall might grow and why. At which level of Bloom's revised taxonomy is this question?","options":["Remembering","Applying and analysing","Creating and evaluating","Understanding only"],"answer":1,"explanation":"Students must use the pattern in the data and apply it to a new case, explaining their reasoning, which is application with analysis. The answer is not in the table to be recalled.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1016","question":"Class VIII students draw concept maps linking 'democracy', 'elections', 'rights', 'representation' and 'accountability'. As an assessment tool, what can such maps reveal best?","options":["How neatly students can draw the diagrams and label them within the time allowed","Whether students can recite the textbook definitions of each term","How many difficult political words each student knows and can spell","How students link ideas, and where their understanding is missing or wrong"],"answer":3,"explanation":"The links students draw, and the ones they miss or get wrong, show the structure of their understanding. That diagnostic information is hard to get from a definition test.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1017","question":"Which assessment practice best matches the vision of NEP 2020 for social science?","options":["Year-end examinations that test memorised content from the whole textbook","Competency-based tasks on analysis and application, with a holistic progress card","Ranking students on a single test at the end of each term to motivate them","Assessing only through objective-type questions, which are quick and highly reliable"],"answer":1,"explanation":"NEP 2020 calls for a shift from rote, summative testing to regular, competency-based assessment of higher-order skills and a holistic, 360-degree progress card.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS"},
  {"id":"cdp-pedagogy-subjects-1018","question":"Which of the following statements about open-ended questions in social science are correct?\n1. They allow more than one acceptable answer.\n2. They cannot be assessed reliably, so they should be avoided in tests.\n3. Clear criteria help teachers assess them fairly.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Open-ended questions invite varied, reasoned answers, and clear criteria such as relevance, reasoning and evidence make marking them consistent. Statement 2 confuses 'harder to mark' with 'impossible to mark'.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1019","question":"A teacher assesses a Class VIII role play on a Lok Sabha debate. Which criterion is most appropriate?","options":["How loudly and confidently each student spoke, as in a real Lok Sabha debate","Whether students wore suitable costumes and looked convincing as real members of parliament","How well their arguments reflected their character's view and parliamentary procedure","How long each student spoke, since longer speeches show more preparation"],"answer":2,"explanation":"The role play was a means of learning about parliamentary procedure and perspectives, so assessment should look at that understanding. Acting skill, costumes or speaking time are not the learning objective.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1020","question":"During group work, a teacher notes: 'Riya linked the rise in onion prices at the haat to transport costs after the floods.' Notes like this, kept over time, are called:","options":["Anecdotal records","Rating scales","Cumulative scores","Achievement tests"],"answer":0,"explanation":"Anecdotal records are brief factual notes of significant behaviour or learning observed in context. They show how a child thinks in real situations, which tests often miss.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1021","question":"A Class VIII question asks: 'If printed books and newspapers had not spread in 19th-century India, how might the social reform movements have been affected?' What mainly does this question test?","options":["Recall of the dates when the first printing presses were set up in India","Knowledge of the names of social reformers and the newspapers they ran","The ability to summarise the chapter on print culture in their own words","Reasoning about causes and consequences through a hypothetical situation"],"answer":3,"explanation":"A counterfactual question forces students to think about how one factor, print, shaped others, such as the spread of reform ideas. It cannot be answered by recall of names or dates.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1022","question":"After a field trip to a textile mill, how should a Class IX teacher assess what students learnt?","options":["By asking for a reflective report linking what they saw to concepts studied in class","By asking students to write the name of the mill, its owner and the year it was set up","By marking attendance on the trip, since being present shows participation","By giving marks for good behaviour on the bus and during the mill visit"],"answer":0,"explanation":"Assessment of a field trip should check whether students connected observation with concepts. Attendance, behaviour or factual details about the mill say little about learning.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1023","question":"A Class IX teacher's test asks, 'Write ten causes of the decline of the Mughal Empire.' Which revision would best turn it into a question that assesses historical thinking?","options":["Ask for fifteen causes instead of ten, to cover the topic more completely","Ask students to write the causes in a table, with one cause in each row","Ask students to pick the cause that mattered most and justify it with evidence","Ask students to write the causes in exactly the same order as the textbook gives them"],"answer":2,"explanation":"Weighing causes, explaining their working and using evidence are the core of historical reasoning. Listing more causes or arranging them differently still only tests memory.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1024","question":"Which of the following are suitable tools for assessing a Class VII group project on 'Water sources in our locality'?\n1. A rubric covering planning, data collection, analysis and presentation\n2. Students' self-reflection on their contribution\n3. A viva in which each member explains part of the findings\n4. Marks based only on the decoration of the final chart","options":["1, 2 and 3 only","1 and 4 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"A rubric, self-reflection and an individual viva together capture both the process and each student's understanding. Marking decoration rewards appearance rather than learning.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1025","question":"A Class 9 student writes, ‘I did a mistake in the test because of the strong rain outside.’ The grammar is fine, but the word combinations are unnatural. The area the teacher should work on, and a suitable activity, is:","options":["Spelling; dictation of commonly misspelt words from the lesson, such as ‘mistake’","Tense; practice of the simple past through sentence transformation drills","Collocation; noticing word partners like ‘make a mistake’ and ‘heavy rain’ in texts","Pronunciation; reading the sentences aloud with correct word stress and natural intonation"],"answer":2,"explanation":"Collocations are words that habitually go together; ‘do a mistake’ and ‘strong rain’ are grammatical but not what users say. Noticing and recording chunks from texts builds this knowledge.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1026","question":"A teacher writes ‘monsoon’ in the middle of the board and children add connected words on branches: clouds, umbrella, puddle, farmer, flood, sowing. The main value of this semantic map is that it:","options":["Teaches the spelling of each word through repeated copying from the board","Links new words to related ideas, which aids understanding and recall","Replaces the need for children to read about the monsoon in the textbook","Tests how many words each child already knows by the end of the lesson"],"answer":1,"explanation":"Words are stored and recalled in networks of meaning; mapping a topic connects new words to known ones and to each other, which supports retention and use.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1027","question":"A Class 7 student understands ‘reluctant’ whenever she meets it in reading but never uses it in her own speech or writing. To move the word into her productive vocabulary, the teacher should:","options":["Make her copy its dictionary meaning five times so it stays in memory","Give her a list of twenty more difficult synonyms to learn by heart","Ask her to underline the word each time it appears in her reading, to notice it more","Set speaking and writing tasks that need the word, so she uses it repeatedly"],"answer":3,"explanation":"Receptive knowledge becomes productive through repeated, meaningful use. Copying definitions or noticing the word again keeps it receptive.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1028","question":"Consider these statements about vocabulary learning: I. Meeting a word’s dictionary meaning once is usually enough to learn it. II. Knowing a word includes its form, meaning, usual partners and the situations it suits. III. Words met in meaningful contexts are generally retained better than words in isolated lists. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":1,"explanation":"Word knowledge is multi-dimensional and builds up over many encounters in varied contexts, so a single meeting with a definition is rarely enough.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1029","question":"Reading ‘The boat drifted towards the bank of the river’, a Class 6 student looks up ‘bank’ and copies the first meaning: ‘an organisation that keeps money’. The teacher should mainly help him to:","options":["Stop using the dictionary, since it only confuses learners at this stage","Always copy the first meaning, as dictionaries list the most common one first","Pick the meaning that fits the context, as many words have several meanings","Learn the spelling of ‘bank’ thoroughly before checking any of its meanings"],"answer":2,"explanation":"Dictionary skills include handling polysemy, scanning the entries and testing each meaning against the context of the sentence.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1030","question":"A teacher writes ‘thin’, ‘slim’, ‘skinny’ and ‘bony’ on cards, and Class 8 students arrange them on a line from the most flattering to the most unflattering, then discuss when each could be used. This activity mainly develops awareness of:","options":["Spelling patterns in English adjectives that describe body shape","The grammatical class of each word and how it is used in a sentence","Pronunciation and stress patterns of two-syllable English adjectives","Connotation, the shades of feeling that separate near-synonyms"],"answer":3,"explanation":"Placing near-synonyms on a cline makes learners notice that words with similar meanings carry different feelings and suit different situations.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1031","question":"What is the most effective way to teach the abstract word ‘honesty’ to Class 4 children?","options":["Through a story, then discussing examples and non-examples from their lives","Writing the dictionary definition on the board and having children learn it","Giving its Hindi equivalent, ‘imaandari’, and moving on to the next word","Showing a picture of an honest person and saying the word several times"],"answer":0,"explanation":"Abstract words cannot be pointed to; meaning is built through situations, examples and contrasts that children can relate to. A single picture of a person cannot show honesty.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1032","question":"Read the sentence: ‘The arid region, which receives almost no rainfall, supports very few crops.’ The clue that helps a reader work out the meaning of ‘arid’ is of which type?","options":["Contrast clue","Example clue","Definition or restatement clue","Clue from the reader’s general knowledge only"],"answer":2,"explanation":"The relative clause ‘which receives almost no rainfall’ restates the meaning of ‘arid’ directly. A contrast clue would signal an opposite with words like ‘unlike’ or ‘but’.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1033","question":"A Class 7 teacher introduces ‘a piece of cake’ and ‘once in a blue moon’. Which approach is most effective?","options":["Avoid idioms until Class 10, since younger learners cannot understand them","List twenty idioms with meanings for students to learn by heart for the test","Explain each word of the idiom separately so that its literal meaning becomes clear first","Use them in a story, discuss their non-literal meaning and compare Hindi idioms"],"answer":3,"explanation":"Idioms are fixed expressions whose meaning is not the sum of their words; context and comparison with equivalents like ‘baayen haath ka khel’ make their figurative sense clear.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1034","question":"Class 7 pairs are planning a poster for a task. One student keeps saying ‘more better’ while they compare designs. The teacher briefly points out ‘better, not more better’ and lets them continue the task. This is an example of:","options":["Focus on form: brief attention to a form while the focus stays on meaning","Focus on forms: teaching grammar items one by one from a structural syllabus","The grammar-translation method, since a grammatical rule is being corrected","The audio-lingual method, since the error is corrected immediately as a habit"],"answer":0,"explanation":"Long distinguished ‘focus on form’, brief attention to language arising during meaning-focused work, from ‘focus on forms’, a syllabus of discrete grammar items taught in isolation.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1035","question":"A teacher gives Class 8 pairs a set of sentences using ‘since’ and ‘for’ (‘since 2019’, ‘for three years’) and asks them to work out when each is used. They are not asked to produce new sentences. This is best described as:","options":["A transformation drill that builds automatic habits through repetition","A consciousness-raising task that helps learners notice and understand a rule","A free production activity that develops fluency with the present perfect","A dictation exercise that tests listening and the accurate spelling of time words"],"answer":1,"explanation":"Consciousness-raising tasks (Ellis) lead learners to discover a grammatical feature from data, building explicit understanding that can later help them notice it in input.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1036","question":"A Class 6 student says, ‘She don’t like milk.’ Match each teacher response with the type of corrective feedback: 1. ‘Oh, she doesn’t like milk? Why not?’ 2. ‘Sorry? Could you say that again?’ 3. ‘Is “don’t” right with “she”? What do we use with he, she and it?’ 4. ‘She…?’ (pausing for the student to finish); a. Clarification request b. Metalinguistic feedback c. Elicitation d. Recast","options":["1-d, 2-a, 3-b, 4-c","1-a, 2-d, 3-b, 4-c","1-d, 2-a, 3-c, 4-b","1-b, 2-a, 3-d, 4-c"],"answer":0,"explanation":"A recast reformulates the error correctly within the conversation; a clarification request signals a problem; metalinguistic feedback comments on the rule; elicitation prompts the learner to supply the form.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1037","question":"Which plan for teaching the passive voice to Class 8 is most in line with teaching grammar in context?","options":["Write the rule for changing active to passive and give twenty sentences for students to convert","Teach all twelve tenses in the passive voice in a single period using a chart","Read a text on tea processing, notice the passives and discuss why the doer is omitted","Ask students to memorise the passive forms of the verb ‘to write’ in every tense"],"answer":2,"explanation":"Process descriptions and news reports use the passive naturally; seeing it in such texts shows its function (the doer is unknown or unimportant), which mechanical conversion exercises do not.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1038","question":"A Class 3 teacher spends many periods making children define ‘noun’, ‘pronoun’ and ‘adjective’ and classify nouns as common, proper, collective and abstract. In the light of NCF 2005, the main problem is that:","options":["Class 3 is too late to start such classification; it should begin in Class 1 itself","Learning grammar terms at this stage does little for children’s actual language use","Grammar should never be part of a primary language syllabus in any form","These definitions should be taught in the mother tongue, not in English"],"answer":1,"explanation":"Young learners develop grammar through rich input and use; definitions and labels add little to their ability to speak, read or write. Grammar is not banned, but taught through meaningful use.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1039","question":"A teacher shows a picture of dark clouds and says, ‘It is going to rain.’ Students then repeat and practise similar sentences with picture cues, and finally talk freely in pairs about their plans for the weekend. This lesson follows the:","options":["Test–teach–test model","Task-based language teaching framework","Grammar-translation model","Present–practise–produce model"],"answer":3,"explanation":"PPP presents a form in a situation, gives controlled practice, then moves to freer production. In a task-based lesson the task would come first and form-focus afterwards.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1040","question":"A teacher first asks Class 7 students to compare two cities using whatever language they have, notes the problems they have with comparatives, teaches those forms, and then gives a similar comparison task. This lesson design is called:","options":["Test–teach–test","Present–practise–produce","Grammar-translation","Total Physical Response"],"answer":0,"explanation":"Test–teach–test starts by finding out what learners can already do, teaches what is missing, and checks again, so teaching responds to actual needs.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1041","question":"While reading a story, a Class 8 teacher asks, ‘Why did the writer say “It might rain” here and not “It will rain”? What difference does it make?’ The teacher is mainly treating grammar as:","options":["A system of choices that writers use to express meaning","A set of rules to be memorised for examinations","A list of errors that students must avoid","Something that should be taught only through translation"],"answer":0,"explanation":"Asking why a writer chose a form treats grammar functionally, as a resource for making meaning, here degrees of certainty, rather than as rules in isolation.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1042","question":"A Class 9 student writes, ‘I am knowing him since my childhood.’ Which analysis of the sentence is most accurate?","options":["Only a spelling error: ‘knowing’ should be written with a double ‘n’","Only a preposition error: ‘since’ should be ‘from’, as in ‘from my childhood days’","Two errors: stative ‘know’ in the progressive, and present for present perfect","Only an article error: ‘the’ should replace ‘my’ before ‘childhood’"],"answer":2,"explanation":"‘Know’ is a stative verb not normally used in the progressive, and a state continuing from the past to now needs the present perfect: ‘I have known him since my childhood’. ‘Since’ is correct.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1043","question":"In a ‘Find someone who…’ activity, Class 6 students move around asking, ‘Have you ever visited the Taj Mahal?’ and ‘Have you ever eaten a jackfruit?’ to fill in a survey sheet with names. This activity mainly shows that:","options":["Grammar can only be practised properly through written exercises","A structure can be practised through purposeful communication","Question forms should be taught through translation into Hindi","Speaking practice is useful only for advanced learners of English"],"answer":1,"explanation":"Learners repeat the present perfect question many times, but for a real purpose (finding people), combining practice of form with meaningful interaction.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1044","question":"A Hindi-speaking Class 5 child says, ‘Please open the light’ and ‘Close the fan.’ These errors most likely arise from:","options":["Overgeneralisation of an English grammar rule","Lack of knowledge of the English tense system","A slip of the tongue that the child can self-correct","Transfer of word combinations from the home language"],"answer":3,"explanation":"Hindi uses ‘kholna’ and ‘band karna’ with lights and fans; the child transfers these collocations into English. Teaching ‘switch on / switch off’ as chunks addresses it.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1045","question":"A Class 3 teacher asks children to say ‘butterfly’ in their own languages (titli, prajapati, phulpakhru…) and makes a multilingual word chart. Which is the main pedagogical value?","options":["It mainly helps the teacher learn the children’s languages for later use","It values children’s languages and links the new word to known concepts","It replaces the need to teach the English word, since children know the concept","It is useful only in classes where every child speaks a different language"],"answer":1,"explanation":"Using home languages as a resource validates children’s identities, anchors the English word to a known concept and builds awareness of how languages compare.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1046","question":"Which task best shows whether a Class 8 student can actually use the word ‘reluctant’?","options":["Describing a situation in which someone felt reluctant and why","Matching ‘reluctant’ with ‘unwilling’ in a list of synonym pairs","Writing the dictionary meaning of ‘reluctant’ accurately from memory","Spelling ‘reluctant’ correctly in a dictation of new words"],"answer":0,"explanation":"Describing a situation requires using the word appropriately in context, which tests productive knowledge; definitions and matching test only recognition.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1047","question":"Class 4 children play ‘word antakshari’, in which each child says an English word that begins with the last letter of the previous word. Which statement about this game is most accurate?","options":["It is pure entertainment and has no real value for learning a language","It mainly develops reading comprehension of long texts in an enjoyable way","It builds vocabulary recall and attention to spelling in a low-anxiety way","It mainly develops handwriting, as children must write each word quickly"],"answer":2,"explanation":"The game makes children retrieve known words quickly and attend to how words end and begin, in an enjoyable setting; it does not involve reading texts or writing.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1048","question":"A structure such as the past tense is introduced in Class 3 in simple stories, revisited in Class 5 with irregular verbs, and again in Class 7 with the past continuous and past perfect. This organisation of grammar is called:","options":["A linear syllabus, where each item is completed once and never revisited","A lexical syllabus, organised only around high-frequency words","A notional-functional syllabus, organised only around language functions","A spiral approach, returning to items with growing depth and complexity"],"answer":3,"explanation":"A spiral curriculum (Bruner) returns to topics at increasing levels of complexity, matching how language is acquired gradually rather than mastered in one go.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1049","question":"Read the sentence: ‘Unlike his timid brother, Raju was audacious and spoke up before the whole village.’ The clue that helps a reader guess ‘audacious’ is mainly a:","options":["Definition clue, since the word is defined in the sentence","Synonym clue, since a word with the same meaning appears","Example clue, since an example of the word is listed","Contrast clue, since ‘unlike’ sets it against ‘timid’"],"answer":3,"explanation":"‘Unlike his timid brother’ signals the opposite of timid, and the action of speaking up confirms it; the word itself is never defined.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1050","question":"A Class 7 student writes: 'Camels grew humps because they needed to store water in the desert.' Which misconceptions does this sentence contain? 1. An animal develops a feature because it needs it. 2. The camel's hump is a store of water. 3. Animals have features suited to where they live.","options":["1 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"The 'need causes the trait' idea is a common teleological misconception, and the hump actually stores fat, not water. Statement 3 is the correct idea of adaptation, not a misconception.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1051","question":"Drawing a food chain, many students draw the arrow from the lion to the deer, 'because the lion eats the deer'. The best way for the teacher to deal with this is to:","options":["Mark it wrong and tell them to reverse all the arrows before the next class","Accept it, since the direction of the arrows does not matter in a food chain","Discuss what the arrow means, energy flowing from eaten to eater, and let them redraw","Avoid arrows altogether and ask students to write the animals as a simple list in order"],"answer":2,"explanation":"The error comes from reading the arrow as 'eats' rather than 'is eaten by / energy goes to'. Making the meaning of the symbol explicit fixes the confusion at its root.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1052","question":"Many Class 8 students believe that all microorganisms are harmful. Which activity would best help them revise this belief?","options":["Showing pictures of diseases caused by bacteria, viruses and fungi and how they spread","Setting milk to curd and dough to rise, and discussing what caused the changes","Asking students to memorise a list of useful microbes and the products they make","Telling students that only some microbes cause disease"],"answer":1,"explanation":"Making curd and raising dough lets students see microbes doing useful work. Pictures of disease would only confirm the misconception, and a list is easy to forget.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1053","question":"Students say that water left in a saucer in the sun 'disappears' and 'is destroyed'. Which activity most directly shows them where it goes?","options":["Measuring how long the water takes to disappear on a hot sunny day and on a cool cloudy day","Repeating the activity with salt water and seeing what is left behind","Keeping a second saucer in the shade and comparing how quickly it dries","Covering water in the sun with an inverted glass and watching droplets form inside it"],"answer":3,"explanation":"Droplets on the inner surface show that the water has turned into vapour and can condense back. Measuring time or changing conditions does not show where the water goes.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1054","question":"Students believe that when a candle burns, the wax 'just disappears'. Which pair of activities best shows that it turns into other substances?","options":["Holding a cold glass over the flame to see droplets, and testing the gases with lime water","Weighing the candle before and after burning to see how much mass is lost","Lighting a second, identical candle to see whether it burns in the same way and for as long","Putting out the flame with an inverted glass and watching the smoke rise"],"answer":0,"explanation":"Water droplets and milky lime water show that burning produces water vapour and carbon dioxide, so the wax has changed into gases. Weighing only confirms the candle got lighter, which fits 'disappears'.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1055","question":"Some students argue that dissolving salt in water is a chemical change because 'the salt disappears and cannot be seen'. Which activity best helps them reconsider?","options":["Dissolving more salt to find out how much the water can hold","Tasting the solution to check that the salt is still there","Evaporating the solution and getting the salt back","Adding sugar to another glass of water and comparing"],"answer":2,"explanation":"Recovering the same salt by evaporation shows that no new substance was formed, which is the test of a physical change. Tasting shows that salt is present but does not address whether it changed.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1056","question":"A student believes that a shadow is 'the reflection of the object on the ground'. Which observation best challenges this idea?","options":["A shadow becomes longer in the evening when the sun is low in the sky","A red ball's shadow is dark, not red, and falls on the side away from the light","A shadow is formed only when there is a source of light shining directly on the object","The shadow of a tall tree is larger than that of a small plant nearby"],"answer":1,"explanation":"A reflection would show the object's colour; a shadow is dark because the opaque object blocks light. Its position, opposite the source, also shows it is caused by blocked light.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1057","question":"Most Class 7 students think that the image in a plane mirror is formed on the surface of the mirror. Which activity best helps them locate the image correctly?","options":["Drawing the image on the surface of the mirror with a marker to fix its position","Measuring the size of the mirror and comparing it with the size of the image","Telling them clearly that the image is formed behind the mirror, not on it","Placing a lit candle before a glass sheet and moving an unlit one behind it until it seems lit"],"answer":3,"explanation":"The unlit candle seems to burn only when it sits where the image is, behind the glass at the same distance as the object. This gives direct evidence of the image's position.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1058","question":"Students in Class 8 think that sound can travel through empty space, because 'we can hear the thunder from the sky'. Which activity or resource best addresses this?","options":["A string telephone, then a bell-in-a-jar demonstration as the air is pumped out","Listening to thunder and counting the seconds after the lightning flash to find its distance","Measuring the loudness of different sounds with a sound-level app","Asking students to memorise the rule that sound needs a medium"],"answer":0,"explanation":"The string telephone shows sound travels through a material, and the bell jar shows sound fading as air is removed. Thunder reaches us through air, not empty space.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1059","question":"A student insists that stars are smaller than the moon, 'because they look so tiny'. Which activity is most helpful?","options":["Showing a chart of the planets in order of their distance from the Sun","Comparing a nearby torch with a distant street lamp at night","Telling students that stars are very far away and so look small","Showing a photograph of the night sky with the moon and many stars"],"answer":1,"explanation":"Seeing that a large, distant lamp can look smaller than a small, nearby torch helps students understand that apparent size depends on distance, so stars can be huge yet look tiny.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1060","question":"Students say that pressure depends only on how hard you push. Which activity is most suitable to show the role of area?","options":["Pushing a heavy box and then a light box across the same floor with the same effort","Pushing a ball gently and then hard to see how far it rolls","Pressing a pin into a board point-first and then head-first, with the same effort","Pulling a rope in tug-of-war with two teams of different strength"],"answer":2,"explanation":"The same force pushes the pointed end in but not the flat head, so the effect depends on area as well as force. The other activities show force but not area.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1061","question":"Many students think that respiration happens only in the lungs and is the same as breathing. Which activity best challenges this idea?","options":["Counting breaths per minute before and after exercise and drawing a bar graph","Drawing and labelling the human respiratory system from the textbook diagram","Blowing into lime water through a straw to show that breathed-out air turns it milky","Keeping yeast in sugar solution and passing the gas it gives off through lime water"],"answer":3,"explanation":"Yeast has no lungs, yet it respires and releases carbon dioxide; this shows respiration is a cellular process, while breathing is only gas exchange in animals with lungs.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1062","question":"A Class 6 student says a dry seed is non-living because 'it does not move or eat'. The best response from the teacher is to:","options":["Have students keep soaked seeds on moist cotton and observe them for a week","Tell the student firmly that seeds are living and ask him to note it in his notebook","Agree with the student, since a dry seed shows none of the signs of life","Ask the student to draw a seed and label its parts, such as the coat and embryo"],"answer":0,"explanation":"Watching a seed germinate shows that it was alive in a dormant state. Students' own observations give stronger reasons to revise the idea than the teacher's statement.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1063","question":"Students in Class 8 believe that all metals are hard solids. Which teaching step best widens their concept?","options":["Showing more iron, copper and aluminium objects and asking students to tap them","Asking them to memorise the properties of metals listed in the textbook","Showing mercury, a liquid, and sodium, soft enough to cut with a knife","Telling them that most metals are hard, so their idea is basically right"],"answer":2,"explanation":"Examples that do not fit the narrow idea, such as liquid mercury and soft sodium, show that hardness is not a defining property of metals.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1064","question":"Students believe that all acids are dangerous and burn the skin. Which activity best broadens their idea?","options":["Showing a video of acid burns so that students learn to handle acids safely","Testing lemon juice, curd, vinegar and tamarind with a natural indicator","Asking them to memorise a list of acids found in the school laboratory","Telling them that only strong acids such as sulphuric acid are dangerous"],"answer":1,"explanation":"Finding that foods they eat every day are acidic shows that acids differ in strength and many are safe. The video would only confirm the misconception.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1065","question":"Students say that water that looks clear is always safe to drink. Which approach best addresses this belief?","options":["Showing that alum makes muddy water clear, which proves clear water is safe","Telling them to drink only bottled water, whatever its source or appearance","Testing the water with litmus paper to find out whether it is safe to drink","Explaining that germs are invisible, so clear water may still need boiling"],"answer":3,"explanation":"Clarity removes only visible particles; invisible microbes can remain. Alum or litmus does not show whether water is free from germs.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-1066","question":"A student says that an elephant must have much bigger cells than an ant because it is a much bigger animal. Which statement should the teacher help the student reach?","options":["Size depends mainly on the number of cells, not on the size of each cell","Bigger animals have bigger cells in all their organs, in proportion to body size","All cells in all organisms are exactly the same size, whatever the organism","Larger animals have fewer but much larger cells, which makes them stronger"],"answer":0,"explanation":"Cells of large and small animals are of broadly similar size; a large animal is large because it has far more cells. This links cell theory to students' everyday reasoning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1067","question":"To find out how children think about force, a researcher shows a series of pictures (a book on a table, a ball in flight, a car parked on a slope) and asks the child at each picture, 'Is there a force here? Why?' This diagnostic technique is called:","options":["Concept cartoon discussion","Interview-about-instances","Free word association test","Sociometry"],"answer":1,"explanation":"In the interview-about-instances technique, a learner is asked to explain whether a concept applies in each of a set of pictured situations. It reveals the reasoning behind their answers.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1068","question":"Assertion (A): Children's alternative conceptions in science should be treated as starting points for teaching rather than as mistakes to be penalised. Reason (R): Such ideas are often based on everyday experience and have their own internal logic.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because alternative conceptions make sense to children in terms of their experience, they must be engaged with and reshaped; penalising them simply drives them underground.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1069","question":"While teaching weather, a teacher hears students say, 'Clouds are made of smoke' and 'Rain falls because clouds get holes in them.' What should she do first?","options":["Give the correct explanation at once so that the wrong ideas do not spread","Ignore these ideas, since they are not in the textbook and will confuse others","Ask for their reasons and record the ideas on the board as hypotheses to test","Tell students to read the textbook chapter on weather and correct themselves"],"answer":2,"explanation":"Eliciting and recording students' ideas as hypotheses respects their thinking and gives the class something to test, for example by making a 'cloud' with warm water and ice and seeing what condenses.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1070","question":"A student claims that a heavier object always floats less well than a lighter one. Which pair of experiences best challenges this?","options":["A heavy steel ship floats, but a light steel nail sinks","A leaf floats and a stone sinks when both are put in water","A wooden block and a plastic button both float in a bucket","A feather and a pin are dropped in the air from the same height"],"answer":0,"explanation":"The heavy ship floats because its shape displaces a large volume of water, while the small nail sinks; this breaks the link between weight alone and floating.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1071","question":"Students say that winter clothes are made of 'warm' materials and summer clothes of 'cool' materials. Which investigation best tests this idea?","options":["Feeling woollen and cotton cloth with the hand to judge which is warmer","Wrapping hot-water bottles in wool and cotton and timing how fast each cools","Asking parents which clothes keep them warm in winter and cool in summer months","Reading the labels of sweaters and shirts to see what each is made of"],"answer":1,"explanation":"Comparing cooling rates shows that wool slows heat loss better (it traps air), rather than being 'warm' itself. A fair, measured test is better evidence than touch, which feels temperature differences unreliably.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1072","question":"A Class 7 teacher finds that students who can explain why metals feel cold also claim that a woollen blanket 'gives out heat'. What does this pattern suggest for her teaching?","options":["The students are careless, so they should simply be tested more often","Wool and metal must be taught in separate years so the ideas do not mix","The two ideas are unrelated, so each must be memorised as a separate fact","They lack a general idea of heat flow that they can apply to both cases"],"answer":3,"explanation":"Students often hold context-bound ideas; the same principle (heat flows from hot to cold, at rates set by conductors and insulators) explains both cases, and the teacher should help them see that link.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1073","question":"Students believe that a plant's mass comes from the water and minerals it takes from the soil. Which question, discussed after the willow tree story, would push their thinking further?","options":["'How much water does a plant need every day to stay healthy?'","'Which minerals do plants get from the soil, and in what amounts?'","'What does the plant take in from the air that adds to its mass?'","'Why do plants need sunlight to stay green and grow taller?'"],"answer":2,"explanation":"Most of a plant's dry mass comes from carbon dioxide taken from the air during photosynthesis. Directing attention to the air opens up the key idea students usually miss.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1074","question":"A Class VII teacher in Nagpur divides a chapter on India's major soils into four parts. Each member of a home group takes one part, meets with members of other groups who have the same part, and then returns to teach it to the home group. What is the main purpose of the meeting with members who share the same part?","options":["To let fast learners finish early and rest while others catch up","To decide which of the home groups will get the highest marks for the chapter","To master their part together and plan how to teach it to their home group","To copy notes from the best student in that meeting, word for word"],"answer":2,"explanation":"In the jigsaw method, the 'expert group' meeting lets students master their piece through discussion and prepare to teach it, so every home group gets accurate content. It is not a competition or a copying session.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1075","question":"In a Class VI group project on 'Our local market', Shalini did almost all the work while three others did nothing, yet all four got the same marks. According to Johnson and Johnson, which essential element of cooperative learning was mainly missing?","options":["Individual accountability","Heterogeneous grouping","Competition between groups","Teacher lecture before group work"],"answer":0,"explanation":"Individual accountability means each member's contribution and learning is checked, for example through individual tasks or random reporting. Without it, 'free riders' can hide behind one hard worker.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1076","question":"For a Class V maths puzzle, a teacher gives each of four group members a different clue card; no one is allowed to show their card, only read it aloud, and the puzzle cannot be solved without all four clues. This design mainly builds:","options":["Group processing","Individual competitiveness","Positive interdependence","Social loafing"],"answer":2,"explanation":"When the group can succeed only if every member contributes, members depend on one another in a positive way. Group processing is reflection on how the group worked, which happens after the task.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1077","question":"In Student Teams-Achievement Divisions (STAD), team scores are based on how much each member improves over his or her own past performance rather than on raw marks. What is the main reason for this rule?","options":["It makes marking quicker, since the teacher only records improvement","It ensures that the team with the highest-scoring students always wins the prize","It allows weaker students to be left out of the team score entirely","Every member, whatever their ability, can contribute equally to the team score"],"answer":3,"explanation":"Improvement points mean a low achiever who improves a lot helps the team as much as a high achiever, which creates equal opportunity for success and makes the team care about everyone's learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1078","question":"A Class IV teacher asks, 'Why do you think birds build nests in trees?', gives everyone a minute to think silently, then lets them discuss with a partner, and finally invites a few pairs to share. What is the main advantage of this structure?","options":["It reduces the number of questions the teacher must ask during a lesson","All children get time to think and rehearse, so even shy ones can contribute","It makes sure that only correct answers are shared with the whole class","It replaces the need for whole-class discussion, as pairs settle the answer themselves"],"answer":1,"explanation":"Think-pair-share builds in individual thinking time and a safe rehearsal with a partner, which raises the quality and spread of participation. It leads into, not replaces, whole-class discussion.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1079","question":"At the end of a group activity, a Class VIII teacher asks each group to discuss: 'What did we do well as a team today? What should we do differently next time?' This reflects which element of cooperative learning?","options":["Positive interdependence","Individual accountability","Promotive interaction","Group processing"],"answer":3,"explanation":"Group processing is the group's reflection on how well it worked together and how to improve; it is what lets cooperative skills grow over time.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1080","question":"Assertion (A): Seating students in groups of four and giving each group a worksheet is enough to ensure cooperative learning. Reason (R): Cooperative learning needs deliberately structured interdependence, individual accountability and social skills.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is false, but R is true","A is true, but R is false"],"answer":2,"explanation":"Sitting together is only group seating; without structure, one child may do the work while others watch. R names what turns group work into cooperative learning, and so shows that A is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1081","question":"Consider the following statements about forming groups for cooperative learning: 1. Mixed-ability (heterogeneous) groups are generally recommended for most cooperative tasks. 2. Groups should always be formed by letting friends sit together, so that there is no conflict. 3. Groups may occasionally be formed by interest or need for a specific purpose. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Heterogeneous groups bring diverse ideas and peer support, and purpose-based groups have their place. Always grouping by friendship tends to exclude some children and reinforce cliques, so statement 2 is wrong.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1082","question":"A Class VI teacher finds that in group work some students let others do everything. Which combination of steps best reduces this 'free rider' problem?","options":["Make groups larger, so that there is more help available for everyone","Rotating roles, a short individual quiz and choosing the presenter at random","Give the group mark only to the group leader, who then shares it out","Stop group work and return to individual seatwork for the rest of the school term"],"answer":1,"explanation":"Clear roles, individual checks and random reporting all make each person's learning visible. Larger groups make loafing easier, not harder.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1083","question":"In a Class V class, a teacher assigns group roles of reader, recorder, timekeeper and reporter. She notices that girls are always chosen as recorders and boys as reporters. What should she do?","options":["Keep the same roles all year, since children work best in the role they are good at","Remove all roles, since roles create stereotypes","Assign roles herself and rotate them regularly, so every child practises every role","Allow only boys to be timekeepers and only girls to be readers"],"answer":2,"explanation":"Rotating roles lets each child develop all the skills and breaks gender stereotyping. Fixed roles lock children into patterns, while removing roles loses the structure they provide.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1084","question":"Assertion (A): In peer tutoring, the tutor also gains academically, not only the tutee. Reason (R): Explaining a concept to someone else makes the tutor organise, clarify and fill gaps in his or her own understanding.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Teaching requires structuring knowledge, anticipating questions and finding examples, which deepens the tutor's understanding. This is why tutors benefit, as R explains.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1085","question":"A Class III teacher pairs Kiran, who can solve simple subtraction with borrowing, with Babli, who can almost do it but needs help at one step. Babli then solves the next problems on her own. Which idea best explains why this pairing worked?","options":["Piaget's view that children learn only through solitary exploration of objects","Skinner's idea that each correct answer must be reinforced with a reward","Kohler's idea of insight, which comes suddenly without any help from others","Vygotsky's idea that a more able peer can scaffold a child within her ZPD"],"answer":3,"explanation":"Babli was within her ZPD: able with help, not yet alone. A more knowledgeable other (here a peer) scaffolded the step until she could manage independently.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1086","question":"In a Class VI reading group, students take turns leading discussion of a passage using four strategies: predicting what comes next, asking questions, clarifying difficult words or ideas, and summarising. The teacher models first and then gradually hands over. This approach is known as:","options":["Jigsaw","Reciprocal teaching","Round-robin reading","Programmed instruction"],"answer":1,"explanation":"Reciprocal teaching (Palincsar and Brown) uses the four strategies of predicting, questioning, clarifying and summarising, with the teacher's role passing gradually to students. Round-robin reading is simply reading aloud in turns.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1087","question":"A Class VII teacher holds a quiz where only the top-scoring group gets a prize, and groups hide answers from each other. Which statement best evaluates this structure?","options":["It is cooperative learning, since students work together within their groups","It is the best structure for all learning, since competition always increases effort","It is individualistic learning, since each student's marks are recorded separately","It is competitive; occasional contests are fine, but relying on them blocks sharing"],"answer":3,"explanation":"When one group's success means others' failure, the goal structure is competitive even if students sit in groups. Constant competition tends to demotivate those who rarely win and reduce helping.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1088","question":"For a complex Class VIII science investigation, a teacher forms groups of ten students each so that 'more heads are better than one'. What problem is she most likely to face?","options":["Social loafing, since in large groups some members contribute little","Too much individual accountability, since every member is closely watched","Lack of diverse ideas, since large groups tend to think alike","Excessive competition among members of the same group for the leader's role"],"answer":0,"explanation":"Effort per person tends to drop as group size grows (social loafing), and with ten members many get no real role. Groups of about three to five usually work best for such tasks.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1089","question":"During a group task in Class VI, two members argue strongly about which explanation of the phases of the moon is correct. What is the most appropriate teacher action?","options":["Separate the two students immediately and put them in different groups for the rest of the task","Tell them the correct answer at once so that the argument ends and work continues","Help them test both ideas with a ball-and-torch model and argue about ideas, not people","Give both students a low mark for not cooperating, to discourage such arguments"],"answer":2,"explanation":"Disagreement about ideas can drive learning (constructive controversy) when students are guided to use evidence and respectful talk. Splitting them, ending it with the answer or penalising them wastes the opportunity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1090","question":"Tara, a Class V student who uses a wheelchair and is excellent at drawing, is in a group making a poster about local birds. How should the teacher plan her participation?","options":["Let Tara watch the group, since moving around the room is difficult for her","Let her draw the birds, using her strengths, and keep materials within her reach","Give Tara a separate individual task so that she is not a burden on the rest of the group","Ask the group to complete the poster and then add Tara's name to it as well"],"answer":1,"explanation":"Inclusive cooperative learning gives every member a real, valued role and removes physical barriers. Watching, separate work or token credit all exclude her from genuine participation.","difficulty":"moderate","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1091","question":"How should a Class VII teacher assess a cooperative group project fairly?","options":["Give the same mark to everyone in the group, since they worked as a single team","Give marks only for how neat and attractive the final product looks on display","Allow the group leader alone to decide each member's marks, since she saw the work","Combine a group mark for the product with checks of each student's own learning"],"answer":3,"explanation":"Fair assessment of group work values both the joint product and each member's learning, keeping individual accountability. A single shared mark or a leader's judgement can hide free riders or bias.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1092","question":"Before group work, a Class IV teacher draws a chart with two columns, 'Looks like' and 'Sounds like', and asks children to suggest what 'listening to your partner' looks and sounds like (eyes on speaker; 'I agree because...'). What is she doing?","options":["Explicitly teaching a social skill needed for cooperative learning","Wasting time that should be used for content","Assessing children's knowledge of the lesson content","Creating a competition between children who listen and those who do not"],"answer":0,"explanation":"Cooperative skills such as listening and disagreeing politely must be taught deliberately; a T-chart makes the skill concrete. Johnson and Johnson list social skills as an essential element.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1093","question":"In a Class V maths class, each group member gets a number from 1 to 4. Groups discuss a problem until all members can explain the answer, and then the teacher calls out a number at random; that member from each group answers. What does this strategy mainly ensure?","options":["Only the brightest child in each group needs to understand the problem","The group with the fastest and brightest member always wins the round","Every member must understand, since anyone may be called to answer","Children do not need to discuss with one another before answering"],"answer":2,"explanation":"Numbered Heads Together combines group support with individual accountability: because the reporter is random, the group must make sure everyone understands.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1094","question":"Class VI students are giving feedback on each other's story drafts. Which instruction from the teacher is most likely to make peer feedback useful?","options":["'Give each story a mark out of ten and write the mark at the top.'","'Write whatever you like about your friend's story, as long as it is honest.'","'Point out all the spelling and punctuation mistakes you can find in it.'","'Using the checklist, name one strength and one specific way to improve it.'"],"answer":3,"explanation":"Peer feedback works when it is guided by criteria and is specific, kind and actionable. Marks alone or error hunting give little help for revision.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1095","question":"A school in Nashik sets up a programme in which Class VII students, including some who are themselves weak readers, read with Class III children twice a week. Which outcome is most likely, according to research on cross-age tutoring?","options":["Only the Class III children benefit, since the Class VII students already know how to read","Both gain: younger children get attention, and tutors gain practice and confidence","Neither group benefits, since only trained teachers can teach reading well","The older weak readers will feel embarrassed and should be removed from the programme"],"answer":1,"explanation":"Cross-age tutoring gives tutees individual support, while tutors (even low achievers) practise skills at an easy level in a respected role, which builds esteem. Excluding weaker older readers removes those gains.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1096","question":"Match each classroom move with the element of cooperative learning it builds. P. The group cannot finish unless each member contributes a part. Q. The teacher randomly picks one member to explain the group's answer. R. Groups reflect on how well they cooperated. S. The teacher models how to disagree politely. Elements: 1. Social skills; 2. Group processing; 3. Individual accountability; 4. Positive interdependence.","options":["P-4, Q-3, R-2, S-1","P-3, Q-4, R-2, S-1","P-4, Q-3, R-1, S-2","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Needing every member's part is positive interdependence; random reporting is individual accountability; reflecting on teamwork is group processing; modelling polite disagreement teaches social skills.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1097","question":"A Class VIII teacher deliberately mixes students of different castes, religions and genders in cooperative groups working towards a common goal, with each having an equal role. What outcome does research on intergroup contact predict?","options":["More conflict, since mixing different social groups always creates tension","No change in attitudes, since prejudice is learnt only at home and cannot really shift","Better academic marks only, with no effect on how students view each other","Reduced prejudice, since the contact is between equals working towards shared goals"],"answer":3,"explanation":"Allport's contact hypothesis holds that contact reduces prejudice when groups have equal status, common goals, cooperation and support from authority, conditions that cooperative learning provides.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1098","question":"While groups in a Class V class work on a task, what should the teacher mainly be doing?","options":["Moving among groups, observing, asking questions and helping without taking over","Sitting at her desk checking notebooks, since the children are working on their own","Standing at the front and explaining the answer so that groups do not make mistakes","Leaving the room, since group work runs itself and children work better alone"],"answer":0,"explanation":"During group work the teacher monitors and intervenes judiciously as a facilitator, gathering evidence of learning and supporting progress. Withdrawing or giving answers both undermine the activity.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1099","question":"A classroom model of the solar system shows the sun and the planets as balls of similar size placed a few centimetres apart. The most important point for the teacher to keep in mind is that:","options":["models confuse children and should never be used to teach EVS topics","the model is accurate, so children can rely on it fully for sizes","it cannot show real sizes and distances, so its limits must be discussed","only a costly model would show the correct sizes and distances of the planets"],"answer":2,"explanation":"Every model simplifies; a model at true scale would not fit in a room. Discussing what the model shows and what it distorts prevents children taking its sizes and distances literally.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1100","question":"A Class 4 teacher teaches the parts of a flower only with a printed chart. The main limitation of this approach is that:","options":["children cannot handle real flowers or see their variety and 3-D form","charts are not allowed in EVS classes under the NCF 2005 guidelines","charts are too colourful and distract children from the lesson's content","the chart will make the lesson too long for a single forty-minute period"],"answer":0,"explanation":"A chart shows one idealised flower in two dimensions. Real flowers of different kinds give first-hand, multisensory observation, which a chart can only supplement.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1101","question":"Looking at a wall map of India, a Class 5 child says that Jammu and Kashmir is at the ‘top’ so it must be the highest place, while Tamil Nadu is ‘at the bottom’ and therefore low. This idea mainly arises from:","options":["a lack of interest in maps and geography lessons","a lack of the drawing skill needed to copy maps","the map being too small to show the heights of places clearly","treating ‘north’ on a map as meaning ‘up’ or higher"],"answer":3,"explanation":"A map’s top is a convention for direction, not height. Children often confuse north with ‘up’; the teacher should make that convention explicit.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1102","question":"What is the strongest reason for children to grow seeds in class rather than only watch a time-lapse video of germination?","options":["Videos are not allowed in primary schools under most state guidelines","It gives first-hand observation over real time, which a video compresses","Seeds are cheaper than a projector, so growing them saves the school money","Children cannot understand videos at all until they reach upper primary"],"answer":1,"explanation":"Direct observation across days builds patience, recording and questioning, and gives a true sense of time. A video is useful, but it is second-hand and can distort how long change takes.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1103","question":"Consider these statements about ICT in primary EVS: I. It can bring distant environments, such as deserts and oceans, into the classroom. II. It should replace direct experience wherever it is available. III. Images taken uncritically from the internet can carry stereotypes. Which are correct?","options":["I only","II and III only","I and III only","I, II and III"],"answer":2,"explanation":"ICT widens access to what children cannot see directly, but it complements rather than replaces first-hand experience, and its images need critical selection.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1104","question":"Assertion (A): Teaching–learning material should be used with a clear learning purpose. Reason (R): Material alone, however attractive, does not ensure that children learn. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Because learning depends on what children do with the material, it must be chosen and used for a specific purpose. R explains A.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1105","question":"A school receives a costly science kit, and the head teacher keeps it locked in the office so that it does not get damaged. The best critique is that:","options":["the kit should be returned, since primary children cannot use such expensive equipment","the kit should be shown to children only on inspection days, to keep it new","only the teacher should touch the kit, during demonstrations at the front","material is meant to be handled; children should learn to use the kit with care"],"answer":3,"explanation":"Unused material teaches nothing. Children can be taught to handle equipment responsibly, and some wear is expected.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1106","question":"In one 40-minute EVS period, a teacher displays fifteen different charts about animals. The main problem is that:","options":["charts should be used only in language classes, never in EVS periods","too many materials overload children, so none can be used meaningfully","the charts should all be about one animal so children are not confused","children should have drawn all fifteen charts themselves beforehand"],"answer":1,"explanation":"More material is not better; each item should serve a purpose and leave time for children to observe and talk. Fifteen charts in one period crowd out thinking.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1107","question":"A Class 4 teacher plans to have children catch butterflies and pin them on a board for a display. A better alternative that also meets the EVS aim of concern for living things is to:","options":["observe butterflies in the school garden, record what they do, and leave them free","buy dead butterflies from a shop so that no butterfly is killed by the class","show the finished pinned board without telling children how the butterflies were caught","ask children to catch the insects at home instead of in the school garden"],"answer":0,"explanation":"Observing live animals in their setting supports learning and care for living beings. Killing animals for display goes against the concern EVS aims to build.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1108","question":"A Class 3 teacher gives groups picture cards showing wheat growing in a field, harvesting, threshing, grinding at a chakki and a roti being made, and asks them to arrange the cards in order and say who does each step. The main learning here is:","options":["memorising the names of farm tools such as the sickle, the plough and the chakki","drawing skills, since children later copy the pictures on the cards","the sequence from field to plate and how many people we depend on for food","the price of wheat in the market and how it changes with seasons"],"answer":2,"explanation":"Sequencing the cards builds an understanding of process and of the interdependence of farmers, workers and families, which is central to the ‘Food’ theme.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1109","question":"For a Class 3 lesson on food, children bring small samples of grains and pulses from home. Which statement about this is most accurate?","options":["Pictures would be better, since real grains create a mess in class","It works only in rural schools, where grains are easily available at home","It is useful only for children whose families grow these crops","Real objects allow multisensory learning and link the lesson to home"],"answer":3,"explanation":"Children can touch, smell and compare real grains, and the material comes from their own kitchens. This works in any school.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1110","question":"A diorama of a forest bought for a Class 4 class shows a tiger, a deer, a camel and a penguin together. The most appropriate response is that:","options":["it is fine, since children only need to see a variety of animals together in one place","material must be checked for accuracy, as mixed habitats create misconceptions","the diorama should be kept in the classroom but used only for decoration","the penguin and camel can be ignored, since children will not notice them"],"answer":1,"explanation":"Inaccurate material teaches errors; camels and penguins do not share a forest with tigers. Teachers must check what material conveys before using it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1111","question":"Children in a Class 3 class in southern Rajasthan speak Bhili at home, while the EVS textbook is in standard Hindi. Which statement best describes this situation?","options":["The textbook’s language may be a barrier, so the teacher should bridge it via Bhili","The textbook should be withdrawn from these schools until a Bhili one is printed","Children should be told to speak only Hindi in class so they learn it faster","The language of the textbook makes no real difference to how well children learn EVS"],"answer":0,"explanation":"A textbook in an unfamiliar language limits access; NCF 2005 asks teachers to use the home language as a resource. Banning it or ignoring the gap harms understanding.","difficulty":"hard","source":"CTET Paper 1 · REET Level 1"},
  {"id":"cdp-pedagogy-subjects-1112","question":"Which worksheet task best supports EVS learning in Class 3?","options":["Fill in the blanks with words from the chapter on plants around us.","Match the names of plants with the descriptions given in the chapter, as in a key.","Look at two plants in your courtyard, draw them and write how they differ.","Copy the first paragraph of the chapter neatly into your notebook."],"answer":2,"explanation":"The task sends children to observe, draw and compare real plants. The others only rework the text.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1113","question":"What is the best reason for Class 4 children to make their own charts of birds seen around the school, instead of the teacher buying a printed chart?","options":["It saves the school money that would be spent on printed charts","Children’s charts are always more accurate than those printed by publishers","Printed charts are not allowed in primary classrooms under NCF 2005","Observing, choosing what to show and organising it is itself the learning"],"answer":3,"explanation":"The process of making the chart, which involves observing, deciding and arranging, builds understanding. Cost is a side benefit; accuracy is not guaranteed.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1114","question":"Which use of flashcards in EVS is LEAST in line with NCF 2005?","options":["Sorting picture cards of animals into groups and explaining the groups","Flashing animal names again and again until children can repeat them","Using picture cards to tell a story about a journey","Arranging cards of a plant’s growth in sequence"],"answer":1,"explanation":"Rapid drilling of names is rote memorisation. The other uses ask children to classify, narrate or sequence.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1115","question":"Consider these statements about teaching materials for children with special needs in EVS: I. Materials should be adapted to the needs of each child. II. The same material works equally well for all children. III. Low-cost tactile materials can be made locally. Which are correct?","options":["I and III only","I and II only","II only","I, II and III"],"answer":0,"explanation":"Inclusive teaching adapts materials, and tactile materials need not be costly. Assuming one material suits all ignores differences, so II is wrong.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1116","question":"Class 5 children are making a collection of leaves of trees around the school. Which instruction best combines learning with concern for the environment?","options":["Pluck one fresh leaf from every tree you see on the way to school","Bring as many leaves as possible; the biggest collection wins a prize","Collect fallen leaves, note each one’s tree, and press them in old newspaper","Buy printed pictures of leaves from the market and paste them neatly in a project file"],"answer":2,"explanation":"Using fallen leaves avoids harming trees while still allowing observation and recording. A competition for quantity encourages damage.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1117","question":"While a teacher shows day and night with a globe and a torch, a Class 5 child asks, ‘Then why don’t people at the bottom fall off?’ The best response recognises that:","options":["the question is off-topic and should be left for a higher class","the child has misunderstood the globe and should look at it again","globes are misleading and should not be used for this topic","the model cannot show gravity, so its limits should be discussed"],"answer":3,"explanation":"Every model leaves things out; acknowledging the limits and taking up the child’s question turns a gap in the model into a learning opportunity.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1118","question":"A Class 5 teacher says, ‘The heart is like a pump.’ A child asks whether the heart has a motor and runs on electricity. This shows that:","options":["the child is being mischievous and should be asked to stay on topic","analogies help but have limits, which the teacher should discuss","analogies should never be used in EVS, as they always confuse","the child is not ready to learn about the heart until a later class"],"answer":1,"explanation":"Children may carry every feature of an analogy over to the real thing. Discussing its limits keeps the analogy useful without creating new misconceptions.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1119","question":"A Class 5 teacher uses newspaper reports about floods in the region during the ‘Water’ theme. The most important caution is to:","options":["choose age-suitable content and discuss where the information comes from","use only national newspapers, since local papers are often less reliable on floods","avoid newspapers, because they are not textbooks approved for EVS","read the reports aloud in full without stopping for discussion"],"answer":0,"explanation":"Newspapers bring real, local issues into class but can carry disturbing images or errors; age-appropriateness and critical reading are the key cautions.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1120","question":"Assertion (A): An EVS lesson without any teaching–learning material can never be effective. Reason (R): Children also learn through talk, questions and their own experiences. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"Discussion of children’s experiences can be very effective without material; so A is false while R is true, and R in fact argues against A.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1121","question":"Class 5 children make a rain gauge from a cut plastic bottle and a ruler instead of using a bought one. The main benefit is that:","options":["a bought rain gauge is inaccurate for measuring local rainfall","bought instruments are not permitted in government primary schools for safety","it is cheap, and making it shows children how the measurement works","it can be thrown away after one use, so nothing needs storing"],"answer":2,"explanation":"Improvised apparatus is low-cost and transparent: children see why the reading means what it means. Bought instruments are not inaccurate or banned.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1122","question":"A Class 2 teacher performs a puppet show on cleanliness while children watch. How can she get the most learning from the puppets?","options":["Perform the same show every day so that children remember the message well","Let children make puppets and perform short scenes from their own lives","Use only ready-made puppets from the market, as they look more real","Ask children to write a summary of the show in their notebooks"],"answer":1,"explanation":"Children learn more by creating and performing than by watching. Repetition or written summaries keep them passive.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1123","question":"Match each material with the purpose it serves best: 1. Real seeds 2. Map of the locality 3. Time-lapse video 4. Role-play props. a. Showing slow changes that cannot be seen within class time. b. First-hand observation of texture and germination. c. Understanding locations and routes. d. Taking on the viewpoints of different people.","options":["1-b, 2-c, 3-a, 4-d","1-a, 2-c, 3-b, 4-d","1-b, 2-d, 3-a, 4-c","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"Real seeds give direct observation, a map shows place and route, time-lapse shows slow change, and props support taking on roles.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1124","question":"A teacher teaches 46 + 27 first with base-ten blocks, then with drawings of sticks and dots, and finally with the written algorithm, which children write next to their drawings. Why should the drawings stay beside the written steps at this last stage?","options":["So that each written step, like the carried 1, links to the action it records","So that slow learners can copy the answer from the drawing whenever they get stuck","Because drawings are more accurate than written numbers for young children","Because the written algorithm should not be used on its own until Class 5"],"answer":0,"explanation":"In the concrete–pictorial–abstract sequence the bridge is the key: linking each symbol to the action it records gives the algorithm meaning. Without the link children learn the symbols as rote steps.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1125","question":"Children follow the teacher's instructions step by step with base-ten blocks and get correct answers, but cannot say why they exchanged ten ones for a ten. What does this show?","options":["Base-ten blocks are unsuitable for primary children and should be dropped","Blocks alone do not carry the idea; children must talk about what their actions mean","The children need much more time with the blocks before any talk about them","The teacher should switch to the written method at once, since the blocks have failed"],"answer":1,"explanation":"Materials used mechanically become another rote procedure. Understanding comes when children think and talk about why they act, for example why ten ones can be swapped for one ten.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1126","question":"A Class 3 child still counts out counters for 7 + 8. Which approach is most suitable?","options":["Take the counters away at once so that she is forced to work out sums mentally from now on","Let her keep using counters for every addition fact, however long it takes, until Class 5","Keep counters but teach derived facts from doubles, so she needs them less","Give her a list of addition facts to memorise at home, with a test every Monday"],"answer":2,"explanation":"Materials should be faded gradually as children develop mental strategies. Removing them suddenly causes anxiety, while relying on them for ever holds the child back; derived facts from doubles are the bridge.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1127","question":"To build the concept of a parallelogram, a teacher shows many parallelograms that differ in side lengths, angle sizes and position on the page. Which of Dienes's principles is she applying?","options":["Perceptual variability (multiple embodiment)","Dynamic principle","Constructivity principle","Mathematical variability"],"answer":3,"explanation":"Mathematical variability means varying the features that are not essential to the concept (side lengths, angles) while keeping the essential ones (two pairs of parallel sides). Perceptual variability means using different materials for the same concept.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1128","question":"A teacher in a government school with very few materials wants to use hands-on activities in maths. Which approach best reflects good practice?","options":["Use low-cost local items like seeds, bottle caps and sticks for clear maths purposes","Wait until the school buys commercial maths kits, since home-made aids give inaccurate ideas","Use only the textbook and blackboard, since real activities always need expensive aids","Ask each child to buy a set of base-ten blocks so that every child can handle them"],"answer":0,"explanation":"A teaching aid's value lies in how purposefully it is used, not in its cost. NCERT and NCF 2005 encourage locally available, low-cost materials.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1129","question":"To compare 2/3 and 3/5, which material most directly supports the reasoning?","options":["Two paper circles of different sizes, one cut into thirds and the other cut into fifths","Equal-length fraction strips cut into thirds and fifths, placed one below the other","Counters arranged in two separate piles of 2 and 3, to compare the numerators","A clock face showing 2 o'clock and 3 o'clock to compare parts of an hour"],"answer":1,"explanation":"Comparing fractions needs the same whole; equal-length strips lined up show that 2/3 reaches further than 3/5. Circles of different sizes break the equal-whole condition.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1130","question":"A Class 7 student solves problems well at home but goes blank in timed maths tests. What is the best response from the teacher?","options":["Give her many more timed tests so that she slowly gets used to the pressure of exams","Tell her parents that she is not putting in enough effort to prepare for tests","See it as maths anxiety and use untimed, low-stakes checks of her reasoning","Move her to an easier section of the class, where tests are shorter and simpler"],"answer":2,"explanation":"Anxiety takes up the working memory needed for problem solving, so performance drops under pressure. Low-stakes, untimed assessment and attention to process help her show and build what she knows.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1131","question":"Which statement about a teacher's own attitude to mathematics is best supported?","options":["A teacher's attitude has no effect on children as long as the syllabus is covered","Only the textbook shapes children's attitude to mathematics, not the teacher","Teachers who dislike maths are always stricter, which improves children's results","An anxious teacher can pass on the idea that maths ability is a fixed talent"],"answer":3,"explanation":"Children pick up the beliefs and feelings their teachers show. An anxious teacher may avoid discussion and signal that maths is for the gifted, which increases children's anxiety.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1132","question":"Which feedback is most likely to build a growth mindset in a child who has just solved a hard problem?","options":["‘When the first method failed, you tried another. That is how problems get solved.’","‘You are so clever; maths just comes naturally to you, as it does to all toppers.’","‘Well done, you are easily the best in the class and nobody else could have solved it.’","‘Good, but your friend did it faster, so try to beat her time on the next one.’"],"answer":0,"explanation":"Praising effort and strategy tells the child that ability grows with work. Praising fixed cleverness or comparing with others makes children afraid of failing later.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1133","question":"A student's mistake on the blackboard makes the class laugh. What is the best response from the teacher?","options":["Ask the student to sit down and call someone who knows the correct method","Say, ‘Let's see what she was thinking. Which part of her method is right?’","Ignore the mistake, quietly write the correct answer and continue the lesson","Warn the class not to laugh and move on quickly to the next question"],"answer":1,"explanation":"Treating errors as information for learning protects the child and helps the whole class understand. Public embarrassment is a known cause of maths anxiety.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1134","question":"A teacher remarks, ‘Girls are good at neat work; boys are better at maths.’ What does this most likely lead to?","options":["Better results for girls, who will try harder to prove the teacher wrong","No effect, since children ignore such remarks made in passing by teachers","Lower confidence and participation in maths among girls over time","More interest in maths among both boys and girls, since it sparks competition"],"answer":2,"explanation":"Stereotypes shape children's beliefs about who can do maths. NCF 2005 calls for gender-fair classrooms in which all children get the same opportunities and expectations.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1135","question":"Assertion (A): Timed drills of number facts can increase anxiety in some children. Reason (R): Fluency with number facts has no importance in mathematics.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Time pressure can raise anxiety, so A is true. But fluency with facts does matter; it frees working memory for problem solving and is better built through games and strategies. R is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1136","question":"A teacher writes multiple-choice items in which each wrong option matches a known misconception, for example choosing ‘0.25’ as larger than ‘0.5’. What is the main use of such items?","options":["Ranking children by their total marks to decide who goes into the top section","Making the test harder for bright students by adding tempting wrong options","Saving time in checking copies, since every item has a single fixed answer","Finding which misconception each child holds so re-teaching can target it"],"answer":3,"explanation":"Options built from real errors make the test diagnostic: a child's choice shows what she thinks, not just that she is wrong, so the teacher knows what to re-teach.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1137","question":"Which evidence tells a teacher the most about a child's understanding of subtraction with regrouping?","options":["The child uses base-ten blocks to explain why 52 − 27 needs a ten broken up","The child's total marks in the unit test on subtraction with regrouping","Whether the child finished the subtraction worksheet before everyone else","The parents' report that all subtraction homework was done correctly at home"],"answer":0,"explanation":"An explanation with materials shows the reasoning behind the procedure. Marks, speed and parental reports show results or effort, not understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1138","question":"A Class 5 teacher keeps a portfolio for each child with drafts, solved problems, mistakes later corrected, and short reflections. What is its main value?","options":["It reduces the number of tests the teacher must set for the report card","It shows the child's growth in understanding over time","It is mainly for showing parents the neatest work their child has done","It replaces the need for any classroom observation of how children work"],"answer":1,"explanation":"A portfolio collects evidence of learning across time, including revisions and reflection, which a single test cannot show. It supports both the teacher's and the child's view of progress.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1139","question":"For an open-ended maths problem, a teacher uses a rubric with criteria such as understanding of the problem, choice of strategy, explanation and accuracy. Why is this better than marking only the final answer?","options":["It allows the teacher to give everyone full marks just for attempting the problem","It is quicker to use than checking each final answer in a large class of forty","It credits different valid approaches and gives specific feedback on each part","It removes the need for children to reach an answer, as only the method counts"],"answer":2,"explanation":"Open-ended problems have many valid routes. A rubric values reasoning and communication as well as accuracy and tells the child what to improve; it does not ignore the answer.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1140","question":"Two children each score 7 out of 10 on a fractions test. All of Arun's errors are copying slips; all of Bina's come from believing that a bigger denominator means a bigger fraction. What should the teacher conclude?","options":["Both need exactly the same revision work, since their scores on the test are equal","Arun needs more help than Bina, since careless slips are harder to fix than ideas","Both should repeat the whole chapter on fractions from the beginning with the class","Equal scores hide different needs: Bina needs re-teaching, Arun needs to check work"],"answer":3,"explanation":"A total score hides what lies behind it. Error analysis shows that Bina holds a misconception that will affect later work, while Arun's understanding is sound.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1141","question":"Children swap their solutions and write ‘two stars and a wish’, two things done well and one thing to improve, on a partner's work. What is the main purpose?","options":["To learn to judge work against criteria and to learn from other methods","To reduce the teacher's work of checking every child's notebook after class","To find out who is the best in the class by comparing the stars received","To give marks for the report card based on what partners write"],"answer":0,"explanation":"Peer assessment helps children understand what good work looks like and to see other strategies, so they become better at checking their own work.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1142","question":"A child writes 3/4 + 1/2 = 4/6. Which written feedback best supports learning?","options":["‘Wrong. Fractions cannot be added like this. See me after class with your notebook.’","‘You added tops and bottoms. Shade 3/4 and then 1/2 of one strip. How much is shaded?’","‘Good try! Keep practising fraction sums and you will surely get them right next time.’","‘0/1. Revise the chapter on fractions and redo all the exercise questions at home.’"],"answer":1,"explanation":"Useful feedback names the error and gives a next step the child can act on; shading shows the answer is 5/4. ‘Good try’ or a grade alone tells the child nothing about what to change.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1143","question":"Which statement about assessment reflects NEP 2020?","options":["Assessment should mainly test how much of the prescribed textbook a student remembers","Board examinations should be removed altogether and replaced by school-based tests","Assessment should test competencies such as analysis rather than rote memory","Assessment should be done only at the end of the year, to reduce pressure on students"],"answer":2,"explanation":"NEP 2020 calls for regular, formative, competency-based assessment that tests higher-order skills. It keeps board exams but wants them to test core understanding rather than memorisation.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1144","question":"A teacher sits with one child, gives her a task, and keeps asking ‘How did you do that?’ and ‘What if…?’ without correcting her. What is the main purpose of this one-to-one interview?","options":["To teach the correct method privately, away from the rest of the class","To test how quickly the child can solve the task without any help","To give the child a mark in private so that she is not embarrassed in class","To find out how the child thinks and the strategies behind her answers"],"answer":3,"explanation":"A task-based (clinical) interview is diagnostic: by probing without correcting, the teacher learns the child's reasoning, which written answers alone often hide.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1145","question":"Which question best tests a Class 4 child's understanding of place value rather than recall?","options":["Make the largest and smallest 4-digit numbers using 3, 0, 8 and 5 once; explain why","Write the place value and the face value of the digit 7 in the number 4,732","Write the number 4,732 in words, and then write it again in its expanded form","Write the numbers that come just before and just after 4,732, and the number ten more"],"answer":0,"explanation":"The task needs reasoning about how a digit's position changes its value, including where 0 can go (the smallest is 3,058, not 0,358). The other questions can be answered by routine.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1146","question":"A Class 4 maths test for a village school has many word problems about metro cards and shopping malls. What is the main concern?","options":["The numbers used in such problems are too large for Class 4 children","Unfamiliar contexts test background knowledge as much as maths skill","Word problems should not be used in Class 4, as reading is still weak","The questions should be in English only, to match city schools' papers"],"answer":1,"explanation":"Children may fail because the situation is strange to them, not because they lack the maths. Fair assessment uses contexts from children's lives, as NCF 2005 recommends.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1147","question":"A diagnostic test shows that six children cannot regroup in subtraction. The teacher works with them in a small group using base-ten blocks while the others do extension problems. This is best described as:","options":["streaming children into fixed ability groups for the rest of the year","summative assessment followed by a grade for each group","remedial teaching based on diagnosis, within differentiated instruction","drill and repeated practice of the subtraction algorithm with the weaker group"],"answer":2,"explanation":"Diagnosis followed by targeted re-teaching of a specific gap is remedial teaching; doing it alongside extension work for others differentiates instruction. It is a temporary, flexible grouping, not permanent streaming.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1148","question":"Which of these statements about manipulatives in mathematics are correct? I. Manipulatives are useful only for slow learners. II. Children need to reflect on and talk about what they do with materials. III. The same concept should be shown with several different materials. IV. Materials should be withdrawn gradually as children link actions to symbols.","options":["I and II only","I, III and IV","II and III only","II, III and IV"],"answer":3,"explanation":"Materials help all learners, including the most able, so I is false. Reflection, multiple embodiments and gradual fading towards symbols describe sound use of manipulatives.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1149","question":"A Class 7 science test for Hindi-medium students is set in complex English, and many students who explain the concepts well orally score poorly. The main problem with the test is that:","options":["Its reliability is low, because students' scores would change a lot if it were retaken","Its validity is low: it measures English reading, not understanding of science","Its objectivity is low, because different examiners would mark the answers differently","Its practicability is low, because it takes far too long to administer and mark"],"answer":1,"explanation":"A test is valid if it measures what it claims to measure. Here language skill, not science understanding, is driving the scores, so the inferences drawn from them are invalid even if the marking is consistent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1150","question":"Two science teachers mark the same set of project reports and their marks differ widely for the same reports. The most effective step to reduce this problem is to:","options":["Let only the senior teacher mark the reports, since she has more experience","Use a common rubric and discuss a few sample reports together before marking","Give every report the average of the two teachers' marks and move on","Replace project work with written tests, which are easier to mark consistently"],"answer":1,"explanation":"Wide differences between markers show low inter-rater reliability; shared criteria and moderation with samples make marking consistent without giving up the value of project work.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1151","question":"A teacher checks whether each student can set up a circuit in which two bulbs glow, marking each student simply as 'can do' or 'not yet', regardless of how others perform. This assessment is:","options":["Norm-referenced, because it compares each student's performance with the others","Summative, because it is a final grade awarded for the whole year","Criterion-referenced, because performance is judged against a fixed standard","Diagnostic, because it is used to identify students with learning disabilities"],"answer":2,"explanation":"Judging each student against a set standard of performance, not against classmates, is criterion-referenced assessment.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1152","question":"In a Class 8 practical examination, the viva consists only of questions such as 'Name this apparatus' and 'What is the formula of water?' Which change would most improve it?","options":["Asking more questions of the same type, so that the viva covers all the apparatus","Removing the viva altogether, since the written record shows enough","Asking students to read out their written records to the examiner","Asking students why they got their result and what they would change next time"],"answer":3,"explanation":"A viva should probe understanding of the experiment, such as how the result relates to the method and sources of error; naming apparatus tests only recall.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1153","question":"Before setting a term test in science, a teacher prepares a blueprint, a table showing how many marks go to each chapter, each learning objective and each type of question. The main purpose of the blueprint is to:","options":["Make sure the test covers content and objectives in the planned proportions","Make the test more difficult by including questions from every single chapter","Allow students to predict the questions and prepare for them in advance","Reduce the number of questions the teacher has to set and mark"],"answer":0,"explanation":"A blueprint is a plan that ensures the test samples the content and objectives as intended, which improves its content validity and balance.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1154","question":"A Class 7 teacher often skips activities to 'finish the syllabus'. Which guiding principle of NCF 2005 most directly argues against this practice?","options":["Making examinations more rigid and centralised so that all schools follow one standard","Shifting learning away from rote methods and connecting it to life outside school","Increasing the number of chapters in each textbook to cover more science","Giving more homework so that the full syllabus is covered on time"],"answer":1,"explanation":"NCF 2005 calls for learning connected to life outside school and away from rote methods; activities are how this happens in science, not an optional extra after the syllabus.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1155","question":"Which features should a good upper primary science textbook have, in the spirit of NCF 2005? 1. Activities followed by open-ended questions. 2. The answers to every activity printed beside it. 3. Examples drawn from different regions and communities of India. 4. Boxes inviting students to think, discuss and find out more.","options":["1 and 2 only","2, 3 and 4 only","1, 3 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"Printing the answers beside each activity turns it into confirmation and discourages students from thinking about their own observations. The other features support inquiry and inclusion.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1156","question":"A school library keeps children's science magazines and story books about science in Hindi and English, and a teacher encourages students to read them. The main purpose of such supplementary reading is to:","options":["Replace the textbook as the main source of questions for the examination","Increase the number of facts students must memorise for the term tests","Keep students busy and quiet during free periods in the library","Encourage curiosity and reading about science beyond the textbook"],"answer":3,"explanation":"Supplementary materials widen exposure, build reading habits and nurture curiosity; they complement the textbook and are not meant for rote learning.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1157","question":"Students build a working periscope from cardboard and two mirrors. Compared with studying a chart of a periscope, this is more effective mainly because:","options":["It involves students actively and shows how the mirrors' angles make it work","It takes more time than a chart, and so keeps students busy for the whole period","It is less expensive than buying a printed chart of a periscope from the market","It needs no explanation from the teacher, since the model explains itself"],"answer":0,"explanation":"Making a working model engages hands and minds: students must place the mirrors correctly, and adjusting them reveals the principle of reflection.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1158","question":"At the school science exhibition, students explain their projects to parents and the local community. Apart from showing their work, the main educational value of this is that it:","options":["Allows the school to rank students for prizes in front of their parents","Saves the teacher the effort of assessing each project separately herself","Builds communication skills and links school science with the community","Is required by the examination board as part of the final science marks"],"answer":2,"explanation":"Explaining work to an outside audience builds communication and confidence, and brings science into the community, which NCF 2005 encourages.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1159","question":"A group of Class 8 students plan a two-month project on whether the water quality of a local pond changes after a festival. Which actions of the teacher are appropriate? 1. Helping them sharpen the question and decide what to measure. 2. Doing the measurements for them to save time. 3. Helping them plan how to record and present data. 4. Writing the conclusion so that it matches the expected result.","options":["1 and 3 only","1, 2 and 3 only","2 and 4 only","1, 3 and 4 only"],"answer":0,"explanation":"In project work, the teacher is a facilitator who guides the framing, planning and recording; doing measurements or writing conclusions for students takes the learning away from them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1160","question":"Assertion (A): Virtual laboratories should completely replace hands-on practical work at the upper primary stage. Reason (R): Virtual laboratories allow experiments to be repeated many times safely.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Virtual labs have real advantages, such as safe repetition, but they cannot develop handling skills or the experience of real materials, so they should supplement, not replace, hands-on work.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1161","question":"A teacher plays a 20-minute video on the digestive system without stopping, and then moves to the next topic. Which change would make the video most effective for learning?","options":["Playing a longer video with more information so that nothing is left out","Playing it twice in a row so that students remember the details better","Pausing for prediction and discussion, and following it with an activity","Asking students to copy the narration into their notebooks while it plays"],"answer":2,"explanation":"Video becomes a learning tool when it is used actively, with pauses for prediction, questions and discussion; passive viewing is little better than a lecture.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1162","question":"A student says that a ball rolls down a slope 'because of gravity'. The teacher responds, 'What do you mean by gravity here? Would the ball roll if the slope were on the moon?' This kind of question is best described as a:","options":["Rhetorical question","Leading question","Closed recall question","Probing question"],"answer":3,"explanation":"A probing question follows up an answer to make the student clarify, justify or extend it, revealing whether the term 'gravity' is understood or only named.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1163","question":"Which homework task is most in line with the aims of upper primary science teaching?","options":["Observing the moon each night for a week and drawing its shape","Copying the answers to all the chapter's exercises neatly from a guide book","Writing the definitions of ten new terms five times each to fix them in memory","Learning the chapter's summary by heart for a test the next day"],"answer":0,"explanation":"Observation-based homework extends inquiry beyond the classroom and builds skills of observing and recording; copying or memorising builds rote habits.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1164","question":"While teaching 'water', a teacher uses rainfall data to make graphs, discusses who controls water in the village and how it is shared, and studies the water cycle and water-borne diseases. This approach is best called:","options":["Disciplinary, subject-centred approach","Spiral curriculum approach","Thematic, interdisciplinary approach","Programmed instruction approach"],"answer":2,"explanation":"Organising learning around a theme that draws on several subjects (science, mathematics, social science) is the thematic, interdisciplinary approach. A spiral approach revisits a topic at increasing depth across years.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1165","question":"A science teacher realises during a lesson that she herself has believed that 'heavier objects fall faster'. The most professional response is to:","options":["Avoid teaching falling objects in future so that she does not mislead students","Continue to teach her belief, since students will not notice the difference","Ask a colleague to teach the topic every year in her place","Test the idea, read about it, discuss it with peers and correct her teaching"],"answer":3,"explanation":"Teachers often share students' misconceptions; reflective practice means checking one's ideas with evidence and updating one's teaching, which also models a scientific attitude.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1166","question":"A teacher notices that many students read the measuring cylinder wrongly. She decides to investigate systematically. Arrange the steps of action research in order: P. Plan and carry out a new way of teaching the reading  Q. Identify the problem clearly  R. Evaluate whether the readings have improved  S. Form hypotheses about the causes, such as the eye not being level with the liquid","options":["Q, P, S, R","S, Q, P, R","Q, S, R, P","Q, S, P, R"],"answer":3,"explanation":"Action research moves from identifying a classroom problem, to hypothesising causes, to trying a planned action, to evaluating its effect, which may lead to another cycle.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1167","question":"A teacher wants to find out whether her lesson actually changed students' ideas about plants' food. Which design gives the best evidence?","options":["Giving the same diagnostic questions, with reasons, before and after the lesson","Asking students at the end of the lesson whether they understood it well","Counting how many students completed all of the lesson's activities","Giving a single test only at the end of the term on the whole chapter on plants"],"answer":0,"explanation":"Comparing the same items before and after, with students' reasons, shows whether their ideas actually shifted. Self-reports and participation counts say little about conceptual change.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1168","question":"Which feedback on a student's lab report is most likely to improve her learning?","options":["'Good work. 7/10. Your diagram is neat and your handwriting has improved a lot.'","'Your conclusion ignores trial 3. What does that result suggest about it?'","'Poor. Write more neatly next time and underline all the headings in red.'","'Wrong conclusion. See the textbook and copy the correct conclusion from page 42.'"],"answer":1,"explanation":"Effective feedback is specific, refers to the work and guides the next step, prompting the student to think. Marks or general remarks do not tell her how to improve.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1169","question":"A teacher allows students to pursue their own questions during science periods but finds that many questions cannot be investigated in school. Which is the best way to handle this?","options":["Forbid students from asking questions that are not covered anywhere in the textbook","Answer all such questions herself so that no class time is wasted on them","Help turn the questions into testable ones and keep the rest for later research","Ignore such questions, since they cannot be answered with school equipment"],"answer":2,"explanation":"Turning a broad question ('Why do plants grow?') into a testable one ('Do bean seeds grow taller in light or in the dark?') teaches an important inquiry skill, while other questions can be kept for reading or research.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1170","question":"A teacher's science class consists of first-generation learners whose parents work as farm labourers. Which strategy is most likely to make science meaningful to them?","options":["Using examples from urban homes shown in the textbook, to widen exposure","Starting from their experience of farming, soil, seeds and weather","Giving extra notes to memorise, since they get little help at home","Teaching only the basic definitions, since they lack exposure to science"],"answer":1,"explanation":"Children's own experiences are rich resources; linking science to farming and weather they know well makes it meaningful and values their knowledge, in line with NCF 2005.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1171","question":"A teacher wants to check what students already know about electricity before starting the chapter. Which tool is most suitable?","options":["A short questionnaire asking students to predict and explain simple circuits","The end-of-chapter test from the textbook, given on the very first day of the chapter","A list of definitions to be learnt by heart before the chapter begins","A project report on all the electrical appliances in their homes"],"answer":0,"explanation":"A pre-assessment asking for predictions and explanations reveals prior knowledge and misconceptions, so teaching can start from where students are.","difficulty":"hard","source":"CTET Paper 2 · KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-1172","question":"Which of the following is a genuine limitation of using only paper-pencil tests in science? 1. They cannot directly assess skills of handling apparatus. 2. They cannot assess any higher-order thinking. 3. They give little evidence of scientific attitudes such as cooperation. 4. They can be badly affected by students' reading level.","options":["1 and 2 only","2 and 3 only","1, 2, 3 and 4","1, 3 and 4 only"],"answer":3,"explanation":"Well-designed written questions can assess higher-order thinking, so 2 is false. But they cannot show manipulative skills or attitudes directly, and reading difficulties can distort them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1173","question":"Which of the following are commonly identified problems in the teaching of social science in Indian schools?\n1. It is often seen as a 'soft' subject of lesser value than science.\n2. Textbooks and teaching are loaded with information to be memorised.\n3. Most schools devote too much time to field work and projects.\n4. Content is often taught without connection to children's lives.","options":["1, 2 and 3 only","2, 3 and 4 only","1, 2 and 4 only","1 and 3 only"],"answer":2,"explanation":"Low status, information overload and disconnection from children's lives are widely noted problems, including in NCF 2005. The reality is the reverse of statement 3: field work and projects are usually too rare, not too frequent.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1174","question":"Assertion (A): Teaching centred on board examinations is a major cause of rote learning in social science.\nReason (R): When examinations reward reproducing textbook answers, teachers and students concentrate on memorisation.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"What examinations reward shapes what is taught and learnt. If recall earns marks, memorisation becomes the rational strategy, so R explains A.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1175","question":"A teacher in a government school in Uttar Pradesh has 62 students in Class VII and wants everyone to take part in a discussion on 'Why do some families migrate to cities?'. Which strategy suits her situation best?","options":["Drop the discussion, since it is impossible to manage in such a large class","Use think-pair-share and small groups with roles, then take one point from each","Let only the front-bench students discuss while the rest listen and take notes","Hold the discussion only with the toppers after school, when the room is quieter"],"answer":1,"explanation":"Large classes call for structures that let everyone think and speak at once, such as pairs and small groups, before sharing with the whole class. Limiting discussion to a few students leaves most of the class out.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1176","question":"A village school in Jharkhand has no wall maps, projector or library. Which plan best uses low-cost resources to teach Class VI students about their district?","options":["Wait until the school receives a government grant for wall maps and a projector","Ask students to buy atlases from the city so that each child has a proper printed map","Teach the topic only from the textbook, since resources are not available","Draw a ground map with chalk, use old newspapers and invite local elders to share"],"answer":3,"explanation":"The community and local surroundings are rich, free resources. A ground map, newspapers and local resource persons make learning concrete even without equipment.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1177","question":"To introduce federalism in Class X, a teacher compares the country to a school in which the principal, the house captains and the class monitors each handle certain matters. Which evaluation of this analogy is most accurate?","options":["It is a useful start, but she must also show where the comparison breaks down","It is a perfect explanation of federalism and needs no further discussion","It is wrong, since analogies should never be used in teaching social science topics","It is useful only for primary classes, as Class X needs formal definitions"],"answer":0,"explanation":"Analogies help bridge to abstract ideas, but every analogy breaks somewhere. In a school the principal can override monitors; in a federation, powers are constitutionally guaranteed. Pointing out the limits completes the learning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1178","question":"Which of the following are reasons why many students find social science boring?\n1. It is often taught as a set of facts to be memorised.\n2. Lessons are seldom connected with students' own lives and surroundings.\n3. The subject by its nature cannot be made engaging.","options":["1 and 3 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"Boredom comes from the way social science is often taught, by rote and disconnected from life, not from the subject itself. Inquiry, discussion and local study regularly make it lively.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1179","question":"A social science teacher realises that she always praises the achievements of her own community's historical figures at length and passes quickly over those of others. What is the most appropriate step?","options":["Continue, since teachers naturally know more about their own community's history","Avoid discussing any historical figures at all, so as to remain neutral","Reflect on her own bias, use varied sources and balance different communities","Ask students from other communities to teach the class about their own figures"],"answer":2,"explanation":"Teachers bring their own social positions into class. Reflection and deliberate use of diverse sources are needed for fair teaching. Omitting all figures or handing the job to students does not address the bias.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1180","question":"A Class VII social science teacher and the mathematics teacher plan a joint lesson in which students tabulate monthly rainfall data for their town, draw bar graphs and explain the pattern of the monsoon. What is the main benefit?","options":["The social science teacher can skip the chapter on climate in her own class","Students use maths on a real geographical question and see subjects as linked","Students can be given marks in both subjects for one task, which saves teachers time","The mathematics syllabus becomes lighter, since data handling is covered"],"answer":1,"explanation":"Cross-curricular work uses skills from one subject to understand another, making both meaningful. The chapter is still taught; this is a richer way of teaching it.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1181","question":"Class VI students keep confusing latitudes with longitudes. Which approach is likely to work best?","options":["Ask them to repeat 'latitudes run east-west, longitudes run north-south' daily","Give them a list of the latitudes and longitudes of major cities to memorise","Skip the topic until Class IX, when students are mature enough for it","Use a globe or orange with lines drawn on it, and link the grid to graph paper"],"answer":3,"explanation":"Handling a model and linking the grid to familiar coordinates on graph paper builds the concept spatially. Chanting a phrase can still leave students confused about which lines are which.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1182","question":"A Class VI child says, 'Day and night happen because the sun goes around the earth.' What is the best first step for the teacher?","options":["Tell the child the correct answer and ask her to write it five times","Darken the room and let children rotate a globe in front of a torch","Say that this is a science question and not part of social science","Show a written definition of rotation and ask the child to memorise it"],"answer":1,"explanation":"A torch-and-globe model lets children see that the earth's rotation produces day and night, which directly confronts the misconception. Telling or defining does not change the child's mental model.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1183","question":"Many Class VI students believe it is hot in summer because the earth is then closer to the sun. Which piece of evidence best challenges this belief?","options":["India and Australia, about equally far from the sun, have opposite seasons","The sun looks bigger and brighter at noon than it does in the evening sky","Hill stations are cooler than the plains in summer because of their height","Deserts are hot during the day and cold at night, even in the summer months"],"answer":0,"explanation":"If distance caused seasons, both hemispheres would have summer together. Opposite seasons in the two hemispheres show that the tilt of the earth's axis, which changes the angle of sunlight and the length of the day, is the cause.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1184","question":"Class VIII students say 'the government' means only the Prime Minister and the ministers in Delhi. Which activity best widens their understanding?","options":["Ask them to memorise the list of Union ministers and their departments","Find out who repairs their street lights and runs their school, and at what level","Show a video of Parliament in session and discuss what the ministers said in the debate","Tell them that government is too large a topic for Class VIII students"],"answer":1,"explanation":"Tracing everyday services to the panchayat or municipality, the state and the union reveals the levels of government through students' own experience.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1185","question":"A Class X teacher asks groups to list what 'development' would mean for a landless rural labourer, a prosperous farmer, an urban unemployed youth and a girl from a well-off family. What is the main purpose?","options":["To show that development means only higher income for every group of people","To prove that one group's view of development is the correct one for India","To show that different people can have different, even conflicting, goals","To teach how to calculate per capita income for each of the four people"],"answer":2,"explanation":"Comparing these goals reveals that development is plural and contested: more days of work for one, freedom or dignity for another, and sometimes one person's development harms another's. Income alone does not capture it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1186","question":"Several Class VIII students say 'secular' means 'against religion'. Which response best builds the correct understanding?","options":["Tell them that secularism means people should give up religion in public life","Ask them to memorise that India is a secular state, as the Preamble of the Constitution says","Avoid the topic, since it relates to religion and may upset some families","Discuss cases where the state favours no religion yet protects religious freedom"],"answer":3,"explanation":"Indian secularism keeps a principled distance from all religions while protecting religious freedom and equality. Cases make this concrete; the 'anti-religion' idea is the misconception to be replaced.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1187","question":"A Class VII teacher uses satellite imagery software to show students the land use around their school, then zooms out to the district and the state. What should she do to make this most useful?","options":["Let students explore the software freely without any particular task","Set questions to answer, such as where farmland is turning into housing and why","Use the tool mainly to impress students with how modern the technology is","Replace all map work with satellite images, since they are more accurate than drawn maps"],"answer":1,"explanation":"Technology helps learning when tied to guiding questions. Satellite views make change in land use visible, but without a task students simply browse.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1188","question":"A Class VIII teacher shows a popular feature film about the freedom struggle. What should accompany the screening?","options":["Nothing; the film is accurate because it is about real people and events","A test on the names of the actors and the characters they played","A discussion comparing scenes with sources and why films dramatise events","A ban on discussing the film so that students are not misled by it"],"answer":2,"explanation":"Films shape popular memory. Comparing them with sources teaches students the difference between dramatisation and history and why such changes are made.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1189","question":"Class VI students in a Chennai school write that 'all people in Rajasthan live in the desert and ride camels'. What is the best way to correct this over-generalisation?","options":["Show images of Rajasthan's cities, hills and farms and let students revise it","Tell them they are wrong and give them the correct sentence to copy","Say that the statement is mostly true, so it can be accepted as it is","Skip the topic, since students in Tamil Nadu do not need to know about Rajasthan"],"answer":0,"explanation":"Evidence of variety within a region lets students revise the stereotype themselves. Simply correcting or accepting the statement leaves the habit of over-generalising unchallenged.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1190","question":"In many schools a social science period consists of the teacher reading the chapter aloud, explaining difficult words and dictating question-answers. What is the main problem with this practice?","options":["It takes too long and makes it hard to finish the syllabus on time","It keeps students passive, with no chance to inquire or connect ideas to life","It is too difficult for students to follow without a guide book","It uses too many teaching aids, which distract students from the text of the chapter"],"answer":1,"explanation":"Reading and dictation turn social science into transfer of information, with no room for questioning or thinking. This is one of the main problems NCF 2005 identifies.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1191","question":"A school in Delhi does not allow off-campus trips because of safety rules. How can a Class VII teacher still give students first-hand experience of local institutions?","options":["Tell students that first-hand experience is not really needed for this chapter","Show the textbook pictures of the post office, bank and municipal office instead","Invite local resource persons and take a supervised walk around the neighbourhood","Give students a list of local institutions and their functions to memorise"],"answer":2,"explanation":"Resource persons and short supervised walks bring the community into learning within safety limits. Textbook pictures alone do not provide first-hand engagement.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1192","question":"Assertion (A): A visit to a district court helps Class VIII students understand the working of the judiciary.\nReason (R): The Supreme Court is the highest court of appeal in India.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true but R is not the correct explanation of A"],"answer":3,"explanation":"Both statements are true. But the value of the visit comes from seeing proceedings first-hand, not from the position of the Supreme Court, so R does not explain A.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1193","question":"A Class IX teacher finds that most students think democracy simply means 'voting in elections'. Which activity would best deepen their understanding?","options":["Ask them to memorise Abraham Lincoln's famous definition of democracy word for word","Count how many general and state elections India has held since independence","Ask them to write an essay on why every citizen must vote in each election","Study cases of a free press, courts protecting rights and officials held to account"],"answer":3,"explanation":"Elections are necessary but not sufficient; rights, rule of law, free media and accountability are also essential. Cases make these features visible, whereas a definition or an essay on voting keeps the narrow view.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1194","question":"Class VI students complain that history has 'too many dates'. Which response best addresses this?","options":["Remove all dates from history teaching so that students focus on stories","Insist that students memorise every date in the chapter, since dates are history","Use timelines for sequence and duration, and expect only key landmark dates","Give extra marks to students who remember the most dates in each test"],"answer":2,"explanation":"Chronology matters, but as a framework for understanding change, not a list to memorise. Timelines and a few key landmarks give that framework; removing dates altogether would destroy the sense of time.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1195","question":"The social science periods in a Class VIII section are being taken by a teacher trained in physical education because of a vacancy. Which outcome is most likely, and what does it point to?","options":["Teaching will become more activity-based automatically, given his PE background","There is no effect, since anyone can read the textbook aloud to the class","Students will learn more because a physical education teacher is strict","Textbook-reading may take over, showing a shortage of trained subject teachers"],"answer":3,"explanation":"Without subject and pedagogical training, teachers tend to rely on the textbook and question-answer drill. A shortage of trained teachers is a recognised problem in social science teaching.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1196","question":"Which of the following statements on making social science meaningful for children are correct?\n1. Local examples help, but must be linked to wider concepts and regions.\n2. Abstract concepts are best introduced through definitions, followed by examples if time permits.\n3. Children's questions can become the starting point of an inquiry.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Linking local examples to larger ideas and building on children's questions make learning meaningful. Starting from definitions, with examples as an optional extra, reverses the concrete-to-abstract order.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1197","question":"Many Class VII students think a 'market' is only a place with shops. The teacher wants them to see that a market can also be a chain of relations, including online sales and wholesale trading. Which activity best achieves this?","options":["Trace a shirt from cotton field to buyer, noting each buyer and seller","Ask students to draw and label all the shops of their local weekly bazaar","Give them the dictionary definition of 'market' to copy and learn by heart","Ask them to list their favourite shops in town and what each one sells"],"answer":0,"explanation":"Following a product through the chain shows that markets link many buyers and sellers across places, some not physical shops at all. Drawing local shops reinforces the narrow idea.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1198","question":"Class VIII students in Kochi write reports on local fishing, share them online with a partner class in Ladakh, comment on each other's drafts and jointly publish a comparison of the two communities' livelihoods. In the SAMR model, this use of technology is best described as:","options":["Substitution","Augmentation","Modification","Redefinition"],"answer":3,"explanation":"Real-time collaboration and publishing with a distant class creates a task that was not possible without the technology, which is Redefinition. Simply typing the report would be Substitution, and adding spell-check would be Augmentation.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1199","question":"A Class VI teacher is excellent with computers and knows her science content, but she uses an impressive 3D animation that runs for the whole period while children watch silently, and they learn little. Which framework best explains the gap?","options":["TPACK, since technology, pedagogy and content knowledge must work together","SAMR, because the use was at the Redefinition level, which is too advanced","Bloom's taxonomy, because the animation was pitched at the Create level","Dale's cone, because animations sit at the top of the cone of experience"],"answer":0,"explanation":"TPACK (Mishra and Koehler) holds that effective teaching with technology needs the intersection of technological, pedagogical and content knowledge. Here the pedagogical part (active learning, interaction) was missing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1200","question":"A Class VII teacher shows text-heavy slides from the projector and reads them aloud for the whole period while students copy them. Which evaluation is most accurate?","options":["This is ideal ICT integration, since the projector is used in every period","The projector merely replaces the blackboard, and students stay passive","Projectors should never be used in classrooms, since they distract students","The slides should have even more text so that students get complete notes"],"answer":1,"explanation":"Technology adds value only when it changes what students can do or understand; reading slides is a lecture in a new medium. The problem is the pedagogy, not the projector.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1201","question":"In a Class X school without enough electrical equipment, a teacher uses a free circuit simulation in which students change resistances and watch the current change. Which statement best describes the appropriate place of such a simulation?","options":["Simulations are always better than real experiments and should replace practical work","Simulations should never be used, because children must handle real objects only","They are useful when real kits are lacking, alongside hands-on work where possible","Simulations should be shown only after the final examination, as revision"],"answer":2,"explanation":"Simulations let students test many variables quickly and visualise what cannot be seen, which is valuable; but they complement rather than replace real experience with materials and measurement.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1202","question":"A Class VI teacher in a small town assigns all homework through an online app. She later learns that a third of her students share one phone with their family or have no internet. What should she do?","options":["Continue with the app, since students must learn to manage technology somehow","Give lower marks to students who do not submit online, to encourage regular work","Ask parents to buy smartphones and data packs so that every child can use the app","Offer offline options, such as printed sheets, so no child depends on home internet"],"answer":3,"explanation":"ICT must not widen inequality; a digital divide calls for alternatives so that every child can do the work. Penalising students for lack of access is unfair.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1203","question":"A Class VII student tells his teacher that he shared his email password with a 'friend' he met in an online game and has sent him photos of himself. What is the most appropriate response by the teacher?","options":["Scold him in front of the class so that the others learn from his mistake","Take it seriously: help him stop contact, inform parents and teach online safety","Ignore it, since what happens online outside school is not the teacher's concern","Ban the student from using the computer lab for the rest of the year"],"answer":1,"explanation":"Online safety is part of digital citizenship that schools must teach; the child needs protective action and support, not shame or punishment. Possible grooming must be escalated to parents and authorities.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1204","question":"For a Class VIII project, students copy whatever the first search result says, including some false claims about a 'miracle cure'. Which teaching response is best?","options":["Teach them to check the author, date and evidence, and compare with reliable sources","Ban internet use for all projects, since online information cannot be trusted","Tell students to use only the first three search results, which are the most reliable","Allow copying as long as students paste the website link at the end"],"answer":0,"explanation":"Information literacy means evaluating sources for authority, currency, evidence and corroboration. Banning the internet or limiting to top results does not build this skill, and copying with a link is still plagiarism.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1205","question":"Consider the following statements about using digital resources in a Class VII project: 1. Students should acknowledge the sources of text and images they use. 2. Any image found online can be freely used in any way, because it is on the internet. 3. Openly licensed resources (for example Creative Commons) can be reused within their stated conditions. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"Being online does not make content free to use; copyright still applies unless a licence allows reuse. Teaching attribution and open licences builds ethical digital habits, so 1 and 3 are correct.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1206","question":"The head of a pre-primary school in Pune plans to give every four-year-old a tablet for one hour of learning apps each day, cutting outdoor and pretend play. What is the most appropriate professional advice?","options":["Support the plan, since early use of technology gives children a head start","Ban all screens completely, since technology has no place in early childhood","Support the plan, but extend tablet time to two hours for faster learning","Keep screen use short and adult-guided, and never let it replace active play"],"answer":3,"explanation":"Young children learn mainly through play, movement, talk and real objects, as NCF-FS 2022 stresses; screens can support this in small, mediated doses but should not replace it. A blanket ban ignores useful, guided uses.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1207","question":"Consider the following statements about the DIKSHA platform: 1. QR codes printed in many textbooks link to related digital content on DIKSHA. 2. DIKSHA is meant only for students and has no material for teachers. 3. Content on DIKSHA is available in several Indian languages. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"DIKSHA was launched as a national platform for teachers and later expanded to students, with QR-coded 'energised' textbooks and multilingual content. Statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1208","question":"Match each learner with the assistive technology most suited to his or her need. P. Sanya, who is blind; Q. Vikram, who has dyslexia and reads very slowly; R. Moin, who has limited hand movement due to cerebral palsy; S. Elsa, who has a severe hearing impairment. Technologies: 1. Captioned videos; 2. Screen reader software; 3. Text-to-speech and audiobooks; 4. Speech-to-text or adapted switches.","options":["P-3, Q-2, R-4, S-1","P-2, Q-3, R-1, S-4","P-2, Q-3, R-4, S-1","P-2, Q-4, R-3, S-1"],"answer":2,"explanation":"A screen reader turns on-screen text into speech or braille for a blind user; text-to-speech and audiobooks reduce the decoding load in dyslexia; speech-to-text or switches replace fine hand movements; captions give access to spoken content for a deaf learner.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1209","question":"A Class IX teacher asks students to watch a short video on photosynthesis at home and uses the class period for experiments, problem-solving and clearing doubts. Which statement about this 'flipped classroom' is most accurate?","options":["Its main benefit is that teachers no longer need to plan their lessons in detail","It frees class time for active work, but fails if students lack video access","It works only for students who already know the topic before the class","It means students teach themselves entirely, with no role for the teacher"],"answer":1,"explanation":"Flipping reserves class time for application and interaction, where the teacher's help matters most. It depends on access and on students actually viewing the material, so planning for equity is essential.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1210","question":"A Class VI teacher runs a short online quiz at the end of a lesson, and the dashboard shows that 70% of students chose the same wrong option on question 3. What is the best use of this information?","options":["Re-teach the idea, targeting the misconception that the wrong option reveals","Ignore it, since this quick quiz does not count towards the term marks at all","Remove question 3 from future quizzes, since it was clearly too difficult for them","Report the scores to parents as the term result for each child"],"answer":0,"explanation":"Instant data is valuable formative assessment: a popular wrong option points to a shared misconception, which should shape the next lesson. Ignoring or deleting it wastes the evidence.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1211","question":"Assertion (A): Adding more technology to a lesson automatically improves students' learning. Reason (R): The effect of technology on learning depends on how it is used to support pedagogy and content.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Technology is a tool; learning depends on the pedagogical design around it. R is true, and it explains why more technology does not by itself guarantee better learning.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1212","question":"A Class VII teacher has students enter two months of daily temperature data into a spreadsheet and produce line graphs, and then spends most of the period on discussing patterns. Which statement best evaluates this?","options":["It is wrong, since students must always draw every graph by hand, without exception","It is good only because it saves the teacher time in checking students' graphs","It moves time from plotting to interpreting, though graph-building must be learnt too","It is suitable only for computer classes, not for mathematics or science periods"],"answer":2,"explanation":"Spreadsheets handle repetitive plotting so that time goes to interpretation, which is the higher-level goal. Students still need to know how scales and axes work so the tool does not become a black box.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1213","question":"A Class VIII teacher plays a 40-minute documentary on the Indian freedom struggle without any pause, and then begins the next topic. How could she best use this video?","options":["Show the whole video twice in a row so that students remember more of it","Show short segments with a clear purpose, pause for questions, then discuss","Ask students to copy notes from the video while it plays, for revision","Play the video only on days when she is absent, to keep the class busy"],"answer":1,"explanation":"Video supports learning when it is purposeful, chunked and followed by discussion; continuous passive viewing leads to low retention. Note-copying while watching splits attention.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1214","question":"In a Class I classroom in a Santhali-speaking area, the teacher uses a low-cost device to play recorded folk stories in Santhali and later in the regional language, with children retelling and acting them. Which statement best supports this practice?","options":["Recorded stories in the home language are useful only for entertainment","ICT should be used only in English, since it is the language of technology","Audio devices are not suitable for children below Class V, who need a teacher","ICT can help bridge home and school languages when followed by talk and activity"],"answer":3,"explanation":"Familiar-language audio stories build listening comprehension and oral language, and the follow-up retelling makes it active. Technology serves multilingual education here rather than displacing the home language.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1215","question":"Several Class VIII students have been mocking a classmate in a class WhatsApp group with edited photos. The classmate has stopped coming to school. What is the most appropriate response?","options":["Treat it as cyberbullying, support the victim and act under school policy","Ignore it, since it happened in a private group outside school hours and premises","Advise the victim to leave the WhatsApp group and simply ignore the messages","Ban the whole class from using phones and WhatsApp for the rest of the year"],"answer":0,"explanation":"Cyberbullying affects safety and attendance at school, so the school must respond: protect the victim, hold perpetrators accountable and build digital citizenship. Telling the victim to leave or a blanket ban does not address the behaviour.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1216","question":"A Class III teacher uses a game-based app in which children answer addition facts quickly to earn stars. Which use of the app is most appropriate?","options":["Use the app instead of teaching the concept of addition with real objects","Use the app as the only maths activity every day, since children enjoy it","Use it for fluency practice after the concept is built with objects","Avoid it, since games have no place in a serious mathematics lesson"],"answer":2,"explanation":"Drill apps help with fluency and motivation, but cannot build the underlying concept, which needs concrete experience and talk. They work as a supplement, not a replacement.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1217","question":"A Class VI teacher is choosing a free learning app for fractions. Which set of criteria is most important?","options":["The app has bright colours, many advertisements and the most downloads in its category","It fits the outcome, needs real thinking, uses a familiar language and protects data","The app has the most levels and rewards, regardless of what content it teaches","The app is in English only, so that children improve their English along with maths"],"answer":1,"explanation":"Educational value (alignment, interactivity), accessibility (language) and safety (data privacy, no inappropriate ads) matter most. Popularity and rewards are not evidence of learning.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1218","question":"In a hill village of Uttarakhand with no internet but electricity and a TV in the school, which ICT choice is most appropriate for supporting learning?","options":["Postpone all ICT use until high-speed internet finally reaches the village school","Ask students to travel to the nearest town for online classes on weekends","Use educational TV, radio and offline content, followed by discussion","Use only the school's mobile data for live streaming of city classrooms"],"answer":2,"explanation":"ICT is broader than the internet; broadcast and offline media can bring good content to low-connectivity areas, and teacher-led follow-up makes it active learning. Waiting or demanding travel denies access.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1219","question":"Class V students create a short digital story with their own drawings, recorded narration and background sounds about a local festival. Which set of learnings does this mainly develop?","options":["Typing speed alone, since the whole story has to be entered on a computer","Recall of textbook facts alone, since festivals are covered in the EVS book","Language, sequencing, creativity and digital skills, rooted in their culture","Drawing skills alone, since all the rest is done automatically by the software"],"answer":2,"explanation":"Digital storytelling integrates language, planning, art and technology, with children as creators rather than consumers. It is a good example of ICT used for expression.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1220","question":"A teacher posts photographs of her Class IV students on public social media with their full names and their test marks, to show parents the class's progress. What is the most accurate evaluation?","options":["It is acceptable, since parents like to see their children's progress online","It is acceptable as long as only the toppers' names and marks are posted online","It is acceptable, since the children's faces are already known in the town","It violates children's privacy; names and marks should never be posted publicly"],"answer":3,"explanation":"Publicly linking identities with marks can shame children and exposes personal data. Responsible ICT use protects children's privacy and needs consent; posting only toppers adds comparison and humiliation.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1221","question":"A Class VI teacher uses a word processor so that students can type essays (P); then she switches on spell-check and a thesaurus to help them revise (Q); later students turn essays into hyperlinked multimedia presentations with audio for a new audience (R). In the SAMR model, P, Q and R are respectively:","options":["Substitution, Augmentation, Modification","Augmentation, Substitution, Redefinition","Substitution, Modification, Augmentation","Substitution, Augmentation, Redefinition"],"answer":0,"explanation":"Typing replaces handwriting with no functional change (Substitution); spell-check adds a functional improvement (Augmentation); redesigning the task as multimedia changes it significantly (Modification). Redefinition would need a task impossible without technology, such as live collaboration with a distant audience.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1222","question":"Consider the following statements about ICT in the classroom: 1. Technology can help teachers reach diverse learners through multiple formats such as audio, video and text. 2. Technology removes the need for teacher planning and judgement. 3. Using ICT without attention to access can widen the gap between advantaged and disadvantaged students. Which of these are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"ICT supports multiple means of representation and can be inclusive, but it still depends on the teacher's planning; unequal access can deepen inequality. Statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1223","question":"Class 5 children listen to a recorded railway announcement only to find out the platform number of the Rajdhani Express. The listening sub-skill being practised is:","options":["Listening for the gist of the whole announcement","Listening for specific information","Inferring the speaker’s attitude from intonation","Discriminating between similar sounds"],"answer":1,"explanation":"Listening for one particular detail while ignoring the rest is listening for specific information, the listening counterpart of scanning. Gist means the overall idea.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1224","question":"A teacher plays an audio story once and asks only, ‘Who are the main characters and what is the problem?’ She then plays it again with five detailed questions. The best justification for this staging is that:","options":["Children forget stories quickly, so every recording must always be played exactly twice","Detailed questions are always easier than general ones, so they should come second","Listening first for gist and then for detail avoids overload and builds understanding","It mainly gives the teacher time to prepare the next activity while the audio plays"],"answer":2,"explanation":"Staged tasks let learners build an overall framework first and then attend to details; asking for everything at once overloads working memory during real-time listening.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1225","question":"A Class 8 student understands every word when the teacher speaks slowly, but loses track in natural speech, where ‘What do you want to do?’ sounds like ‘Whaddya wanna do?’. The most useful help is practice with:","options":["Reading the transcript silently before every listening task begins","Listening only to slow, carefully read recordings until he is completely ready","Memorising the spellings of all the words used in each recording","Features of connected speech such as linking, weak forms and elision"],"answer":3,"explanation":"His word knowledge is fine; his bottom-up decoding of fast connected speech is the problem. Raising awareness of how words merge and reduce helps him segment natural speech.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1226","question":"To test listening comprehension, a Class 5 teacher plays a long recording once and asks children to write full-sentence answers to long questions while they listen. What is the main flaw in this test?","options":["The recording should have been in the mother tongue, since listening tests must avoid English","The heavy writing load contaminates the test, so it no longer measures just listening","Listening cannot be tested in a classroom at all, so only reading should be assessed","Children should first read the transcript, since unprepared listening is unfair"],"answer":1,"explanation":"A valid listening test should keep demands from other skills low, for example ticking, numbering or drawing. Here weak writers would score low even if they understood well.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1227","question":"A teacher uses a short real radio cricket commentary in a Class 9 listening lesson instead of the scripted textbook dialogue. The best reason for this choice is that real recordings:","options":["Are always easier to follow than scripted ones, because the topic is familiar to students","Follow a strict grammatical sequence, so they fit the order of the English syllabus","Have natural speed, hesitations and overlaps that learners must cope with outside class","Remove the need for pre-listening work, because students already know about cricket"],"answer":2,"explanation":"Authentic listening prepares learners for real speech; with suitable tasks even demanding material becomes manageable, though it is not easier than scripted dialogue.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1228","question":"Assertion (A): Children in Class 1 can understand stories read aloud that are well beyond the level they can read on their own. Reason (R): In the early years, listening comprehension usually runs well ahead of reading comprehension.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Young children are still learning to decode, so their understanding of spoken language is far ahead of what they can read; read-alouds use this gap to build vocabulary and comprehension.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1229","question":"Which activity is mainly fluency-focused rather than accuracy-focused?","options":["A group discussion on banning homework, with no correction during it","Reading a set dialogue aloud with careful attention to intonation","Changing sentences orally from the present into the past tense","Repeating pairs of words such as ‘ship’ and ‘sheep’ after the teacher"],"answer":0,"explanation":"Fluency activities put meaning and the flow of communication first; the others focus on producing correct forms.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1230","question":"Many Class 6 students in a Bihar school say ‘wery’ for ‘very’ and ‘vest’ for ‘west’. Which activity most directly targets the problem?","options":["Writing each confused word ten times with the correct spelling","Reading a long passage aloud quickly, without stopping at all","Minimal-pair work: hearing and saying ‘vine–wine’, ‘vest–west’","Learning the dictionary meanings of the words they confuse"],"answer":2,"explanation":"The learners’ home languages do not separate /v/ and /w/, so they need to hear and produce the contrast. Minimal pairs isolate exactly that difference.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1231","question":"What is the most realistic goal for teaching English pronunciation to students in Indian schools?","options":["A British accent, since Received Pronunciation is the world standard","Clear, intelligible speech and confidence, not a foreign accent","An American accent, since it is the variety heard most in the media","No attention to pronunciation, since only writing is examined"],"answer":1,"explanation":"English is used worldwide in many varieties; the realistic aim is intelligibility to a wide range of listeners, with attention to the sounds and stress that affect understanding.","difficulty":"hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1232","question":"Class 7 students get role cards: the shopkeeper’s card lists prices and the lowest acceptable price; the customer’s card gives a budget and items needed. They then bargain. The main purpose of this role play is to:","options":["Check whether students can recall a model dialogue word for word","Teach the spellings of all the vegetables and fruits named on the role cards","Improve students’ handwriting as they note down prices and items","Practise language for a real-life function, with an information gap"],"answer":3,"explanation":"Role cards with different information give a reason to communicate, and bargaining practises the language of a real social function such as offering, refusing and persuading.","difficulty":"moderate","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1233","question":"When a teacher asks a question to the whole class, few children answer. She switches to ‘think–pair–share’: children think alone, discuss with a partner and then share with the class. The main reason this increases participation is that it:","options":["Gives children time to rehearse ideas and lowers the fear of speaking","Lets the teacher call only on the confident children who know the answer","Cuts down the amount of speaking that each child is expected to do","Shows children the correct answer before they are asked to speak"],"answer":0,"explanation":"Thinking time and a low-risk partner rehearsal reduce anxiety and give every child something to say, so more children are ready to speak in front of the class.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1234","question":"A teacher asks, ‘Why do you think the old man gave away his land?’ and calls on a child within a second; if there is no answer she gives it herself. Research on wait time suggests that if she waits three to five seconds, the most likely result is:","options":["Students will lose interest and the pace of the whole lesson will suffer","Only the brightest few will answer, and the rest will stay silent","No change at all, since wait time affects only written answers","Longer, more thoughtful answers from more students willing to speak"],"answer":3,"explanation":"Mary Budd Rowe found that longer wait time after a question led to longer, better-reasoned answers and more participation, especially for higher-order questions like this one.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1235","question":"In a 40-minute Class 6 English period, the teacher talks for about 35 minutes, explaining the lesson in detail. From the point of view of language learning, the main problem is that:","options":["Any errors in the teacher’s English will be copied by all the students","The teacher will fall behind and fail to finish the syllabus on time","Students get almost no chance to use the language themselves","Such detailed explanations will be far too simple for the students"],"answer":2,"explanation":"Learners develop speaking through their own use of language; when teacher talk dominates, student talking time and opportunities for output almost disappear.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1236","question":"In a ‘show and tell’ session, each Class 1 child brings something from home, such as a toy or a photo, and talks about it to the class. The main value of this activity is that it:","options":["Builds confidence in speaking about familiar things to an audience","Teaches children the correct grammar of long and complex English sentences","Tests how well children can read difficult words from the board","Gives children practice in writing short paragraphs about objects"],"answer":0,"explanation":"Talking about something personal gives children content and motivation, links home and school, and develops speaking for an audience in a supportive setting.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1237","question":"Two teachers listen to the same recorded speaking task of a Class 8 student; one gives 8/10 and the other 4/10. The best step to make speaking assessment more consistent is to:","options":["Stop assessing speaking altogether, since it can never be marked fairly","Use a shared rubric with clear descriptors and compare sample ratings","Simply average the two marks and move on to the next student","Replace the speaking task with a written grammar test that is easy to mark"],"answer":1,"explanation":"Inter-rater reliability improves when raters share explicit criteria and calibrate on samples; abandoning or replacing the task would lose validity.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1238","question":"After listening to a story, Class 3 children are asked to retell it in their own words to a partner. As an assessment task, story retelling mainly shows the child’s:","options":["Handwriting and spelling of the story’s key words and names","Listening comprehension and oral expression together","Knowledge of grammatical terms used in the story","Speed of silent reading compared with classmates"],"answer":1,"explanation":"Retelling needs understanding of the story (listening) and the ability to organise and express it (speaking), so it integrates both skills in one task.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1239","question":"Which of the following is NOT a sound principle of language teaching in the spirit of NCF 2005?","options":["Accuracy must be fully achieved before children are allowed to communicate","Children need rich and varied exposure to the language, spoken and written","Language is best learnt through its use in meaningful contexts","Errors are a natural and informative part of learning a language"],"answer":0,"explanation":"Insisting on accuracy before communication delays use and raises anxiety; NCF 2005 favours meaningful use with errors treated as signs of learning.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1240","question":"Assertion (A): Listening is a passive skill, so it develops automatically and need not be taught. Reason (R): Listening involves only hearing sounds and not interpreting meaning.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are false"],"answer":3,"explanation":"Listening is an active, receptive skill in which the listener decodes sounds and builds meaning using context and prior knowledge, so it benefits from teaching. Both statements are false.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1241","question":"Consider these statements: I. Listening and reading are receptive skills. II. Receptive skills involve no active mental processing by the learner. III. Speaking and writing are productive skills. Which are correct?","options":["I and II only","II and III only","I, II and III","I and III only"],"answer":3,"explanation":"‘Receptive’ means taking in language, not being passive; listeners and readers actively predict, infer and interpret. So II is false.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1242","question":"A Class 1 teacher often has the whole class repeat new rhymes and sentence patterns together. Which evaluation of choral repetition is most accurate?","options":["It should never be used, because it comes from behaviourist drilling","It is enough by itself to develop children’s spoken language fully and quickly","It gives shy children safe practice but needs balancing with individual talk","It is useful only for teaching the spelling of new rhyme words"],"answer":2,"explanation":"Choral work builds confidence and familiarity with sounds and rhythm without singling anyone out, but it does not let children express their own meanings, so it needs to be balanced.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1243","question":"In a recording, a girl spills tea on her new dress and says flatly, ‘Oh, great!’ Students are asked how she feels. This question tests the ability to:","options":["Infer a speaker’s attitude from intonation and context","Listen for the gist, the overall idea of a long recording","Listen for specific information such as names, times and numbers","Discriminate between minimal pairs of similar sounds"],"answer":0,"explanation":"The words are positive but the tone and situation show annoyance; understanding sarcasm requires inferring attitude from intonation and context, not just decoding words.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1244","question":"A Class 9 teacher teaches phrases such as ‘Sorry to interrupt, but…’, ‘Could you say that again?’ and ‘Let me add to what Priya said…’ before a group discussion. The main purpose is to help students:","options":["Memorise polite sentences that can be reproduced in the written examination","Improve the spelling of common phrases that students often get wrong","Manage talk: take turns, ask for clarification and build on others’ ideas","Keep their turns short so that the discussion finishes within the period"],"answer":2,"explanation":"Such phrases are tools for managing interaction, part of discourse and strategic competence, which help learners take part in real discussions.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1245","question":"To assess the speaking skill of Class 3 children, a teacher asks each child to recite a poem learnt by heart. What is the main weakness of this assessment?","options":["Poems are too difficult for Class 3, so most children will fail the task","It mainly tests memory and recitation, not spontaneous speaking","It takes too little time per child to give any useful information","It actually tests writing, since the poem was first copied in notebooks"],"answer":1,"explanation":"Speaking ability means expressing one’s own meanings; recitation shows memory and pronunciation of a fixed text. Picture talk or a short conversation would be more valid.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1246","question":"Before a recorded talk, a Class 9 teacher points out phrases such as ‘firstly’, ‘on the other hand’ and ‘to sum up’, and asks students to note what follows each. The main purpose is to help students:","options":["Learn the spellings of linking words that often appear in examinations","Translate the talk into their mother tongue while they listen","Skip the details of the talk and listen only to its last part","Use signposting phrases to follow the structure of a long talk"],"answer":3,"explanation":"Discourse markers signal how a talk is organised, such as new points, contrasts and conclusions, so attending to them helps listeners follow the argument and take organised notes.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1247","question":"A teacher says, ‘I bought you a PREsent’ and then ‘Let me preSENT the winners’, and asks Class 8 students what changed besides the meaning. The point being taught is that:","options":["English spelling always shows clearly where the stress falls","Stress can change the word class and meaning of some words","Stress makes no difference at all to meaning in English","Only nouns carry stress in English words and sentences"],"answer":1,"explanation":"In pairs like ‘PREsent’ (noun) and ‘preSENT’ (verb), stress shifts with word class; spelling does not show this, so it needs explicit attention in speaking and listening.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1248","question":"Under the theme ‘Shelter’, a Class 4 EVS lesson looks at nests, burrows and anthills as well as human houses. The main reason for including animal homes is to help children:","options":["learn the names of animal homes for the end-of-term examination","see shelter as a need of all living beings, shaped by surroundings","understand that animals build stronger and better homes than humans do","fill the theme with interesting pictures to hold their attention"],"answer":1,"explanation":"Seeing that all living beings need shelter, and that homes suit surroundings, builds connections across the living world. Naming homes is recall; comparing who builds ‘better’ misses the point.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1249","question":"Class 5 children keep pieces of chapati in a dry box, a damp box and an open plate, and observe them for a week. Which question from the teacher best guides careful observation?","options":["Which of the three chapatis is the best one to eat at the end of the week?","Have you seen spoilt food at home before, and what did your family do?","What changes do you see each day in colour, smell and texture, and where?","Do you like chapati, and how many do you usually eat at each meal at home?"],"answer":2,"explanation":"The question points children to specific, comparable features over time, which is the heart of observation and recording. The others invite opinion or yes/no answers.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1250","question":"A Class 4 teacher wants children to understand that water is not shared equally. Which activity best achieves this?","options":["A role play giving some ‘families’ far more water than others, then a discussion","Reading the textbook paragraph on water scarcity aloud, with the teacher explaining","Writing an essay on ‘Save Water’ for the school wall magazine","Learning a slogan on water conservation by heart for the assembly"],"answer":0,"explanation":"Experiencing unfair distribution in a role play, then reflecting on it, builds understanding and empathy. Essays and slogans stay at the level of words.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1251","question":"Class 5 children interview elders about journeys they made fifty years ago: how they travelled, how long it took and who could afford to travel. Besides change in transport over time, this activity helps children see that:","options":["older modes of transport were always better and more comfortable than today’s","travel habits have hardly changed at all in the last fifty years","only modern, faster transport is really worth studying in EVS","who could travel depended on money, place and social factors"],"answer":3,"explanation":"Asking ‘who could travel’ draws out the social side of travel, linking history with equity. The other options are either false or narrow.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1252","question":"Which question, asked under the theme ‘Things We Make and Do’, best moves children from the product to the people behind it?","options":["How many bricks are needed to build one room of a house like ours?","Who makes our bricks, and what is their work like?","What colours and sizes are the bricks used in our school building?","Are bricks heavier than stones of the same size, and why is that?"],"answer":1,"explanation":"The theme aims at valuing workers and their conditions as well as processes. Asking about the brick-kiln workers brings that in; the others stay with the object.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1253","question":"A Class 3 teacher plans to have every child draw a family tree showing parents and grandparents. Some children in the class are living with relatives or in a children’s home. The most sensitive way to frame the task is:","options":["Draw your father’s and mother’s families, going back to grandparents.","Draw only the people who live with you in your house right now.","Draw the people who care for you and matter in your life.","Leave out the children who do not have parents, to spare them."],"answer":2,"explanation":"The open framing lets every child represent her real circle of care without exposure or exclusion. The others assume a standard family or single out some children.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1254","question":"A Class 3 teacher asks groups to invent a new game using only a ball and chalk, set its rules and teach it to another group. Under the sub-theme ‘Work and Play’, this activity mainly develops:","options":["cooperation, making and following rules, and expression","speed and accuracy in running, catching and throwing the ball","knowledge of the official rules of well-known national games","competition among children to find out who the best player is"],"answer":0,"explanation":"Designing and teaching a game requires working together, negotiating rules and explaining them. Athletic speed and official rules are not the aim.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1255","question":"In a Class 4 lesson on animals that work with people, which question best develops concern for animals?","options":["Name five animals that carry loads for people in our area.","How much weight can a bullock pull compared with a horse?","Which working animal is the strongest, and how do we know?","How are cart bullocks in our area treated, and is it fair?"],"answer":3,"explanation":"Asking children to look at how working animals are treated, and to judge it, builds empathy and ethical concern. The others are recall or facts.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1256","question":"Class 3 children list the plants used in their homes for food, medicine, festivals and building. The main learning from this activity is:","options":["the correct botanical names and families of the plants they listed","how closely people’s daily and cultural life depends on plants","which of these common plants are poisonous and should be avoided","how to grow these useful plants at home in pots and beds"],"answer":1,"explanation":"Listing uses across food, health, ritual and construction shows the many ties between people and plants. Botanical names and gardening are not the focus.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1257","question":"A teacher uses an old chart showing separate zones of the tongue for sweet, salty, sour and bitter tastes. A child puts a little sugar on the ‘bitter’ zone and says it still tastes sweet. The best response of the teacher is to:","options":["tell the child she placed the sugar on the wrong part of her tongue","ask her to repeat it carefully until she gets the result shown on the chart","accept the evidence, let others test it, and discuss why the chart is wrong","ignore it, since a chart printed by a publisher is more reliable than one child"],"answer":2,"explanation":"The ‘tongue map’ is a well-known error; taste buds for all basic tastes are spread across the tongue. Letting evidence correct printed material teaches a central habit of inquiry.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1258","question":"NCERT EVS chapters on water include stories of stepwells, community tanks and disputes over water. The main reason for including them is to:","options":["present water as a shared resource tied to community and fairness","teach children the architecture and building methods of old stepwells","prepare children for history questions that may come in later classes","show that water shortages and disputes belong only to the distant past"],"answer":0,"explanation":"The theme treats water not only as a natural substance but as something people build, share and fight over, connecting it to equity and community.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1259","question":"A Class 4 teacher asks groups to design and build, with clay and paper, a house suited to a place with heavy snowfall, and to explain their design choices. This task mainly asks children to:","options":["copy the picture of a snow house given in the textbook as neatly as possible","recall the names of the traditional houses found in different states","practise colouring, decoration and neat handwork with clay and paper","apply what they understand about climate to design something new"],"answer":3,"explanation":"Designing for given conditions and justifying choices is application and creation, a higher-order task. It goes well beyond recall or decoration.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1260","question":"Class 5 children have a simple map of their town with a scale. Which question can be answered only by using the map, not from memory?","options":["What is the name of your town, and which district is it in?","Which is your favourite place in town, and why do you like it?","Using the scale, how far is the station from school, and by which roads?","Have you ever been to the railway station, and who took you there that day?"],"answer":2,"explanation":"Measuring distance with the scale and planning a route needs the map. The others rely on memory or opinion.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1261","question":"A teacher includes the lives of pastoral communities such as the Bakarwals and Gaddis, who move with their herds, in the theme ‘Travel’. The main purpose is to:","options":["show that nomadic life is backward and that settling down is a sign of progress","show travel for livelihood and respect diverse ways of life as equally normal","teach children the exact routes shepherds use in the hills each season","encourage children to take up herding as a career when they grow up"],"answer":1,"explanation":"Such examples widen children’s idea of travel and of normal life, building respect for diversity. Calling nomadic life backward is a prejudice EVS aims to question.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1262","question":"Class 4 children list ways in which food is preserved at home, such as pickling, drying papad and sun-drying vegetables. The main pedagogical value of this is that it:","options":["links home practices with ideas about why food spoils and how to keep it","teaches children traditional recipes that they can write in the examination","shows children that the methods used at home are old and unscientific","makes observation and experiments on spoilage unnecessary in class"],"answer":0,"explanation":"Starting from household practices helps children ask why salt, oil or drying keep food from spoiling, which can then be explored by observation.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1263","question":"A Class 4 child says, ‘Water that looks clear is always safe to drink.’ The teacher’s best response is to:","options":["agree, since visible dirt is the only thing that can make water unsafe to drink","tell the child that only sealed bottled water from a shop is safe to drink","say clearly that the statement is wrong and move on to the next topic","discuss that clear water can carry unseen germs, and why we boil or filter it"],"answer":3,"explanation":"The idea equates visible dirt with danger. Talking about invisible germs and everyday ways of making water safe extends it. Bottled water is no general solution.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1264","question":"Class 5 children ask their grandparents what games they played, what they ate as children and what they now find difficult in daily life. The main aim of this activity is to:","options":["collect old family recipes so that the school can publish a cookbook","show children that life in the past was simpler, healthier and better than today","build understanding across generations and sensitivity to older people’s needs","test children’s writing skills through a long report on the interviews"],"answer":2,"explanation":"Learning about elders’ childhoods and present difficulties builds connection and empathy. It is not meant to idealise the past.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1265","question":"Class 5 children build a bridge of paper between two books and test how many coins it can hold; one group’s bridge collapses quickly. Which question from the teacher best promotes design thinking?","options":["Why did your group fail when the other groups did better than you?","What could you change so it holds more coins? Try it and see.","Which group has made the best bridge, and who should get the prize?","Should we stop here, since paper is simply too weak for bridges?"],"answer":1,"explanation":"Inviting children to modify and retest treats failure as information, which is how design and experimentation work. Blame or ranking discourages trying again.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1266","question":"A Class 3 child says, ‘Birds live in their nests just as we live in our houses.’ Which response best helps the child refine this idea?","options":["Have children watch birds near school to find out when nests are actually used","Tell the child she is correct, since a nest is simply a bird’s house","Tell the child that birds never use nests and always sleep out on open branches","Ask the child to draw a bird sitting inside its nest, like a family at home"],"answer":0,"explanation":"Most birds build nests for laying eggs and raising young, not as permanent homes. Observation can lead children to this, which neither agreement nor denial would.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1267","question":"For a week, Class 4 children record what is served in the mid-day meal each day and then discuss the variety. This activity is a good example of:","options":["checking whether the school cook is doing her job properly every day","teaching children to complain politely when they dislike the food served","comparing nearby schools to find out which one serves the best meal","using a daily school experience as a resource for learning about food"],"answer":3,"explanation":"The mid-day meal is part of children’s daily life and can be observed, recorded and discussed, which suits the ‘Food’ theme. It is not an inspection or a complaint exercise.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1268","question":"After a walk, Class 5 children write a letter to the gram panchayat about a broken hand pump in their village, describing the problem and suggesting a solution. This activity best shows:","options":["a pure language exercise in letter-writing that is unrelated to EVS","the teacher handing over her own civic responsibility to the children","EVS joined with language, with children acting as responsible citizens","a punishment for the children who first complained about the hand pump"],"answer":2,"explanation":"Children use language for a real purpose while engaging with local governance and a shared resource, joining EVS, language and citizenship.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1269","question":"Most children in a Class 3 class in a remote village have never left the village. For the theme ‘Travel’, the teacher’s best strategy is to:","options":["start from people who come to the village, like vendors, then widen with stories","skip the theme until the children have had a chance to travel themselves","show only pictures of aeroplanes and fast trains so that the children get excited","ask children to imagine long journeys on their own, without any support"],"answer":0,"explanation":"Even without travelling, children see people who travel to them; starting there and widening with stories keeps the known-to-unknown principle.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1270","question":"Class 5 children collect seeds from around the school and group them by how they think each seed travels, by wind, water or animals, giving reasons from the seeds’ shapes. The main process skill being developed is:","options":["memorising the common and local names of different seeds","inferring how something works from its structure","measuring the length and mass of seeds accurately","copying the seed classification given in the textbook"],"answer":1,"explanation":"Children reason from features such as wings, hooks or a fibrous coat to a likely way of dispersal, which is inference. It is neither recall nor measurement.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1271","question":"Assertion (A): The theme ‘Things We Make and Do’ includes building, crafts and other activities people carry out around the child. Reason (R): The theme aims to help children appreciate processes, materials and the skills of people around them. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Activities such as building and crafts are included precisely so that children understand processes and value the skills and labour involved.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1272","question":"Which of these are good practices in teaching ‘Shelter’ in Class 4? I. Comparing houses in different climates and the reasons for their design. II. Discussing who builds houses and their working conditions. III. Telling children that pucca houses are always better than kachcha houses. IV. Looking at the homes of animals.","options":["I and II only","II and III only","I, III and IV only","I, II and IV only"],"answer":3,"explanation":"Kachcha houses of mud and bamboo are often well suited to local climate; calling pucca houses ‘always better’ is a value judgement EVS should question. The other three are sound practices.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1273","question":"A teacher gives each group a sealed box containing an unknown object. Students may tilt, shake and weigh the box but never open it, and must describe what they think is inside and why. The main idea about the nature of science this activity teaches is that:","options":["Scientists can always check their answers by looking directly at the thing studied","Scientists often build models from indirect evidence, open to revision","Guessing is the same as scientific inference, so any idea is as good as another","There is always one right answer, and the teacher already knows it"],"answer":1,"explanation":"Like ideas about the atom or the earth's interior, students' ideas about the box rest on indirect evidence and stay tentative. The teacher should not open the box, so that the point is not lost.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1274","question":"A student asks why astronomy is taught as a science but astrology is not. Which reason should the teacher help students arrive at?","options":["Astronomy is much older than astrology and has a far longer written history","Astronomy is taught in universities, so it must be a proper science","Astronomy makes testable claims and changes them when evidence disagrees","Astrology uses no mathematics at all, while astronomy uses a great deal"],"answer":2,"explanation":"Science is marked by testable claims and revision in the light of evidence. Age, prestige or the use of mathematics are not what make a field scientific.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1275","question":"In the 1840s, a doctor showed that deaths of mothers in a hospital fell sharply when doctors washed their hands, yet many colleagues rejected his findings for years. A teacher uses this story mainly to show students that:","options":["Doctors in the past did not care about their patients’ lives at all","Hand-washing is useful mainly in hospitals and not in daily life","Good evidence always convinces scientists immediately, whatever they believe","Acceptance of scientific ideas can be shaped by beliefs and social factors"],"answer":3,"explanation":"Semmelweis's evidence was resisted partly because it clashed with doctors' beliefs and there was no germ theory yet to explain it. The story shows science as a human, social enterprise, which is historical validity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1276","question":"Class 6 students fix a stick upright in the school ground and mark the tip of its shadow every hour from morning till afternoon. Which process skill does this activity develop most directly?","options":["Using space-time relationships","Classifying objects into groups","Forming and testing hypotheses","Controlling variables in a fair test"],"answer":0,"explanation":"Tracking how the position and length of the shadow change with time is the basic process skill of using space-time relationships, along with observing and recording.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1277","question":"Students are shown a picture of two sets of animal footprints in mud that come together, become confused, and then only one set continues. Groups give different stories of what happened. The main purpose of the activity is to show that:","options":["Only one story can be correct, and the teacher will reveal it at the end","The same observations can support more than one reasonable inference","Footprints are not useful evidence because they can be read in many ways","Students should avoid making inferences and only state what they observe"],"answer":1,"explanation":"What is seen (the tracks) is the same for all; the stories are inferences. Different reasonable inferences from the same data show why scientists look for more evidence before deciding.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1278","question":"To find the time period of a pendulum, the teacher asks students to time 20 oscillations and divide by 20, rather than timing just one. The main reason is that:","options":["One oscillation is too fast for students to count and time properly","Twenty oscillations make the pendulum settle and swing more regularly","It reduces the effect of errors in starting and stopping the watch","Timing more swings increases the time period of the pendulum"],"answer":2,"explanation":"The reaction-time error in starting and stopping the watch is about the same for 1 or 20 oscillations, so spreading it over 20 makes the error per oscillation much smaller.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1279","question":"Students investigate whether the length of a pendulum affects the time of one oscillation. Which of the following must they keep the same as a controlled variable?","options":["The length of the thread, so that each trial is a fair test","The time taken for one oscillation, so results can be compared","The number of students timing the swings in each group","The mass of the bob and the angle from which it is released"],"answer":3,"explanation":"Length is the independent variable and the time of an oscillation is the dependent variable; the bob's mass and the release angle must be kept constant so that only length changes.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1280","question":"Each group tested one plant with fertiliser and one without; in one group the fertilised plant grew taller, and that group concluded that 'fertiliser makes all plants grow taller'. The main weakness in this conclusion is that:","options":["Only one plant was used in each condition, so chance could explain it","Fertiliser should never be used in school experiments with plants","The group should have chosen a faster-growing kind of plant for the test","The plants should have been measured only once, at the very end"],"answer":0,"explanation":"With one plant per condition, natural variation can produce a difference. Repeating with many plants, and comparing results across groups, makes the conclusion more reliable.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1281","question":"Students note that in summer both the sale of cold drinks and the number of cases of heat-stroke go up. One student concludes that cold drinks cause heat-stroke. Which is the best response?","options":["Agreeing with the student, since the two rise together every summer","Asking if a third factor, such as hot weather, could cause both","Telling the student to stop drinking cold drinks during the hot months","Saying that data of this kind cannot tell us anything useful at all"],"answer":1,"explanation":"Two things rising together does not show that one causes the other; both can depend on a third factor. This teaches the difference between correlation and cause.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1282","question":"During an investigation a student asks the teacher, 'Is my answer right?' The response that best supports inquiry is:","options":["'Yes, it is right; you can move on to the next step now.'","'No, it is wrong; check the answer given in the textbook.'","'What does your evidence show? How could you check it?'","'Ask the class topper whether she got the same answer.'"],"answer":2,"explanation":"In inquiry the evidence, not the teacher's authority, decides; turning the question back helps the student evaluate her own results.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1283","question":"While teaching crop production, a Class 8 teacher wants students to understand the Green Revolution in a balanced way. Which approach is most suitable?","options":["Presenting it only as a great success that put an end to India’s food shortages","Presenting it only as a disaster for soil, water and the environment","Asking students to memorise the year it began and the crops it involved","Weighing evidence on higher yields against harms such as falling groundwater"],"answer":3,"explanation":"A science-technology-society issue should be examined using evidence on both benefits and costs, helping students weigh trade-offs rather than adopting a one-sided view.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1284","question":"A teacher keeps a 'science corner' with toys students made from waste, such as straw whistles, matchbox pull-carts and balloon-powered cars. The main value of this practice is that it:","options":["Shows science can be joyful with everyday materials and invites tinkering","Replaces the need for textbooks and written work in science lessons","Prepares students for the practical questions in competitive examinations","Keeps the classroom decorated and attractive for visitors and inspectors"],"answer":0,"explanation":"Toys from trash let students explore principles such as sound, friction and air pressure at little cost, and encourage tinkering and innovation.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1285","question":"A Class 7 student has already mastered the concept of acids and bases while others are still working. What should the teacher provide?","options":["The same worksheet once more, to make sure that her learning is really secure","Nothing extra, so that she waits quietly for the others to finish","Enrichment, such as her own investigation of local flowers as indicators","The next chapter’s notes, so she can start memorising them early"],"answer":2,"explanation":"Enrichment deepens and extends learning for those who have mastered the basics, through open-ended, challenging tasks rather than repetition or idle waiting.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1286","question":"Assertion (A): A teacher should begin teaching electric circuits from students' experience of torches and household switches. Reason (R): Learning proceeds best from the known to the unknown.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Torches and switches are familiar to students, so starting from them follows the maxim 'from known to unknown', which explains why the teacher should begin there.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1287","question":"Match each method with its example. P. Project method  Q. Heuristic method  R. Lecture-demonstration  S. Problem-solving method. 1. The teacher shows a reaction of a small piece of sodium with water while explaining it  2. Students, with minimal hints, find out for themselves how to separate sand, salt and iron filings  3. The class sets up and runs a school weather station over a whole term  4. Students take up 'Why does tube-well water in our village taste salty?', form hypotheses and test them","options":["P-3, Q-4, R-1, S-2","P-4, Q-2, R-1, S-3","P-3, Q-2, R-4, S-1","P-3, Q-2, R-1, S-4"],"answer":3,"explanation":"A term-long purposeful real-life undertaking is a project; finding out with minimal guidance is heuristic; the teacher showing and explaining is lecture-demonstration; working systematically on a felt problem through hypotheses is problem-solving.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1288","question":"A teacher writes 'All metals expand on heating' on the board, and then shows the ring-and-ball experiment to illustrate it. This lesson follows:","options":["Inductive approach, moving from examples to a rule","Deductive approach, moving from a rule to examples","Heuristic approach, where students discover the rule","Project approach, where students plan their own work"],"answer":1,"explanation":"Stating a general rule first and then showing particular cases is deduction. An inductive lesson would begin with several cases and let students arrive at the rule.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1289","question":"Students believe that air has no weight because 'we cannot feel it pressing down'. Which activity gives them the most direct evidence?","options":["Fanning air towards their faces and feeling it push on the skin","Blowing up a balloon and letting it go so that it flies across the room","Balancing two blown-up balloons on a stick, then pricking one","Watching leaves and branches move about in a strong wind"],"answer":2,"explanation":"When one balloon loses its air, the balance tilts towards the still-inflated balloon, showing that the air inside it has weight. The other activities show that air moves, not that it has weight.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1290","question":"A teacher fills a glass to the brim with water, covers it with a postcard and turns it upside down; the card stays in place. Which student idea is this demonstration most likely to challenge?","options":["Water is heavier than the same volume of air","Liquids take the shape of the container they are in","Water always flows downwards when nothing holds it","Air pushes only downwards, not upwards or sideways"],"answer":3,"explanation":"The card is held up by air pressing upward on it, which contradicts the common idea that air pressure acts only downwards. Air pressure acts in all directions.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1291","question":"A Class 6 student argues that fire is a living thing because 'it grows, moves and needs air'. The most productive way for the teacher to use this is to:","options":["Have the class test fire against other signs of life, like cells and reproduction","Tell the student firmly that fire is not a living thing and move on to the next topic","Accept the argument, since every feature the student mentioned is correct","Avoid the question, since it may confuse other students before the exam"],"answer":0,"explanation":"The argument uses some real features of life; testing fire against the full set of characteristics refines the concept of 'living' for the whole class.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1292","question":"A Class 8 lesson on water purification has students test local purification methods they designed themselves, explains how chlorination came into use, and uses simple language suited to them. Which NCF 2005 criterion does the lesson NOT clearly address, as described?","options":["Process validity","Historical validity","Ethical validity","Cognitive validity"],"answer":2,"explanation":"Designing tests serves process validity, the history of chlorination serves historical validity, and suitable language serves cognitive validity. Nothing in the description deals with values such as honesty or concern for life.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1293","question":"Students say that the moon gives out its own light. Which observation, discussed in class, best challenges this idea?","options":["The moon looks much bigger when it is low near the horizon at night","The moon can sometimes be seen clearly in the daytime sky","The moon's lit side always faces the sun, and its lit part changes","The moon is much closer to the earth than any of the stars"],"answer":2,"explanation":"If the moon made its own light, the whole disc would always glow. The lit side facing the sun, and the changing lit part, shows that it reflects sunlight.","difficulty":"hard","source":"CTET Paper 2 · state TETs · KVS"},
  {"id":"cdp-pedagogy-subjects-1294","question":"Which of the following practices is most likely to create the misconception that science is only done by people in laboratories?","options":["Inviting a local farmer to explain how she decides the right time to sow","Taking students to watch a potter at work and discussing the changes in the clay","Asking students to investigate questions that arise in their own homes","Teaching science only through textbook lab experiments, unlinked to outside work"],"answer":3,"explanation":"Linking science to everyday work and life shows that scientific thinking is used widely. Confining it to laboratory experiments alone reinforces the narrow image.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1295","question":"Which activity best shows students the role of controlled conditions in scientific investigation?","options":["Comparing a test where two variables changed at once with one where only one did","Copying the steps of a well-known experiment from the board neatly into notebooks","Watching a video on a famous experiment and noting down its main result","Writing a report on the life and discoveries of a famous scientist"],"answer":0,"explanation":"Comparing a confounded test with a fair one shows students that when two things change together, it is impossible to say which caused the result.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1296","question":"Consider these statements about inquiry-based science. 1. Students' questions can drive the investigation. 2. Students use evidence to construct explanations. 3. The teacher acts mainly as a facilitator. 4. Every investigation must end with the result given in the textbook. Which are correct?","options":["1 and 4 only","1, 2 and 3 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":1,"explanation":"Inquiry puts students' questions and evidence at the centre, with the teacher as a guide. Insisting on a predetermined textbook result reduces inquiry to confirmation.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1297","question":"A teacher finds that students in her class think rainbows are 'objects in the sky' at a fixed place. Which activity best helps them revise the idea?","options":["Drawing a rainbow in the sky with all seven colours in the correct order","Making a ‘rainbow’ with a water spray and noticing it moves as they move","Memorising VIBGYOR so that the order of colours is never forgotten","Reading and discussing a poem about how rainbows appear in the sky"],"answer":1,"explanation":"A spray rainbow appears only at a certain angle between the sun, the drops and the observer, and it shifts as the observer moves, which shows it is an effect of light, not an object.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1298","question":"Match each teaching method with the classroom example that best fits it.\nMethods: (P) Source method (Q) Survey (R) Simulation (S) Case study\nExamples: (1) Students hold a mock gram sabha on a drainage problem (2) Students read an extract from a 1930s petition and answer questions on it (3) Students study in depth one farmer's experience of taking a loan (4) Students ask 40 households how they get drinking water","options":["P-2, Q-4, R-1, S-3","P-3, Q-4, R-1, S-2","P-2, Q-1, R-4, S-3","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Working with an original extract is the source method; collecting data from many households is a survey; a mock gram sabha simulates a real process; studying one farmer's situation in depth is a case study.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1299","question":"After keeping a weather diary for June, a Class VII student writes, 'Our town has a rainy climate, because it rained on 22 days this month.' What should the teacher help the student understand?","options":["That the conclusion is correct, since rain on 22 days is a large number","That a weather diary is not a valid activity in the study of geography","That rainfall has nothing to do with climate, which depends only on temperature","That one month’s record shows weather; climate is the pattern over many years"],"answer":3,"explanation":"Weather is the day-to-day state of the atmosphere; climate is the long-term pattern. Generalising from one monsoon month confuses the two. The diary itself is a valuable activity; the inference needs correcting.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-1300","question":"Class VII students in a Maharashtra village collect soil from a riverbank, a field and a hill slope and compare their colour, texture and how fast they absorb water. What is the main aim of this field work?","options":["To learn the scientific names of the different minerals present in each soil","To see first-hand that soils differ from place to place, and ask why","To collect soil samples for use in the school’s science laboratory","To prepare an attractive decorative display for the annual day"],"answer":1,"explanation":"Geography field work develops observation and inquiry: noticing differences in the real environment and asking what causes them. Naming minerals is not the aim at this stage.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1301","question":"A Class VIII teacher asks groups to take each key word of the Preamble, such as justice, liberty, equality and fraternity, and find an example from school or community life where it is respected or violated. What does this approach achieve?","options":["It helps students memorise the whole Preamble word for word","It removes the need to study the rest of the Constitution in detail","It links abstract constitutional ideals to situations students know","It shows students that the Preamble has no legal value in courts"],"answer":2,"explanation":"Applying each ideal to real situations turns abstract words into lived meaning and invites judgement about whether ideals are realised. Memorisation is not the aim.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1302","question":"Class VIII students argue that the freedom of speech means 'we can say anything about anyone, anywhere'. Which response best develops a correct understanding?","options":["Discuss cases showing the right is protected but has reasonable limits","Agree with the students, since fundamental rights can never be limited","Tell them that free speech is not really a protected right in India","Ask them to memorise the article number of the right for the exam"],"answer":0,"explanation":"Fundamental rights are vital but not absolute; the Constitution allows reasonable restrictions on grounds such as defamation, public order and incitement. Cases show why such limits exist and how they are judged.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1303","question":"Class X students interview working people in their area and classify each job by whether it offers a regular salary, paid leave and job security. Which economic concept does this activity mainly help them understand?","options":["Per capita income and how it is worked out for a whole region","The difference between the organised and unorganised sectors","Inflation and how rising prices affect the wages of workers","Foreign trade and how it creates jobs in the local area"],"answer":1,"explanation":"Job security, paid leave and regular wages are the features that distinguish organised from unorganised employment. Real interviews make the distinction, and the vulnerability of unorganised workers, concrete.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-1304","question":"A Class VII teacher asks, 'In what ways are weekly markets today like the markets of medieval times, and in what ways are they different?' Which historical concept is she developing?","options":["Causation","Chronology","Historical significance","Change and continuity"],"answer":3,"explanation":"Asking what has changed and what has stayed the same over time develops the concept of change and continuity. Causation would ask why something happened.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1305","question":"A Class VIII student writes, 'The British won the Battle of Plassey only because Mir Jafar betrayed Siraj-ud-daulah.' What should the teacher encourage?","options":["Accept the answer as complete, since the betrayal is a historical fact","Mark it wrong, since Mir Jafar’s betrayal is only a popular myth","Ask the student to memorise the date of the battle instead","Explore other causes too, like Company ambitions and court rivalries"],"answer":3,"explanation":"The betrayal was real, but historical events usually have several interacting causes. Moving from a single cause to multiple causes is a key step in historical reasoning; rejecting the fact would be wrong.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1306","question":"Class VIII students trace where their town's electricity comes from: a power station, coal from a mine in another state, and the railway that brings it. What understanding does this activity mainly build?","options":["Regions depend on each other, and resource use in one place affects others","Electricity used in a town is always produced inside the limits of that same town","Coal is a renewable resource that can be mined without any limit","Every region produces all the resources that its own people need"],"answer":0,"explanation":"Tracing a resource reveals interdependence between regions and the hidden costs of consumption, such as mining in faraway areas. The distractors are factual errors or the opposite of what the activity shows.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1307","question":"For a Class X lesson on consumer rights, students bring packets from home and examine the MRP, the expiry date, quality certification marks and the address for complaints. This approach is best described as:","options":["Lecture-based learning led mainly by the teacher","Rote learning of the main consumer protection laws","Experiential learning linked to everyday life","Programmed learning in small, fixed steps"],"answer":2,"explanation":"Examining real products lets students discover consumer information for themselves and links rights to their own purchases. That is experiential, life-linked learning.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1308","question":"A Class IX teacher plans a lesson on earthquake safety. Which activity is most effective?","options":["Reading aloud the textbook section on the causes of earthquakes","Students map safe spots and exits in their school, then hold a mock drill","Memorising the Richter scale readings of major past earthquakes","Writing a long essay describing the terrible destruction caused by earthquakes"],"answer":1,"explanation":"Disaster preparedness is practical knowledge. Mapping one's own school and practising a drill builds skills students can use; reading or essays alone do not.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1309","question":"A Class VI teacher holds a mock election for class monitor, with nomination, campaign speeches, a secret ballot and counting. What must follow to make it a social science lesson rather than just a class event?","options":["Announce the winner and then continue with the next chapter from the textbook","Give prizes to all the candidates so that no one feels left out","Ask students to memorise the names and symbols of all the candidates","Discuss how it compares with real elections and what makes an election fair"],"answer":3,"explanation":"The simulation provides an experience; the debrief links it to concepts such as secret ballot, fair competition and representation. Without it, students remember a contest, not democratic principles.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1310","question":"Assertion (A): A social science teacher should present the history of the students' own region as superior to that of other regions, to build local pride.\nReason (R): NCF 2005 recommends connecting learning with the local context of children.","options":["Both A and R are true and R is the correct explanation of A","A is false but R is true","A is true but R is false","Both A and R are true but R is not the correct explanation of A"],"answer":1,"explanation":"Using local context is recommended, but the aim is understanding, not ranking regions. Presenting one region as superior breeds prejudice and goes against social science's commitment to respect for diversity.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1311","question":"Assertion (A): Map work in the early classes should begin with the child's immediate surroundings.\nReason (R): Children's understanding of space develops from familiar to more distant places.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Spatial understanding grows outward from the classroom, home and neighbourhood to wider regions, which is precisely why map work should begin locally.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1312","question":"A Class VIII teacher in Kanpur plans a lesson on livelihoods. Some students' parents are sanitation workers. Which approach is most appropriate?","options":["Present sanitation work as a pitiable job so that students feel sympathy","Leave sanitation work out of the lesson to avoid any embarrassment","Treat it as essential, dignified work and discuss its pay, risks and caste bias","Ask the children of sanitation workers to describe their parents' work in front of the class"],"answer":2,"explanation":"Discussing the work with dignity and examining its structural problems avoids both pity and erasure. Putting particular children on the spot without their consent can expose and hurt them.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1313","question":"A Class VIII student in a Bundelkhand village asks, 'Why is there no secondary school in our village?' What is the most valuable response?","options":["Tell the student politely that such questions are for adults, not for children","Answer briefly that the government has no money for more schools","Note it down for a discussion at the end of the year, after exams","Turn it into a class inquiry on how schools are sanctioned and who decides"],"answer":3,"explanation":"A genuine question from the child's life is an ideal starting point for learning about government, policy and citizens' participation. Quick answers or postponement waste this opportunity.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1314","question":"Which of the following classroom practices are learner-centred?\n1. Students frame their own questions to interview a panchayat member.\n2. The teacher dictates notes for students to copy.\n3. Students compare two accounts of the same event and decide which is more reliable.","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Framing questions and evaluating accounts put students at the centre of building knowledge. Dictation makes the teacher the only active participant.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1315","question":"A teacher plans a Class VI lesson on rural livelihoods using the 5E model (Engage, Explore, Explain, Elaborate, Evaluate). Which sequence of her planned steps follows the first four phases?\nP: Students share what their families do for a living\nQ: The teacher introduces concepts such as 'landless labourer' and 'debt'\nR: Groups read case studies of families in a farming village\nS: Students compare the case studies with their own village","options":["Q, P, R, S","Q, R, S, P","P, R, Q, S","R, Q, P, S"],"answer":2,"explanation":"Sharing family work engages prior knowledge, case studies let students explore, the teacher then explains the concepts arising from them, and comparing with their own village elaborates and applies them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1316","question":"Several Class VIII students believe that judges make the laws of the country. Which activity best corrects this?","options":["Trace one law, such as the RTE Act, from Parliament to government to the courts","Ask students to memorise and keep repeating the sentence ‘Parliament makes laws’","Show a large picture of the Supreme Court building and name its present judges","Tell students that courts have no role at all in matters of law"],"answer":0,"explanation":"Following one law through its life shows the distinct roles of the legislature, the executive and the judiciary. Saying courts have no role overcorrects, since courts interpret laws and can strike them down.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1317","question":"A Class VIII teacher uses a folk song from her district about a famine in the colonial period as a source. What caution should she help students apply?","options":["Folk songs cannot be used as sources, since they were never written down","Folk songs are fully accurate because ordinary people sang them as they lived","Oral songs may change over time and are hard to date, so check other evidence","Only the tune of the song has historical value, not the words it contains"],"answer":2,"explanation":"Folk songs can preserve the experience of ordinary people, but oral transmission alters them and dating is uncertain. Like any source, they need corroboration, neither rejection nor blind trust.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1318","question":"Match the concept with the activity that develops it.\nConcepts: (P) Chronological thinking (Q) Spatial thinking (R) Economic reasoning (S) Civic reasoning\nActivities: (1) Comparing the cost of a government and a private hospital for the same treatment (2) Arranging pictures of means of transport from different periods in order (3) Debating whether a new rule in school treats all students fairly (4) Locating on a map the places from which a city gets its vegetables","options":["P-2, Q-1, R-4, S-3","P-3, Q-4, R-1, S-2","P-2, Q-4, R-3, S-1","P-2, Q-4, R-1, S-3"],"answer":3,"explanation":"Ordering transport pictures builds a sense of time; mapping supply sources is spatial; comparing costs of services is economic reasoning; judging a rule's fairness is civic reasoning.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1319","question":"In a Class VII lesson on medieval temple towns, a student from a Christian family asks why the textbook has nothing about the churches of Goa or Kerala. What is the best response?","options":["Tell the student that the question is irrelevant to the chapter being taught now","Value the question, explain the chapter’s scope and invite an inquiry into it","Say that Christian history in India began only in the colonial period","Promise to answer it later, when the class reaches Class XII history"],"answer":1,"explanation":"Valuing the question, explaining the textbook's scope and opening an inquiry respects the student and widens everyone's understanding. Christianity in Kerala is much older than colonial rule, so that reply would also be wrong.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-1320","question":"A Class VI teacher wants students to understand why the Harappan cities had planned drains and streets. Which question best starts an inquiry?","options":["What do the drains, wells and streets tell us about how people lived?","Who discovered Harappa, and in which year was the site first excavated?","Name four Harappan cities and the rivers on which they were located.","Write a definition of ‘town planning’ and learn it by heart."],"answer":0,"explanation":"Asking what material remains reveal about society invites inference from evidence. The other questions call for recall of names, dates or definitions.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1321","question":"Which of the following statements about using the local community as a resource in social science are correct?\n1. Elders can serve as sources for oral history.\n2. Local institutions such as the post office, bank or panchayat can be studied directly.\n3. Community examples should replace national and global content.","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":0,"explanation":"The community offers living sources and institutions to study. But local study is a starting point that leads to wider understanding, not a replacement for national and global content.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1322","question":"Match each pre-school activity with the pre-number skill it builds. 1. Sorting leaves by shape 2. Arranging sticks from shortest to longest 3. Putting one plate in front of each doll 4. Saying a bead string still has the same number of beads after it is stretched; a. conservation b. one-to-one correspondence c. seriation d. classification","options":["1-d, 2-c, 3-b, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-d, 2-b, 3-c, 4-a"],"answer":0,"explanation":"Sorting by a property is classification, ordering by size is seriation, pairing plate with doll is one-to-one correspondence, and recognising that number does not change with arrangement is conservation.","difficulty":"hard","source":"CTET Paper 1 · state TETs · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1323","question":"A four-year-old always counts ‘one, two, three, five, six’, the same way every time, and gives the last word as the total (‘six’). Which is the most accurate description?","options":["She does not yet follow any of the counting principles, standard or otherwise","She uses stable order and cardinality but not the standard number-word list","She follows only the one-to-one principle and none of the others","She shows a counting disability and needs referral to a specialist at once"],"answer":1,"explanation":"Stable order means using the same list in the same order each time, even if it is not the standard list; giving the last word as the total is the cardinal principle. What is missing is the conventional sequence, which comes with practice.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1324","question":"A child counts a row of five blocks from the left and gets 5. Asked how many there will be if she counts from the right, she says, ‘I don't know; let me count.’ Which counting principle has she not yet grasped?","options":["Stable order","One-to-one correspondence","Order irrelevance","Abstraction"],"answer":2,"explanation":"Order irrelevance means the total does not depend on where counting starts. A child who must recount to be sure has not yet grasped it, even though her counting itself is correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1325","question":"Asked to count a pencil, a cup and a ball together, a child says they cannot be counted ‘because they are different things’. Which counting principle is she missing?","options":["Cardinality, that the last number names the total","Stable order, that number words come in a fixed order","One-to-one correspondence, one number word for each object","Abstraction, that any collection of things can be counted"],"answer":3,"explanation":"The abstraction principle says counting applies to any set, whether the things are alike or not, and even to sounds or actions. The child thinks only similar objects can be counted together.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1326","question":"A Class 1 child can recite numbers from 1 to 50 but cannot give the teacher 7 seeds from a heap when asked. Which activity should the teacher focus on?","options":["‘Give me 7’ tasks with real objects, moving each one and stopping at 7","More daily practice in reciting the number names in order all the way up to 100","Writing the numerals 1 to 50 neatly in the notebook several times","Learning several number rhymes and songs by heart with actions"],"answer":0,"explanation":"Reciting is rote counting; giving a set of a given size needs rational counting (one-to-one matching and knowing when to stop). Practice with real objects builds this.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1327","question":"A child counts beads arranged in a circle and keeps counting some beads twice because she cannot tell where she started. What is the best help?","options":["Tell her to count faster so that she does not lose track of where she began","Show her a tracking strategy, like moving each counted bead aside","Give her only beads arranged in a straight line from now on","Tell her the correct answer and move on to the next activity"],"answer":1,"explanation":"Keeping counted and uncounted objects apart is a key part of accurate counting. Teaching a tracking strategy helps with any arrangement; avoiding circles only hides the difficulty.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1328","question":"A closed box with two sections holds 5 beans. The child shakes it, opens one side, sees 3 beans and says, ‘So 2 are hiding.’ What is this activity mainly building?","options":["Rote counting of number names in the right order","Writing numerals correctly and in the right sequence","Part-whole understanding of numbers (number bonds)","Measurement of length using non-standard units"],"answer":2,"explanation":"Knowing that 5 can be split into 3 and 2, and finding a missing part, is part-whole thinking. It is the basis for flexible addition and subtraction, and for missing-addend problems.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1329","question":"Why is a ten-frame (a 2 × 5 grid) more useful for early number work than counters in a random heap?","options":["It looks bright and colourful, so children pay more attention to it","It is cheaper and quicker to make than a set of loose counters","It is needed so that children can practise rote counting up to 10","It shows numbers against 5 and 10, so 7 is seen as ‘5 and 2’"],"answer":3,"explanation":"The structure of the frame lets children see quantities without counting one by one and links them to 5 and 10, which supports strategies such as ‘make ten’.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1330","question":"Which of these statements about NEP 2020 are correct? I. The foundational stage covers ages 3 to 8. II. It includes three years of preschool or Anganwadi and Grades 1 and 2. III. It calls achieving foundational literacy and numeracy for all children an urgent national mission. IV. It requires a board examination at the end of Grade 2 to test numeracy.","options":["I, II and III","I and III only","II, III and IV","I, II, III and IV"],"answer":0,"explanation":"NEP 2020 has a 5-year foundational stage (ages 3–8: three years of preschool plus Grades 1 and 2) and makes foundational literacy and numeracy an urgent national mission. There is no board exam at Grade 2.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1331","question":"Asked to mark 10 on a 0–100 number line, a Class 1 child places it near the middle. What does this show, and what helps?","options":["She cannot count up to 100 yet and should practise counting aloud every day","Her number line crowds large numbers; benchmarks and straight-track games help","She has simply confused 10 with 100 and needs to read the numerals more carefully","She is careless and should be told to pay more attention to the task"],"answer":1,"explanation":"Young children space small numbers widely and crowd larger ones, as on a log scale. Experience with benchmarks and with board games numbered in a straight line helps them build a linear sense of number size.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1332","question":"Why are board games with numbered squares in a straight line, such as a simple snakes-and-ladders board, especially helpful in early numeracy?","options":["They teach children to win and to lose gracefully in front of their friends","They are mainly useful for practising reading the words on the board","Moving along numbered squares links each number to a position and distance","They replace the need for counting real objects in the early classes"],"answer":2,"explanation":"A straight numbered track gives children many experiences of ‘larger numbers are further along’, and studies show such games improve number-line estimation and comparison.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1333","question":"A Class 1 child compares two pencils whose left ends are not lined up and says the one sticking out further on the right is longer. What has she not yet understood?","options":["How to place a ruler correctly and read its centimetre marks","That length is always measured in standard units like centimetres","That pencils of the same colour are always the same length","That lengths must be compared from a common starting line"],"answer":3,"explanation":"Direct comparison needs both objects to start at the same baseline. Without it, the one that ends further right only looks longer. Lining up ends comes before any unit measurement.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1334","question":"Which of these problems is usually the hardest for Class 1 children?","options":["‘Rani had some bangles. Her aunt gave her 3 more. Now she has 8. How many did she have at first?’","‘Rani had 5 bangles. Her aunt gave her 3 more. How many does she have now?’","‘Rani had 5 bangles. Her aunt gave her some more. Now she has 8. How many bangles did her aunt give?’","‘Rani has 5 red bangles and 3 green bangles. How many bangles does she have?’"],"answer":0,"explanation":"When the starting amount is unknown, children cannot simply act the story out from the beginning, so ‘start unknown’ problems are the hardest. Result-unknown and part-part-whole problems are the easiest.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1335","question":"A teacher wants Class 2 children to become fluent with addition facts without rote memorisation. Which approach is best?","options":["Daily timed tests of all the facts, with the fastest children praised before the class","Strategies such as doubles, near doubles and making ten, practised through games","Writing each addition fact ten times in the notebook every evening","Allowing only finger counting until the children reach Class 4"],"answer":1,"explanation":"Facts learnt through reasoning strategies are remembered better and can be rebuilt if forgotten. Games give the practice without the anxiety of timed tests.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1336","question":"A Class 2 child cannot use the ‘make ten’ strategy for 8 + 5 (8 + 2 + 3). Which prerequisite is she most likely missing?","options":["Knowing the multiplication table of 2 by heart without mistakes","Being able to read and write all the numbers up to 100 correctly","Knowing pairs that make 10 and splitting 5 into 2 and 3","Being able to write numerals neatly and in the correct direction"],"answer":2,"explanation":"‘Make ten’ needs the child to know that 8 needs 2 more to make 10 and to split 5 into 2 and 3. Ten-frames and number bonds build both skills.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1337","question":"A Class 2 child counts the four symbols beside ‘Mangoes’ in a pictograph and says 4 children like mangoes. The key says each symbol stands for 2 children. What is the best next step?","options":["Ask her to read the key and work out what four symbols stand for","Tell her that the right answer is 8 and move on to the next row","Use only pictographs where one symbol stands for one child from now on","Ask her to count the symbols again, slowly and carefully this time"],"answer":0,"explanation":"She counted symbols without using the scale. Asking her to read and apply the key (4 × 2 = 8) builds the habit of reading a graph's key; avoiding scaled graphs would hide the difficulty.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1338","question":"In a pretend shop, a Class 2 child says five ₹1 coins are worth more than one ₹10 note ‘because there are more of them’. What has she not yet understood?","options":["How to count a set of coins one by one without missing or repeating any","That the value of money depends on the number of notes and coins","That notes and coins have values, so one ₹10 note equals ten ₹1 coins","That coins are always more valuable than notes because they are metal"],"answer":2,"explanation":"She judges by the number of items, not by value. Exchanging coins for notes in the pretend shop (ten ₹1 coins for one ₹10 note) builds the idea of value, much like trading ones for a ten.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1339","question":"A child continues the pattern red-blue-blue, red-blue-blue as red-blue, red-blue, red-blue. What is the best way to help her?","options":["Tell her the correct colours to use for the next few beads in the row","Give her only easier ABAB patterns from now on so she does not fail","Ask her to circle the repeating part and say it aloud before going on","Ask her to count all the beads in the pattern and write the total"],"answer":2,"explanation":"Seeing the repeating unit (red-blue-blue) is the key to any repeating pattern. Circling and saying it lets her find the unit herself; telling her the answer does not build the skill.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1340","question":"Which set of signs, persisting despite good teaching over time, would most justify referring a child for assessment for dyscalculia?","options":["Occasional slips in carrying when doing long addition under time pressure","Disliking maths homework and finishing it slowly, often at the last minute","Making errors only in word problems written in a second language she is learning","Great difficulty seeing small quantities at a glance and comparing two numbers"],"answer":3,"explanation":"Dyscalculia is a persistent difficulty with basic number sense, such as subitising and comparing magnitudes. Occasional slips, dislike or language problems are not signs of it.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1341","question":"A teacher in a multigrade school has Classes 1, 2 and 3 together for maths. Which plan works best?","options":["A shared theme, like a class shop, with tasks at a different level for each class","Teaching each class separately in turn while the other two classes sit quietly and wait","Teaching only the Class 3 syllabus to everyone so nobody is left behind","Giving all three classes the same worksheet so that marking is easier"],"answer":0,"explanation":"A shared context with tiered tasks keeps all children engaged at their own level and lets older children help younger ones, which suits the multigrade classrooms common in India.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1342","question":"A Class 3 teacher teaches several speed tricks for multiplication without explaining why they work. What is the main pedagogical concern?","options":["Tricks are too difficult for Class 3 children to remember correctly","Tricks without understanding are easily misapplied and build no number sense","Tricks are not part of Indian mathematics and so do not belong in the syllabus","Tricks take too long to teach when the syllabus has to be finished"],"answer":1,"explanation":"Speed is not the aim at this stage; a trick without understanding is just another rule to forget or misapply. If tricks are used, children should explore why they work.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1343","question":"Assertion (A): Children who can recite number names up to 100 no longer need to count real objects. Reason (R): Reciting number names and understanding quantity are different abilities.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Reciting is a verbal sequence; understanding quantity needs one-to-one counting, cardinality and comparison, which develop through counting real objects. So R is true and it shows why A is false.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1344","question":"Which of these statements about early numeracy are correct? I. Recognising small quantities at a glance (subitising) is a foundation for number sense. II. Counting should always begin with written numerals. III. Number names, numerals and quantities should be linked to one another. IV. Children must master counting to 100 before any addition.","options":["I, II and III","II and IV only","I and III only","I, III and IV"],"answer":2,"explanation":"Number work begins with objects and spoken names, not written numerals, and simple addition through stories and objects starts long before counting to 100. I and III describe sound practice.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1345","question":"Writing numbers in order, a Class 1 child writes ‘…37, 38, 39, 310, 311’. What does this most clearly show?","options":["She has trouble holding the pencil and forming the digits correctly","She has not yet learnt to write the digit 4, so she avoids it and writes 3 again","She is copying from a neighbour who has made the same mistake","She carries on counting ones past 9, not seeing that ten ones make a new ten"],"answer":3,"explanation":"After 39 the ones are full, so they make one more ten: 40. Writing 310 shows the ten-and-ones structure is not yet understood; bundling sticks at 39 + 1 makes it visible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1346","question":"For 6 + 9, a Class 1 child says ‘six…’ and then counts on nine more, raising a finger for each word, and stops at ‘fifteen’. Which next step would make her strategy more efficient?","options":["Go back to counting both sets from one with objects, to be sure of the total","Count on 6 from 9, the larger number, since the order does not change the sum","Memorise 6 + 9 = 15 by repeating it aloud several times every day","Stop using fingers to keep track, since finger counting is a bad habit to break"],"answer":1,"explanation":"She already counts on and keeps track of the second number, a real step beyond counting all. Starting from the larger addend (using commutativity) shortens the count from nine steps to six.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1347","question":"A Class VI teacher plans a unit using backward design (Wiggins and McTighe). Which order of planning steps should she follow?","options":["Choose interesting activities, then write objectives, then prepare a test","Write the test first, then choose the activities, then write the objectives","Set the desired results, then decide the evidence, then plan the activities","Plan the learning experiences, then identify the results, then decide on evidence"],"answer":2,"explanation":"Backward design starts from the goal, then defines acceptable evidence (assessment), and only then plans activities, so that activities serve the goal rather than the other way round.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1348","question":"Which of these is the best-stated learning outcome for a Class II lesson on measurement?","options":["The teacher will explain the concept of length with several examples","Children will understand measurement and appreciate its importance in life","Children will do the activity given on page 34 of the textbook","Children will compare two lengths using hand spans and give reasons"],"answer":3,"explanation":"A good learning outcome states what the child will be able to do in observable terms. The others describe teacher actions, a vague state ('understand') or an activity rather than learning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1349","question":"Consider the following statements about the class-wise learning outcomes developed by NCERT for the elementary stage: 1. They describe what children should be able to do by the end of each class in each subject. 2. They prescribe a single teaching method that every teacher must follow. 3. Along with the outcomes, suggested pedagogical processes are given to help achieve them. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"NCERT's learning outcomes are competency benchmarks for each class, accompanied by suggested pedagogical processes. They guide teaching and assessment but do not mandate one method, so statement 2 is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1350","question":"In the Herbartian lesson plan as commonly used in Indian teacher education, which is the correct sequence of the five formal steps?","options":["Presentation, Preparation, Generalisation, Association, Application","Preparation, Presentation, Association, Generalisation, Application","Preparation, Association, Presentation, Application, Generalisation","Preparation, Presentation, Generalisation, Association, Application"],"answer":1,"explanation":"The steps move from preparing the mind and presenting new material to comparing and associating it, drawing a general rule, and finally applying it. Generalisation needs association first.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1351","question":"A Class VII science teacher using the 5E model has already engaged students, let them explore floating and sinking, and helped them explain it with the idea of density. Now she asks them to predict whether an egg will float in salt water and test it. Which phase is this?","options":["Engage","Explain","Elaborate","Evaluate"],"answer":2,"explanation":"Elaborate extends and applies the newly explained concept to a new situation. Evaluate is where understanding is assessed, though assessment can occur throughout.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1352","question":"Ten minutes into her planned Class IV lesson on multiplication, Ms Joshi realises most children have not understood repeated addition, which the lesson assumes. What should she do?","options":["Continue with the plan so that the syllabus stays on schedule","Abandon the topic altogether and move on to the next chapter","Give extra homework on multiplication so children practise at home","Adapt the plan to revisit repeated addition with concrete objects"],"answer":3,"explanation":"A lesson plan is a guide, not a script; responding to evidence of children's understanding is what good teaching requires. Pushing ahead builds on a weak foundation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1353","question":"A Class III teacher starts a lesson on floating and sinking by asking, 'What things have you seen floating in the pond or in a bucket of water? What sinks?' What is the main purpose of this step?","options":["To draw out children’s prior ideas so new learning links to them","To fill the first few minutes while the children settle down","To test the children quickly and give them marks for their answers","To show children that their everyday ideas are usually wrong"],"answer":0,"explanation":"Eliciting prior knowledge links the lesson to experience and reveals alternative conceptions the teacher must address. It is diagnostic and motivating, not a graded test.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1354","question":"Consider the following statements about planning: 1. A unit plan organises several lessons around a coherent theme or set of learning outcomes. 2. A year plan helps a teacher distribute units across the session, keeping in mind holidays and local events. 3. Once a unit plan is made, individual lesson plans are unnecessary. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":1,"explanation":"Year, unit and lesson plans work at different levels and support each other; daily lessons still need specific plans for activities and checks. Statement 3 is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1355","question":"Which Class V lesson plan opening best reflects a constructivist approach to teaching about why some foods spoil faster?","options":["The teacher reads out the definition of food spoilage and children copy it","The teacher writes ten causes of food spoilage on the board for children to learn","Children say why roti spoils before pickle, share ideas and plan a test","The teacher shows pictures of spoiled food and tells children never to eat it"],"answer":2,"explanation":"Constructivist lessons begin from a puzzling, real question and children's own ideas, which they then test. The other openings transmit conclusions and leave children passive.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1356","question":"At the end of a Class VI lesson on factors, a teacher gives each student a slip asking: 'Write all factors of 18' and 'Is 1 a factor of every number? Why?' She sorts the slips before planning the next class. What is the main purpose?","options":["To collect marks from every student for the end-of-term report card","To check each student’s understanding and plan the next lesson from it","To catch and punish the students who did not pay attention during the lesson","To keep the students busy and quiet until the bell rings for recess"],"answer":1,"explanation":"An exit ticket is a quick formative check; sorting responses shows who needs support or extension, so the next lesson is planned from evidence.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1357","question":"A Class VII learning outcome states: 'The learner explains why seasons change in a year.' The unit test has one question: 'Name the four seasons in India.' What is the main problem?","options":["The question is far too difficult for most Class VII students to answer","There is no problem, since the question is about seasons as well","The outcome itself is too simple for Class VII and should be deleted","The item checks recall of names, not the ability to explain the cause"],"answer":3,"explanation":"Assessment must match the cognitive demand of the outcome. 'Explain why' needs an item about the tilt of the Earth's axis and its revolution, not a recall list.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1358","question":"Ms Kumari teaches Classes I, II and III together in one room in a single-teacher school in Jharkhand. Which planning approach suits this multigrade setting best?","options":["Teach Class III while Classes I and II sit silently, then rotate the classes each day","A common theme with tiered tasks, peer support and self-learning materials","Combine all three classes and teach the Class III syllabus to everyone","Teach only the class that has an important examination coming up soon"],"answer":1,"explanation":"Multigrade teaching works through common themes, differentiated tasks, peer learning and graded self-learning materials. Keeping groups idle or teaching one level to all wastes learning time.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1359","question":"A Class VI objective reads: 'Given an outline map of India, students will locate at least 8 of the 10 major rivers.' In the ABCD format of writing objectives, the phrase 'at least 8 of the 10' is the:","options":["Audience","Behaviour","Condition","Degree"],"answer":3,"explanation":"ABCD stands for Audience (students), Behaviour (locate), Condition (given an outline map) and Degree (the criterion for success, here at least 8 of 10).","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1360","question":"A Class V teacher says proudly, 'I always finish the textbook by January.' Yet a test shows most of her students cannot read a simple bar graph, which is a Class V learning outcome. What does this most strongly suggest?","options":["Her planning aimed at covering chapters, not at learning outcomes","The learning outcome is too difficult for Class V and should be removed","Her students did not study at home or revise what was taught","Textbooks should be finished even earlier, by December, to allow revision"],"answer":0,"explanation":"Learning-outcome-based planning asks whether children can do what was intended, not whether pages were covered. Finishing early without learning shows a coverage mindset.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1361","question":"Which way of closing a Class IV lesson on food chains is most effective for learning?","options":["The teacher carefully summarises the whole lesson herself and then gives homework","The lesson ends when the bell rings, wherever the teacher happens to be","Children sum up in their own words, raise a question, and she links it ahead","The teacher asks ‘Any questions?’ and moves on if no one speaks up at once"],"answer":2,"explanation":"Closure that has learners consolidate and articulate their own understanding, and connect forward, helps memory and shows the teacher what was learnt. Teacher-only summaries keep children passive.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1362","question":"While writing objectives for a Class VII lesson, which verb gives the most observable and measurable objective?","options":["Know","Appreciate","Classify","Understand"],"answer":2,"explanation":"'Classify' names an action a teacher can see and check. 'Know', 'understand' and 'appreciate' describe inner states that need to be turned into observable behaviours before they can be assessed.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1363","question":"A teacher in a Chennai city school uses a textbook example of 'counting cattle in the village' for Class II subtraction. Her students live in flats and have never seen cattle closely. What would be the best adaptation while planning?","options":["Use local examples, like buses at a stop, keeping the same maths","Keep the textbook example, since textbooks must be followed exactly","Skip subtraction until the students can visit a village on a trip","Ask students to memorise the textbook example word for word"],"answer":0,"explanation":"Contextualising examples to children's lives makes the concept meaningful while keeping the learning goal unchanged; NCF encourages linking school knowledge to children's experiences.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1364","question":"Consider the following statements about the NIPUN Bharat Mission launched in 2021: 1. Its aim is that every child attains foundational literacy and numeracy by the end of Grade 3. 2. It covers children in the age group of 3 to 9 years. 3. It requires that early literacy be taught only in English. Which of these are correct?","options":["1 and 3 only","2 and 3 only","1, 2 and 3","1 and 2 only"],"answer":3,"explanation":"NIPUN Bharat aims at universal FLN by the end of Grade 3 for children aged 3-9, and in line with NEP 2020 it encourages learning in the home or local language. Statement 3 is false.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1365","question":"A Class III teacher plans a two-week theme on 'Water': children measure water use at home (maths), write a poem on rain (language), and survey water sources (EVS). What is the main strength of this plan?","options":["It reduces the number of separate subjects that the teacher must plan and teach","It joins subjects around a meaningful theme so children see connections","It allows the teacher to avoid using the prescribed textbooks entirely","It ensures that every child in the class scores the same marks in tests"],"answer":1,"explanation":"Thematic, integrated planning mirrors how children experience the world and lets skills from different subjects support each other, as NCF recommends for the early years.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1366","question":"A teacher keeps a column called 'Reflection after the lesson' in her plan book, where she notes what worked, which children struggled and what she will change. What does this mainly support?","options":["Reflective practice that uses lesson evidence to improve teaching","Completing the official records that are checked during inspection","Comparing her lessons with colleagues’ lessons to decide promotions","Recording students’ marks and attendance for the report card"],"answer":0,"explanation":"Post-lesson reflection turns each lesson into data for improvement, the core of being a reflective practitioner. It is not mainly an administrative or grading record.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1367","question":"A Class II teacher writes the objective: 'Children will show willingness to share play materials with others.' To which domain does this objective belong?","options":["Cognitive","Psychomotor","Affective","Metacognitive"],"answer":2,"explanation":"Willingness, attitudes and values belong to the affective domain (Krathwohl). Cognitive deals with knowledge and thinking, and psychomotor with physical skills.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1368","question":"In a village school in Punjab, attendance drops sharply during the wheat harvest, and many children help in the fields. How should the class teacher plan her year?","options":["Keep the year plan unchanged and mark the absent children as failing the term","Plan key topics around the harvest, use it as context, and plan catch-up","Give double homework during the harvest so that no work is lost","Report the parents of absent children to the education authorities"],"answer":1,"explanation":"Planning that takes the local calendar into account reduces learning loss and connects school to children's lives. Penalising children for a community reality is neither fair nor effective.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1369","question":"At the start of a Class VI writing task, the teacher shares a short list: 'A good letter here will: have a clear greeting and closing; give two reasons for the request; use polite words.' Students later check their own letters against it. What is the main benefit?","options":["It saves the teacher from having to read or correct any of the students’ letters","It ensures that all the letters written in the class are identical","It is useful only for the teacher’s own marking at the end of the task","Students see what success looks like and can improve their own work"],"answer":3,"explanation":"Shared success criteria make the target clear and enable self- and peer-assessment, a key practice of assessment for learning. They guide quality without forcing identical products.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1370","question":"Assertion (A): A good teacher follows the written lesson plan exactly, whatever happens in class. Reason (R): Planning gives direction and structure to teaching.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Planning does give direction, but good teachers adjust to evidence of learning, children's questions and unforeseen events. So R is true while A is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1371","question":"In Gagné's nine events of instruction, which three events come first, in order?","options":["Gaining attention, stating the objective, recalling prior learning","Presenting the content, gaining attention, providing feedback","Stating the objective, presenting the content, assessing performance","Recalling prior learning, gaining attention, eliciting performance"],"answer":0,"explanation":"Gagné's sequence begins by gaining attention, telling learners the objective and stimulating recall of prior learning, before presenting content, guiding learning, eliciting performance, giving feedback, assessing and enhancing retention and transfer.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1372","question":"A Class 4 teacher asks, ‘Why do many trees shed their leaves before summer?’ and, when no hand goes up within two seconds, answers it herself. The most useful advice for her is to:","options":["ask only easy questions that children can answer at once without pausing","put the question directly to the brightest child so the lesson moves on","give more wait time, and let children talk in pairs before answering","give the answer first and then ask the question to check memory"],"answer":2,"explanation":"Thinking questions need wait time; research shows longer pauses produce more and better answers. Answering herself teaches children to wait rather than think.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1373","question":"Which pair shows a closed question followed by an open question?","options":["What would you like to know about bats? / Is a bat a bird?","Is a bat a bird? / What would you like to know about bats?","Where do bats live? / Name two other animals that can fly.","How many legs does a bat have? / Does a bat have wings?"],"answer":1,"explanation":"‘Is a bat a bird?’ has one short answer; ‘What would you like to know about bats?’ invites children’s own questions. The first option reverses the order, and the others are both closed.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1374","question":"Which question best encourages divergent thinking in a Class 5 lesson on waste?","options":["What is the colour of the dustbin used for dry waste in our school?","Is plastic biodegradable, or does it stay in the soil for years?","Where is the garbage collected from our town finally dumped?","In how many different ways could we reuse a plastic bottle at home?"],"answer":3,"explanation":"Divergent questions have many acceptable answers and invite original ideas. The others have a single correct answer.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1375","question":"A Class 5 child asks, ‘Why do fireflies glow?’ and the teacher does not know the answer. The best response is to:","options":["admit she does not know and plan with the children how to find out","tell the child that the question is not in the syllabus for this year","give a confident guess as if it were the correct scientific answer","ask the child not to ask such difficult questions in the middle of class"],"answer":0,"explanation":"Admitting not knowing and finding out together models inquiry and values the child’s curiosity. Guessing as fact or dismissing the question damages both.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1376","question":"Which sequence best represents an inquiry cycle in an EVS lesson?","options":["Observe → record → predict → ask a question → explain to others","Explain → test → ask a question → predict → record","Question → predict → test → observe and record → explain","Plan → ask a question → predict → explain → observe"],"answer":2,"explanation":"Inquiry starts with a question, moves to a prediction and a test, then to recorded observation and finally explanation and sharing.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1377","question":"Which of the following are process skills that EVS aims to develop? I. Observation II. Classification III. Measurement IV. Rote recall of definitions","options":["I and II only","I, II and III only","II, III and IV only","I, II, III and IV"],"answer":1,"explanation":"Observing, classifying and measuring are process skills used in inquiry. Rote recall of definitions is not a process skill and is discouraged in EVS.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1378","question":"Which is the best-written learning objective for a Class 4 EVS lesson on houses?","options":["Children will know all about the different kinds of houses.","The teacher will cover pages 45 to 50 of the textbook in two periods.","Children will appreciate the many kinds of houses and the people who build them.","Children will explain, with two reasons, how local houses suit the weather."],"answer":3,"explanation":"A good objective states observable learning by children with a clear standard. ‘Know’ and ‘appreciate’ are vague, and covering pages is the teacher’s task, not a learning outcome.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1379","question":"Which classroom best reflects a constructivist approach to EVS?","options":["The teacher starts from children’s ideas, which they test and revise","The teacher explains the chapter clearly and children underline important lines","Children copy notes from the board and learn them for a test","The teacher reads the chapter aloud and asks the questions at the end"],"answer":0,"explanation":"Constructivism has learners build knowledge by working on their own ideas through activity and discussion. The others are transmission models.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1380","question":"Class 5 children judge which of two proposed sites is better for a new hand pump in their village, considering distance, drainage and who would use it, and defend their choice. In Bloom’s revised taxonomy, this task is mainly at the level of:","options":["Remembering","Understanding","Evaluating","Applying"],"answer":2,"explanation":"Making and defending a judgement using criteria is evaluating, near the top of the revised taxonomy. It goes beyond recall, explanation or applying a known procedure.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1381","question":"Which homework task is most in the spirit of EVS for Class 3?","options":["Learn the answers to all the questions at the end of the chapter by heart for a test","Find out from family which animals visit your house at night, and how you know","Copy the whole chapter neatly in your notebook with the headings underlined","Write the names of ten animals five times each in neat handwriting"],"answer":1,"explanation":"The task sends children to observe and talk with family, making home a site of inquiry. The others are rote.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1382","question":"Class 3 children make leaf prints with paint. What makes this an EVS learning activity and not only an art activity?","options":["Children compare the shapes and vein patterns and discuss how leaves differ","Children use bright colours and mix new shades for each of the prints","The finished prints are displayed on the classroom wall for visitors","The teacher gives marks for neatness and for the best arrangement of prints"],"answer":0,"explanation":"The EVS learning lies in close observation and comparison, which the art activity makes possible. Colour, display and neatness do not make it EVS.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1383","question":"A Class 4 child gives a wrong answer about why the pond dries up in summer. The teacher responds, ‘Interesting! What made you think so?’ The main purpose of this response is to:","options":["embarrass the child gently in front of the class so she is more careful","delay giving the correct answer so that the lesson can move faster","show the class that wrong answers are acceptable as final answers","understand the child’s reasoning and keep it safe to share ideas"],"answer":3,"explanation":"Probing reveals the thinking behind an answer, which the teacher can then work with, and children learn that ideas are welcome. The wrong answer is not accepted as final.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1384","question":"A Class 5 teacher has 60 children and wants all of them to think about why the village pond is shrinking. The most effective strategy is to:","options":["ask the whole class and take answers from the first two hands that go up","use think–pair–share, so each child thinks alone and then with a partner","ask the children to write down the answer given in the textbook","call the children one by one to the front of the class to answer"],"answer":1,"explanation":"Think–pair–share gets every child thinking and talking even in a large class. Taking answers from a few lets most children opt out.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1385","question":"In a one-room school, a single teacher handles Classes 3, 4 and 5 together. How does a thematic approach to EVS help her?","options":["She can teach the Class 5 lesson to all, since harder content stretches younger ones","She can take each class in turn for EVS while the other two do silent seatwork","All three classes explore one theme, like ‘Water’, with tasks at different levels","She can give one common worksheet on a theme to all three classes, for fairness"],"answer":2,"explanation":"A shared theme allows common discussion while tasks are graded for each class, which suits multi-grade teaching. Taking classes in turn is a common multi-grade routine but is not a thematic approach, and one worksheet for all ignores differences in level.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1386","question":"A Class 4 chapter says that the rainy season begins in June. Children in a Chennai school say that in their city the heaviest rain comes in October and November. The teacher should:","options":["value their experience and explore why rain comes at different times in India","tell them that the textbook is correct and that they must be remembering it wrongly","ask them to write the textbook answer in the examination anyway","skip the topic, since it is confusing and may mislead the other children"],"answer":0,"explanation":"Tamil Nadu gets much of its rain from the north-east monsoon in October–December. Children’s observations are correct, and the difference is a rich starting point for inquiry.","difficulty":"very-hard","source":"CTET Paper 1 · TNTET"},
  {"id":"cdp-pedagogy-subjects-1387","question":"Assertion (A): An EVS teacher should welcome children’s questions even when they seem unrelated to the lesson of the day. Reason (R): Children’s questions reveal their curiosity and thinking and can be used to guide teaching. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Questions show what children wonder about and how they think, which is why they should be welcomed, noted and taken up when possible.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1388","question":"After a visit to the fish market, a teacher notes in her diary that the children asked many questions about how much the fish seller earns and how early he wakes up, but few about the fish. The best use of this note is to:","options":["scold the children for asking off-topic questions instead of studying the fish","repeat the visit with a strict worksheet that keeps attention on the fish","conclude that these children are simply not interested in learning EVS","plan the next lessons around livelihoods, building on the children’s interest"],"answer":3,"explanation":"Reflective teachers use children’s responses to plan; livelihood is itself an EVS concern. Calling the questions off-topic misses a genuine entry point.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1389","question":"The NCERT EVS books end chapters with varied tasks such as ‘Find out’, ‘Discuss’, ‘Draw’ and ‘Tell’, instead of only written questions. The main reason is to:","options":["make the books longer and more attractive for children to look at","engage children in many ways and take learning beyond the classroom","reduce the teacher’s role so that children can manage on their own","prepare children early for the written board examinations of later years"],"answer":1,"explanation":"Varied tasks use talk, drawing, inquiry and writing, and many send children to family and surroundings. That breadth is the design intention.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1390","question":"A parent complains that EVS homework asks her child to ‘find out from elders’ instead of giving the answers in the book. The teacher’s best explanation is that:","options":["the book has no answers in it because it was printed in a great hurry this year","the teacher has no time in class to give answers to every question","such tasks value family knowledge and help children learn to find things out","the task is only meant to keep children busy at home in the evening"],"answer":2,"explanation":"These tasks are deliberate: they value home knowledge and build the skill of inquiry. They are not a gap in the book or busy work.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1391","question":"Three groups of Class 3 children sort the same set of animal pictures. One groups them by number of legs, another by what they eat and the third by where they live. The teacher should:","options":["accept all three and ask each group to explain the basis it chose","accept only the grouping by habitat, since that is the one in the textbook","ask all the groups to redo the task by number of legs, so results match","mark the task wrong because the three groupings do not match each other"],"answer":0,"explanation":"Classification depends on the chosen criterion; what matters is applying it consistently and explaining it. Insisting on one basis narrows thinking.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1392","question":"Class 5 children will do an activity with a lit candle under a glass. Which is the best approach for the teacher?","options":["Do the activity herself while children watch from a safe distance","Drop the activity altogether because it involves an open flame","Let children do it without instructions, so they discover the risks themselves","Explain safety rules, supervise closely and let small groups do it"],"answer":3,"explanation":"Safety and hands-on work go together: clear rules and supervision let children do the activity themselves. Dropping it or doing it only as a demonstration denies them experience.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1393","question":"A Class 5 survey project on water sources in the village can give the teacher evidence of which indicators? I. Observation and recording II. Discussion III. Analysis IV. Cooperation","options":["I and II only","I, II and III only","I, II, III and IV","II and IV only"],"answer":2,"explanation":"Surveys involve recording data, talking with people and classmates, interpreting patterns and working in groups, so all four indicators can be observed.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1394","question":"Which statement by a teacher best reflects her role as a facilitator in EVS?","options":["‘Listen carefully; I will tell you the correct answer in a minute.’","‘Let us find out together. How could we check your idea?’","‘Copy this diagram carefully; it will come in the test.’","‘Do not ask questions until I have finished the chapter.’"],"answer":1,"explanation":"A facilitator helps children test their own ideas instead of handing out answers. The others place the teacher as the sole source of knowledge.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1395","question":"A Class 4 child cannot define ‘adaptation’ but explains clearly why a duck has webbed feet and a hen does not. From the NCF 2005 point of view, the teacher should conclude that the child:","options":["has understood the idea, which matters more than stating a definition","has not really learnt the topic, since she cannot give the definition","should memorise the definition word for word before moving on","needs remedial teaching in EVS until she can define the key terms"],"answer":0,"explanation":"EVS at this stage avoids definitions and looks for understanding; explaining a real case shows it. Demanding the definition misreads the aim.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1396","question":"A Class 4 teacher puts up a ‘Wonder Wall’ where children stick slips with questions such as ‘Why do cats’ eyes shine at night?’ The main purpose is to:","options":["keep children quiet during lessons by giving them somewhere to write","decorate the classroom with colourful slips for visitors","find out which children can write neatly and spell correctly","value children’s questions and use them to plan inquiries"],"answer":3,"explanation":"Displaying children’s questions values curiosity and gives the teacher material for future inquiry. Decoration and neatness are not the point.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1397","question":"Half of a Class 6 section scores below 30% in an English unit test. Before planning any remedial classes, the teacher’s first step should be to:","options":["Repeat the whole unit at the same pace so that everyone revises it","Use a diagnostic test to find what is causing the low scores","Give the low scorers extra homework from the same exercises as before","Inform parents that their children need private tuition in English"],"answer":1,"explanation":"Remedial teaching depends on diagnosis: low scores can come from weak decoding, vocabulary, grammar or test-taking, and each needs a different response. Repeating the same teaching ignores the cause.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1398","question":"A Class 3 child understands stories read aloud and speaks with a rich vocabulary, but reads very slowly, confuses ‘b’ and ‘d’, and cannot sound out simple new words despite regular teaching. Which support is most appropriate?","options":["Structured, multisensory phonics, such as tracing letters while saying sounds","Moving her down to a lower class where the reading demands are lighter for now","Making her copy each confused letter fifty times to fix it in memory","Asking her to read aloud before the class daily so that she practises more"],"answer":0,"explanation":"Good oral language with persistent decoding difficulty suggests dyslexia. Explicit, systematic, multisensory phonics, with extra time and audio support, helps; public reading and punitive copying do harm.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1399","question":"Which of these practices goes against the principles of remedial teaching?","options":["Starting from what the learner can already do and building step by step","Using varied materials and activities suited to the learner’s difficulty","Giving frequent feedback and recording small gains to build confidence","Re-teaching the same content in the same way and at the same pace"],"answer":3,"explanation":"If the original teaching did not work for the child, repeating it unchanged is unlikely to work now. Remedial teaching changes the approach, pace and materials to match the diagnosed need.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1400","question":"A Class 7 teacher collects one composition from each student and sorts the errors: 40% tense, 30% articles, 15% prepositions and 15% others. The main use of this error analysis is to:","options":["Rank students from best to worst for the progress report","Prove to parents that the students have not been studying","Target teaching at the most frequent error patterns","Decide which students should be failed in the term examination"],"answer":2,"explanation":"Error analysis turns scattered mistakes into patterns, so remedial work can target what most learners need. It is a diagnostic tool, not a ranking device.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1401","question":"A teacher pairs a Class 5 child who reads fluently with a classmate who struggles, for 15 minutes of paired reading daily. Which statement about this peer tutoring is most accurate?","options":["It helps only the weaker reader; the fluent one gains nothing","It should be avoided, because only trained teachers can help weak readers","It usually benefits both, since tutoring deepens the tutor’s own skills","It works only when both children are of exactly the same reading level"],"answer":2,"explanation":"Peer tutoring gives the struggling reader extra supported practice, and the tutor consolidates skills by modelling and explaining; it also builds a cooperative classroom.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1402","question":"A Class 6 student reads at about the Class 2 level. For his remedial reading sessions, the most suitable texts are those that:","options":["Are the Class 2 picture books his younger cousins use, since the level matches","Match his age and interests but use simple language (high-interest, low-level)","Are taken from the Class 6 textbook so that he keeps up with his class","Have long lists of words to be read aloud without any story at all"],"answer":1,"explanation":"Texts meant for small children can embarrass an older learner and lose his interest; material with mature content but accessible language keeps him motivated while matching his reading level.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1403","question":"In a government school, for one hour a day children from Classes 3 to 5 are grouped by their actual reading level (letter, word, paragraph, story) instead of by class, and taught with level-appropriate activities; groups change as children progress. This approach is known as:","options":["Streaming children permanently into fixed ability sections","Grammar-translation for multi-grade classes with mixed abilities","Detention of weak children in their present class for another year","Teaching at the Right Level, grouping by level, not grade"],"answer":3,"explanation":"Teaching at the Right Level, developed by Pratham, groups children temporarily by assessed level so that teaching meets them where they are; flexible regrouping avoids permanent labelling.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1404","question":"Consider these statements: I. A diagnostic test aims to locate specific learning difficulties rather than to rank learners. II. An achievement test measures how far learners have mastered what was taught. III. A diagnostic test is usually given only once, at the end of the year. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":0,"explanation":"Diagnostic tests are used whenever difficulties need to be identified, typically before remedial teaching, not only at year’s end, so III is false.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1405","question":"A Class 4 child writes ‘hopping’ when she means ‘hoping’ and ‘runing’ for ‘running’. The most effective remedial step is to:","options":["Have her write each misspelt word twenty times in her notebook","Ignore the errors, since spelling will correct itself over time","Tell her to avoid words ending in ‘-ing’ in her writing for now","Use word sorts such as hop/hopping and hope/hoping"],"answer":3,"explanation":"The errors show confusion about one rule (short vowel and doubling versus silent ‘e’ dropping). Sorting words like hop/hopping and hope/hoping helps her discover the pattern behind both errors.","difficulty":"very-hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1406","question":"At the end of each English lesson, Class 7 students answer two short questions on a slip. The teacher reads the slips that evening and changes the next day’s plan to re-teach what most students found confusing. This is an example of:","options":["Assessment for learning, used to guide teaching","Assessment of learning, used to certify achievement","Norm-referenced testing, used to compare learners","Summative assessment, used for the report card"],"answer":0,"explanation":"Information that is used to adjust ongoing teaching is formative assessment, or assessment for learning; it is not about grading or comparing.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1407","question":"Class 8 students use a checklist (‘Does my story have a clear beginning? Have I used paragraphs?’) to review their own drafts, note what they need to improve and set a goal for the next piece. This practice is best described as:","options":["Assessment of learning","Norm-referenced assessment","Assessment as learning","Summative assessment"],"answer":2,"explanation":"Assessment as learning puts students in charge of monitoring and regulating their own learning, building metacognition; assessment for learning is mainly the teacher using information to adjust teaching.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1408","question":"A reading test on a passage about the Taj Mahal includes the question ‘In which city is the Taj Mahal?’, which most students can answer without reading the passage. This mainly lowers the test’s:","options":["Reliability, because scores would differ on another day","Validity, because it does not measure reading","Objectivity, because different markers may disagree","Practicality, because the test takes too long to mark"],"answer":1,"explanation":"If general knowledge alone answers an item, the item does not measure what it claims, namely understanding of the passage; that is a validity problem.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1409","question":"A teacher notices that she gives higher marks to essays she checks in the morning than to similar essays she checks late at night. The problem and its best remedy are:","options":["Low validity; she should set a different and easier essay topic next time","Low reliability; she should mark with a clear rubric and recheck samples","Low practicality; she should give fewer writing tasks to the class","Low objectivity of students; they should write more neatly"],"answer":1,"explanation":"Inconsistent scoring of the same quality of work by the same rater is an intra-rater reliability problem; explicit criteria and rechecking make marking more consistent.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1410","question":"A state board English examination contains only grammar multiple-choice questions. Teachers then stop doing speaking and writing activities and spend class time on MCQ practice. This effect of a test on teaching is called:","options":["Positive washback","Halo effect","Negative washback","Test reliability"],"answer":2,"explanation":"Washback is the influence of a test on teaching and learning; when a narrow test pushes teachers to neglect important skills, the washback is negative.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1411","question":"Which of the following is an integrative rather than a discrete-point language test?","options":["A dictation of a short connected passage","Marking the stressed syllable in a list of single words","Choosing the right preposition in ten unrelated sentences","Choosing the correct article in a list of nouns"],"answer":0,"explanation":"Integrative tests such as dictation and cloze draw on several skills and areas of knowledge at once; discrete-point tests check one item at a time, such as a single preposition.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1412","question":"A teacher checks whether each Class 3 child ‘can read a short story and tell what happened in it’, recording each child as ‘achieved’ or ‘not yet’, without comparing children with one another. This assessment is:","options":["Norm-referenced, since each child is judged against the class","Diagnostic only, since it uses the label ‘not yet’ for some children","Summative only, since it records whether the child achieved it","Criterion-referenced, as each child is judged against an outcome"],"answer":3,"explanation":"Criterion-referenced assessment judges performance against a defined standard or outcome; norm-referenced assessment ranks learners against each other.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1413","question":"A Class 2 teacher gives children a sheet of ‘I can…’ statements (‘I can tell a story from pictures’) with three faces to colour: happy, so-so, not yet. The main purpose is to:","options":["Replace the teacher’s own assessment of the children completely","Rank the children for the term report card","Help children reflect on their own learning in a simple way","Test children’s ability to colour within the lines"],"answer":2,"explanation":"Simple self-assessment helps even young learners become aware of what they can do and what to work on next, building ownership of learning.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1414","question":"Which written comment on a Class 5 story is most likely to help the child improve?","options":["‘Good work. 7/10. Try to make your next story as good as this one.’","‘Great opening! In the middle, add how Meena felt when the dog ran off.’","‘Very nice work! Your handwriting is neat and the story is nice and long.’","‘Too many mistakes. Rewrite the whole story neatly in your notebook.’"],"answer":1,"explanation":"Descriptive feedback names what works and gives a specific, doable next step; grades and general praise or criticism tell the child little about how to improve.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1415","question":"A teacher keeps brief dated notes such as ‘12 Aug: Ravi used “enormous” on his own while describing the elephant in free talk.’ This assessment tool is:","options":["An anecdotal record","A rating scale","A cumulative record","An achievement test"],"answer":0,"explanation":"Anecdotal records are brief factual notes of significant observed behaviour, useful for tracking language development in natural settings. A cumulative record is a long-term school file of overall progress.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1416","question":"As a Class 1 child reads a short book aloud, the teacher ticks each correct word on a copy and codes errors (substitutions, omissions, self-corrections) to see which cues the child is using. This tool, associated with Marie Clay, is a:","options":["Cumulative record","Cloze test","Checklist","Running record"],"answer":3,"explanation":"A running record captures a child’s oral reading in real time and is analysed for accuracy, self-correction and the cues used (meaning, structure, visual).","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1417","question":"An item in a Class 6 test reads: ‘A person who writes poems is called an ______. (a) poet (b) author (c) singer (d) painter’. What is the main flaw in this item?","options":["The ‘an’ in the stem cues ‘author’ and misleads students","It has more than one correct answer, so it is unreliable","It is too easy, since everyone knows what a poet does","It should have been an open-ended question instead"],"answer":0,"explanation":"The intended answer is ‘poet’, but ‘an’ fits only ‘author’, so the stem misleads and test-wise students may choose by grammar alone; stems should not give grammatical cues.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1418","question":"A school places all children who need extra help in English in a section publicly called the ‘weak group’, which stays fixed for the year. The main problem with this arrangement is that:","options":["Remedial help should never be given in groups, only one to one by a specialist","Children in the group will learn too fast and soon get bored","Fixed public labels lower children’s self-esteem and expectations","It makes planning harder for the teacher of that section"],"answer":2,"explanation":"Labelling can become a self-fulfilling prophecy. Remedial grouping should be need-based, temporary and discreet, with children moving on as they progress.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1419","question":"Consider these statements about continuous assessment in language: I. Assessment should be built into everyday teaching and learning. II. Only pen-and-paper tests give reliable information about language ability. III. Observation, conversations, projects and portfolios are valid ways of assessing language. Which are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":1,"explanation":"Continuous, comprehensive assessment uses many tools in many contexts; restricting assessment to written tests misses listening, speaking and real use of language.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1420","question":"A Class 7 class averages 85% in a test where students choose the correct verb form in separate sentences, but their free compositions are full of the same verb errors. Which conclusion is best supported?","options":["The test was too difficult, so the scores do not mean much","The students must have copied in the test and should be retested under watch","Free composition is an unfair way to test grammar knowledge","Knowing forms in isolated items does not ensure correct use in writing"],"answer":3,"explanation":"Discrete-point success shows explicit knowledge, but using forms while composing draws on automatic control; assessment must include integrated tasks to show real ability.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1421","question":"A Class 5 child who stammers volunteers to answer in English but gets stuck on the first word. The most helpful teacher response is to:","options":["Finish the word for him quickly so that he is not embarrassed","Avoid asking him questions in the future so that he is not stressed in class","Ask him to stop and try again only after he has calmed down","Wait calmly, keep eye contact and let him finish without time pressure"],"answer":3,"explanation":"Patient listening without completing words or rushing reduces pressure and shows that what he says matters; avoiding him denies him practice and participation.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1422","question":"Students have just explored how a balloon fixed on a bottle inflates in hot water and shrinks in cold water. At the start of the Explain phase of the 5E model, the teacher should first:","options":["Have students explain what they saw, then build scientific terms on that","Dictate the textbook explanation of the expansion of gases for students to note","Give a short test to see which students understood the activity","Show a new, unrelated demonstration to keep interest high in the class"],"answer":0,"explanation":"In the Explain phase, students' own explanations come first and the teacher then connects them to formal concepts and vocabulary. Dictation ignores what students made of the exploration.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1423","question":"Which task best fits the Evaluate phase of a 5E unit on heat insulation?","options":["Watching a video on how thermos flasks are designed and made in a factory","Reading the textbook section on conductors and insulators aloud","Designing a way to stop ice melting on the way home and justifying it","Listing all the definitions learnt in the unit and learning them by heart"],"answer":2,"explanation":"Evaluate asks students to show understanding by using it in a new situation and justifying their choices. Watching, reading and listing are not evidence of understanding.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1424","question":"A teacher asks, 'What will happen to a balloon on the mouth of a bottle if the bottle is put in hot water? Why?' Students write their answers, the teacher does it, and students then try to reconcile what they saw with what they wrote. This strategy is called:","options":["KWL (Know-Want-Learned) chart","Concept cartoon discussion","Jigsaw group work","Predict-Observe-Explain"],"answer":3,"explanation":"Predict-Observe-Explain asks students to predict with reasons, observe, and explain any difference between prediction and observation.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1425","question":"Before a unit on soil, a teacher makes a three-column chart with students: what we Know, what we Want to know, and what we Learned. The 'Want to know' column is most useful because it:","options":["Records the answers that students must memorise for the unit test","Gathers students' own questions to guide the unit's investigations","Shows the teacher which students already know the most about soil","Replaces the need for activities, since the questions are answered there"],"answer":1,"explanation":"In a KWL chart, students' questions in the 'W' column give direction and ownership to the inquiry, and are revisited in the 'L' column.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1426","question":"In a lesson on pollution, each member of a group studies one type (air, water, soil or noise) with members of other groups who have the same type, and then returns to teach it to the home group. This cooperative learning structure is:","options":["Think-pair-share","Jigsaw","Brainstorming","Role play"],"answer":1,"explanation":"In Jigsaw, each member becomes an 'expert' on one part with others, then teaches it to the home group, making everyone depend on each other's learning.","difficulty":"hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1427","question":"A Class 8 lesson teaches students to read their household electricity meter, calculate monthly consumption, and learn simple wiring safety, so that they gain skills useful for work. Which NCF 2005 criterion does this lesson serve most clearly?","options":["Historical validity","Process validity","Environmental validity","Ethical validity"],"answer":2,"explanation":"Environmental validity includes equipping learners with knowledge and skills to enter the world of work and placing science in their real surroundings. Reading meters is not mainly about methods of generating knowledge.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1428","question":"A Class 8 chapter adds a box listing famous inventors and the years of their inventions, to be memorised for the test. Does this achieve historical validity as NCF 2005 means it?","options":["Yes, because any historical information gives historical validity","Yes, because memorising dates develops a strong sense of history","No, because the inventors listed in the box are not Indian","No, because it is about how ideas developed, not names and dates"],"answer":3,"explanation":"Historical validity aims to let learners see science as an evolving social enterprise, how ideas arose, were challenged and changed. A list of names and dates adds rote load without that understanding.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1429","question":"A textbook section reads, 'A bar magnet has two poles, north and south.' Which revision would most improve its process validity?","options":["Adding a large coloured picture of a bar magnet with both its poles labelled","Having students hang a magnet freely and test each end with another magnet","Adding a clear definition of a magnetic pole in a highlighted box","Adding a box on the history of magnets and compasses in ancient China"],"answer":1,"explanation":"Process validity requires that students use the methods of science, observing and testing, to arrive at knowledge. Pictures and definitions merely restate the claim.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1430","question":"A group of Class 7 students proposes to find out whether a pesticide harms frogs by spraying it on frogs caught from a pond. What should the teacher do?","options":["Allow it, since it is a real investigation that answers a genuine local question","Allow it, but only with a small number of frogs to limit the harm","Redirect them to a non-harmful study, like observing pond frogs over time","Cancel all investigations involving animals for the rest of the year"],"answer":2,"explanation":"Ethical validity requires concern for life. The teacher can keep the inquiry while protecting the animals, for example by non-harmful observation or using available data.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1431","question":"During an activity, a few drops of dilute acid fall on a student's hand. What should the teacher do first?","options":["Wash the area at once with plenty of running water","Apply an ointment directly over the acid","Ask the student to wipe it off with a dry cloth and continue","Send the student to the principal's office"],"answer":0,"explanation":"Immediate washing with plenty of water dilutes and removes the acid; applying ointments over acid or delaying treatment can worsen the injury.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1432","question":"During a demonstration of an electric circuit, the bulb fails to glow. The most educational response from the teacher is to:","options":["Abandon the demonstration and explain the circuit from the textbook","Tell students that the bulb would normally glow and move on","Ask students what might be wrong and check each idea together","Replace the whole set-up quietly without saying anything about it"],"answer":2,"explanation":"Treating the failure as a problem to investigate models scientific troubleshooting: forming hypotheses (loose wire, dead cell, fused bulb) and testing them one by one.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1433","question":"In a school in a hill town, students find that water boils at about 97 °C, not at 100 °C as their textbook says. The best response from the teacher is to:","options":["Tell them to write 100 °C, since that is the correct textbook answer","Tell them that their thermometer must be broken and should be replaced","Ignore the difference, since 3 °C is too small to matter in an experiment","Discuss reasons, like lower air pressure at height, and how to check them"],"answer":3,"explanation":"Unexpected results are opportunities to reason from evidence. Boiling point falls with altitude, and checking the thermometer is also sensible; forcing the textbook value teaches dishonesty.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1434","question":"A Class 6 teacher first asks students to measure the length of the classroom in hand spans, and then compares the different answers they get. The main purpose is to:","options":["Help students see the need for a standard unit of length","Teach that hand spans are the most accurate unit of length","Save time, since hand spans are quicker than using a tape","Test which students have the largest hands in the class"],"answer":0,"explanation":"Different answers from different-sized hands make students feel the need for a common standard unit, which motivates the introduction of standard units.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1435","question":"While teaching adolescence and reproductive health in Class 8, a teacher finds that students are embarrassed and that several hold myths they heard at home. The most suitable approach is to:","options":["Skip the chapter, since it is a sensitive topic for many families","Ask students to read the chapter quietly at home, without any class discussion","Keep a respectful tone, give accurate facts and use an anonymous question box","Tell students not to discuss the subject with anyone, even at home"],"answer":2,"explanation":"NCF 2005 includes reproductive and sexual health at the upper primary stage. A safe, respectful setting, accurate information and anonymous questions help students overcome embarrassment and myths.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1436","question":"A student with a hearing impairment is in a Class 8 lesson on sound. Which arrangement best allows her to take part?","options":["Excusing her from the whole lesson, since she cannot hear the sounds being made","Letting her feel vibrations, as on a drum skin, with visual and written cues","Seating her at the back so that the others can hear the teacher better","Giving her extra reading from the textbook in place of the activities"],"answer":1,"explanation":"Sound is caused by vibrations, which can be felt and seen. Multi-sensory activities with visual cues allow full participation in the concept.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1437","question":"Assertion (A): A student's marks in written science tests alone are an inadequate indicator of her scientific ability. Reason (R): Science learning includes process skills and attitudes that written tests rarely capture.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Scientific ability includes observing, experimenting, curiosity and honesty, which written tests capture poorly; that is why marks alone are an incomplete picture.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1438","question":"Which question best assesses the process skill of interpreting data?","options":["Define solubility and give one example of a soluble substance.","Name two substances that dissolve in water and two that do not.","What is the chemical formula of common salt, and what is its common name?","Using a table of sugar dissolved at 20, 40, 60 °C, estimate it at 50 °C."],"answer":3,"explanation":"Interpreting data means reading patterns in data and making reasoned estimates from them. The other questions test recall only.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1439","question":"Students believe that plants take in water only to 'drink' it and that they lose none. Which activity best challenges this belief?","options":["Watering a potted plant and watching the soil around it get wet and dark","Covering a leafy branch with a clear plastic bag in sunlight","Measuring the height of the plant every day for a week","Cutting the roots of a plant and seeing whether it wilts"],"answer":1,"explanation":"Droplets inside the bag come from water vapour given out by the leaves (transpiration), showing that plants lose much of the water they absorb.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1440","question":"Students often say 'heat rises'. Which statement should the teacher help them reach?","options":["Heat always moves upwards, whatever the material it is passing through may be","Heat moves only by convection, so it must always travel upwards","Heat moves upwards in solids but downwards in liquids and gases","Warm fluids rise, but heat can travel any way by conduction and radiation"],"answer":3,"explanation":"It is warm fluid that rises, carrying heat by convection; heat conducts along a rod in any direction and radiates in all directions. The everyday phrase hides this distinction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1441","question":"A student says that water evaporates only when it is heated to 100 °C. Which question best challenges this idea?","options":["'What is the boiling point of water at normal air pressure?'","'Why do wet clothes dry on a line even on a cold winter day?'","'Does water boil faster in a covered pan or an open one?'","'What is the difference between boiling and melting a substance?'"],"answer":1,"explanation":"Clothes drying at ordinary temperatures shows that evaporation occurs at any temperature from the surface of a liquid; 100 °C is the boiling point, not the temperature of evaporation.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1442","question":"Which learning objective in a science lesson plan is stated in the most useful form?","options":["Students will know about magnets and their many uses in daily life.","Students will understand magnets well and enjoy learning about them.","Students will sort objects a magnet attracts and state a rule for them.","Students will appreciate the importance of magnets in modern technology."],"answer":2,"explanation":"An objective stated as observable behaviour (sort, state a rule) tells the teacher what to look for in assessment. 'Know' and 'understand' cannot be observed directly.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1443","question":"While planning a unit on electricity, a teacher draws a concept map of the ideas involved. This is most useful to her because it helps her:","options":["See how concepts link and which ideas students need first","Decide exactly how many periods the unit on electricity will need","Avoid using activities, since the map already shows all the ideas","Choose questions for the final test only, not for daily teaching"],"answer":0,"explanation":"A planning concept map shows how concepts connect and reveals prerequisites, such as a closed path before series circuits, so the unit can be sequenced logically.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1444","question":"On a nature walk to make a herbarium, students start plucking leaves and flowers from every plant they see. The teacher's best guidance is to:","options":["Allow it, since the herbarium needs as many specimens as possible","Stop the herbarium activity altogether and return to the classroom","Ask them to pluck only from plants in other people's gardens","Ask them to take mostly fallen leaves and only a few fresh samples"],"answer":3,"explanation":"Science activities should respect living things and the environment. Collecting fallen material and minimal samples meets the learning aim while showing concern for life.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1445","question":"For laboratory work, a teacher deliberately forms groups that mix students who are more and less confident in science. This is supported mainly by the idea that:","options":["Weaker students should be kept busy by the stronger ones in the group","Learners can go beyond their own level with help from abler peers","Mixed groups make the teacher's job of supervising much easier","Students should compete within groups to see who is the best"],"answer":1,"explanation":"Vygotsky's zone of proximal development suggests that learners achieve more with support from more knowledgeable others, including peers.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1446","question":"To help students understand insulation, a teacher wraps one glass of ice in newspaper and leaves another unwrapped. Students predict that the wrapped ice will melt faster, 'because paper makes it warm'. The best follow-up is to:","options":["Tell them clearly that they are wrong and then explain the correct answer","Observe both, compare melting times and discuss why paper slowed it","Skip the observation, since the answer is given in the textbook","Add more ice to the unwrapped glass so that the test is fairer"],"answer":1,"explanation":"Letting the evidence contradict the prediction, then discussing it, helps students see that the paper slows heat flow from the warm air to the ice rather than 'adding warmth'.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · KVS"},
  {"id":"cdp-pedagogy-subjects-1447","question":"A teacher gives Class 8 students a choice between preparing for a science quiz and carrying out a month-long investigation of plant growth in different soils. Which better develops inquiry skills, and why?","options":["The quiz, because it covers many more facts in a short time","The quiz, because competition makes students work much harder","The investigation, since students plan, collect and interpret data","Both equally, since both of them involve the subject matter of science"],"answer":2,"explanation":"An investigation engages students in the full process of inquiry; a quiz mainly rewards quick recall of facts.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1448","question":"Four children scored 2, 4, 0 and 6 in a quiz. A Class 7 student finds the mean as 4, saying ‘0 is nothing, so I divided 12 by 3.’ What is the misconception?","options":["She ignores 0 as a data value; the mean is 12 ÷ 4 = 3","She has added the four scores wrongly; the total is really 14","She has found the median of the scores instead of the mean","She has found the mode of the scores instead of the mean"],"answer":0,"explanation":"A score of 0 is still one child's value, so there are four values and the mean is 3. Thinking of the mean as ‘evening out’ the scores, with the 0 child receiving some too, shows why it counts.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1449","question":"A student gives the median of 7, 2, 9, 4, 5 as 9. What has she done?","options":["Taken the largest value in the list as the median of the data","Picked the middle value without first ordering the data","Found the mean of the values and rounded it up","Taken the value that occurs most often in the list"],"answer":1,"explanation":"9 is the middle entry of the unsorted list. Ordered, the data are 2, 4, 5, 7, 9, so the median is 5. The median depends on order of size, not on the order in which the data were written.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1450","question":"Which task best assesses a Class 7 student's understanding of the mean, beyond the procedure?","options":["Find the mean of 4, 8, 6 and 2, showing every step of the working clearly","Write down the formula for the mean and name each symbol used in it","Mean sweets for five children is 6; suggest each child’s share and explain","Find the mean of the first ten natural numbers without a calculator"],"answer":2,"explanation":"Working backwards from a mean to possible data needs the idea that the total is 5 × 6 = 30 and can be shared in many ways. Computing a mean only checks the procedure.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1451","question":"A bar graph of two shops' sales has its vertical axis starting at 50. Shop A's bar reaches 60 and Shop B's reaches 80. A student says Shop B sold three times as much as Shop A. What should the teacher help her notice?","options":["She is right, since the bar for Shop B is three times as tall as the bar for A","She has misread the values; they are really 6 and 8 on the scale","Bar graphs cannot be used to compare the sales of two shops","The axis starts at 50, so bar heights exaggerate it; 80 is only 4/3 of 60"],"answer":3,"explanation":"Above the 50 line the bars are 10 and 30 units tall, which looks like 3 times. The actual sales are 60 and 80. Reading axes critically, and spotting misleading graphs, is part of data literacy.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1452","question":"A die shows 6 three times in a row. A student says a 6 is now less likely on the next throw ‘because it has come too often’. How should the teacher respond?","options":["Say the die has no memory, so the chance stays 1/6, and test many throws","Agree, since the number 6 has already had more than its fair share of turns","Tell her that a 6 is now more likely, since the die seems to favour it","Tell her that probability cannot be used with dice or other games"],"answer":0,"explanation":"Each throw is independent, so the chance of a 6 stays 1/6. Thinking a result is ‘due’ or ‘used up’ is the gambler's fallacy; collecting real data helps students see that streaks occur naturally.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1453","question":"A student says that when two coins are tossed there are three outcomes, two heads, two tails, or one of each, so each has a probability of 1/3. What is the best response?","options":["Agree, since there are three possible results and each is equally likely","Have her list outcomes for a ₹1 and a ₹2 coin, then toss two coins many times","Tell her probability does not apply when two different coins are tossed together","Tell her the answer is 1/2 for each result, since a coin has two sides"],"answer":1,"explanation":"Distinguishing the coins shows four equally likely outcomes, so ‘one of each’ has probability 2/4 = 1/2, and two heads 1/4. Labelling the coins and experimenting expose the error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1454","question":"Asked to divide ₹40 between Asha and Babu in the ratio 3 : 5, a student gives Asha ₹24, saying ‘3/5 of 40 is 24’. What is the misconception?","options":["She has made an arithmetic slip while working out 3/5 of 40","She has given Asha's share to Babu by reversing the ratio","She reads 3 : 5 as 3/5 of the whole, not 3 of 8 parts","She has used the unitary method wrongly in the last step"],"answer":2,"explanation":"A part-to-part ratio of 3 : 5 means Asha gets 3 of 8 equal parts: 3/8 × 40 = ₹15, and Babu ₹25. Confusing part-part with part-whole is a common ratio error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1455","question":"Finding the area of a triangle, a Class 7 student multiplies half the base by the length of a slanting side. What is the best way to address this?","options":["Tell her to always take the longest side of the triangle as its height instead","Give her more triangles with the height already marked on each one","Ask her to learn the formula more carefully and revise it every day","Have her draw the perpendicular to the base and compare it with the slant side"],"answer":3,"explanation":"Height in ½ × base × height must be perpendicular to the base. Drawing it shows it is shorter than the slant side; marking it in advance would hide the very idea she lacks.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1456","question":"A student says that doubling the radius of a circle doubles its area. Which activity best challenges this?","options":["Draw circles of radius 2 cm and 4 cm on squared paper and compare areas","Ask her to learn the formula area = πr² by heart and apply it carefully","Show her that the circumference also doubles when the radius is doubled","Tell her that the area actually becomes three times larger"],"answer":0,"explanation":"Since area depends on r², doubling r multiplies area by 4 (4π against 16π). Counting squares makes this visible. The circumference does double, which is probably where her idea came from.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1457","question":"Students believe that cuboids with the same volume must have the same surface area. Which activity best challenges this?","options":["Giving them the formulae for volume and surface area to memorise and use","Building cuboids from 12 unit cubes and counting their outer faces","Measuring the volume of water in a jug with a measuring cylinder","Showing them that every cube and cuboid has exactly six faces"],"answer":1,"explanation":"Both cuboids have a volume of 12 cubes, but the outside surfaces are 50 and 32 square units. Building and counting shows the two measures are independent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1458","question":"A Class 7 student divides fractions quickly using ‘invert and multiply’ but cannot say what 3 ÷ 1/2 means, and in a new problem she inverts the wrong fraction. In Skemp's terms, her understanding is:","options":["relational, since she gets most of her answers right quickly","logical, since she follows a fixed procedure step by step","instrumental, since she knows the rule but not why it works","conceptual, since she knows the meaning of division well"],"answer":2,"explanation":"Instrumental understanding is ‘rules without reasons’; it works for familiar tasks but breaks down in new ones. Relational understanding, knowing what to do and why, lets a student rebuild or adapt the method.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1459","question":"A Class 6 student computes accurately and quickly but often cannot decide which operation to use in a word problem. Among the strands of mathematical proficiency, which one is weakest?","options":["Procedural fluency","Productive disposition","Adaptive reasoning","Strategic competence"],"answer":3,"explanation":"Strategic competence is the ability to formulate, represent and solve problems, including choosing an operation. Her procedural fluency is strong; that alone does not make her a problem solver.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1460","question":"Match each strand of mathematical proficiency with its description. 1. Conceptual understanding 2. Procedural fluency 3. Strategic competence 4. Productive disposition; a. seeing mathematics as sensible and worthwhile, and oneself as able to learn it b. carrying out procedures accurately, efficiently and flexibly c. grasping concepts, operations and the relations between them d. formulating, representing and solving problems","options":["1-c, 2-b, 3-d, 4-a","1-b, 2-c, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"These are four of the five interwoven strands described by Kilpatrick and colleagues; the fifth is adaptive reasoning, the capacity for logical thought, explanation and justification.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1461","question":"Which of these questions on fractions makes the highest cognitive demand on a Class 6 student?","options":["Work out 3/4 of 8 and show each step of your working clearly","Write a daily-life problem solved by 3/4 × 8 and explain why it fits","Write the fraction that shows 3 parts out of 4 equal parts of a whole","Is 3/4 a proper fraction or an improper one? Give the rule."],"answer":1,"explanation":"Creating a problem that fits a calculation needs the student to understand what ‘3/4 of’ means and to justify the match; it sits at the highest levels of Bloom's taxonomy. The others are recall or routine application.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1462","question":"Asked to draw the perpendicular bisector of a line segment with ruler and compasses, a Class 7 student measures the midpoint with a ruler and draws a right angle with a protractor. What should the teacher do?","options":["Mark it wrong and return the notebook to her without giving any explanation","Accept it, since the final result looks exactly the same as a construction","Ask her to use compasses and say why equidistant points lie on the bisector","Tell her that protractors must never be used at all in geometry"],"answer":2,"explanation":"Constructions are about reasoning: the compass arcs locate points equidistant from both ends, and those points lie on the perpendicular bisector. Measuring hides that reason, even if the drawing looks right.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1463","question":"A Class 7 student says that if the three angles of one triangle equal the three angles of another, the triangles must be congruent. Which response is best?","options":["Agree, since AAA is one of the accepted congruence rules","Tell her to remember only the SSS, SAS, ASA and RHS rules","Ask her to measure the angles again more carefully with a protractor","Ask her to draw two triangles with equal angles but different sizes"],"answer":3,"explanation":"Equal angles fix the shape but not the size, so AAA gives similar triangles, not congruent ones. A counterexample she draws herself is more convincing than a list of rules.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1464","question":"A student uses a² + b² = c² to find a side of a triangle that has no right angle. What is the best way to address this?","options":["Have her test it on a 4, 5, 6 cm triangle and discuss when it holds","Tell her that the formula works for every triangle, whatever its angles","Ask her to memorise the formula again and write it out ten times","Tell her to use the formula only for equilateral triangles from now on"],"answer":0,"explanation":"For sides 4, 5 and 6, 16 + 25 = 41, which is not 36, so the relation fails. Testing shows the condition (a right angle) is essential, not a detail to forget.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1465","question":"A Class 8 student writes 2⁻³ = −8. Which approach best helps her understand negative exponents?","options":["Tell her that a negative power always gives a negative number as the answer","Continue the pattern 8, 4, 2, 1 by halving, and ask what 2⁻³ must be","Ask her to learn the rule a⁻ⁿ = 1/aⁿ by heart and apply it","Ask her to check the answer on a calculator and correct it"],"answer":1,"explanation":"Each step down divides by 2, so 2⁻³ = 1/8. The pattern makes the definition sensible; the minus sign in the power does not make the value negative.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1466","question":"A student writes √(16 + 9) = √16 + √9 = 7. What is the error, and how can it be shown?","options":["She has found the square roots of 16 and 9 wrongly in her working","She should have squared the numbers instead of taking their roots","She treats roots as spreading over addition; √25 = 5 shows the error","She has added 16 and 9 wrongly before taking the square root of the sum"],"answer":2,"explanation":"√(16 + 9) = √25 = 5, not 7. Like (a + b)² = a² + b², this is an over-generalisation of the distributive law to operations where it does not hold.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1467","question":"The price of a book rises from ₹50 to ₹75. A student says this is a 25% increase. What is the misconception?","options":["She has divided the increase by the new price of ₹75 instead","She has calculated 25% of the new price of ₹75 and given that as the answer","She has mixed up percentage increase and percentage decrease","She took the ₹25 rise as the percentage; it is 50% of the original ₹50"],"answer":3,"explanation":"Percentage increase is the increase divided by the original amount: 25/50 = 50%. Treating the rupee change as a percentage ignores what it is a percentage of.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1468","question":"A car goes 120 km to a town at 40 km/h and returns at 60 km/h. A student says the average speed is 50 km/h. What is the best response?","options":["Have her find total distance and total time (240 km, 5 h) and compare","Agree, since the simple average of 40 and 60 is 50, just as she has said","Tell her that average speed cannot be found for a journey out and back","Tell her to use the formula for the mean of two numbers instead"],"answer":0,"explanation":"The trip takes 3 hours out and 2 hours back, so the average speed is 240 ÷ 5 = 48 km/h. The car spends longer at the slower speed, so a simple mean of speeds is wrong.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1469","question":"A teacher cuts a paper circle into many equal sectors and arranges them alternately into a shape close to a parallelogram. What is the main purpose?","options":["To teach students how to cut paper accurately into equal sectors","To link the circle’s area to a known shape, giving a reason for πr²","To find the exact value of π by measuring the sides of the rearranged shape","To show students that a circle is really a kind of polygon"],"answer":1,"explanation":"The rearranged shape is nearly a rectangle with length half the circumference (πr) and height r, so its area is πr². It is an informal argument for the formula, not a measurement of π.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1470","question":"Students count the faces, vertices and edges of many polyhedra and find that F + V − E = 2 every time. The teacher then asks them to check a solid with a hole through it, like a square picture frame. What is the teacher mainly teaching?","options":["That Euler's formula is false and should not be used for any solid at all","How to draw solids and their hidden edges on paper accurately","That rules found from examples may hold only under certain conditions","How to count the edges of complicated solids quickly"],"answer":2,"explanation":"For a solid with a hole, F + V − E = 0, so the pattern fails. Euler's formula holds for polyhedra without holes. Testing the limits of a conjecture is a key part of mathematical reasoning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1471","question":"Assertion (A): Students should explore proportion through real contexts such as recipes and maps before learning cross-multiplication. Reason (R): Cross-multiplication is an incorrect method for solving proportions.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Cross-multiplication is a correct method; the concern is that it is used mechanically without understanding. So A is true (contexts build proportional reasoning) and R is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1472","question":"Which of these statements about teaching data handling are correct? I. Students should collect their own data on questions they care about. II. Drawing graphs from textbook tables is enough for data literacy. III. Interpreting and questioning graphs, including misleading ones, is part of data handling. IV. The choice of graph depends on the kind of data.","options":["I and II only","II, III and IV","I, II and IV","I, III and IV"],"answer":3,"explanation":"Data handling includes asking questions, collecting, representing and interpreting data, and choosing suitable graphs. Copying textbook tables into graphs covers only one small part, so II is false.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1473","question":"Which of the following statements fit the NCF 2005 approach to teaching history?\n1. History should help children see links between the past and the present.\n2. History should be presented as completed knowledge that students must accept.\n3. History should include the experience of different regions, not only of capital cities.\n4. Students should get some idea of how historians know what they know.","options":["1, 2 and 3 only","2, 3 and 4 only","1 and 4 only","1, 3 and 4 only"],"answer":3,"explanation":"NCF 2005 wants history linked to the present, regionally plural, and taught with a sense of how historical knowledge is built from evidence. Treating history as finished knowledge to be accepted is what it moves away from.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1474","question":"Assertion (A): NCF 2005 suggests that economics at the upper primary stage be introduced through the experiences of ordinary people.\nReason (R): Economic matters have no relevance to children's lives until they become adults.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"Children already live amid buying, selling, wages and prices, which is exactly why economics can start from everyday experience. R is false, and it would actually argue against A.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1475","question":"A Class VII teacher includes the Chipko movement, in which village women in the Himalayan foothills hugged trees to stop felling, in a lesson on forests. What is the main value of this example?","options":["It proves that all forest laws made by the government are unjust","It shows ordinary people, including women, acting to protect resources","It shows that only the government can protect forests effectively","It provides an important date and place for students to memorise for the test"],"answer":1,"explanation":"Chipko shows citizens, especially women, as active agents in environmental protection. It is not a claim that all laws are unjust, and its value lies far beyond a date.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1476","question":"Which of the following is a divergent question for a Class VIII lesson on urban problems?","options":["In how many different ways could our town reduce its traffic jams?","Which ministry of the government is responsible for urban development?","What is the population of our town according to the last census?","Name the metro cities of India and the states they are in."],"answer":0,"explanation":"Divergent questions have many possible answers and encourage creative thinking. Convergent questions have one correct answer, such as a figure, a name or a list.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1477","question":"A social science teacher notices that during the mid-day meal some children are made to sit separately because of their caste. What is the most appropriate response?","options":["Ignore it, since the mid-day meal is not part of the social science period at all","Discuss the matter in class only if a parent comes and complains about it","Ask the separated children to move away quietly to avoid any conflict","Stop it, report it to the head and discuss it in class as unequal treatment"],"answer":3,"explanation":"Caste-based discrimination in school violates the Constitution and the dignity of children. The teacher must act and can use the issue to teach equality; staying silent makes the school complicit.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1478","question":"A Class VI student says, 'India has too many languages and religions; that is why there are problems.' Which response best fits the aims of social science?","options":["Agree, since a single language and religion would make the country stronger","Tell the student not to discuss such sensitive matters in the classroom","Explore coexistence, and how prejudice rather than diversity causes conflict","Ask the student to memorise the number of languages spoken in India"],"answer":2,"explanation":"Social science aims to build respect for diversity. Exploring examples of coexistence and the role of prejudice addresses the misconception directly; silence or agreement leaves it in place.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1479","question":"Class IX students compare three accounts of a 1920s textile mill strike: the management's report, a workers' union pamphlet and a newspaper article. All three agree on the date and number of workers, but they differ sharply on its causes. What should students conclude?","options":["Since the accounts disagree on the causes, none of them can be used","Agreement makes facts secure; disagreement shows the writers’ interests","The newspaper must be correct, since newspapers are always neutral observers","The union pamphlet must be correct, since the workers were the victims"],"answer":1,"explanation":"Corroboration across independent sources strengthens facts, and disagreement reveals perspective. Assuming any one type of source is automatically neutral or true is the error historians try to avoid.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1480","question":"Class IX students notice that the rainfall map and the population density map of India look broadly similar, and conclude that rainfall alone decides where people live. What should the teacher do next?","options":["Have them look for exceptions, like rainy hills with few people","Confirm the conclusion, since the two maps match closely in most places","Tell them that two maps of different things cannot be compared at all","Ask them to memorise the population density of each state for the test"],"answer":0,"explanation":"Patterns across maps are a good start, but exceptions such as the high-rainfall, thinly populated hills of the north-east show that several factors work together. Hunting for exceptions refines a hasty generalisation.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1481","question":"A Class VII teacher reads aloud a story about an Adivasi girl whose family struggles to keep its land. What is the main purpose of using such literature in social science?","options":["To replace the difficult chapter with a story that is easier for students to follow","To improve students' reading speed and pronunciation in class","To build empathy with the human side of an issue the chapter then examines","To give students a clear moral at the end that they can memorise"],"answer":2,"explanation":"Stories let students feel an issue from the inside, which motivates analysis of its causes in the chapter. They complement concepts rather than replace them.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-1482","question":"Which description best fits the role of the social science teacher according to NCF 2005?","options":["A facilitator who helps students inquire, discuss and build understanding","The sole source of correct information that students must accept","A supervisor who ensures that students copy notes accurately and neatly","An examiner whose main task is to prepare students for the board examinations"],"answer":0,"explanation":"NCF 2005 sees the teacher as a facilitator of learning who designs experiences and guides inquiry, not as the only authority or a transmitter of notes.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1483","question":"Assertion (A): Thematic maps, such as rainfall maps, use shades or colours to show variation across an area.\nReason (R): The equator is the line of latitude at 0°.","options":["Both A and R are true and R is the correct explanation of A","A is false but R is true","A is true but R is false","Both A and R are true but R is not the correct explanation of A"],"answer":3,"explanation":"Both statements are correct facts, but the position of the equator has nothing to do with why thematic maps use shading. R therefore does not explain A.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1484","question":"A Class X teacher shows data in which the child sex ratio is much lower in some states than in others and asks students to explain the difference. How should the teacher guide the discussion?","options":["Tell students that the difference is natural and needs no further explanation","Link the data to son preference and sex-selection, discussing them sensitively","Ask students to memorise the sex ratio of each state for the exam","Avoid the topic altogether, since it is too sensitive for Class X students"],"answer":1,"explanation":"Data become meaningful when linked to social causes; here, gender discrimination before birth. Sensitive, informed discussion builds awareness, while avoidance or rote figures lose the point.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1485","question":"Class IX students visit the local ration shop, record which items are available and at what prices, and talk to card holders. Which topic does this activity best support?","options":["Food security and the public distribution system","Foreign trade and the balance of payments","The history of agriculture and farming in ancient India","International organisations such as the WTO"],"answer":0,"explanation":"A ration shop is where the public distribution system meets people. Observing it and talking to card holders gives first-hand understanding of food security and its problems.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1486","question":"A Class VIII teacher shows how a textbook from the 1960s and a recent textbook describe the same historical event differently. What is the main learning?","options":["Old textbooks were wrong and should be ignored by students today","The newer textbook is always right because it is more recent","Historical writing changes as new evidence and questions emerge","History cannot be studied seriously, since it keeps changing"],"answer":2,"explanation":"Comparing textbooks shows that history is an ongoing interpretation shaped by evidence and by the questions of each generation. Neither 'old means wrong' nor 'new means right' follows.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1487","question":"A Class VII teacher asks, 'Who built the Taj Mahal?' Students reply, 'Shah Jahan.' She then asks, 'Did Shah Jahan cut and carry the marble?' What is she trying to bring out?","options":["That Shah Jahan did not actually order the monument to be built at all","That the answer given in the textbook is wrong and must be corrected","That monuments should not be studied in history at all, only rulers","That the many artisans and labourers, rarely named, also made history"],"answer":3,"explanation":"The question shifts attention from the patron to the workers whose labour made the monument, a 'history from below' perspective. It does not deny Shah Jahan's role as the patron.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1488","question":"Class IX students read extracts from the Constituent Assembly debates in which members argued over the national language. What is the main learning?","options":["That the Constitution was copied from other countries without debate","That members of the Assembly agreed on everything right from the very start","That the Constitution emerged from debate, disagreement and compromise","That language has never been an important issue in Indian politics"],"answer":2,"explanation":"Primary debate extracts show that constitutional provisions were argued over and negotiated, a model of democratic deliberation. This counters the idea that the Constitution was simply handed down or copied.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1489","question":"A Class VIII teacher wants to show students the stages through which a bill becomes a law. Which visual aid is most suitable?","options":["A pie chart","A flow chart","A bar graph","A timeline of Indian history"],"answer":1,"explanation":"A flow chart shows a sequence of steps and decision points, which matches the passage of a bill through the Houses and the President's assent. Pie charts and bar graphs show quantities.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1490","question":"Which kinds of questions should a social science test avoid?\n1. Questions that reward reproducing textbook lines\n2. Questions that ask students to evaluate a source\n3. Questions that assume experiences only some students have had","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Questions that reward reproduction encourage rote learning, and questions that assume particular experiences are unfair. Evaluating a source is a valuable higher-order task that tests should include.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-1491","question":"A Class VI teacher ends every social science lesson with a moral such as 'We must always obey our elders.' Which critique is most in line with NCF 2005?","options":["Values should be discussed against ideals like justice, not preached","Values have no place at all in social science, which deals only with facts","She should give more morals per lesson so that students remember them","Morals should be taught only in the language class, through stories"],"answer":0,"explanation":"NCF 2005 gives social science a normative role, but through engagement with values, not preaching. An unexamined moral such as unconditional obedience can even conflict with ideas of rights and justice.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1492","question":"To teach equality in Class VIII, students survey their own school for ramps, accessible toilets and materials for students with disabilities, and write to the principal with suggestions. What is the main value of this activity?","options":["It replaces the need to read the chapter on equality in the textbook","It shows students that equality applies only to matters of caste and gender","It ensures that the school receives more funds from the government","It extends equality to persons with disabilities and links it to action"],"answer":3,"explanation":"The audit makes equality concrete, widens it to disability, and gives students a constructive civic action. Equality is not limited to caste and gender.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1493","question":"Class X students struggle with words like 'sovereign', 'subsidy' and 'federal'. Which strategy builds understanding best?","options":["Give a glossary of all the terms for students to memorise before the chapter","Introduce each term in real contexts and have students use it in sentences","Avoid using these difficult terms in class until the board exam","Ask students to look up each of the words in a good dictionary at home"],"answer":1,"explanation":"Subject vocabulary is learnt by meeting and using words in context. A glossary or dictionary definition alone gives labels without understanding, and avoiding the terms leaves students unable to read the discipline.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1494","question":"A teacher plans a Class X debate on the motion 'Industrialisation was good for India'. Which change would most improve the thinking it produces?","options":["Allow only the class toppers to speak, so that the arguments are of high quality","Give marks to the side with more speakers, to encourage participation","Reframe it as ‘For whom, and at what cost, did industrialisation bring change?’","Hold the debate without any preparation, so the arguments are spontaneous"],"answer":2,"explanation":"A yes-or-no motion forces a binary that hides complexity. Asking who gained, who lost and at what cost pushes students to weigh evidence about different groups.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1495","question":"Class VIII students compare satellite maps of their city from 1995 and 2020 and mark where farmland and lakes have turned into housing. What does this mainly develop?","options":["Reasoning about change in land use over space and time","Memory of the city's ward numbers and their boundaries","Skills in drawing buildings and roads accurately to scale","Knowledge of the history of satellites and space research"],"answer":0,"explanation":"Comparing maps from two dates combines spatial and temporal thinking and raises questions about why land use changed and with what effects.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1496","question":"Which of the following is a secondary source for a Class VI student studying the Mauryas?","options":["An inscription of Ashoka carved on a rock or pillar","A punch-marked silver coin from the Mauryan period","A pottery fragment dug up at a Mauryan site","A chapter on the Mauryas in a present-day textbook"],"answer":3,"explanation":"Inscriptions, coins and pottery come from the period itself and are primary. A present-day textbook chapter interprets those sources and is therefore secondary.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1497","question":"While teaching a Class IX chapter on pastoralists, the teacher learns that Irfan's family are Bakarwal herders who migrate seasonally. When she asks him to tell the class about it, he looks down and stays silent. What should she do?","options":["Insist that he speak now, since his experience is so valuable for the lesson","Offer choices, like sharing later or in writing, and value his knowledge","Assume he knows nothing about it and move on to the next student","Tell the class about his family’s way of life herself, on his behalf"],"answer":1,"explanation":"Children from marginalised communities may hesitate to be singled out. Offering choices respects his agency while showing that his community's knowledge matters; speaking for him or forcing him can expose him to embarrassment.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1498","question":"A Class VIII teacher takes the theme of water first at the level of the students' own mohalla, then the state, then the country and finally the world. What is the main value of studying one theme at these different scales?","options":["It shows how one issue differs across scales and how places connect","Students can then avoid studying their own region in great detail","It reduces the total number of themes that students have to learn","It makes social science the same as science, which uses scales too"],"answer":0,"explanation":"Moving from local water use to national and global questions shows the connection between scales and places, a central idea in geography. It neither skips the local nor merely cuts content.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1499","question":"Midway through a Class V lesson on fractions, Ms Iyer sees puzzled faces when she uses a pizza example, so she immediately switches to folding paper strips, which the children know well. In Donald Schön's terms, this is:","options":["Reflection-on-action","Reflection-for-action","Reflection-in-action","Critical incident analysis"],"answer":2,"explanation":"Reflection-in-action is thinking on one's feet and adjusting during the activity itself. Reflection-on-action happens afterwards, looking back on what happened.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1500","question":"To understand how her teaching is experienced, a Class VIII teacher asks students to write anonymously at the end of each week: 'When were you most engaged this week? When did you feel most confused?' In Stephen Brookfield's framework of critical reflection, she is using which lens?","options":["The autobiographical lens (her own experience as a learner)","The students' eyes lens","The colleagues' perceptions lens","The theoretical literature lens"],"answer":1,"explanation":"Brookfield's four lenses are the teacher's own autobiography, students' eyes, colleagues' perceptions and theory or research. Anonymous student feedback is the students' lens.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1501","question":"A Class VI teacher notices that many students do not participate in English speaking activities. She tries pair work before whole-class speaking for three weeks, records how many students speak, and then reflects on the results. According to the action research cycle, what should she do next?","options":["Present the findings as a universal rule that all schools should adopt for English speaking","Stop the study, since one completed cycle of action research gives a final, settled answer","Return to her original method, since three weeks is far too short a time to show any change","Revise the plan using what she learnt and begin a new cycle of action and observation"],"answer":3,"explanation":"Action research is cyclical: plan, act, observe, reflect, and then re-plan. Its findings improve the teacher's own context rather than becoming universal laws.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1502","question":"Consider the following statements about action research by teachers: 1. It is carried out by practitioners to improve their own practice in their own setting. 2. Its main aim is to produce general laws that apply to all classrooms. 3. It usually proceeds in cycles of planning, acting, observing and reflecting. Which of these are correct?","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Action research is practical, local and cyclical; it seeks improvement in a particular classroom rather than generalisable laws, so statement 2 is false.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1503","question":"Which of the following is the most suitable problem for a Class V teacher's action research?","options":["What is the effect of family income on literacy rates across all the states of India?","Why do eight children in my Class V not finish their written work, and how can I help them?","How did the education policy of 1968 influence the adoption of the three-language formula?","Is a child's intelligence mainly inherited from parents or mainly acquired from the environment?"],"answer":1,"explanation":"Action research focuses on a specific, practical problem in the teacher's own classroom that she can act on. The other questions are large-scale, historical or theoretical research topics.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1504","question":"According to John Dewey, reflective thinking typically begins when a teacher:","options":["follows a routine that has always worked well with her earlier classes","faces a situation of doubt or difficulty that needs resolving","receives a circular from the department asking her to change her methods","memorises the steps of a teaching method given in the teacher's handbook"],"answer":1,"explanation":"For Dewey, reflection starts from a felt difficulty or uncertainty, which leads to inquiry and careful consideration of beliefs and actions. Routine action does not call for reflection.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1505","question":"Which classroom practice best shows the teacher acting as a facilitator of learning, as envisaged in NCF 2005?","options":["The teacher explains each answer fully and step by step, so that children never form or carry mistaken ideas about the topic","The teacher dictates clear, well-organised notes that children memorise and revise carefully before each unit test","The teacher asks why shadows in the room change during the day, gives materials and guiding questions, and lets children explore","The teacher reads the textbook aloud with expression while children follow the lines with their fingers and underline key words"],"answer":2,"explanation":"A facilitator designs situations, provides resources and asks questions so that children construct understanding themselves. Explaining every answer or dictating notes keeps the teacher as transmitter.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1506","question":"Assertion (A): A teacher acting as a facilitator may still give direct explanations at certain points in a lesson. Reason (R): Constructivism holds that learners actively construct knowledge rather than passively receiving it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Facilitation does not exclude well-timed explanation, for example after children have explored, so A is true; R is also true. But R explains why the teacher facilitates, not why she sometimes explains directly.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1507","question":"A Class VI teacher invites a colleague to observe her class. Which arrangement is most likely to help her grow professionally?","options":["The colleague drops in without warning, so that he sees her normal teaching, and reports what he saw to the principal","The colleague observes the full lesson and gives her a numerical rating on every aspect of teaching for her service file","The colleague observes and then teaches the next lesson himself, so that she can see the right way to handle it","They agree on one focus beforehand, he records evidence on it, and they discuss it afterwards without judgement"],"answer":3,"explanation":"Peer observation supports reflection when it is collaborative, focused, evidence-based and non-evaluative. Surprise inspections or ratings make it threatening and less useful.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1508","question":"Which reflective journal entry by a Class IV teacher shows the deepest level of reflection?","options":["'Today I taught the lesson on directions using the map in the textbook. The children enjoyed it and the class was lively throughout.'","'The lesson on directions went badly. The children were very noisy, did not listen to my instructions and kept talking among themselves.'","'Many children confused left and right on the map, I think because I faced them while demonstrating. Tomorrow I will stand with my back to them.'","'I completed the chapter on directions as per my lesson plan, covered all the textbook exercises and gave homework from the back of the chapter.'"],"answer":2,"explanation":"Deep reflection describes what happened, analyses why using evidence, and plans a change. The other entries are merely descriptive or blame students without analysis.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1509","question":"Listening to an audio recording of her own Class VII lesson, Ms Fernandes notices that she called on boys twice as often as girls and gave boys more follow-up questions. What is the most appropriate next step?","options":["Delete the recording and move on, since calling on boys more often is a natural classroom pattern that cannot be changed","Acknowledge the unconscious bias, use strategies such as random selection and equal wait time, and record another lesson","Ask the girls to raise their hands more often, since the teacher can only call on those who volunteer to answer","Conclude that the boys are more interested in the subject, and plan more challenging questions to keep them engaged"],"answer":1,"explanation":"Recording reveals patterns teachers are unaware of; reflective practice turns this evidence into deliberate change and checks the effect. Blaming the students or ignoring it leaves the bias in place.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1510","question":"In her school, Class V teachers meet every two weeks to look at samples of students' written work together, discuss what the work shows about learning, and plan changes in their teaching. This practice is best described as:","options":["A professional learning community, in which teachers learn together from evidence of students' learning","An inspection exercise meant to find out which teacher's section is weakest so that the principal can act on it","An administrative meeting held mainly to complete the school's assessment records and registers on time","A competition between sections to see which class teacher's students produce the neatest written work"],"answer":0,"explanation":"Professional learning communities focus on collaborative inquiry into student learning and shared improvement of teaching. They are developmental, not evaluative or administrative.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1511","question":"A Class III child says confidently, 'Plants eat soil; that is why they grow in it.' What is the best response from a teacher acting as a facilitator?","options":["'Wrong. Plants make their own food in their leaves. Write the correct answer in your notebook now.'","'Good answer!' and move on to the next child, so as to protect this child's confidence in speaking up","'Ask your parents about it tonight and tell the whole class the right answer when you come tomorrow.'","'Interesting idea. Why do you think so? How could we check if the soil gets less as the plant grows?'"],"answer":3,"explanation":"A facilitator treats children's ideas as starting points, asks for reasoning and helps design a way to test them. Simply correcting or wrongly praising both miss the chance for children to reconstruct their understanding.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1512","question":"Consider the following statements about continuous professional development (CPD) of teachers as envisaged in NEP 2020: 1. Each teacher is expected to take part in at least 50 hours of CPD every year. 2. CPD can only be done through formal degree courses. 3. Teachers should have opportunities to choose CPD according to their own interests and needs. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"NEP 2020 expects at least 50 hours of CPD a year, offered in many modes (workshops, online modules) with teacher choice. It is not limited to degree courses, so statement 2 is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1513","question":"Lawrence Stenhouse argued that curriculum development should rest on the 'teacher as researcher'. Which practice best fits this idea?","options":["Teachers treat curriculum ideas as hypotheses, test them in their own classes and refine their teaching","Teachers deliver the curriculum exactly as designed by subject experts, since any change would weaken it","Teachers leave research to universities and focus their energy on completing the syllabus on time","Teachers conduct large surveys across many districts so that their findings can shape national policy"],"answer":0,"explanation":"Stenhouse saw teachers as inquirers who treat curriculum proposals as hypotheses to be tested in their own classrooms. Passive delivery is the opposite of his view.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1514","question":"Many Class VIII students in two sections fail to submit homework. Mr Rao responds by increasing the penalty for missing homework. Ms Das asks herself whether the homework is meaningful, whether students can do it without help at home, and what homework is meant to achieve, and then redesigns it. In Argyris and Schön's terms:","options":["Both teachers are showing double-loop learning","Mr Rao shows double-loop learning and Ms Das shows single-loop learning","Mr Rao shows single-loop learning and Ms Das shows double-loop learning","Neither teacher is reflecting on practice"],"answer":2,"explanation":"Single-loop learning changes actions within existing assumptions (more punishment); double-loop learning questions the underlying assumptions and goals themselves, as Ms Das does.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1515","question":"After video-recording a Class VI discussion lesson, a teacher finds that she spoke for about 80% of the time and students' answers were mostly one word. Which change best follows from this reflection?","options":["Speak faster and more clearly so that more of the planned content is covered within the period","Plan open questions, use longer wait time and pair talk, and step back so students talk more","Ask mainly yes/no questions so that every student can answer quickly and nobody feels left out","Stop recording lessons, since the camera makes both the teacher and the students nervous and quiet"],"answer":1,"explanation":"Reducing teacher talk and creating structures for student talk (open questions, wait time, pair discussion) shifts the class toward active learning, which is what the evidence calls for.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1516","question":"After a Class IV lesson, a teacher says, 'The lesson went very well; the children were happy and active.' A mentor asks, 'How do you know what they learnt?' Which practice should the teacher adopt?","options":["Rely on her own feeling about the lesson, since an experienced teacher knows her class well","Judge success by how quiet and attentive the class remained while she was explaining the topic","Judge success by whether all the planned textbook pages and exercises were completed on time","Judge the lesson by evidence of learning, such as children's work, answers and exit tasks"],"answer":3,"explanation":"Reflective practitioners evaluate lessons using evidence of learning, not only impressions of enjoyment, quietness or coverage. Activity does not automatically mean learning.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1517","question":"A Class VII teacher asks students to keep a learning log in which they write after each lesson: 'What did I learn? What is still confusing? What helped me learn?' What does this mainly develop?","options":["Students' handwriting speed and neatness, through daily writing practice after lessons","Students' metacognition, as they monitor their own learning and strategies","Students' memory of textbook definitions, since they rewrite key points after every lesson","A record of attendance and lesson coverage that the teacher can show during inspections"],"answer":1,"explanation":"Reflecting on what one has understood and what helps one learn builds metacognitive awareness, and the logs also give the teacher feedback for planning.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1518","question":"Two views of the teacher are being compared. View X: the teacher is a technician who applies methods designed by experts. View Y: the teacher is a reflective practitioner. Which statement best captures View Y?","options":["She makes judgements in complex, uncertain situations by constantly examining her actions, beliefs and their effects","The teacher should follow the methods prescribed in the teacher's manual closely, since they were designed by experts","The teacher's main professional task is to complete the syllabus on time and prepare students well for examinations","Reflection is mainly useful for new teachers in their first year, until they have mastered the standard methods"],"answer":0,"explanation":"Schön's reflective practitioner treats teaching as complex problem-solving informed by ongoing reflection, not mechanical application of fixed methods. Reflection matters throughout a career.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1519","question":"During a Class V science lesson, a student asks a question the teacher cannot answer: 'Why do cats' eyes shine in the dark?' What is the most appropriate response from a teacher who sees herself as a co-learner and facilitator?","options":["Tell the student the question is not in the syllabus, so the class should focus on the chapter","Give a confident answer on the spot, since admitting ignorance would reduce the class's trust in her","Admit she is not sure and plan with the class how to find out, then share the findings later","Ask the student to save such difficult questions for the higher classes, where they will be taught"],"answer":2,"explanation":"Modelling honest inquiry ('let us find out') shows that knowledge is built, not just held by the teacher. Inventing an answer spreads misconceptions and dismissing the question kills curiosity.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1520","question":"A teacher in Ajmer feels that the Class IV EVS textbook chapter on 'Houses' shows only city flats and bungalows, while her students live in kuchcha and pucca houses in villages and in temporary shelters. What should she do as a reflective, autonomous teacher?","options":["Teach the chapter as given, then add a line noting that village houses also exist","Write to the SCERT about the gap and wait for a revised edition before teaching the chapter","Replace the chapter with her own lesson on village houses and leave out city homes","Use the textbook as one resource and add children's own homes, materials and shelters"],"answer":3,"explanation":"NCF 2005 treats the textbook as one resource and asks teachers to connect it to children's lives while keeping the wider view. Replacing the chapter with village houses alone is tempting but drops the diversity of homes the topic is meant to show, and a token line or waiting for a new edition fails the learners now.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1521","question":"Match each reflective activity with what it mainly offers. P. Keeping a teaching journal; Q. Peer observation; R. Collecting anonymous student feedback; S. Reading research on how children learn fractions. Offers: 1. Students' perspective; 2. A colleague's perspective; 3. Theoretical perspective; 4. The teacher's own perspective over time.","options":["P-4, Q-2, R-1, S-3","P-2, Q-4, R-1, S-3","P-4, Q-1, R-2, S-3","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"These map onto Brookfield's lenses: a journal gives the teacher's own view over time, peer observation a colleague's view, anonymous feedback the students' view, and research the theoretical lens.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1522","question":"A Class VI teacher writes after a lesson: 'Two children cried when I returned their test papers in front of everyone.' She later analyses why it happened and what it shows about her assessment practice. This method of reflection is called:","options":["Micro-teaching feedback cycle","Programmed learning","Critical incident analysis","Cooperative team teaching"],"answer":2,"explanation":"Critical incident analysis takes a significant event and examines its causes and meanings to question one's practice. It is a reflection tool, unlike micro-teaching or team teaching, which are teaching formats.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1523","question":"Assertion (A): Reflective practice requires a teacher to examine not only her methods but also the beliefs and assumptions behind them. Reason (R): Unexamined beliefs, for example about which children are 'capable', can shape teaching decisions without the teacher being aware of it.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because hidden assumptions drive choices (whom to call on, what to expect), critical reflection has to look at beliefs as well as techniques. R gives exactly this reason.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1524","question":"Consider these statements about primary EVS in the light of NCF 2005: I. It should help children see links between natural and social phenomena. II. Children’s local knowledge may be used in class only after it is confirmed by the textbook. III. It should develop sensitivity towards the environment and towards people. IV. Learning in EVS should be judged mainly through written term-end tests. Which are correct?","options":["I and II only","III and IV only","I, III and IV only","I and III only"],"answer":3,"explanation":"NCF 2005 treats local knowledge as valid in its own right and favours continuous, varied assessment over term-end tests, so II and IV are wrong; I and III state its aims.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1525","question":"Assertion (A): Concept maps are useful for assessing children’s understanding in EVS. Reason (R): Concept maps were first developed in the 1970s. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Novak’s team developed concept maps in the 1970s, but their usefulness in assessment comes from showing how a learner links ideas, not from their date of origin.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1526","question":"Many Class 5 children in a school in the Little Rann of Kutch come from families that make salt in the salt pans. The richest way to use this in EVS is to:","options":["avoid the topic, since the work is hard and children may feel embarrassed about their parents' jobs","show a video of a modern salt factory in another country, so that children see the latest technology","ask children to learn the chemical name and formula of common salt, since that is the scientific fact","invite parents to explain how salt is made and discuss the working conditions, such as heat and brine"],"answer":3,"explanation":"The families’ work links ‘Water’ and ‘Things We Make and Do’ with livelihood and working conditions, and respects children’s background. Avoiding it or replacing it with distant examples wastes a real resource.","difficulty":"very-hard","source":"CTET Paper 1 · GTET"},
  {"id":"cdp-pedagogy-subjects-1527","question":"Which of the following is an activity WITHOUT a clear EVS learning purpose?","options":["Children compare the feet of a hen and a duck and guess why they are so different","Children colour a printed outline of a cow, and the teacher moves on without discussion","Children track how the water level of a nearby pond changes over three months of the year","Children ask a local shopkeeper where the vegetables in his shop come from each morning"],"answer":1,"explanation":"Colouring an outline with no observation, discussion or question is busy work. The other activities each involve observing, recording or inquiring.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1528","question":"Match each alternative conception with the activity that best challenges it: 1. ‘Sugar is destroyed when it dissolves in water.’ 2. ‘Air has no weight.’ 3. ‘Plants do not need light.’ 4. ‘Seeds are non-living.’ a. Tasting the water and letting some of it dry to see what is left. b. Balancing two blown-up balloons on a stick and bursting one. c. Keeping one potted plant in a dark box and one in light, watering both equally. d. Soaking and sowing seeds and comparing them with dry seeds.","options":["1-b, 2-a, 3-c, 4-d","1-a, 2-b, 3-d, 4-c","1-a, 2-b, 3-c, 4-d","1-d, 2-b, 3-c, 4-a"],"answer":2,"explanation":"Sweet taste and leftover crystals show sugar is still there; the burst balloon side rises, showing air has weight; the dark-box plant tests light alone; germination shows seeds are alive.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1529","question":"Which plan for the theme ‘Food’ in Class 4 is the most integrated?","options":["Reading the chapter on food carefully, answering all its questions and drawing a balanced plate in the notebook","A science period on nutrients and their sources, followed by a short written test on the different vitamins","Learning the names of common food grains and pulses in English and Hindi and writing them in a neat chart","Surveying home breakfasts and graphing them, writing a family recipe, discussing who cooks, and planting herbs"],"answer":3,"explanation":"The last plan brings in mathematics, language, gender roles and growing food around one theme, starting from children’s homes. The others stay within one subject or one skill.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1530","question":"A school ranks Class 4 children by their EVS test marks and puts the list on the noticeboard. The strongest criticism of this practice is that it:","options":["takes up noticeboard space that would be better used for displaying children's drawings and project work","encourages comparison and labelling, discouraging many children instead of showing each child's progress","does not give the top-scoring children any reward or certificate beyond seeing their names on the list","is done after every test, when such a ranking list should really be put up only once a year"],"answer":1,"explanation":"Public ranking turns assessment into competition and labels; CCE stresses each child’s progress and descriptive feedback. Doing it less often does not fix the problem.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1531","question":"During a lesson on soil, some Class 4 girls refuse to touch earthworms, saying, ‘Girls get scared of such things.’ The teacher’s best response is to:","options":["let only the boys handle the earthworms, since girls are naturally more sensitive and easily frightened by such creatures","tell the girls firmly to handle the earthworms at once, or they will lose marks for the practical activity","handle the earthworms gently herself, invite each child to try at their own pace, and discuss how fears are learnt","skip the earthworm activity altogether, so that no child in the class is made to feel uncomfortable"],"answer":2,"explanation":"The remark repeats a learnt gender script. Modelling, gentle encouragement and discussion challenge it without force; excusing girls or forcing them both reinforce problems.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1532","question":"After a visit to a vegetable farm, Class 5 children have made notes of very different quality and depth. The most useful follow-up activity is to:","options":["collect the best notebook and read it aloud to the class, so that everyone knows what a model answer looks like","give a short written test on the farm visit, to check which children paid attention during the trip","ask the children to copy the teacher's summary of the visit, so that all of them have complete and correct notes","let groups pool their observations into a shared chart and list the questions still unanswered"],"answer":3,"explanation":"Pooling lets every child contribute and learn from others, and listing open questions keeps the inquiry going. A model answer or copied summary sidelines most children’s observations.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1533","question":"Looking at a bird’s nest, a teacher wants to move Class 3 children from observing to reasoning. Which sequence of questions does this best?","options":["Why did the bird build it? → What is it made of? → What is this thing called? → Now draw it neatly in your notebook.","What do you see? → How is it unlike last week's nest? → Why is it built this way? → What if it were on the ground?","Is it a nest? → Is it big or small? → Is it brown or grey? → Is it made of twigs? → Is it up in a tree?","Name the bird that built it. → Name the colour of its eggs. → Name its food. → Name the animals that hunt it for food."],"answer":1,"explanation":"Good questioning moves from observation to comparison to explanation to prediction. The others are disordered, closed or recall-based.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1534","question":"A Class 4 child with dyslexia understands EVS ideas well in discussion but scores poorly on written EVS tests. The most appropriate step is to:","options":["give the child extra written tests for practice, since regular writing practice will improve the scores","record in the report card that the child is weak in EVS, so that parents can arrange extra tuition","excuse the child from all EVS assessment, so that the child is not stressed by tasks that are too hard to do","assess the child also through oral answers, drawings and practical tasks, so that EVS learning is measured"],"answer":3,"explanation":"The written test measures reading and writing more than EVS for this child. Varied modes of assessment let the learning show; excusing the child from assessment is not inclusion.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1535","question":"Assertion (A): Children’s alternative conceptions in EVS are best removed by giving them the correct definition early. Reason (R): Children can memorise a definition without changing the way they actually think about the idea. Choose the correct option.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"R is true, and it is exactly why A is false: a memorised definition can sit alongside an unchanged alternative idea. Conceptual change needs experience and reasoning.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1536","question":"Class 3 children, most of whom cannot yet write fluently, are to record the number of birds they see in the school garden each day for a week. The most suitable way is:","options":["writing a paragraph each day about the birds","copying the teacher’s record from the board","making a picture table with tally marks for each kind of bird","remembering the numbers and telling them at the end of the week"],"answer":2,"explanation":"Picture tables with tally marks let young children record accurately without fluent writing, and the data can later be compared. Memory and copying are unreliable or passive.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1537","question":"The NCERT EVS books often ask, ‘Look at the picture. What is happening here?’ The main purpose of such picture-based questions is to:","options":["build observation and interpretation, and let children who cannot yet read well take part","fill space in the book attractively, so that young children do not lose interest in the printed text","test children's drawing skills, since they are expected to copy each picture into their notebooks","replace reading in EVS, since pictures are easier for children to understand than written sentences"],"answer":0,"explanation":"Picture reading is itself a sub-skill of observation and recording, and it gives every child a way in regardless of reading level. It does not replace reading.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1538","question":"Which statement best describes the relationship between primary EVS and the separate science and social science subjects taught from Class VI?","options":["EVS covers parts of the Class VI science syllabus early, so that the later classes become easier for children","EVS is unrelated to the later subjects and serves mainly to keep young children engaged and interested in school","EVS lays a foundation of curiosity, process skills and nature-society links, on which the later subjects build","EVS is simply a shortened, simplified version of the Class VI textbooks, with more pictures and fewer words"],"answer":2,"explanation":"EVS is not a compressed version of later subjects; it lays foundations of inquiry and integrated understanding, which the disciplines later develop separately.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1539","question":"Once Class 5 children accept that clouds are made of tiny drops of water, the teacher asks them to use the same idea to explain morning fog and the mist on a bathroom mirror. In the conceptual-change model, this step mainly shows children that the new idea is:","options":["intelligible","a cause of dissatisfaction","plausible","fruitful"],"answer":3,"explanation":"An idea is fruitful when it helps explain new situations. Intelligibility concerns understanding it, plausibility concerns believing it, and dissatisfaction concerns the old idea.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1540","question":"Class 5 children lead Class 3 children on a nature walk around the school, pointing out plants and insects. Which statement about this arrangement is most accurate?","options":["Only the Class 3 children learn; the Class 5 children lose time that should go to their own syllabus","Both groups learn: younger ones get guidance, and older ones deepen understanding by explaining","It works only if the teacher stays silent throughout, so that the older children feel fully in charge","It removes the need for the teacher to plan the walk, since the older children already know the area"],"answer":1,"explanation":"Peer tutoring benefits both sides; explaining makes older children organise and check their own knowledge. The teacher still plans and supports.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1541","question":"A textbook picture of ‘an Indian village’ shows only mud huts, a well and a bullock cart. Children in a city school conclude that all villages look like this. The teacher’s best response is to:","options":["agree with them, since the textbook picture has been chosen by experts to show a typical village","tell them that villages no longer look like that, since all of them now have pucca houses and roads","show photographs of many kinds of villages and discuss how villages differ and change","ask them to copy the picture carefully into their notebooks and label each part of the village"],"answer":2,"explanation":"A single picture can become a stereotype. Showing variety and change corrects the generalisation and teaches children to read pictures critically.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1542","question":"For a survey on plastic use, a Class 5 group writes the question, ‘Don’t you think plastic bags are harmful?’ The main problem with this question, and the best fix, is:","options":["it is too long for a survey; shorten it to ‘Plastic bags: harmful?’ so that people answer quickly","it should be asked only to shopkeepers, since they handle far more plastic bags than ordinary families","it is informal; it should be rewritten in English, since survey questions must use formal language","it is a leading question; ask instead, ‘What bag do you usually use for shopping, and why?’"],"answer":3,"explanation":"A leading question pushes people towards one answer and biases the data. A neutral, open question gathers real information about practices and reasons.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1543","question":"Which of these is an example of first-hand (experiential) rather than second-hand learning in EVS?","options":["Watching a close-up video that shows step by step how rice is cooked","Tasting and feeling raw and cooked rice and describing the differences","Reading a story about a rice farmer and his family during the harvest","Listening to the teacher describe a paddy field she visited as a child"],"answer":1,"explanation":"Tasting and handling the rice is direct sensory experience. Video, stories and descriptions are useful but second-hand.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1544","question":"At the end of each EVS lesson, a Class 4 teacher asks children to write or draw on a slip ‘one thing I learnt today’ and ‘one thing I am still wondering about’. This practice mainly serves to:","options":["give the teacher quick feedback on learning and help children reflect","collect marks for each child that can be added up for the term-end report card","keep children quietly busy in the last five minutes before the bell rings","check children’s handwriting and spelling regularly in a low-stress way"],"answer":0,"explanation":"Exit slips are a formative tool: the teacher sees what was understood and what puzzles remain, and children reflect on their own learning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1545","question":"A Class 4 child says, ‘All snakes are poisonous, so my father kills every snake he sees.’ The teacher’s best response is to:","options":["agree with the child, since snakes are dangerous and a family has to protect itself from every one of them","say firmly that killing snakes is a crime under wildlife law and that the father should be reported for it","explain that most snakes are not venomous and help farmers by eating rats, while teaching how to stay safe","avoid the topic, since it concerns the child’s family and the teacher should not question parents’ practices"],"answer":2,"explanation":"The response corrects the over-generalisation, shows the snake’s role in the ecosystem and keeps safety in view, without blaming the family.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1546","question":"Which of these statements about teaching–learning materials in EVS are correct? I. Good material lets children handle and explore it. II. Teacher-made material from local resources can be as effective as bought material. III. Once made, a piece of material can be used for every topic. IV. Material must be checked for accuracy and bias before use.","options":["I and II only","I, II and III only","II, III and IV only","I, II and IV only"],"answer":3,"explanation":"Material is chosen for a purpose and topic, so III is wrong. Hands-on use, the value of local material and checking for accuracy and bias are all sound principles.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1547","question":"A Class 5 group submits a beautiful model of a water-harvesting system, and the teacher learns that a parent made most of it. For assessing the project, the best approach is to:","options":["give full marks, since the model is excellent and the children did choose the topic and plan the model themselves","assess the process, such as the children’s records, explanations and participation, and do more work in school","give zero marks to the group and stop project work, since it always ends up being done by the parents","ask the parent to explain the model to the class, since the parent clearly understands the system best"],"answer":1,"explanation":"Assessing the product alone rewards outside help; looking at the process shows what the children learnt. Doing more of the work in school reduces the problem; dropping projects loses their value.","difficulty":"very-hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1548","question":"Two Class 5 children submit concept maps on ‘Water’. Riya’s map has many words joined by plain lines with no labels. Sameer’s map has fewer words, but every line carries a linking phrase such as ‘is stored in’ or ‘is used for’. Which conclusion is most justified?","options":["Sameer’s map shows more understanding, because his labelled links state how the ideas are related","Riya’s map shows better understanding, because it covers many more concepts linked to the topic of water","Both maps show the same level of understanding, since both children have connected all their words with lines","Neither map can show understanding, since concept maps really measure only how much a child has memorised"],"answer":0,"explanation":"In a concept map, meaning lies in the propositions made by labelled links. Many unlinked words show recall; fewer words with explicit relationships show understanding.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1549","question":"Which of the following pairs are correctly matched? 1. Cognitive validity: language and concepts suited to the learner's age. 2. Content validity: showing how scientific ideas changed over time. 3. Process validity: learning how scientific knowledge is generated and validated. 4. Ethical validity: honesty, objectivity and concern for life.","options":["1, 3 and 4 only","1 and 2 only","2, 3 and 4 only","1, 2, 3 and 4"],"answer":0,"explanation":"Showing how ideas changed over time is historical validity; content validity is about conveying significant and correct science. The other three pairs are correctly matched.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1550","question":"Assertion (A): Creating cognitive conflict alone is often not enough to bring about conceptual change in science. Reason (R): Learners also need a new idea that they find intelligible and plausible to replace the old one.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Conflict may make a learner dissatisfied, but without an understandable and believable alternative she may explain away the evidence or hold both ideas; that is why conflict alone is not enough.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1551","question":"Several Class 6 students say that a switch 'makes the electricity' that lights the bulb. Which activity best addresses this idea?","options":["Showing a picture of a power station and explaining how electricity reaches the classroom switch","Building a circuit with a paper-clip switch and seeing the bulb light only when the clip closes the gap","Telling students clearly that cells make the electricity, not switches, and asking them to write it down","Counting the switches in the classroom and noting which light or fan each one turns on and off"],"answer":1,"explanation":"Making their own switch shows that it only opens or closes the path; the cell drives the current. Telling them is weaker than letting them see the switch's real role.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1552","question":"A student says the sun goes round the earth, 'because I can see it rise and set every day'. Which activity best helps her consider another explanation?","options":["Drawing the sun's path across the sky at different times of the day in a notebook","Memorising the statement that the earth goes round the sun, as given in the textbook","Turning slowly on a chair beside a lamp and seeing the lamp seem to 'rise' and 'set'","Watching the sun carefully at noon to see that it is directly overhead and not moving"],"answer":2,"explanation":"Spinning on a chair shows that the same apparent motion can be produced by the observer turning, which makes the earth's rotation a plausible alternative to the sun's movement.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1553","question":"Students say there is no gravity in space, because astronauts float in their spacecraft. Which question best challenges this idea?","options":["'Have you seen a video of astronauts floating freely inside the space station?'","'What is the unit of force, and how do we measure the weight of an astronaut?'","'Is it difficult to walk on the moon, and why do astronauts there wear heavy boots?'","'If there were no gravity in space, what would keep the moon going round the earth?'"],"answer":3,"explanation":"The moon's orbit shows that the earth's gravity reaches far into space; astronauts float because they and their craft are falling round the earth together, not because gravity is absent.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1554","question":"Students believe that friction acts only between solid surfaces. Which activity best widens their idea?","options":["Dropping a flat sheet and a crumpled sheet of paper together and comparing their fall","Rubbing their palms together hard and noticing how warm they become after some time","Sliding a book across the floor and then across a rough mat to compare how far it goes","Rolling a pencil on the table and comparing it with sliding the same pencil along it"],"answer":0,"explanation":"The flat sheet falls more slowly because air opposes its motion more; this shows that air (and water) exert frictional force, not just solid surfaces.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1555","question":"Students believe that every part of a plant makes food. Which activity gives the most direct evidence against this idea?","options":["Testing a root and a stem of the plant for starch, since starch shows where food is present","Testing the green and non-green parts of a variegated croton leaf for starch after sunlight","Measuring the length and area of different leaves to see which parts of the plant are largest","Keeping a whole plant in the dark for a week and then observing whether its leaves turn yellow"],"answer":1,"explanation":"Only the green parts of a variegated leaf turn blue-black with iodine, linking food-making to chlorophyll. Starch in roots or stems could have been stored there, so testing them does not settle the question.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1556","question":"A Class 6 student argues that a butterfly is not an animal 'because animals have four legs and fur'. The teacher's best response is to:","options":["Tell the student that butterflies are insects, not animals, so the answer is actually correct","Accept the answer, since it is partly correct and correcting it now may discourage the student from speaking up","Ask the student to list all the animals shown in the textbook and learn them as the correct examples","List with the class features all animals share, like feeding on others, and test butterflies, fish and birds"],"answer":3,"explanation":"The student is using a narrow everyday meaning of 'animal' (mammals). Working out the scientific defining features shows that insects, fish and birds are animals too.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1557","question":"In a Class 8 lesson on industrial chemicals, a teacher discusses the 1984 Bhopal gas leak. The most appropriate educational purpose of this discussion is to:","options":["Warn students about the dangers of chemistry, so that they think carefully before choosing it as a career","Show that chemical industries do more harm than good and that all of them should be closed down","Help students see that technology brings responsibility and a need for safety and accountability","Make students memorise the date, the place and the gas involved, since these are often asked in exams"],"answer":2,"explanation":"Using such a case in science teaching helps learners understand the human and environmental costs of unsafe technology and the ethical responsibilities involved, without blanket fear or mere recall.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1558","question":"After meeting a local mechanic who built a low-cost water pump, a Class 8 class decides to design its own device. Arrange the stages of the design process in order: P. Build a prototype  Q. Identify the problem and the needs of users  R. Test the prototype and improve it  S. Generate and choose among ideas","options":["S, Q, P, R","Q, P, S, R","Q, S, P, R","Q, S, R, P"],"answer":2,"explanation":"Design begins by identifying the problem and users' needs, then generating ideas, building a prototype, and testing and improving it, often in repeated cycles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1559","question":"A teacher brings a newspaper report of a dengue outbreak in the district to a Class 8 class. Which use of the report best develops scientific thinking?","options":["Asking students to check the report's claims against what they know of mosquitoes, then survey sites nearby","Asking students to copy the report neatly into their notebooks and underline the important health facts","Reading the report aloud to the class as a piece of current news, and then moving straight on to the next chapter","Telling students to avoid going out in the evening and to keep well away from the places where mosquitoes gather"],"answer":0,"explanation":"Critically evaluating a real report and acting on it with a local survey connects science to life and builds the habit of checking claims against evidence.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1560","question":"Even after an ammeter activity showed equal current on both sides of a bulb, several students still say the bulb 'uses up' current. What is the most suitable next step?","options":["Repeating the same ammeter activity exactly as before, since seeing it again will eventually convince them","Marking the students' answers wrong in every test until they learn to write the correct statement about current","Moving on to the next chapter, since the activity has already been done and the evidence it gave was very clear","Using another model, such as a loop of moving beads, and discussing that the bulb uses up energy, not current"],"answer":3,"explanation":"Persistent misconceptions need multiple representations and a clear account of what does change (energy) to make the new idea intelligible and plausible; repeating the same activity rarely shifts them.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1561","question":"Which entry is the most useful anecdotal record of a student's behaviour during a science activity?","options":["'Ravi is lazy and never works properly in his group; he always lets the others do the work and then copies their results.'","'Ravi is a poor science student who does not seem interested in practical work and will probably struggle in the higher classes.'","'12 March, magnets: Ravi tested five objects alone, noted results, asked why a steel scale was attracted but a spoon was not.'","'Ravi did well today in the magnet activity and seemed much more interested than usual. Good progress this term overall.'"],"answer":2,"explanation":"A good anecdotal record gives a dated, objective description of what the student did and said, kept separate from judgments. Labels such as 'lazy' or 'poor' are interpretations, not records.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1562","question":"A teacher gives the same chapter test to two sections. In Section A she only records the marks; in Section B she studies the errors, regroups students by the kind of mistake and reteaches. What makes the Section B use formative?","options":["The difficulty level of the questions set in the chapter test","How the results are used to improve teaching and learning","The number and type of questions included in the chapter test","The point in the term at which the chapter test was given"],"answer":1,"explanation":"Whether an assessment is formative depends on its use: results used to adjust teaching and support learners make it formative, even when the test itself is identical.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1563","question":"In a school, science theory is taught in the first term and all practicals are done together in the last month before the examination. The main drawback of this arrangement is that:","options":["Practicals are cut off from the concepts they should help build, so they become rituals","Students spend too much time in the laboratory in one month, which leaves little time for revision","Teachers get very tired in the last month, so the quality of supervision in practicals goes down","There is not enough apparatus for all students to do every practical at the same time of year"],"answer":0,"explanation":"Practical work is most useful when it is woven into teaching, so concepts are formed through activity. Separating them turns practicals into a routine for marks.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1564","question":"A Class 6 textbook diagram shows the planets close together around the sun. Students take it as a true picture. Which activity best corrects this impression?","options":["Colouring the planets in the diagram carefully, so that students can tell each planet apart easily","Asking students to memorise the order of the planets from the sun with the help of a short rhyme","Making a scale model in the school ground with a ball for the sun and marked planet distances","Showing a bigger, more detailed diagram of the same kind, with labels for each planet and its moons"],"answer":2,"explanation":"Most textbook diagrams are not to scale; a scale model reveals the vast distances between planets, showing the model's limits and building a truer picture.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1565","question":"In a class investigation on how fast different materials let water through, each group's results vary a little. The teacher pools the data from all groups on the board before conclusions are drawn. This mainly teaches students that:","options":["The results of individual groups are worthless, since only a class average can be trusted in science","Science is a shared activity in which combining and comparing results gives more reliable findings","The group whose results are closest to the textbook value is right and the others made mistakes","Data from different groups should always be identical if each group has done the experiment properly"],"answer":1,"explanation":"Pooling data shows variation is normal and that collaboration and replication strengthen conclusions, which reflects science as a collaborative enterprise.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1566","question":"While learning about plants, Class 6 students describe roots as 'the plant's legs that hold it'. The teacher's best approach to scientific vocabulary is to:","options":["Ban everyday language and insist on the correct technical terms from the first day, so that wrong ideas do not form","Never introduce technical terms at this stage, since students' own words are enough for understanding plants","Ignore the description and move on, since comparing roots to legs is a childish way of talking about plants","Accept everyday descriptions first, then introduce terms such as 'anchorage' and 'absorption' for ideas they hold"],"answer":3,"explanation":"Technical terms are best learnt as labels for ideas students already understand in their own words; terms imposed first become empty words.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1567","question":"Several students submit science fair projects copied from the internet. The teacher's best guidance for future projects is to:","options":["Help students begin from questions about their own surroundings and design their own investigations","Ban the use of the internet for projects, since students cannot be trusted to use it without copying","Award marks mainly for the neatness of the charts, since that part at least has to be done by the students","Assign the same project to everyone, so that copying is easy to spot and the marking is fair to all"],"answer":0,"explanation":"Projects rooted in students' own questions and surroundings encourage originality and real inquiry, and the internet can then be used as a source rather than a copy.","difficulty":"moderate","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1568","question":"In a debate on banning single-use plastic bags, which student response shows the best scientific argument?","options":["'Plastic is very bad for the environment. Everyone knows that, and so do all the experts we see on television.'","'My uncle runs a shop and says plastic bags are fine and cheap, so they should certainly not be banned.'","'Plastic bags should be banned, because they look ugly lying everywhere and make our town look dirty.'","'Ban them: our survey found bags blocking three drains near school, and they do not decay, so it will worsen.'"],"answer":3,"explanation":"A strong scientific argument links a claim to evidence (the survey) through reasoning (they do not decompose). The others rest on common belief, authority or appearance.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1569","question":"A teacher could either show a video of a candle burning under a glass or do it live in class. Which is the strongest reason to prefer the live demonstration?","options":["It is quicker than finding and playing a video, so more of the period is left for writing notes","Students see the real event, ask 'what if', and the teacher can change conditions on the spot","It needs no preparation, since a candle and a glass are easily available in every school","Videos are never useful in science, since students only learn from things they see in person"],"answer":1,"explanation":"A live demonstration is authentic and interactive: the teacher can respond to students' questions by changing conditions, such as using a bigger glass. Videos have uses but cannot respond in this way.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1570","question":"Students believe that maggots arise on their own from rotting food. Which investigation best tests this idea?","options":["Keeping food in two jars, one covered with fine cloth and one left open, and seeing which gets maggots","Looking closely at maggots under a hand lens to see which part of the rotting food they are coming from","Reading about the life cycle of the housefly in the textbook and drawing each stage carefully","Keeping the food in a refrigerator and checking whether maggots still appear after a few days"],"answer":0,"explanation":"If maggots came from food alone, both jars would develop them. Maggots only in the open jar show they come from eggs laid by flies, a version of Redi's classic test.","difficulty":"hard","source":"CTET Paper 2 · KVS · state TETs"},
  {"id":"cdp-pedagogy-subjects-1571","question":"Which activity best reflects NCF 2005's suggestion that upper primary students should design simple technological units and modules?","options":["Reading about how large dams generate electricity and listing the parts of a hydroelectric plant","Copying a labelled diagram of a rain gauge from the textbook and learning how it is used","Building a rain gauge from a plastic bottle and using it to record rainfall through the monsoon","Watching a video on weather instruments and noting down how each one is used by scientists"],"answer":2,"explanation":"Designing and using a working device of their own engages students' hands and minds and links technology to everyday life. Reading, copying and watching are passive.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1572","question":"Arrange the steps of a scientific investigation in a logical order: P. Interpret the data and draw a conclusion  Q. Frame a testable question and hypothesis  R. Plan a fair test  S. Collect and record data  T. Communicate the findings","options":["R, Q, S, P, T","Q, R, S, T, P","Q, S, R, P, T","Q, R, S, P, T"],"answer":3,"explanation":"An investigation moves from a testable question and hypothesis to planning a fair test, collecting data, interpreting it and communicating the findings, though real science often loops back.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1573","question":"A teacher asks a student to 'think aloud' while she predicts which of several circuits will light a bulb. The main value of this technique is that it:","options":["Reveals the reasoning behind her answers, not just whether they are right","Makes the test faster, since the teacher can hear answers instead of reading them","Lets the teacher correct her immediately and give her the right answer at each step","Replaces practical work, since predicting circuits is as good as building them"],"answer":0,"explanation":"Think-aloud protocols expose a learner's mental model, such as the 'one wire' or 'clashing current' idea, which a right or wrong answer alone would hide.","difficulty":"very-hard","source":"CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1574","question":"A Class 7 teacher with limited apparatus sets up four tables, each with a different activity on heat (conduction, convection, radiation, insulation), and groups move from table to table every ten minutes. This arrangement mainly helps because:","options":["Students can skip the tables they find hard and spend more time on the activities they like","Every student gets hands-on work at every table with only one set of materials each","The teacher does not need to supervise, since each table has its own written instructions","It removes the need for a discussion afterwards, since each group has done all four activities"],"answer":1,"explanation":"Station rotation makes the most of limited apparatus while giving everyone hands-on time; a closing discussion is still needed to connect the four activities.","difficulty":"hard","source":"CTET Paper 2 · state TETs · NVS"},
  {"id":"cdp-pedagogy-subjects-1575","question":"In a Class 6 English lesson in Mumbai, students discuss a story in groups using Hindi, Marathi and English freely, then each group writes its summary in English. The teacher’s deliberate use of all the learners’ languages to make meaning is best described as:","options":["Submersion","Subtractive bilingualism","Translanguaging","Grammar-translation"],"answer":2,"explanation":"Translanguaging treats a learner’s languages as one connected repertoire and uses all of it to understand and produce content. Grammar-translation translates texts to learn rules, which is not happening here.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1576","question":"A school in a Santali-speaking area forbids Santali on the premises, and over a few years children stop using it even at home while their school language stays weak. This outcome is called:","options":["Additive bilingualism, since a new language has been added","Subtractive bilingualism, as the new language replaces the first","Balanced bilingualism, since the two languages are now equal","Code-mixing, since words from both languages are combined"],"answer":1,"explanation":"When a second language is learnt at the cost of the first, bilingualism is subtractive, often with harm to identity and learning. Additive bilingualism adds a language while the first keeps developing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1577","question":"During an English activity, a Class 2 child says, ‘Ma’am, mujhe ek eraser chahiye.’ The most suitable teacher response is to:","options":["Tell the child to ask again only in English, or not at all","Ignore the request until the child asks in correct English","Note it down as a language mistake to discuss with the parents","Give it, saying, ‘Oh, you need an eraser? Here you are.’"],"answer":3,"explanation":"Mixing languages is a normal strategy of bilingual children. Responding to the meaning while modelling the English form keeps communication going and gives useful input without shame.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1578","question":"A Class 4 teacher in Delhi has children whose home languages include Bhojpuri, Bengali, Nepali and Urdu, none of which she speaks. Which is the most practical way to use these languages as a resource?","options":["Avoid them, since she cannot check whether they are being used correctly","Allow them only during breaks and never during lesson time in the classroom","Invite children to share words and stories from home and use peer help","Teach entirely in English, so that no one language group is favoured over others"],"answer":2,"explanation":"A teacher need not know every language; children, peers and families are the experts. Inviting their languages into tasks builds inclusion and helps link new English words to known concepts.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1579","question":"A teacher writes ‘Raju aam khata hai’ and ‘Raju eats a mango’ on the board and asks Class 5 children where the verb comes in each. The main purpose of this comparison is to:","options":["Show that Hindi grammar is less correct than English grammar","Practise translating Hindi sentences into English word by word","Test whether children know the Hindi word for ‘mango’","Build awareness of how the two languages differ"],"answer":3,"explanation":"Comparing subject–object–verb order in Hindi with subject–verb–object order in English builds metalinguistic awareness and helps children understand errors like ‘Raju mango eats’.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1580","question":"Assertion (A): NCF 2005 recommends drawing on children’s home languages in class even when the medium of instruction is English. Reason (R): Children learn best when new knowledge is connected to what they already know, including their own language.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"NCF 2005 treats multilingualism as a resource precisely because learning builds on prior knowledge and the language in which children think and experience the world.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1581","question":"A school near Mangaluru fines children five rupees each time they are heard speaking Tulu in school. From the point of view of NCF 2005, this practice is:","options":["Justified, as it gives children maximum exposure to English","Harmful, as it devalues identity and wastes a resource","Acceptable, as long as the fine money is used to buy books","Useful, as it improves discipline in the school"],"answer":1,"explanation":"Punishing a home language signals that the child’s culture is inferior and raises anxiety; NCF 2005 asks schools to respect and use children’s languages.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1582","question":"A Class 2 library in Jharkhand has picture books with the same story printed in Santali and English on facing pages. The main benefit for Santali-speaking children is that:","options":["They can skip the English text and read only in Santali","The books save the school money by printing two books in one","They can understand the story in Santali and link it to English","They avoid any need for the teacher to read aloud"],"answer":2,"explanation":"Bilingual texts let children build meaning through the stronger language and then connect it to English words and structures, supporting both literacy and identity.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1583","question":"Some parents demand that only English be used from Class 1 because the home language ‘spoils’ English. Which response by the teacher is most consistent with research and policy?","options":["Agree, since early exclusive English always produces the best results","Tell the parents that language choices are not their concern","Say that English should not be taught at all until Class 6","Explain that a strong home language supports learning English"],"answer":3,"explanation":"Research on cross-linguistic transfer and NEP 2020’s emphasis on the home language in the early years both show that strong first-language skills support learning a second.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1584","question":"Knowing that Hindi has no direct equivalent of the English articles ‘a’ and ‘the’, a teacher plans extra work on articles for her Hindi-speaking Class 6 students before errors appear. She is using insights from:","options":["The natural order hypothesis of Krashen","Contrastive analysis of the two languages","Total Physical Response of James Asher","The language experience approach to reading"],"answer":1,"explanation":"Contrastive analysis compares the structures of two languages to predict where learners may struggle; differences such as missing articles are likely trouble spots.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1585","question":"Class 5 children survey which languages are spoken in their homes and neighbourhood and make a ‘language map’ of the class. The main purpose of this activity is to:","options":["Build respect for the class’s linguistic diversity","Find out which children should be moved to another section","Prove that English is the most important language in the class","Test children’s spelling of the names of languages"],"answer":0,"explanation":"Language mapping makes diversity visible, values every child’s languages and gives the teacher information she can use for planning multilingual activities.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1586","question":"A Class 2 teacher in a village school without a projector wants to teach ‘sieve’, ‘grater’, ‘ladle’ and ‘rolling pin’. Which teaching–learning material is most effective?","options":["A printed chart of the words with their dictionary definitions","A video on a website that the class cannot access","A list of the words to be copied ten times in notebooks","The real objects, which children can see, handle and use"],"answer":3,"explanation":"Realia make meanings concrete and memorable for young learners, especially for familiar household items, and need no technology.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1587","question":"A Class 7 teacher uses the textbook but also brings local folk tales, newspaper cuttings, recipes and songs into her English lessons. Which statement best supports this?","options":["The textbook is useless and should be set aside","Only materials written by native speakers should be used","The textbook is one resource among many; varied texts enrich input","Extra materials should be used only after the syllabus is finished"],"answer":2,"explanation":"NCF 2005 cautions against treating the textbook as the only source of knowledge; diverse, relevant texts widen exposure and engagement.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1588","question":"A shy Class 1 child who never speaks in class begins to talk in English when the teacher gives her a sock puppet and asks, ‘What does Bunny want to say?’ The puppet most likely helps because:","options":["Puppets teach grammar better than teachers do","Speaking as a character lowers her anxiety about mistakes","Puppets make the class noisy, which hides the child’s voice","The child is copying words the puppet maker wrote"],"answer":1,"explanation":"Puppets give a safe persona that lowers the affective filter; the child takes risks with language that she would not take as herself.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1589","question":"Class 8 students record themselves giving a one-minute talk on a phone, listen back with a checklist and record a second, improved version. The main value of this use of technology is that it:","options":["Is useful only for testing pronunciation of single words","Replaces the teacher’s role in assessing speaking altogether","Lets students hear and assess their own speaking","Mainly trains students to use mobile phones well"],"answer":2,"explanation":"Recordings make spoken language visible for reflection, supporting self-assessment and rehearsal, which are hard to achieve with live speech alone.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1590","question":"A teacher cuts a sentence into word cards (‘every’, ‘morning’, ‘my’, ‘grandmother’, ‘walks’) and asks Class 3 groups to arrange them into a sentence. This low-cost material mainly develops:","options":["Handwriting through copying the cards","Awareness of English word order","Pronunciation of difficult sounds","Speed of silent reading of long texts"],"answer":1,"explanation":"Rebuilding jumbled sentences makes children think about how words combine into grammatical order, in a hands-on and collaborative way.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1591","question":"Which feature makes a picture book most suitable for emergent readers in Class 1?","options":["Predictable, repetitive text with rhythm, and pictures that support it","Long sentences that introduce many new words on each page to build vocabulary","Small print with few pictures, so that children focus fully on the printed words","A complex plot with many characters and flashbacks to hold children's interest"],"answer":0,"explanation":"Predictable books (‘Brown bear, brown bear, what do you see?’) let children anticipate words through repetition, rhythm and pictures, so they experience success early.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1592","question":"After reading a folk tale, Class 5 children complete a chart with boxes for ‘Setting’, ‘Characters’, ‘Problem’, ‘Main events’ and ‘Solution’. This organiser is called a:","options":["Venn diagram","Timeline of dates","KWL chart","Story map"],"answer":3,"explanation":"A story map shows the elements of a narrative and how they fit together, supporting comprehension, retelling and later story writing.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1593","question":"A Class 3 teacher shows a colourful animation for every new word, and children watch passively while she clicks through slides. Which principle of using teaching–learning materials is being ignored?","options":["Materials should always be expensive and digital","Materials should engage children actively, not just decorate","Materials should be used only by the teacher, never by children","Materials should never include pictures"],"answer":1,"explanation":"Teaching aids are tools for learning; if children only watch, the material does not lead them to use language. A simple aid used actively often works better.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1594","question":"Match the dictionary type with the learner and purpose it suits best: 1. Picture dictionary 2. Learner’s dictionary with example sentences 3. Thesaurus 4. Bilingual dictionary; a. A Class 8 student checking how a word is used in a sentence b. A Class 1 child linking words to images c. A Class 9 writer looking for a more precise word d. A beginner checking the meaning of an English word in her home language","options":["1-b, 2-a, 3-c, 4-d","1-b, 2-c, 3-a, 4-d","1-d, 2-a, 3-c, 4-b","1-b, 2-a, 3-d, 4-c"],"answer":0,"explanation":"Picture dictionaries suit young children, learner’s dictionaries show usage, a thesaurus offers words of related meaning, and a bilingual dictionary links the two languages for beginners.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1595","question":"A teacher gives Class 6 students a comic strip with empty speech bubbles and asks them to write what the characters might be saying. This activity mainly develops:","options":["Writing natural dialogue that suits a situation","Copying model sentences from the textbook","Pronunciation of difficult words","Knowledge of the rules for changing to reported speech"],"answer":0,"explanation":"Pictures supply the situation and the bubbles require short, appropriate spoken-style language, combining creativity with awareness of how people talk in context.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1596","question":"Assertion (A): Placing minority-language children in an English-only classroom with no support often leads to poor learning. Reason (R): Without comprehensible input and support in the first language, children cannot easily connect the new language to meaning.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Such ‘submersion’ gives input that children cannot understand, so little is acquired and content learning also suffers; support in the home language makes input meaningful.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1597","question":"Consider these statements: I. Code-switching by bilingual speakers usually follows patterns and is not random. II. Using the home language in class always slows down the learning of English. III. Bilingual children often show greater awareness of how language works. Which are correct?","options":["II and III only","I and II only","I and III only","I, II and III"],"answer":2,"explanation":"Code-switching is rule-governed and purposeful, and bilingualism is linked to stronger metalinguistic awareness. Well-planned use of the home language supports, rather than slows, English learning.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1598","question":"A teacher puts objects in a cloth ‘feely bag’; a Class 2 child touches one without looking and describes it (‘It is soft… it is round… it is small’) while others guess. This activity mainly develops:","options":["Knowledge of the parts of speech","The spelling of the names of the objects","Silent reading of descriptive passages","Descriptive words linked to the senses"],"answer":3,"explanation":"The guessing game creates a real reason to describe, and touching gives concrete meaning to adjectives such as soft, rough and smooth.","difficulty":"moderate","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1599","question":"In a Class 10 letter, a student writes, ‘Kindly do the needful and prepone the meeting.’ Which response best reflects a sound understanding of English as used in India?","options":["Mark both expressions as errors that must be removed from Indian students’ English","Explain that these are Indian English usages that some readers abroad may not know","Treat them as fossilised errors that need daily drilling of the British forms","Call them slang that is never acceptable in any kind of formal writing"],"answer":1,"explanation":"‘Prepone’ and ‘do the needful’ are established in Indian English. A sound approach builds awareness of audience, so students can choose forms that readers in different contexts will understand.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1600","question":"A Class 3 child writes 7 × 0 = 7. Which question best helps her see the error?","options":["‘There are 7 plates with 0 laddoos on each. How many laddoos in all?’","‘What is 7 + 0? Now use that same idea to work out 7 × 0 for me.’","‘Can you say the table of 7 again, slowly, starting from 7 × 1 up to 7 × 10?’","‘What is 0 × 0? And what do you get when you multiply 0 by 1?’"],"answer":0,"explanation":"She is applying the rule for adding 0 to multiplication. A story about 7 groups of nothing shows the total is 0; asking about 7 + 0 would only strengthen the confusion.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1601","question":"A Class 4 child multiplies 305 × 4 and writes 1200. Her working shows: 5 × 4 = 20, write 0, carry 2; then she writes 0 in the tens place; then 3 × 4 = 12. What is the most likely misconception?","options":["She does not know the fact 5 × 4 well, and so gets the very first partial product wrong","She thinks 0 makes everything 0, so she drops the carried 2 when the tens digit is 0","She has carried the 2 into the hundreds place instead of into the tens place","She multiplied 30 by 4 instead of 305 by 4, leaving out the ones digit"],"answer":1,"explanation":"In the tens place, 0 × 4 = 0 and the carried 2 must still be added, giving 2; the answer is 1220. Treating ‘0 makes everything 0’ as a rule wipes out the carry.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1602","question":"A Class 3 child writes 400 − 6 = 400, explaining ‘0 take away 6 is nothing’. What is the best response?","options":["Tell her to subtract the smaller digit from the bigger one in each column, so 6 − 0 = 6","Ask her to memorise the rule for subtracting from zero and practise it on ten sums","Ask her to show 400 with bundles and take 6 sticks away, opening a bundle when needed","Give her more subtraction sums without zeros first, and return to zeros much later"],"answer":2,"explanation":"She has a rule that 0 − n = 0. With bundles she must open a hundred into tens and a ten into ones to take 6 away, leaving 394; this shows why regrouping across zeros is needed.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1603","question":"A Class 4 child says 12 ÷ 4 and 4 ÷ 12 are the same ‘because the numbers are the same, just like 12 × 4 and 4 × 12’. Which response is best?","options":["Agree with her, since division is the opposite of multiplication and follows the same rules","Tell her that division is never possible when the first number is smaller than the second","Ask her to learn by heart that division is not commutative and write it in her notebook","Ask her to compare sharing 12 rotis among 4 children with sharing 4 rotis among 12"],"answer":3,"explanation":"Sharing 12 among 4 gives 3 each, while 4 among 12 gives 1/3 each. The two situations make it clear that order matters in division, unlike multiplication.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1604","question":"Class 4 children use every number given in a word problem, even when some are not needed. What is the most useful teaching response?","options":["Give problems with extra information; children cross out what is not needed and say why","Give only problems with exactly the numbers needed, so that children are not confused","Teach key words for each operation, such as 'altogether' for addition and 'left' for subtraction","Tell children to use only the first two numbers in a problem and ignore any others"],"answer":0,"explanation":"Deciding what information is relevant is part of understanding a problem. Problems with extra data build this skill; problems with only the needed numbers let children succeed without reading carefully.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1605","question":"In a discussion on ‘Is 1 a prime number?’, which student argument is mathematically strongest?","options":["‘No, because my teacher told us so last year, and it is also written in the book.’","‘No, because a prime has exactly two different factors, and 1 has only one.’","‘Yes, because 1 cannot be divided exactly by any other number except itself.’","‘No, because 1 is too small to be prime; primes begin only from the number 2.’"],"answer":1,"explanation":"The strongest argument uses the definition. A prime has exactly two distinct factors, 1 and itself; 1 has only one factor. Answers from authority or size are not mathematical reasons.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1606","question":"Asked to write a number sentence for ‘5 less than 12’, a Class 3 child writes 5 − 12. What is the best explanation?","options":["She does not know how to subtract and has not learnt to take away numbers","She does not understand the meaning of the word ‘less’ in a maths question","She writes the numbers in the order she hears them, though it means 12 − 5","She thinks subtraction can be done in any order, just like addition can"],"answer":2,"explanation":"‘5 less than 12’ starts from 12 and takes away 5. Translating word by word reverses the order, a common language difficulty in maths that acting out or drawing can correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1607","question":"A parent often tells her child, ‘Don't worry, I was also bad at maths.’ How should a teacher see this, and respond?","options":["As helpful, since it removes pressure from the child and makes failure in maths feel normal","As unimportant, since what parents say at home has little effect on learning in school","As a reason to give the child easier work, since the child may have inherited a weakness","As a message that maths ability is fixed; she should share that ability grows with effort"],"answer":3,"explanation":"Well-meant comfort can lower expectations and suggest that maths is a fixed gift. Working with parents to spread a growth view of ability supports the child's effort and confidence.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1608","question":"A Class 6 student sorts quadrilaterals correctly by properties such as ‘has parallel sides’ and ‘has right angles’ but says a square cannot be a rhombus. At which Van Hiele level is she reasoning?","options":["Analysis: she uses properties but does not yet relate one class of shapes to another","Visualisation: she judges shapes only by how they look as a whole, not by properties","Informal deduction: she sees how the properties of different shapes are logically linked","Deduction: she can build formal proofs about shapes from axioms and definitions"],"answer":0,"explanation":"Describing shapes by properties is analysis. Seeing that a square has all the properties of a rhombus, and so belongs to that class, needs informal deduction, which she has not yet reached.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1609","question":"After learning the properties of a rhombus and a kite, students get the task: ‘Change a rhombus into a kite that is not a rhombus by moving only one vertex. Find as many ways as you can and explain them.’ Which Van Hiele learning phase does this task belong to?","options":["Inquiry (information)","Free orientation","Directed (guided) orientation","Explicitation"],"answer":1,"explanation":"Free orientation gives open, many-step tasks that students solve in their own ways, using properties they already know. Directed orientation uses short, teacher-led steps towards one property.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1610","question":"At the end of a unit, students make a chart showing how squares, rectangles, rhombuses, parallelograms and kites are related, and use it to summarise what they learnt. Which Van Hiele phase is this?","options":["Directed orientation","Explicitation","Integration","Free orientation"],"answer":2,"explanation":"In integration, the last phase, students review and pull together what they have learnt into an overall picture. The teacher helps them build this overview but does not add new ideas.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1611","question":"After a class solves the handshake problem for 10 people, the teacher asks, ‘Could your method work for 50 people? Can you solve it another way?’ In Pólya's model, this is:","options":["understanding the problem","devising a plan","carrying out the plan","looking back"],"answer":3,"explanation":"Looking back means checking the result, trying other methods and extending the solution to new cases. It is the stage most often skipped and the one that builds generalisation.","difficulty":"moderate","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1612","question":"Asked ‘How many squares are there on a chessboard?’, all students in a Class 6 class answer 64. Which prompt from the teacher is best?","options":["‘Are there squares bigger than one small square on the board?’","‘The answer is actually 204; can you check it and find out why?’","‘Count only the white squares and then double your answer.’","‘64 is correct; well done. Now let us move on to the next problem.’"],"answer":0,"explanation":"The question has a trap: squares of sizes 1 × 1 up to 8 × 8 give 64 + 49 + … + 1 = 204. A prompt that reopens the problem keeps the thinking with the students; giving the answer ends it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1613","question":"A Class 4 child works out 5 hours 10 minutes − 2 hours 40 minutes and writes 2 hours 70 minutes. What has the child most likely done?","options":["Subtracted the hours wrongly, taking 2 from 5 to get 2 instead of 3","Regrouped one hour as 100 minutes instead of 60, as in place value","Added the minutes instead of subtracting them, then adjusted the hours","Read the two times from a clock face wrongly before she subtracted"],"answer":1,"explanation":"Borrowing an hour gives 60 + 10 = 70 minutes, and 70 − 40 = 30, so the answer is 2 hours 30 minutes. Her 110 − 40 = 70 shows she is using base-ten regrouping for time.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1614","question":"A Class 6 child writes 3 1/2 − 1 3/4 = 2 1/4. What has she done?","options":["Changed both mixed numbers into improper fractions wrongly before subtracting them","Used a wrong common denominator for 1/2 and 3/4, so the fraction parts went wrong","Subtracted wholes, then 1/2 from 3/4 as 1/2 is smaller, instead of regrouping a whole","Added the fractional parts instead of subtracting them, while subtracting the wholes"],"answer":2,"explanation":"Since 1/2 < 3/4, one whole must be regrouped: 2 3/2 − 1 3/4 = 1 3/4. Taking the smaller fraction from the larger is the fraction form of the ‘smaller from larger’ error in whole numbers.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1615","question":"NCF 2005 calls for engaging every student with a sense of success while also offering challenge. Which task design best fits this?","options":["Separate easy worksheets for weak students and hard ones for bright students throughout the year","The same set of routine exercises for all students, so that everyone gets an equal chance to succeed","Only the textbook's ‘challenge’ problems for everyone, so that all students are stretched to the limit","Easy-to-start tasks that can go far, e.g. ‘Find numbers that are sums of consecutive numbers’"],"answer":3,"explanation":"Low-floor, high-ceiling tasks let every child succeed at some level while the most able go deeper. Permanent labelling with easy and hard sheets limits what some children can reach.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1616","question":"A Class 6 student says two lines drawn on a page are parallel because they do not meet on the page. What is the best response?","options":["Ask her to extend both lines with a ruler and check whether the gap stays the same","Agree, since lines that do not meet anywhere on the page must be parallel to each other","Tell her to measure the length of each line, since parallel lines must be equal in length","Tell her that parallel lines must be horizontal, like the lines in her ruled notebook"],"answer":0,"explanation":"Lines that look separate on a page may meet when extended. Parallel lines never meet however far they are extended, which means the distance between them stays the same everywhere.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1617","question":"A Class 2 child says a big balloon must be heavier than a small stone. Which activity best addresses this?","options":["Tell her clearly that size has nothing to do with weight and ask her to remember it","Let her predict which side will go down, then compare the two on a simple pan balance","Show her pictures of heavy and light things and ask her to sort them into two groups","Ask her to compare the two by looking carefully at their size and shape before deciding"],"answer":1,"explanation":"Young children often judge weight by size. Predicting and then testing on a balance gives direct evidence that big things can be light and small things heavy.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1618","question":"A teacher asks, ‘The answer is 24. What could the question be?’ What is the main value of this kind of question for assessment?","options":["It is quick to mark, since every child's answer will be the same number, 24","It tests only multiplication facts, since 24 is best reached through the tables","Children give many different answers, showing the range and depth of understanding","It is suitable only for gifted children, since others cannot handle an open question"],"answer":2,"explanation":"An open question lets each child respond at her own level, from 20 + 4 to 1/2 of 48 or 4 × 6. The variety shows the teacher what each child understands.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1619","question":"A Class 5 child with dyscalculia understands problems well but makes many calculation errors. In a word-problem test, which accommodation best lets her show her reasoning?","options":["Removing word problems from her test, since they need calculation that she finds hard","Giving her the same test with no support, so that her result is fair compared with others","Giving her only easier sums with small numbers, so that she can get more answers right","Allowing a number line or calculator, with extra time, while she shows her reasoning"],"answer":3,"explanation":"Accommodations should remove the barrier, not the learning goal. Support for computation lets her show her problem-solving and reasoning, which is what the test is meant to measure.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1620","question":"A Class 5 child finishes every maths task quickly and then becomes restless. What is the best response from the teacher?","options":["Give her richer problems that go deeper, such as investigating patterns or posing her own","Give her more sums of the same kind, so that she gets extra practice and stays busy","Make her help the teacher with chores such as distributing notebooks and cleaning the board","Ask her to sit quietly and read until the others finish, so the class is not disturbed"],"answer":0,"explanation":"Enrichment through depth and challenge keeps able learners engaged and growing. More of the same work only punishes speed and does not develop her thinking.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1621","question":"Assertion (A): Errors in children's mathematical work should be treated as windows into their thinking. Reason (R): Many errors are systematic, coming from a consistent but incorrect rule the child applies.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Because many errors follow a rule the child believes in, studying them shows what the child thinks and what to teach. R explains why A is good practice.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1622","question":"Assertion (A): Mathematical games at the primary stage are meant only for fun and do not support learning. Reason (R): Games can give purposeful practice and help children think about strategy.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Well-chosen games give repeated practice in a motivating way and build reasoning about strategy, so R is true and it shows why A is false. NCF 2005 recommends games at the primary stage.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1623","question":"Which of these statements about maths anxiety are correct? I. It can affect children who are otherwise capable in maths. II. Publicly comparing marks can increase it. III. It is best tackled by giving more timed tests. IV. Collaborative, low-stakes tasks can reduce it.","options":["I and III only","I, II and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"Maths anxiety is not the same as low ability, and public comparison and time pressure make it worse. Collaborative, low-stakes work helps; more timed tests usually increase it, so III is false.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1624","question":"A Class 3 child writes 34 × 5 = 1520. Her working shows 4 × 5 = 20 and 3 × 5 = 15 written side by side. What is the error?","options":["She does not know the 5 times table well, so both of her partial products come out wrong","She multiplied the tens digit by 10 first and then by 5, adding an extra zero","She writes partial products 20 and 15 side by side, ignoring place value and regrouping","She added the digits instead of multiplying them, getting a much bigger number"],"answer":2,"explanation":"34 × 5 = 150 + 20 = 170. Writing ‘15’ and ‘20’ side by side ignores place value and regrouping; an area model with 30 × 5 and 4 × 5 makes the two parts and their sum visible.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1625","question":"Assertion (A): Role play can sometimes reinforce stereotypes instead of challenging them.\nReason (R): When portraying characters, students may draw on stereotyped ideas unless the teacher prepares them and debriefs afterwards.","options":["Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true","Both A and R are true and R is the correct explanation of A"],"answer":3,"explanation":"Students tend to act out the images they already carry, such as a 'villager' or a 'tribal', which can harden stereotypes. That is why preparation and debriefing matter; R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1626","question":"Which of the following are features of the approach of NCERT's Social and Political Life textbooks for Classes VI to VIII?\n1. They use narratives and case studies of individual people.\n2. They avoid discussing inequality, to keep children comfortable.\n3. They ask students to relate concepts to their own experience.","options":["1 and 3 only","1 and 2 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"These books build concepts through stories of people and repeatedly ask students to connect them with their lives. They deal openly with inequality, discrimination and marginalisation rather than avoiding it.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1627","question":"Class VII students believe that the Mughal Empire began only after the Vijayanagara kingdom had ended. Which activity best corrects this?","options":["Ask students to memorise the founding year of each kingdom and arrange them in order","Tell them the two kingdoms were in different regions, so their dates do not matter at all","Draw both kingdoms as parallel bars on one timeline to show the decades they coexisted","Rearrange the chapters in the textbook so that the Mughal chapter comes after Vijayanagara"],"answer":2,"explanation":"The Mughals were established in the north in 1526, while Vijayanagara remained powerful in the south until its defeat in 1565. Parallel bars make this overlap visible, correcting the idea that history is a single line of succession.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1628","question":"A Class VI student's map of her route from home to school is neatly drawn but has no north arrow and no key for the symbols she used. What should the teacher's feedback focus on?","options":["Praising the neat drawing, since neatness is the main quality of a good map","Asking her to colour the map more brightly so that each place stands out","Asking her to redraw it on a larger sheet so that more detail can be shown","Adding a direction arrow and a key, so that others can read and use the map"],"answer":3,"explanation":"Direction and a legend are what turn a drawing into a usable map. Neatness or colour matter far less than the elements that make a map readable by someone else.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1629","question":"Class VII students read an English translation of a Persian chronicle. One asks, 'Is this translation still a primary source?' Which answer is most accurate?","options":["No; once a text is translated it becomes a secondary source, and so it is of little real use to a historian","The original is primary; the translation lets us read it, but the translator's choices shape its meaning","Yes; a good translation is exactly the same as the original in every way, so nothing changes","No; a primary source must be read in its original language, or it cannot be used at all"],"answer":1,"explanation":"Historians use translations all the time, but translation involves interpretation. Students should treat the content as coming from the original while noting that the translator's choices mediate it.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1630","question":"In a village in Andhra Pradesh, families are divided over a proposal to open a liquor shop, and students bring the issue to their Class VIII social science period. What is the most appropriate approach?","options":["Study the decision process, the gram sabha's role and each side's case, with ground rules and a neutral teacher","Refuse to discuss it in class, since the issue divides parents and could lead to quarrels among students","Tell students which side is morally right, since teachers should guide children on such social questions","Ask students to hold a vote and announce the class result to the gram sabha as the voice of the village's youth"],"answer":0,"explanation":"A live local controversy is an ideal way to learn about local democracy when handled fairly: process, institutions and arguments, with the teacher facilitating rather than campaigning.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1631","question":"A Class VII teacher points out that the only hand pump in a village was installed in the hamlet of the landowning families, and asks, 'Who decided this, and who is left out?' What is she mainly helping students understand?","options":["How hand pumps work and why they are needed where piped water is not available","That access to public facilities can reflect power and inequality in a community","That government facilities are always placed fairly, according to each hamlet's need","That villages do not really need hand pumps if they have wells and ponds nearby"],"answer":1,"explanation":"The question links a physical facility to social power: who decides where public resources go and who loses out. That is a core concern of social science teaching on equality.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1632","question":"A Class VIII teacher notices a memorial in the town square with the names of people who died in a local event of the freedom struggle. Which activity makes best use of it?","options":["Ask students to copy all the names into their notebooks so that the martyrs are never forgotten","Take a group photograph at the memorial for the school magazine, with a short caption about the freedom struggle","Have students find out who these people were and how the event is remembered, from family memories and records","Ignore it, since the event is not in the textbook and will not be asked in the board examination"],"answer":2,"explanation":"Local memorials are entry points into local history and into how communities remember the past. Investigating them builds research skills and connects national history to the students' own place.","difficulty":"hard","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1633","question":"Class IX students in a Kerala school are asked to frame questions for a local history project. Which question is the most suitable for inquiry?","options":["When exactly was our town founded, and who was the ruler of the area at that time in history?","Who is the present MLA of our constituency, and which party has won the seat most often since 1957?","How many schools, hospitals and post offices are there in our town today, according to official records?","Why did many families here migrate to the Gulf in the 1970s and 1980s, and how did it change our town?"],"answer":3,"explanation":"A 'why' and 'how' question about change invites investigation of causes and effects using interviews, records and data. The others have single factual answers.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1634","question":"During a Class VII discussion of a sad story about a family that lost its land, a boy's eyes fill with tears and others laugh, saying, 'Boys don't cry.' How should the teacher use this moment?","options":["Tell the boy quietly to control himself, so that he is not teased further by the class later","Ignore the laughter so that the lesson can continue and the boy is not embarrassed further","Scold the class sharply for laughing and move on with the story without any discussion","Stop the mockery gently and help the class see 'boys don't cry' as a norm that limits all"],"answer":3,"explanation":"The incident is a live example of gender norms, which social science teaches are socially constructed. Addressing it protects the child and turns the moment into learning, instead of suppressing it.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1635","question":"While teaching about floods in Class VIII, the teacher asks, 'Who suffers most in a flood, and why?' Which understanding is this question meant to build?","options":["That floods affect everyone living in the area equally, since rising water does not choose whom it harms","That a disaster's impact depends on people's situation, such as poverty, housing, gender and disability","That floods are caused only by heavy rain, so their effects cannot be prevented by people","That only governments can reduce the effects of floods, through dams and relief camps"],"answer":1,"explanation":"Disasters strike unevenly: the poor in fragile housing, women, the elderly and persons with disabilities often face the worst effects. The question shifts students from seeing disasters as purely natural to seeing their social dimension.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1636","question":"A Class X teacher presents two countries, each with five citizens. In Country A, each earns ₹10,000 a month. In Country B, four earn ₹500 each and one earns ₹48,000. What should students conclude?","options":["Both have the same average income of ₹10,000, but the average hides the extreme inequality in B","Country B is richer, because one of its citizens earns ₹48,000, far more than anyone in Country A","Country A is poorer, because no one there earns a high income and its people have no rich class","Both are equally developed, since average income is the best measure of how well people live"],"answer":0,"explanation":"Country B's average is (4 × 500 + 48,000) ÷ 5 = ₹10,000, the same as A. The example shows why averages must be read alongside distribution when judging development.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1637","question":"A Class VI teacher asks students to mark on a map where their parents and grandparents were born, if they wish to share it. What is the main learning, and why is sharing optional?","options":["It mainly tests map-reading skills; sharing is optional so that the activity does not take too long","It shows that mostly rural people migrate; sharing is optional because migration can be embarrassing","Migration runs through many family histories and wider patterns; sharing is optional for privacy","It ranks families by how far they have moved; sharing is optional so that no family feels left behind"],"answer":2,"explanation":"Family migration maps make migration personal and reveal patterns across the class. Some families may have painful or private histories, such as displacement, so participation must be voluntary.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1638","question":"Which of the following classroom activities is a simulation?","options":["Students take the roles of judge, lawyers and witnesses in a mock trial","Students read the chapter on the judiciary silently and underline key terms","Students answer a quiz on the names and levels of courts in India","Students write an essay on why courts are important in a democracy"],"answer":0,"explanation":"A simulation recreates a real process in which students take roles and act it out. Reading, quizzes and essays do not involve modelling the process.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1639","question":"A Class VIII teacher asks, 'Don't you all agree that the British only harmed India?' What is the main problem with this question?","options":["It is too difficult for Class VIII students, who cannot yet judge colonial rule as a whole","It is about history, not political science, so it does not belong in a civics lesson","It has too many correct answers, so students will not be able to agree on a single one","It is a leading question that signals the answer wanted, so students do not weigh evidence"],"answer":3,"explanation":"Leading questions close inquiry by telling students what to think. An open question, such as 'In what ways did colonial rule affect different groups?', invites evidence-based reasoning.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1640","question":"Before starting a unit on the Constitution, a teacher has Class VIII students fill the first two columns of a chart: what they already know and what they want to know. The third column, what they learnt, is filled at the end. What is the main purpose?","options":["To keep students busy and quiet while the teacher prepares the materials for the unit","To activate prior knowledge, give students ownership of questions and aid reflection","To check students' handwriting and spelling before they begin writing longer answers","To replace the unit test, since the chart already shows what each student has learnt"],"answer":1,"explanation":"A KWL chart connects new learning to what students know, turns their questions into goals for the unit and prompts reflection at the end.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1641","question":"Assertion (A): Memorising the textbook's list of the causes of the Revolt of 1857 develops historical understanding.\nReason (R): Historical understanding requires analysing how causes are connected and weighing the evidence for them.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is false but R is true","A is true but R is false"],"answer":2,"explanation":"R correctly describes historical understanding, and that is exactly what a memorised list does not provide. A is false.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1642","question":"Looking at a population density map, Class IX students say Kerala must have more people than Rajasthan because Kerala is shaded much darker. What should the teacher clarify?","options":["The students are right, since darker shading on any map always means a larger total population","Shading on such maps is mainly decorative and is used to make the states easier to tell apart","Shading shows density (people per sq km); Rajasthan is less dense but much larger, with more people","Population cannot really be shown accurately on maps, so students should use only the census tables"],"answer":2,"explanation":"Density is a ratio, not a total. Kerala is densely populated but small; Rajasthan has a lower density over a much larger area and a larger total population. Confusing density with total is a common map-reading error.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1643","question":"A Class VII section runs a monthly wall magazine on which students publish short reports on local issues, such as a broken road or a new bus route, with interviews and photographs. What does this activity mainly develop?","options":["Inquiry, communication and civic engagement with the local community","Decorative and display skills that make the classroom walls look attractive","Memorisation of textbook answers through repeated writing on local topics","Competition between sections, since the best magazine wins a school prize"],"answer":0,"explanation":"Researching, interviewing and reporting on local issues builds inquiry and communication skills and an active interest in community affairs, all central aims of social science.","difficulty":"hard","source":"CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1644","question":"A Class IX student writes accurate facts in history answers but never explains how one event led to another. Which remedial strategy is most effective?","options":["Ask her to write much longer answers, since more words will give the examiner more points to mark","Give her more facts to memorise, since a richer store of facts will naturally lead to better explanations","Tell her that explanation is not really needed in history, as long as her facts are accurate","Model explanations with words like 'because' and 'as a result', and practise linking causes and effects"],"answer":3,"explanation":"The student lacks the skill of causal explanation, not knowledge. Modelling and scaffolded practice with linking language build that skill directly; length or more facts do not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS"},
  {"id":"cdp-pedagogy-subjects-1645","question":"A Class VIII student with dyslexia understands social science discussions well but scores poorly in written tests. Which adjustment is most appropriate?","options":["Lower the expectations for the student permanently, so that the student does not feel pressured","Give audio-visual materials and extra time, and allow some assessment orally or through diagrams","Ask the student to copy the chapter daily, since copying will improve reading and writing skills","Exempt the student from social science, so that more time can be spent on reading practice"],"answer":1,"explanation":"Inclusive practice removes barriers to showing learning while keeping the same goals. Alternative modes of access and assessment let the student's understanding show; lower expectations or exemption are discriminatory.","difficulty":"hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1646","question":"Which of the following describe what 'multiple perspectives' means in social science?\n1. Comparing how different groups experienced the same event\n2. Accepting every claim as valid even without evidence\n3. Recognising the position of the author of a source","options":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"answer":2,"explanation":"Multiple perspectives means attending to different groups' experiences and to who is speaking in a source. It does not mean that every claim is equally valid regardless of evidence.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1647","question":"Which learning objective is best framed for a Class VI lesson on rural livelihoods?","options":["Students will know about rural life and the many different occupations found in Indian villages.","Students will appreciate villages and develop respect for the hard work done by rural people.","Students will compare the work, income and security of a landless labourer and a landowner.","Students will understand the chapter on rural livelihoods fully and answer all its questions."],"answer":2,"explanation":"A good objective names a specific, observable performance, here comparing on stated aspects using given material. 'Know', 'appreciate' and 'understand fully' are vague and cannot be checked.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1648","question":"A Class X teacher asks students to say whatever comes to mind when they hear 'globalisation' and writes every response on the board without comment. Which technique is she using, and what is its purpose?","options":["Brainstorming, to generate ideas freely and reveal what students already know","Lecture, to explain the concept step by step, using students' own words as examples","Drill, to fix the correct definition of globalisation through repetition","Debate, to decide which of the responses is right and which are wrong"],"answer":0,"explanation":"Brainstorming collects many ideas quickly without judging them, revealing what students already know and think. Sorting and evaluating the ideas comes afterwards.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1649","question":"Which test item best assesses whether Class VIII students can apply the concept of representation?","options":["Define representation in your own words and give one example of it from the textbook chapter.","Your class of 40 must pick four members to meet the principal. Suggest a fair method that represents all groups.","Name the number of members in the Lok Sabha and state how many of its seats are reserved for SC and ST candidates.","Write two lines on the importance of representation in a democracy, using the key terms from the chapter."],"answer":1,"explanation":"Applying a concept means using it in a new situation. Designing a fair selection for a class committee requires students to think about who is represented and how, which a definition or a fact cannot show.","difficulty":"very-hard","source":"CTET Paper 2 · state TETs · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1650","question":"A Class VIII teacher wants students to work with a primary source in a lesson on the Salt Satyagraha. Which material should she choose?","options":["The summary of the Salt March given in the current textbook","A newspaper report of the march published in 1930","A quiz on the dates of the march prepared by the teacher","A documentary on the march made in 2015, with a modern narrator"],"answer":1,"explanation":"A newspaper report printed during the march was produced at the time of the event, so it is a primary source. A present-day textbook summary and a recent documentary interpret the event later and are secondary.","difficulty":"moderate","source":"CTET Paper 2 · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1651","question":"A Class II teacher plans a week of reading: P. children read a new levelled book on their own; Q. the teacher reads a big book aloud, thinking aloud about how she works out a hard word; R. a small group reads a book with the teacher's prompts and support; S. the whole class reads the big book together with the teacher. Following the gradual release of responsibility, what is the right order?","options":["S, Q, R, P","Q, R, S, P","Q, S, R, P","P, R, S, Q"],"answer":2,"explanation":"Responsibility moves from teacher to child: modelling (Q, 'I do'), shared reading (S, 'we do'), guided reading (R, 'you do with help') and independent reading (P, 'you do alone').","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1652","question":"In a Class I classroom in Mandla, the teacher starts each day with a circle time in which children talk about what they saw on the way to school, in whatever language they are comfortable with. Which outcome is this practice most directly designed to support?","options":["Completing the textbook faster, since children are already settled and ready when the lesson starts","Oral language development and confidence, which form the base for reading and writing","Testing children's general knowledge about their surroundings and the events of the day","Keeping children calm and quiet before the first period of formal teaching begins"],"answer":1,"explanation":"Rich daily conversation builds vocabulary, listening and speaking, and a sense of belonging, all of which underpin early literacy. NCF-FS 2022 gives conversation a central place for this reason.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1653","question":"A Class III teacher wants children's writing to be purposeful rather than copying from the board. Which task best meets this aim?","options":["Copying the textbook lesson neatly in notebooks, so that children learn correct spelling and sentences","Writing the same sentence ten times, so that handwriting becomes neat and letters are well formed","Writing answers to questions from the guidebook, so that children have correct material to revise","Writing a letter to the gram panchayat about the broken handpump near school, after discussing it"],"answer":3,"explanation":"Writing for a real audience and purpose gives children a reason to organise ideas and use language meaningfully. Copying and repetition practise form but not composition.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1654","question":"Four-year-old Pinky fills a page with wavy lines and a few letter-like shapes, then 'reads' it to her teacher: 'Milk, bread, sugar.' Which interpretation is most accurate?","options":["She shows emergent writing: she knows writing carries a message, before using conventional letters","She is only scribbling, which has no real connection to writing and will simply stop as she grows","She is confused about writing, because she cannot actually read what she wrote and is only pretending","She should be taught to trace letters properly before she is allowed to 'write' on her own again"],"answer":0,"explanation":"Assigning meaning to marks shows an understanding that print carries messages, a key emergent literacy milestone. Treating it as meaningless scribble or forcing tracing undervalues this development.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1655","question":"A Class III teacher measures her students' reading only by words read correctly per minute and praises the fastest readers. Many fast readers cannot say what the passage was about. Which conclusion is most appropriate?","options":["Speed is the most reliable measure of reading ability, since fast readers will understand more in time","The passage was too easy, so children raced through it without needing to think about the meaning","Fluency matters as a support for comprehension; assessment must check understanding, not just speed","Comprehension cannot be properly assessed as early as Class III, so speed is the best measure available"],"answer":2,"explanation":"Fluency is a bridge to comprehension, not the goal itself. Rewarding speed alone encourages 'barking at print' without meaning-making.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1656","question":"Assertion (A): Well-planned, engaging lessons prevent much classroom misbehaviour. Reason (R): Students who are actively involved in meaningful tasks have fewer reasons and opportunities to go off task.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Preventive classroom management relies on engagement, clear routines and pace; much disruption comes from boredom, confusion or idle time, as R explains.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1657","question":"While rushing in a Class II art activity, Mohit spills paint across a table. Which teacher response is an example of a logical consequence rather than a punishment?","options":["Making Mohit stand in the corner for the rest of the period to think about his carelessness","Taking away his recess for two days, so that he learns to be careful with class materials","Writing a note in his diary so that his parents know about the mess and can talk to him","Asking Mohit to help clean the table and to carry paint more carefully next time"],"answer":3,"explanation":"A logical consequence (Dreikurs) is directly and reasonably related to the behaviour and teaches responsibility. Standing in a corner or losing recess have no link to the spill and are punitive.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1658","question":"Two Class V boys get into a fight after one breaks the other's model. Which approach reflects restorative practice?","options":["Bring them together to talk about what happened, how each was affected and how to repair the harm","Suspend both boys for a day, so that the rest of the school learns that fighting is not tolerated","Find out who started the fight and punish only him, since the other boy was only defending himself","Separate the two boys for the rest of the year, so that they get no further chance to quarrel"],"answer":0,"explanation":"Restorative practice focuses on understanding harm, taking responsibility and repairing relationships, rather than only assigning blame and punishment.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1659","question":"A Class VI teacher in a crowded government school has 62 students and a small room. Which set of strategies is most likely to keep the class productive?","options":["Clear, well-paced lectures, a strict silence rule, and a short question slot at the very end","Clear routines and signals, small groups with rotating leaders, materials ready, pair talk","Ability-based rows, extra time for the weaker rows, and a monitor to keep others quiet","One whole-class activity at a time, with each student called up to the board in turn"],"answer":1,"explanation":"Routines, signals and organised groups and pairs make active learning possible even with 62 students. Well-paced lectures keep order but leave most students passive, and ability rows label learners.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1660","question":"In a pre-primary class, three-year-olds Anu and Babu sit side by side, each building with blocks, sometimes copying each other but not building together. Their teacher is worried that they are 'not playing together'. According to Parten's stages of play, what should she conclude?","options":["They have a social development problem and should be referred to a counsellor for support","They should be made to build one tower together, so that they learn to cooperate early","This is parallel play, which is normal at this age and leads on to cooperative play","This is solitary play, which shows that they do not like each other and prefer to be alone"],"answer":2,"explanation":"Parten found that playing alongside others with similar materials (parallel play) is common in young preschoolers and precedes associative and cooperative play. It is not a sign of a problem.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1661","question":"Match each type of play described by Piaget with the example: P. A baby repeatedly shaking a rattle to hear the sound; Q. A four-year-old using a leaf as a plate for 'feeding' her doll; R. Eight-year-olds playing kho-kho by agreed rules. Types: 1. Games with rules; 2. Practice (functional) play; 3. Symbolic play.","options":["P-3, Q-2, R-1","P-2, Q-3, R-1","P-2, Q-1, R-3","P-1, Q-3, R-2"],"answer":1,"explanation":"Practice play repeats actions for their own sake (sensorimotor years), symbolic play uses one thing to stand for another (preoperational years), and games with rules emerge strongly in middle childhood.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1662","question":"Consider the following statements about experiential and vocational exposure in NEP 2020: 1. It suggests '10 bagless days' during Grades 6 to 8, when students intern with local vocational experts such as carpenters, gardeners or potters. 2. It treats vocational exposure as only for students who are weak in academics. 3. It aims to reduce the hard separation between academic and vocational streams. Which of these are correct?","options":["1 and 2 only","2 and 3 only","1, 2 and 3","1 and 3 only"],"answer":3,"explanation":"NEP 2020 proposes bagless days with local vocational experts for all students in Grades 6-8 and seeks to remove hard separations between academic and vocational learning. Statement 2 contradicts this.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1663","question":"In a Class VI comprehension lesson, a teacher asks: 'The passage says the farmer's crops failed twice, and in the last paragraph he joins a self-help group. Using both parts, why do you think he made that decision?' In Raphael's Question-Answer Relationships (QAR), this question is of which type?","options":["Right There","On My Own","Think and Search","Author and Me"],"answer":2,"explanation":"Think and Search questions have answers in the text, but the reader must pull together information from different parts. 'Right There' answers sit in one sentence, and 'Author and Me' needs the reader's own knowledge as well as the text.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1664","question":"Assertion (A): Jigsaw classrooms tend to reduce hostility and prejudice among students from different social groups. Reason (R): In jigsaw, each student holds information others need, so students must depend on and listen to each other.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Aronson’s jigsaw cuts prejudice because every member’s piece is needed, so students must cooperate and come to value one another; this interdependence is exactly why hostility falls, so R explains A.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1665","question":"Before moving on in a Class VII lesson on fractions, a teacher asks one carefully chosen multiple-choice question where each wrong option matches a known misconception, and all students hold up their answer cards at once. What is the main purpose of this step?","options":["To collect a grade for every student that can be entered in the term's assessment record","To fill the remaining minutes of the period with a quick and enjoyable whole-class activity","To see at once who has the key idea and which misconceptions remain, before moving on","To make the lesson more competitive, since students enjoy seeing who gets the answer first"],"answer":2,"explanation":"Such a 'hinge' question gives instant evidence from every student at a decision point in the lesson; diagnostic distractors show exactly what to re-teach.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1666","question":"While teaching Class IV children to write a paragraph, a teacher first gives sentence starters and a word bank, then only a word bank, and finally asks them to write without any support. What is she doing?","options":["Reducing support step by step as children gain competence (fading the scaffold)","Lowering her expectations of the class, since many children could not write paragraphs","Making the task harder each time, as a way of pushing the class to work faster","Testing whether children can remember the word bank without seeing it any more"],"answer":0,"explanation":"Scaffolding is temporary support that is withdrawn as learners become independent; fading it gradually transfers responsibility to the child.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1667","question":"Biswajit, an Odia-speaking child, joins a Class II in Raipur where the medium is Hindi. Which step by the teacher is most likely to help him settle and learn?","options":["Seat him alone near the teacher, so that he can concentrate fully on learning Hindi without distraction","Pair him with a buddy who knows Odia and Hindi, accept Odia responses, and use pictures and gestures","Tell him to speak only Hindi from the first day, since that is the fastest way to learn it","Place him in Class I for a year until his Hindi is good enough for the Class II textbooks"],"answer":1,"explanation":"A bilingual peer buddy offers emotional and language support, and accepting his language keeps him learning while Hindi develops. Isolation, a language ban or demotion all set him back.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1668","question":"Aarav, a Class II child on the autism spectrum, becomes very upset when the timetable changes unexpectedly. Which classroom strategy is most helpful?","options":["Avoid telling him about changes in advance, so that he does not spend the day worrying","Change routines often and without warning, so that he gradually gets used to change","Use a visual schedule, warn him in advance of any change, and keep routines predictable","Take him out of the class whenever the routine changes, until he has calmed down fully"],"answer":2,"explanation":"Many autistic children rely on predictability; visual schedules and advance warning of changes reduce anxiety and help them participate. Surprises and frequent changes increase distress.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1669","question":"In a B.Ed. micro-teaching session, a trainee teaches a 5-minute lesson focused only on the skill of probing questions, receives feedback, re-plans, and re-teaches to a new small group. What is the main reason for this design?","options":["To cover a large part of the syllabus in a short time through many very short lessons","To evaluate the trainee for final certification, since each re-teach is graded separately","To replace real classroom practice teaching, which is too difficult for most trainees","To practise one skill at a time in a simple setting, with feedback and repeated attempts"],"answer":3,"explanation":"Micro-teaching scales down time, class size and content so that a single skill can be practised, observed and refined through the teach-feedback-reteach cycle.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1670","question":"A Class I teacher in Meerut replaces all the Hindi and local rhymes her children know with English nursery rhymes, believing this will speed up English learning. What is the most valid concern?","options":["English rhymes are too long and too fast for Class I children to learn and remember easily on their own","It drops familiar rhymes that build sound awareness, and signals that the home language matters less","Rhymes have no real role in early literacy, so the time would be better spent on letters","Children cannot learn more than one language at a time, so English rhymes will confuse them"],"answer":1,"explanation":"Rhymes in a language children understand develop sensitivity to sounds and rhythm, which supports reading in any language. Dropping them devalues the home language and removes meaningful input. Children can learn several languages.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1671","question":"A Class IV teacher holds a weekly class meeting in which children raise problems (for example, 'the ball is always taken by the same group at recess'), suggest solutions and agree on one to try. What does this mainly develop?","options":["Dependence on the teacher, who finally decides which solution the class should follow","Competition between groups of children to see whose solution gets the most votes","Skills of democratic participation, problem-solving and shared responsibility","Children's habit of complaining about each other instead of settling matters themselves"],"answer":2,"explanation":"Class meetings give children a voice in managing their community and teach negotiation and responsibility, a democratic approach to classroom management. The teacher facilitates rather than imposes.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1672","question":"To assess speaking in a Class IV English class, the teacher records each child's 1-minute talk about a favourite food on her phone and listens later with a rubric, sharing the recording with the child. Which advantage is most important?","options":["It allows careful, repeated listening for fair marking, and the child can hear herself and see progress","It removes the need for a rubric, since the teacher can simply compare children's recordings","It allows the teacher to post the recordings publicly, so parents can see what children can do","It replaces the need to talk with children during class, since all speaking can now be recorded at home"],"answer":0,"explanation":"Recordings make oral assessment more reliable and give learners concrete feedback and evidence of growth. Privacy still matters, so recordings should not be posted publicly.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · state TETs"},
  {"id":"cdp-pedagogy-subjects-1673","question":"A Class V teacher believes, 'If I let children talk to each other during a task, I lose control of the class.' Which response best reflects current understanding of classroom management and learning?","options":["She is right; a silent class is a well-managed class, and talk should wait until the task is finished","She should allow talk only during recess and games, when it cannot disturb the learning of others","Talk should be allowed only in language periods, where speaking is itself the skill being taught","Structured, purposeful talk aids learning; good management means routines and focus, not silence"],"answer":3,"explanation":"Learning is social, and productive noise during structured tasks is a sign of engagement. Management aims at an environment where learning happens, not at silence for its own sake.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1674","question":"Consider the following statements about using local toys and games in the foundational stage: 1. They can be made from low-cost local materials, sometimes by children themselves. 2. They connect school learning to children's culture and home experience. 3. They are useful only for physical development and not for language or number. Which of these are correct?","options":["1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"],"answer":0,"explanation":"Local toys and games are affordable, culturally rooted and rich contexts for language, counting, patterns and social skills, so statement 3 is false.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1675","question":"A Class VIII teacher wants her students to evaluate, not just recall, after a lesson on renewable energy. Which task best does this?","options":["‘List five sources of renewable energy and say which of them are used in your own state.’","‘Define solar energy in your own words and give two examples of its use in everyday life.’","‘Draw a neat, labelled diagram of a windmill and name the main parts that help it make electricity.’","‘Solar panels or a biogas plant for our school? Recommend one, judging cost, local needs and benefits.’"],"answer":3,"explanation":"Making and defending a judgement using criteria is Evaluate. Listing and defining are Remember and Understand, and drawing a known diagram is reproduction.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1676","question":"A Class 9 teacher has students collect and practise whole expressions such as ‘by the way’, ‘I was wondering if…’, ‘make a decision’ and ‘as far as I know’, treating them as ready-made units rather than building them word by word from rules. This reflects:","options":["The audio-lingual method, which drills single sentence patterns","The grammar-translation method, which works through word lists","The lexical approach, which sees language largely as chunks","The silent way, which builds sentences with coloured rods"],"answer":2,"explanation":"Michael Lewis’s lexical approach holds that much fluent language consists of prefabricated chunks and collocations, so learners should notice and store them as wholes.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1677","question":"A Class 8 English course is organised into units titled ‘Making requests’, ‘Apologising’, ‘Giving directions’ and ‘Expressing opinions’, rather than ‘Present tense’ or ‘Passive voice’. This is a:","options":["Structural syllabus, ordered by grammar items","Notional-functional syllabus, ordered by functions","Lexical syllabus, ordered by how often words occur","Procedural syllabus, ordered by a fixed list of tasks"],"answer":1,"explanation":"A notional-functional syllabus, linked with Wilkins and early communicative teaching, organises content around what learners need to do with language rather than grammatical forms.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1678","question":"Teacher P teaches grammar first and then gives communicative activities to practise it. Teacher Q gives communicative tasks from the start and expects language to develop through using it. In the debate on communicative language teaching, these are known respectively as the:","options":["Strong version and weak version of CLT","Grammar-translation and direct method","Structural approach and audio-lingual method","Weak version and strong version of CLT"],"answer":3,"explanation":"The ‘weak’ version (Howatt) adds communicative practice to a taught syllabus — learning to use English; the ‘strong’ version claims language is acquired through communication — using English to learn it.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1679","question":"Assertion (A): Learners taught only by the grammar-translation method often read and translate texts well but struggle to hold a conversation. Reason (R): The grammar-translation method gives priority to reading, writing and accuracy, and very little to spoken communication.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"What a method practises is what learners become good at; GTM’s focus on written texts and rules explains its learners’ weak speaking.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1680","question":"Consider these statements about the direct method: I. The mother tongue is used to explain difficult words. II. Oral skills are given priority. III. Grammar is taught inductively through examples. Which are correct?","options":["I and II only","II and III only","I and III only","I, II and III"],"answer":1,"explanation":"The direct method bans the mother tongue and conveys meaning through demonstration and context, so I is false; it puts speech first and lets learners infer rules from examples.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1681","question":"A Class 5 EVS lesson is taught in English to children still learning it. The teacher uses pictures, real objects, simplified sentences and a list of key words, and plans aims for both the science content and the language needed to talk about it. This approach is best described as:","options":["Immersion with no support, so that learners sink or swim","The grammar-translation method applied to a science lesson","Content and language integrated learning, with dual aims","Teaching EVS through the mother tongue alone, without English"],"answer":2,"explanation":"CLIL integrates subject learning with language learning, using scaffolds such as visuals and key vocabulary so that both content and language develop together.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1682","question":"While doing a jigsaw puzzle alone, a five-year-old mutters, ‘This blue one… no, not here… the corner piece goes first.’ According to Vygotsky, this talk:","options":["Is egocentric speech that shows the child cannot yet think logically","Is mere imitation of adult speech without any purpose","Is a sign of a language disorder that needs a specialist’s attention","Is private speech that helps the child guide and regulate her action"],"answer":3,"explanation":"Vygotsky saw private speech as social speech turned inward to plan and guide behaviour, a step towards inner speech; Piaget, by contrast, called such talk egocentric.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1683","question":"A Class 7 student who normally uses past tenses correctly makes several tense errors when speaking nervously during the school assembly. In Chomsky’s terms, these errors are best described as reflecting:","options":["Limits of performance, not of competence","A gap in her linguistic competence","An error in her language acquisition device","Fossilisation of her interlanguage"],"answer":0,"explanation":"Competence is the underlying knowledge of language; performance is its use in real conditions, affected by nerves, fatigue or memory. Her usual accuracy shows the knowledge is there.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1684","question":"A teacher reads that, according to the critical period hypothesis, it becomes harder to acquire native-like pronunciation after puberty. The most sound conclusion for teaching Class 9 beginners is that:","options":["They can no longer learn English, so teaching should focus on Hindi","They should learn only through grammar rules, since acquisition stops at puberty","They can still reach high proficiency, though a home-language accent may remain","They will learn faster than young children in every area of language"],"answer":2,"explanation":"Age effects mainly concern ultimate pronunciation; adolescents often learn rules and vocabulary quickly and can become highly proficient, so neither giving up nor a rules-only approach follows.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1685","question":"Anil studies English to clear a job interview at a bank. Fatima studies English because she loves English novels and wants to make friends with her pen pals in other countries. In Gardner’s terms, their motivation is respectively:","options":["Integrative and instrumental","Integrative and integrative","Intrinsic and extrinsic","Instrumental and integrative"],"answer":3,"explanation":"Instrumental motivation is learning a language for practical gain such as a job; integrative motivation is the wish to connect with the language’s speakers and culture.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1686","question":"A Class 6 teacher lets students choose their own books for weekly reading from a class library and share why they liked them. The main motivational principle behind this is that:","options":["Choice and personal interest build intrinsic motivation to read","Marks for reading increase the effort that students put in","Reading is enjoyable only when it is free of any discussion","Students read more when the teacher selects every book for them"],"answer":0,"explanation":"Autonomy and interest are key sources of intrinsic motivation; choosing books and sharing responses makes reading personally meaningful rather than a task done for marks.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1687","question":"A Class 8 student keeps a vocabulary notebook of words she meets outside class, sets herself a weekly goal and checks her progress with an online quiz. These habits mainly show:","options":["Dependence on the teacher for all decisions about learning","Learner autonomy: taking charge of her own learning","A lack of interest in the classroom English lesson","Memorisation without any understanding of the words"],"answer":1,"explanation":"Autonomous learners set goals, choose strategies and monitor progress; teachers foster this because language learning continues far beyond the classroom.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1688","question":"To remember the English word ‘pane’, a Hindi-speaking student imagines rain water (‘paani’) streaming down a window pane. This is an example of:","options":["Learning through grammar-translation","Guessing meaning from context while reading","The keyword method, a memory strategy","Overgeneralising a rule of English"],"answer":2,"explanation":"The keyword method links a new word to a similar-sounding known word through a vivid image; Oxford classes such mnemonics as memory strategies.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1689","question":"Class 5 children read a play script aloud in parts with expression, using voice rather than costumes or memorised lines, and then perform it for another class. This technique, called readers’ theatre, mainly develops:","options":["Silent reading speed and quick scanning skills","Fluent, expressive reading through rehearsal","Memorisation of long passages for examinations","Handwriting through copying the play script"],"answer":1,"explanation":"Rehearsing a script for an audience gives a real reason for repeated reading, which builds fluency, phrasing and expression without the pressure of memorising.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1690","question":"After reading a short story about a girl who leaves her village for the city, a Class 9 teacher first asks, ‘How did the ending make you feel? Has anyone in your family made a similar move?’ This reflects:","options":["A translation approach that renders the story into Hindi","A grammar-based approach that uses the story to teach tenses","A biographical approach that studies the author’s life","A reader-response approach that values personal response"],"answer":3,"explanation":"Reader-response approaches start from the reader’s own engagement and experience, making literature personally meaningful before close analysis.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1691","question":"A teacher tells Class 8 students, ‘Never begin a sentence with “And” or end one with a preposition.’ A linguist would say this rule reflects:","options":["A prescriptive view, saying how people should use the language","A descriptive view, recording how people actually use the language","A universal rule found in the grammar of all human languages","A rule of pronunciation rather than of grammar"],"answer":0,"explanation":"Prescriptive rules state what is considered correct, often by tradition; descriptive grammar records actual usage, in which such sentences are common in good writing.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1692","question":"A Class 3 child who reads Hindi fluently writes English words exactly as they sound, such as ‘nite’ for ‘night’ and ‘sed’ for ‘said’. The most likely reason is that:","options":["Devanagari is spelt far more regularly than English","She has a learning disability affecting her memory for words","She has not learnt the English alphabet and letter names properly","She is careless and does not check her work"],"answer":0,"explanation":"Devanagari is largely phonetic, so she expects one spelling for each sound; English spelling is far less regular, so its patterns need explicit teaching.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1693","question":"Many Class 9 students give every syllable of an English sentence almost equal weight, which makes their speech hard to follow for some listeners. The teacher plans work on sentence stress and weak forms. The best explanation of the difficulty is that:","options":["Indian learners cannot hear differences in loudness between syllables","English has fewer vowel sounds than most Indian languages, so all sound alike","English is stress-timed; many Indian languages are syllable-timed","The students have not been taught enough grammar to group words into phrases"],"answer":2,"explanation":"English rhythm depends on stressed syllables with unstressed ones reduced; carrying over a more syllable-timed rhythm affects intelligibility, so stress and weak forms need attention.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1694","question":"In a Class 7 section of 55 students, the teacher wants to assess speaking regularly. Which practice is most feasible and valid?","options":["Giving a written test on spoken English phrases","Observing a few groups each week with a checklist","Asking each student to recite a poem once a year","Assessing speaking only through the final examination"],"answer":1,"explanation":"Rotating observation of group work with clear criteria gives continuous, valid information on real speaking in a large class; written tests and recitations do not assess spontaneous speaking.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1695","question":"A Class 6 teacher sets up a weekly ‘book talk’ in which students briefly recommend a book they enjoyed and classmates may ask questions. Besides speaking practice, the main benefit is that it:","options":["Lets the teacher rank students by how many books they read","Tests students’ memory of the book’s exact words","Replaces the need for any reading in class","Builds a reading culture through peers’ recommendations"],"answer":3,"explanation":"Peer recommendations are powerful motivators; talking about books makes reading social and visible, encouraging others to pick up books.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1696","question":"Consider these statements comparing Krashen’s ‘i+1’ and Vygotsky’s ‘zone of proximal development’: I. Both suggest that learning happens just beyond the learner’s current level. II. The ZPD stresses help from a more knowledgeable other, while i+1 stresses comprehensible input. III. Both see the learner as a passive receiver of knowledge. Which are correct?","options":["II and III only","I and II only","I and III only","I, II and III"],"answer":1,"explanation":"Both ideas place learning slightly above present ability, but Vygotsky emphasises assisted performance in social interaction and Krashen emphasises understood input. Neither sees the learner as passive.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1697","question":"A lesson in the prescribed Class 6 reader is long and difficult for students in a rural school. Which adaptation is most appropriate?","options":["Build background, gloss key words and split the text into parts","Skip the lesson, since it is not suited to these students","Read the lesson aloud and dictate the answers to all the questions","Translate the whole lesson into the home language and teach only that"],"answer":0,"explanation":"Teachers adapt materials to learners: building background, supporting vocabulary and chunking keep the text and its learning while making it accessible.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1698","question":"In a programme for tribal children in Odisha, children begin literacy in their home language (such as Kui or Saora), then gradually move into Odia and later English, using what they know to learn the new. This model is:","options":["Submersion education in the state language","Subtractive bilingual education","Mother-tongue-based multilingual education","English-only immersion from Class 1"],"answer":2,"explanation":"MTB-MLE starts with the language children understand, builds strong literacy in it and then bridges to other languages, applying the principle of moving from the known to the unknown.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1699","question":"A Class 1 teacher writes a thank-you letter to the school gardener on chart paper while the children suggest what to say; she thinks aloud about spacing, capital letters and spelling as she writes their words. This practice is called:","options":["Guided writing","Independent writing","Copy writing","Shared writing"],"answer":3,"explanation":"In shared writing children compose together and the teacher acts as scribe, modelling the conventions of writing; in guided writing children hold the pen with teacher support.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1700","question":"A Class 1 teacher splits ‘cat’ into /k/ + ‘at’ and then makes ‘hat’, ‘mat’ and ‘bat’ by changing only the first sound. The units she is working with are:","options":["Syllables","Morphemes","Consonant digraphs","Onset and rime"],"answer":3,"explanation":"The onset is the first consonant sound(s) of a syllable and the rime is the vowel with what follows; word families like -at use rime patterns to read many words quickly.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1701","question":"A Class 5 child reads 4,05,000 as ‘four lakh five hundred’. What does this most likely show?","options":["She misread the 5's place; it is in thousands, so the number is four lakh five thousand","She does not know the word ‘lakh’ and uses it for any number with six digits","She has mixed up the Indian and international systems of numeration and their commas","She is careless and needs to read each number more slowly, pointing to every single digit"],"answer":0,"explanation":"In 4,05,000 the 5 is in the thousands place, so the number is four lakh five thousand. A place-value chart with lakhs, ten thousands and thousands helps her read each period by place.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1702","question":"A Class 4 child says 9,999 is greater than 10,001 ‘because 9 is bigger than 1’. What has the child not understood?","options":["How to read four-digit and five-digit numbers aloud using their place names","That numbers are compared first by number of digits, then place by place from the left","The names of the places, such as thousands and ten thousands, in large numbers","That numbers must be compared digit by digit starting from the ones place on the right"],"answer":1,"explanation":"A five-digit number is always greater than a four-digit number. Comparing first digits works only when both numbers have the same number of digits.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1703","question":"Rounding 346 to the nearest hundred, a Class 5 child first rounds it to 350 and then rounds 350 to 400. What is the best response?","options":["Accept it, since each step follows the rounding rule correctly and the final answer is a hundred","Tell her to always round up whenever a 5 appears at any stage of the rounding","Ask her to place 346 on a number line between 300 and 400 and see which it is nearer","Ask her to learn the rounding rule again and write it ten times in her notebook"],"answer":2,"explanation":"346 is 46 away from 300 and 54 away from 400, so it rounds to 300. Rounding in steps (chain rounding) adds error; the number line shows what ‘nearest’ means.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1704","question":"A Class 5 child works out 99 × 7 in her head as ‘700 − 7 = 693’. What is the best response from the teacher?","options":["Ask her to use the standard written algorithm instead, since it is safer and easier to check","Tell her that mental methods are not allowed in exams, so she must always show working","Mark it correct and move on without comment, since the answer she got is right","Ask her to explain her method and link it to (100 − 1) × 7, the distributive property"],"answer":3,"explanation":"Her strategy rests on the distributive property. Making it explicit helps her and the class use it on purpose, and lays groundwork for algebra.","difficulty":"hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1705","question":"A Class 5 child writes 1/3 + 1/3 + 1/3 = 3/9 = 1/3. Which question is most likely to create a useful conflict in her thinking?","options":["‘How many thirds of a roti make one whole roti?’","‘What is the LCM of 3 and 9, and how do you use it here?’","‘Can you simplify 3/9 again to check your final answer?’","‘What is 1/3 + 1/3? Write it the same way as before.’"],"answer":0,"explanation":"She knows that three thirds make a whole, yet her method gives one third. Facing that contradiction pushes her to rethink adding tops and bottoms, more than repeating the rule would.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1706","question":"A Class 2 child says a tall, thin glass holds more water than a short, wide bowl ‘because it is taller’. What is the most suitable activity?","options":["Tell her clearly that height does not matter and that wide containers hold more","Let her predict, then fill the glass and pour it into the bowl to compare","Show her the capacity marks on a measuring jug and explain what millilitres mean","Ask her to draw both containers carefully side by side and compare the drawings"],"answer":1,"explanation":"Young children judge capacity by height. Predicting and then pouring from one into the other gives direct evidence and builds the idea of capacity as the amount a container holds.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1707","question":"To find the time from 9:40 to 11:15, which tool best supports Class 4 children's reasoning?","options":["A rule to subtract 9:40 from 11:15 directly, as children do with decimal numbers","A clock with only an hour hand, so that children can count the hours that pass","An open number line jumping from 9:40 to 10:00, then to 11:00, then to 11:15","A calendar on which children mark the start and end times and count the gaps"],"answer":2,"explanation":"Jumping to the next hour gives 20 + 60 + 15 = 95 minutes, which is 1 hour 35 minutes. Treating times as decimals (11.15 − 9.40) gives a wrong answer because an hour has 60 minutes, not 100.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1708","question":"The morning temperature in Drass is −12 °C and it rises by 7 °C by noon. A Class 6 student says the noon temperature is −19 °C. Which response is best?","options":["Tell her to subtract the smaller number from the bigger number and keep the minus sign","Tell her that a rise always makes the number bigger, so the answer must be +19 °C","Ask her to add 12 and 7 again carefully and check her addition on her fingers","Ask her to start at −12 on a thermometer drawn as a number line and move 7 up"],"answer":3,"explanation":"Rising by 7 from −12 moves towards zero, reaching −5 °C. She added the sizes and kept the minus sign. A vertical number line makes the direction of change clear.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1709","question":"Before setting a Class 7 maths test, a teacher prepares a blueprint. What is its main purpose?","options":["To balance the test across content, objectives, question types and marks","To decide the pass marks and the grade boundaries before the test is set","To list the students who will take the test and their seating arrangement","To make the test as difficult as possible so that only the best can score full"],"answer":0,"explanation":"A blueprint is a planning grid that ensures a test covers the intended content and objectives in the right proportion, which supports the test's validity.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1710","question":"A Class 3 maths test has long word problems in complex English. A child in a Hindi-medium school scores poorly, but solves the same problems orally in Hindi. Which quality of the test is most affected?","options":["Its reliability, because the papers were marked by different teachers in the school","Its validity as a maths test, since it measures English reading more than maths","Its objectivity, because the word problems were open-ended and hard to mark","Its practicality, because the long problems took too much time to set and mark"],"answer":1,"explanation":"A test is valid when it measures what it intends to measure. Heavy language demands mean the scores reflect reading ability, not maths understanding.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1711","question":"Two teachers give very different marks to the same student's answer on an open-ended maths problem. Which step would most improve the reliability of marking?","options":["Giving only multiple-choice questions from now on, so that marking is automatic","Letting the more senior teacher's marks count, since she has more experience","Agreeing on a rubric with clear criteria and sample answers before marking","Averaging the two marks without any discussion, so that neither teacher is overruled"],"answer":2,"explanation":"Reliability means consistent scores across markers and occasions. A shared rubric with examples reduces differences between markers while keeping open-ended tasks.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1712","question":"A Class 9 student proves that the diagonals of a parallelogram bisect each other using congruent triangles, and explains how a definition differs from a theorem. At which Van Hiele level is she working?","options":["Analysis","Informal deduction","Rigour","Deduction"],"answer":3,"explanation":"Building formal proofs within an axiomatic system, and understanding the roles of definitions and theorems, marks the deduction level. Rigour involves comparing different axiomatic systems.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1713","question":"A Class 11 student compares triangles drawn on a flat sheet with triangles drawn on a ball and explains why their angle sums differ, depending on the axioms each geometry uses. This reasoning belongs to which Van Hiele level?","options":["Rigour","Deduction","Informal deduction","Analysis"],"answer":0,"explanation":"At rigour, the highest level, students compare different axiomatic systems, such as Euclidean and spherical geometry. School geometry seldom goes beyond deduction.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1714","question":"According to the NCF 2005 position paper on mathematics, the school mathematics curriculum ‘disappoints’ which groups?","options":["Only the children who are weak in mathematics and keep failing to clear the examinations","Only the teachers, who must complete a heavy syllabus within the academic year","Both a talented few who are not challenged and a majority who find it hard and drop out","Only the parents, who want their children to score higher marks in board exams"],"answer":2,"explanation":"The paper describes a curriculum that fails both the able few, who find it unchallenging, and the many who drop out of meaningful engagement. Both are among its core problems.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1715","question":"How does NCF 2005 describe the role of mathematics at the upper primary stage?","options":["Students mainly practise the four operations on much larger numbers and in longer word problems","Students first taste the power of maths through abstractions like algebra that compress earlier work","Students should begin learning formal two-column proofs in geometry, as is done in later classes","Students should study mathematics as a separate discipline with its own formal structure"],"answer":1,"explanation":"NCF 2005 sees the upper primary stage as the point where abstract ideas like algebraic notation start to summarise and extend earlier arithmetic. Seeing mathematics as a discipline with its own structure belongs to the secondary stage.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1716","question":"A Class 4 child in Bihar solves a word problem correctly when the teacher tells it in Bhojpuri, but gets the written Hindi version wrong. What should the teacher infer?","options":["The child has a learning disability in mathematics and should be assessed by a specialist","The child probably copied the oral answer from a friend who understood the Bhojpuri version","The child should be given only plain number sums from now on, and no word problems in any language","The barrier is reading, not maths; reading problems aloud and allowing the home language can help"],"answer":3,"explanation":"Correct oral solutions show the mathematical reasoning is in place. The barrier is language and reading, which needs separate support so it does not hide her mathematical ability.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1717","question":"To find 6 + 4 + 3, a Class 3 child writes ‘6 + 4 = 10 + 3 = 13’. What is the problem with this?","options":["6 + 4 = 10 + 3 is false; she uses ‘=’ to mean ‘and then’, not ‘is equal to’","There is no problem, since each step is correct and the final answer, 13, is right","She should have added 4 and 3 first, since addition must go from right to left","She has added the numbers in the wrong order; 3 should have been added before 4"],"answer":0,"explanation":"Read as written, the line claims 6 + 4 = 13. Such run-on number sentences reveal an operational view of ‘=’, which causes difficulty later in algebra; writing 6 + 4 = 10 and 10 + 3 = 13 fixes it.","difficulty":"very-hard","source":"CTET Paper 1 · CTET Paper 2 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1718","question":"A Class 5 child writes 1/2 × 6 = 1/12. Which question best helps her?","options":["‘What is 6 × 2? Is it 12?’","‘What is half of 6 rotis?’","‘Can you write 6 as 6/6?’","‘What is 1/2 + 6 rotis?’"],"answer":1,"explanation":"She multiplied the denominator by 6. Half of 6 rotis is clearly 3 rotis, which shows that 1/2 × 6 = 6/2 = 3; writing 6 as 6/1 is what makes the rule work.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1719","question":"A Class 5 child says 7.08 and 7.8 are equal ‘because zero has no value’. What is the best response?","options":["Agree, since zeros in decimals have no value and can always be removed","Tell her that 7.08 is larger, because it has more digits after the point","Ask her to show both on a metre stick, as 7 m 8 cm and 7 m 80 cm","Ask her to learn by heart that zero is a number and does have a value"],"answer":2,"explanation":"The 0 in 7.08 holds the tenths place, so the 8 means 8 hundredths, while in 7.8 it means 8 tenths. A trailing zero (7.80) can be dropped; a zero between digits cannot.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1720","question":"A Class 7 student writes 0.5% = 1/2. What is the misconception?","options":["She does not know that 1/2 is the same as 0.5 when written as a decimal","She has confused percentage with ratio, reading 0.5% as the ratio 1 : 2","She has made a small slip in copying the question and wrote % by mistake","She ignored the % sign: 0.5% means 0.5 per hundred, or 1/200; 1/2 is 50%"],"answer":3,"explanation":"0.5% = 0.5/100 = 0.005 = 1/200. She has read 0.5% as the decimal 0.5. Small percentages like this are often confused with the decimal written before the % sign.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1721","question":"Class 5 children each draw a map of the route from school to the bus stop, but their maps do not match in size or distances. What is the best next step?","options":["Use the mismatch to discuss why maps need a common scale, e.g. 1 cm for 10 steps","Ask the children to copy the teacher's map, so that everyone has the same correct one","Tell them that only official maps are correct, since children's maps are just drawings","Ask them to draw the maps again more neatly and with a ruler, so that they match better"],"answer":0,"explanation":"The differences give a real reason for the idea of scale. Children who feel the need for a common scale understand it far better than those simply told about it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1722","question":"Assertion (A): In Classes 1 and 2, the ‘+’ sign should be introduced only after children have solved many joining stories orally and with objects. Reason (R): Symbols have meaning for children only when they stand for experiences the children already have.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Symbols record ideas; introduced before the experiences they stand for, they become marks to manipulate without meaning. R gives the reason for A.","difficulty":"hard","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1723","question":"Assertion (A): Since Van Hiele levels depend on age, all children in Class 8 reason at the deduction level. Reason (R): Progress through the Van Hiele levels depends mainly on instruction and experience.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Van Hiele levels are not tied to age; they depend on experience and teaching, so Class 8 students may be at different levels, many below deduction. A is false and R is true.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1724","question":"Which of these statements about number sense are correct? I. It includes thinking flexibly about numbers, for example seeing 8 as 5 + 3, 10 − 2 or 4 + 4. II. Children who count quickly always have good number sense. III. Estimation is part of number sense. IV. Number sense grows through rich talk and experience, not only drill.","options":["I and II only","I, III and IV","II, III and IV","I, II, III and IV"],"answer":1,"explanation":"Fast counting is a procedural skill and does not guarantee number sense, so II is false. Flexibility, estimation and growth through experience and talk describe number sense.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1725","question":"Two equal paper squares are each cut in half, one along a diagonal (two triangles) and one down the middle (two rectangles). A child says a triangle and a rectangle cannot both be halves ‘because they are different shapes’. What does the child need to understand?","options":["That only rectangles can be halves of a square, since a square has straight sides","That triangles are always smaller than rectangles cut from the same square","That a half means equal size relative to the same whole, not a particular shape","That the squares were not cut correctly, since halves must always look the same"],"answer":2,"explanation":"Each piece is half the area of an equal square, so both are halves. Drawing both on squared paper and counting squares shows that the triangle and the rectangle cover the same area.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1726","question":"A Class 5 teacher plans a story lesson in three stages: pre-reading, while-reading and post-reading. Which activity belongs to the post-reading stage?","options":["Predicting the story from its title and the cover picture","Answering a question at the end of each section while they read","Writing a letter from one character to another about the events","Discussing key words needed to follow the first page"],"answer":2,"explanation":"Post-reading tasks use the understood text for extension and personal response, such as writing in role; prediction and key words come before reading, and section questions during it.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1727","question":"Teaching a poem about the monsoon to Class 8, which approach best develops appreciation of figurative language?","options":["Giving definitions of simile and metaphor for students to learn by heart","Asking students to find images and discuss what each makes them feel","Listing all the figures of speech in the poem with their names for copying","Asking students to write the meanings of difficult words from a guidebook"],"answer":1,"explanation":"Appreciation grows from noticing how images work and responding to their effect; naming devices without engaging with them turns poetry into labelling.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1728","question":"A Class 6 teacher’s daily homework is ‘Write the meanings of 20 words from the dictionary.’ Which homework would build vocabulary more effectively?","options":["Writing the meanings of 40 words instead, so that more words are covered","Copying the same 20 words five times each to remember their spellings well","Learning the dictionary entries for words that begin with one letter","Reading a story of their choice and noting three new words in context"],"answer":3,"explanation":"Words met in meaningful reading, noted with their context and chosen by the learner, are retained and understood better than lists copied from a dictionary.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1729","question":"Class 7 students produce a monthly class newspaper: they interview staff and classmates, write reports and reviews, edit each other’s pieces and read the finished issue. Which statement about this project is most accurate?","options":["It mainly develops handwriting, since the paper is written by hand","It integrates all four skills through real, purposeful tasks","It is a writing task only, since the outcome is a written newspaper","It is useful only for students who already write very well"],"answer":1,"explanation":"Interviewing involves speaking and listening, reports involve writing, and editing and reading the issue involve reading; the real audience gives every skill a purpose.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1730","question":"Many Class 9 students memorise answers to textbook questions from guidebooks and reproduce them in tests. Which step by the teacher would best encourage genuine understanding?","options":["Banning guidebooks and searching bags regularly to enforce the ban","Setting the same textbook questions but awarding marks only for exact wording","Asking for personal responses and applications that no guidebook contains","Giving more questions from the guidebook so that students practise them better"],"answer":2,"explanation":"Questions that ask students to interpret, relate the text to their lives or apply ideas cannot be answered by memorised guide answers, which shifts effort towards real comprehension.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1731","question":"To teach ‘in’, ‘on’ and ‘under’ to Class 2, which activity is most effective?","options":["Writing the definitions of the three words for children to copy","Making children memorise a list of sentences using each word","Asking children to underline ‘in’, ‘on’ and ‘under’ in a long passage","Children placing a ball in, on and under a box on command"],"answer":3,"explanation":"Acting out spatial relationships links each preposition directly to its meaning through movement, in the spirit of Total Physical Response.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1732","question":"A teacher with 60 students in Class 6 avoids pair work because she fears noise and loss of control. Which advice is most practical?","options":["Demonstrate first, set a time limit and agree on a signal to stop","Avoid pair work altogether, since large classes need lecture teaching","Use pair work only with the best students, while the rest copy notes","Allow pair work only in the last five minutes when noise matters less"],"answer":0,"explanation":"Pair work multiplies speaking time in large classes; careful set-up, demonstration, time limits and an agreed signal keep it purposeful and manageable.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1733","question":"A Class 3 teacher gives a long instruction in English for a game, and most children start doing different things. What should she do next time?","options":["Repeat the same instruction louder and more slowly","Give the instruction in writing on the board for children to read","Use short steps, demonstrate the game and check understanding first","Skip the game, since Class 3 children cannot follow English instructions"],"answer":2,"explanation":"Instructions work when they are brief, shown as well as told, and checked with simple questions such as ‘Who goes first?’; repeating a confusing instruction louder does not help.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1734","question":"After presenting ‘I used to live in Patna’, a teacher asks, ‘Do I live in Patna now?’ and ‘Did I live there for a long time?’ The main purpose of these questions is to:","options":["Test whether students can spell ‘Patna’ correctly","Find out where the students themselves used to live","Practise forming questions in the simple present tense","Check that students understand what ‘used to’ means"],"answer":3,"explanation":"Concept-checking questions test understanding of meaning, here a past habit or state that is no longer true, without relying on students repeating the form.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1735","question":"Before introducing the word ‘well’, a teacher shows a picture and asks, ‘What is this? What do people in your village use it for?’ The main purpose of this elicitation is to:","options":["Draw on children's knowledge and involve them before giving the word","Find out which children do not know the word, so they can be corrected","Save time by avoiding the need to teach the word at all","Test children’s knowledge for the term report card"],"answer":0,"explanation":"Elicitation activates prior knowledge and gets learners thinking and talking, so the new word attaches to an existing concept instead of being simply announced.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1736","question":"In a ‘listen and draw’ activity, a teacher describes a picture (‘There is a big tree on the left. A cat is sitting under it…’) and Class 3 children draw what they hear. This activity mainly assesses and develops:","options":["Drawing ability, since the outcome is a picture","Listening comprehension, shown without speaking or writing","Speaking fluency, since children talk about their drawings","Reading skills, since children read the description"],"answer":1,"explanation":"Drawing gives children a way to show understanding of spoken language without needing to speak or write, which suits young learners.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1737","question":"A Class 8 teacher gives an open-book English test in which students may use their textbook. What is this kind of test best suited to assess?","options":["Memorisation of passages and answers","Speed of handwriting under examination conditions","Locating, interpreting and applying information","Knowledge of the author’s biography"],"answer":2,"explanation":"Since the text is available, open-book questions must go beyond recall and assess higher-order skills such as finding, interpreting and using information.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1738","question":"Assertion (A): During a storytelling session, a Class 1 teacher should not correct every pronunciation slip a child makes. Reason (R): Constant correction can raise anxiety and discourage children from speaking.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In a meaning-focused activity, over-correction shifts attention to form and raises the affective filter; that is exactly why selective, later feedback is preferred.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1739","question":"Preparing Class 4 children for a visit to the railway station, the teacher introduces ‘ticket counter’, ‘platform’, ‘coach’, ‘porter’ and ‘announcement’ with a picture of a station and role play. Why is this an effective way to teach vocabulary?","options":["The words are taught in alphabetical order, which aids memory","The words form a set linked to a real situation they will meet","The words are short and easy to spell","The words are taught without any context, which avoids confusion"],"answer":1,"explanation":"Grouping words around a situation the children will experience gives them context, makes connections between words and offers an immediate use for them.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1740","question":"Consider these factors: I. Long sentences with many clauses. II. An unfamiliar topic for which children have little background. III. Many abstract or rare words. Which can make a text harder for Class 5 readers?","options":["I only","I and III only","II and III only","I, II and III"],"answer":3,"explanation":"Text difficulty depends on sentence complexity and vocabulary, and also on the reader’s background knowledge of the topic; all three raise the load.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1741","question":"A Class 6 teacher includes folk tales from Assam, Kerala and Africa in her English reading lessons. Apart from language, the main benefit is that children:","options":["Develop empathy and awareness of other cultures","Learn the exact geography of each place in the tales","Memorise more stories for examinations","Learn that all stories have the same ending"],"answer":0,"explanation":"Literature from varied cultures lets children see the world through other eyes, fostering empathy and respect for diversity, while also giving rich language input.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1742","question":"A school measures each Class 3 child’s oral reading fluency as words read correctly per minute. Which interpretation is most accurate?","options":["It indicates fluency but needs pairing with comprehension checks","A high score proves that the child fully understands what she reads","It measures only the child’s pronunciation of difficult words","It is useless and should never be used in schools"],"answer":0,"explanation":"Fluency is closely linked to comprehension, but a child can read fast without understanding; fluency measures need to be paired with comprehension tasks.","difficulty":"very-hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1743","question":"In communicative language teaching, the teacher’s role is best described as:","options":["The main source of knowledge who lectures and corrects every error","A silent observer who never takes part in the activities","A facilitator who sets up communication and monitors and guides","A drill leader who models sentences for repetition"],"answer":2,"explanation":"CLT moves the teacher from transmitter to facilitator, needs analyst and sometimes co-communicator, organising activities in which learners use language meaningfully.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1744","question":"A Class 4 child with attention difficulties finds it hard to sit through a 40-minute English lesson and often disturbs others. Which classroom adjustment is most suitable?","options":["Making him sit at the back so that he disturbs fewer children","Breaking tasks into short steps with movement breaks and clear routines","Excusing him from English lessons until he can sit still","Giving him the same long tasks as others but with punishment for disturbance"],"answer":1,"explanation":"Short, structured tasks, predictable routines and chances to move help children with attention difficulties stay engaged; isolation and punishment do not.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1745","question":"A Class 7 student finishes every English task quickly and accurately and has started to look bored. The most appropriate step is to:","options":["Give her more exercises of the same type to keep her busy","Make her correct the work of all her classmates every day","Ask her to sit quietly until the others finish","Offer extension tasks like writing a sequel to the story"],"answer":3,"explanation":"Enrichment should deepen and broaden learning with challenging, creative tasks, not simply add more of the same or turn the student into an assistant.","difficulty":"hard","source":"CTET Paper II · State TETs"},
  {"id":"cdp-pedagogy-subjects-1746","question":"Class 8 students compare a Hindi poem with its published English translation and discuss which images or sounds were lost or changed. The main purpose of this activity is to:","options":["Prove that English translations are always inferior to the original","Notice how each language carries meaning and culture differently","Train students to translate word by word for examinations","Replace the reading of English poems in the syllabus"],"answer":1,"explanation":"Comparing an original with its translation sharpens sensitivity to how languages encode meaning, rhythm and culture, using translation as a resource for language awareness.","difficulty":"very-hard","source":"CTET Paper II · KVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1747","question":"A Class 1 child reads ‘ship’ as ‘s–h–i–p’, saying a separate sound for ‘s’ and ‘h’. The teacher should next teach that:","options":["‘sh’ is a digraph: two letters that stand for one sound","‘ship’ must be memorised as a sight word","The child should spell the word aloud before reading it","‘s’ and ‘h’ are silent letters in this word"],"answer":0,"explanation":"Digraphs such as ‘sh’, ‘ch’ and ‘th’ represent single sounds; knowing them lets the child blend correctly (/ʃ/–/ɪ/–/p/). ‘Ship’ is perfectly decodable once the digraph is known.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1748","question":"Each morning a Class 1 teacher writes a short message on the board (‘Good morning! Today is Monday. We will plant seeds.’) and reads it with the children, pointing to the words. The main value of this routine is that it:","options":["Replaces the need for storybooks in the classroom","Tests which children can read the date correctly","Gives meaningful daily reading and models writing","Mainly teaches children the days of the week"],"answer":2,"explanation":"A ‘morning message’ is real, predictable text about the children’s own day, so it builds concepts of print, sight words and the idea that writing carries meaning.","difficulty":"hard","source":"CTET Paper I · KVS PRT · NVS"},
  {"id":"cdp-pedagogy-subjects-1749","question":"A teacher wants Class 3 children to learn ‘at’, ‘on’ and ‘in’ with time expressions. Which plan teaches them in a meaningful context?","options":["Giving the rule and 20 unrelated blanks to fill in","Correcting children’s mistakes with these words in their notebooks only","Asking children to memorise lists of times, days and months","Using the timetable and a festival calendar (‘Diwali is in November’)"],"answer":3,"explanation":"The timetable and calendar give real, familiar contexts in which the contrast (at with clock times, on with days and dates, in with months) is needed and used.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1750","question":"After each group presentation, Class 6 students give peer feedback as ‘two stars and a wish’: two things that worked well and one thing to improve. The main value of this format is that it:","options":["Replaces the teacher’s feedback completely","Lets students give marks to each other for the term report card","Avoids any mention of weaknesses so that nobody gets upset","Makes feedback specific and balanced, so it is easy to act on"],"answer":3,"explanation":"Naming strengths alongside one clear target keeps feedback constructive and focused, and teaches students to look at work against criteria.","difficulty":"hard","source":"CTET Paper I · State TETs"},
  {"id":"cdp-pedagogy-subjects-1751","question":"In a Hindi writing task, a Class I child writes ‘मेर नम सत ह’ for ‘मेरा नाम सीता है’. Every consonant is right and in the right order, but no matras are written. What does this most likely show?","options":["A visual-processing difficulty, because she drops the small marks written above, below and beside letters","That she copies letter shapes from memory and has not yet linked the printed letters with sounds","A systematic early stage: she hears each akshar and writes its base consonant, but has yet to mark vowels","That she does not yet hear the vowel sounds in spoken words and needs hearing and speech screening"],"answer":2,"explanation":"Writing the right consonant for each syllable, in order, shows she is mapping sounds to print; the vowel signs are the next layer to build, as with invented spelling. Because the letters match the sounds, it is not rote copying or a disorder.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1752","question":"During a Class 4 maths lesson taught in Hindi, a child reads ‘अंश 3, हर 4’ and asks, ‘हर का मतलब तो हर एक होता है न?’ Which idea from language across the curriculum best describes what the teacher must now do?","options":["Treat ‘हर’ as a subject-register word whose special meaning must be built explicitly, in context, in the maths class","Switch to English terms such as ‘denominator’, because technical words in English carry only a single meaning","Send the child to the Hindi teacher, since the confusion reveals a gap in general vocabulary for the language period","Give the class a glossary of all fraction terms to memorise before any further work on fractions is attempted"],"answer":0,"explanation":"Every subject has its own register, and everyday words used with a special meaning (हर = denominator) must be taught by the subject teacher in context. Language learning is every teacher's job, and memorised glossaries do not build meaning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1753","question":"A three-and-a-half-year-old Hindi-speaking child says, ‘कल मैं नानी के घर जाया था।’ No adult around her uses ‘जाया’. The best interpretation is that she:","options":["is copying a non-standard form heard at home, showing that speech is learnt mainly by imitation","has a vocabulary delay, because by this age children should know the past forms of common verbs","is confusing the present and past tenses, which children usually sort out only after starting school","is applying the regular past-tense pattern (-या) to an irregular verb, a sign of active rule-making"],"answer":3,"explanation":"‘जाया’ follows the regular pattern (खाया, आया) and is not heard from adults, so it cannot be imitation; it shows the child has extracted a rule and over-applied it, just like ‘goed’ in English.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1754","question":"Moumita, whose home language is Bengali (which has no grammatical gender), joins a Hindi-medium Class 3 and says ‘मेरा किताब’ and ‘बस आया’. Which response by the teacher is most sound?","options":["Teach the rule that nouns ending in -ई are feminine and those ending in -आ are masculine, so that she can work out the gender of new nouns","Give rich, meaningful exposure and recast her sentences naturally, as Hindi noun gender is learnt word by word through use","Correct each gender error the moment it occurs, so that the wrong forms do not settle into fixed habits","Explain that gender follows meaning, so objects linked with women or softness take the feminine forms"],"answer":1,"explanation":"Hindi noun gender is largely arbitrary (पानी and दही are masculine, किताब and बस are feminine), so the -ई/-आ rule misleads and the meaning rule is false. It is acquired through plenty of meaningful input and gentle recasts, not constant interruption.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1755","question":"In a Kendriya Vidyalaya in Chennai, Class 7 learners of Hindi write both ‘मैं कल फ़िल्म देखा’ and ‘राम ने घर गया’. What do these two errors, taken together, most strongly suggest?","options":["The learners have not yet been taught the past tense and are guessing forms from the present tense","The errors are careless slips, because a learner who knew no rule would not make two opposite mistakes","The learners know that ‘ने’ exists but are unsure when it applies, a normal interlanguage stage","The learners are carrying Tamil word order into Hindi, so the subject, object and verb end up in the wrong positions"],"answer":2,"explanation":"‘ने’ is needed with transitive verbs in the perfective (मैंने फ़िल्म देखी) but not with intransitive ones (राम घर गया). Leaving it out in one and over-using it in the other shows a partly formed rule; Tamil, like Hindi, is verb-final, so word order is not the issue.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1756","question":"A Class 3 Hindi teacher writes the prose meaning (भावार्थ) of each line of a बालगीत on the board and has children memorise it for the test. Which criticism is most accurate?","options":["It turns the poem into a prose passage, losing the rhythm, images and personal response that poetry at this stage aims to build","The real problem is that children should memorise the poem itself, since recitation rather than meaning is the aim of poetry","Prose meanings are useful, but only after children have first memorised a word list of every difficult word in the poem","The method is sound, because written tests at this stage mainly check whether children know the meaning of each line"],"answer":0,"explanation":"At the primary stage poetry is for enjoyment: rhythm, sound, imagery and the child's own response. Line-by-line paraphrase for memorising kills that, while mere recitation without engagement is not the aim either.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1757","question":"A Class 3 child's dictation shows ‘दीन’ for ‘दिन’, ‘पुरा’ for ‘पूरा’ and ‘कीताब’ for ‘किताब’, though every consonant is correct. Which plan most directly targets this pattern?","options":["Daily choral chanting of the full बारहखड़ी until every vowel sign can be recited in order without a single mistake","Copying each misspelt word correctly ten times, so that the right visual form becomes fixed in memory","Teaching the rule that ‘ि’ is written before the consonant and ‘ी’ after it, with daily practice in placing each sign","Oral games contrasting short and long vowels in meaningful pairs (दिन–दीन, कुल–कूल), then linking each to its matra"],"answer":3,"explanation":"The errors are all short/long vowel (ह्रस्व–दीर्घ) confusions, so the child needs to hear and contrast vowel length in meaningful words and then link it to the sign. The position of ‘ि’ is not her problem, and chanting or copying does not build the distinction.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1758","question":"Hindi-medium Class 7 students can recite that ‘वाष्पोत्सर्जन पत्तियों से होता है’ but cannot explain it. What should the science teacher do first?","options":["Replace the Hindi terms with the English ones, which students will need anyway in higher classes","Build the idea through observation (a bag tied over a leafy twig), then give the term and its parts, वाष्प + उत्सर्जन","Ask the Hindi teacher to teach such words as examples of sandhi in the grammar period, so that their meaning becomes clear","Start each chapter with a list of new terms and their meanings, and test the list before the lesson begins"],"answer":1,"explanation":"The concept must come before the label: once students have seen water collect in a bag around a leafy twig, the technical word, broken into meaningful parts, names something they understand. Switching language or memorising glossaries leaves the concept unbuilt.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1759","question":"Consider these statements about languages in the NCF for School Education 2023: 1. R1 is ideally the child's home language or a familiar language, used for early literacy. 2. R2 can be any language other than R1, including English. 3. All three languages, R1, R2 and R3, must be native to India. 4. R3 is generally introduced in the Middle Stage. Which are correct?","options":["1 and 3 only","2, 3 and 4 only","1, 2 and 4 only","1, 2, 3 and 4"],"answer":2,"explanation":"Following NEP 2020, at least two of the three languages must be native to India, not all three, so statement 3 is wrong; English can be R2 or R3, and R3 usually begins in the Middle Stage.","difficulty":"hard","source":"CTET · KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1760","question":"Class 6 students in a Bengaluru school, learning Hindi as a second language, understand spoken Hindi from films and songs but cannot read Devanagari. Which starting point makes best use of what they bring?","options":["Use songs and dialogues they already know orally as first reading texts, so decoding rests on familiar language","Begin with the full varnamala chart in order, since reading cannot really start until every single letter is known","Write Hindi in the Roman script at first, since the students can already read English letters","Teach the main grammar rules of Hindi first, so that reading later becomes simply a matter of applying them to texts"],"answer":0,"explanation":"Texts whose language children already know orally let them check their decoding against meaning, which speeds up learning the script. Romanised Hindi delays the script, and grammar-first or alphabet-first ignores their oral strength.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1761","question":"Asked to write a Hindi essay on ‘मेरा प्रिय त्योहार’, almost all 40 students in a Class 8 submit near-identical essays memorised from a guidebook. Which change to the task would best assess their real writing ability?","options":["Have them write on the same topic again in class under close supervision, with guidebooks kept away","Cut marks for any essay longer than 150 words, so that long memorised passages become pointless","Mark only spelling and grammar, since the content of the essays is identical and so cannot be compared fairly","Set a situation from their own lives, such as a letter to a cousin about last Eid or Diwali in your lane"],"answer":3,"explanation":"A specific, personal situation cannot be met with a memorised text, so it shows how students actually organise ideas and use language. Supervision does not stop recall of a memorised essay, and marking only accuracy ignores expression.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1762","question":"A Class I Hindi teacher says, ‘कमल में से ‘क’ हटा दो, क्या बचा?’ and children answer ‘मल’. The game is done only orally. It mainly builds:","options":["phonics, because children link the letter ‘क’ with the sound it stands for","phonological awareness at the akshar (syllable) level","phonemic awareness at the level of single consonant sounds","concepts of print, since children learn where a word begins"],"answer":1,"explanation":"‘क’ here is the whole syllable /ka/, and removing it from ‘कमल’ leaves ‘मल’; the task is oral syllable deletion. No print is involved, so it is not phonics or print awareness, and no single phoneme is isolated.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1763","question":"NCERT's ‘बरखा’ series of graded storybooks for Classes 1 and 2 is designed mainly so that children:","options":["learn the varnamala one letter at a time, with each book built around a new letter","practise neat copying, since every page gives a model sentence for children to trace","read on their own, for pleasure and meaning, through short everyday stories graded by level","learn moral values, as every story ends with a clearly stated lesson for class discussion"],"answer":2,"explanation":"Barkha is a supplementary graded reading series of short stories from children's everyday lives in natural language, meant to help them become independent readers who read with enjoyment and understanding.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1764","question":"A Class 2 child writes ‘परेम’ for ‘प्रेम’ and ‘करम’ for ‘कर्म’. What does this most likely reveal?","options":["She hears every sound but writes each as a full akshar, not yet knowing how clusters are joined (half letters, रेफ)","She cannot hear the /r/ sound inside such words and needs listening drills on that sound before more writing","She is confusing ‘र’ with the vowel ‘ऋ’, which is why she adds an extra syllable","She is carrying the spelling patterns of English words into Hindi, so she adds a vowel between the two consonants"],"answer":0,"explanation":"Both spellings contain every sound in the right order; she simply writes a vowel-bearing full letter where Hindi writes a cluster (प्र, र्म). She needs to learn the conjunct conventions through familiar words, not hearing drills.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1765","question":"Which way of teaching ‘विशेषण’ to Class 6 best reflects a contextual, inductive approach to grammar?","options":["Give the definition with five examples, then set an exercise in which students underline the adjectives in sentences","Have students learn the kinds of विशेषण (गुणवाचक, संख्यावाचक and so on) with two examples of each","Define ‘विशेषण’ first and then ask students to find adjectives in the lesson they have just read","Children describe objects from a bag, list the describing words they used, notice their job, then get the term"],"answer":3,"explanation":"Inductive grammar moves from use to noticing to naming: children first use describing words for real, then see what they do, and only then get the label. The other options all start from the definition.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1766","question":"Class 7 students memorise 50 मुहावरे with meanings from a guide, yet in their writing they misuse them, for example ‘उसने आँखें चुराकर किताब पढ़ी’ to mean ‘he read carefully’. What is the best way forward?","options":["Double the list so that they meet more idioms, and test the meanings every week through matching exercises","Let them meet idioms in stories and talk, discuss when and why speakers use them, and then use them in situations","Ask them to avoid idioms in their own writing until they are confident of every meaning on the list","Have them write each idiom's meaning ten times, since the misuse shows that the meanings were never properly learnt"],"answer":1,"explanation":"An idiom's meaning depends on context and connotation (आँखें चुराना = to avoid someone's eyes), which isolated lists cannot give. Meeting idioms in real discourse and using them for a purpose builds that sense.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1767","question":"A Class 2 child in a Bhili-speaking area writes a lively Hindi story about her goat, using several Bhili words where she does not know the Hindi ones. In assessing this piece, what should get the most weight?","options":["The number of Bhili words used, which shows how far she still is from writing in standard Hindi","The neatness of her handwriting and the correct use of the headline (शिरोरेखा)","Her ideas, sequence and expression, while the teacher notes the Hindi words she can learn next","Her spelling of the Hindi words, since accuracy is the main aim of writing at Class 2"],"answer":2,"explanation":"Drawing on her home language to say what she means is a strength, not a fault; assessment should value meaning and organisation, and the Bhili words show the teacher exactly which Hindi vocabulary to build next.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1768","question":"Class 1 children chant the whole बारहखड़ी (क का कि की…) perfectly every morning, yet stumble over ‘काम’ and ‘कील’ in a new sentence. The most accurate explanation is that:","options":["they know a chanted sequence but cannot yet recognise akshars out of order and blend them into words","the chanting has not gone on long enough, and fluent reading will follow once the chant is perfect and quick","the बारहखड़ी is the wrong unit altogether, since Hindi must be taught only as separate phonemes from the start","they cannot read new words until they have learnt all the conjunct letters as well"],"answer":0,"explanation":"Recitation is serial memory: a child can say ‘का’ after ‘क’ without recognising ‘का’ alone. Reading needs recognising akshars in any order and blending them into meaningful words, which must be practised with real text.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1769","question":"A Class 8 social science teacher in a Hindi-medium school has students rewrite the textbook section on drought as a short news report for a village notice board. Viewed as language across the curriculum, the main value of the task is that:","options":["it gives the Hindi teacher fewer writing tasks to set, since the subject teachers share that load","it lets the teacher check spelling and grammar in social science as well as in Hindi","it keeps students busy with writing so that they do not need the teacher's explanation","students reshape subject content for a new audience, which deepens understanding and builds a genre"],"answer":3,"explanation":"Transforming information into a different genre for a real audience makes students select, explain and organise the content, so language and subject learning feed each other; checking mechanics or sharing workload is not the point.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1770","question":"A Class 4 teacher crosses out ‘किताब’ and ‘दरवाज़ा’ in a child's composition and writes ‘पुस्तक’ and ‘द्वार’ as the ‘शुद्ध हिंदी’ forms. The best evaluation of this is:","options":["Correct, because examinations reward tatsam words, and children should learn to use them from an early age","Mistaken, because such everyday words are standard Hindi, and replacing them devalues her language","Partly correct: such words are fine in speech but should be replaced by tatsam forms in writing","Correct, because Sanskrit-based words are more precise and formal than everyday words of Persian origin"],"answer":1,"explanation":"‘किताब’ and ‘दरवाज़ा’ are part of standard Hindi in speech and writing. Treating them as errors narrows the child's language and sends the message that her natural Hindi is wrong.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1771","question":"A Class 1 child writing ‘दिन’ and ‘किताब’ puts the short-i sign (ि) to the right of the consonant it belongs to, in the order the sounds are heard. The rest of each word is correct. What is the most likely explanation?","options":["She has a visual-motor difficulty that makes her reverse marks around letters, so she should be screened for dyslexia at once","She cannot yet hear the short /i/ sound in these words and is only guessing where the vowel sign should go","She is confusing the short-i sign with the long-i sign (ी), which really is written to the right of the consonant","She is following the spoken order of sounds, which clashes with the script's convention for ‘ि’; this needs explicit teaching"],"answer":3,"explanation":"In speech /i/ comes after the consonant, but Devanagari writes ‘ि’ before it. A child who places it after is being logical about sound order; she hears the vowel and knows it is short, so she needs the visual convention pointed out and practised.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1772","question":"Decoding ‘कमल’ akshar by akshar, a Class 1 child says ‘क-म-ल… कमला?’ and does not recognise the word, although she knows the flower कमल well. What should the teacher do?","options":["Explain that every Hindi word ends in a consonant sound with no vowel after it, and drill this rule on lists of words","Model blending the akshars into a word she knows, so she learns to check her decoding against familiar spoken words","Send her back to the letter chart, since she has clearly not yet mastered the sounds of क, म and ल","Have her memorise common words as whole shapes, since decoding akshar by akshar misleads readers of Hindi"],"answer":1,"explanation":"Spoken Hindi often drops the inherent अ at the end of a word (कमल is said kamal), which the script does not show. Readers learn this by matching decoded strings to words they know; the ‘rule’ in the first option is false, and she already knows the letters.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1773","question":"Which feature of Devanagari makes the akshar a natural unit for early reading instruction in Hindi?","options":["Each akshar usually stands for a consonant with its vowel, a unit children hear easily, and spelling is fairly regular","Devanagari letters have no fixed sounds, so each akshar must be learnt as a separate picture without reference to sound","The headline (शिरोरेखा) joins all the letters of a word, so children must learn whole words before they meet any letters","Vowel sounds are not written at all in Devanagari, so each akshar on the page holds only a single consonant sound"],"answer":0,"explanation":"Devanagari is an alphasyllabary: an akshar is a syllable-sized unit (consonant plus vowel sign), and sound–symbol mapping is fairly regular, so children can learn akshars and blend them. Vowels are written, as matras or full letters.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1774","question":"Shreya, a Marathi-speaking child, joins a Hindi-medium Class 3. Within a week she reads Hindi passages aloud almost fluently but understands little of them. What best explains this?","options":["She has a specific comprehension disability that should be formally assessed before any further teaching","She reads too fast and should be told to slow down and point to each word as she reads aloud in class","Decoding transfers because both use Devanagari, but understanding needs Hindi words and grammar she is still acquiring","She is reading Hindi with a Marathi pronunciation, and these wrong sounds are blocking her understanding of the whole text"],"answer":2,"explanation":"Because Marathi and Hindi share the script, her decoding skill carries over at once, but comprehension depends on knowing the language. She needs oral Hindi and vocabulary support, not a disability label or slower reading.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1775","question":"Ramkali, fluent and expressive in Bundeli at home, says little in a Class 4 Hindi speaking test in which the teacher insists on ‘standard Hindi’, and is marked low. Which change would make the assessment more valid?","options":["Give her extra marks to make up for her disadvantage, since she comes from a rural home and is not to blame for it","Assess how she communicates ideas in tasks where she may use her own variety, and track standard Hindi separately","Excuse her from oral assessment until her standard Hindi is good enough to be assessed in a fair manner","Assess her only through written work, where differences of pronunciation and dialect do not show up at all"],"answer":1,"explanation":"A speaking assessment should capture the ability to express and organise ideas; forcing an unfamiliar variety measures dialect, not speaking skill. Growth in standard Hindi can be recorded separately without silencing her.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1776","question":"Consider these statements: I. A dialect such as Bhojpuri or Awadhi is a fully rule-governed language system. II. Standard Hindi owes its status mainly to social and historical factors, not to linguistic superiority. III. A child's home variety should be replaced as early as possible so that it does not interfere with standard Hindi. IV. The ability to move between a home variety and standard Hindi is a valuable skill. Which are correct?","options":["I and III only","II and IV only","I, II, III and IV","I, II and IV only"],"answer":3,"explanation":"All varieties are systematic, and a standard is a social choice, not a better language; so I, II and IV hold. Replacing the home variety (III) harms the child's confidence and loses a resource for learning.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1777","question":"To make Class 7 students sensitive to register, a Hindi teacher takes ‘पानी’, ‘जल’ and ‘नीर’. Which activity serves this aim best?","options":["Students find where each is used, at home, in a science book or a poem, and discuss why it fits there","Students learn the three words as exact synonyms and then write one sentence of their own using each","Students rank the three words from the most correct to the least correct form, with reasons for the order","Students look up the origin of each word in a dictionary and note which language each one came from"],"answer":0,"explanation":"Register is about which word suits which context: पानी in everyday talk, जल in formal or scientific writing, नीर in poetry. Seeing the words in use and discussing the fit builds this; treating them as exact synonyms or ranking them as ‘correct’ misses it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1778","question":"A Class 5 teacher in a Hindi-medium school has children write in a ‘गणित डायरी’ how they solved a problem and where they got stuck. From a language-across-the-curriculum view, the main value is that:","options":["it gives extra handwriting practice, for which the Hindi period has very little time left","it lets the teacher mark children's Hindi spelling at the same time as their mathematics","putting their reasoning into words clarifies children's thinking and shows the teacher how they reason","it removes the need for written maths tests, since the diary already shows every child's answers and working"],"answer":2,"explanation":"Writing to learn makes children organise and examine their own reasoning, and the teacher gains a window into it. Spelling, handwriting or replacing tests are not the purpose.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1779","question":"A Class 4 teacher uses a short tool to find whether each child can read akshars, words, a short paragraph or a story, then groups children by that level rather than by class for part of the day, re-testing every few weeks. This is the core idea of:","options":["ability tracking, in which weaker readers are placed permanently in a separate section of the class","Teaching at the Right Level, with short-term level-based groups that are regrouped often","norm-referenced testing, in which each child is ranked against the class average","mastery learning, in which no child moves on until the whole class passes a unit"],"answer":1,"explanation":"Teaching at the Right Level groups children by current reading level for focused instruction, reassesses them and moves them up quickly. Permanent tracking, ranking and whole-class mastery gates are different ideas.","difficulty":"hard","source":"KVS PRT · NVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1780","question":"A Class 2 teacher holds regular sessions of Hindi पहेलियाँ (riddles), in which children guess the answer from playful clues. These sessions mainly develop children's:","options":["memory, because riddles and their answers are learnt by heart and then recited","knowledge of grammar, since riddles are always phrased in complete and correct sentences","pronunciation, because riddles use difficult sounds that children must repeat aloud","ability to infer from clues and play with word meanings, a form of thinking in language"],"answer":3,"explanation":"Riddles make children hold several clues in mind, infer and notice double meanings, which builds reasoning through language and awareness of words. They are not mainly memory, grammar or pronunciation drills.","difficulty":"moderate","source":"CTET Paper 1 · state TETs"},
  {"id":"cdp-pedagogy-subjects-1781","question":"Class 6 students learning Hindi as R2 in a Kochi school collect Hindi words from railway signs, wrappers and posters and build a class wall chart. The main value of this activity is that:","options":["it shows Hindi as a language in real use around them and gives familiar, meaningful print to read","it can replace the textbook, which is far too hard for second-language learners at this early stage","it trains them in translation, since each word on the chart must carry its Malayalam meaning","it improves their handwriting, since they copy printed letters from many different fonts"],"answer":0,"explanation":"Environmental print links the new script to real contexts the children already know, so reading starts from meaningful, motivating material. It supplements rather than replaces the textbook.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1782","question":"Class 4 children write long Hindi stories with almost no पूर्ण विराम (।). Which approach is most likely to help?","options":["Give twenty unpunctuated sentences to correct every day for a week, with answers checked by the teacher","Teach the definitions of all the punctuation marks and have the children learn them by heart for a class test","Each child reads her story aloud to a partner, notices where a thought ends and she pauses, and marks it","Deduct a mark for every missing full stop so that children learn to take punctuation more seriously"],"answer":2,"explanation":"Punctuation marks units of meaning; hearing their own text aloud lets children notice where a thought ends and mark it in their real writing. Isolated drills and penalties rarely transfer.","difficulty":"hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1783","question":"In a Class 2 of 55 children, a teacher relies almost entirely on chorus reading of the Hindi textbook. What is the most serious limitation of this practice?","options":["It is noisy for the neighbouring classes and disturbs the work of the rest of the school","Choral work has no place at all in early literacy and should be dropped from the class","It tires children out, because reading aloud takes more effort than reading silently","It hides which children are decoding and which are only following others' voices"],"answer":3,"explanation":"In a chorus, children can echo stronger readers or recite from memory, so the teacher cannot see who actually reads. Some choral reading is useful, but used alone it masks individual difficulties.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1784","question":"A Class 3 child writes ‘वह ज़ोर से हंस रहा है’. What is the teacher's most useful response?","options":["Mark it wrong and have her copy the correct form ‘हँस’ ten times in her notebook","Show the pair हंस (swan) and हँस (laugh), say both aloud, and let her hear how the sign changes meaning","Ignore it, since chandrabindu and anusvara are fully interchangeable in all modern Hindi writing","Teach her the complete set of rules for using anusvara and chandrabindu before she writes any more"],"answer":1,"explanation":"Here the sign changes meaning (swan vs laugh), so a heard and meaningful contrast is the clearest lesson. Anusvara replaces chandrabindu only in some contexts (such as a matra above the headline), so they are not freely interchangeable.","difficulty":"very-hard","source":"CTET Paper 1 · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1785","question":"Which activity best builds morphological awareness among Class 5 Hindi learners?","options":["Building word families such as सफल → असफल, सफलता and noticing how each added part changes meaning","Memorising lists of prefixes (उपसर्ग) with their definitions and examples for a written test","Taking dictation of long and difficult words chosen from the textbook lessons of the term","Arranging lists of words in dictionary order as quickly as possible"],"answer":0,"explanation":"Morphological awareness is sensitivity to meaningful parts of words; building and comparing word families makes children notice how prefixes and suffixes change meaning. Memorised lists do not develop that sensitivity.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1786","question":"A Class 2 child who has been deaf from birth joins a Hindi-medium inclusive class. Which approach is most in line with current understanding and NEP 2020?","options":["Rely only on lip-reading and speech training, so that she learns to speak Hindi like her classmates","Seat her near the window for good light and teach her exactly as the hearing children are taught","Support her through Indian Sign Language as a first language, with written Hindi learnt alongside","Delay reading and writing until she has acquired enough spoken Hindi through her hearing aids"],"answer":2,"explanation":"A full first language (Indian Sign Language, which NEP 2020 asks to be standardised and used) gives her a base for thinking and for learning written Hindi. Relying only on speech or delaying literacy leaves her without full access to language.","difficulty":"hard","source":"CTET · KVS PRT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1787","question":"Class 7 students often write ‘उसने कहा की वह आएगा’. Which explanation and response is most accurate?","options":["It is a careless slip, and reminding students to check their spellings before they hand in work will solve it","‘कि’ and ‘की’ sound alike in quick speech; students need to notice their different jobs across many sentences","Students are confusing the tatsam and tadbhav forms of one word, which should be taught to them as pairs","‘की’ is simply the older spelling of ‘कि’, so students are using an outdated but still acceptable form"],"answer":1,"explanation":"‘कि’ is a conjunction introducing a clause; ‘की’ is the feminine possessive marker. Because they sound alike in connected speech, students must learn to tell them apart by function, which needs attention in context, not a general reminder.","difficulty":"very-hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1788","question":"During a Class 6 Hindi discussion in a Mumbai school, a student says, ‘मेरे को भी बोलना है।’ What is the best response?","options":["Let the talk flow, and later build awareness that ‘मुझे’ is expected in formal speech and writing, without faulting her","Stop her immediately and have her repeat the sentence with ‘मुझे’ before she is allowed to continue","Ignore it entirely, since in a speaking activity a teacher should never draw any attention to form, either now or later on","Ask the class to vote on whether ‘मेरे को’ or ‘मुझे’ is correct, so that they discover the rule for themselves"],"answer":0,"explanation":"‘मेरे को’ is common in colloquial Hindi; the aim is to keep the discussion going and later build awareness of the formal register. Interrupting silences her, voting does not settle usage, and ignoring form forever leaves a gap for formal writing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1789","question":"A Class 6 Hindi teacher collects anonymised sentences with agreement errors from students' compositions (‘लड़कियाँ खेल रहा है’), and the class works out together what is wrong and why. The main strength of this practice is that:","options":["students find out which classmates make the most errors and can offer them extra help","it covers the grammar syllabus much faster than working through the exercises given in the textbook","it removes the need for the teacher to give each student individual feedback","the rules discovered come from learners' own language, so they address their real errors"],"answer":3,"explanation":"Using learners' own errors makes grammar relevant and lets students reason out agreement rules they actually need. Anonymity protects them, so it is not about identifying weak students, and it does not replace individual feedback.","difficulty":"hard","source":"CTET Paper 2 · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1790","question":"Before reading a Hindi story aloud, a Class 1 teacher spends a few minutes on the cover picture: ‘चित्र में क्या हो रहा है? आगे क्या होगा?’ This mainly helps children to:","options":["learn the names of the letters printed on the page alongside the picture on the cover","memorise the story in advance so that they can later recite it without the text","build oral language and expectations about the story, which support making meaning","practise sitting quietly and paying attention before the actual reading starts"],"answer":2,"explanation":"Picture talk activates children's experience and language and sets up predictions, so they listen and later read for meaning. It is not about letter names or memorising the story.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1791","question":"Class 7 students claim that when two dice are rolled, a total of 12 and a total of 7 are equally likely, ‘because each is just one number’. Which activity best challenges this idea?","options":["Roll one die many times to show that every face comes up about equally often, then extend the result to two dice","List all 36 ordered outcomes in a 6 × 6 table and count how many give each total, then compare with pooled class rolls","Roll two dice ten times and see which total turns up more often, so that the evidence comes from the students","Tell them that 7 is the most likely total and ask them to remember this fact for any questions on dice that come in the final test"],"answer":1,"explanation":"Six of the 36 equally likely outcomes give 7, but only (6, 6) gives 12. Listing the sample space shows why, and a large pooled experiment confirms it; ten rolls are too few, and one die hides the issue.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1792","question":"A Class 5 child writes 48 × 52 = 24,960 and moves on. Which habit would most quickly have shown her that the answer cannot be right?","options":["Estimating first: about 50 × 50 = 2,500, so an answer near 25,000 is ten times too big","Checking that the answer is even, since both the numbers being multiplied are even","Checking that the answer is larger than both of the numbers that were multiplied","Copying the numbers again neatly in columns and seeing that each digit is in its place"],"answer":0,"explanation":"48 × 52 = 2,496, close to the estimate 2,500, so 24,960 is off by a factor of ten. The evenness and ‘bigger than both’ checks are both passed by the wrong answer, and recopying checks nothing.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1793","question":"Four children have 3, 7, 2 and 8 marbles. Before giving the formula for the mean, which activity best builds its meaning?","options":["Arrange the numbers in order and pick the middle value, which shows the typical amount each child has","Practise finding ‘total ÷ number of children’ for many such data sets until the steps become automatic","Build cube towers of 3, 7, 2 and 8 and move cubes from tall towers to short ones until all are equal","Find the number that appears most often, since the mean tells us the value that is most common"],"answer":2,"explanation":"Levelling the towers (each becomes 5) shows the mean as a fair share, which later explains why we add and divide. Picking the middle value is the median and the most common value is the mode.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1794","question":"For data on the favourite fruits of a Class 6 class (mango 12, banana 8, apple 5, guava 9), a student draws a line graph joining the four points. What does this choice most reveal?","options":["She should have chosen a pictograph instead, because all the numbers in the data are small","Her only mistake is that the vertical axis of the graph does not begin at zero as it should","Line graphs cannot show values above ten, so the scale she chose for the vertical axis is the real problem here","She has not grasped that a line implies change between ordered values, which separate fruits do not have"],"answer":3,"explanation":"Joining points suggests a continuous trend, as with temperature over time; fruits are separate categories with no order, so a bar graph fits. The axis and scale are side issues.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1795","question":"A Class 7 student insists that ‘π is exactly 22/7, because that is what we use in every sum’. Which response is most appropriate?","options":["Reassure her that 22/7 is accurate enough for school sums, and that the difference matters only in advanced science","Have her compare 22/7 = 3.1428… with π = 3.1415… and discuss 22/7 as a convenient approximation for calculation","Explain that π is really 3.14, and that 22/7 is simply the same value written as a fraction to make division easier","Have her measure and divide the circumference by the diameter of several round objects to discover the true ratio herself"],"answer":1,"explanation":"Comparing decimals shows directly that 22/7 and π differ from the third decimal place, so 22/7 is an approximation and π has no exact fraction form. Measuring round objects is tempting, but measurement error is far larger than that difference, so it cannot settle the question and may even seem to confirm 22/7.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1796","question":"A Class 6 student claims, ‘If a number is divisible by both 4 and 6, it must be divisible by 24.’ What is the best response?","options":["Agree, because 4 × 6 = 24, and being divisible by two numbers always means being divisible by their product as well","Show that 48 is divisible by 4, 6 and 24, which confirms that the claim holds for every such number","Ask her to test 12, then discuss why the product rule holds only when the two divisors have no common factor","Tell her that the rule works only for even numbers, which explains why it fails for some of them"],"answer":2,"explanation":"12 is divisible by 4 and 6 but not 24; the least common multiple of 4 and 6 is 12. Divisibility by two numbers implies divisibility by their product only when they are co-prime (such as 3 and 8). One confirming example proves nothing.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1797","question":"A Class 7 teacher lets students use calculators to write 1/7, 2/7, 3/7 and so on as decimals and look for patterns. What is the best justification for this?","options":["The calculator does the long divisions, so attention goes to the repeating cycle 142857 and why it appears","Calculators give the exact decimal value of every fraction, so students see the true answer every single time","Students who find long division hard need not learn it at all once calculators are allowed in class","The main gain is practice in keying numbers quickly and accurately into a calculator for later use"],"answer":0,"explanation":"Here the calculator frees students from tedious work so they can notice that every ‘sevenths’ decimal uses the same cycle 142857 and reason about remainders. Calculators truncate rather than give exact values, and division still has to be learnt.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1798","question":"In dynamic geometry software, student P places four points by eye to make a square and joins them; student Q builds a square using perpendicular lines and a circle for equal sides. When the teacher drags a vertex, what is the main learning point?","options":["Both figures stay squares, since the software automatically corrects any small inaccuracy in drawing","Q's figure keeps its properties under dragging as they were built in; P's only looked like a square","P's figure is better, since freehand placement develops a feel for shapes that construction does not","Dragging distorts both figures in exactly the same way, so dragging is of little use in judging any figure"],"answer":1,"explanation":"The drag test separates a figure that merely looks right from one defined by its properties. Seeing P's ‘square’ collapse pushes students from appearance-based to property-based thinking.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1799","question":"Ravi recites every multiplication table up to 10 perfectly, but to find 7 × 8 he starts from ‘seven ones are seven’ and recites up. What should the teacher build next?","options":["More daily recitation of the tables, so that he can reach any fact in the sequence more quickly","Timed flash-card drills in random order until he can answer each fact within three seconds","Permission to use a calculator for all facts above 5 × 5, since he already knows the tables","Links among facts, such as 7 × 8 = 5 × 8 + 2 × 8, so that facts can be reached out of sequence"],"answer":3,"explanation":"His facts are stored as a chant, not as connected knowledge. Derived-fact strategies use what he knows to reach any fact directly and build understanding; more chanting strengthens the sequence, and timed drills add pressure without meaning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1800","question":"Consider these statements about a mathematics laboratory in school: I. It is mainly a room equipped with costly instruments. II. Its activities can use low-cost material such as paper folding, geoboards and beads. III. Its activities help students form conjectures and test them. IV. At the secondary stage it removes the need for proof. Which are correct?","options":["I and II only","I, III and IV only","II and III only","II, III and IV only"],"answer":2,"explanation":"A maths lab is an approach to exploring and conjecturing with simple materials, not a costly room (I is wrong). Activities can suggest and check results, but they do not replace proof (IV is wrong).","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1801","question":"Class 4 children's estimates of the weight of a pumpkin range from 200 g to 50 kg. Which activity is most likely to improve their estimation?","options":["Let them lift benchmarks such as a 1 kg salt packet and a 500 g packet, and compare by hand before weighing","Teach them to convert grams into kilograms and back again, so that all their estimates use the right units","Give a small prize to the child whose guess comes closest each time, so that all the children try harder to estimate","Weigh every object on the scale straight away, so that children only work with exact values"],"answer":0,"explanation":"Good estimation rests on personal referents; handling a known 1 kg mass gives a reference to compare against. Unit conversion and prizes do not build a sense of weight, and weighing everything skips estimation entirely.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1802","question":"Class 7 students find that squares and regular hexagons tile a floor but regular pentagons do not. Which question best leads them towards the reason?","options":["Since a pentagon has an odd number of sides, can any shape with an odd number of sides tile a floor?","Are all the sides of the pentagon the same length as those of the hexagon and the square?","Is the regular pentagon a symmetrical shape, like the square and the regular hexagon?","What is each interior angle, and can copies of that angle meet at a point to make exactly 360°?"],"answer":3,"explanation":"A regular pentagon's angle is 108°, which does not divide 360°, so copies cannot fit around a point; 90° and 120° do. The odd-sides idea is a trap, since triangles tile, and symmetry or side length is not the issue.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1803","question":"A teacher gives Class 6 students straws of 3 cm, 4 cm and 9 cm and asks them to make a triangle. They cannot. The main purpose of the task is for students to:","options":["practise measuring straws accurately to the nearest millimetre with a ruler","discover that the two shorter sides together must be longer than the third","learn that a triangle can be made only from three straws of equal length","see that triangles cannot be made from straws of three different lengths"],"answer":1,"explanation":"3 + 4 = 7 is less than 9, so the short straws cannot meet; trying different sets leads to the triangle inequality. Triangles with unequal sides are common, so the other conclusions are false.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1804","question":"A shopkeeper asks Class 7 students which shoe size he should stock most. One student finds the mean of the sizes sold last month, 6.4, and recommends ‘size 6.4’. What is the best response?","options":["Accept it, since the mean is always the best single value to represent any set of data","Suggest using the range instead, since it shows how widely the sizes sold were spread","Point out that no shoe is sized 6.4; the mode, the size sold most often, answers his question","Suggest using the median instead, since it is not affected by a few unusually large or small sizes"],"answer":2,"explanation":"The question is which size is most in demand, which is the mode; a mean can give a value that does not exist in the data. Choosing an average means matching it to the question.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1805","question":"A Class 8 student says, ‘A price cannot rise by 150%, because 100% is the whole thing.’ What is the most accurate response?","options":["A part of a whole cannot exceed 100%, but a rise is compared with the base: ₹40 up 150% is ₹100","Agree, since a percentage is always some part of a whole and so can never be more than one hundred","Percentages above 100 occur only in sports figures and need not be considered in ordinary arithmetic","Say that 150% is simply another way of writing 1.5 and that this point settles the student's doubt"],"answer":0,"explanation":"‘100% is the whole’ holds for part-of-whole situations. A percentage change compares with the starting value: 150% of ₹40 is ₹60, so the new price is ₹100. Converting 150% to 1.5 does not address the confusion.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1806","question":"A Class 6 student evaluates 12 ÷ 3 × 2 as 2, explaining, ‘BODMAS says M comes before D.’ What is the best diagnosis?","options":["The student is right, since in the word BODMAS multiplication is written before division","The expression is ambiguous without brackets, so both 2 and 8 should be accepted","The student should have done 3 × 2 first, since the multiplication sign sits closer to the 3","Division and multiplication have equal priority and are done left to right, so the answer is 8"],"answer":3,"explanation":"(12 ÷ 3) × 2 = 8. The letter order in the mnemonic misleads students into ranking M above D; the convention is equal priority, worked left to right, which makes the expression unambiguous.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1807","question":"Which representation shows most clearly why 23 × 14 needs four partial products?","options":["A number line with fourteen jumps of 23, each labelled with the running total","A 23 by 14 rectangle split into 20 × 10, 20 × 4, 3 × 10 and 3 × 4 parts","The lattice method, with digits written in diagonal cells and added along diagonals","Writing 23 fourteen times in a column and adding them two at a time"],"answer":1,"explanation":"The area model shows 200 + 80 + 30 + 12 = 322: each part is one place-value product. Repeated addition and number-line jumps give the answer but hide the structure; the lattice gives the steps without their meaning.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1808","question":"A Class 5 child thinks an angle is ‘the pointed corner’ and cannot decide which of two clock positions shows the bigger angle. Which activity best builds the missing idea?","options":["Measuring many angles drawn on paper with a protractor and recording their sizes","Memorising the names acute, obtuse, right and reflex angle, with a neat drawing of each kind","Turning their bodies, opening scissors and moving clock hands to compare amounts of turn","Drawing many angles with long arms so that the size of each angle is easy to see"],"answer":2,"explanation":"The child lacks the idea of an angle as an amount of turn. Turning activities build it directly; protractor work and names assume it, and long arms feed the arm-length misconception.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1809","question":"A Class 6 child says the volume of a stone cannot be found ‘because a stone has no length, breadth and height’. What is the best response?","options":["Let her lower the stone into a measuring cylinder of water and see how much the level rises","Have her treat the stone as a cuboid, measure its longest edges and multiply the three","Have her weigh the stone, since weight and volume are the same thing for solid objects","Agree that the volume of an irregular object is not defined until much higher classes"],"answer":0,"explanation":"Volume is the space an object takes up; water displacement measures it directly, and the formula l × b × h is just one method for cuboids. Treating the stone as a cuboid gives only a rough figure, and weight is a different quantity.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1810","question":"A child is stuck on a word problem. The teacher asks, ‘What is 3 × 4? Good, 12. And what do we do with the 12 now? Add or subtract? Yes, subtract. So what is 20 − 12?’ The child gets the answer. Which description is most accurate?","options":["It is Socratic dialogue, which builds deep understanding through a chain of questions","It is scaffolding in the zone of proximal development, which will soon fade out on its own","It is focusing questioning, which brings the child's own reasoning into the open","It is funnelling: the teacher does the thinking, and the child only fills in small gaps"],"answer":3,"explanation":"Each question narrows the path until the child supplies only a trivial step, so the reasoning stays with the teacher. Focusing questions ask the child to explain what she notices and why; real scaffolding hands over thinking rather than taking it.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1811","question":"For 302 − 297, child A uses the column method, borrows across the zero and gets 15; child B says, ‘297 to 300 is 3, and 2 more is 5.’ What should the teacher take from this?","options":["Child A has followed the correct standard method and only needs more practice in borrowing across zeros","Child B chose a strategy that suits these numbers, showing stronger number sense than the column method","Child B's method is a shortcut that works only for easy numbers and should be discouraged","Both children should be taught to use only the column method so that answers are consistent"],"answer":1,"explanation":"Seeing that 302 and 297 are close and counting up (difference = 5) is efficient and shows number sense; the column method across zeros is error-prone here. Flexible strategy choice should be encouraged, not replaced by one method.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1812","question":"Finding the area of a leaf traced on squared paper, a Class 5 child counts every square the outline touches, even thin slivers, as a whole square. Which advice best fixes the method?","options":["Count only the squares that lie completely inside the outline, and leave out all the others","Measure the length and the breadth of the leaf and multiply them, as for a rectangle","Count squares more than half covered as whole ones and ignore those less than half covered","Use larger squares, so that fewer partial squares need to be counted along the edge"],"answer":2,"explanation":"Counting every partial square overestimates, and counting only full squares underestimates. The ‘more than half’ convention lets the over- and under-counts roughly balance; length × breadth suits only rectangles.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1813","question":"In the repeating pattern ▲ ■ ■ ▲ ■ ■ …, which answer and reasoning for the 20th shape is correct?","options":["■, because 20 leaves remainder 2 when divided by 3, and the 2nd shape of each unit is ■","▲, because 20 is an even number and the triangles come at the even positions","■, because the pattern has twice as many squares as triangles, so squares are likelier","▲, because 18 is a multiple of 3, so a new unit of the pattern begins at the 20th place"],"answer":0,"explanation":"The unit has 3 shapes; positions 19, 20, 21 are ▲, ■, ■ since 18 ends a unit. 20 = 3 × 6 + 2, so it is the 2nd shape, ■. Option C has the right shape but no valid reasoning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1814","question":"A Class 8 teacher asks, ‘About how many rotis are eaten in our school every day?’ Groups decide what to assume, estimate and compare answers. The main value of this task is that it:","options":["gives practice in multiplying large numbers quickly and accurately with no help","leads to an exact answer once the groups have surveyed every family in the school","checks whether students remember facts about nutrition learnt in science lessons","builds mathematical modelling: making assumptions, estimating and refining them"],"answer":3,"explanation":"Such Fermi problems have no single exact answer; their worth lies in choosing assumptions, estimating and judging how reasonable the result is, which is the modelling cycle.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1815","question":"Class 4 children measure the area of a tabletop by covering it with one-rupee coins, while one group uses bangles; the counts make little sense. What is the teacher's best follow-up?","options":["Ask every group to use the same coins, since the problem is only that the units differed","Discuss the gaps circles leave and find shapes, such as squares, that cover without gaps or overlaps","Ask them to measure the length and breadth of the table in centimetres instead of covering it","Give them bigger coins so that fewer coins are needed and the counting becomes easier"],"answer":1,"explanation":"A unit of area must tile the surface; circles leave gaps whatever their size, so even identical coins give a poor measure. Standardising alone does not fix this, and length and breadth skip the idea of covering.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1816","question":"Tossing a coin 10 times, a Class 7 child gets 7 heads and says the coin must be unfair. What is the best response?","options":["Pool all the class's tosses, hundreds in all, see what fraction are heads, and discuss small samples","Agree, since a fair coin always gives exactly 5 heads in 10 tosses and this coin did not","Ask her to toss the same coin 10 more times and decide from whichever result she gets","Tell her the chance of heads is exactly 1/2, so her result must have come from a mistake in counting the tosses"],"answer":0,"explanation":"Small samples vary a lot; 7 heads in 10 is quite common for a fair coin. Pooling many tosses shows the proportion settling near 1/2. Another 10 tosses is still a small sample.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1817","question":"A Class 6 child plots the point (3, 5) by going 5 across and 3 up. Which response best helps her see why the order matters?","options":["Treat it as a spatial-reasoning difficulty and give her extra practice in copying shapes on square grids","Teach the trick that x comes before y in the alphabet, so the first number is always x","A partner game of calling and marking points, where mismatches show why an agreed order is needed","Have her plot twenty more points from the textbook exercise until the method becomes a habit"],"answer":2,"explanation":"The order of coordinates is a convention, and its purpose shows when two people must locate the same point. The game makes the need for an agreement felt; a mnemonic or drill fixes the habit without the reason.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1818","question":"For a totally blind Class 4 child in an inclusive class, which tool is most suitable for doing arithmetic calculations?","options":["A large-print number chart placed close to her desk for easy reference","A talking calculator, so that she never needs to work through any steps","A Braille slate and stylus to copy sums down in the same layout as others","A Cranmer abacus, whose beads stay in place and can be read by touch"],"answer":3,"explanation":"The Cranmer abacus lets a blind learner set and read numbers by touch while working through the steps of a calculation. Large print helps low vision, not total blindness; a talking calculator skips the learning, and a slate is for writing.","difficulty":"moderate","source":"CTET · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1819","question":"A Class 7 teacher introduces negative numbers through Brahmagupta's rules, stated in terms of ‘fortunes’ and ‘debts’. The main value of this is that it:","options":["shows that the ancient rules were more accurate than the rules for integers taught in schools today","gives integers a meaningful context and presents mathematics as a human, historical activity","replaces the number line, which is no longer needed once the rules are known","is mainly meant to build national pride rather than any mathematical understanding"],"answer":1,"explanation":"Brahmagupta's 7th-century rules framed positive and negative numbers as fortunes and debts, a context that makes operations meaningful and shows mathematics as developed by people over time. It complements the number line rather than replacing it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1820","question":"A child works out 25 × 16 as 50 × 8 = 100 × 4 = 400. Which explanation correctly justifies the method?","options":["Doubling one factor and halving the other keeps the product, since (25 × 2) × (16 ÷ 2) = 25 × 16","It works only because 25 and 16 are both perfect squares, so it would fail for most other numbers","It works because multiplication is commutative, which means 25 × 16 is the same as 16 × 25","It works only when one of the factors ends in 5, which is what makes doubling it possible"],"answer":0,"explanation":"Multiplying one factor by 2 and dividing the other by 2 leaves the product unchanged, for any numbers. Being perfect squares or ending in 5 is irrelevant, and commutativity is true but does not explain the steps.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1821","question":"Class 3 children watch ants walking in a line to a sugar crystal, and most say the ants ‘can see the sugar from far away’. Which activity best tests this idea?","options":["Show a video of ants carrying food, so that children can watch how ants walk in a line to the food and back to the nest","Tell them that ants have poor eyesight and find food mainly by smell, and have them write this down in their notebooks","Wipe a finger across the ants' trail, watch what the ants do at the break, and discuss what they might be following","Count the ants in the line every five minutes and draw a bar graph showing how their number changes over time"],"answer":2,"explanation":"Breaking the trail and seeing the ants lose their way lets children gather evidence that the ants follow something on the ground (a scent), not something seen. Telling or watching a video gives no test, and counting ants does not address the idea.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1822","question":"Class 5 children want to find which of three seeds (cotton, winged drumstick and mango) travels farthest in the wind. Which plan is a fair test?","options":["Drop each seed from the same height in front of the same fan setting, measure the distance, and repeat several times","Let each child throw a seed by hand as far as possible and measure how far each seed lands from the starting line","Let three groups test one seed each outdoors, at whatever time of day suits each group, and compare their distances","Drop each seed once from the classroom window and record which one lands farthest from the wall of the building"],"answer":0,"explanation":"Only the kind of seed should change; height and wind must stay the same, and repeating trials allows for chance. Throwing adds force, outdoor tests at different times vary the wind, and a single trial is unreliable.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1823","question":"For the theme on waste, Class 5 children weigh and sort the school's dry and wet waste every day for a week and present suggestions to the principal. The strongest reason this beats a lecture on the 3Rs is that:","options":["it keeps children busy outside the classroom, which reduces noise and indiscipline during the EVS period","it covers the whole waste chapter faster than reading and discussing the textbook in the classroom","children handle waste with their hands, which is the main skill that EVS aims to build at this stage","children collect their own evidence on a real problem and act on it, linking knowledge to action"],"answer":3,"explanation":"Gathering data on their own school's waste and proposing changes makes the problem real and connects understanding with responsible action, a core aim of EVS. Covering the syllabus or keeping children busy is not the point.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1824","question":"To show how a bird's beak suits its food, a teacher has children pick up grains, water and ‘worms’ (rubber bands) using tweezers, spoons and clothes pegs. After the activity, what is it most important for the teacher to do?","options":["Award marks to the fastest group, since speed shows which children best understood the beak shapes","Discuss how the model differs from real birds, which also use their tongue, neck and behaviour to feed","Move straight on to the next chapter, since the activity has already made the point clear to children","Ask children to memorise the names of birds with each beak type, so that they can answer test questions"],"answer":1,"explanation":"Every model is simplified; without discussing its limits, children may think beaks are rigid tools working alone. Drawing out the comparison turns a game into understanding.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1825","question":"In the NCF for School Education 2023, the curricular area for Grades 3 to 5 that continues the integrated approach of EVS is called:","options":["The World Around Us","Science and Social Life","Our Environment and Science","Integrated General Studies"],"answer":0,"explanation":"NCF-SE 2023 names ‘The World Around Us’ as the integrated curricular area for the Preparatory Stage (Grades 3–5), drawing on science, social science and environmental education.","difficulty":"moderate","source":"CTET · KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-1826","question":"On a morning walk, Class 4 children say: P. ‘The ground near the tap is wet.’ Q. ‘Someone must have left the tap open.’ R. ‘There are a dog's footprints in the mud.’ S. ‘The dog came here to drink water.’ Which of these are inferences rather than observations?","options":["P and R","Q and R","Q and S","P, Q and S"],"answer":2,"explanation":"P and R report what can be seen directly; Q and S go beyond what is seen to explain it, so they are inferences that might be wrong (rain, or a dog passing by). Separating the two is a key EVS process skill.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1827","question":"A Class 3 child says an ‘empty’ bottle has nothing in it. Which activity best helps her rethink this?","options":["Show the textbook picture of air drawn inside a bottle and ask her to colour the air in it carefully","Push the bottle mouth-down into a bucket of water, then tilt it and watch the bubbles escape","Tell her that air is everywhere even though we cannot see it, and repeat this every day","Weigh the empty bottle on a kitchen scale to show that it weighs more than nothing at all"],"answer":1,"explanation":"Water cannot fill the inverted bottle until bubbles escape, which shows something was taking up the space. A kitchen scale cannot detect the air, and telling or colouring gives no evidence.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1828","question":"Looking at a globe, a Class 5 child asks, ‘Why don't people at the bottom fall off?’ Which response best addresses the idea behind the question?","options":["Explain that people in those places feel a little lighter, which is why they do not notice being upside down","Turn the globe so that India is at the bottom, to show that no place on earth is really at the bottom","Tell the child that gravity holds the people at the bottom on to the earth, and then move on with the lesson","Stick small figures all over the globe and discuss that ‘down’ for everyone means towards the earth's centre"],"answer":3,"explanation":"The question assumes one fixed ‘down’ for the whole universe. Showing figures standing everywhere, with ‘down’ always towards the centre, replaces that idea; turning the globe helps but does not explain ‘down’, and naming gravity explains nothing.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1829","question":"Class 5 children ask what would happen if all the frogs near a paddy field were caught for sale. Which line of thinking should the teacher encourage?","options":["Tracing links both ways: more insects that frogs eat, less food for frog-eating snakes and birds, harm to the crop","Concluding that nothing much would change, since frogs are small animals that do not eat the paddy crop","Concluding that only the snakes would be affected, since frogs are food for snakes and for no other animal","Memorising a food chain from the textbook that includes frogs, so that such questions can be answered well in the exam"],"answer":0,"explanation":"Removing one organism affects both what it eats and what eats it, and these effects spread through the web, here to insect pests and the crop. Single-link thinking misses the system.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1830","question":"To assess Class 4 children's ‘concern for animals’, a teacher sets the written question, ‘Should we be kind to stray dogs? Give two reasons.’ What is the main problem with this?","options":["The question is too difficult for Class 4, since it demands two separate and well-argued reasons from each child","Attitudes cannot be assessed at all, so they should be kept out of EVS records altogether","Children tend to write the expected answer, so observing how they actually treat animals is more valid","The question should have been set as multiple choice, so that the marking is fully objective"],"answer":2,"explanation":"Written questions on values invite the ‘right’ answer and say little about real attitudes. Observations of behaviour over time (on walks, with class pets, during discussions) are the valid evidence.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1831","question":"A Class 3 teacher teaches ‘evaporation, condensation and precipitation’ with a printed cycle diagram that children must label. Which criticism is most in line with the NCERT EVS approach?","options":["The diagram should be replaced by a video, since moving pictures make the whole cycle easier to remember for tests","Abstract terms come before children have experienced and talked about the processes, such as wet clothes drying","Water is not part of the EVS syllabus in Class 3, so this topic should be left for later classes","The terms are correct, but children should also learn their written definitions by heart for revision"],"answer":1,"explanation":"Primary EVS builds from experience and the child's own words; technical terms and formal diagrams before that are abstract labels without meaning. Water is in fact a recurring EVS theme from Class 3.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1832","question":"Class 4 children count their breaths per minute before and after running. After running, counts range from 25 to 45, and one child says, ‘Mine must be wrong, because it isn't the same as Priya's.’ What is the best response?","options":["Ask everyone to count again and again until all the counts in the class match each other","Take the class average as the correct value and change each child's sheet so that it matches the average","Discard the highest and the lowest counts, since these are probably counting errors","Discuss that bodies differ, so counts vary; what matters is that every child's count went up"],"answer":3,"explanation":"Natural variation is real data, not error. The pattern that matters is the rise in every child's breathing rate after exercise; forcing counts to agree or deleting extremes teaches children to distrust honest observation.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1833","question":"A Class 4 child says that a black cat crossing the road brings bad luck, and several others agree. Which response best fits the aims of EVS?","options":["Ask where they heard it and how they could check it, e.g. noting what happens on days a cat crosses, without mocking","Explain the scientific facts about cats, and ask the children to tell their families at home that the belief is wrong","Avoid the topic, since beliefs from home lie outside the scope of EVS and may upset some parents","Leave the belief unchallenged in class, but present the scientific view separately in the next lesson"],"answer":0,"explanation":"EVS aims to build the habit of asking for evidence while respecting children's homes. Inviting them to think about how to check the claim does this; telling them to correct their families sets school against home.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1834","question":"Class 4 children compare how much water sand, clay and garden soil hold, by pouring water through each in a funnel and measuring what drips out. What must be kept the same in each trial?","options":["Only the amount of water poured, since the soils themselves are meant to be different","The type of soil used in each funnel, so that the results can be compared fairly","The amount of soil, the amount of water and the same kind of funnel and filter","Only the time of day at which each trial is done, so that the room temperature is equal"],"answer":2,"explanation":"Soil type is what is being changed; everything else that could affect the result, the quantity of soil, the water poured and the funnel and filter, must be the same. Keeping only one factor fixed leaves the test unfair.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1835","question":"With eyes closed and noses pinched, many children cannot tell small pieces of apple from raw potato. The activity mainly shows that:","options":["the tongue cannot detect any taste at all when the eyes are kept closed","what we call flavour depends largely on smell working along with taste","apple and potato contain the same substances, so they taste the same","the tongue has separate zones, and pinching the nose blocks the sweet zone"],"answer":1,"explanation":"Much of what we experience as flavour comes from smell; blocking the nose leaves only basic tastes and texture. The ‘tongue zones’ map is a myth.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1836","question":"A Class 5 child insists that bats are birds ‘because they fly’. Which approach best helps her?","options":["Tell her that bats are mammals and ask her to learn the full definition of a mammal by heart for the test","Point out that some birds, such as the ostrich, cannot fly, so flying is not a good test","Ask her to list all animals that fly, including insects, and to group them by flying alone","Compare features such as fur or feathers and milk or eggs, and discuss which features decide the group"],"answer":3,"explanation":"Grouping depends on a set of shared features, not one; comparing them shows why bats are with mammals. The ostrich example shows flight is not needed to be a bird, but not why bats are not birds.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1837","question":"Class 4 children adopt one tree and, over several weeks, record every living thing they find on or around it. This activity is best suited to develop:","options":["sustained observation and the idea of a tree as a home and food source for many living things","the ability to draw a tree accurately, with all of its parts and branches clearly and neatly labelled","memory for the scientific names of the insects and birds that live on different trees","speed in collecting leaves and bark samples to add to the class herbarium collection"],"answer":0,"explanation":"Repeated observation of one tree reveals birds, insects, lichens and more, and shows interdependence in a habitat. Drawing, naming or collecting are not the main purpose.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1838","question":"Many Class 5 children in a city school say water ‘comes from the tap’. Which activity best extends their thinking?","options":["Show a chart of the water cycle and explain evaporation, condensation and rainfall to them in detail","Ask them to list all the uses of water at home and record them neatly in a table","Trace back from the tap to the tank, pipes, treatment plant and river or lake, with a visit or a map","Give them a reading passage about the rivers of India and set questions on it for homework"],"answer":2,"explanation":"Following the actual route of their water links the familiar tap to sources and systems they cannot see, which builds on their experience. A general water-cycle chart or a reading on rivers does not connect to the tap.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1839","question":"After an EVS chapter about a visually challenged child, a teacher has children walk blindfolded around the school for five minutes. Which follow-up makes the activity most meaningful?","options":["Ask them to describe how difficult it was, so that they understand how hard life must be for all blind people","Discuss what helped or blocked them, then audit the school for access and meet people about their abilities","Repeat the activity every week, so that children become skilled at moving about with their eyes covered","Have them write an essay on ‘If I were blind’ in the language period as a piece of creative writing"],"answer":1,"explanation":"A short simulation can leave only fear and pity (a deficit view). Turning it towards barriers in the environment and the abilities of visually challenged people shifts the focus to access and respect.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1840","question":"Class 4 children say all insects are harmful and should be killed. Which response is most effective?","options":["Agree in the case of mosquitoes and houseflies, and move on, since the rest is beyond the syllabus for Class 4","Tell them that only a few insects bite, so most insects are neither harmful nor useful to us","Ask them to memorise a list of useful insects and the uses of each one for the unit test","Have them find out what bees, silkworms, ladybirds and dung beetles do, and imagine life without them"],"answer":3,"explanation":"Finding out the roles of pollinators, silk producers, pest-eaters and decomposers gives children evidence that challenges the generalisation and builds an idea of interdependence. A memorised list does not change their view.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1841","question":"After a day of heavy rain in Jaisalmer, a Class 5 child says, ‘So Rajasthan is not a dry place after all.’ Which response best addresses her reasoning?","options":["Compare rainfall records over many years, showing that one rainy day does not change a long-term pattern","Agree with her, since the heavy rain proves that the textbook was wrong about the climate of that whole region","Explain that it never rains in deserts, so the news report she heard must have been a mistake","Ask her to read the textbook chapter on deserts again and to underline the important points"],"answer":0,"explanation":"Her error is judging climate (a long-term pattern) from one weather event. Records over years make the difference clear; saying deserts never get rain is itself false.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1842","question":"Facing her friend across a table, a Class 4 child gives directions on a map: ‘From the gate, turn right to the well.’ Her friend, holding the map the other way round, goes the wrong way. What should the teacher help children build?","options":["Memory for the four cardinal directions, recited daily in a chant until every child knows them by heart","Taking another's viewpoint, and using landmarks or fixed directions (north, east), not just ‘left’ and ‘right’","The habit of always holding maps with the written labels upright, whichever way one happens to be facing at the time","The skill of drawing larger maps with brighter colours, so that routes are easier to follow"],"answer":1,"explanation":"‘Left’ and ‘right’ depend on which way one faces; giving directions others can follow needs perspective-taking and fixed references. Holding labels upright ignores the reader's real orientation.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1843","question":"A Class 5 child classifies the potato as a root ‘because it grows underground’. Which approach is best?","options":["Tell her that the potato is really a stem and ask her to memorise it along with other such examples","Agree with her, since all the parts of a plant that grow underground are its roots","Let her sprout the ‘eyes’ (buds) of a potato, compare with a carrot, and discuss what buds suggest","Show a labelled diagram of a plant and ask her to copy it neatly into her notebook"],"answer":2,"explanation":"Potato eyes are buds, which grow on stems; sprouting them gives evidence that the potato is an underground stem, unlike the carrot, a root. Growing underground is not what makes a part a root.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1844","question":"Class 5 children join a bird count, recording the birds they see near school every week and sending the data to a nationwide project. The greatest value of this is that:","options":["they learn the names of all the birds of India for the inter-school quiz held every winter","it replaces textbook reading, which children find dull at this stage","the birds near the school will be protected because they have been counted","they take part in real science, adding data and seeing patterns such as winter visitors"],"answer":3,"explanation":"Contributing to a citizen-science project gives children authentic observation and recording, a sense that their data matters, and patterns such as seasonal migration they can see for themselves.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1845","question":"Children in a city school say they see only a few stars at night, while their cousins in a village see many. What is the best use of this observation?","options":["Investigate why together, comparing dark and lit spots, and discuss how artificial light hides faint stars","Explain that there are far fewer stars in the sky above cities than there are above villages and forests","Tell them that in cities the stars can be seen clearly only during the cold and dry winter months of the year","Ask them to memorise the names and shapes of the main constellations instead"],"answer":0,"explanation":"Children's own observations are a starting point for inquiry; comparing locations leads to the idea of light pollution. The same stars are above both places, so the second option is false.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1846","question":"For an EVS model, a teacher asks every child to buy chart paper, sketch pens and thermocol. Several children come empty-handed and are scolded. What is the best change?","options":["Exempt the poorer children from the project so that they are not embarrassed in class","Plan with waste and local materials (cartons, clay, leaves) shared in groups, so all can take part","Let each group share one set of bought materials while keeping the same model design","Ask all the parents to pay a fixed amount into a class fund from which the materials are then bought"],"answer":1,"explanation":"Using freely available materials removes the cost barrier and the stigma, and is closer to the spirit of EVS. Exemption excludes children, and pooled buying or fees still burden poorer families.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1847","question":"For the theme on work, a teacher's homework asks children to write their parents' monthly income and the value of their house. What is the most serious problem?","options":["The amounts are too large for children of this age to write correctly in figures","Many parents may not know the exact figures, so the answers will not be accurate","It intrudes on family privacy and can shame poorer children; questions about the work itself serve the aim","Family income is not part of the EVS syllabus at this stage, so it cannot be discussed in the classroom at all"],"answer":2,"explanation":"The theme is about kinds of work and how people do it; asking for income and property exposes families and invites comparison and shame. Sensitive framing is part of good EVS planning.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1848","question":"Many Class 3 children say ‘the fox is cunning and the crow is foolish’, citing stories. What is the best response?","options":["Explain that animals act on instinct, so words like cunning and foolish describe people rather than animals","Read them other fables in which the fox is foolish and the crow is clever, so that they hear both sides","Ask each child to draw the fox and the crow and write beneath each picture the trait it shows in the story","Enjoy the fables as stories, then compare them with what real foxes and crows are observed to do"],"answer":3,"explanation":"The EVS task is to help children separate story traits from observed behaviour while still valuing fables as stories; real crows, for instance, solve problems well. Reading counter-fables is tempting, but it swaps one story stereotype for another instead of turning children to evidence.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1849","question":"A Class 4 child says water in a matka stays cool ‘because clay is a cold material’. Which activity best helps?","options":["Wrap one bottle in a wet cloth and one in a dry cloth, keep both in a breeze, and compare after an hour","Explain the term ‘evaporation’ in detail and have children copy its definition into their notebooks for revision","Have children touch a clay pot and a steel pot to find out which material feels colder to the hand","Ask them to draw a matka and label its parts, then write two lines about its uses at home"],"answer":0,"explanation":"The wet-cloth bottle cools because water evaporating from the surface takes away heat, which is what the porous matka does. Touching pots tests the child's idea on her own terms and may simply confirm it.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1850","question":"A Class 3 child says fish do not need air because they live in water. Which starting point is best?","options":["Explain that fish breathe by taking the oxygen that is part of each water molecule (H₂O) through their gills","Watch a fish in a bowl, noting its moving gill covers, and ask why fish gulp at the surface in stale water","Show her a video of a whale rising to breathe at the surface, to show that water animals also need air","Tell her that fish breathe through gills and ask her to label the gills on a diagram of a fish in her notebook"],"answer":1,"explanation":"Observing gill movement and surface gulping in stale water lets the child see that fish take something from the water, leading to the idea of air dissolved in it. The whale video is tempting, but a whale is a mammal with lungs, so it says nothing about how fish get air; and fish use dissolved oxygen, not the oxygen bound in H₂O.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1851","question":"During a Class 10 lesson, a student dismisses evolution as ‘just a theory, not a proven fact’. Which response best addresses the misunderstanding?","options":["Agree that it is only a theory, and say that it will become a law once it has been fully proved by experiments","Explain that in science a theory is a well-tested explanation backed by many lines of evidence, not a guess","Avoid the point, since students are free to believe whatever they like about the origin of living things","Tell the student that every scientist accepts evolution, so the student should accept it on their authority"],"answer":1,"explanation":"The objection mixes the everyday sense of ‘theory’ (a hunch) with the scientific sense (a well-substantiated explanation). Theories do not turn into laws; laws describe patterns, theories explain them. Appeal to authority is not the scientific way to settle it.","difficulty":"very-hard","source":"KVS TGT · NVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1852","question":"After pushing the plunger of a sealed syringe of air, Class 9 students draw the particles inside as smaller circles than before. What is the best teaching response?","options":["Praise the drawing, since squeezing a gas really does make each of its particles shrink a little","Tell them to draw the same number of particles, which is the only problem in the drawing","Have them repeat the activity with water, which they will find compresses just as easily","Ask what is between the particles and whether the particles or the gaps between them change"],"answer":3,"explanation":"Compression reduces the empty space between particles; the particles themselves do not shrink. Students often transfer bulk changes (smaller volume) to the particles, so questioning what changes helps them refine the model.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1853","question":"Asked to predict, most Class 8 students say steel wool will weigh less after burning, ‘as burnt things become ash’. When it is burnt on a balance, the mass goes up. How should the teacher use this result?","options":["As a puzzle to explain: the iron has combined with oxygen from the air, so the product has more mass","As a sign that the balance was faulty, since burning always makes a substance lighter than before","As an exception to note quickly, since steel wool behaves unusually and is rarely burnt in daily life","As proof that mass is not conserved in chemical reactions, which the textbook should have said clearly"],"answer":0,"explanation":"The surprise creates cognitive conflict: the gain comes from oxygen joining the iron, so mass is conserved once all reactants are counted. Wood seems to lose mass because its products escape as gases.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1854","question":"A Class 7 teacher has students make turmeric paper and test soap solution, lemon juice and water with it. The soap solution turns the paper red. The main value of this activity is that:","options":["it replaces the need to learn about litmus and other indicators used in laboratories","it proves that turmeric is the most accurate indicator available for any substance","it uses everyday materials to show how indicators reveal bases, linking lab ideas to home","it shows that all yellow substances turn red when they are mixed with any kitchen liquid at all"],"answer":2,"explanation":"Turmeric turns red in a basic solution such as soap; making indicators from kitchen materials makes the concept concrete and cheap. It complements, not replaces, standard indicators, and does not show turmeric is the best one.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1855","question":"A Class 8 student says that whenever she has a cold, her family gives her an antibiotic ‘to kill the germs’. In a lesson on microorganisms, what is the most useful response?","options":["Explain that colds are mostly viral, antibiotics act only on bacteria, and needless use breeds resistance","Explain that antibiotics are best kept for severe colds, such as those with a high fever lasting several days","Explain that antibiotics do work on colds but must be taken for the full course so that the germs do not return","Suggest that she ask her doctor about a vaccine for the common cold instead, since prevention is better than cure"],"answer":0,"explanation":"Colds are caused mainly by viruses, which antibiotics do not affect, and needless use breeds resistant bacteria. The 'full course' advice is tempting because it is sound for bacterial infections, but here it endorses using antibiotics on a viral illness; there is also no vaccine for the common cold.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1856","question":"After a lesson on food chains, a Class 10 student writes, ‘Energy goes round and round in an ecosystem, just like water and carbon.’ Which statement should the teacher help the student reach?","options":["Energy and matter both cycle, but energy cycles much more slowly than carbon","Energy is used up completely at each level, so none is left for decomposers","Matter cycles, but energy flows one way, entering as light and leaving as heat","Energy cycles only in water ecosystems, where it is carried by the water cycle"],"answer":2,"explanation":"Nutrients such as carbon are recycled by decomposers, but energy enters as sunlight, passes along food chains with large losses as heat at every step, and is not reused. Decomposers do get energy from dead matter, so the second option is wrong.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1857","question":"Class 9 students plot distance against time for a toy car and join every point with short straight lines, giving a zig-zag graph. What should the teacher help them understand?","options":["The zig-zag is the most honest graph possible, because it passes through each and every measured point","They should have used a bar graph, since each reading is a separate measurement taken at a separate time","Graphs should be drawn freehand without a ruler, so that they look smoother and closer to real motion","Every reading has some error, so a smooth line of best fit shows the trend better than joining the dots"],"answer":3,"explanation":"Measured points scatter because of measurement error; a best-fit line or curve shows the underlying relation and lets students judge outliers. Joining every dot treats each error as real motion.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1858","question":"In a Class 8 school, every student's practical record has an identical ‘Aim, Apparatus, Procedure, Result’ copied from a guide, with no data of their own. Which change best improves learning from practicals?","options":["Check the records more strictly for neatness and completeness, and deduct marks for any copied page","Have students record their own data and write, in their own words, what they found and why","Give students a printed format for every experiment so that the writing is quicker and more uniform","Drop written records entirely and assess practicals only through the viva held at the end of the year"],"answer":1,"explanation":"A practical record is meant to capture what students actually observed and how they interpreted it. Recording their own data and reasoning makes the write-up part of thinking; stricter checking or fixed formats keep it a copying exercise.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1859","question":"A teacher asks Class 8 groups to answer ‘Does salt make ice melt faster?’ as a claim, the evidence for it and the reasoning linking the two. Which group's answer best fits this format?","options":["‘Salt melts ice faster. Everyone knows that salt is spread on icy roads in cold countries to clear them in winter.’","‘Salt makes ice melt. We think this is because salt is a very strong and hot chemical.’","‘Salt makes ice melt faster: salted cubes melted in 6 minutes, plain in 11; salt lowers the melting point.’","‘Our salted ice cubes melted in 6 minutes and the plain ones in 11 minutes.’"],"answer":2,"explanation":"Claim–evidence–reasoning needs all three: a claim, the group's own data and a scientific reason linking them. The others give common knowledge instead of evidence, a wrong reason without data, or data with no claim or reasoning.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1860","question":"While teaching about plate movements, a teacher tells how Wegener's idea of drifting continents was largely rejected for decades and accepted only after new evidence from the ocean floor. The main purpose of telling this story is to show that:","options":["scientific knowledge can change with new evidence, and acceptance also depends on explaining how something works","scientists usually reject new ideas only out of jealousy, so new ideas should be trusted more than old ones","Wegener's idea was wrong when he proposed it and became right only later because the continents changed","history of science is useful mainly to make lessons interesting, and has little to do with understanding science"],"answer":0,"explanation":"Continental drift lacked a convincing mechanism until sea-floor spreading and plate tectonics supplied one. The story shows science as tentative and evidence-driven, without suggesting that new ideas are always right.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1861","question":"To find out what rusting needs, a Class 7 teacher sets up three tubes with iron nails: one in tap water, one in boiled water covered with a layer of oil, and one in dry air over a drying agent. What is the job of the oil layer?","options":["It keeps the boiled water warm, so that the nail in that tube stays hot through the whole test period","It stops air from dissolving back into the boiled water, so that nail meets water but no air","It coats the nail, showing that oil and grease protect iron objects from rusting","It makes the boiled water heavier so that the nail stays completely under the water"],"answer":1,"explanation":"Boiling drives out dissolved air, and the oil keeps air out afterwards, so that tube tests water without air; the dry tube tests air without water. Only the nail with both rusts. The oil is not meant to coat the nail.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1862","question":"Germinating seeds kept in a thermos flask with a thermometer warm up over a day. A teacher sets up a second flask with boiled (dead) seeds. Why is the second flask needed?","options":["To show that boiled seeds germinate more slowly than raw seeds kept in exactly the same conditions","To provide a supply of warm seeds in case the first flask cools during the night","To give the class a second reading, so that the average of the two can be taken","To show that the rise in temperature comes from living seeds and not from the flask itself"],"answer":3,"explanation":"The control has everything the same except that the seeds are dead. If only the living seeds warm up, the heat must come from their respiration. Boiled seeds do not germinate at all.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1863","question":"In a lesson on materials, Class 8 students say that ‘chemical-free’ products are always safe and that anything with ‘chemicals’ is harmful. Which response is most accurate?","options":["Agree, since natural substances are safe in any amount, while man-made chemicals are always toxic to the body","Agree only partly, since some chemicals are safe in food but all of them are harmful in cosmetics","Avoid the point, because advertising and products are outside the scope of a science lesson","Show that everything, even water and salt, is made of chemicals, and harm depends on substance and dose"],"answer":3,"explanation":"All matter is chemical; whether something is harmful depends on what it is and how much of it is taken. ‘Chemical-free’ is a marketing phrase, and natural substances can also be toxic.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1864","question":"A teacher gives Class 8 students the question ‘How does the length of a pendulum affect its swing time?’ and a step-by-step procedure, but not the expected result. In Banchi and Bell's levels of inquiry, this is:","options":["confirmation inquiry, since the students follow a procedure to check a known result","structured inquiry, since the question and procedure are given but not the result","guided inquiry, since the teacher guides students by giving them the research question","open inquiry, since the students collect their own data and draw their own conclusion"],"answer":1,"explanation":"Confirmation gives the result too; structured gives question and procedure; guided gives only the question, with students designing the method; open leaves the question to students. Here the method is supplied, so it is structured.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1865","question":"To help Class 7 students see that digestion begins in the mouth, which activity is most suitable?","options":["Have students chew a piece of plain roti for a few minutes and notice that it begins to taste sweet","Show a labelled chart of the digestive system and trace the path of food from mouth to stomach","Ask students to memorise the names of the digestive juices and the organs that make each of them","Have students count how many times they chew each bite during lunch and record the count in a table"],"answer":0,"explanation":"Saliva begins breaking down starch into sugar, so roti chewed for long starts to taste sweet: direct evidence that digestion starts in the mouth. A chart or list only states the fact.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1866","question":"Class 7 students say we ‘suck’ juice up a straw. The teacher fits a straw through a hole in an airtight bottle lid, sealing the gap, and students find they cannot drink. What should this lead them to?","options":["That the straw was too narrow, so the juice could not travel up it with enough speed","That sucking works only with open bottles, because closed bottles hold the juice inside them more tightly","That air pushing on the juice's surface drives it up when pressure inside the straw is lowered","That the bottle had too little juice in it, so the straw could not reach the liquid properly"],"answer":2,"explanation":"Drinking through a straw lowers the pressure inside the straw; atmospheric pressure on the liquid's surface pushes it up. Sealing the bottle removes that outside air push, so the drink does not rise.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1867","question":"A Class 9 teacher shows a conceptual multiple-choice question, has students vote individually, then asks them to convince a neighbour and vote again. Correct answers rise from 40% to 75%. This technique is known as:","options":["the jigsaw method, since each student holds one part of the answer and must teach it to the others","peer instruction, in which discussion of a conceptual question between votes builds understanding","the think-aloud protocol, since students say aloud their thinking while answering the question","the Socratic method, since the teacher leads every student to the answer by careful questioning"],"answer":1,"explanation":"Eric Mazur's peer instruction uses conceptual questions, individual votes, peer discussion and revotes; students who have just understood often explain well to classmates. The teacher here does not lead each student by questions.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1868","question":"A Class 8 student classifies a mushroom as a plant ‘because it grows from the ground and doesn't move’. What is the best response?","options":["Compare it with a green plant on colour and how it gets food, then discuss why mushrooms are fungi","Agree for now, since mushrooms are simple plants and the details of fungi are taught only in higher classes","Tell her that mushrooms are animals because they cannot make their own food, unlike green plants","Ask her to learn the textbook list of fungi, so that she can recognise them in the examination"],"answer":0,"explanation":"Fungi lack chlorophyll and absorb food from dead matter, unlike plants; comparing features gives her reasons for the grouping. They are not animals either, and not moving is not a defining feature.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1869","question":"Many Class 7 students believe blood in veins is blue and turns red only when it meets air. Which evidence best challenges this?","options":["The veins on our wrists look blue through the skin, which shows that the blood inside them is blue","A diagram in which veins are coloured blue and arteries red, as in most textbooks","Blood drawn from a vein into a closed syringe is already dark red, before any air reaches it","Blood that flows from a small cut turns darker after a while as it is exposed to air"],"answer":2,"explanation":"Blood collected from a vein into a sealed tube is already dark red, so it is never blue; veins look bluish because of how skin absorbs and scatters light. Textbook colour codes add to the misconception.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1870","question":"A Class 8 student says louder sounds travel faster than soft ones. Which everyday observation best challenges this?","options":["We hear a loud sound from farther away than a soft sound from the same place","Thunder is heard after we see the lightning, which shows that light travels much faster than sound","A loud shout makes the window glass shake, which a soft voice does not do","At a distance, the loud drums and soft flutes of a band reach us in step with each other"],"answer":3,"explanation":"If loudness affected speed, a distant band's loud and soft notes would arrive out of step; they do not. Hearing a loud sound farther away concerns energy, not speed, and thunder compares light with sound.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1871","question":"Class 8 students light an LED with a ‘potato battery’ of copper and zinc strips and say, ‘The potato has electricity inside it.’ How should the teacher refine this?","options":["The energy comes from a chemical reaction at the metal strips; the potato's juice lets charges move between them","Agree, since potatoes store electricity from the sunlight that the plant absorbed while it grew in the field","Say the LED glowed only because of static charge on the students' hands while they handled the strips","Agree, but add that potatoes store far less electricity than lemons, which is why lemon batteries are used more often"],"answer":0,"explanation":"The zinc reacts chemically, and the potato's juice acts as the electrolyte linking the two metals; replace the strips with two copper pieces and the cell fails. The potato is not a store of electricity.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1872","question":"A Class 10 teacher places a compass under a wire and switches on a current; the needle swings, and swings the other way when the current is reversed. The best next question is:","options":["‘What is the name of the scientist who first discovered this effect, and when did he do so?’","‘How many times did the needle move during our whole demonstration today?’","‘Which colour of wire would make the needle move more strongly than this one?’","‘What does this tell us about what surrounds a wire carrying a current?’"],"answer":3,"explanation":"The deflection shows a magnetic field around the current-carrying wire whose direction depends on the current. Asking students to infer this extends the observation; names, counts or wire colour do not.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1873","question":"A Class 7 student writes, ‘In respiration our body produces energy from food.’ What is the most accurate refinement?","options":["Correct as written, since producing energy from food is exactly what respiration does in every cell","Energy is not produced; respiration releases energy stored in food so the body can use it","Respiration produces oxygen, which then gives the body the energy it needs to move","Energy is produced only during exercise, when respiration happens in the muscles"],"answer":1,"explanation":"Energy cannot be created; respiration breaks down food (glucose) with oxygen and releases stored chemical energy. Precise language here prepares students for the conservation of energy.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1874","question":"A Class 10 student asks why a bird sitting on a single live wire does not get a shock. Which explanation should the teacher guide students towards?","options":["Birds' feet are covered with a special insulating skin that stops any current from entering their bodies","The current in overhead wires is too weak to affect any animal, however large it is","Both feet are on one wire at almost the same potential, so very little current flows through the bird","Birds are too light for the current to flow through them down to the ground beneath"],"answer":2,"explanation":"Current flows only when there is a potential difference across a path; between two points close together on one wire, it is almost zero. Touching a second wire or an earthed pole would complete a path, which is why birds are killed that way.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1875","question":"Class 9 students debate growing Bt cotton. Which of these questions can be answered mainly by scientific evidence?","options":["Should farmers be free to choose seeds even if seed companies earn large profits?","Does Bt cotton reduce bollworm damage in fields compared with non-Bt cotton?","Is it right for a few companies to own the patents on genetically changed seeds?","Should the government decide which crops farmers in a district may grow?"],"answer":1,"explanation":"Whether Bt cotton reduces bollworm damage is an empirical question that field data can test. The others are about values, fairness and policy, which evidence informs but cannot settle; separating the two is key in socio-scientific debates.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1876","question":"Two Class 6 groups measure the same table with metre tapes and get 1.52 m and 1.53 m. One group insists the other must be wrong. What should the teacher help them understand?","options":["Every measurement has some uncertainty, so readings this close agree within what tapes can show","The group with the higher reading must be wrong, since cloth tapes tend to stretch and give larger values","Only the teacher's own reading can be trusted, so both groups should copy that value","They must keep measuring until both groups get exactly the same value to the millimetre"],"answer":0,"explanation":"Small differences come from reading the scale, placing the tape and judging ends; a difference of 1 cm here is within reasonable uncertainty. Understanding this is part of understanding how measurement works.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1877","question":"A Class 8 student finds that tap water lights a bulb in a conduction tester and concludes, ‘Water is a good conductor of electricity.’ How should the teacher take this further?","options":["Agree, and add that this is why all water must be kept away from electrical appliances at home","Tell her that the tester was faulty, since water does not conduct electricity under any conditions","Ask her to repeat the test with the same tap water several times to make the result more reliable","Test distilled water too, and then distilled water with a pinch of salt, and discuss what changed"],"answer":3,"explanation":"Distilled water barely conducts; tap water conducts because of dissolved salts. Comparing the three refines her over-general conclusion, which repeating the same test cannot do.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1878","question":"A Class 9 teacher displays ‘The Scientific Method: Observe → Hypothesise → Experiment → Conclude’ and tells students that all scientists follow these steps in this order. What is the main problem?","options":["The steps are in the wrong order, since experiments must always be done before any hypothesis is made","Scientists work in varied, often looping ways, and fields such as astronomy rarely run experiments","The poster leaves out the step of publishing results, which is the most important step of all","The poster is accurate, but such a detailed method is too difficult for students of Class 9"],"answer":1,"explanation":"There is no single fixed sequence; scientists move back and forth between ideas and evidence, and observational sciences test ideas without controlled experiments. Presenting one rigid method misrepresents the nature of science.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1879","question":"A teacher wants a Predict–Observe–Explain task that will most surprise Class 8 students and open a discussion on heat transfer. Which is best?","options":["Ice cubes in air and in water at the same room temperature: which melt faster?","Will ice placed in the sun melt faster than ice kept in the shade of a tree nearby?","Will hot tea cool faster in an open cup than in a covered steel tumbler?","Will a candle melt faster if it is lit than if it is left unlit on the table?"],"answer":0,"explanation":"Most students predict that ice melts faster in air, but water transfers heat to ice far better, so the cubes in water melt first. A good POE task targets a likely wrong prediction; the others have obvious answers.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1880","question":"A Class 6 student argues that a tomato is a vegetable ‘because we cook it in sabzi, not eat it like a mango’. What is the best response?","options":["Tell her she is wrong, since tomatoes are fruits, and kitchen names have no value in any science discussion","Agree, since the way we use a food in the kitchen is how science decides whether it is a fruit","Explain that botanically a fruit grows from a flower and holds seeds, while in cooking ‘vegetable’ means use","Avoid the question, since such borderline cases are only a matter of opinion with no right answer"],"answer":2,"explanation":"Everyday and scientific classifications serve different purposes: botanically, a tomato is a fruit because it develops from the flower and contains seeds, while in cooking it is used as a vegetable. Both labels make sense in their own context.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1881","question":"Asked why the Revolt of 1857 happened, most Class 8 students write only, ‘Because of the greased cartridges.’ Which task best deepens their understanding of historical causation?","options":["Have them memorise a numbered list of the ten main causes of the revolt from the textbook for the coming unit test","Ask them to find out who made the cartridges and whether the rumour about the grease was true or false","Sort causes into long-term grievances (annexations, revenue, sepoys' terms) and the immediate trigger, then link them","Ask them to write a dramatic diary entry of a sepoy on the day he refused to use the new cartridges"],"answer":2,"explanation":"The cartridges were the trigger; the revolt grew from long-standing grievances such as annexation of Awadh, revenue demands and sepoys' conditions. Distinguishing and linking long-term causes and the spark builds causal reasoning; a memorised list does not.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1882","question":"Class 9 students cannot make sense of contour lines on a topographical sheet. Which activity best builds the idea?","options":["Make a clay hill, slice it at equal heights and trace each slice from above to see lines crowd on steep sides","Have them memorise the rule that closely spaced contours show steep slopes and widely spaced ones show gentle slopes","Have them copy the contour lines from the sheet into their notebooks using a different colour for each height","Show them photographs of hills and valleys and ask them to describe the landforms seen in each of the pictures"],"answer":0,"explanation":"Slicing a model at equal heights and viewing the outlines from above shows directly how a 3-D slope becomes 2-D lines, so the spacing rule makes sense. Memorising or copying gives the rule without the idea.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1883","question":"Students in Itanagar and in Dwarka compare notes and find that the sun rises almost two hours earlier in Itanagar, though both use the same clock time. Which explanation should the teacher guide them to?","options":["Arunachal is closer to the sun than Gujarat, so the sunlight reaches it sooner every morning","Itanagar lies at a greater height above sea level, so the sun appears above the hills there much sooner","Clocks in Arunachal are set differently by custom, though the official time is the same","India spans about 30° of longitude, yet one standard time (82.5° E) is used across the country"],"answer":3,"explanation":"The earth turns 15° an hour, so places about 29° apart in longitude see sunrise about two hours apart, yet Indian Standard Time is the same everywhere. Distance from the sun has nothing to do with it.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1884","question":"A Class 8 student argues that groundwater can never run out ‘because water is a renewable resource’. Which response best addresses this?","options":["Agree, since the water cycle always returns all the water that is taken from the ground every year","It is renewable only while use does not exceed recharge; look at falling water-table data for the district","Tell him that groundwater is a non-renewable resource, just like coal and petroleum, and will soon be used up","Explain that rain refills wells within a few days, so heavy pumping makes no real difference over time"],"answer":1,"explanation":"Groundwater is renewed by recharge, but when pumping exceeds recharge the water table falls, as in many Indian districts. Calling it non-renewable is also inaccurate; the key idea is the rate of use versus renewal.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1885","question":"In a Class 7 lesson on advertising, students analyse a soap advertisement. Which question best develops critical thinking about it?","options":["What feelings and values does the advertisement link to the soap, and whose lives does it show or leave out?","How many times does the brand name appear in the advertisement, and in which colour is it printed?","Which famous actor appears in the advertisement, and in how many films has the actor worked?","Is the soap shown in the advertisement better than the one used in your home, and why exactly do you think so?"],"answer":0,"explanation":"Advertisements sell through feelings and images of a ‘good life’; asking which values are attached and who is shown or left out lets students read ads critically. The other questions stay with surface details or personal preference.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1886","question":"NCERT's Class 8 history book discusses James Mill's division of Indian history into ‘Hindu’, ‘Muslim’ and ‘British’ periods. Why does the book question this periodisation?","options":["Because Mill wrote his history in English rather than in an Indian language, so it is less authentic as a source","Because the dates Mill gave for the start and end of each period were later shown to be wrong","Because it treats the rulers' religion as the main marker of an era and paints British rule as civilising","Because the British period was too short, compared with the other two, to be called a separate period"],"answer":2,"explanation":"Mill's scheme reduces whole eras to the religion of rulers, ignores the diversity of life within them and presents British rule as bringing progress. The objection is to the logic of the division, not to dates or language.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1887","question":"A Class 8 teacher uses a Premchand story about a peasant in debt to discuss rural life under colonial rule. Which caution should accompany its use as a source?","options":["Fiction has no value in history lessons, so the story should be read only in the Hindi period","The story should be treated as a full factual record, since Premchand lived through the same period himself","Only the dates and place names in the story should be used, since everything else is invented","It conveys how people experienced the period, but should be read alongside records such as revenue reports"],"answer":3,"explanation":"Literature written in a period reveals attitudes and lived experience, but it is shaped by the author's purpose and imagination, so it is best corroborated with other sources. Dismissing it or treating it as a record both misuse it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1888","question":"A teacher shows Class 9 a set of cases marked ‘Yes’ (countries where leaders are chosen in free elections and can be voted out) and ‘No’ (a monarchy, a military rule, a one-party state). Students compare them and work out the essential features of democracy. This follows:","options":["the advance organiser model, since the cases give students a framework before the lesson begins","the concept attainment model, where learners infer a concept's attributes from examples and non-examples","the jurisprudential inquiry model, since students judge whether the governments are fair or unfair","the mastery learning model, since no student may move on until every one of them can define democracy correctly"],"answer":1,"explanation":"Concept attainment (Bruner) presents labelled examples and non-examples so that learners infer the defining attributes themselves. An advance organiser is a framework given before new material.","difficulty":"very-hard","source":"KVS TGT · NVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1889","question":"Before a chapter on the Mughal administration, a teacher gives Class 7 a brief overview showing how ideas such as ‘ranks’, ‘revenue’ and ‘provinces’ connect, so that new details can be fitted into it. This is an example of:","options":["a concept map drawn by students after the chapter to show what they have learnt","an anticipation guide, in which students agree or disagree with given statements beforehand","an advance organiser, which gives a framework for linking new material to what is known","a K-W-L chart, in which students note what they know and want to learn before reading"],"answer":2,"explanation":"Ausubel's advance organiser is a short, general framework presented before new learning, so that details can be anchored meaningfully. A concept map drawn afterwards, an anticipation guide or a K-W-L chart serve other purposes.","difficulty":"very-hard","source":"KVS TGT · DSSSB TGT"},
  {"id":"cdp-pedagogy-subjects-1890","question":"Class 7 students walk in a straight line from the village centre to the fields and river, noting land use, houses and vegetation every 100 metres, and then draw a cross-section. This activity is called a:","options":["transect walk, which shows how land use changes across an area","heritage walk, which records the historical buildings of a village","nature trail, which is meant mainly to identify plants and birds","traverse survey, which measures exact distances for a land record"],"answer":0,"explanation":"A transect walk records features at intervals along a line, revealing patterns such as how land use changes from the settlement to the fields and river. It is a standard geography fieldwork method.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1891","question":"Most Class 9 students define ‘monsoon’ simply as ‘heavy rain in July and August’. Which idea should the teacher help them add?","options":["The monsoon is a cyclone that forms over the Bay of Bengal every year towards the end of June","The monsoon is rain that falls only on the western coast of India, brought there by the Western Ghats","The monsoon is the season when the earth comes closest to the sun and heats up the land","The monsoon is a seasonal reversal of winds, which brings rain in one season and dry air in another"],"answer":3,"explanation":"The word comes from the Arabic for ‘season’; the defining feature is the seasonal reversal of wind direction, which brings the wet south-west monsoon and the drier north-east winds. Rain is a result, not the definition.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1892","question":"A Class 10 student says a ₹500 note has value ‘because the government keeps gold worth ₹500 for every note’. What should the teacher help the student understand?","options":["The student is right, since every note issued in India is backed by gold of exactly equal value","Modern currency is accepted because it is authorised by the government and trusted in exchange","Notes have value only because of the cost of the special paper, threads and ink used to print them","Notes have value only when they are deposited in a bank, which then pays out their worth"],"answer":1,"explanation":"Rupee notes are not exchangeable for gold; they are legal tender issued under government authority, and people accept them because they trust others will too. The cost of printing is far below a note's value.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1893","question":"A Class 8 student says, ‘Only rich people pay taxes, so the poor don't pay for roads and schools.’ Which activity best challenges this?","options":["Have students look at shop bills from home for GST and discuss who pays such taxes when buying goods","Explain the difference between direct and indirect taxes and have students learn both definitions by heart","Ask students to find out the income-tax rates for different income groups from the internet","Tell students that everyone pays taxes, and ask them to write this point in their notebooks"],"answer":0,"explanation":"Indirect taxes such as GST are included in the price of goods everyone buys, so the poor also pay taxes. Finding GST on their own family's bills turns a definition into evidence.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1894","question":"For a project on ‘The history of our school’, Class 6 students look at old admission registers and photographs and interview retired teachers. What is the main learning from this project?","options":["The exact founding date of the school, which is the main fact that local history projects aim to find","The names of past principals, so that students can show respect to those who served the school","How historians build an account from varied sources, and how memories and records may differ","How to make an attractive scrapbook, since presentation is the main skill in a history project"],"answer":2,"explanation":"Working with registers, photographs and interviews gives students first-hand experience of historical method: collecting, comparing and interpreting sources that may not agree.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1895","question":"To teach disguised unemployment, a teacher describes a family of eight working on a small plot that four people could manage. Students say, ‘But they are all employed; they all work on the farm.’ Which question best moves them on?","options":["How many hours a day does each member of the family work on the farm in the busy season?","If four of them found other jobs, would the farm's output fall?","What crops does the family grow, and how much land would it need to grow more of them?","How much income does the family earn from selling the crops in the market every year?"],"answer":1,"explanation":"Disguised unemployment means more people are engaged than the work needs, so removing some does not reduce output. The question targets exactly that test; hours, crops or income do not.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1896","question":"Class 9 students see that Mumbai receives far more rainfall than Pune, about 150 km away. Which approach best helps them explain the difference?","options":["Tell them that Pune is farther from the sea and so is drier, and have them note this point","Ask them to memorise the definition of a rain-shadow area with Pune as the main example","Have them compare the populations of the two cities to see whether rainfall depends on a city's size","Give a relief map with the Western Ghats and the monsoon winds' path, and have them reason it out"],"answer":3,"explanation":"Moist winds rise over the Western Ghats and drop most of their rain on the windward side (Mumbai), leaving the leeward side (Pune) in a rain shadow. Reasoning from relief and wind data builds understanding; distance from the sea alone does not explain it.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1897","question":"Studying a medieval kingdom, a Class 7 student says, ‘Women did nothing important then, because the court chronicles hardly mention them.’ What should the teacher help her see?","options":["She is right, since the court chronicles recorded everything important that happened at the time","Women's lives in that period are simply unknowable, so the topic should not be studied","Silence in sources reflects who wrote them and for whom; other sources may show women's roles","Chronicles are unreliable in every respect and should never be used to study the period"],"answer":2,"explanation":"Court chroniclers wrote about rulers and battles for patrons; their silence says more about their purpose than about women's lives. Other evidence, such as inscriptions, grants, songs or paintings, can reveal women's roles.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1898","question":"In a Class 8 discussion, a student says only educated people should be allowed to vote. Which teacher response best develops understanding of universal adult franchise?","options":["Ask what the right to vote rests on, and what happened when voting was limited by property or education","Tell the student firmly that this view is undemocratic and must not be expressed again in the classroom","Agree that educated voters may choose better, but explain that the Constitution does not allow such a limit","Hold a vote in the class on the proposal and accept whatever result the majority produces"],"answer":0,"explanation":"Universal adult franchise rests on equal citizenship, not ability; examining history (restricted franchise under colonial rule) lets students see whose voices were excluded. Shutting the student down or putting rights to a class vote avoids the reasoning.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1899","question":"NCERT social science books often open a topic with the story of one person, such as a farmer or a domestic worker. What is the main caution a teacher should take when using such a case?","options":["Cases should be avoided, since a story makes students emotional and distracts them from facts","The case should be read aloud only once, so that students do not remember the person's name","The teacher should treat the case as true for every person in India, so that it is easy to learn and remember","Students should test how far the case represents a wider pattern before drawing general conclusions"],"answer":3,"explanation":"A case makes abstract ideas concrete, but one life is not the whole picture; students should ask how typical it is and look at wider evidence before generalising.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1900","question":"To introduce how archaeologists date finds, a teacher buries objects in layers of different coloured sand in a glass box and lets students ‘excavate’ them. What principle does this mainly teach?","options":["That the deepest objects are always the most valuable, since they must have been buried with great care","That lower layers are usually older than the layers above them, unless they have been disturbed","That every object found in one layer must have been made in exactly the same year","That the colour of the soil in a layer tells archaeologists the exact age of the objects"],"answer":1,"explanation":"The principle of superposition says layers below are generally older, which gives relative dates; the ‘unless disturbed’ condition matters, as pits and burrows mix layers. Layers do not give exact years.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1901","question":"Class 6 students examine pictures of coins of one ancient dynasty showing deities from several different traditions. Which conclusion is most reasonable?","options":["The rulers probably sought support from people of varied beliefs, though coins cannot show what all believed","All the people of that kingdom must have followed every one of the religions shown on the coins of their rulers","The rulers must have had no religion of their own, since they used images from many traditions","The coins were most likely made by foreign traders, since rulers would show only their own gods"],"answer":0,"explanation":"Coins tell us what rulers chose to show, suggesting they sought support from people of varied faiths or ruled a diverse area; they cannot reveal what each subject believed. The other options go beyond the evidence.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1902","question":"Before reading extracts from Ibn Battuta's account of 14th-century Delhi, what is the most important point for Class 7 students to keep in mind?","options":["His account is fully reliable, since a foreign visitor has no reason to favour any group in India over another","His account is worthless, since he did not know the local languages and stayed only briefly","As an outsider he noted what seemed strange to him, and he wrote much of it later, from memory","His account should be checked only against the textbook, which has already decided what happened"],"answer":2,"explanation":"Travellers' accounts are valuable because they record what locals took for granted, but they reflect the writer's background, purpose and audience. Reading them critically means neither accepting nor rejecting them wholesale.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1903","question":"A Class 7 teacher asks students to find which items in their family's thali, such as chillies, potatoes and tomatoes, came to India from the Americas after 1500. The main purpose is to:","options":["prove that Indian food today is not really Indian, since many of its ingredients came from abroad","link history to students' daily lives and show how contact and trade change everyday culture","teach students the botanical names of vegetables and the regions in which each is grown today","prepare a list of foreign foods which students should avoid, since local foods are healthier"],"answer":1,"explanation":"Tracing familiar foods to their origins shows that culture is shaped by contact and exchange over time, and that history is present in daily life. It does not make the food ‘less Indian’.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1904","question":"In a Class 9 lesson, five students discuss a question in an inner circle while the rest sit around them, noting how arguments are built and giving feedback afterwards; roles then rotate. This structure is called a:","options":["jigsaw, in which each group becomes expert on one part","think-pair-share, in which pairs talk before sharing","panel discussion, in which experts answer questions","fishbowl discussion, with an inner and outer circle"],"answer":3,"explanation":"In a fishbowl, an inner group discusses while an outer group observes the discussion process and later reflects on it, which builds both content understanding and discussion skills.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1905","question":"A Class 10 teacher runs a barter game in which each student must trade a card for what she needs without using money, and many fail to complete a trade. What concept does the game mainly bring out?","options":["That barter was never really used in any society, since it is impossible in practice","That traders in a barter system cheat more often than traders who use money","The double coincidence of wants, which money removes as a medium of exchange","That the value of goods in a barter system is always fixed by the government"],"answer":2,"explanation":"In barter both people must want what the other has; when that rarely happens, trades fail. Money solves this by acting as an accepted medium of exchange, which the game lets students feel directly.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1906","question":"Looking at a map of India, several Class 6 students say rivers always flow ‘from the top of the map to the bottom’. Which evidence best challenges this?","options":["The Narmada and Tapi flow west to the Arabian Sea: rivers follow the land's slope, not map direction","The Ganga flows from the Himalayas towards the south-east, which proves that all rivers flow south","Rivers in the southern hemisphere flow northward, which shows that a river's direction depends on its hemisphere","Rivers on maps are drawn only roughly, so their direction on a map cannot really be trusted at all"],"answer":0,"explanation":"Rivers flow downhill from higher to lower land in whatever compass direction that takes them; the westward Narmada and Tapi show this. ‘Top of the map’ is north, not uphill.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1907","question":"Class 10 students study why sugar mills are usually located close to sugarcane fields. Which explanation should the teacher guide them towards?","options":["Sugar mills need very little electricity, so they can be built anywhere in a rural area of the country","Sugarcane is bulky and loses sugar after cutting, so it must be crushed soon, near the fields","Sugar is consumed mainly in villages, so mills are placed close to the people who buy the sugar","The government requires every sugar mill to be built inside the village where the cane is grown"],"answer":1,"explanation":"A heavy, perishable raw material that loses weight in processing pulls industry towards its source; sugarcane loses sucrose if haulage is delayed. Reasoning from the nature of the raw material is the key idea.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1908","question":"Before a unit on the Constitution, a teacher has Class 8 play a game with no agreed rules; arguments break out and the strongest players take over. Students then frame rules together. The main purpose is to help students see that:","options":["games without any rules are more fun, so societies should have as few laws as they possibly can","the teacher's authority is needed to settle every dispute that arises in the class","agreed rules limit the power of the strong and give everyone a fair basis to take part","the students who argued most during the game should not be chosen to frame the rules"],"answer":2,"explanation":"The breakdown shows why a society needs agreed rules that bind everyone, protect the weaker and limit power, which is what a constitution does. The point is not reliance on the teacher.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1909","question":"A Class 9 student says a map with a scale of 1:1,000,000 is a ‘large-scale map’ because the number is bigger than in 1:50,000. What is the correct idea?","options":["She is right, since the larger the second number of a scale, the larger the scale of the map","Both maps have the same scale, since each represents real distances on a reduced sheet","Scale cannot be compared unless both maps are drawn on sheets of exactly the same size","1:50,000 is the larger scale; it shows a smaller area in more detail than 1:1,000,000"],"answer":3,"explanation":"1/50,000 is a larger fraction than 1/1,000,000, so 1:50,000 is the larger scale, used for detailed maps of small areas. Students often judge by the size of the second number, which reverses the idea.","difficulty":"very-hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1910","question":"For a geography project on urban housing, Class 9 students plan to photograph people in a nearby basti and post the pictures online. What should the teacher insist on first?","options":["Asking people's consent, respecting refusals and avoiding images that show them as objects of pity","Choosing the most striking photographs, since vivid images make the project more convincing","Taking the photographs quickly and quietly, so that people do not change how they behave","Posting the photographs only after removing the school's name, so that the school cannot be blamed later"],"answer":0,"explanation":"Fieldwork involving people requires consent and respect for their dignity; images taken without permission or chosen for shock value exploit the people being studied.","difficulty":"moderate","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1911","question":"Many Class 7 students say ‘ship’ and ‘sheep’, and ‘live’ and ‘leave’, the same way, which causes confusion in speech. Which activity most directly targets this?","options":["Have them read the lesson aloud daily, with the teacher correcting each word they say wrongly as they go along","Teach the phonetic symbols for every English vowel and have students transcribe whole passages with them","Have them copy lists of words containing ‘ee’ and ‘i’ and learn the spelling rules for each of the two vowels","Minimal-pair games: they hear a word and point to the right picture, then say pairs for a partner to identify"],"answer":3,"explanation":"Students first need to hear the long/short vowel contrast before they can produce it; minimal-pair listening and speaking games focus on exactly that, in meaningful pairs. Spelling rules and full transcription do not train the ear.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1912","question":"Class 9 students keep writing ‘do a mistake’ and ‘make homework’. The teacher gives them printed lines from real texts, each showing ‘make’ or ‘do’ with the words around it, and asks them to find patterns. This approach:","options":["lets learners discover collocations from real usage, so the patterns stick better than a rule","is too advanced for school, since only trained linguists can learn anything useful from such lines","replaces vocabulary teaching, so the teacher need never explain any word meaning again","mainly practises reading speed, since the lines are short and can be read very quickly"],"answer":0,"explanation":"Concordance lines show how words actually combine (make a mistake, do homework), and discovering these patterns is data-driven learning. Collocations are largely conventional, so seeing many real examples works better than a rule.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1913","question":"Class 8 students find phrasal verbs such as ‘eat up’, ‘use up’, ‘fill up’ and ‘cheer up’ hard to remember. Which approach is most helpful?","options":["Learn an alphabetical list of a hundred phrasal verbs with their meanings, ten new verbs each day","Avoid phrasal verbs in class, since students can always use one-word verbs such as ‘consume’ instead","Group them by the particle's meaning (‘up’ for completion or increase) and meet them in context","Translate each phrasal verb into the mother tongue and test the translations every Friday"],"answer":2,"explanation":"Many particles carry a core meaning (‘up’ = completely or more), so grouping by particle makes phrasal verbs less arbitrary, and context shows their use. Long lists and avoidance do not build usable knowledge.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1914","question":"To teach report writing, a Class 8 teacher first analyses model reports with the class, then writes one together with them on the board, and only then has students write their own. This sequence follows:","options":["the grammar-translation method, in which model texts are studied, translated and then copied closely","the genre-based teaching–learning cycle: deconstruction, joint construction, then independent writing","the audio-lingual method, in which correct models are drilled until habits are formed","the direct method, in which writing is taught only through speech and never through models"],"answer":1,"explanation":"The genre-based cycle moves from analysing how a text type works, to building one jointly, to independent writing, so support is gradually withdrawn. Students study models to understand them, not to copy them.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1915","question":"A Class 6 teacher teaches 15 new words each Monday and tests them on Friday; by the next month students have forgotten most of them. Which change is most likely to help retention?","options":["Teach 30 new words each week instead, so that more of them remain after the usual amount of forgetting","Bring the words back in new activities after a day, a week and a month, at growing intervals","Give a harder test on Friday so that students take the weekly word lists more seriously","Ask students to copy each new word twenty times on Monday when it is first introduced"],"answer":1,"explanation":"Memory for words strengthens with repeated retrieval spread out over time (spaced repetition), ideally in varied contexts. Cramming many words or copying them in one sitting leads to quick forgetting.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1916","question":"After reading a short story with Class 8, a teacher dictates ‘the central idea’ and marks students' own interpretations wrong if they differ. Which approach would better develop literary response?","options":["Give students a guidebook's summary of the story so that their answers match the expected one","Ask students to memorise the teacher's central idea, since examinations reward one single correct answer to such questions","Avoid discussing meaning at all and focus only on the new words and grammar in the story","Invite personal responses and interpretations, asking students to support each with evidence from the text"],"answer":3,"explanation":"A reader-response approach values students' own readings while requiring them to ground interpretations in the text; this builds independent thinking about literature. A single dictated meaning shuts that down.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1917","question":"Before a Class 6 reading lesson, a teacher prints all the past-tense verbs in a story in bold, without saying anything about them, and students later begin using these forms more accurately. Which idea best explains this?","options":["Input enhancement draws learners' attention to forms, and noticing them helps acquisition","The affective filter rises when text is printed in bold, which makes those forms easier to learn","Bold printing is a form of explicit grammar teaching that replaces the need for rules","Students learn only what is tested, and bold words tell them what will be on the test"],"answer":0,"explanation":"Schmidt's noticing hypothesis holds that learners acquire forms they notice in input; typographic enhancement makes forms more noticeable without explicit teaching. Bold type does not lower or raise the affective filter.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1918","question":"During a discussion about a school trip, a student says, ‘We goed to the zoo.’ The teacher replies, ‘Oh, you went to the zoo? What did you see?’ and the talk continues. This is an example of:","options":["focus on forms, in which grammar points are taught one by one in a planned sequence","error avoidance, in which the teacher ignores all errors so that fluency is never disturbed","focus on form, in which attention to a form arises briefly within meaningful communication","explicit correction, in which the teacher states the rule and asks the student to repeat it"],"answer":2,"explanation":"Focus on form draws attention to language briefly during communication, here through a recast. Focus on forms is the planned, item-by-item grammar syllabus, and the teacher did not ignore the error or state a rule.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1919","question":"Before an English test, a Class 9 student decides which sections to revise first, sets herself a timetable and, after each practice, checks which errors she still makes. These are mainly:","options":["cognitive strategies, since they work directly on the language material being learnt","social strategies, since they involve working with others to learn the language","metacognitive strategies, since she plans, monitors and evaluates her own learning","compensation strategies, since they help her make up for gaps in her knowledge"],"answer":2,"explanation":"Planning, monitoring and evaluating one's own learning are metacognitive strategies. Cognitive strategies act on the material itself (practising, note-making), social ones involve others, and compensation strategies cover gaps in use.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1920","question":"Class 9 students give a talk on the same topic three times to three different partners, first in 4 minutes, then in 3, then in 2. The main purpose of this activity is to develop:","options":["accuracy, since each partner corrects every error before the student moves on to the next round","fluency, since repeating the same content under time pressure speeds up speech","vocabulary, since students must use new words in each version of their talk","listening, since students mainly sit and listen to what their partners say"],"answer":1,"explanation":"In the 4/3/2 activity, content stays the same while time shrinks, so learners retrieve language faster and speak more smoothly; it is a fluency activity, not an accuracy or vocabulary one.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1921","question":"To learn spellings, a Class 4 teacher has children look at a word, say it, cover it, write it from memory and then check it against the original. The main strength of this routine is that it:","options":["requires no practice at home, since a single go is enough to learn every word","teaches the meaning of each word, which is the main reason children learn spellings at this stage","replaces reading, since children no longer need to meet the words in any texts","makes children recall the word from memory and check it, rather than merely copy it"],"answer":3,"explanation":"Look–say–cover–write–check builds a visual memory of the word through active recall and self-checking, which copying does not. It is a spelling routine, not a way of teaching meaning.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1922","question":"In a Class 7 English reader, a story shows the mother cooking and the father reading the newspaper on every page. To develop critical literacy, which question should the teacher ask?","options":["Whose work is shown and whose is missing, and how could the story be retold differently?","What did the mother cook in the story, and how many members were there in the family?","Which new words did you find in the story, and what is the meaning of each of them?","Which part of the story did you like the most, and would you recommend it to a friend? Why or why not?"],"answer":0,"explanation":"Critical literacy asks how a text represents people, whose roles are visible or hidden and what alternatives exist. Recall, vocabulary or liking questions do not examine the text's assumptions.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1923","question":"Reader P knows every word in a passage about a cricket match but cannot follow it, having never seen cricket. Reader Q, a keen cricket fan, guesses the story from the first line and ignores what the text actually says. What does the interactive view of reading suggest?","options":["Reading combines decoding the text and using background knowledge; P lacks the second and Q neglects the first","P is the better reader, since reading is only the accurate decoding of each word and every sentence on the page","Q is the better reader, since reading is only guessing meaning from what one already knows about a topic","Neither is reading at all, since reading begins only once a reader knows every word and the whole topic"],"answer":0,"explanation":"Interactive models combine bottom-up processing (decoding words) with top-down processing (using schema). P has the first without the second; Q over-relies on the second and ignores the text.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1924","question":"In a one-to-one writing conference with a Class 6 student about her story draft, what should the teacher do first?","options":["Correct all the spelling and grammar errors in the draft so the student can copy them","Read out a model story by a famous author so that she can see how a good story should be written and organised","Ask what she is trying to say and what she likes most, then talk about one part that could be clearer","Give the draft a grade so that she knows where she stands before she begins her revision"],"answer":2,"explanation":"Conferences work best when they start from the writer's intentions and focus on meaning and one or two revisions; correcting everything or grading makes the student passive and shifts attention to surface errors.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1925","question":"While writing an email to a pen-friend, a Class 8 student realises she does not know how to say ‘I am looking forward to meeting you’ and asks the teacher. Which idea from second-language research best explains the value of such moments?","options":["The input hypothesis, which says that only listening and reading lead to acquisition","The output hypothesis, which says that producing language makes learners notice gaps in what they know","The critical period hypothesis, which says that language is learnt best before puberty","The monitor hypothesis, which says that consciously learnt rules are used only to edit what we say or write"],"answer":1,"explanation":"Swain's output hypothesis holds that trying to produce language pushes learners to notice what they cannot yet say and to seek the form, which aids learning. Krashen's input hypothesis would give output little role.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1926","question":"Class 8 stories keep telling feelings flatly: ‘She was very sad.’ Which approach most effectively helps students write more vividly?","options":["Build a class word wall of precise feeling words such as gloomy, crushed and uneasy, and encourage students to use them","Have students keep a daily journal about their own feelings to build fluency and confidence in expressing emotion","Return each draft with every flat sentence marked and a livelier version suggested in the margin for students to copy","Read passages where writers show a feeling through actions and detail, then have students revise one of their own lines"],"answer":3,"explanation":"Mentor texts let students see how skilled writers show emotion through action and detail, then practise that craft on their own lines. A word wall is tempting, but swapping 'sad' for 'gloomy' still tells the feeling rather than showing it.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1927","question":"A Class 4 child with dyslexia struggles to link English letters with sounds despite much reading practice. Which approach is best supported for her?","options":["Giving her more silent reading of long passages, so that she meets words more often","Excusing her from reading and writing in English until she grows out of the difficulty","Having her copy each spelling list neatly several times, since dyslexia is mainly a difficulty with handwriting","Structured, multisensory phonics in which she sees, says, hears and traces letters and sounds"],"answer":3,"explanation":"Explicit, systematic phonics using several senses together (as in Orton–Gillingham-based methods) is well supported for dyslexia. More unsupported reading or copying does not address the decoding difficulty.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1928","question":"Taught that ‘a verb is a doing word’, a Class 6 student labels ‘swimming’ in ‘Swimming is good exercise’ as a verb. What does this show?","options":["A meaning-based definition misleads; word class depends on how a word functions in the sentence","The student is right, since every word ending in ‘-ing’ is a verb in all sentences","The student is careless and should learn the definition of a verb more thoroughly","The sentence is ungrammatical, since a verb cannot be used as the subject of a sentence in English"],"answer":0,"explanation":"Here ‘swimming’ is the subject and works as a noun (a gerund). Defining word classes by meaning (doing word, naming word) fails such cases; students should look at the job the word does.","difficulty":"very-hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1929","question":"Class 6 students write only in short, choppy sentences such as ‘I have a dog. The dog is brown. It is playful.’ Which activity best builds more mature sentences?","options":["Ban short sentences in all their writing, so that students are forced to write longer ones","Teach the definitions of simple, compound and complex sentences for a test the following week","Give sets of short sentences to combine in different ways, using ‘and’, ‘which’ and ‘because’","Ask students to copy long sentences from the textbook into their notebooks every day"],"answer":2,"explanation":"Sentence-combining practice lets students try out ways of joining ideas and compare the results, which develops syntactic maturity. Definitions, bans or copying do not give that practice.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1930","question":"A Class 6 English teacher has limited time for explicit vocabulary teaching. Which words should get the most class time?","options":["Rare literary words from the textbook poems, since these are the most impressive ones to use in essays","High-frequency words that cover most of everyday texts, since these give the greatest return","Words that are spelt in unusual ways, since these cause the most errors in written tests","Technical words from science and maths, since every other subject needs them most often"],"answer":1,"explanation":"A small set of high-frequency words makes up most of the running words in ordinary texts, so teaching them well pays off the most; rarer words are better left to context and dictionaries.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1931","question":"A Class 3 child writes ‘jumpt’, ‘playd’ and ‘wantid’. What is the best teaching response?","options":["Mark the words wrong and have her copy each correct spelling ten times in her notebook","Show that ‘-ed’ is written the same for every past-tense verb, whatever sound it makes","Teach her to spell by sound alone, since English spelling closely follows the way words are pronounced","Tell her to avoid past-tense verbs in her writing until she knows how to spell them"],"answer":1,"explanation":"She spells by sound, and the past-tense ending is pronounced /t/, /d/ or /ɪd/; English keeps one spelling, ‘-ed’, for the meaning. Teaching this morpheme pattern fixes all three errors at once.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1932","question":"A teacher shows Class 5 that answers can be ‘Right There’ in one sentence, found by ‘Think and Search’ across the text, worked out with ‘Author and Me’, or come ‘On My Own’. The main aim of teaching this framework is to help students:","options":["remember the names of four question types for a test on reading comprehension","answer only those questions that can be found directly in a single sentence of the text they have read","avoid using their own experience, since answers should always come from the text","know where to look for an answer, so they combine text and their own knowledge as needed"],"answer":3,"explanation":"Question–Answer Relationships teach students that some answers are stated, some must be pieced together, and some need their own knowledge with the text; knowing this improves how they search for and build answers.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1933","question":"In a Class 7 English class, small groups read the same novel; each member has a rotating role such as discussion leader, word finder or connector, and groups meet weekly. This is called:","options":["literature circles","guided reading","round-robin reading","shared reading"],"answer":0,"explanation":"Literature circles are student-led discussion groups reading the same book, with rotating roles to structure talk. Guided reading is teacher-led small-group instruction, and round-robin reading is turn-taking aloud.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1934","question":"Which of these shows the deepest knowledge of the word ‘heavy’ by a Class 8 student?","options":["She can spell ‘heavy’ correctly and give its exact meaning in her mother tongue and in Hindi","She can pick out ‘heavy’ from four options in a matching test of meanings","She uses ‘heavy rain’ and ‘heavy traffic’ correctly, but says ‘strong tea’, not ‘heavy tea’","She can say that ‘heavy’ is an adjective and that ‘light’ is its antonym"],"answer":2,"explanation":"Knowing a word fully includes its collocations and limits of use, not just form and meaning. Using ‘heavy’ with the right partners shows that depth; spelling, translation or matching show only basic knowledge.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1935","question":"When a Class 4 teacher asks a child, ‘Can you open the window?’, the child says ‘Yes, I can’ and stays seated. The child is most likely still developing:","options":["vocabulary, since he does not know the meaning of the word ‘window’","pronunciation, since he could not say the word ‘open’ clearly enough to be understood","pragmatic understanding, since the question is really a polite request","listening, since he did not hear the teacher's question properly"],"answer":2,"explanation":"He answered the literal question about ability, missing that ‘Can you…?’ is a polite request. Understanding such indirect meanings is pragmatic competence, built through use in real situations.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1936","question":"A Class 5 teacher first writes a paragraph on the board while thinking aloud, then writes the next one with the class's suggestions, then has pairs write one, and finally each child writes alone. This sequence reflects:","options":["gradual release of responsibility: I do, we do, you do together, you do alone","the grammar-translation method, in which a model is translated and then copied","free writing, in which children write without any planning or support at all","the audio-lingual method, in which correct forms are drilled through repetition"],"answer":0,"explanation":"In gradual release, the teacher models, then shares the task, then supports pairs, and finally hands over to independent work, so responsibility shifts step by step to the learner.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1937","question":"Class 5 children often mix up ‘there’, ‘their’ and ‘they're’ in writing. Which activity is most likely to help?","options":["Write the three words on a chart and have children say them aloud in chorus every day","Tell children to use only ‘there’ in their writing until they are older and more careful","Give the dictionary definitions of the three words and ask children to learn them by heart","Sort sentences from their own writing by meaning, with a picture cue for each word"],"answer":3,"explanation":"The words sound alike, so saying them aloud does not help; children need to link each spelling with its meaning and use, and sorting their own sentences makes that link. Avoidance and definitions alone do not.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1938","question":"Class 9 essays arguing that mobile phones should be allowed in school give only reasons in favour. Which step most improves their argumentative writing?","options":["Ask students to make the essays longer by adding many more reasons in favour of their own side of the issue","Teach them to state and answer the strongest counter-argument, which makes their case more convincing","Ask students to write only on topics they personally feel very strongly and deeply about","Give them a list of persuasive linking words to put at the start of every paragraph"],"answer":1,"explanation":"A strong argument anticipates and rebuts opposing views; adding counter-arguments shows awareness of the issue and strengthens persuasion. More one-sided reasons or connectors do not.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1939","question":"A Class 2 English teacher uses action songs every day. Which is the strongest reason for this?","options":["Songs give repeated, enjoyable exposure to chunks and rhythm with little anxiety","Songs are the only way to teach English grammar to children of this age group","Songs keep children quiet and seated, which makes managing a large class of young children easier","Songs replace the need for any reading or writing in the early English classes"],"answer":0,"explanation":"Action songs give much repetition of whole phrases with rhythm and movement in a relaxed setting, which suits young learners. They are one useful tool, not the only way to teach grammar or a substitute for literacy.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1940","question":"A teacher cuts a short story into its sentences, gives one strip to each student in a group, and the group must put the story in order by reading strips aloud, without showing them. The activity mainly develops:","options":["handwriting, since each student must later copy out the whole story neatly from the strips","dictionary skills, since students must look up each unknown word before they can begin","awareness of how texts hang together, through clues such as time words and pronouns","silent reading speed, since each student must read every strip as fast as possible"],"answer":2,"explanation":"To order the strips, students must notice cohesive clues (then, after that, she, it) and the logic of events, while talking to each other. It builds discourse awareness and speaking, not handwriting or speed.","difficulty":"hard","source":"CTET Paper 2 · KVS TGT"},
  {"id":"cdp-pedagogy-subjects-1941","question":"In the first weeks of Class 1, a teacher uses each child's own name for many literacy games: finding it on a chart, spotting its first letter in other names, building it from letter cards. Why is the child's name such a useful starting point?","options":["It is personally meaningful, so children attend closely to its letters and use it as an anchor for others","Names are always spelt regularly, so they are the easiest words for children to sound out letter by letter","It saves the teacher from preparing any other reading material during the first months of the session","Names are the words most often tested in early reading assessments, so learning them improves scores"],"answer":0,"explanation":"A child's name is the first word that matters to her; she attends to its letters, recognises them elsewhere and uses them to work out other words. Many names are not phonically regular, so that is not the reason.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1942","question":"A four-year-old confidently ‘reads’ the word on a familiar biscuit packet, but cannot read the same word when it is printed in plain black letters on a card. This most likely shows that she:","options":["has a visual memory problem that needs to be screened by a specialist before any reading begins","has learnt to decode the word but forgets it when the colours are changed","is reading the logo as a picture from its colours and shape, not from the letters","is pretending, since she has no knowledge at all about print or its meaning"],"answer":2,"explanation":"At the earliest, logographic phase children recognise words by context and visual features such as colour and design, not by letters. It is a normal step showing she knows print carries meaning, not decoding or a disorder.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1943","question":"A five-year-old writes ‘LFNT’ for ‘elephant’ and ‘BK’ for ‘bake’. What strategy is she using?","options":["She is copying words from a wall chart and simply leaving out the letters she cannot remember","She uses letter names for sounds: ‘L’, ‘F’, ‘N’ and ‘K’ sound like parts of the words","She has a hearing difficulty that stops her from hearing the vowel sounds in words","She is writing in a code of her own that has no link with the sounds of the words"],"answer":1,"explanation":"Letter-name spelling is a normal early stage: the name ‘el’ stands for the first syllable of ‘elephant’, ‘ef’ for /f/, ‘en’ for /n/. It shows real phonological analysis, the base for learning conventional spelling.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1944","question":"While reading a picture book with a small group, a teacher asks a child what is happening, praises the answer, adds a little more language (‘Yes, the dog is chasing the cat up the tall tree’) and asks the child to say it again. This technique is known as:","options":["round-robin reading, in which each child reads one line aloud in turn","guided reading, in which children read a levelled text on their own with the teacher's support","choral reading, in which the group reads the same text aloud together","dialogic reading, in which the adult prompts, evaluates, expands and repeats"],"answer":3,"explanation":"Dialogic reading turns the child into the storyteller through the PEER sequence (prompt, evaluate, expand, repeat), which builds oral language. Here the children are not decoding text, so it is not guided, choral or round-robin reading.","difficulty":"very-hard","source":"KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-1945","question":"A Class 1 teacher uses two kinds of small books: some with repeated patterns (‘I see a red bird. I see a blue bird…’) and some made mostly of words using letter-sounds already taught (‘Sam sat on a mat’). What is the best reason for using both?","options":["Patterned books should be used only for children who cannot learn phonics at all","Phonic books should be used only for testing, while patterned books are for enjoyment","Phonic books should be used only for testing decoding, while patterned books are kept for enjoyment","Patterned books build confidence and print concepts; phonic books let children practise decoding"],"answer":3,"explanation":"Predictable texts let beginners join in and learn about print and fluency, while decodable texts let them apply taught letter-sound knowledge. Each does a different job, so they work best together.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1946","question":"After a class trip, a Class 1 teacher writes a group message on chart paper, but children take turns holding the marker to write letters and words they know while the teacher writes the rest. This is called:","options":["shared writing, in which the teacher alone holds the pen while the children only suggest the words","interactive writing, in which teacher and children share the pen to compose the text together","guided writing, in which each child writes on her own with help from the teacher at her desk","copy writing, in which children copy the teacher's finished text into their own notebooks"],"answer":1,"explanation":"In interactive writing children ‘share the pen’, contributing what they can; in shared writing the teacher scribes the children's ideas. Both model composing, but interactive writing gives practice in letter formation and spelling too.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1947","question":"A pre-primary teacher often uses wordless picture books with her group. What is their main value for early literacy?","options":["Children tell the story in their own words, building narrative and oral language skills","They prepare children for spelling tests, since children name the objects in each picture","They are meant only for children who cannot yet read, and have no use once reading starts","They keep children quiet, since there are no words to be read aloud during the session"],"answer":0,"explanation":"Without printed words, children must create the narrative: sequencing events, describing and inferring. This builds the oral language and story sense that later reading comprehension depends on.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1948","question":"Many parents of children in a Class 1 village classroom cannot read. Which advice best supports the children's literacy at home?","options":["Ask parents to hire tutors, since they cannot help with reading themselves","Ask older siblings to make the child copy all the alphabet letters neatly every evening after school","Encourage parents to tell stories, sing songs and talk with the child about picture books","Tell parents to leave literacy entirely to the school, since they cannot read"],"answer":2,"explanation":"Oral storytelling, songs and talk about pictures build vocabulary, narrative and love of books, which matter as much as decoding; non-reading parents can do all of this. Copying drills or giving up on home support help far less.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1949","question":"A Class 1 teacher teaches the sound of ‘s’ as ‘suh’ and of ‘t’ as ‘tuh’; children then blend ‘suh-a-tuh’ and say ‘suhatuh’ instead of ‘sat’. What should she change?","options":["Teach the letter names instead of sounds, since names are easier for children to blend into words","Stop blending altogether and teach every word as a whole shape for children to memorise","Pronounce sounds as purely as possible, stretching ones like ‘sss’ without an added ‘uh’","Teach the children to blend only words with two letters until they are in Class 2 or later"],"answer":2,"explanation":"Adding a vowel to each consonant (‘suh’) inserts extra sounds that make blending fail. Pure sounds, especially continuous ones that can be stretched (sss, mmm), blend smoothly into words.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1950","question":"Children who read well early read more, gain vocabulary and knowledge, and pull further ahead, while weak readers read less and fall further behind. This pattern, described by Keith Stanovich, is known as:","options":["the Matthew effect in reading","the halo effect in assessment","the Pygmalion effect in teaching","the recency effect in memory"],"answer":0,"explanation":"The Matthew effect (‘the rich get richer’) describes how early reading differences widen over time through differences in reading volume. It is a strong argument for early identification and support.","difficulty":"very-hard","source":"KVS PRT · NVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1951","question":"A Class 3 child decodes every word correctly but so slowly and effortfully that she remembers little of what she read. Which explanation best fits?","options":["She does not yet know enough letter-sound links, which is why her decoding is accurate but very slow","She has a memory disorder, since a normal child would remember what she has just read","She is reading carelessly and needs to be told to pay attention to the meaning of the text","Decoding takes up most of her attention, leaving little for comprehension; she needs fluency practice"],"answer":3,"explanation":"Automaticity theory (LaBerge and Samuels) holds that attention is limited: when decoding is effortful, little is left for meaning. Repeated reading and practice make decoding automatic, freeing attention for comprehension.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1952","question":"According to the ‘simple view of reading’, reading comprehension is the product of decoding and language comprehension. What follows for a child who decodes perfectly but understands little even when the same text is read aloud to her?","options":["Her difficulty is in decoding, so she needs much more phonics practice to fix the problem","Her difficulty is language comprehension, so she needs vocabulary and oral language work","She has no difficulty, since accurate decoding is the same thing as reading","She needs only to read faster, since speed will bring comprehension with it"],"answer":1,"explanation":"If she cannot understand the text even when it is read to her, the gap is in language comprehension, not decoding. Because the two multiply, strength in one cannot make up for weakness in the other.","difficulty":"very-hard","source":"KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-1953","question":"In a Class 1 journal period, children draw a picture and tell the teacher about it; she writes their exact words under the drawing and reads them back. The main value of this practice is that:","options":["it saves time, since children do not need to write anything at all in Class 1","children see their own spoken words turned into print, linking talk and writing","it gives the teacher a record of each child's handwriting for assessment","it lets the teacher correct the grammar of what the children say before writing"],"answer":1,"explanation":"Scribing a child's own words shows that what we say can be written and read back, a key insight for emergent literacy. Writing their exact words, not corrected ones, keeps ownership with the child.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1954","question":"Consider these statements: I. Children should begin learning about print only after a fixed ‘readiness’ age. II. Literacy development begins long before formal instruction, through everyday experiences with print and talk. III. Scribbling and pretend reading are part of literacy development. IV. Oral language has little link with later reading. Which match the emergent literacy view?","options":["I and IV only","I, II and III only","II, III and IV only","II and III only"],"answer":3,"explanation":"The emergent literacy view rejects a fixed readiness age (I) and sees literacy growing from early experiences, including scribbling and pretend reading (II, III). Oral language is a strong foundation for reading, so IV is wrong.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1955","question":"A Class 1 teacher teaches letters c, a, d, g and o together in handwriting lessons. Why is this a sensible grouping?","options":["They are all vowels, so children learn the vowels together before the consonants","They come one after another in the alphabet, so the order is easy to remember","They all start with the same anticlockwise curve, so one movement is practised","They are the letters children use most often in their own names and words"],"answer":2,"explanation":"These letters share a starting stroke, an anticlockwise ‘c’ curve; grouping letters by movement builds correct formation habits. Only a and o are vowels, and they are not consecutive in the alphabet.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1956","question":"A pre-primary child asks for the same picture book to be read every day for two weeks. What is the best way for the teacher to view this?","options":["As valuable, since rereading lets the child notice more, predict and join in with the language","As a sign the child is not ready for books, so reading to her should be postponed for a while","As a habit to discourage, since children should hear a new book every single day","As a sign of a learning difficulty, since normal children want variety in their books"],"answer":0,"explanation":"Repeated reading of a favourite book builds familiarity with its language, lets the child predict and ‘read along’, and deepens understanding; it is typical and useful at this age, alongside new books.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1957","question":"To check Class 1 children's decoding, a teacher asks them to read made-up words such as ‘mip’, ‘tob’ and ‘sut’. Why use such words?","options":["They test decoding itself, since children cannot have memorised them as sight words","They are easier than real words, so all children can feel successful and confident in the test","They teach new vocabulary, since children learn the meaning of each made-up word","They test spelling, since children must write each word after reading it aloud"],"answer":0,"explanation":"Pseudo-words cannot be recognised from memory or guessed from meaning, so reading them shows whether a child can apply letter-sound knowledge. They carry no meaning and are not easier than familiar words.","difficulty":"very-hard","source":"KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-1958","question":"A pre-primary teacher stocks the play corner, set up as a clinic, with appointment cards, a notepad for ‘prescriptions’, a calendar and a sign saying ‘Doctor is in’. The main purpose is to:","options":["teach children the names of medicines and diseases before they reach Class 1","keep children busy with paper while she works with a small reading group","let children use reading and writing for real purposes within their play","test which children can already write words correctly without any help"],"answer":2,"explanation":"Literacy props in dramatic play let children use print as people really do, pretending to write prescriptions and read signs, which builds an understanding of what literacy is for.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1959","question":"A four-year-old says ‘wabbit’ for ‘rabbit’ and ‘fank you’ for ‘thank you’, while her speech is otherwise clear and fluent. What should the teacher do?","options":["Make her repeat each word correctly several times whenever she says it wrongly","Refer her at once to a speech therapist, since such errors at this age clearly show a speech disorder","Ask her classmates to correct her whenever she uses these words in class","Model the words naturally in talk, without making her repeat them; these sounds often develop later"],"answer":3,"explanation":"Sounds such as /r/ and /th/ are among the last to develop, and such substitutions are common at four. Natural modelling is enough; repeated correction can make children self-conscious, though persistent difficulty later may need referral.","difficulty":"moderate","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1960","question":"Reading a memorised big-book line aloud and pointing to each word, a Class 1 child points to two words while saying ‘ba-by’ and ends up pointing at the wrong word. What does this show?","options":["She has not memorised the line well and should repeat it more often","She is still forming the concept of a written word, matching each spoken syllable to a printed word","She has an eye-movement problem that makes her finger move ahead of her eyes on the page of text","She is careless while pointing and should be asked to read more slowly and quietly"],"answer":1,"explanation":"Matching voice to print depends on knowing that a written word may hold several syllables. Her syllable-by-syllable pointing shows that this concept of word is still forming, an important step before decoding.","difficulty":"very-hard","source":"KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-1961","question":"A five-year-old often writes ‘b’ for ‘d’ and sometimes writes her name in mirror image, but is learning letters well otherwise. What is the most appropriate view?","options":["These are clear signs of dyslexia, and she should be referred for formal testing immediately","Such reversals are common at this age; teach formation and give practice, and watch over time","She should stop writing for a few months until her brain matures enough to stop reversing","Reversals show poor eyesight, and she needs an eye test before any further writing work"],"answer":1,"explanation":"Letter reversals are normal in young writers, since objects stay the same when flipped but letters do not. Clear formation teaching and time usually resolve them; concern arises only if they persist with other difficulties.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1962","question":"A pre-primary teacher often asks children to talk about things not in front of them: ‘What did you do at your nani's house?’ ‘What will we need for tomorrow's picnic?’ Why does such talk especially support later reading?","options":["It builds the language needed to describe things beyond the here and now, as written texts do","It checks whether parents are taking their children to visit relatives and friends on the weekends","It trains children's memory, which is the main skill needed for reading later","It replaces story reading, since children learn more from their own talk"],"answer":0,"explanation":"Decontextualised talk about past, future or absent things uses explicit, connected language much like written text, and children skilled in it tend to comprehend books better.","difficulty":"very-hard","source":"KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-1963","question":"Before reading a story aloud to Class 2, a teacher chooses a few words to teach. Following Beck's tiers of vocabulary, which set should she focus on?","options":["‘the’, ‘is’ and ‘and’, since children will meet these words most often in texts","‘photosynthesis’, ‘isotope’ and ‘mitosis’, since technical words are always the hardest ones","‘enormous’, ‘grumble’ and ‘curious’, useful words found more in books than in talk","Every new word in the story, since all unknown words are equally important"],"answer":2,"explanation":"Tier 2 words are high-utility words of mature language that appear across texts but less in everyday talk, so teaching them gives the most benefit. Tier 1 words are already known, and Tier 3 words are subject-specific.","difficulty":"hard","source":"KVS PRT · CTET Paper 1"},
  {"id":"cdp-pedagogy-subjects-1964","question":"At the end of a Class 2 writing period, one child sits in a special chair and reads out her piece, and classmates say what they liked and ask questions. The main purpose of this ‘author's chair’ is to:","options":["grade the best writer in the class publicly, which motivates the others to try harder","let the teacher correct the child's errors in front of the class for everyone's benefit","fill the last few minutes of the period with an activity that needs no planning","give children a real audience and help them see themselves as writers"],"answer":3,"explanation":"Sharing with listeners who respond and ask questions makes writing purposeful and builds identity as authors; it also models how readers react. It is not a public correction or ranking.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1965","question":"A teacher listens to a Class 2 child read a short text and finds she reads about 92 words correctly out of 100. For guided reading with teacher support, this text is best described as being at her:","options":["independent level, so she should read it alone at home","frustration level, so it should be put away at once","listening level, so it should only be read aloud to her","instructional level, suitable for reading with support"],"answer":3,"explanation":"Commonly used guides treat about 95% or more accuracy as independent, about 90–95% as instructional, and below about 90% as frustration level. At 92% the text suits teacher-supported reading.","difficulty":"very-hard","source":"KVS PRT · NVS PRT"},
  {"id":"cdp-pedagogy-subjects-1966","question":"Which statement best describes systematic phonics teaching?","options":["Letter sounds are taught only when a child happens to ask about a word while reading","Children are left to discover letter-sound links on their own from wide and varied reading","Letter-sound links are taught explicitly in a planned sequence and applied in reading","Children memorise whole words by shape, and letters are introduced only in Class 3"],"answer":2,"explanation":"Systematic phonics follows a planned sequence of letter-sound relationships taught directly, with practice in blending and reading. Incidental or discovery approaches leave gaps for many children.","difficulty":"very-hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1967","question":"A Class 1 child writes ‘Iwenttothepark’ with no spaces. Which support is most useful?","options":["Have her read it back while pointing, find where words begin, and leave a finger space","Rewrite the sentence correctly for her and ask her to copy it ten times into her notebook","Ignore it, since spacing will appear on its own once she starts Class 3","Mark the sentence wrong so that she learns to take more care next time"],"answer":0,"explanation":"Spacing depends on the concept of a written word; reading back while pointing helps her find word boundaries, and a finger spacer gives a practical tool. Copying or marking wrong does not build the concept.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1968","question":"While reading a story aloud, a Class 2 teacher pauses and says, ‘Close your eyes. What do you see in the old woman's kitchen? What can you smell?’ This mainly develops:","options":["phonemic awareness, since children listen for the sounds in the words","visualisation, a comprehension strategy of building mental images","fluency, since children practise reading the text more quickly","spelling, since children picture how each word is written"],"answer":1,"explanation":"Asking children to form mental images from the text is the visualising strategy, which helps them engage with and remember what they hear or read. It is not about sounds, speed or spelling.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1969","question":"A Class 2 child reads ‘city’ as ‘kitty’. What is the best teaching response?","options":["Tell her she guessed and ask her to look carefully at every letter","Ask her to learn ‘city’ as a sight word, since it breaks all the rules","Show that ‘c’ often says /s/ before e, i or y, and check meaning","Teach her that the letter ‘c’ always makes the sound /k/ in English"],"answer":2,"explanation":"She applied the most common sound of ‘c’; the next step is the pattern that ‘c’ is usually soft before e, i and y, together with checking that the word makes sense. ‘c’ does not always say /k/.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1970","question":"A Class 1 child sometimes reads ‘was’ as ‘saw’ and ‘on’ as ‘no’. What is the most useful response?","options":["Encourage her to track left to right with a finger and check whether the sentence makes sense","Refer her for dyslexia testing, since such reversals happen only in children with that difficulty","Remove these words from her reading books until she is older and more careful","Have her copy both words ten times each so that their shapes become fixed"],"answer":0,"explanation":"Such reversals are common in beginners still building left-to-right scanning. Tracking with a finger and checking meaning (‘I saw a dog’ vs ‘I was a dog’) helps her self-correct.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1971","question":"In the SAMR model of technology use, which of these is an example of ‘redefinition’ rather than ‘substitution’?","options":["Students type the same essay on a computer instead of writing it by hand in their notebooks","Students in two schools co-create a survey of local birds online and map their data together","The teacher shares the textbook chapter as a PDF so students can read it on a tablet at home","Students answer the usual worksheet questions in an online form instead of on printed paper"],"answer":1,"explanation":"Redefinition means technology makes possible a task that could not be done before, such as real-time collaboration and shared mapping across schools. Typing, PDFs and online forms simply replace paper (substitution).","difficulty":"very-hard","source":"KVS TGT · NVS TGT · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1972","question":"For a project, Class 8 students find a polished website with striking claims about a health remedy. Which habit best helps them judge its reliability?","options":["Trust it if it looks professional and has many pictures, graphs and colourful charts","Trust it if it appears at the top of the search results, since search engines rank by accuracy","Read the whole site carefully from start to end, since a site explains its own reliability best","Leave the site and check what other trusted sources say about it and its claims"],"answer":3,"explanation":"Lateral reading, checking what independent sources say about a site and its claims, is what skilled fact-checkers do. Appearance, ranking or the site's own description of itself are poor guides.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1973","question":"A Class 9 student wants to use a photograph marked with a Creative Commons ‘CC BY’ licence in her school presentation. What must she do?","options":["Use it and credit the creator, as the licence requires attribution","Ask the website to pay her for using it, since it is free content","Avoid it entirely, since all images found online are always illegal to use","Use it freely without any credit, since Creative Commons means no rights"],"answer":0,"explanation":"CC BY allows reuse, including adaptation, as long as the creator is credited. Creative Commons licences keep some rights, and many online images can be used lawfully when their licence terms are followed.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1974","question":"Many students in a district have no internet at home but have a television with a DTH connection. Which resource best fits this situation?","options":["Live video classes on a paid conferencing platform that needs good bandwidth at home","Daily homework set only through a messaging app on the parents' smartphones","Government educational channels broadcast over DTH, such as Swayam Prabha","Asking students to visit a cyber café daily to download that day's materials"],"answer":2,"explanation":"Swayam Prabha offers free educational channels over DTH, which reach homes without internet. Options needing data, smartphones or cyber cafés exclude the very students the teacher wants to reach.","difficulty":"moderate","source":"KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1975","question":"A Class 8 student shares a dramatic photograph said to show a recent flood in their town. Which step best teaches students how to check whether it really shows this flood?","options":["Read the comments under the post to see whether people who live in the town confirm that it shows the flood","Do a reverse image search to find where and when the photograph first appeared online","Examine the image closely for signs of editing such as blurred edges, odd shadows or mismatched lighting","Check the date and location stored in the file information of the copy that was shared with them"],"answer":1,"explanation":"Most misleading flood photos are genuine images recycled from another time or place, and a reverse image search reveals where they first appeared. Looking for signs of editing is tempting, but an unedited old photo passes that test, and file details are usually stripped or reset when images are forwarded.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1976","question":"A school buys animated e-storybooks for Class 1 with games, sound effects and pop-ups on every page. Teachers find children remember the stories less well than with print books. The most likely reason is that:","options":["the extra features pull attention away from the story and the talk around it","young children's eyes tire quickly on screens, so they stop following midway","the e-books read the words aloud, so children stop attending to the text","children turn print pages more slowly, which gives them time to absorb more"],"answer":0,"explanation":"Games, sound effects and pop-ups unrelated to the story compete for young children's limited attention and cut down adult–child talk about the book. Narration is tempting as a cause, but Class 1 recall depends on following the story, not on decoding print, and read-aloud supports that.","difficulty":"hard","source":"CTET Paper 1 · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1977","question":"Class 5 children, without computers, write exact step-by-step instructions for a partner to draw a shape, then fix the steps when the drawing goes wrong. This activity mainly develops:","options":["typing speed, which children will later need in order to write programs on a computer","drawing skills, since children must draw shapes accurately from instructions","memory, since children must remember long sets of instructions given orally","computational thinking: writing precise algorithms, testing and debugging them"],"answer":3,"explanation":"Unplugged activities build the core ideas of computing, precise sequencing, testing and debugging, without devices. The drawing is only a vehicle for checking whether the algorithm works.","difficulty":"hard","source":"KVS · NVS · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1978","question":"A teacher wants to use a free quiz app that asks students to sign in with their phone numbers and photographs. What should she check first?","options":["Whether the app has the brightest colours and the most game features available","Whether most other teachers in the city are already using the app with their classes","What data the app collects, how it uses it, and whether parents' consent is needed","Whether the app has an option to show students' scores publicly on a leaderboard"],"answer":2,"explanation":"Children's personal data needs protection; teachers should read the privacy terms, collect only what is needed and get consent. Popularity, features or leaderboards say nothing about safety.","difficulty":"hard","source":"KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1979","question":"A teacher's video on the water cycle shows an animation, a voice-over, and the full voice-over text printed on screen at the same time. According to Mayer's multimedia principles, the main problem is:","options":["redundancy: the same words in speech and on screen overload learners and reduce learning","the video uses pictures, which distract from the words and so should be removed from it entirely","the video has a voice-over, which is less effective than reading printed text alone","there is no problem, since giving the same information three ways always helps"],"answer":0,"explanation":"Mayer's redundancy principle: learners do better with graphics and narration than with graphics, narration and identical on-screen text, which competes for visual attention. Pictures with narration are themselves effective.","difficulty":"very-hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1980","question":"Several Class 10 students submit essays generated entirely by an AI chatbot. Which response by the teacher is most sound?","options":["Ban all digital tools at home and set only handwritten homework from now on","Redesign tasks around drafts, personal context and discussion, and teach critical use of AI","Accept the essays, since using available tools is a skill students will need later","Give zero marks to all essays that look very well written, since they are probably made by AI tools"],"answer":1,"explanation":"Process-based tasks with drafts, local or personal content and oral discussion make learning visible, while teaching students that chatbots can be wrong builds responsible use. Bans are unenforceable and guessing from quality is unfair.","difficulty":"very-hard","source":"KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1981","question":"A teacher notices that some quiet Class 8 students who rarely speak in class write thoughtful posts in the class's online discussion forum. The most likely reason is that:","options":["online forums are always better than classroom discussion for every kind of student","quiet students are lazy in class and work hard only when they are at home","the forum lets students copy each other's ideas without being noticed","the forum gives them time to think and write without speaking in front of peers"],"answer":3,"explanation":"Asynchronous discussion allows time to reflect and removes the pressure of speaking aloud, so some students participate more fully. It complements rather than replaces classroom talk.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1982","question":"A Class 7 teacher has each student keep an e-portfolio of drafts, recordings and final work across the year. Its main advantage for assessment is that it:","options":["replaces the need for the teacher to give students any feedback on their work","lets the teacher rank students more precisely at the end of the year","shows growth over time and lets students reflect on their own progress","takes less storage space than paper files kept in the school office"],"answer":2,"explanation":"A portfolio collects evidence over time, showing development and inviting self-reflection, which a single test cannot. Storage or ranking is not its purpose, and it supports rather than replaces feedback.","difficulty":"moderate","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1983","question":"A Class 9 teacher has students move a slider for ‘m’ in y = mx + c on graphing software and describe what happens to the line. The main value of this is that students:","options":["see how changing one parameter changes the graph, and form general ideas from it","no longer need to plot any graphs by hand or to understand coordinates at all","can avoid learning the meaning of slope, since the software shows it","can finish the chapter much faster, since the software does all of the work for them"],"answer":0,"explanation":"Dynamic software lets students vary a parameter and observe its effect instantly, leading them to generalise about slope. It builds understanding of slope rather than replacing it.","difficulty":"hard","source":"KVS TGT · NVS TGT"},
  {"id":"cdp-pedagogy-subjects-1984","question":"A Class 7 student with dyslexia understands science well but reads slowly. In a science test, the teacher lets her use text-to-speech to hear the questions. Is this fair?","options":["No, because it gives her an advantage over the other students in the same test","Yes, because the test measures science, and this removes a barrier unrelated to it","No, because she should learn to overcome her reading difficulty without any special help","Yes, but only if every other student in the class is also allowed to use the tool"],"answer":1,"explanation":"An accommodation is fair when it removes a barrier unrelated to what is assessed; here reading speed is not the construct, science understanding is. It does not lower the standard of the test.","difficulty":"very-hard","source":"KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1985","question":"For a group report written in a shared online document, how can a teacher best judge each member's contribution?","options":["Give the same mark to every member, since group work should always be marked jointly","Ask the group leader alone to report who did the most work and mark on that basis","Mark only the final document's quality, since contributions cannot be known","Use the document's version history along with each student's short reflection"],"answer":3,"explanation":"Version history shows who wrote and revised what, and individual reflections add each student's account; together they support fair individual assessment within group work.","difficulty":"hard","source":"KVS TGT · CTET Paper 2"},
  {"id":"cdp-pedagogy-subjects-1986","question":"After a Class 6 teacher firmly but calmly corrects one student for teasing, she notices several others who were about to tease also stop. Kounin called this:","options":["withitness","overlapping","the ripple effect","smoothness of momentum"],"answer":2,"explanation":"Kounin's ripple effect is the influence of a teacher's response to one student on the behaviour of others who see it. Withitness is awareness of everything happening; overlapping is handling two things at once.","difficulty":"very-hard","source":"KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1987","question":"A Class 5 student carelessly tears a library book. Which response is a logical consequence rather than a punishment?","options":["He repairs the book with tape and helps the librarian mend other books for a period","He loses his recess for a whole week, so that he understands how serious his action was","He is made to stand at the back of the class during the next library period","He writes ‘I will take care of books’ a hundred times in his notebook"],"answer":0,"explanation":"A logical consequence is related to the behaviour and helps put things right, here repairing the damage. Losing recess, standing or writing lines are unrelated punishments that teach little about care for books.","difficulty":"hard","source":"CTET · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1988","question":"A school starts giving stickers for every book read. Children who used to read eagerly now read only short books to collect stickers, and stop reading when the scheme ends. This illustrates:","options":["the halo effect, in which one good trait colours the view of others","the overjustification effect, in which rewards weaken intrinsic interest","the Pygmalion effect, in which teachers' expectations shape students' performance","the recency effect, in which the last items learnt are best remembered"],"answer":1,"explanation":"Rewarding an activity that is already enjoyed can shift the reason for doing it to the reward, so interest drops when rewards stop. Rewards fit better for tasks with little initial interest.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1989","question":"A Class 7 teacher wants a whole-class discussion in which students respond to each other, not only to her. Which seating arrangement suits this best?","options":["Rows facing the board, so that all students can see the teacher clearly","Students seated in separate rows by ability, so similar students sit together","Single desks spaced far apart, as arranged for an examination in the hall","A U-shape or circle, so that students can see and talk to one another"],"answer":3,"explanation":"When students can see each other's faces, they address one another, which supports discussion. Rows direct talk to the teacher, and exam spacing discourages interaction.","difficulty":"moderate","source":"CTET · KVS"},
  {"id":"cdp-pedagogy-subjects-1990","question":"A Class 3 teacher wastes several minutes each time she tries to get the class's attention during group work. Which practice is most likely to help?","options":["Shouting louder each time, so that every group can hear her clearly over all the noise","Stopping group work altogether, since it always makes the class too noisy","Teaching and practising a signal, such as a raised hand, until it is a routine","Punishing the noisiest group each time, so that the others learn from it"],"answer":2,"explanation":"Routines must be taught and rehearsed; an agreed attention signal practised until automatic saves time without raising voices. Abandoning group work or punishing groups does not build the routine.","difficulty":"moderate","source":"CTET · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1991","question":"A Class 4 teacher's homework often needs parents to explain new concepts. First-generation learners regularly return it incomplete. What is the best change?","options":["Set tasks that practise what was learnt in class and that children can do on their own","Give more homework to those particular children, so that they can catch up with the others","Ask parents to attend evening classes so that they can help with homework","Stop checking the homework of those children, since it is not their fault"],"answer":0,"explanation":"Homework should consolidate classroom learning and be within the child's independent reach; tasks that depend on parents' schooling disadvantage first-generation learners. More homework or excusing them does not help.","difficulty":"hard","source":"CTET · KVS PRT · DSSSB PRT"},
  {"id":"cdp-pedagogy-subjects-1992","question":"In a lesson on perimeter, a Class 5 teacher gives three groups tasks of differing complexity: finding perimeters of drawn rectangles, of irregular shapes, and designing a garden with a given perimeter. This is an example of:","options":["ability tracking, since children are permanently placed in fixed groups","tiered tasks: one concept with different levels of challenge","mastery learning, since all children must pass before moving on","peer tutoring, since stronger children teach weaker ones"],"answer":1,"explanation":"Tiered tasks keep the same learning goal (perimeter) while varying complexity so each child is challenged appropriately. Groups can change by task, unlike permanent tracking.","difficulty":"hard","source":"CTET · KVS"},
  {"id":"cdp-pedagogy-subjects-1993","question":"A teacher presents a lesson through a story, a diagram and a demonstration, lets students choose to show their learning by writing, drawing or speaking, and offers choices of topic. This planning follows:","options":["the Herbartian steps, which give one fixed sequence of steps for every lesson taught","programmed instruction, which breaks the content into small frames with quick feedback","the grammar-translation method, adapted for content subjects","Universal Design for Learning: many ways to represent, express and engage"],"answer":3,"explanation":"UDL builds flexibility into planning from the start through multiple means of representation, action and expression, and engagement, so more learners, including those with disabilities, can access the lesson.","difficulty":"very-hard","source":"KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1994","question":"Midway through a lesson, a teacher asks one carefully designed multiple-choice question and checks all students' answers at once on fingers raised, deciding whether to move on or reteach. Such a question is called a:","options":["summative test item, recorded towards the final term grade","rhetorical question, which does not need any reply","hinge question, which decides the lesson's next step","closed recall question, which checks only memory"],"answer":2,"explanation":"A hinge question is placed at a key point of a lesson to quickly check whole-class understanding, with wrong options that reveal misconceptions; the responses decide whether to proceed or reteach.","difficulty":"hard","source":"KVS · NVS"},
  {"id":"cdp-pedagogy-subjects-1995","question":"Research by Ruth Butler compared feedback as grades only, comments only, and grades with comments. Which result is most relevant for teachers?","options":["Comments alone led to more improvement; adding grades reduced attention to comments","Grades alone led to the most improvement, since students mainly want to earn higher marks","Grades with comments led to most improvement, since students get both","All three types of feedback led to the same amount of improvement"],"answer":0,"explanation":"Students given comments only improved most; when grades were added, they focused on the grade and largely ignored the comments. This supports descriptive feedback in formative assessment.","difficulty":"very-hard","source":"KVS · NVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1996","question":"In Bloom's mastery learning, what happens after a formative test shows that some students have not mastered a unit?","options":["They are moved to a lower section of the class, so that the rest of the class can move ahead","They receive corrective teaching through different methods and are tested again","They repeat the year, since mastery cannot be gained later on","They get lower grades, and the class moves on to the next unit"],"answer":1,"explanation":"Mastery learning follows formative tests with correctives, alternative ways of teaching the same content, and then a second test, while others do enrichment. It assumes most students can master content given time and suitable help.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-1997","question":"A Class 4 classroom has walls covered with bought charts that never change. Another teacher keeps a ‘working wall’ showing the current topic's key words, examples and children's attempts, updated each week. The main advantage of the working wall is that:","options":["it looks more colourful and impresses visitors to the school","it saves money, since no charts need to be bought for the class","it covers more of the syllabus at once than ordinary charts do","it supports current learning, and children use it as they work"],"answer":3,"explanation":"Displays help when they connect with current learning and are used as a resource; a working wall changes with the topic and includes children's own work. Permanent decorative charts soon become invisible.","difficulty":"moderate","source":"CTET · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1998","question":"At a parent–teacher meeting, which way of sharing a Class 3 child's progress is most useful?","options":["Telling parents only the child's rank in class, since it is easy to understand","Giving parents a list of all the mistakes the child made in the term","Showing samples of the child's work, describing strengths and next steps","Comparing the child with the best student in class, to motivate the family"],"answer":2,"explanation":"Descriptive reporting with work samples shows parents what the child can do and how to help next, in line with continuous assessment. Ranks, mistake lists and comparisons give little guidance.","difficulty":"hard","source":"CTET · KVS PRT"},
  {"id":"cdp-pedagogy-subjects-1999","question":"In anti-bullying work with Class 7, a teacher focuses on the students who watch bullying without joining in. Why does she give bystanders so much attention?","options":["Bystanders often decide whether bullying goes on; their support for the target can stop it","Bystanders are usually the hidden bullies, so they should be punished along with the main bully","Bystanders are not affected by bullying, so they make the most neutral witnesses","Bystanders should be told to keep away, since any action by them makes matters worse"],"answer":0,"explanation":"Bullying often depends on an audience; when peers refuse to laugh and support the target or seek help, it frequently stops. Teaching safe bystander action is a key part of prevention.","difficulty":"hard","source":"CTET · KVS · DSSSB"},
  {"id":"cdp-pedagogy-subjects-2000","question":"A Class 5 child clowns around and interrupts often; he stops briefly when the teacher reacts, then starts again. Following Dreikurs, the most likely goal of this behaviour, and the best response, is:","options":["revenge, so the teacher should avoid him and let his classmates handle the matter themselves","attention, so the teacher should give attention for positive behaviour, not the clowning","power, so the teacher should win a contest of wills by punishing him firmly","inadequacy, so the teacher should excuse him from all tasks he finds difficult"],"answer":1,"explanation":"Behaviour that stops when noticed and then resumes points to attention-seeking; the remedy is to minimise attention to the misbehaviour and give it generously for appropriate behaviour.","difficulty":"very-hard","source":"CTET · KVS · DSSSB"},
];

export default questions;
